COLLDATA("mujamawsat","ur",[[1,"سیدنا ابو موسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری اُمت اُمتِ مرحومہ ہے۔ آخرت میں اس پر کوئی عذاب نہ ہوگا۔ جب قیامت کا دن ہوگا تو مسلمانوں کے ہر آدمی کو دونوں اہل کتاب (یہود و نصاری) میں سے ایک آدمی دیا جائے گا اور کہا جائے گا اے مسلمان! یہ تیرا آگ سے فدیہ ہے۔“ یہ حدیث عبدالملک سے سعید بن یزید ہی روایت کرتے ہیں اور سعید بن یزید سے صرف یحیی بن صالح الوحاظی روایت کرتے ہیں۔ مذکورہ روایت ضعیف ہے، تاہم دوسری صحیح حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری اس امت پر اللہ کی رحمت ہے، آخرت میں اس پر عذاب نہیں۔ اس کا عذاب دنیا میں فتنوں، زلزلوں اور قتل کی صورت میں ہے۔ (ابو داؤد، کتاب الفتن، رقم: ٤٢٧٨) معلوم ہو آخرت میں اس امت کے اہل ایمان پر ابدی عذاب نہیں ہے۔","",{"k":"المعجم الكبير للطبرانی (١٧٧/٢٠)، سنن ابو داؤد (٤٢٧٨)۔"}],[2,"سیدنا ابو موسی رضی اللہ عنہ سے روایت ہے کہ دو آدمی نبی صلی اللہ علیہ وسلم کے پاس ایک اونٹ کا جھگڑا لے کر آئے ان میں سے ہر ایک یہ دعوی کرنا تھا کہ یہ اس کی ملکیت ہے۔ اور ہر ایک کے پاس دو گواہ موجود تھے جو یہ گواہی دے رہے تھے کہ یہ اونٹ اس کا ہے، تو نبی سے تم نے فیصلہ فرمایا: ”سی ان دونوں کے درمیان آدھا آدھا تقسیم کر دیا جائے۔“ از قتاده از ابی مجلز، اس حدیث کو ضحاک ہی روایت کرتے ہیں،اس میں ابو مغیرہ کیلے ہیں۔","",{"k":"المعجم الصغير للطبرانی (٨/١، ٥)، قال الالباني : صحيح۔","f":"مذکورہ روایت سے معلوم ہوا کہ اگر دونوں کے پاس گواہ ہوں تو پھر قاضی دونوں کے درمیان صلح کروا دے اور مال دونوں کے درمیان آدھا آدھا تقسیم کر دے۔"}],[3,"سیدنا جابر ولی الا علینہ نے بیان کیا رسول اللہ صلے علی یتیم نے فرمایا: ”برابری کا لحاظ رکھتے ہوئے خواتین کی شادی کرو، صرف اولیاء (سرپرست) ہی ان کی شادی کریں، اور دس درہم سے کم کوئی مہر نہیں۔“ یہ حدیث عمرو سے حجاج ہی روایت کرتے ہیں، اس کو مبشر بن عبید روایت کرنے میں اکیلے ہیں۔","",{"k":"السنن الكبرى للبيهقي (٦٧/٦)۔"}],[4,"سیدنا عبد الله بن بسر مازنی بیانیہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں ہر آدمی کو قیامت کے دن پہچان لوں گا۔ صحابی نے پوچھا: یا رسول اللہ سے تم! آپ انہیں کیسے پہچانیں گے حالانکہ وہاں مخلوقات بکثرت ہوں گی؟ آپ نے فرمایا: ”بھلا بتاؤ! اگر تم کسی باڑے میں چلے جاؤ،اور وہاں سیاہ کالے گھوڑے ہوں، ان میں ایک گھوڑا سفید پیشانی اور سفید ٹانگوں والا ہو تو تم اس کو ان میں سے پہچان نہ لو گے؟ اس نے کہا: کیوں نہیں؟ آپ نے فرمایا: ” تو میری امت والے اس دن وضو کی وجہ سے سفید پیشانی اور سفید ٹانگوں والے ہوں گے۔“","",{"k":"السنن الكبرى للبيهقي: ١٣٣/٧ موضوع۔","f":"مذکورہ روایت میں وضو کی فضیلت کا اثبات ہے۔ غُر، اغر کی جمع ہے، آغر کے معنی ہیں، ذُوغرّة (چمک یا سفیدی والا) یہ لفظ سفید پیشانی والے جانور ( گھوڑے وغیرہ) کے لیے استعمال ہوتا ہے۔ یہاں مراد وہ نور ہے جس سے روز قیامت اہل ایمان کی پیشانیاں روشن ہوں گی اور وہ اس کی وجہ سے ممتاز ہوں گے۔ محجلون، تحجیل سے ہے، اس کے معنی بھی سفیدی کے ہیں لیکن اس کا استعمال اس سفیدی کے لیے ہوتا ہے جو گھوڑے کی چاروں یا تین ٹانگوں میں ہوتی ہے۔ یہاں اہل ایمان کے ہاتھوں اور پیروں کی وہ روشنی مراد ہے جو وضو کی وجہ سے انہیں حاصل ہوگی۔ مطلب یہ ہے کہ جس طرح وہ گھوڑا ممتاز ہوتا ہے جس کے منہ اور ٹانگوں پر سفیدی ہوتی ہے اس طرح امت محمدیہ کے اہل ایمان کی پیشانیاں اور ہاتھ پاؤں روشن ہوں گے، وہ:٥ میدان حشر میں دوسری امتوں سے ممتاز ہوں گے۔ (السلسلة الصحيحة: ٣٣٥/٦، رقم: ٢٨٣٦)"}],[5,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عبد اللہ بن ام مکتوم یا اللہ کو مدینہ پر دو فعہ اپنا جانشین مقرر کیا۔ وہ نابینا تھے اور لوگوں کو نماز پڑھاتے تھے۔“ یہ حدیث قتادہ سے صرف عفیر ہی روایت کرتے ہیں، ابو مغیرہ اسے اکیلے روایت کرتے ہیں۔","",{"k":"کی سنن ابو داؤد (٢٩٣١)، قال الشيخ الالباني: صحيح، السنن الكبرى للبيهقي (٣/٨٨)۔","f":"مذکورہ روایت سے معلوم ہوا کہ دین اسلام نے نابینوں کو مقام وعزت سے نوازا ہے، اور اسلام نے ان کو باقی انسانوں کے برابر حقوق عطا کیے بلکہ ان کو اہم ذمہ داریاں دینے کا بھی آغاز کیا۔ سیدنا عبد اللہ بن ام مکتوم فلا اليه موذن بھی تھے۔ یہ بھی معلوم ہوا کہ نابینا شخص جماعت کروا سکتا ہے۔"}],[6,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے فرمایا: ”نبی الے علم کی طرف دو دفعہ جن بھیجے گئے، اور جنوں میں سے معزز جن نصیبین میں رہتے تھے۔ قتادہ سے صرف عفیر ہی یہ حدیث روایت کرتے ہیں۔ ابو مغیرہ اسے روایت کرنے میں اکیلے ہیں۔ مذکورہ روایت عفیر بن معدان کے ضعیف ہونے کی وجہ سے کمزور ہے","",{"k":"مجمع الزوائد (٧/١٠٦)، عضير بن معدان ضعیف ہے۔۔"}],[7,"سیدنا انس بن مالک بنی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ”میرے پاس جبریل علینا دحیہ کلبی کی شکل میں آتے ہیں۔ انس کہتے ہیں: ”وحیہ کلبی بڑے جسم والے، خوبصورت اور سفید رنگ والے آدمی تھے۔ یہ حدیث قتادہ سے عفیر ہی روایت کرتے ہیں۔ ابو مغیرہ ا۔ ہی روایت کرتے ہیں۔ مذکورہ روایت سے سیدنا دحیہ کلبی رضی اللہ عنہ کی فضیلت کا اثبات ہوتا ہے۔ یہ بھی معلوم ہوا کہ بسا اوقات جبریل علی نام انسانی شکل وصورت میں بھی آتے تھے۔ سیدنا دحیہ کلبی با این وہ عظیم صحابی ہیں جو نبی معظم ملنے کی کمی کا خط مبارک لے کر ہرقل کے پاس گئے تھے۔ امام طولون شافعی لکھتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم نے اپنے خطوط دے کر جن قاصدوں کو بھیجا وہ خوبصورت اور عقل مند تھے۔ گفتگو کے ماہر اور قائل کرنے کے لحاظ سے دلیل کی قوت سے بھی مالا مال تھے۔:٨ (اعلام السائلين عن كتب سيد المرسلين)","",{"k":"مجمع الزوائد (٣٧٨/٩)۔"}],[8,"سیدنا انس بن مالک نبی الیہ سے مروی ہے کہ نبی ملنے سی ایم نے فرمایا: ”جب مجھے معراج پر لے جایا گیا تو میں ایک قوم کے پاس سے گزرا جن کے تانبے کے ناخن تھے جن سے وہ اپنے چہروں اور سینوں کو نوچ رہے تھے۔ میں نے کہا: جبرائیل! یہ کون ہیں؟“ انہوں نے کہا: ” یہ وہ لوگ ہیں جو لوگوں کا گوشت کھاتے، ان کی بے عزتی کرتے اور ان کی عزتوں سے کھیلتے ہیں۔ “ حضرت عبدالرحمن بن جبیر بن نفیر سے صرف صفوان ہی روایت کرتے ہیں، ابو مغیرہ اسے روایت کرنے میں اکیلے ہیں۔ . لوگوں کا گوشت کھانے سے مراد غیبت کرنا ہے جو بہت بڑا گناہ ہے اور اس کی سزا بھی بہت بڑی ہے۔ ارشاد باری تعالیٰ ہے وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا أَيُحِبُّ اَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَاتَّقُوا اللهَ إِنَّ اللهَ تَوَّابٌ رَحِيمٌ ﴾ (سورة الحجرات:١٢) تم ایک دوسرے کی غیبت نہ کرو۔ کیا تم میں سے کوئی شخص اس بات کو پسند کرتا ہے کہ وہ اپنے مردہ بھائی کا گوشت کھائے؟ تم اسے ناپسند کرتے ہو، اور اللہ سے ڈرو! یقیناً اللہ تعالیٰ بہت توبہ قبول کرنے والا، نہایت مہربان ہے۔“ اور عزتوں میں واقع ہونے سے مرادلوگوں کے سامنے دوسروں کی برائیاں بیان کر کے ان کی ساکھ اور وقار کو مجروح کرنا ہے","",{"k":"♦، سنن ابی داؤد (٤٨٧٨)، قال الالباني صحیح، شعب الایمان (٢٣١/١٤، ٦٤٤١)۔"}],[9,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: علم حاصل کرنا ہر مسلمان پر فرض ہے۔ اس حدیث کو محمد سے کثیر اور کثیر سے صرف حفص بن سلیمان روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا علم حاصل کرنا فرض ہے۔ اسی لیے تو نبی معظم ملنے کی بکثرت دعا فرمایا کرتے تھے: ﴿ رَبّ زِدْنِي عِلْمًا ( سوره طه: ١١٤) اے اللہ! میرے علم میں اضافہ فرما حصول علم کی اہمیت کا اندازہ اس سے بھی لگایا جا سکتا ہے کہ پہلی وحی ہی تعلیم وتعلم سے متعلق ہے۔ ارشاد باری تعالی ہے: إقرأ باسم رَبَّكَ الَّذِي خَلَقَ ﴾ (العلق: ١) ”اے پیغمبر! آپ پڑھیے اپنے رب کے نام سے جس نے ( ہر چیز کو ) پیدا کیا ہے۔“","",{"k":"سنن ابن ماجه، المقدمة باب فضل العماء، رقم : ٢٢٤ قال الشيخ الالباني، صحیح۔"}],[10,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا: ” رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ میں سے ایک آدمی کی بیمار پرسی کی اسے کوئی تکلیف تھی، میں بھی آپ کے ساتھ تھا۔ آپ نے اس کا ہاتھ پکڑا، پھر اپنا ہاتھ اس کی پیشانی پر رکھا، اور آپ اس عمل کو بیمار کی بیمار پرسی کی تکمیل سمجھتے تھے۔ اور فرمایا: ”اللہ تعالیٰ نے فرمایا: بخار میری آگ ہے، میں اس کو اپنے مومن بندے پر مسلط کرتا ہوں تا کہ اس کا آخرت میں آگ کا حصہ دنیا میں ہی پورا ہو جائے۔ ابو صالح اور یہ اشعری ہیں، ان سے صرف اسماعیل بن عبید اللہ روایت کرتے ہیں، اس حدیث کو روایت کرنے میں عبدالرحمن اکیلے ہیں۔","",{"k":"السنن الكبرى للبيهقي (٣/٣٨٢)۔","f":"مذکورہ روایت سے معلوم ہوا کہ تکلیفوں کی وجہ سے مومن کے گناہ معاف ہو جاتے ہیں۔ یہ بھی معلوم ہوا کہ تکلیف پہنچنا مومن کی شان ہے کیونکہ اس میں اجر و ثواب ہے جو دخول جنت کا ذریعہ ہے۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: جو بھی دکھ، تکلیف گھٹن، رنج اور غم مسلمان بندہ کو پہنچ جائے یہاں تک کہ اگر کانٹا بھی لگ جائے تو اللہ تعالیٰ ان سب تکالیف کے ) بدلہ میں اس کی خطائیں معاف فرما دیتا ہے۔ (ادب المفرد، للبخارى، رقم: ٤٩٢)"}],[11,"سیده ام حبیبہ بنی شفا سے روایت ہے نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے ایک دن میں بارہ رکعت نماز ادا کی اللہ تعالیٰ اس کے لیے جنت میں ایک گھر بنا دیتا ہے۔ چار رکعت ظہر سے قبل، دو رکعت ظہر کے بعد، دوعصر سے پہلے، دو مغرب کے بعد، دو عشا کے بعد اور دو فجر سے پہلے۔ اس حدیث کو از ابن عجلان از ابو اسحاق از اوسط انجلی صرف اسماعیل بن عیاش روایت کرتے ہیں۔ اور اس حدیث کولیث بن سعد از محمد بن عجلان از ابواسحاق از عمر و بن اوس از عنبسہ روایت کرتے ہیں۔ ناشدن مذکورہ روایت سے معلوم ہوا کہ شب و روز میں سنن مؤکدہ کی تعداد بارہ رکعت ہے، بعض روایات میں دس رکعتیں ہیں۔ (دیکھئے، رقم: ٩١٤) ان دس رکعتوں میں دورکعتیں نماز ظہر سے قبل ہیں۔ اہل علم نے ان میں تطبیق یوں دی ہے کہ بعض اوقات آپ صلی اللہ علیہ وسلم ظہر سے پہلے دو رکعتیں اور بعض اوقات چار رکعتیں پڑھ لیا کرتے تھے۔ اس لیے دونوں طرح جائز و درست ہے۔ (فتح الباری: ٣٧٧/٣) دوسری بات یہ بھی ہے کہ ہر نماز کے ساتھ اس سے قبل یا بعد میں نفلی نماز ہے۔ اس کی دو قسمیں ہیں: (١) وہ جس پر رسول اللہ صلی اللہ علیہ وسلم نے ہمیشگی اختیار کی ہے ان کی تعداد دس یا بارہ ہے۔ یہ سنت مؤکدہ یا سنت روا تب کہلاتی ہیں۔ (٢) وہ جس پر نبی سے تم نے پیشگی اختیار نہیں کی۔ انہیں نوافل یا غیر مؤکدہ کہا جاتا ہے۔ تاہم کثرت سے نوافل ادا کرنے سے جنت مل جائے گی، بلکہ جنت میں نبی معظم صلی اللہ علیہ وسلم کا ساتھ نصیب ہو جائے گا۔ جیسا کہ سیدنا ربیعہ بن کعب اسلمی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم ملل علیم نے مجھ سے فرمایا: ” (جو مانگنا چاہتا ہے ) مانگ لے۔ میں نے عرض کیا: ”میں جنت میں آپ کی رفاقت کا طلب گار ہوں۔ “ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کے علاوہ بھی کچھ؟“ میں نے عرض کیا: ”بس یہی مطلوب ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ((فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ)) اپنے معاملے میں کثرت سجود ( یعنی نوافل ) کے ساتھ میری مدد کر “ (صحیح مسلم، کتاب الصلوة، رقم","",{"k":"سنن ترمذی (٤١٥)، قال الشيخ الالباني: صحيح۔"}],[12,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ سے تم نے ہمیں ہمارے دین کے متعلق کسی مسئلہ میں الجھن نہیں چھوڑی۔ آپ مالٹے سلیم نے پینے کی اشیا میں پھونک مارنے سے منع فرمایا۔“ مذکورہ روایت کمزور ہے تاہم صحیح روایت میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے برتن میں سانس","",{"k":"مجمع الزوائد (٥/٧٨)، مبشر بن عبید ضعیف ہے۔۔","f":"لینے یا اس میں پھونک مارنے سے منع فرمایا۔ (سنن ترمذی، ابواب الاشربه، رقم: ١٨٨) معلوم ہوا کھانے پینے میں پھونک مارنا جائز نہیں۔ اگر کھانا یا مشروب زیادہ گرم ہو تو انتظار کرے اور ٹھنڈا کر کے کھائے پیے"}],[13,"سیدنا عبد الرحمن بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم کسی بات پر قسم کھاؤ، پھر تم اس سے بہتر کام دیکھ لو تو اس بہتر کام کو کرو، اور اپنی قسم کا کفارہ دے دو۔“ یہ حدیث وائل بن داؤد سے خالد بن یزید روایت کرتے ہیں، حوطی اسے روایت کرنے میں اکیلے ہیں۔ (١) ایک روایت میں ہے کہ ( پہلے ) اپنی قسم کا کفارہ دو، پھر وہ کام کرو جو بہتر ہے۔ (ابو داؤد، رقم: ٣٢٧٧- ٣٢٧٨) ان احادیث سے معلوم ہوا کہ قسم توڑنے سے پہلے بھی کفارہ ادا کیا جا سکتا ہے اور بعد میں بھی۔ جمہور اسی کے قائل ہیں، جبکہ احناف کا موقف یہ ہے کہ کفارہ بہر صورت قسم توڑنے کے بعد ہی ادا کیا جائے گا۔ (سبل السلام: ٤ / روضة النديه: ٢/ ٣٦١) جمہور کا مؤقف ہی راجح ہے۔ امام بخاری جہاللہ نے اپنی صحیح میں باب قائم کیا ہے کہ ((الكارة قبل الحنث و بعده)) فتم توڑنے سے پہلے اور بعد میں کفارہ ادا کرنا۔“ (٢) قسم توڑنے کا کفارہ کیا ہے؟ ارشاد باری تعالیٰ ہے: فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسْكِيْنَ مِنْ اَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَّمْ يَجِدْ فَصِيَامُ ثَلَثَةِ أَيَّامٍ﴾ (المائدة: ٨٩) اس (یعنی قسم ) کا کفارہ دس محتاجوں کو کھانا کھلانا ہے اوسط درجے کا جو اپنے گھر والوں کوکھلاتے ہو یا ان کو کپڑا پہنانا ہے یا ایک غلام یا لونڈی آزاد کرنا ہے جس کو مقدور نہ ہو تو تین دن کے روزے ہیں۔“ نو یہ روزے مسلسل رکھے جائیں گے۔","",{"k":"صحیح بخاری (٦٦٢٢)۔"}],[14,"سیدنا عبد الرحمن بن سمرہ بنی اللہ بیان کرتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے عبد الرحمن! امارت کا کبھی سوال نہ کرنا، کیونکہ اگر وہ تجھے بن مانگے مل گئی تو اس کے انتظام کرنے میں تیری مدد کی جائے گی۔ اور اگر تو نے وہ مانگ کر لی تو تجھے اس کے حوالے کر دیا جائے گا۔ اور اگر تو کسی چیز کی قسم کھالے، پھر تم اس کے علاوہ کسی دوسری چیز کو اس سے بہتر سمجھو تو بہتر کام کرو، اور اپنی قسم کا کفارہ دے دو۔“ یہ حدیث خالد سے صرف یزید روایت کرتے ہیں، عبد العزیز ا سے روایت کرنے میں اکیلے ہیں۔","",{"k":"صحیح مسلم (١٦٥٢)۔","f":"امارت سے مراد خلافت (حکومت) یا اس کا کوئی بھی منصب ہے۔ اس کی آرزو اور اس کے لیے کوشش کرنا نا پسندیدہ ہے۔ اس لیے کہ یہ بہت بڑی ذمہ داری ہے جس سے عہدہ برآ ہونا نہایت مشکل امر ہے۔ البتہ جس کو بغیر مانگے یہ منصب مل جائے وہ اسے قبول کر لے کیونکہ بن مانگے یہ اسی کو ملے گا جس میں اس کی خاص استعداد و صلاحیت ہو گی۔ علاوہ ازیں اللہ تعالیٰ کی طرف سے بھی اس کی مدد ہو گی جبکہ خود خواہش کر کے حاصل کرنے والا اللہ کی طرف سے خیر کی توفیق سے محروم رہے گا۔ چنانچہ آج اس حقیقت کا عام مشاہدہ کیا جا سکتا ہے۔"}],[15,"سیدنا عبد الرحمن بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح ایک اور حدیث ذکر فرمائی۔“ یہ حدیث عرفطہ سے صرف ولید بن عباد روایت کرتے ہیں اور ولید سے صرف اسماعیل بن عیاش روایت کرتے ہیں، عبدالوہاب بن ضحاک اسے روایت کرنے میں اکیلے ہیں۔ ١٦","",{"k":"انظر (١٤)۔"}],[16,"سیدنا عبداللہ ابن عمر بنایا جا سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم رکوع کی تکبیر کے وقت اپنے دونوں ہاتھ اٹھاتے تھے اور اس وقت بھی جب آپ سجدہ کرتے ہوئے نیچے جھکتے تھے۔“ یہ حدیث ارطاۃ سے جراح ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني: ١١ / ١٤٣ بخاری (٧٣٥)۔"}],[17,"سیدہ ام عصمہ عوصیه ولی اش با بیان کرتی ہیں کہ رسول اللہ سے تم نے فرمایا: ”جو مسلمان کوئی گناہ کرے تو جس فرشتے کے ذمہ اس کے گناہوں کو شمار کرنا لگایا گیا ہے وہ تین گھڑیاں ٹھہرتا ہے۔ اگر تو ان تین گھڑیوں میں سے کسی وقت بھی وہ اپنے اس گناہ سے معافی مانگ لے تو وہ گناہ قیامت کے روز اس پر پیش نہیں کیا جائے گا۔“ یہ حدیث ام عصمہ سے اس سند کے علاوہ نہیں روایت کی گئی، ابو مغیرہ اس کو روایت کرنے میں اکیلے ہیں۔","",{"k":"مجمع الزوائد (٢٠٨/١٠)، اس میں سعید بن سنان متروک ہے۔۔"}],[18,"سیدنا عبداللہ ابن عمر ضیا اللہ نبی سے علی کی طرف منسوب کرتے ہیں کہ آپ مریم نے فرمایا: جو شخص تم میں سے جمعہ کو آئے تو وہ غسل کرے۔“ یہ حدیث مکحول سے ابو وہب ہی روایت کرتے ہیں، ابن ابی وہب سے صرف سوید روایت کرتے ہیں، حوطی اس کی روایت کرنے میں اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ جمعہ والے دن غسل کرنا مسنون ہے۔","",{"k":"صحیح بخاری (٨٧٧)۔","f":"غسل جمعہ کی مشروعیت پر تو تمام اہل علم کا اتفاق ہے۔ البتہ اس کے حکم میں اختلاف ہے کہ یہ واجب ہے یا مستحب۔ جن حضرات نے غسل جمعہ کو واجب قرار دیا ہے انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے فرمان ((غسل الجمعة واجب على كل مسلم)) (صحیح بخاری، رقم: ٨٧٩، صحیح مسلم، رقم: ٨٤٦) اور اسی طرح سیدنا عمر و بن سلیم انصاری یا اللہ کا بیان ہے کہ میں گواہی دیتا ہوں کہ (جمعہ کا) غسل واجب ہے۔ (صحيح بخاري كتاب الجمعة، رقم: ٨٨٠) سے استدلال کیا ہے اور یہ موقف حافظ ابن حجر عسقلانی ہمالہ۔ (فتح الباری: ١٣/٣)، ابن حزم بالله (المحلى بالا اثار: ١/ ٢٥٥) امام ابن قیم اللہ، (زاد المعاد: ١/ ٣٦٥) اور شیخ ابن عثیمین اللہ۔ (فتاوی منار الاسلام:١/ ٩٧) وغیرہ کا ہے۔ جبکہ بعض اہل علم کا کہنا ہے غسل جمعہ سنت مؤکدہ ہے فرض نہیں۔ کیوں کہ غسل جمعہ فرض کرنے کا ایک خاص سبب تھا اور وہ یہ کہ صحابہ تنگی حالات کے باعث موسم گرما میں بھی اُونی لباس پہنے ہوتے تھے جس وجہ سے مسجد میں اُن کے پسینے کی بدبو پھیل جاتی، تو آپ صلی اللہ علیہ وسلم نے انہیں فرمایا: \"اگر تم اس دن غسل کر لیا کرو تو وہ بہتر ہے۔“ (صحیح بخاری، رقم: - صحیح مسلم، رقم: ٨٤٧) معلوم ہوا کہ غسل جمعہ کی فرضیت ایک خاص سبب کی بنا پر تھی، اور جب وہ سبب زائل ہو گیا تو فرضیت کا حکم بھی ختم ہو گیا۔ جمہور علماء امام احمد، شافعی، مالک، ابوحنیفہ رحمہم اللہ اسی کے قائل ہیں۔ (فتح القدير: ٤٤/١) اسی طرح شیخ الاسلام ابن تیمیہ، امام شوکانی، نواب صدیق حسن خاں، مولا نا عبد الرحمن مبارکپوری بینہ وغیرہ اسی موقف کے حامل ہیں۔ (السبل الجرار: ١١٧/١، تحفة الاحوذى: ٢٤/٣) راجح موقف دوسرا معلوم ہوتا ہے۔ (واللہ اعلم بالصواب)"}],[19,"سیدنا زر بن حبیش رضی اللہ عنہ سے روایت ہے کہ میں صفوان بن عسال مرادی کے پاس صبح صبح گیا تو انہوں نے پوچھا: اے زر! اتنے سویرے کیوں آئے ہو؟ میں نے کہا: میں علم حاصل کرنے کے لیے حاضر ہوا ہوں۔ انہوں نے کہا: صرف عالم ہونے اور متعلم ہونے کی صورت میں صبح کرو، اور اس سے تجاوز نہ کرو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو آدمی علم تلاش کرتا ہے تو فرشتے اس کے اس عمل کو پسند کرنے کی وجہ سے اپنے پر اس کے لیے بچھا دیتے ہیں۔ “ ( رضی اللہ عنہ کہتے ہیں: پھر میں نے آپ سے موزوں پر مسح کرنے کے متعلق سوال کیا، اور کہا کہ میرے دل میں اس سے کچھ کھٹکا) ہے۔ انہوں نے فرمایا: ہم نبی ما علیم کے ساتھ سفر کرتے تو آپ ہمیں حکم فرماتے تھے کہ ہم تین دن اور تین راتیں جنابت کے بغیر اپنے موزے نہ اتاریں بلکہ پیشاب، پاخانے اور نیند سے (ان پر مسح کر لیں)۔ اور مقیم کے لیے ایک رات دن اجازت ہے۔“ حفص بن سلیمان سے اسے علی بن عیاش ہی روایت کرتے ہیں۔ مذکورہ حدیث میں علم حاصل کرنے کی فضیلت کا بیان ہے کہ اللہ کے فرشتے طالب علم کے پاؤں کے نیچے اپنے نورانی پر رکھ دیتے ہیں۔ ایک حدیث میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے میری طرف وحی کی ہے کہ جو شخص علم حاصل کرنے کے لیے کسی راستے پر چلے تو میں اس کے لیے جنت کا راستہ آسان کر دوں گا۔ (شعب الایمان، رقم: ٥٧٥١)","",{"k":"المعجم الكبير للطبراني (٦٠/٨)۔"}],[20,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”شادی کرنا دو طرح کا ہے: ایک تو پاک دامنی کی غرض سے ہے، اور دوسرا شادی کرنا نکاح کی غرض سے ہوتا ہے۔ یہ حدیث زہری سے صرف مبشر بن عبید ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبرانی (٩٦/١٩)، السلسة الضعيفه (٢٩٦/٢، ٧٩٧)۔"}],[21,"سیدنا عروہ بن زبیر رضی اللہ عنہ سے روایت ہے وہ سیدنا عبداللہ ابن عباس رضی اللہ عنہما کے پاس آئے اور انہیں کہا: ”اے ابن عباس! لمبا عرصہ تو نے لوگوں کو گمراہ کیا ہے“ انہوں نے کہا: اے عریہ! یہ کس طرح ہوا؟ انہوں نے کہا: جب کوئی شخص حج یا عمرے کا احرام باندھ کر نکلے اور وہ طواف کر کے فارغ ہو","",{"k":"مجمع الزوائد: ٢٣٤/٣ وسنده حسن۔","f":"جائے تو تم کہتے ہو کہ وہ حلال ہو گیا۔ (احرام کی پابندیاں ختم ہو گئیں) سیدنا ابو بکر اور سیدنا عمر بنایا تو اس سے منع کرتے تھے۔ سیدنا عبداللہ ابن عباس ولی یہ تھا کہنے لگے: عروہ! تجھ پر افسوس! کیا وہ دونوں زیادہ معتبر ہیں یا وہ جو کتاب اللہ میں ہے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ اور اپنی امت میں اس کو مسنون کیا ہے؟ عروہ کہنے لگے وہ دونوں کتاب اللہ کو اور جو رسول اللہ صلی اللہ علیہ وسلم نے مسنون کیا اس کو ہم دونوں سے اچھی طرح جانتے تھے۔ ابن ملیکہ کہتے ہیں: عروہ،سیدنا عبداللہ ابن عباس نیا پر غالب آ گئے۔ یہ حدیث ابن خلیل کے نزدیک ساقط ہے۔ نا جمہور علماء کا موقف یہ ہے کہ مکہ میں حج و عمرہ کی غرض سے آنے والے کے لیے طواف کعبہ کے بعد دوگانہ طواف اور صفا و مروہ کی سعی بھی ضروری ہے جب کہ ابن عباس بنی الجھا کا موقف یہ تھا کہ طواف کے بعد احرام کھول لینا جائز ہے۔ امام بخاری را یتیمیہ نے بھی ابن عباس ریلی لا کے اس موقف سے اختلاف کیا ہے (دیکھیے، صحیح بخاری، کتاب الحج، باب من طاف بالبيت اذا قدم۔۔)"}],[22,"\" سیدنا عبداللہ ابن عم رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص جمعہ کے لیے آئے تو وہ غسل کرے۔ یہ حدیث ابی عذبہ سے صرف جراح ہی روایت کرتے ہیں، ان سے روایت کرنے میں حوطی اکیلے ہیں۔","",{"k":"سنن ترمذی (٤٩٢)، قال الالبانی، صحیح . وسنن ابن ماجة (١٠٨٨)۔"}],[23,"\"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو عورت اپنے خاوند کی اجازت کے بغیر (نفلی) روزہ رکھے، پھر اس کا خاوند اس سے کسی چیز کا ارادہ کرے، اور وہ عورت اس پر رکاوٹ ڈالے تو اس پر تین کبیرہ گناہ لکھے جاتے ہیں۔“ اوزاعی سے اس حدیث کو صرف بقیہ ہی روایت کرتے ہیں، حوطی ان سے روایت کرنے میں اکیلے ہیں۔ مذکورہ روایت کمزور ہے۔ تاہم اگر عورت نفلی روزہ رکھنا چاہے تو اپنے خاوند سے اجازت لے۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: عورت کے لیے حلال نہیں کہ وہ (نفلی) روزہ رکھے جبکہ اس کا خاوند ( گھر میں ) موجود ہوالا کہ وہ اس کی اجازت دے دے۔ (صحیح بخاری، کتاب النکاح، رقم: ٥١٩٢، صحیح مسلم، رقم: ١٠٢٦) معلوم ہوانفلی عبادت کے مقابلے میں شوہر کے حقوق کی ادائیگی زیادہ اہم وضروری ہے۔ البتہ جب فرض روزے یا کسی بھی فرض عبادت کا مسئلہ ہو تو پھر اسے ترجیح ہو گی۔ امام نووی رحمہ اللہ نے عورت کے لیے شوہر کی اجازت کے بغیر نفلی روزے رکھنے کو حرام قرار دیا ہے۔ (شرح مسلم للنووی:٢٧١/٤)","",{"k":"السلسة الضعيفه (٥/٤٧٢، ٢٤٧٣)، المعجم الكبير للطبراني (٩٧/١٩)۔"}],[24,"سیدنا ابو ہریرہ ضیا اللہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”تین دعائیں ضرور قبول ہوتی ہیں ان میں کوئی شک نہیں: (١) مظلوم کی دعا (٢) والد کی اپنی اولاد کے متعلق بد دعا (٣) اور مسافر کی دعا۔“ یہ حدیث یحیی بن ابی کثیر سے ابی سلمہ اور ان سے صرف اوزاعی ہی روایت کرتے ہیں، ابو مغیرہ ان سے روایت کرنے میں اکیلے ہیں، اور لوگوں کی روایت از یحی بن ابی کثیر از ابو جعفر ہے۔ مذکورہ روایت میں ان لوگوں کا تذکرہ ہے جن کی دعا ان کے اپنے حالات کے اعتبار سے زیادہ لائق قبول ہوتی ہے۔ ان میں (١) مظلوم کا ذکر ہے جس پر کسی طرح کا ظلم کیا جائے اس کو مظلوم کہتے ہیں اور جو شخص ظلم کرے اس کو ظالم کہتے ہیں۔ مظلوم ان لوگوں میں سے ہے جن کی دعا ضرور قبول ہوتی ہے۔ (٢) اسی طرح والد کی بددعا، بعض روایات میں والدین کا تذکرہ ہے۔ بہر حال والدین کی دعا بھی اولاد کے حق میں تیزی کے ساتھ اثر کرتی ہے۔ اولاد کو چاہیے کہ ماں باپ کی خدمت کرتی رہے، اور دعا لیتی رہے،اور کوئی ایسی حرکت نہ کرے جس سے ان کا دل دکھے اور ان میں سے کوئی دل سے یا زبان سے بد دعا کر بیٹھے۔ کیونکہ جس طرح ان کی دعا قبول ہوتی ہے اسی طرح ان کے دکھے دل کی بددعا بھی لگ جاتی ہے۔ (٣) مسافر کو بھی نبی معظم صلی اللہ علیہ وسلم نے ان لوگوں میں شامل فرمایا ہے جن کی دعا قبول ہوتی ہے۔ اور وجہ اس کی یہ ہے کہ مسافر گھر بار سے دور ہوتا ہے، آرام نہ ملنے کی وجہ سے مجبور اور پریشان ہوتا ہے۔ جب اپنی مجبوری اور حاجت مندی کی وجہ سے دعا کرتا ہے تو اس کی دعا اخلاص بھری ہوتی ہے، اور صدق دل سے نکلنے کی وجہ سے قبول ہوتی ہے۔","",{"k":"سنن ترمذی (١٩٠٥)، قال الالبانی حسن۔"}],[25,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: خبر معائنے کے برابر نہیں ہو سکتی۔ جو کچھ موسی علی سلام کی قوم نے ان کے (کوہ طور پر ) جانے کے بعد کیا۔ اللہ تعالیٰ نے انہیں بتایا تو انہوں نے تختیاں نہیں پھینکیں،مگر جب وہ اپنی آنکھوں سے دیکھا تو تختیاں نیچے پھینک دیں۔ مذکورہ روایت سے معلوم ہوا کہ ایک چیز کو آدمی دیکھتا ہے تو اس کا یقین مزید بڑھ جاتا ہے۔ اس کا ہرگز یہ مطلب نہیں کہ (استغفر اللہ ) سیدنا موسیٰ علی نام کو اللہ تعالیٰ پر یقین نہیں تھا۔ جیسا کہ سیدنا ابراہیم علینا نے سوال کیا تھا کہ اے میرے پروردگار! مجھے دکھا تو مر دوں کو کس طرح زندہ کرے گا؟ اللہ ذوالجلال نے فرمایا: کیا تمہارا ایمان نہیں؟ جواب دیا: ایمان تو ہے وَلكِن لِيَطْمَئِنَّ قَلْبِي ﴾ (البقره:٢٢٠) لیکن میرے دل کی تسکین ہو جائے۔ مطلب یہ ہے کہ یقین تو پہلے بھی ہے لیکن مشاہدے کے بعد میرے یقین اور علم میں مزید پختگی اور اضافہ ہوگا۔ ٢٦","",{"k":"مسند احمد (٢٧١/١، ٢٤٤٧)، قال الشيخ شعيب الأرناؤط، فائدة۔"}],[26,"سیدنا عبداللہ ابن عمر ضای اینجا بیان کرتے ہیں کہ رسول اللہ لیے علیم نے فرمایا: ”جب تم میں سے کوئی شخص جمعہ کو آئے تو وہ غسل کرے۔“ یہ حدیث اوزاعی سے ابو مغیرہ ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٨٧٧)۔"}],[27,"\"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا صفیہ علی یا کو ایک ہی کہ حیض ( حمل سے ) بری قرار دیا۔ یہ حدیث زہری سے حجاج بن ارطاۃ ہی روایت کرتے ہیں، ان سے روایت کرنے میں اسماعیل بن عیاش اکیلے ہیں۔","",{"k":"کر سنن الكبرى للبيهقي (٧/٤٤٩)۔","f":"آئے وہ حاملہ نہیں ہوتی۔ مذکورہ روایت کمزور ہے۔ تاہم اکثر یہ ہے کہ حاملہ عورت کو حیض نہیں آتا، اور جس کو حیض"}],[28,"سیدنا انس بن مالک رضی یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قیلولہ کیا کرو (دوپہر کو سویا کرو) کیونکہ شیطان قیلولہ نہیں کرتا۔“ یہ حدیث ابو خالد الدالانی سے صرف کثیر ہی روایت کرتے ہیں اور کثیر سے صرف معاویہ بن بیچی روایت کرتے ہیں، ان سے روایت کرنے میں علی بن عیاش اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ قیلولہ کرنا چاہیے۔ قیلولہ کا مطلب دو پہر کے وقت کچھ دیر آرام کرنا ہے۔ یہ مسنون ہے۔ نبی معظم تعلیم اور صحابہ کرام رضوان اللہ علیہم اجمعین قیلولہ کیا کرتے تھے جیسا کہ سیدنا سہل بن سعد رضی اللہ عنہ فرماتے ہیں: ہم قیلولہ اور دو پہر کا کھانا جمعہ کے بعد کرتے تھے۔ (صحیح بخاری، کتاب الجمعة، رقم: ٩٣٩) لہذا بہتر یہ ہے کہ ظہر کی نماز پڑھ کر یا نماز جمعہ ادا کر کے قیلولہ کیا جائے۔ قیلولہ کے بہت زیادہ","",{"k":"مجمع الزوائد (١١٣/٨)، السلسلة الصحيحه (٣٩١/٢، ١٦٤٧)۔","f":"ہیں یہی وجہ ہے کہ دور حاضر میں بعض غیر مسلم ممالک میں اس پر پابندی کروائی جاتی ہے۔"}],[29,"سیدنا عبداللہ ابن عمر بنی یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص تم سے کوئی نیکی کرے تو اس کا بدلہ اس کو دیا کرو۔ اگر تم اس کا بدلہ دینے کی طاقت نہ رکھو تو اس کے لیے خوب دعا کرو۔ یہاں تک کہ اسے علم ہو جائے کہ تم نے اس کا شکریہ ادا کر دیا ہے۔ کیونکہ اللہ تعالیٰ قدر دان اور شکر کرنے والوں کو پسند فرماتا ہے۔“ یہ حدیث نافع سے عرفطہ ہی روایت کرتے ہیں، اسماعیل بن عیاش، ولید بن عباد سے روایت کرنے میں اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (١١/١٤٤)۔","f":"ایک حدیث میں ہے، نبی معظم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ”جس کے ساتھ کوئی احسان کیا جائے اسے چاہیے کہ اس کا بدلہ دے۔ اگر بدلہ دینے کے لیے اس کے پاس کوئی چیز نہ ہو تو پھر اس احسان کرنے والے کے بارے میں اچھے کلمات کہے، کیونکہ جس نے اچھے کلمات کہہ دیئے تو اس نے اس کا شکر یہ ادا کیا۔ اگر اس نے اس کے احسان کو چھپا دیا تو اس نے اس کی ناشکری کی۔ “ (بخاری ادب المفرد:، رقم: ٢١٥) ان دونوں حدیثوں سے یہ ثابت ہوا کہ اگر بدلہ دینے کے لیے کچھ نہ پاؤ تو اس کی تعریف کرو اور لوگوں کے سامنے ظاہر کرو کہ اس نے ہمارے ساتھ اچھا سلوک کیا۔ اس کے لیے دعا بھی کرنی چاہیے جب آپ کے پاس دینے کو کچھ نہیں ہے تو اللہ تعالیٰ ہی سے عرض معروض کرو کہ وہ اپنے پاس سے اس کو عطا فرما دے۔:٣٠ یہ بھی معلوم ہوا کہ اگر کوئی احسان اور نیکی کرے تو اس شخص کے لیے دعا گو اور شکر گزار ہونا چاہیے۔"}],[30,"سيدنا سائب بن یزید سے روایت ہے کہ سفیان بن ابی زہیر رضی اللہ عنہ نے اسے بتایا کہ اس نے رسول اللہ نے تم کو یہ فرماتے ہوئے سنا جس نے کوئی کتا رکھا تو اس کے عمل سے روزانہ ایک قیراط کمی ہوتی رہتی ہے۔ یہ حدیث یحیی بن ابی کثیر سے معاویہ بن سلام ہی روایت کرتے ہیں۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے مویشیوں یا زراعت کی حفاظت کے لیے یا شکاری کتے کے علاوہ ( شوقیہ ) کوئی کتا رکھا تو اس کے ثواب سے ہر روز ایک قیراط کم ہوتا رہتا ہے۔ (صحیح بخاری، رقم: ٣٣٢٧،٢٣٢٢۔ صحیح مسلم، رقم: ١٥٧٥) معلوم ہوا کہ تین مقاصد کے لیے کتا رکھا جا سکتا ہے۔ (١) مال مویشیوں کی دیکھ بھال (٢) زراعت کی حفاظت (٣) اور شکار کے لیے۔ ان کے علاوہ محض شوقیہ لڑائی کے لیے رکھنا جائز نہیں ہے۔ جو ایسا کرے گا اس کے اجر سے روزانہ ایک قیراط ثواب کم ہوتا رہے گا۔ بعض روایات میں یہ وضاحت ہے کہ ایک قیراط احد پہاڑ کے برابر ہے۔ (صحیح بخاری: کتاب الجنائز، رقم: ٣٣٢٥)","",{"k":"صحیح بخاری (٢٣٢٢)۔"}],[31,"سیدنا عبداللہ بن عمر نا اہوجا سے روایت ہے کہ نبی ٹیم نے فرمایا: ”مسجدوں کو گزرگاہ نہ بناؤ ان کو صرف نماز یا ذکر کرنے کے لیے ہی رہنے دو۔“ یہ حدیث سالم سے ابوقبیل المعافری ہی روایت کرتے ہیں، ابو قبیل کا نام حیی بن ھانی ہے اور ابوقبیل روایت کرنے میں بیٹی بن صالح اکیلے ہیں۔ نان مذکورہ روایت سے معلوم ہوا کہ مساجد کو گزرگاہ نہ بنایا جائے کیونکہ اگر راستہ ہو گا تو ایک","",{"k":"معجم الكبير للطبرانی (٤٥٣/١٠، ١٣٠٤)، السلسلة الصحيحه (٥/٧٥، ١٠٠١)۔","f":"تو مسجد کا احترام نہیں رہے گا اور پھر نمازیوں کی نماز میں خلل بھی واقع گا۔ حدیث کے آخر میں فرمایا کہ صرف نماز یا ذکر کے لیے رہنے دو۔ کیونکہ مساجد کی تعمیر کا بنیادی مقصد بھی یہی ہے۔ ارشاد باری تعالیٰ ہے: ﴿وَانَّ الْمَسَاجِدَ لِلّهِ فَلَا تَدْعُوا مَعَ اللَّهِ اَحَدًا ﴾ (سورۃ الجن:١٨) اور یہ کہ بلاشبہ مساجد اللہ کے لیے ہیں، پس اللہ کے ساتھ کسی کو مت پکارو “ اور نبی صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص مسجد میں کسی آدمی کو گم شدہ چیز کا اعلان کرتے ہوئے سنے تو کہے: اللہ تعالیٰ وہ چیز تمہیں واپس نہ لوٹائے،۔ یقیناً مساجد اس مقصد کے لیے نہیں بنائی گئیں۔ (صحیح مسلم، کتاب المساجد، رقم: سنن ابوداؤد، رقم: ٤٧٣) کیونکہ مساجد تو نماز، ذکر الہی، وعظ ونصیحت اور تلاوت قرآن وغیرہ کے لیے ہیں۔"}],[32,"سيدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے مسلمانوں کے راستے سے انہیں تکلیف دینے والی چیز ہٹا دی اللہ تعالیٰ اس کے بدلے اس کے لیے ایک نیکی لکھ دیتا ہے اور جس کے لیے اللہ تعالیٰ اپنے ہاں ایک نیکی لکھ دے اس کو اس کے بدلے جنت میں داخل فرمائے گا۔“ یہ حدیث","",{"k":"١١٠١ ١١٠١ السلسلة الصحيحه (٥/٣٠٥، ٢٣٠٦)، مجمع الزوائد (٣/١٣٥)۔","f":"ابوالدرداء سے صرف اس سند سے مروی ہے، ابوبکر بن ابی مریم اُن سے روایت کرنے میں اکیلے ہیں۔ ان مذکورہ حدیث سے معلوم ہوا کہ راستہ سے تکلیف دینے والی چیز ہٹا دینے کے عوض اللہ تعالیٰ جنت عطا کریں گے۔ جیسا کہ سیدنا ابو بریدہ اسلمی نبی اللہ صلی اللہ علیہ وسلم نے فرمایا کہ میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے ایسا عمل بتائیے جو مجھے جنت میں داخل کر دے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ((امط الاذى عن طريق:٣٣ الناس)) ”لوگوں کے راستہ سے تکلیف دینے والی چیز کو ہٹا دیا کرو۔ ( بخاری ادب المفرد، رقم: ٢٢٨)"}],[33,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی سے ہم نے فرمایا: \" تکیہ لگا کر نہ کھاؤ۔ اور جمعے کے دن لوگوں کی گردنیں نہ پھلانگو۔“ یہ حدیث ابو الدرداء سے صرف اسی سند سے مروی ہے، ارطاۃ بن منذر اس حدیث کو روایت کرنے میں اکیلے ہیں۔","",{"k":"معجم الكبير للطبراني (٢/٢٥٤)، مجمع الزوائد (٢/١٧٩)۔","f":"بخاری شریف میں ہے کہ نبی معظم مالیے علیم نے فرمایا: ((لا اكُلُ مُتَحِنَّا )) ”میں ٹیک لگا کر نہیں کھاتا۔ (صحیح بخاری، کتاب الاطعمة، رقم: ٥٣٩٨) کسی ایک جانب جھک کر کھانا، اتکاء ہے جیسے دائیں، یا بائیں ہاتھ پر یا دیوار کے ساتھ ٹیک لگا کر وغیرہ۔ مذکورہ حدیث سے یہ بھی معلوم ہوا کہ جمعہ کے لیے جو آئے وہ لوگوں کی گردنیں نہ پھلانگے۔ جیسا کہ سیدنا عبد اللہ بن بسر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی جمعہ کے دن لوگوں کی گردنیں پھلانگتے ہوئے آیا۔ اس وقت نبی ملے عام خطبہ ارشاد فرما رہے تھے۔ آپ ملنے لیے تم نے فرمایا: ”بیٹھ جاؤ! بے شک تم نے بہت تکلیف دی ہے۔“ (صحیح سنن نسائی، رقم: ١٣٣٢٦ سنن ابو داؤد، کتاب الصلاة، رقم: ١١١٨) حنابلہ کے نزدیک دوران خطبہ گردنیں پھلانگنا مکروہ ہے۔ امام نووی اور امام شافعی بیما کے نزدیک یہ عمل حرام ہے۔ ابن قیم اللہ کے نزدیک یہ کبیرہ گناہوں میں سے ہے۔ (نیل الاوطار:٢/ ٥٤٠، تحفة الاحوذی: ٦٢/٣) اس حکم سے امام اور ایسا شخص مستثنیٰ ہے جو اگلی صفوں میں کچھ خالی جگہ دیکھتا ہے اور اسے پُر کرنے کی غرض سے وہاں پہنچتا ہے۔ (فتح الباری: ٣٩٢/٢) .:٣٤ ٣٤"}],[34,"سیدنا ابو درداء رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس صحابہ کرام عینی ایم نے السلام رشتہ داریوں کا ذکر کیا تو ہم نے کہا: جو شخص صلہ رحمی کرتا ہے اس کی عمر دراز کی جاتی ہے۔ تو نبی اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کی عمر میں اضافہ نہیں ہوتا کیونکہ اللہ تعالیٰ نے فرمایا: ﴿فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ ” جب ان کی موت کا وقت آجائے تو ایک گھڑی بھی نہ پیچھے ہو سکے گی اور نہ ہی آگے ہو سکے گی۔ لیکن ایک آدمی کی نیک اولاد ہوتی ہے وہ اس کے بعد اس کے لیے دعا کرتے ہیں تو وہ دعا اس کو پہنچتی ہے۔ اس کی موت کے وقت میں تاخیر کرنے کا یہ مفہوم ہے۔ یہ حدیث ابوالدرداء سے صرف اسی سند سے مروی ہے، سلیمان بن عطاء اس حدیث کو روایت کرنے میں اکیلے ہیں۔ (١) مذکورہ روایت کمزور ہے تاہم صحیح روایت میں ہے، نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص پسند کرتا ہے کہ اس کے لیے اس کے رزق میں فراخی کی جائے اور اس کے نشان قدم ( باقی رکھنے ) میں دیر کی جائے ( اس کی عمر دراز کی جائے ) تو وہ اپنی رشتہ داری کو ملائے۔ (صحیح بخاری، رقم: ٥٩٨٥) سوال یہ پیدا ہوتا ہے کہ ارشاد باری تعالی ہے: ﴿ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةٌ وَلَا يَسْتَقْدِمُونَ ﴾ (الاعراف: ٣٤) ” جب ان کا مقرر وقت آگیا تو ایک گھڑی نہ پیچھے ہوں گے نہ پہلے۔“ تو رشتہ داروں کے ساتھ حسن سلوک سے رزق میں فراخی اور عمر میں اضافہ کس طرح ہو سکتا ہے؟ اس کا جواب یہ ہے کہ اللہ تعالیٰ نے تقدیر میں رزق کی فراخی کے اسباب اور عمر بڑھنے کے اسباب بھی لکھ رکھے ہیں، مثلاً جو شخص محنت کرے گا، ہوش مندی اختیار کرے گا اسے کھلا رزق ملے گا اور جو کاہلی اور ستی اختیار کرے گا وہ تنگ دست ہو جائے گا۔ اسی طرح اچھا کھانا، اچھی آب و ہوا، اچھا ماحول انسان کو صحت مند رکھنے کے اسباب ہیں جن سے عمر بڑھتی ہے، جبکہ خراب آب و ہوا ناقص ماحول بیماری اور پریشانی کا باعث بنتا ہے جس سے عمر گھٹتی ہے۔ (٢) دوسری بات حدیث میں یہ ہے کہ رشتہ داری کو ملانا گھر والوں میں محبت، مال میں ثروت اور نشان قدم میں تاخیر ( عمر میں برکت) کا باعث ہے۔ (صحیح سنن ترمذی، رقم: ١٦١٢) وينسأله في اثرہ اور اس کے نشانِ قدم میں تاخیر کی جائے گی۔ مطلب یا تو حقیقی عمر بڑھ جاتی ہے، یا پھر اس کے اوقات ضائع نہیں ہوتے۔ گویا تھوڑی عمر میں بہت زیادہ نیکیاں کرلیں۔ جیسا کہ اللہ تعالیٰ نے گذشتہ قوموں کی بہت لمبی عمروں کے مقابلے میں اس امت کی عمر بہت تھوڑی رکھی۔::٣٥ (٣) یا کسی ایسے عمل کی توفیق ملتی ہے جس کا مرنے کے بعد بھی اسے ثواب پہنچتا رہتا ہے، مثلاً، صدقہ جاریہ، نیک اولاد، جو اس کے لیے دعا کرے۔","",{"k":"المعجم الكبير للطبراني (٢٠/٢٥٤)، مجمع الزوائد (١٥٣/٨)۔"}],[35,"سیدنا عبداللہ ابن عباس ولی پنجاب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بسم ا الرَّحْمَنِ الرَّحِيم کو بلند آواز سے پڑھا کرتے تھے۔","",{"k":"١] . )) المعجم الكبير للطبراني (١٤٦/٩)۔","f":"مذکورہ روایت کمزور ہے۔ بسم اللہ کی قرآت اونچی یا سری کرنے سے میں فقہا کا اختلاف ہے۔ امام شافعی براللہ کے نزدیک بسم اللہ اونچی آواز سے پڑھنا بہتر ہے۔ جب کہ جمہور، ابو حنفیہ اور احمد میم کے نزدیک بسم اللہ کو سری آواز سے پڑھنا بہتر ہے۔ امام ترندی اللہ فرماتے ہیں: صحابہ و تابعین میں سے اکثر اہل علم کا اسی پر (یعنی جمہور کے مؤقف پر) عمل ہے جن میں خلفاء اربعه، سیدنا ابن مسعود، ابن زبیر، سیدنا عمار رضی اللہ عنہ وغیرہ شامل ہیں۔ (تحفۃ الاحوذی:٦١/٢، المغنی:١٤٩/٢) مخفی و پوشیده کومسنون قرار دینے والوں کے دلائل یہ ہیں:\n(١) سیدنا انس خلیل اللہ فرماتے ہیں کہ میں نے نبی معظم ملنے کی تم سیدنا ابو بکر، سیدنا عمر اور سیدنا عثمان بنی اسم کے ساتھ نماز پڑھی، میں نے ان میں سے کسی کو بھی بسم اللہ الرحمن الرحیم (جہراً) پڑھتے ہوئے نہیں سنا۔ (صحیح مسلم، کتاب الصلاة، رقم: ٦٠٥)\n(٢) سیدنا انس بنی اللہ فرماتے ہیں کہ نبی نے یم اور دیگر صحابہ کرام نی نیم اونچی آواز سے بسم اللہ الرحمن الرحیم نہیں پڑھتے تھے۔ (مسند احمد: ١٧٩/٣، شرح معانی الاثار: ٢٠٣/١) جن کے نزدیک اونچی آواز سے بسم اللہ پڑھنا مسنون ہے ان کے دلائل درج ذیل ہیں: سیدنا انس رضی اللہ عنہ سے نبی معظم صلی اللہ علیہ وسلم کی قرآت کے متعلق سوال کیا گیا تو انہوں نے جواب میں کہا آپ ملے ان کی قرآت مد کے ساتھ تھی۔ پھر آپ رضی اللہ عنہ نے بسم اللہ الرحمن الرحیم پڑھی اور کہا: بسم اللہ (لفظ اللہ کی لام کو ) مد کے ساتھ پڑھتے۔ الرحمان ( میں میم ) کو مد کے ساتھ پڑھتے اور الرحیم ( میں حاء کو ) مد کے ساتھ پڑھتے۔ (صحیح بخاری کتاب فضائل القرآن، رقم: ٥٠٤٦) درست بات یہی ہے کہ دونوں طرح جائز و مباح ہے البتہ مخفی پڑھنے کے متعلق احادیث زیادہ صحیح اور واضح ہیں۔"}],[36,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تبارک و تعالیٰ نے فرمایا: ”میری عزت و جلال کی قسم! میں ظالم سے بدلہ ضرور لوں گا چاہے جلدی لوں یا دیر سے۔ اور میں اس شخص سے بھی ضرور بدلہ لوں گا جو مظلوم کو دیکھے اور اس کی مدد کرنے کی طاقت بھی رکھتا ہو پھر اس کی مدد نہ کرے۔“ یہ دونوں حدیثیں مہدی سے صرف اسی سند سے مروی ہیں، دونوں میں بیٹی بن حمزہ روایت کرنے میں اکیلے ہیں۔ مذکورہ روایت کمزور ہے۔ تاہم مظلوم کی مدد کرنا چاہیے، اور مظلوم کی بد دعا سے بچنا چاہیے اور جو مظلوم، تنگ دست کی مدد کرے گا اللہ تعالیٰ اس کی ضرور مدد کرے گا۔","",{"k":"المعجم الكبير للطبراني (١٤٦/٩)۔"}],[37,"\" سیدنا جابر بنا الیہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جب کسی کا خادم جو اس کی محنت و مشقت کے لیے کافی ہو تو وہ شخص اس کو بھی کھلائے، اگر وہ اس طرح نہ کرے تو وہ اس کو لقمہ ہی دے دے۔“ یہ حدیث اوزاعی سے صرف یحی بن حمزہ روایت کرتے ہیں، ان سے ان کی اولا دروایت کرنے میں اکیلی ہے۔ اند. سیدنا جابر نبی الیہ سے پوچھا گیا کہ ایک آدمی کا خادم اس کو ( یعنی اپنے مالک کو ) مشقت اور گرمی سے بچاتا ہے تو کیا نبی معظم صلی اللہ علیہ وسلم نے حکم فرمایا کہ اسے کھانے پر بلایا جائے؟ سیدنا جابر ضیا اللہ نے فرمایا: ہاں، اسے کھانے پر بلایا جائے) اور اگر تم میں سے کوئی شخص اپنے خادم کے ساتھ کھانا پسند نہ کرے تو اس کے ہاتھ ہی میں ایک لقمہ دے کر کھلا دے۔ (بخاری، ادب المفرد، رقم: ١٩٨) معلوم ہوا جس خادم نے کھانا پکانے میں مشقت اور آگ کی گرمی کو برداشت کیا، اور اپنے مالک کو اس مشقت اور گرمی سے بچایا اس کا یہ حق ہے کہ اس کو بھی کھانے میں شریک کیا جائے۔ اگر ساتھ کھلانے پر طبیعت گوارا نہیں کرتی تو پھر اس کے ہاتھ ہی میں ایک دو لقمے رکھ دو۔","",{"k":"صحيح الجامع الصغير (٢٧١/٢، ٧٧١)۔"}],[38,"على بن عبد اللہ بن عباس روایت کرتے ہیں مجھے میرے باپ نے حدیث بیان کی کہ میرے باپ نے مجھے کسی کام کے لیے رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا۔ میں نے آپ کو صحابہ بنی ایام میں کے ساتھ مسجد میں بیٹھے ہوئے پایا مگر آپ سے کلام کرنے کی جرات نہ کر سکا۔ جب آپ نے مغرب کی نماز پڑھ لی تو ( دوسری) نماز پڑھنے کے لیے اٹھے یہاں تک کہ مؤذن نے عشا کی اذان کہہ دی اور لوگ جلدی جلدی اٹھے۔ آپ نے نماز پڑھی اور پڑھتے رہے یہاں تک مسجد میں جو بھی تھا چلا گیا، اور آپ بھی اپنے گھر کو چلے گئے، اور میں بھی آپ کے پیچھے ہو لیا جب آپ نے میری آہٹ محسوس فرمائی تو کہنے لگے: ”کون ہے؟“ اور میری طرف توجہ فرمائی۔ میں نے کہا: میں ابن عباس ہوں۔ آپ نے فرمایا: ”رسول اللہ صلی اللہ علیہ وسلم کے چچا کا بیٹا؟“ میں نے عرض کیا: جی ہاں رسول اللہ صلی اللہ علیہ وسلم کے چا کا بیٹا۔ آپ نے فرمایا: ”رسول اللہ صلی اللہ علیہ وسلم کے چا کے بیٹے کو آنا مبارک ہو! کس کام سے آئے ہو؟ میں نے عرض کیا: میرے باپ نے مجھے فلاں کام کے لیے بھیجا ہے۔ آپ نے فرمایا: تم اس وقت آئے ہو؟“ میں نے کہا: نہیں۔ آپ نے فرمایا: ”جب کہ تو اب تک واپس نہیں گیا تو اب واپس نہیں جا سکے گا۔“ پھر آپ اپنے گھر گئے، میں بھی آپ کے ساتھ ہی چلا گیا۔ میں نے کہا: آج رات میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کا طریقہ دیکھوں گا، آپ سو گئے یہاں تک کہ میں نے آپ کے خراٹوں کی آواز سن لی۔ پھر جاگے، اور اپنی نظر آسمان کی طرف اٹھائی، اور یہ آیات تلاوت کیں جو سورہ آل عمران میں ہیں: ان فى خَلْقِ السَّمَوَاتِ وَالْأَرْضِ سے پانچ آیتیں پڑھیں یہاں تک ﴿إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ تک پڑھ لیں۔ پھر آپ صلی اللہ علیہ وسلم نے یہ دعا کی: ((اللَّهُمَّ اجْعَلْ فِي سَمْعِي نُوراً وَفِي بَصَرِي نَوْراً وَمِنْ فَوْقِى نُوْراً وَمِنْ تَحْتِى نُوراً وَعَنْ يَمِيْنِى نُورًا وَعَنْ شِمَالِى نُوراً وَاجْعَلْ لِيْ عِنْدَكَ نُوراً)) اے اللہ! میرے کان اور نظر میں نور ڈال دے اور میرے اوپر اور نیچے بھی نور کر دے اور میرے دائیں اور بائیں بھی نور کر دے اور میرے لیے اپنے پاس سے نور کر دے۔ آپ کی ایک جانب پتھر سے بنا ہوا ایک برتن تھا جس پر مسواک تھی۔ آپ نے مسواک کی، پھر وضو کیا اور دو رکعت نماز پڑھی۔ پھر سو گئے حتی کہ میں آپ کے خراٹوں کی آواز سننے لگا۔ پھر آپ بیدار ہوئے تو یہی آیات پڑھیں اور یہی دعا مانگی۔ پھر مسواک کی اور وضو کر کے دو رکعت نماز ادا کی۔ پھر سو گئے یہاں تک کہ میں آپ کے خراٹوں کی آواز سنے لگا۔ پھر آپ بیدار ہوئے تو پہلی آیات پڑھیں، پھر یہ دعا کی پھر مسواک کی وضو کر کے دو رکعت نماز پڑھی۔ پھر سو گئے، یہاں تک کہ میں آپ کے خراٹوں کی آواز سننے لگا۔ پھر بیدار ہوئے تو یہی آیات تلاوت کیں، اور یہی دعا پڑھی۔ پھر مسواک کی، وضو کیا اور نماز ادا کی۔ میں نے یہ معلوم کیا کہ اس میں انہوں نے وتر پڑھے۔ پھر آپ نے فرمایا: ”کیا لڑکا سو گیا ہے؟“ میں نے کہا: نہیں، میں اٹھا، وضو کیا پھر آ کر آپ کی بائیں جانب کھڑا ہو گیا تو آپ نے اپنی دو انگلیوں سے میرے کان کو پکڑ کر گھوما کر اپنی دائیں جانب کر لیا۔ پھر دو رکعت صبح کی (سنتیں ادا کیں، پھر نماز کے لیے تشریف لے گئے۔“","",{"k":"♦، کر المعجم الكبير للطبراني (١٤٥/٩)۔","f":"مذکورہ روایت سند کے لحاظ سے کمزور ہے۔ تاہم شواہد کی بنا پر صحیح ہے۔ سیدنا عبد اللہ بن عباس ظلی پوجا کا یہ واقعہ ان کی کم عمری کا ہے۔ اس میں ان کی نجابت وسعادت کا واضح بیان ہے۔ بالخصوص رسول اللہ صلی اللہ علیہ وسلم کے معمولات جاننے کا شوق اور اس غرض کے لیے شب بیداری کی مشقت اٹھانا۔"}],[39,"\" علقمہ بن قیس بیان کرتے ہیں سیدنا عبداللہ ابن مسود نبی اللہ نے فرمایا: (قیامت کی ) پانچ نشانیاں گزرگئی ہیں اور پانچ باقی ہیں۔ (١) چاند کا پھٹ جانا گزر گیا ہے ہم نے اس کو دیکھا تھا (٢) دھواں بھی گزر گیا ( قحط کے سال) (٣) بڑی پکڑ بھی گزرگئی (غزوہ بدر ) اور (٤) روم ( کا غلبہ ) بھی گزر گیا۔“ مذکورہ حدیث میں جو نشانیاں ذکر کی گئی ہیں یہ تمام کی تمام علامات قیامت کے متعلق ہیں جو گزرچکی ہیں (٢) چاند کا پھٹ جانا۔ جیسا کہ ارشاد باری تعالیٰ ہے: ﴿اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ ﴾ (سورہ القمر: ١) ” قیامت قریب آگئی اور چاند پھٹ گیا۔“ چاند کے دوٹکڑے ہونے کا واقعہ نبی معظم سے یمن کی مکی زندگی میں ہوا تھا۔ یہ قیامت کی ایک نشانی بھی ہے اور نبی معظم صلی اللہ علیہ وسلم کا معجزہ بھی تھا۔ (٢) دھواں کا آنا، جیسا کہ قرآن مجید میں ہے: يَوْمَ تَأْتِي السَّمَاءُ بدُخَانٍ مُّبِينٍ ﴾ (سورۃ الدخان: ١٠) (٣) اللہ کی پکڑ جو بدر میں ہوئی جیسا کہ ارشاد باری تعالیٰ ہے۔ یوم نَبْطِسُ البَطْشَةَ الكُبری اور وہ وبال جو قریش پر بدر کے دن آیا اس کا تذکرہ اس آیت میں ہے: ﴿فَسَوْفَ يَكُونُ لِزَامًا ﴾ (الفرقان: ٧٧) تو اللہ تعالیٰ نے قریش مکہ کو بدر والے دن شکست دی۔ (٤) روم جو ایرانیوں کے ہاتھوں مغلوب ہوئے اور بعد میں اللہ تعالیٰ نے انہیں غلبہ عطا فرمایا۔ جیسا کہ قرآن مجید میں المه غُلِبَتِ الرُّومُ ٥ ﴾ (الروم:١-٢) ٤٠","",{"k":"سنن ترمذی (٣٢٥٤)۔"}],[40,"سیدنا عمر بن خطاب نبی الیہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اعمال کا دارو مدار نیتوں پر ہے، اور ہر شخص کے لیے وہی کچھ ہے جو اس نے نیت کی۔ تو جس کی ہجرت اللہ تعالیٰ اور اس کے رسول کی طرف ہو تو اس کی ہجرت اللہ اور اس کے رسول کی طرف ہو گی۔ اور جس کی ہجرت دنیا حاصل کرنے یا کسی عورت سے نکاح کرنے کے لیے ہے تو اس کی ہجرت اسی طرف ہوگی جس کی طرف اس نے ہجرت کی۔“ یہ حدیث اوزاعی سے صرف بیٹی بن حمزہ اور ابوخلید عقبہ بن حماد اور ولید بن مسلم ہی روایت کرتے ہیں۔ نان مذکورہ روایت سے معلوم ہوا کہ ہر نیک عمل میں اخلاص ضروری ہے، جیسا کہ ارشاد باری تعالیٰ ہے: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلوةَ وَيُؤْتُوا الزَّكُوةَ وَذَلِكَ دِينُ الْقَيِّمَةِ ﴾ (البينه: (٥) ان کو یہی حکم دیا گیا تھا کہ وہ اخلاص کے ساتھ اللہ کی عبادت کریں، یک سو ہو کر۔ نماز پڑھیں، زکوۃ دیں اور یہی دین قیم ہے۔“ مذکورہ روایت کے علاوہ بعض روایات میں اس حدیث کا پس منظر یہ بیان کیا گیا ہے کہ ایک شخص نے ام قیس نامی عورت کو نکاح کا پیغام بھیجا۔ اس نے اس وقت تک نکاح کرنے سے انکار کر دیا جب تک وہ ہجرت نہ کرے۔ چنانچہ اس نے اس کی اس شرط کی وجہ سے ہجرت کر لی اور وہاں جا کر دونوں کا باہم نکاح ہو گیا۔ چنانچہ صحابہ مینی سیستان میں میں اس کا نام ہی مہاجرام قیس مشہور ہو گیا۔ اس حدیث کی بنیاد پر علماء کا اتفاق ہے کہ اعمال میں نیت ضروری ہے، اور ہر عمل کا نیت کے مطابق ہی اجر ملے گا۔ ٤١","",{"k":"رقم: ١ . فائد صحیح بخاری۔"}],[41,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے جمعہ کے دن روزہ رکھنے سے منع فرمایا، مگر پہلے دنوں میں شامل کر کے رکھ سکتا ہے۔“ یہ حدیث نعمان بن بشیر سے صرف یحی بن حمزہ ہی روایت کرتے ہیں۔ ان مذکورہ حدیث سے معلوم ہوا کہ اکیلے جمعہ کے دن کا روزہ رکھنا ممنوع ہے۔ جمہور علماء اسے مکروہ کہتے ہیں، جبکہ بعض نے اس دن کے روزے کو حرام کہا ہے۔ (المجموع: ٧٣٨/٦) جمعہ کے دن روزہ کے ممنوع ہونے کا یہ سبب بھی بیان کیا جاتا ہے کہ جمعہ کے دن کو رسول اللہ صلی اللہ علیہ وسلم نے عید کا دن کہا ہے۔(مسند احمد: ٥٣٢/٢) اور عید کے دن بالاتفاق روزہ حرام ہے اس لیے جمعہ کے دن بھی روزہ درست نہیں۔ تاہم عید اور جمعہ میں اتنا فرق ضرور ہے کہ جمعہ سے پہلے ایک دن یا اس کے بعد ایک دن ملا کر روزہ رکھنا درست ہے، جبکہ عید کا روزہ کسی صورت بھی جائز نہیں ہے۔ (صحیح بخاری، کتاب الصوم،رقم: ١٩٨٥)","",{"k":"السلسلة الصحيحة (٨٦/٣، ١٠١٢)، المعجم الكبير للطبراني (٩٧/١٩)۔"}],[42,"\"سیدنا ابو ثابت بن قیس بن شماس انصاری نیل اللہ بیان کرتے ہیں میں نے کہا: یا رسول اللہ سے ہم اللہ کی قسم! مجھے ڈر ہے کہ میں ہلاک ہو جاؤں گا۔ آپ نے فرمایا: ” کیوں؟“ میں نے کہا: اللہ تعالیٰ نے نہ کیسے ہوئے کام پر تعریف کیے جانے سے منع فرمایا ہے اور میں اپنے آپ کو تعریف کو پسند کرنے والا پاتا ہوں۔ اللہ تعالیٰ نے تکبر سے منع کیا ہے اور میں اپنے آپ کو پاتا ہوں کہ میں جمال اور خوبصورتی کو پسند کرتا ہوں۔ اور اللہ تعالیٰ نے آپ کی آواز سے اپنی آواز میں بلند کرنے سے منع فرمایا اور میں بلند آواز والا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تو راضی نہیں دنیا میں زندہ رہے تو تعریف والا رہے، اور شہادت کی موت میں قتل کیا جائے، اور جنت میں قابل تعریف ہو کر چلا جائے۔ میں نے کہا: کیوں نہیں یا رسول اللہ نے تم راوی کہتے ہیں وہ قابل تعریف زندگی جیتے رہے۔ اور مسیلمہ کذاب سے جنگ میں شہید ہوئے۔“ یہ حدیث اوزاعی سے بیٹی بن حمزہ ہی روایت کرتے ہیں، ان سے روایت کرنے میں ان کی اولا دا کیلی ہے۔","",{"k":"المعجم الكبير للطبرانی (٦٨/٢، ١٢٩٦)، مجمع الزوائد (٩/٣٢٢)۔","f":"مذکورہ روایت کمزور ہے تاہم سیدنا ثابت بن قیس رضی اللہ عنہ کے متعلق نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”اے ثابت تو جنتی ہے۔“ (صحیح مسلم، کتاب الايمان، باب مخافة المؤمن) ٤٣"}],[43,"سیدنا عبداللہ ابن مسعود فضل الله بیان کرتے ہیں کہ جس رات نبی صلی اللہ علیہ وسلم کی طرف جنوں کو بھیجا گیا تھا اس رات میں آپ کے ساتھ تھا۔ ایک جن رسول اللہ صلی اللہ علیہ وسلم کی طرف آگ کا ایک شعلہ لے کر آیا۔ جبریل عیسلام نے کہا: ”اے محمد صلی اللہ علیہ وسلم! کیا میں آپ کو ایسے کلمات نہ سکھا دوں جن کے کہنے سے اس کا یہ شعلہ بجھ جائے گا، اور یہ اپنی ناک کے بل اوندھا گر پڑے گا؟ یوں کہتے: ((أَعُوْذُ بِوَجْهِ اللَّهِ الْكَرِيمِ وَكَلِمَاتِ اللهِ التَّامَّةِ الَّتِي لا يُحَاوِزُ هُنَّ بَر وَلا فَاجِرٌ مِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وَمَا يَعْرُجُ فِيهَا وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ وَمِنْ شَرِّ طَوَارِقِ اللَّيْلِ وَالنَّهَارِ إِلَّا طَارِقٌ يَطْرُقُ بِخَيْرٍ يَا رَحْمنُ)) میں اللہ تعالیٰ کے عزت والے چہرے کی پناہ چاہتا ہوں۔ اور اللہ تعالیٰ کے ان کامل کلمات کی پناہ لیتا ہوں جن سے نیک اور گناہ گار تجاوز نہیں کرسکتا۔ اس چیز کی برائی سے جو آسمان سے اترے، اور جو اس میں اوپر جائے،اور اس چیز کی برائی سے جو اس نے زمین میں پیدا کی، اور جو چیز اس میں سے باہر نکلتی ہے، اور رات اور دن کے وقت آنے والے فتنوں سے مگر جو رات کو خیر کے ساتھ آئے، اے رحمن! یہ حدیث اوزاعی سے صرف یحی بن حمزہ ہی روایت کرتے ہیں، اُن سے روایت کرنے میں اُن کی اولا دا کیلی ہے۔ ناندن . مذکورہ روایت سے معلوم ہوا کہ شیطان (جن ) لوگوں کو ڈرانے کی کوشش کرتے ہیں۔ اگر انسان ان سے ڈر جائے تو مزید جنات حملہ کر دیتے ہیں اور ڈراتے ہیں۔ جیسا کہ ارشاد باری تعالیٰ ہے: وَانَّهُ كَانَ رِجَالٌ مِّنَ الْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ الْجِنِ فَزَادُوهُمْ رَهَقًا ﴾ (الجن: ٦ ) بات یہ ہے کہ چند انسان بعض جنات سے پناہ طلب کیا کرتے تھے جس سے جنات اپنی سرکشی میں اور بڑھ گئے۔ اگر آدمی مذکورہ دعا پڑھے تو اللہ تعالیٰ آدمی کو شیطان کے شر سے بچالیں گے۔","",{"k":"مجمع الزوائد (١٠/١٢٧)۔"}],[44,"سيدنا عمرو بن العاص رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ اسے علم کو فرماتے ہوئے سنا: ”بہت زیادہ باتیں کرنا شیطان کا ایک حصہ ہے۔“ یہ حدیث ثور سے بیٹی بن حمزہ ہی روایت کرتے ہیں۔ ٤٥",""],[45,"سیدنا ابو ہریرہ ضیا یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم کفار سے جنگ کرتے رہو گے یہاں تک تم ایک ایسی قوم سے جنگ کرو گے جن کی چھوٹی چھوٹی آنکھیں ہوں گی اور ان کی ناک چپٹی ہوں گی گویا ان کے چہرے تہ بتہ رکھی ہوئی ڈھالیں ہیں۔ یہ حدیث زہری سے صرف ابو عثمان الا وقص ہی روایت کرتے ہیں، اسے روایت کرنے میں ولیدا کیلے ہیں۔ مذکورہ حدیث میں ترکوں کے ساتھ جنگ کرنے کا بیان ہے، کیونکہ ترکوں کے چہرے پر گوشت، گول، چوڑے، چھوٹی آنکھوں اور چپٹی ناک والے ہوتے ہیں۔ .٤٦","",{"k":"صحیح بخاری (٢٩٢٩)، سنن ابن ماجه (٤٠٩٧)۔"}],[46,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”تم میں سے جو شخص جمعہ کو آئے تو وہ نسل کرے۔ یہ حدیث زہری سے اس سند کے علاوہ مروی نہیں ہے۔","",{"k":"المعجم الكبير للطبراني (١١/١٤٤)۔"}],[47,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دمشق اور اس کے آس پاس کے دروازوں پر اور بیت المقدس اور اس کے آس پاس کے دروازوں پر میری امت کا ایک گروہ ہمیشہ لڑائی کرتا رہے گا۔ ان کو نقصان پہنچانے والے نقصان نہیں پہنچاسکیں گے۔ اور وہ قیامت قائم ہونے تک غالب رہیں گے۔“ عامر الاحول سے صرف ولید بن عباد ہی اسے روایت کرتے ہیں، اسے روایت کرنے میں اسماعیل بن عیاش اکیلے ہیں۔","",{"k":"الضعيفة، رقم: ٥٤١٩ . المعجم الكبير للطبرانی (١٩/٩٨)، مجمع الزوائد (١١/٦٠)، السلسلة الله۔"}],[48,"سیدنا عبداللہ ابن عمر بنی النہا سے روایت ہے رسول اللہ علی علیم نے فرمایا: ” جو شخص جمعہ کی طرف آئے تو وہ غسل کرے۔ نعمان سے صرف بیٹی ہی اسے روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٨٧٧)، ابو داؤد (٤٩٢)۔"}],[49,"سیدنا عبداللہ ابن عباس والی عنہا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جو شخص جمعہ کو آئے تو وہ غسل کرے۔“","",{"k":"صحیح بخاری (٩١٩)۔"}],[50,"سیدنا عبد اللہ ابن عمر نا انا بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ولاء کے بیچنے یا ہبہ کرنے سے منع فرمایا۔ سفیان از عمرو بن دینارا سے بیٹی بن حمزہ ہی روایت کرتے ہیں، اُن سے روایت کرنے میں ان کی اولا دا کیلی ہے، اور لوگ اسے از اسفیان از عبداللہ بن دینار سے روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ ولاء کو فروخت کرنا اور ہبہ کرنا جائز نہیں ہے۔ ولاء کا معنی، نصرت، قرابت، محبت اور ملکیت ہے۔ اصطلاحی تعریف: ولاء ایسا تعلق ہے جس کی وجہ سے مالک اپنے آزاد کردہ غلام کا وارث بنتا ہے بشرطیکہ اس کے اقرباء موجود نہ ہوں۔ (الفرائض:٢٠)","",{"k":"سنن ترمذی، البيوع (١٢٣٦)، قال الالبانی : صحیح۔"}],[51,"سیدہ عائشہ منی نیہا سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگ قیامت کے روز ننگے پاؤں ننگے جسم، بے ختنہ اٹھائے جائیں گے۔ سیدہ عائشہ بیا نیہا نے پوچھا لوگوں کے شرم گاہوں کا کیا ہوگا؟ تو آپ نے فرمایا: ” ہر آدمی کا ایسا حال ہو گا کہ جو اسے دوسروں سے بے پروا بنا دے گا۔“ (اپنے حال میں ایسا فکرمند ہو گا کہ کسی کی فکر نہ ہوگی۔ زہری اور زبیدی کے درمیان کوئی ایسا راوی نہیں ہے، جس نے یہ حدیث زبیدی سے سنی ہو۔ نعمان سے سوائے بیٹی بن حمزہ کے ان کی اولا دان سے روایت کرنے میں اکیلی ہے۔ (١) مذکورہ حدیث میں میدان محشر کی کیفیت کا بیان ہے۔ (٢) سورہ عبس کی آیت ٣٧ کی تفسیر بھی معلوم ہوئی کہ لِكُلِّ امْرِيُّ مِنْهُمْ يَوْمَئِذٍ شَانٌ يُغْنِيهِ اس دن ان میں سے ہر شخص کی ایک ایسی حالت ہوگی جو اسے ( دوسروں سے) بے پروا بنا دے گی۔ یعنی باپ بیٹے سے اور بیٹا باپ سے اسی طرح ہر انسان دوسرے سے بھاگ رہا ہوگا۔","",{"k":"صحیح. سنن نسائی، قال الالبانی۔"}],[52,"سیدنا براء بن عازب رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کو یہ دعا سکھائی کہ وہ اپنے بستر پر جائے تو یہ دعا پڑھے: ((اللَّهُمَّ وَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِى إِلَيْكَ، وَفَوَّضْتُ أَمْرِى إِلَيْكَ، وَأَسْلَمَتْ نَفْسِي إِلَيْكَ، رَهْبَةً وَرَغْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)) ”اے الله! میں نے اپنا چہرہ تیری طرف موڑ دیا، اور اپنی پیٹھ تیری طرف لگا دی، اور اپنا کام تیرے سپرد کر دیا اور اپنی جان تیرے سپرد کر دی تجھ سے ڈرتے ہوئے اور تجھ پر امید رکھتے ہوئے نہیں ہے پناہ اور نجات کی جگہ تیرے سوا، میں تیری کتاب جو تو نے اتاری اور تیرے بھیجے ہوئے رسول پر ایمان لایا۔ اگر وہ اس رات فوت ہو گیا تو اسے معاف کر دیا جائے گا۔ عمرو بن قیس سے اسے صرف ثور بن یزید ہی روایت کرتے ہیں اور ٹور سے صرف بیٹی بن حمزہ روایت کرتے ہیں، اُن سے روایت کرنے میں ان کی اولا دا کیلی ہے۔ مذکورہ دعا رات سوتے وقت پڑھنا مسنون ہے۔ اس دعا میں رات کو سوتے وقت اپنے ایمان و اسلام اور اللہ سے کئے ہوئے عہد کی تجدید ہے۔ ہر مسلمان اس طرح رات کو تجدید عہد کر لیا کرے تو یقیناً دن کی مصروفیتوں میں بھی اسے اللہ اور اس کے احکام یا در ہیں گے۔","",{"k":"المعجم الصغير للطبراني (٦/١، ٣)۔"}],[53,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: روزہ جہنم سے بچنے) کے لیے ڈھال ہے۔ “ اوزاعی سے صرف یحیی بن حمزہ ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (٩٨/١٩)۔","f":"مذکورہ حدیث میں روزے کی فضیلت کا اثبات ہے کہ روزہ انسان کو جہنم سے بچالے گا یہ تب ہو گا جب روزے کی حالت میں مخش گفتگو اور جہالت کا کام نہ کیا جائے۔ جیسا کہ نبی معظم سے ہم نے فرمایا: روزہ ایک ڈھال ہے۔ پس جب تم میں سے کسی کا روزہ ہو تو وہ دل لگی کی باتیں کرے نہ شور و غل کرے۔ اگر کوئی اسے گالی دے یا اس سے لڑائی جھگڑا کرے تو وہ کہہ دے میں تو روزہ دار ہوں۔ (صحیح بخاری، کتاب الصوم، رقم: ١٨٩٤) .٥٤"}],[54,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دعا کی: اے اللہ! مضر پر اپنی پکڑ سخت کر اور ان پر اسی طرح قحط سالی بھیج جس طرح یوسف علینا) کے وقت میں قحط سالی بھیجی تھی۔“ زہری سے اس حدیث کو ابوبکر اور ان سے شعیب ہی روایت کرتے ہیں۔ فائد اذیت پہنچاتے ہوں۔ مذکورہ روایت سے معلوم ہوا کہ کفار کے لیے بد دعا کرنا جائز ہے جبکہ وہ مسلمانوں کو","",{"k":"صحیح بخاری (٩١٩)۔"}],[55,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ علم کو لوگوں سے چھین کر اپنی طرف نہیں اٹھالے گا بلکہ علماء اپنی طرف قبض کر لینے سے علم کو اٹھالے گا یہاں تک کہ جب کوئی عالم باقی نہ رہے گا تو لوگ جاہلوں کو سردار بنالیں گے ان سے مسائل پوچھے جائیں گے تو وہ بغیر علم کے فتویٰ دیں گے، وہ خود بھی گمراہ ہوں گے اور دوسروں کو بھی گمراہ کر دیں گے۔“ حضرت ہشام بن عروہ اپنے والد سے، وہ حضور نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں اور اسناد میں عبد اللہ بن عمر کا ذکر نہیں کرتے۔ (١) مذکورہ روایت سے معلوم ہوا کہ علم علماء کے ساتھ اُٹھا لیا جائے گا، پھر جہالت ہوگی جاہل فتوی دیں گے۔ (٢) معلوم ہوا کہ جہالت کی بنا پر فتویٰ دینا درست نہیں ہے۔ اگر علم نہ ہو تو فتویٰ نہ دیا جائے۔ (٣) علم کا اٹھ جانا علامات قیامت سے ہے۔ (٤) قرب قیامت گمراہی و ضلالت عام ہو جائے گی۔ .٥٦","",{"k":"حَدَّثَنَا أَحْمَدُ بْنُ عَبْدِ الْوَهَّابِ بْنِ نَجْدَةَ قَالَ: يَا أَبُو الْمُغِيرَةِ قَالَ: نا الْأَوْزَاعِيُّ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ، وَلَمْ يَذْكُرْ فِي الْإِسْنَادِ: عَبْدَ اللَّهِ بْنَ عَمْرٍو المعجم الكبير للطبراني (٢٠/٨٩)۔"}],[56,"سیدنا عبداللہ ابن عمر بالا بیان کرتے ہیں رسول اللہ میم نے فرمایا: ”جو شخص جمعے کو آئے تو وہ فسل کرے۔“ یہ حدیث اوزاعی سے صرف ابو مغیرہ ہی روایت کرتے ہیں۔","",{"k":"تقدم تخريجه، انظر (١٨)۔"}],[57,"سیدنا عبد اللہ فی المیہ سے روایت ہے کہ نبی صلے سلیم نے فرمایا: ” تو اور تیرا مال تیرے باپ کا ہے۔","",{"k":"سنن ابن ماجه (٢٢٩٢)، قال الالباني، صحیح۔","f":"(١) مذکورہ روایت سے معلوم ہوا کہ باپ اپنے بیٹے کی کمائی کھا سکتا ہے۔ کیونکہ اولاد پر واجب ہے کہ اپنے والدین کی کفالت کریں اور اسے اپنے لیے سعادت جانیں۔ لیکن اس کا یہ مطلب نہیں کہ سارا مال باپ کا ہی ہے۔ کیونکہ اللہ تعالیٰ نے ان دونوں کی ملکیت اور تصرف علیحدہ علیحدہ رکھا ہے۔ اسی بنا پر ان دونوں میں وراثت چلتی ہے۔\n(٢) اس روایت میں والدین کے مقام و مرتبہ کو بھی واضح کیا گیا ہے۔"}],[58,"سیدنا عوف بن مالک ابھی نبی اللہ نے بیان کیا، میں نبی متے کے پاس گیا تو آپ ایک چڑے کے خیمے میں تھے، میں نے آپ کو سلام کیا، پھر کہا: کیا میں اندر آ سکتا ہوں؟ آپ نے فرمایا: ” آ جاؤ تو میں نے اپنا سر اندر داخل کیا تو آپ اطمینان وسکون سے وضو فرما رہے تھے میں نے کہا یا رسول اللہ مائے نی میں کیا میں سارا اندر آ سکتا ہوں؟ آپ نے فرمایا: ”تم سارے اندر آ جاؤ جب میں اندر گیا تو آپ نے مجھے فرمایا: ”قیامت سے قبل چھ باتیں شمار کر لو (١) تمہارے نبی کی وفات، عوف فضل اللہ کہتے ہیں میں اس بات پر اتنا خاموش ہوا جتنا میں پہلے کبھی نہیں ہوا، آپ نے فرمایا: ”ایک، میں نے کہا: ایک، آپ نے فرمایا: (٢) بیت المقدس کی فتح۔ (٣) تم میں ایک فتنہ ہو گا جو عرب کے گھروں پر عام ہو گا۔ (٤) اور ایک بیماری جو تمہیں اس طرح پکڑے گی جس طرح بکریوں کو عقاص بیماری پکڑ لیتی ہے (٥) اور تم میں مال عام ہو جائے گا، حتی کہ ایک آدمی کو سو دینار دیئے جائیں گے اور وہ پھر بھی راضی نہ ہوگا۔ (٦) پھر تمہاری بنو اصفر (روم، یورپ، امریکہ کے لوگوں ) سے صلح ہو جائے گی لیکن وہ غدر کریں گے اور تمہاری طرف اسی (٨٠) جھنڈوں تلے جمع ہو کر آئیں گے، اور ہر جھنڈے کے نیچے بارہ ہزار فوجی ہوں گے۔ مکحول سے صرف عبداللہ بن علاء بن زبر فضل اللہ ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قیامت سے قبل چھ چیزوں کا ظہور ہوگا۔ (١) نبی صلی اللہ علیہ وسلم کی وفات: مسلمانوں پر آنے والے مصائب و مشکلات میں سب سے بڑی مصیبت امام کائنات کی وفات تھی جس نے صحابہ کرام بھی ایم کو بے چین کر دیا تھا اور ان کی آنکھوں کے سامنے اندھیرے چھا گئے تھے۔ انہیں نظر نہیں آ رہا تھا کہ ہم کیا کریں؟ حالانکہ آپ کی وفات ایک فطری امر تھا ﴿ وَمَا جَعَلْنَا لِبَشَرِ مِنْ قَبْلِكَ الْخُلْدَ أَفَأَئِنْ مِتَ فَهُمُ الْخَلِدُوْنَ﴾ (الانبياء: ٣٤) (٢) مسجد اقصیٰ کی آزادی اور فتح بیت المقدس جو کہ قبلہ اول ہے، اور اس پر یہودیوں کا قبضہ اب بھی ہے اور خیر القرون میں بھی تھا۔ لیکن سرور عالم سے تم نے مسلمانوں کے ہاتھوں اس کی فتح ہونے کی پیش گوئی فرمائی تھی جو ٦ ہجری میں خلیفہ ثانی سیدنا فاروق اعظم بنی اہلیہ کے ہاتھوں پر پوری ہوئی۔ (٣) فتنوں کی بھی نبی معظم ملنے سلیم نے پیش گوئی فرمائی۔ فتنہ کے معنی امتحان، آزمائش، اور مصائب و آلام کے ہیں۔ نبی معظم صلی اللہ علیہ وسلم نے امت کے لوگوں کو ان فتنوں کے متعلق آگاہ فرمایا تھا۔ آپ کی وفات اور وحی کی آمد کے سلسلہ کے منقطع ہونے کے ساتھ ہی ملت اسلامیہ میں فتنوں کا سلسلہ شروع ہو گیا تھا۔ جن میں سے چند فتنے یہ تھے: (١) فتنہ ارتداد (٢) فتنه قتل عثمان رضی اللہ عنہ جنگ جمل (٤) جنگ صفین (٥) خوارج کا ظہور (٦) سیدنا علی رضی اللہ عنہ کی شہادت (٧) سانحہ کربلا (٨) واقعه حرۃ ٢١ ہجری (٩) جبریہ، قدریہ، اور معتزلہ کے فتنے وغیرہ۔ نوٹ: ایک حدیث میں مذکور عرب کے اس فتنہ کے مقتولین کو جہنمی کہا گیا ہے۔ (دیکھئے: مسند احمد: ٢١١/٢) (٤) عقاص الغنم ایک بیماری ہے، جو جانور کو اپنی لپیٹ میں لے لیتی ہے جس سے اس کی ناک سے ایک مادہ خارج ہونے لگتا ہے اور وہ آنا فانا مر جاتا ہے نبی کا پینا نے موت کی کثرت کو ” عقاص الغنم “ سے اس لیے تشبیہ دی ہے کہ طاعون میں بھی بدن میں ایک ایسا ہی زخم ہوتا ہے جس سے ایک سیال مادہ خارج ہوتا ہے، اور مریض اس کے باعث موت کے منہ میں چلا جاتا ہے۔ حافظ ابن حجر العسقلانی اللہ فرماتے ہیں یہ بیماری فلسطین کے شہر عمواس میں طاعون کی صورت میں ظاہر ہو چکی ہے جو سیدنا عمر ربی الیہ کے دور خلافت میں ١٨ ہجری کو بیت المقدس کی فتح کے بعد واقع ہوئی۔ (فتح الباری ٣٢١/٦، کتاب الجزیه) حافظ ابن کثیر جماللہ فرماتے ہیں: یہ سن ١٨ ہجری کی بات ہے عمواس شہر کے محلہ میں طاعون کا مرض پھیلا اور اس نے پورے شام کو اپنی لپیٹ میں لے لیا جس میں بہت سے صحابہ کرام بی الیہم اجمعین لقمہ اجل بن گئے۔ ان میں سیدنا معاذ بن جبل، ابوعبیدہ بن جراح، شرحبیل بن حسنه، فضل بن عباس اور بعض دیگر جلیل القدر صحابہ کرام بینی اسلیم بھی شامل تھے۔ ایک عام اندازے کے مطابق ٢٥ ہزار مسلمان اس بیماری میں کام آئے۔ (البدايه والنهايه: ٧٦/٧) (٥) مال کی کثرت: سیدنا عمر رضی اللہ عنہ اور سیدنا عمر بن عبد العزیز رحمتہ اللہ کے زمانہ میں مال کی کثرت تھی، اسی طرح امام مہدی اور سیدنا عیسی عالی نام کے زمانہ میں بھی مال کی کثرت ہوگی۔ (٢) علاماتِ قیامت میں سے مسلمانوں اور رومیوں کے مابین ایک بہت بڑی جنگ بھی ہے۔ یہ ظہور مہدی سے قبل ہوگی۔ نبی عالیسلام نے اس کا نام الْمَلْحَمَةُ الْكُبْری“ رکھا ہے۔ (سنن ابی داؤد، کتاب الملاحم، رقم: ٤٢٩٤، وحسنه الألباني في صحيح ابی داؤد)","",{"k":"صحیح بخاری، الجزيه والموادعه (٣١٧٦)، المعجم الكبير للطبراني (٤٠١/١٢)۔"}],[59,"سیدنا عبد الرحمن بن عوف، سیدنا معاویہ بن ابی سفیان اور سیدنا عبد اللہ بن عمرو دی انیمه بیان کرتے ہیں کہ رسول الله ملل علیم نے فرمایا: ہجرت دو طرح کی ہوتی ہے(١) ایک یہ ہے کہ تم گناہوں کو ترک کر دو۔ (٢) دوسری ہجرت یہ ہے کہ تم اللہ تعالیٰ اور اس کے رسول کی طرف ہجرت کرو۔ اور جب تک تو بہ قبول ہوتی ہے ہجرت ختم نہیں ہوتی۔ اور تو بہ مغرب سے سورج طلوع ہونے تک قبول ہوتی رہتی ہے۔ جب سورج مغرب سے طلوع ہو گا اس وقت ہر ایک دل میں جو کچھ ایمان یا کفر ) ہے اس پر مہر لگ جائے گی، اور لوگوں کو عمل کرنے کی ضرورت نہیں ہوگی۔ عبدالرحمن بن عوف سے یہ حدیث اسی طریقہ سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ ہجرت دو طرح کی ہے۔ (١) باطنی ہجرت (٢) ظاہری ہجرت (١) باطنی ہجرت، جو ہر جگہ، ہر حال میں ہے قیامت تک رہے گی اور یہی حقیقی ہجرت ہے۔ (٢) ظاہری ہجرت، یہ ہجرت بلاد کفر سے بلاد اسلام کی طرف ہے۔ جب کفار کے علاقے میں اسلام کے احکامات پر عمل کرنا مشکل ہو جیسا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ہجرت منقطع نہیں ہوگی جب تک دشمن سے جنگ جاری رہے گی۔ (سنن نسائی، کتاب البيعة، رقم: ٤١٧٣، ابن حبان، رقم: ٤٨٦٦)","",{"k":"المعجم الكبير للطبراني (٣٠٧/١٤، ١٦٢٦٠)۔"}],[60,"سیدنا ابو ذر رضی اللہ عنہ فرماتے ہیں: پہلی چیز جس نے مجھے اسلام کی طرف دعوت دی وہ یہ تھی کہ ہم عرب لوگ تھے۔ ہمیں قحط آ گیا تو میں اپنی ماں اور بھائی کو جس کا نام اُنہیں تھا اپنے سسرال کے پاس لے گیا جو نجد کے اوپر والی جانب میں رہتے تھے۔ جب ہم ان کے پاس پہنچے تو انہوں نے ہماری عزت و تکریم کی۔ جب یہ بات قبیلے کے ایک آدمی نے دیکھی تو وہ میرے ماموں کے پاس چلا گیا اور اسے کہنے لگا: تجھے معلوم ہے کہ انیس تیرے گھر والوں کی طرف تیرے پیچھے جاتا ہے۔ اس کے دل میں شگاف پڑ گیا اور جب میں اپنے اونٹوں کو چرا کر واپس آیا تو اسے غمگین دیکھا، اور رونے لگا۔ میں نے کہا: ماموں جان کیوں رو ر ہے ہو؟ اس نے مجھے بات بتائی۔ میں نے کہا: اللہ تعالیٰ ہمیں اس سے بچائے ہم تو بے حیائی کو برا سمجھتے ہیں۔ لوگوں نے ہمارے درمیان خلل ڈال دیا۔ اور جس طرح تم نے ہم کو شروع میں صاف دل رکھا تھا اتنا ہی تو نے ہمارے دلوں کو گدلا کر دیا اب اکٹھے رہنے کی کوئی صورت ممکن نہیں۔ میں نے اپنی ماں اور بھائی کو اُٹھا کر میکے کے قریب کی آبادی میں لے آیا۔ میرے بھائی نے کہا: میں ایک آدمی سے پانی پر شعر کے ذریعہ مقابلہ کروں گا۔ میرا بھائی شاعر تھا۔ میں نے اسے کہا: ایسے نہ کرو مگر وہ اصرار کی وجہ سے نکل آیا اور درید بن جمہ سے مقابلہ کیا۔ اس کے ریوڑ کو اپنے ریوڑ کی طرف کیا۔ اللہ کی قسم! میرے بھائی سے درید اونچا تھا تو وہ دونوں خنساء کے پاس فیصلہ لے گئے۔ اس نے میرے بھائی کے حق میں درید کے خلاف فیصلہ دے دیا۔ کیونکہ درید اس کے باپ سے اس کا رشتہ مانگتا تھا۔ مگر خنساء نے کہا: وہ بہت بوڑھا ہے مجھے اس کی کوئی ضرورت نہیں پھر اس نے درید کے متعلق دل میں کینہ رکھ لیا۔ ہم نے اس کا ریوڑ اپنے ریوڑ سے ملا لیا اور ہمارے اونٹ ایک بڑا ریوڑ سو کے قریب ہو گئے۔ پھر میں مکے آیا تو سب سے پہلیصفا پر آیا۔ وہاں قریش کے کچھ لوگ موجود تھے۔ مجھے پتہ چلا تھا کہ وہاں ایک صابی، دیوانہ، شاعر اور جادوگر ہے۔ میں نے کہا: وہ جس کو یہ لقب دیئے جاتے ہیں وہ کہاں ہے؟ انہوں نے کہا: وہ ہے جہاں تو دیکھ رہا ہے۔ میں ادھر مڑا تو میں ایک پتھر کے برابر بھی آگے نہیں گیا کہ وہ ہڈیوں، پتھروں اور اینٹوں پر ٹوٹ پڑے اور مجھے خون آلود کر دیا۔ میں بیت اللہ کے پاس آگیا تو اس کے پردوں اور عمارت کے درمیان داخل ہو گیا اور تمیں دن نہ کچھ کھایا، نہ پیا صرف ماء زمزم پیتا رہا۔ جب ایک چاندنی رات ہوئی تو خزاعہ کی دو عورتیں آئیں۔ انہوں نے بیت اللہ کا طواف کیا۔ پھر اساف اور نائلہ کا ذکر کر نے لگیں اور یہ دونوں بت تھے جن کی لوگ پرستش کرتے تھے۔ میں نے ان پردوں سے اپنا سر نکالا اور کہا: ایک کو دوسرے پر چڑھا دو ( یعنی ایک کی دوسرے سے شادی کر دو) تو وہ ناراض ہوئیں۔ پھر کہنے لگیں: خدا کی قسم! ہمارے مرد موجود ہوتے تو تم یہ بات کبھی نہ کہتے۔ میں نکل کر ان کے پیچھے ہو لیا یہاں تک کہ وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس چلی گئیں۔ انہیں ملیں تو آپ نے پوچھا تم کون ہو؟ کس قبیلے سے ہو؟ اور کہاں سے آئی ہو؟ انہوں نے آپ کو ساری بات بتائی۔ آپ نے پوچھا تم نے اس صابی کو کہاں چھوڑا؟ انہوں نے کہا وہ کعبے کی عمارت اور پردوں میں ہے۔ آپ نے ان سے پوچھا: ”کیا انہوں نے تمہیں کچھ کہا؟ انہوں نے کہا: ہاں، ایسی بات کہی کے منہ کو پھیر دیتی ہے۔ آپ مسکرائے تو وہ دونوں چلی گئیں۔ میں آپ کے پاس آ گیا اور آپ کو اس وقت سلام کہا: آپ نے فرمایا: ”تم کون ہو؟ کہاں کے رہنے والے ہو؟ اور کہاں سے آئے ہو؟ اور کس کام سے آئے ہو؟“ میں آپ کو ساری بات بتانے لگا تو آپ نے پوچھا ” کہاں سے کھاتے پیتے رہے؟ میں نے کہا: صرف زمزم کا پانی پیتا رہا ہوں۔ آپ نے فرمایا: ”و کھانے کا کھانا ہے۔“ آپ کے پاس سیدنا ابو بکر بنی انہیں بھی تھے۔ وہ کہنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! اجازت دیجئے کہ اسے آج رات میں اپنے پاس رکھوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ٹھیک ہے۔‘ پھر رسول اللہ صلی اللہ علیہ وسلم باہر نکلے چلنے لگے اور سیدنا ابو بکر رضی اللہ عنہ نے میرا ہاتھ پکڑ لیا، یہاں تک کہ رسول اللہ نے تم سیدنا ابو بکر بی اے کے دروازے پر جار کے۔ پھر ابو بکر رضی اللہ عنہ گئے اور ہمارے پاس طائف کا منقہ لے آئے۔ ہمارے آگے مٹھیوں سے رکھتے رہے اور ہم اس سے کھاتے رہے۔ یہاں تک کہ ہم اس سے سیر ہو گئے۔ نبی اللے تم نے فرمایا: ”ابو ذر! میں نے کہا: جی حاضر ہوں۔ فرمایا: ” مجھے زمین اٹھا کر دکھائی گئی اور وہ زمین کھجوروں والی تھی، میرا خیال ہے کہ وہ تہامہ ہوسکتی ہے۔ اپنی قوم کے پاس جاؤ تو انہیں بھی اس دین کی دعوت دو، جس میں تم داخل ہو چکے ہو۔ سیدنا ابوذر رضی اللہ عنہ کہتے ہیں: میں آپ کے پاس سے آیا تو اپنی ماں اور بھائی کے پاس چلا گیا۔ انہیں سارا واقعہ بتایا تو وہ کہنے لگے: جس دین میں تو داخل ہو گیا ہے ہم بھی بے رغبت نہیں ہم بھی مسلمان ہو گئے پھر ہم نکل کر مدینے آ گئے اور اپنی قوم کو ساری بات بتائی۔ وہ کہنے لگے: ہم تیری تصدیق کرتے ہیں لیکن ہم خود آپ ملنے کو ملنا چاہتے ہیں۔ جب نبی ملنے کی تم ہمارے پاس تشریف لائے تو ہم سب آپ سے ملے۔ غفار قبیلے نے آپ سے کہا: یا رسول اللہ علیم! ابو ذر نے ہمیں جو کچھ بتایا ہم نے وہ معلوم کر لیا، اور ہم مسلمان ہو گئے،اور ہم گواہی دیتے ہیں کہ آپ اللہ کے رسول ملے لیتے ہیں۔ پھر اسلم خزاعہ آگے ہوئے۔ انہوں نے کہا: یا رسول اللہ علیم! ہم بھی اس دین میں رغبت رکھتے ہیں جس دین میں ہمارے بھائی اور حلیف داخل ہوئے ہم بھی اس میں داخل ہوتے ہیں۔ آپ نے فرمایا: ”اسلم قبیلے کو اللہ تعالیٰ سلامت رکھے، اور غفار کو اللہ معاف کر دئے، پھر سیدنا ابو بکر رضی اللہ عنہ نے میرا ہاتھ پکڑا اور کہا: ابو ذر ضیا اللہ! میں نے کہا جی ابوبکر! تو انہوں نے کہا: کیا تم اپنی جاہلیت کے دور میں بھی کسی معبود کی بندگی کرتے تھے؟ میں نے کہا: جی ہاں جان بوجھ کر دھوپ میں کھڑا رہتا تھا جب اس سے سخت تکلیف محسوس کرتا تو میں کمبل کی طرح لوٹ پوٹ ہو کر گر پڑتا تو مجھے کہنے لگے تم کس طرف منہ کرتے تھے میں نہیں جانتا مگر جس طرح بھی اللہ تعالیٰ مجھے موڑ دیتے یہاں تک کہ اللہ تعالیٰ نے مجھے اسلام میں داخل کر دیا۔“ عروہ بن رویم سے ابوطرفہ عباد بن ریان روایت کرتے ہیں۔ عباد سے صرف ولید روایت کرتے ہیں، ان سے روایت کرنے میں محمد بن عائذ ا کیلئے ہیں۔","",{"k":"المعجم الكبير للطبراني (٣٢٥/١)۔","f":"(١) مذکورہ روایت میں سیدنا ابو ذر غفاری رضی اللہ عنہ کے اسلام لانے کا واقعہ ہے۔\n(٢) یہ بھی معلوم ہوا کہ زمزم کھانے اور پینے دونوں کے لیے کام آتا ہے۔ جیسا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: (( خَيْرُ مَاءِ عَلَى وَجْهِ الْأَرْضِ مَاءُ زَمْزَمٍ فِيْهِ طَعَامُ الطَّعْمِ وَشِفَاءُ السُّقْمِ)) زمین پر سب سے بہتر پانی زمزم کا ہے جو بھو کے کا کھانا اور بیمار کی شفا ہے۔ (مجمع الزوائد: ٢٨٦/٣، رجال صحيح.)\n(٣) قبیلہ اسلم اور غفار کے لیے دعا فرمائی: جیسا کہ بخاری شریف میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” غفار کی اللہ تعالیٰ نے مغفرت فرما دی اور قبیلہ اسلم کو اللہ تعالیٰ نے سلامت رکھا۔“ (صحیح بخاری، کتاب المناقب: ٣٥١٣) کیونکہ عہد جاہلیت میں ان قبیلوں کو دوسرے قبیلوں سے کم درجے کا سمجھا جاتا تھا۔ قبیلہ غفار والے عہد جاہلیت میں حاجیوں کا مال چراتے، چوری کرتے، اسلام لانے کے بعد اللہ تعالیٰ نے ان کے گناہوں کو معاف کر دیا۔"}],[61,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تبارک و تعالیٰ فرماتے ہیں: اے ابن آدم! اگر تو زائد از ضرورت مال دے دے تو یہ چیز تیرے لیے بہتر ہے۔ اور اگر تو اس کو روک رکھے گا تو یہ چیز تیرے لیے بہت بری ہے۔ اور اس شخص سے شروع کر جس کی تو کفالت کرتا ہے اور بقدر ضرورت روزی رکھنے والے پر اللہ ملامت نہیں کرتا اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔“‘ قاسم سے صرف عبداللہ بن علاء ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ضرورت سے زائد مال جمع کرنا، لوگوں میں تقسیم نہ کرنا، کنجوسی کرنا، اللہ ذوالجلال کے نزدیک ناپسندیدہ ہے۔ اور مال خرچ کرتے وقت ان سے ابتدا کرنا چاہیے جن کی کفالت کا ذمہ آدمی پر ہے۔ ایک حدیث میں ہے کہ آدمی کے لیے یہ گناہ ہی کافی ہے کہ وہ جس کی خوراک کا ذمے دار ہے اس سے ہاتھ روک لے۔ (صحیح مسلم، كتاب الزكاة، رقم: ٩٩٦) اوپر والا ہاتھ نیچے سے بہتر ہے اس میں انفاق فی سبیل اللہ کی فضیلت کا تذکرہ ہے۔","",{"k":"السلسلة الصحيحة (٥/٤٧٢، ٢٤٧٣)، المعجم الكبير للطبراني (٩٩/٩)۔"}],[62,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سب سے پہلے جس چیز کے متعلق بندے سے سوال ہوگا وہ یہ ہے: کیا میں نے تیرا جسم صحیح و تندرست نہیں بنایا اور تجھے ٹھنڈے پانی سے سیراب نہیں کیا۔ ضحاک بن عبدالرحمن بن عرزب سے صرف عبداللہ بن علاء ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ قیامت کے دن اللہ کی نعمتوں کے متعلق سوال ہو گا۔ جیسا کہ ارشاد باری تعالیٰ ہے ﴿ ثُمَّ لَتُسْئَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ ﴾ (التکاثر: ٨) ”پھر اس دن تم سے نعمتوں کے بارے میں ضرور پوچھا جائے گا۔“ اسی طرح سیدنا ابو ہریرہ نبی الیہ سے روایت ہے، ایک دن نبی معظم تعلیم، سیدنا ابو بکر اور سیدنا عمر نیا اینجا بھوک کی وجہ سے گھر سے نکلے اور ایک انصاری کے گھر آئے، اس نے مہمانی میں کھجوریں اور بکری کا گوشت پیش","",{"k":"المعجم الكبير للطبرانی (١٩/١٠٠)۔","f":"کیا۔ آپ صلی اللہ علیہ وسلم نے گوشت اور کھجور میں کھائیں اور شیریں پانی پیا۔ جب خوب سیر ہو چکے تو آپ مطلئے علیم نے فرمایا: ” مجھے اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! تم سے قیامت کے دن اس نعمت کے بارے میں ( بھی ) سوال ہوگا۔‘“ (صحیح مسلم، کتاب الاشربه)"}],[63,"سیدنا ابو عمره انصاری رضی اللہ عنہ نے بیان کیا، ہم ایک جنگ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ لوگوں کو بھوک لگ گئی۔ انہوں نے اپنی بعض سواریوں کو ذبح کرنے کے لیے رسول اللہ ملے عام سے اجازت مانگی، آپ نے اجازت دینے کا ارادہ کر لیا تھا کہ سیدنا عمر بن خطاب خیال یہ کہنے لگے: اللہ کے رسول لئے عام ہے اگر ہم اپنی سواریاں ذبح کر دیں گے تو پھر کل جب دشمن کو ملیں گے تو ہم بھوکے اور پیدل ہوں گے۔ آپ نے فرمایا: ”اے عمر! پھر تمہارا کیا خیال ہے؟“ انہوں نے کہا: لوگوں سے ان کا بچا ہوا زادِ راہ منگوا کر اس میں برکت کی دعا کریں۔ اللہ تعالیٰ ہمیں آپ کی دعا کی وجہ سے ان شاء اللہ تعالیٰ منزل مقصود تک پہنچا دے گا۔ اس طرح ہوا گویا کہ آپ پر پردہ تھا جو ہٹا دیا گیا۔ آپ نے حکم دیا تو چٹائی بچھائی گئی۔ پھر لوگوں سے ان کے بچے ہوئے زاد راہ منگوائے گئے تو جو کچھ ان کے پاس تھا وہ لے آئے۔ لوگوں میں سے کوئی کھانے کی ایک مٹھی لے آیا، کوئی ایک چلو لے آیا، کوئی انڈے کے برابر لے آیا، آپ نے حکم دیا اور وہ سب ایک کپڑے میں رکھے گئے، پھر آپ نے برکت کی دعا کی، پھر جو اللہ نے چاہا وہ کلام کیا، پھر لشکر میں آواز دی تو وہ آگئے، پھر انہیں حکم دیا وہ کھانے لگے، اور برتن بھر لیے، اور اپنے تو شہ دان بھی، پھر ایک چھوٹا ڈھل منگوا کر سامنے رکھ لیا، پھر کچھ پانی لا کر اس میں ڈال دیا، پھر اس میں کلی کی، اور جو اللہ نے چاہا وہ کلام زبان سے ادا کیا پھر آپ نے اپنی انگلی داخل کی تو میں اللہ کی قسم اٹھاتا ہوں کہ میں نے آپ کی انگلیاں دیکھیں کہ ان سے پانی کے چشمے پھوٹ پڑے۔ پھر لوگوں کو حکم دیا تو انہوں نے پی لیا، اور کچھ نے مشکیں بھر لیں، اور برتن وغیرہ بھی۔ پھر آپ ہنسے یہاں تک کہ آپ کی ڈاڑھیں نظر آنے لگیں اور فرمایا: ”میں گواہی دیتا ہوں کہ اللہ وحدہ لا شریک ہے اور محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں۔ یہ دو شہادتیں جو شخص بھی قیامت کے دن لے کر اللہ سے ملے گا تو وہ چاہے جس عمل پر بھی ہو جنت میں داخل ہوگا۔“ یہ حدیث زہری سے از عبداللہ بن علاء ہی روایت کرتے ہیں، اُن سے روایت کرنے میں ان کے بیٹے اکیلے ہیں۔","",{"k":"مجمع الزوائد: ١ / ٢٠ المجعم الكبير (١/٦٧٦)۔","f":"(١) مذکورہ حدیث میں نبی معظم صلی اللہ علیہ وسلم کے معجزہ کا اثبات ہے، کھانے میں برکت ہوئی اور اللہ تعالیٰ نے انگلیوں سے چشمہ جاری کر دیا۔\n(٢) یہ بات بھی ثابت ہوئی کہ جو تو حید و رسالت پر فوت ہو گا وہ جنت میں جائے گا جیسا کہ سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ نبی رحمت ملنے کی کیانی نے فرمایا: ”جس شخص نے خالص دل سے لا الہ الا اللہ (کلمہ توحید ) کی گواہی دی، وہ جنت میں داخل ہوگا۔“ (سلسلة صحيحه، رقم: ٢٣٥٥)"}],[64,"سیدنا انس بن مالک فضل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس کے اخلاق اپنے غلام، چوپایوں اور بچوں سے برے ہوں تو اس کے کانوں میں یہ آیت پڑھو: ﴿أَفَغَيْرَ دِيْنِ اللَّهِ يَبْغُونَ ”کیا وہ اللہ تعالیٰ کے دین کے علاوہ کوئی اور دین تلاش کرتے ہیں؟“ یہ حدیث حضرت انس سے صرف اسی سند سے مروی ہے۔","",{"k":"السلسلة الضعيفة (٦٧٦)۔"}],[65,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (شیر خوار بچوں کو ) بے وقوف عورتوں سے دودھ پلوانے سے منع فرمایا۔ سالم بن عبداللہ سے صرف ابو معمر اور ابو معمر سے حکم بن یعلی ہی روایت کرتے ہیں، سلیمان بن عبدالرحمن اس حدیث کو روایت کرنے میں اکیلے ہیں۔","",{"k":"مجمع الزوائد (٤/٢٦٢)، عباد بن عبد الصمد وهو ضعيف۔"}],[66,"سیدنا عرباض بن ساریہ ضیا اللہ سے روایت ہے کہ ایک دن صبح کے وقت ہم میں رسول اللہ نے تم کھڑے ہوئے تو ہمیں نصیحت فرمائی جس سے دل لرز لگے، آنکھیں اشک بار ہو گئیں۔ ہم نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ صلی اللہ علیہ وسلم نے ہمیں ایسا وعظ فرمایا ہے جس طرح الوداع کرنے والا آخری نصیحتیں کرتا ہے۔ اس لیے کوئی وصیت فرمائیں؟ آپ ملنے سلیم نے فرمایا: تم اللہ سے ڈرنا اور اپنے امیر کی بات سننا اور ماننا اپنے اوپر لازم کر لو چاہے تمہارا حاکم حبشی غلام ہی کیوں نہ ہو۔ جو شخص میرے بعد باقی رہا وہ شدید اختلاف دیکھے گا۔ تم میری سنت اور خلفاء راشدین ( ہدایت یافتہ ) کی سنت کو لازم پکڑو، اسے اپنے دانتوں میں مضبوط پکڑ لو اور (دین میں) نئے کاموں سے بچ کر رہنا کیونکہ ہر نیا کام گمراہی ہے۔“ یہ حدیث یحیی بن ابی المطاع سے صرف عبداللہ بن علاء بن زبر ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ صحابہ منی ایم کو نبی مکرم سے ہم نے چند نصیحتیں فرمائی تھیں۔ (١) اللہ سے ڈرنا، تقویٰ اختیار کرنا، اسی طرح ارشاد باری تعالیٰ ہے۔ يَأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ حَقَّ تُقَتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُّسْلِمُونَ (آل عمران: ١٠٢) ”اے ایمان والو! اللہ سے ڈرو، جیسا اس سے ڈرنا چاہیے، اور تمہاری موت آئے تو اسلام پر آئے۔“ (٢) یہ بھی معلوم ہوا کہ جائز کاموں میں حکمرانوں کی اطاعت ضروری ہے۔ ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ امَنُوا أَطِيعُوا اللَّهَ وَاَطِيْعُوا الرَّسُولَ وَ أُولِي الْأَمْرِ مِنْكُمْ﴾ (النساء: ٥٩) اللہ تعالیٰ نے فرمایا: اے ایمان والو! اطاعت کرو اللہ کی اور اطاعت کرو رسول کی اور ان کی جو تمہارے حکمران ہیں۔“ وہ حکمران غلام سیاہ فام بھی ہو تو اس کا احترام کرنا ضروری ہے، رنگ کیسا ہی ہو، وہ کسی بھی نسل سے تعلق رکھتا ہو بشرطیکہ اس کا حکم قرآن وحدیث کے مخالف نہ ہو۔ (٣) فتنوں کے ظہور کی بھی خبر دی مقصد امت کو متنبہ کرنا ہے تا کہ وہ ان سے اپنا دامن بچا کر رکھے اس لیے اس سے بچنے کا طریقہ بھی بتلا دیا کہ میری سنت اور خلفاء راشدین کے طریقے پر چلنا۔ (٤٢) اسی طرح صحیح راستے کی نشاندہی بھی فرما دی۔ وہ یہ کہ نبی مکرم نے ایم کی سنت اور خلفائے راشدین کے تعامل سے تجاوز نہ کیا جائے یہ کثرت اختلافات میں حق کو پہچاننے کی ایک کسوٹی اور معیار ہے۔ (٥) یہ بھی معلوم ہوا کہ مسلمانوں کو بدعات ( دین میں نئے نئے کام کرنے ) سے بچنا چاہیے، کیونکہ وہ کام مردود ہے۔ جیسا کہ سیدہ عائشہ منی انہما سے روایت ہے نبی مکرم ماے علی تم نے فرمایا: ”جس نے ہمارے اس دین (اسلام) میں (اپنی طرف سے ) کوئی نئی بات ایجاد کی جو اس میں سے نہیں، تو وہ مردود ہے۔“ (صحیح بخاری، کتاب الصلح، رقم: ٢٦٩٨، صحیح مسلم، رقم: ١٧١٨)","",{"k":"سنن ابن ماجه، المقدمة (٤٢)، قال الالباني، صحیح، سنن الكبرى للبيهقي (١/١١٤)۔"}],[67,"سیدنا ابو ثعلبہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے وہ چیز بتائیں جو میرے لیے حلال ہے اور جو چیز میرے لیے حرام ہے؟ تو آپ نے اپنی نظر مبارک میرے اوپر سے نیچے تک دوڑائی اور فرمایا: ”اے نئی پود! میں نے کہا: اللہ کے رسول! اچھی پود یا بُری پود ہوں؟ آپ نے فرمایا: بلکہ تم اچھی پود ہو۔ پالتو گدھے کا گوشت کھاؤ نہ درندوں میں سے کچلیوں والے جانور کھاؤ۔‘ عبداللہ بن علاء فرماتے ہیں کہ مجھے بسر بن عبید اللہ نے حضرت ابو ادریس خولانی کے حوالے سے بیان کیا از ابو ثعلبہ اسی کی مثل۔ مسلم بن مشکم سے صرف عبد اللہ بن علاء بن زبیر ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ پالتو گدھا، اور درندوں میں کچلیوں والا جانور حرام ہے۔ () پالتو گدھے کا گوشت کھانا حرام ہے اور اس کی حرمت غزوہ خیبر کے موقع پر نازل ہوئی تھی۔ (صحیح بخاری، کتاب المغازي، رقم: ٤١٩٨) (٢) درندوں میں سے ہر کچلی والا جانور حرام ہے۔ جبکہ پرندوں کے متعلق ضابطہ بیان کرتے ہوئے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” پرندوں میں سے ہر ایسے پرندے کا کھانا حرام ہے جو پنجے کے ذریعے شکار کرے۔“ (صحیح مسلم، کتاب الصيد رقم: ١٩٣٤) (( ذي ناب من السباع)) سے مراد ایسا درندہ ہے جو کچلیوں کے ساتھ شکار کر کے کھائے۔ مثلاً شیر، بھیڑیا اور چیتا وغیرہ۔ ((مخلب)) کا معنی پنجہ یا چنگل ہے (ذی مخلب)) یعنی جو پنجوں کے ذریعے شکار کرے (مثلاً چیل، شائیس اور باز وغیرہ) ان احادیث میں شرع نے ایک جامع اصول بیان کر دیا ہے اب جو جانور اس کے تحت آئے گا وہ حرام ہوگا، اور جو اس کے تحت نہیں آئے گا وہ حلال ہوگا الا کہ کسی جانور کی الگ سے حرمت بیان کر دی گئی ہو۔ اسی طرح شارع نے ان کے علاوہ جو جانور حرام ہیں ان کی بھی نشاندہی کر دی ہے۔","",{"k":"وَحَدَّثَنِي بُسْرُ بْنُ عُبَيْدِ اللهِ، عَنْ أَبِي إِدْرِيسَ الْخَوْلَانِيِّ، عَنْ أَبِي ثَعْلَبَةَ مِثْلَهُ . لَمْ يَرْوِهِ عَنْ مُسْلِمِ بْنِ مِشْكَم إِلَّا عَبْدُ اللَّهِ بْنُ الْعَلَاءِ بْنِ زَيْرٍ . مجمع الزوائد (٤/١٦٨)۔"}],[68,"سیدنا عبداللہ بن سعدی رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس وفد کی صورت میں آئے، ہم سات آٹھ آدمی تھے ہر ایک اپنی ضرورت کی چیز مانگ رہا تھا۔ میں ان سب سے آخر میں اندر گیا تو میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! میں اپنے پیچھے کچھ ایسے لوگ چھوڑ آیا ہوں جو کہتے ہیں کہ ہجرت ختم ہوچکی ہے۔ آپ نے فرمایا: ” تیری حاجت وضرورت ان کی حاجت سے بہتر ہے، جب تک کفار سے جہاد ہوتا رہے گا اس وقت تک ہجرت ختم نہیں ہو گی۔ حسان سے اسے ابوا در لیس ہی روایت کرتے ہیں۔","",{"k":"سنن نسائى (٤١٧٢)، قال الالباني صحیح۔","f":"مذکورہ روایت سے معلوم ہوا کہ بلاد کفر سے بلاد اسلام کی جانب ہجرت کا حکم اب بھی باقی ہے۔ اہل علم نے اس صورت میں ہجرت کو واجب قرار دیا ہے جب کفار کے علاقوں میں اسلام کے احکامات پر عمل کرنا مشکل ہو۔ ایک روایت میں ہے کہ نبی معظم ملنے کی تم نے فرمایا: ((لا هجرة بعد الفتح)) (صحیح بخاری، کتاب الجهاد، رقم: ٢٨٢٥) فتح (مکہ) کے بعد ہجرت نہیں لیکن جہاد اور نیت باقی ہے۔“ اس کا مطلب یہ ہے کہ ہجرت تو دارالکفر سے دار الاسلام کی طرف کی جاتی ہے لیکن اب جبکہ مکہ فتح ہو کر دار الاسلام بن گیا تو پھر دارالاسلام سے دار الاسلام کی طرف ہجرت نہیں، اگر اب کوئی مکہ سے مدینہ منتقل ہو گا تو اسے ہجرت کا ثواب نہیں ملے گا۔ ٦"}],[69,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ علیم نے فرمایا: ”جب تم میں سے کوئی شخص کسی آدمی کی طرف اپنا نیزہ سیدھا کرے، وہ نیزہ اس کے گلے کی ہڈی کے پاس پہنچ جائے اور وہ لا الہ الا اللہ کہہ دے تو بھی وہ اپنا نیزہ اس سے ہٹا لے۔“ مذکورہ روایت کمزور ہے تاہم اگر کوئی آدمی عین لڑائی میں مسلمان ہو جائے تو بھی اسے قتل نہیں کیا جائے گا۔","",{"k":"ضعيف الجامع الصغير (٤٠٩/٤، ١٣٨٧)، مجمع الزوائد (٢٥/١)۔"}],[70,"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ بے شک عیاض بن حمار نہشلی نے رسول اللہ صلی اللہ علیہ وسلم کو ایک گھوڑا بطور ہدیہ بھیجا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں مشرکین کا عطیہ نا پسند کرتا ہوں۔“ یہ دونوں حدیثیں سفیان سے صرف صلت بن عبدالرحمن روایت کرتے ہیں،سلیمان بن عبدالرحمن ان دونوں کو روایت کرنے میں اکیلے ہیں۔","",{"k":"تَفَرَّدَ بِهِمَا: سُلَيْمَانُ بْنُ عَبْدِ الرَّحْمَنِ . سنن ابو داؤد (٣٠٥٧)، قال الالبانی حسن صحیح، صحيح الجامع الصغير (٢٥٠٥)۔","f":"مذکورہ روایت سے معلوم ہوا کہ مشرکوں، کافروں سے ہدیہ نہیں لینا چاہیے۔ کیونکہ ہدیہ لینا، دینا دلوں میں قربت اور محبت پیدا کرتا ہے۔ اس لیے کافروں اور مشرکوں سے آزادانہ طور پر ہدیے کے تبادلے سے پر ہیز کرنا چاہیے۔ تاہم جہاں کوئی شرعی اور سیاسی مصلحت ہو تو ہدیہ لینے میں کوئی حرج نہیں۔ جیسا کہ امام بخاری وماللہ نے صحیح بخاری میں باب نقل فرمایا ہے: ((کتاب الهبة، باب قبول الهدية من المشركين)) سیدنا عیاض بن حمار فنی لینے سے ہدیہ قبول نہ کرنے کی وجہ یہ معلوم ہوتی ہے کہ انہیں اسلام لانے پر ابھارنا مقصود تھا۔ نبی معظم صلی اللہ علیہ وسلم نے اکیدر روم اور نجاشی کا ہدیہ قبول کیا ہے کیونکہ ان کے ایمان لانے کی قوی امید تھی۔ سیدنا عیاض رفضا اہلیہ نے بعد میں اسلام قبول کر لیا اور رسول اللہ صلی اللہ علیہ وسلم کی صحبت اختیار کی۔"}],[71,"\"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے ہاتھ اے علی کندھوں کے برابر بلند کرتے جب تکبیر تحریمہ کہتے اور رکوع کرتے اور جب سجدہ کرتے۔‘ ابن عجلان سے صرف مسلمہ ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (١١/١٤٥)۔"}],[72,"سیدنا ابو درداء رضی اللہ عنہ کہتے ہیں ” میں نے سیدہ عائشہ علی العلما سے رسول اللہ صلی اللہ علیہ وسلم کے اخلاق کے متعلق سوال کیا تو انہوں نے فرمایا: آپ کے اخلاق قرآن مجید تھے، اسی کے مطابق غضب ناک ہوتے اور اسی کے مطابق خوش ہوتے۔ حضرت ابوالدرداء، حضرت عائشہ سے صرف اس حدیث کو اسی سند کے ساتھ روایت کرتے ہیں، اسے روایت کرنے میں زید بن واقد ا کیلے ہیں۔","",{"k":"صحيح الجامع الصغير (٤٨١١)، المعجم الكبير للطبراني (٢/٢٥٥)۔","f":"ناندن خلق کا لفظی معنی وہ خصائل جو پیدائشی طور پر انسان میں پائی جائیں اور طبیعت میں پختہ ہو جائیں اور اس طرح عادت بن جائیں کہ بغیر سوچے سمجھے خود بخودسرزد ہوتی رہیں، خلق کہلاتی ہیں۔ عام طور پر خلق سے لوگوں سے اچھا برتاؤ کرنا اور انہیں خندہ پیشانی سے ملنا مراد لیا جاتا ہے اگر چہ خلق کے مفہوم میں یہ بھی شامل ہے مگر یہ خلق کا محدود مفہوم ہے۔ بقول سیدہ عائشہ بنا لیا وہ سب کچھ جو قرآن میں ہے، آپ سے بلا تکلف خود بخود عمل میں آتا تھا جیسے وہ آپ کی طبعی خصلت ہے۔ قرآن میں جو حکم دیا گیا اس پر آپ کا عمل تھا۔ جس سے منع کیا گیا اس سے مکمل اجتناب تھا۔ جو خو بیاں اختیار کرنے کی تلقین کی گئی آپ ان سے پوری طرح آراستہ تھے اور جن صفات کو نا پسندیدہ قرار دیا گیا۔ ان کے قریب بھی نہیں پھٹکتے تھے۔ الغرض آپ میں تمام انسانی خوبیاں جمع ہو گئی تھیں۔ SDRSD"}],[73,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی آدمی جوتا پہنے تو دائیں پاؤں سے شروع کرے اور جب اتارے تو بائیں پاؤں سے ابتدا کرے۔“ مذکورہ روایت میں جوتا پہنے اور اتارنے کے آداب کا تذکرہ ہے۔ وہ تمام کام جو زینت، عزت یا شرف کا باعث ہوں انہیں دائیں طرف سے شروع کرنا چاہیے۔ جیسا کہ سیدہ عائشہ بنی النا بیان کرتی ہیں کہ رسول اللہ ملے عام اپنے تمام کاموں میں جہاں تک ہوسکتا، دائیں جانب کو پسند فرماتے تھے، وضو کر نے لکھی کرنے اور جوتا پہنے ہیں۔ ٦* (صحیح بخاری، کتاب الوضوء، رقم: ١٦٨، صحيح مسلم، رقم: ٢٦٨) اس کی وجہ یہ ہے کہ دائیں جانب میں اللہ تعالیٰ نے زیادہ قوت اور صلاحیت رکھی ہے۔ جس کی وجہ سے دائیں جانب زیادہ تکریم کی حق دار ہے۔ جو کام اس کے برعکس ہیں ان کی بائیں طرف سے ابتدا کرنی چاہیے۔ مثلاً مسجد سے نکلنے اور بیت الخلا میں داخل ہوتے وقت بایاں پاؤں پہلے رکھے۔ کیونکہ جوتا پہننا باعث عزت و زینت ہے اس لیے دائیں پاؤں سے ابتدا کا حکم دیا اور جوتا اتارنے میں اس کا الٹ ہے۔ ٧٤","",{"k":"صحیح بخاری (٥٨٥٦)، سنن ابی داؤد (٤١٣٩)، سنن ترمذی (١٧٧٩)۔"}],[74,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ سے تم نے فرمایا: امام ( مقتدیوں کی نماز کا ) ضامن اور مؤذن امانت دار ہے۔ اے اللہ! اماموں کو ہدایت فرما اور اذان کہنے والوں کو معاف فرما دے۔“","",{"k":"سنن ابی داؤد (٥١٧)، قال الالباني صحیح، السنن الكبرى للبيهقي (١/٤٣٠)۔","f":"اندن مذکورہ روایت سے معلوم ہوا کہ مؤذن کے لیے ضروری ہے کہ وقت کی پابندی کرے۔ اور امام کو چاہیے کہ سنت کے مطابق نماز پڑھائے۔ دعاؤں میں اپنے مقتدیوں کو شامل رکھے اور صرف اپنے آپ ہی کو مخصوص نہ کرے۔ نبی معظم اللہ کریم نے امام کی فضیلت بیان کی ہے، شریعت نے اس کو عزت دی ہے، لہذا اس کو نمازوں کا خیال رکھنا چاہیے۔ (٢) اسی طرح مؤذن کا اذان دینا اعلان عام ہوتا ہے کہ نماز سحر یا افطار کا وقت ہو گیا ہے اس لیے لوگ اس پر اعتبار کرتے ہیں اور لوگوں کو اعتبار کرنا بھی چاہیے اور مؤذن کو چاہیے کہ اپنی ذمے داری کا خوب احساس کرے۔"}],[75,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے تطبیق کی۔ (رکوع میں ہاتھوں کو گھٹنوں کے درمیان رکھا) حماد بن ابی سلیمان سے صرف حماد بن سلمہ ہی اسے روایت کرتے ہیں اور حماد سے صرف ابراہیم بن حجاج ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (٨/٤١٠، ٩٨٧٨)۔","f":"مذکورہ روایت سے معلوم ہوا کہ شروع اسلام میں نبی علینام حالت رکوع میں اپنی ہتھیلیوں کو ایک دوسرے میں دے کر نماز پڑھتے تھے لیکن اب یہ منسوخ ہو چکا ہے۔ جیسا کہ سیدنا مصعب بن سعد رضی اللہ عنہ بیان کرتے ہیں کہ میں نے اپنے ابا جان (سیدنا سعد بن ابی وقاص رضای الیہ) کے پہلو میں نماز پڑھی، اور میں نے اپنے ہاتھوں کو (رکوع میں ) اپنے گھٹنوں کے درمیان رکھا تو انہوں نے مجھے اس سے منع فرمایا۔ میں نے پھر ویسے ہی کیا تو انہوں نے کہا: ایسے مت کرو۔ ہم (صحابہ کرام بی سی ) یہ کیا کرتے تھے مگر ہمیں اس سے روک دیا گیا اور حکم دیا گیا کہ ہم اپنے ہاتھوں کو گھٹنوں پر رکھا کریں۔ (صحیح بخاری، کتاب الاذان، رقم: ٧٩٠) ٧٦"}],[76,"سیدنا عبداللہ ابن عمر نے اپنا بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رات کی نماز دو دو رکعت ہے، تم جب صبح ہو جانے سے ڈرو تو ایک رکعت سے اس کو طاق بنا دو۔“ محمد بن عمرو سے صرف عباد بن عباد ہی اسے روایت کرتے ہیں، فضل بن زید سے روایت کرنے میں اکیلے ہیں۔","",{"k":"صحیح بخاری (٩٩٠)، سنن ابی داؤد (١٣٢٦)۔","f":"مذکورہ روایت سے معلوم ہوا کہ رات کی نماز دو دو رکعت ہے، اور آخر میں ایک رکعت وتر پڑھ لیا جائے۔اس سے ایک وتر کا جواز ہی نہیں اس کی فضلیت ثابت ہوتی ہے۔ تین وتر بھی پڑھنے ہوں تو افضل طریقہ یہ ہے کہ دو رکعت پر سلام پھیر دیا جائے اور پھر ایک رکعت بطور وتر پڑھی جائے۔ کیونکہ یہ نبی معظم طلئے علی ام سے ثابت ہے۔"}],[77,"سیدنا ابو ہریرہ نبی الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص کسی ایسی مجلس میں بیٹھے کہ جس میں شور شرابہ زیادہ ہو تو وہاں سے کھڑا ہونے سے پہلے یہ دعا پڑھ لے: ((سُبْحَانَكَ وَبِحَمْدِكَ لا إِلهَ إِلَّا أَنْتَ اسْتَغْفِرُكَ وَأَتُوبُ اِلَيْكَ)) یعنی اے اللہ! تو پاک ہے، اور ساتھ اپنی تعریف کے، تیر یبغیر کوئی عبادت کا مستحق نہیں میں تجھ سے بخشش مانگتا ہوں اور تیری طرف تو بہ کرتا ہوں، تو اس مجلس میں جو بھی گناہ ہوا ہو گا وہ معاف ہو جائے گا۔“ مذکورہ روایت سے معلوم ہوا کہ کفارہ مجلس کی دعا پڑھنا مسنون ہے۔ لغط، شور و غوغا کو کہتے ہیں۔ لیکن یہاں یہ لفظ بے","",{"k":"سنن ترمذی (٣٤٣٣)، صحيح الجامع الصغير (٦١٩٢)۔","f":"باتوں کے مفہوم میں استعمال ہوا ہے، یعنی ایسی باتیں جن سے آخرت میں کوئی فائدہ نہیں ہوگا۔ اس میں گناہوں کی مغفرت سے مراد صغیرہ گناہ ہیں کبیرہ گناہ اور حقوق العباد سے متعلقہ گناہ نہیں ہیں۔"}],[78,"سیدنا عمرو بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن شخص ایک سوراخ سے دو دفعہ نہیں ڈسا جاتا۔ کثیر سے اسے صرف حسینی ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٦١٣٣)، سنن الكبرى للبيهقي (٣٢٠/٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسلمان مومن کو ایک بار کسی چیز کا تجربہ ہو جاتا ہے، اس سے نقصان اٹھاتا ہے تو پھر دوبارہ دھوکہ نہیں کھاتا ہوشیار رہتا ہے۔ جیسا کہ سیدنا معاویہ بن سفیان رضی اللہ عنہ فرماتے ہیں: ((لا) حَكِيم الا ذو تَجْرِبَةٍ)) (تجربہ کار شخص ہی دانا ہوتا ہے )، ایک ہی بار دھوکا کھاتا ہے پھر ہوشیار رہتا ہے۔"}],[79,"سیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رات کی نماز دو دو رکعت ہے۔ “ حضرت عبداللہ بن عمر سے صرف حسینی ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ رات کی نماز دو دورکعتیں ہے۔ باقی رہا کہ دن کی نماز بھی دو دو رکعت ہے اس روایت کو امام نسائی ہواللہ نے خطا کہا ہے لیکن دیگر اہل علم کے نزدیک صحیح و ثابت ہے۔ اس لیے دن کے نوافل دو دو رکعت کر کے پڑھنے چاہئیں۔ لیکن نبی معظم نے نام سے ظہر یا عصر کے نوافل چار چار رکعت کی صورت میں پڑھنا بھی ثابت ہیں۔","",{"k":"سنن ابی داؤد (١٢٩٥)، قال الشيخ الالباني صحیح۔"}],[80,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” جب محرم نہ بند نہ پائے تو شلوار پہن لے۔ اور جس شخص کو جوتے نہ مل سکیں تو وہ موزے پہن لے۔“ یہ حدیث شیبانی سے صرف بیٹی بن عبدالملک بن ابی عقبہ اور ابو شہاب الحناط روایت کرتے ہیں۔","",{"k":"نسائی، رقم : ٢٦٧٢ . صحیح بخاری (٥٨٠٤)، سنن۔","f":"مذکورہ روایت سے معلوم ہوا کہ محرم شخص، مجبوری کی بنا پر شلوار اور موزے پہن سکتا ہے۔ ایک حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جس کے پاس جوتے نہ ہوں تو وہ موزے پہن لے،اور دونوں موزوں کو ٹخنوں کے نیچے سے کاٹ لے۔ (صحیح مسلم، کتاب الحج، رقم: ١١٧٧) چونکہ پہلی حدیث میں موزے کاٹنے کا تذکرہ نہیں ہے۔ اس لیے امام احمد ہماللہ فرماتے ہیں: موزے کاٹنے کی ضرورت نہیں ہے بغیر کاٹے بھی پہنے جا سکتے ہیں جبکہ جمہور علماء مطلق روایت کو مقید (دوسری) روایت کے ساتھ ملاتے ہیں اور کہتے ہیں کہ موزے کاٹنا ہی اولی ہے۔ امام ابن قدامہ اللہ نے بھی یہی وضاحت فرمائی ہے۔ (المغنی ابن قدامه: ١٢٢/٥) لیکن نہ کاٹنے والوں کا یہ موقف ہے کہ موزے کاٹنے کا حکم ابتدائے احرام کا تھا اور دوسرا حکم عرفہ کے دن کا ہے۔ (٢) جمہور علماء کہتے ہیں کہ شلوار کو بھی پھاڑ کر پہننا چاہیے۔ امام احمد جماللہ اور شافعیہ کے نزدیک شلوار کو پھاڑنے کی ضرورت نہیں کیونکہ حدیث میں ایسا کہیں ذکر موجود نہیں۔ یہی موقف راجح ہے۔"}],[81,"سيدنا ابو موسی اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ علیم نے فرمایا: قیامت کے دن لوگ جمع کیے جائیں گے تو ایک منادی کرنے والا یہ آواز لگائے گا: کیا یہ میری طرف سے انصاف نہیں کہ میں ہر قوم کے معبودوں کو ان کے والی مقرر کر دوں پھر ان کے معبود اٹھائے جائیں گے تو وہ ان کے پیچھے ہو لیں گے۔ یہاں تک کہ مومنوں کے علاوہ کوئی بھی نہ رہے گا تو انہیں کہا جائے گا: تمہارا کیا معاملہ ہے؟ وہ کہیں گے: ہم جس معبود کی عبادت کرتے رہے وہ دکھائی نہیں دے رہا۔ راوی کہتے ہیں: پھر اللہ تبارک و تعالیٰ ان پر جلوہ افروز ہوگا۔ یہ حدیث فرات بن سلیمان سے صرف ابو الیح الرقی ہی روایت کرتے ہیں۔ ساتھ ہوگا۔","",{"k":"مجمع الزوائد (١/٣٤٣)۔","f":"مذکورہ روایت کمزور ہے تاہم معلوم ہوا کہ قیامت کے دن ہر شخص اپنے اپنے معبود کے ٨٢"}],[82,"سیدنا عبد اللہ بن زبیر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر فرمایا: ”کون سا شہر زیادہ حرمت والا ہے؟“ کہا گیا: مکہ، پھر فرمایا: ”کون سا مہینہ بہت زیادہ حرمت والا ہے؟“ کہا گیا: ذوالحجہ ہے۔ پھر فرمایا: ”کون سا دن بہت زیادہ عزت والا ہے؟“ کہا گیا: نحر کا دن جو حج اکبر کا دن ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تمہارے خون اور تمہارے مال تم پر اپنے رب سے ملاقات کرنے کے وقت تک اسی طرح حرام ہیں جس طرح اس دن کی تمہارے اس مہینے میں تمہارے اس شہر کی طرح حرمت ہے۔ اس لیے میں یہ رائے نہیں رکھتا کہ اللہ تعالیٰ کے حرم میں کوئی خون بھی بہایا جائے۔ یہ حدیث فرات بن احنف سے مالک بن سعیر ہی روایت کرتے ہیں، اس کو روایت کرنے میں ابو عبیدہ اکیلے ہیں،حضرت ابن زبیر سے یہ حدیث صرف اسی سند سے مروی ہے۔","",{"k":"سنن الكبرى للبيهقى ٣ / ٢١٥، المعجم الكبير للطبراني (٣٨٦/١٨)۔","f":"مذکورہ روایت میں جو خطبہ مبارک ہے یہ خطبہ یوم النحر کے دن سنایا اور نبی معظم صلی اللہ علیہ وسلم نے لوگوں کو لڑائی جھگڑے سے منع کیا ہے۔ کیونکہ حج کا مقصد عظیم دنیائے اسلام کو اللہ کے خوف اور اتفاق کی دعوت دینا ہے اور اس کا بہترین موقع یہی خطبات ہیں۔ لہذا خطیب کا فرض ہے کہ مسائل حج کے ساتھ ساتھ وہ دنیائے اسلام کے مسائل پر روشنی ڈالے اور مسلمانوں کو کتاب وسنت کی پابندی اور باہمی اتفاق کی دعوت دے کہ حج کا یہی مقصود اعظم ہے، اور آپس میں فتنہ و فساد سے بچنے کی تلقین کرے۔ کیونکہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد کفر کی طرف نہ لوٹ جانا کہ ایک دوسرے کی گردن مارنے لگو بلا وجہ لڑ نا کفر، یعنی کافروں کا ساعمل ہے۔ (صحیح بخاری، الفتن، رقم: ٧٠٧٧)"}],[83,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ ان کا ایک بیٹا فوت ہو گیا تو رسول اللہ علیم نے ان کے بیٹے کے لیے تعزیت کا یہ مکتوب لکھا: ”بسم اللہ الرحمن الرحیم! محمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے معاذ بن جبل کے نام تجھ پر سلام ہو۔ میں اللہ کی نعمتوں پر اللہ کی حمد بیان کرتا ہوں اس کے بغیر کوئی معبود نہیں۔ حمد و صلاۃ کے بعد: اللہ تعالیٰ تیرے اجر و ثواب کو عظیم بنا دے اور تجھے صبر کرنا سکھا دے، اور ہمیں بھی اور تجھے بھی شکر کرنے کی توفیق عنایت فرمائے۔ کیونکہ ہماری جانیں، مال، اہل اور اولا دسب اللہ کے عمدہ عطیات اور مانگی ہوئی امانات میں سے ہیں۔ اللہ تعالیٰ تجھ کو خوش حالی اور مسرت کا","",{"k":"المعجم الكبير للطبرانی (١٥/٨٠، ١٦٧٤٠)، مجمع الزوائد (٣/٣)۔","f":"دے، اور جب تجھ سے واپس لے تو بہت زیادہ اجر دے کر لے۔ رحمت، مہربانی اور ہدایت دے۔ اگر تو اس کا اجر لینا چاہے تو صبر کر اور کہیں ایسا نہ ہو کہ تیری گھبراہٹ تیرے اجر کو ضائع کر دے تو تجھے ندامت اٹھانا پڑے۔ تجھے معلوم ہونا چاہیے کہ تیرا جزع فزع کرنا کسی فوت شدہ کو واپس نہیں کر سکتا اور نہ ہی غم کو ہٹا سکتا ہے اور جو چیز نازل ہونے والی ہوتو وہ گویا کہ واقع ہو چکی ہے اور تجھ پر سلام ہو۔“ یہ حدیث معاذ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں مجاشع اکیلے ہیں۔ مذکورہ روایت کمزور ہے۔ تاہم تعزیت کرنا، لوگوں کے غم میں شریک ہونا مسنون ہے، جیسا کہ حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جس نے اپنے مومن بھائی کی مصیبت میں اس سے تعزیت کی اللہ تعالیٰ اسے قیامت کے دن سبز حلہ پہنائے گا جس پر قیامت کے دن رشک کیا جائے گا۔“ احكام الجنائز للالباني، ص: ١٦٣)"}],[84,"سيدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فقیر مسلمان، غنی مسلمانوں سے پانچ سو سال پہلے جنت میں جائیں گے“ ہم نے پوچھا: یا رسول اللہ! لے تم! وہ کون لوگ ہیں؟ آپ نے فرمایا: وہ ایسے لوگ ہیں کہ جہاں ہلاکت اور موت ہو تو انہیں بھیج دیا جائے، اور جہاں مال غنیمت ہو وہاں ان کے علاوہ اور لوگوں کو بھیجا جائے جن کو دروازوں سے دور رکھا جائے۔“ یہ حدیث شعبہ سے صرف ابوسعید ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ غریب مسلمان امیروں سے پانچ سوسال پہلے جنت میں جائیں گے کیونکہ دنیا میں کم نعمتیں ہونے کی وجہ سے ان کا حساب بھی مختصر ہوگا جب کہ امراء دنیوی نعمتوں کے طویل حساب سے گزریں گے جس کی وجہ سے وہ غرباء کے بعد جنت میں جائیں گے۔","",{"k":"٢٦٠ مجمع الزوائد: ١٠ / ٢٦٠ . ١٠۔"}],[85,"ا سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے روزے کی حالت میں صبح کی، پھر بھول کر کچھ کھا، پی لیا تو یہ اسے اللہ تعالیٰ نے کھلایا اور پلایا ہے (اس لیے وہ اس روزے کی قضا یا کفارہ نہ دے)۔ لیث بن سعد سے اسے صرف ان کے بیٹے شعیب ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ روزے کی حالت میں بھول کر کھا، پی لینے سے روزہ نہیں ٹوٹتا، اور نہ ہی ایسے شخص پر کوئی قضا یا کفارہ لازم آتا ہے جمہور علماء اسی کے قائل ہیں۔ (نیل الاوطار: ١٧٨/٣) شیخ ابن عثیمین جاللہ اور سعودی مستقل فتوی کمیٹی نے بھی یہی فتویٰ دیا ہے۔ (فتاوی اسلامیه: ١٢٨/٢، فتاوى اللجنة: ٢٦٩/١٠) امام مالک رحمہ اللہ نے کہا ہے کہ بھول کر کھانے والے کا بھی روزہ باطل ہو جاتا ہے، اور اس کے ذمہ قضا لازم ہوتی ہے۔ (المغنی ابن قدامه: ٣٢٧/٤) یہ مؤقف مذکورہ بالا صحیح اور صریح حدیث کے خلاف ہونے کی بنا پر درست نہیں","",{"k":"كر المعجم الكبير للطبراني (١٠١/١٩)۔"}],[86,"سیدنا ابو ہریرہ بنی الیہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے ہاشم کی اولاد! اے عبد المطلب کی اولاد! اے صفیہ رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی! اے فاطمہ رسول اللہ صلی اللہ علیہ وسلم کی بیٹی! میں یہ بات معلوم نہ کروں کہ لوگ تو آخرت کو اٹھائے ہوئے آئیں اور تم دنیا کو اٹھائے ہوئے آؤ۔ میرے دوست تم میں سے قیامت کے روز متقی اور پر ہیز گار لوگ ہوں گے۔ بے شک میری مثال تم میں سے اس شخص جیسی ہے جسے اپنی قوم کا خیر خواہ خیال کیا جاتا ہے وہ ان کے پاس آیا تو کہنے لگا: اے میری قوم تمہارا دشمن آ گیا تم دشمن سے ڈھانپ لیے گئے ہو، تمہاری صبح نہیں ہوگی۔ میں تو تمہیں ڈرانے والا ہوں اور موت تمہیں لوٹانے والی ٢ مجم اوسط طبرانی ١ من pers plängere اور قیامت کے روز کا تم سے وعدہ ہے۔ زہرہ بن معبد سے اس کو صرف نافع بن یزید اور نافع سے صرف عثمان بن کلیب روایت کرتے ہیں، اسے روایت کرنے میں زکریا بن بیٹی الوقارا کیلے ہیں۔","",{"k":"المعجم الكبير للطبراني: ١٠٢/١٩ رانی (١٩/١٠٢)، مجمع الزوائد (١/٢٢٨)۔","f":"مذکورہ روایت کمزور ہے۔ تاہم صحیح روایت میں ہے کہ نبی معظم تم نے اپنے خاندان والوں کو تو حید کی دعوت کے ساتھ ساتھ تقویٰ اور نیکی اختیار کرنے کا حکم دیا ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”اے عبد مناف کے بیٹو! اپنی جانوں کو اللہ سے خرید لو ( یعنی نیک کام کر کے انہیں اللہ تعالیٰ کے عذاب سے بچا لو ) اے عبد المطلب کے بیٹو! اپنی جانوں کو اللہ تعالیٰ سے خرید لو۔ اے زبیر بن عوام کی والدہ رسول اللہ سے سیم کی پھوپھی! اے فاطمہ بنت محمد! تم دونوں اپنی جانوں کو اللہ سے بچالو، میں تمہارے لیے اللہ کی بارگاہ میں کچھ اختیار نہیں رکھتا۔ تم دونوں میرے مال میں جتنا چاہو مانگ سکتی ہو۔“ (صحیح بخاری، کتاب المناقب، رقم: ٣٥٢٧)"}],[87,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: دستم ملاقات ناغہ کر کے کیا کرو اس طرح آپس میں تمہاری محبت میں اضافہ ہو گا۔“ اسے حضرت نافع سے صرف یزید بن ابی حبیب اور یزید سے صرف ابن لہیعہ روایت کرتے ہیں، اسے روایت کرنے میں روح بن صلاح اکیلے ہیں۔ معلوم ہوا کہ دوستوں سے ملاقات وقفہ ڈال کر کرنی چاہیے کیونکہ یہ محبت میں اضافے کا فائد باعث ہے۔ ٨","",{"k":"المعجم الكبير للطبراني (١٤٦/١١)۔"}],[88,"سیدنا حذیفہ بن یمان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” عنقریب تم پر ایسا وقت آئے گا کہ جس میں تین چیزوں سے زیادہ عزت کسی چیز کی نہ ہوگی (١) حلال درہم (٢) وہ بھائی جس سے مانوس ہوا جائے (٣) وہ سنت جس پر عمل کیا جائے۔“‘سفیان سے اس حدیث کو صرف روح بن صلاح ہی روایت کرتے ہیں۔","",{"k":"ضعيف الجامع الصغير (٢٣٩٦)، مجمع الزوائد (١/١٧٢)۔"}],[89,"سیدنا معاذ بن جبل رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آدمی جس عورت کا بطور نکاح مالک نہیں اس کی طلاق کا کوئی اعتبار نہیں۔ اسی طرح جس غلام کا آدمی مالک نہ ہو اس کے آزاد کرنے کا بھی کوئی اعتبار نہیں۔“","",{"k":"السنن الكبرى للبيهقي (٣١٩/٧)، ارواء الغليل: ٦/ ١٧٤ قال الالباني۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جو طلاق کا مالک نہیں وہ طلاق نہیں دے سکتا۔ ()) اس کی ایک صورت یہ ہو سکتی ہے کہ کوئی شخص کہے: فلاں کی بیوی کو طلاق یا باپ کہے کہ میں بیٹے کی بیوی کو طلاق دیتا ہوں یہ طلاق نہیں ہوگی کیونکہ اس کے پاس اختیار نہیں۔ (٢) یا آدمی یہ کہے کہ جب میری شادی ہوگی میری بیوی کو طلاق، اس طرح بھی طلاق واقع نہیں ہو گی۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: (( لا طلاق الا بعد نكاح )) ”طلاق صرف نکاح کے بعد ہی ہوتی ہے۔ (حاکم: ٢٠٤/٢) (٣) جس کے پاس اختیار نہ ہو اس کی آزادی کا بھی کوئی اعتبار نہیں مثلاً کوئی آدمی کسی کے غلام کے متعلق کہے کہ میں تجھے آزاد کرتا ہوں وہ آزاد نہیں ہو گا، ہاں اگر اس نے اختیار دیا ہے کہ میرے فلاں غلام کو یا میرے غلاموں میں سے کسی ایک کو آزاد کر دے تو تب وہ آزاد ہو جائے گا۔"}],[90,"سیدنا جابر بن عبد اللہ ہی یہ کہتے ہیں ”ہم میں سے ایک شخص نے ایک غلام آزاد کیا۔ جس کا اس کے علاوہ اور کوئی مال بھی نہ تھا تو رسول اللہ صلی اللہ علیہ وسلم نے اس کو دوبارہ غلامی میں واپس کر دیا، پھر اسے بیچ ڈالا۔“ مذکورہ روایت سے معلوم ہوا کہ اگر آدمی خود ضرورت مند ہے تو بہتر یہ ہے کہ پیسے اپنے او پر خرچ کرے۔ جیسا کہ نبی معظم ماے علی تم نے اس غلام کو فروخت کرنے کا حکم دیا۔ اسی طرح ایک اور روایت میں ہے کہ ایک آدمی نے اپنا ایک غلام مرتے وقت آزاد کر دیا، پھر وہ محتاج ہو گیا تو رسول اللہ سے ہم نے اس (غلام کو ) پکڑا اور فرمایا: ”مجھ سے کون اسے خریدے گا؟ پھر نعیم بن عبد اللہ فی الین نے کچھ قیمت (٨٠٠ درہم) کے عوض اسے خرید لیا تو آپ ملنے کی ایم نے یہ رقم اس آدمی کے حوالے کی اور فرمایا: ” جب تم میں سے کوئی ضرورت مند ہو تو چاہیے کہ (خرچ کرنے کی ) ابتدا اپنے سے کرے، اگر کچھ بیچ جائے تو اپنے عیال پر خرچ کرے۔ اگر ان سے بیچ رہے تو اپنے قرابت داروں پر خرچ کرے۔ (سنن ابو داؤد، کتاب العتق، رقم: ٣٩٥٩)","",{"k":"السنن الكبرى للبيهقي (٣١٣/١٠)۔"}],[91,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما یہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ میمونہ صلی اللها سے احرام کی حالت میں نکاح کیا۔ (١) ایک حدیث میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” محرم نکاح کر سکتا ہے نہ نکاح کرا سکتا ہے اور نہ ہی نکاح کا پیغام بھیج سکتا ہے۔ (صحیح مسلم، كتاب النكاح رقم: ١٤٠٩، سنن ابو داؤد، رقم: ١٨٤١) (٢) مذکورہ بالا روایت جس میں یہ ہے کہ نکاح کیا، اہل علم نے اسے سیدنا عبد اللہ بن عباس رضی اللہ عنہما کا وہم قرار دیا ہے جیسا کہ سیدنا سعید بن مسیب جماللہ نے فرمایا ہے کہ سیدنا عبداللہ ابن عباس رضی اللہ عنہما کو وہم ہوا ہے کہ نبی صلی اللہ علیہ وسلم نے حالت احرام میں سیدہ میمونہ بنی اٹھا سے شادی کی تھی۔ (صحیح سنن ابو داؤد، رقم: ١٦٢٨) بلکہ سیدہ میمونہ علی البا خود بیان فرماتی ہیں کہ رسول اللہ لئے علیم نے مجھ سے شادی کی تو اس وقت ہم دونوں سرف مقام پر حلال ( یعنی حالت احرام میں نہیں ) تھے۔ (صحیح سنن ابو داؤد، رقم: ١٦٢٦) معلوم ہوا کہ نبی مکرم سے یمن کی شادی احرام کی حالت میں ہوئی نہ ہی کسی کے لیے احرام کی حالت میں شادی کروانا جائز ہے۔ جمہور اسی کے قائل ہیں۔ جبکہ احناف نے محرم کے لیے شادی کو جائز قرار دیا ہے۔ (شرح المهذب: ٢٩٦/٧، فتح البارى: ٥٢٨/٤) بلا شبہ جمہور کا مؤقف ہی حق ہے، امام شوکانی اللہ اور علامہ عبد الرحمان مبارکپوری اللہ نے بھی اسی کو ترجیح دی ہے۔ نیل الاوطار: ٣٥٨/٣، تحفة الاحوذى: ٦٨٠/٣)","",{"k":"المعجم الصغير للطبرانی (١/١٠٢، ٩٩)، سنن نسائی (٣٢٧٣)۔"}],[92,"سیدنا عبداللہ ابن عباس کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم مردوں کے ذریعے زندوں کو تکلیف نہ دو۔“","",{"k":"المعجم الكبير للطبراني (٤٧٠)، مجمع الزوائد (٧٦/٨)۔","f":"مذکورہ روایت کمزور ہے تا ہم ایک صحیح حدیث میں ہے رسول اللہ میم نے فرمایا: \" مردوں کو گالی مت دو کیونکہ ایسا کرنے سے تم زندوں کو ایذا دو گے۔“ (سنن ترمذی، رقم: ١٩٨٢، سلسلة صحيحة، رقم: ٢٣٩٧) مطلب یہ ہے کہ جب مردوں کو گالی دو گے تو جو ان کے زندہ عزیز و اقارب ہیں وہ تکلیف محسوس کریں گے۔"}],[93,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ طلع علم روزے کی حالت میں بوسہ لے لیا کرتے تھے۔“ یہ (٨٩ تا ٩٣) احادیث حضرت سعید بن ابی ایوب سے صرف روح بن صلاح ہی روایت کرتے ہیں۔ ایک حدیث میں ہے سیدہ عائشہ منی اینجا بیان کرتی ہیں کہ نبی مکرم سے بحالت روزہ اپنی ازواج کا بوسہ لیتے اور جسم سے جسم بھی ملا لیتے تھے، لیکن آپ ملے لیتی تم میں سب سے زیادہ اپنی خواہش پر قابو پانے والے تھے۔ (صحیح بخاری، کتاب الصوم، رقم: ١٩٢٧، صحیح مسلم، رقم: ١١٠٦) معلوم ہوا کہ آدمی حالت روزہ میں اپنی بیوی کا بوسہ لے سکتا ہے لیکن اپنے نفس پر قابو پا سکتا ہو تو درست ہے۔ اگر آدمی اپنے نفس پر قابو نہ پاسکتا ہو تو اس کے لیے درست نہیں ہے۔","",{"k":"صحیح مسلم (١١٠٦/٧٢)، سنن ابو داؤد (٢٣٨٢)۔"}],[94,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب سورج مغرب سے طلوع ہوگا تو ابلیس سجدے میں گر پڑے گا۔ آواز دے گا: اے میرے اللہ! تو جس کے متعلق چاہتا ہے اس کے لیے سجدہ کرنے کا مجھے حکم دے تو اس کے سپاہی اس کے پاس جمع ہو کر اس سے پوچھیں گے: اے ان کے سردار! یہ کیا آہ وزاری ہے؟ تو وہ کہے گا: میں نے اپنے رب سے معلوم وقت تک مہلت دینے کا سوال کیا تھا اور یہ وقت معلوم ہے۔ پھر صفا پہاڑی کے ایک شگاف سے دابتہ الارض نکلے گا تو پہلا قدم وہ انطاکیہ شہر میں رکھے گا۔ پھر ابلیس آئے گا تو وہ ابلیس کو تھپڑ مارے گا۔ عبداللہ بن عمرو سے یہ حدیث صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عثمان بن سعید ا کیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (٩٠/٢٠)۔","f":"مذکورہ روایت کمزور ہے تاہم سورج کا مغرب کی جانب سے طلوع ہونا اور توبہ کا دروازہ بند ہو جانا صحیح روایات سے ثابت ہے۔ اسی طرح دابتہ الارض کا نکلنا بھی برحق ہے۔"}],[95,"سیدنا ابو ہریرہ ضیا المیہ نے بیان کیا: رسول اللہ صلی اللہ علیہ وسلم نے ایک دن (بارش کی وجہ سے) کیچڑ میں سجدہ کیا یہاں تک میں آپ کی پیشانی اور ناک پر اس کا نشان دیکھ رہا ہوں۔‘ اوزاعی سے یہ حدیث صرف سوید ہی روایت کرتے ہیں، اسے روایت کرنے میں زہیر بن عباد کیلے ہیں۔ مذکوره روایت سے معلوم ہوا کہ سجدے میں ناک اور پیشانی کو زمین پر رکھنا مسنون ہے۔ سجدے میں انسان کی پیشانی تنگی ہو اور براہ راست زمین یا مصلے پر لگے تو راج اور افضل ہے۔ نبی صلی اللہ علیہ وسلم کا اپنی پگڑی کی پٹی یا تہ پر سجدہ کرنا ثابت نہیں ہے۔ مگر کچھ صحابہ کرام بھی ایم کے آثار سے ضرور ثابت ہے۔ .:٩٦ (نيل الاوطار: ٢٩٠/٢)","",{"k":"المعجم الكبير للطبرانی (١٠٢/١٩)۔"}],[96,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے وہ اس کو نبی صلی اللہ علیہ وسلم تک پہنچاتے ہیں، آپ نے فرمایا: ”جس شخص نے دنیا میں اپنی اولاد کو قرآن کی تعلیم دی تو اس تعلیم قرآن کی وجہ سے اس کا رب قیامت کے روز جنت میں اسے ایسا تاج پہنائے گا کہ تمام اہل جنت اس کو پہچانیں گے۔“ اس حدیث کو عباد بن ابی صالح سے صرف حضرت جابر بن سلیم ہی روایت کرتے ہیں، اسے روایت کرنے میں موسیٰ اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم صحیح روایت میں ہے نبی مکرم ملے ہم نے فرمایا: ” قاری کے والدین کو دو قیمتی لباس پہنائے جائیں گے جس کے مقابلے میں دنیا و مافیہا کی ساری دولت بیچ ہوگی۔ قاری کے والدین عرض کریں گے: اے رب! ہماری یہ عزت افزائی کس عمل کے بدلے میں ہوئی ہے؟ انہیں جواب دیا جائے گا: اپنے بیٹے کو قرآن مجید پڑھانے کے بدلے میں۔ (سلسلة صحيحه، رقم: ٢٨٢٩) معلوم ہوا جو اپنی اولاد کو قرآن مجید کی تعلیم دلواتا ہے قیامت کے دن اس کے والدین کو قیمتی لباس پہنائے جائیں گے۔","",{"k":"المعجم الكبير للطبراني (١٠٣/١٩)، مجمع الزوائد: ١٦٦/٧ . ١٩۔"}],[97,"\" سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے صحابہ کرام نبی ایم جب آپس میں ملاقات کرنے تو مصافحہ کرتے اور جب سفر سے واپس آتے تو ایک دوسرے سے گلے ملتے تھے۔“ یہ حدیث شعبہ سے عبد السلام بن حرب ہی روایت کرتے ہیں، اسے روایت کرنے میں بیچی الجعفی اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ ملاقات کے وقت مصافحہ کرنا چاہیے۔ سیدنا انس نبی الیہ کے متعلق آتا ہے کہ وہ روزانہ صبح کو اپنے ہاتھوں کو مصافحہ کے لیے خوشبودار تیل لگایا کرتے تھے۔ .:٩٨ ( ادب المفرد، رقم: ١٠١٢)","",{"k":"السلسلة الصحيحه (١/١٥٩)، رقم۔"}],[98,"سیدنا ابو ہریرہ بنی یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میرے گھر اور میرے منبر کے درمیان جنت کے باغوں میں سے ایک باغ ہے۔“ یہ حدیث عبداللہ سے صرف عبدالرحمن بن اشرس ہی روایت کرتے ہیں۔ مانده مذکوره روایت سے مدینہ منورہ کی فضیلت کا اثبات ہے خاص طور پر حجرہ اور منبر کے درمیانی جگہ کی گھر سے مراد، سیدہ عائشہ نبیل اللہ کا حجرہ ہے جہاں آپ آرام فرما ہیں۔ ابن عساکر کی روایت میں یوں ہے کہ میری قبر کے درمیان اور منبر کے درمیان جنت کی کیاریوں میں سے ایک کیاری ہے۔ اور طبرانی میں سیدنا عبداللہ بن عمر رضی اللہ عنہما سے مروی روایت میں بھی قبر کا لفظ ہے۔ اللہ تعالیٰ نے آپ کو پہلے ہی آگاہ فرما دیا تھا کہ آپ اس حجرہ میں قیامت تک آرام فرمائیں گے۔ بیان کردہ قطعہ حقیقتاً جنت کا ایک ٹکڑا ہے۔ بعض نے کہا: اس کی برکت اور خوبی کی وجہ سے مجازاً ایسے کہا گیا یا اس لیے کہ وہاں عبادت کرنا خصوصی طور پر دخول جنت کا ذریعہ ہے۔ منبر کے بارے میں جو فرمایا قدرت خداوندی سے یہ بھی بعید نہیں کہ قیامت کے دن حوض کوثر پر اس منبر کو دوبارہ مہیا کر کے آپ صلی اللہ علیہ وسلم کے لیے رکھ دیا جائے۔ (فتح البارى: ١٢٥،١٢٤/٤)","",{"k":"صحیح بخاری (١٨٨٨)، سنن ترمذی (٣٩١٥)۔"}],[99,"سیدنا ولید بن عقبہ ضیا المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اہل جنت کے کچھ لوگ اہل جہنم کے کچھ لوگوں کی طرف جھانک کر دیکھیں گے تو پوچھیں گے کہ تم جہنم میں چلے گئے ہو؟ اللہ کی قسم! ہم تو جنت میں اس چیز کی بنا پر داخل ہوئے ہیں جو تم سے سیکھی تھی تو وہ کہیں گے ہم جو کچھ کہتے تھے اس کے مطابق عمل نہیں کرتے تھے۔ یہ حدیث اسماعیل بن ابی خالد سے صرف ابوبکر الداھری ہی روایت کرتے ہیں۔ مذکورہ روایت کمزور ہے تاہم داعی الی اللہ کو چاہیے کہ جن اعمال کی طرف لوگوں کو دعوت دے ان پر خود عمل کرتا ہو۔ دائی جو کہے اس کے مطابق عمل نہ کرے تو یہ اللہ تعالیٰ کی ناراضی کا سبب ہے۔ جیسا کہ ارشاد باری تعالی ہے: يَأَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ كَبُرَ مَقْتًا عِنْدَ اللهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ﴾ (الصف: ٢تا٣) ”اے ایمان والو! تم ایسی بات کیوں کہتے ہو جس پر خود عمل نہیں کرتے ہو۔ یہ بات اللہ کو بہت ہی زیادہ ناپسند ہے کہ تم وہ بات کہو جس پر خود عمل نہیں کرتے۔“ ١٠٠","",{"k":"السلسلة الضعيفة (٣/٢٦٧، ١٢٦٨)۔"}],[100,"سیدنا انس رضی اللہ عنہ سے روایت ہے ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے عرض کیا، میرا باپ مر گیا ہے، اور اس نے حج نہیں کیا میں اس کی طرف سے حج کرسکتا ہوں؟ آپ نے فرمایا: ” یہ بتاؤ! اگر تمہارے باپ کے ذمہ کوئی قرض ہو اور تم اس کو ادا کر دو تو کیا وہ ادا ہو جائے گا؟“ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ”اپنے باپ کی طرف سے حج کرو۔ حضرت ثابت سے اسے صرف عباد ہی روایت کرتے ہیں، اسے روایت کرنے میں ابوسعیدا کیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ میت کی طرف سے حج کیا جاسکتا ہے۔ جمہور علماء اور امام شافعی فرماتے ہیں میت کی طرف سے حج کیا جا سکتا ہے خواہ حج فرض ہو یا نفل۔ (تحفۃ الاحوذی: ٨٠٧/٣) نده شیخ الاسلام ابن تیمیہ جملہ نے فرمایا ہے کہ میت کی طرف سے بالا تفاق حج درست ہے۔ (مجموع الفتاوى: ٩/٢٦) شیخ ابن باز اللہ نے بھی یہی فتویٰ دیا ہے۔ علاوہ ازیں اہل علم حجیت قیاس کے دلائل میں اس حدیث کو بھی پیش کرتے ہیں کیونکہ آپ صلی اللہ علیہ وسلم نے اس میں اللہ کے حق کو اللہ کے غیر کے حق پر وجوب ادا ئیگی میں قیاس کیا ہے۔ عورت مرد کی طرف سے اور مرد عورت کی طرف سے حج کر سکتے ہیں شیخ الاسلام ابن تیمیہ، ابن قدامہ، ابن باز تیم اسی کے قائل ہیں۔ (الاخبار العلمية: ص - المغنى ابن قدامه: ٢٧/٥، مجموع الفتاوى لابن باز: ٤٢٢/١٦) -٠/","",{"k":"المعجم الكبير للطبراني (١/٣١٣)۔"}],[101,"سیدنا جابر بھی اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ارشاد فرمایا: ”گناہ پر شرمندگی مانده مذکورہ روایت سے معلوم ہوا تو یہ یہ ہے کہ آدمی سے گناہ ہو جائے تو اس پر شرمندہ ہو۔ علماء نے کہا ہے کہ تو بہ ہر گناہ سے واجب ہے۔ اگر گناہ کا تعلق اللہ سے ہے، کسی آدمی کا حق اس سے متعلق نہیں تو ایسے گناہ سے توبہ کی قبولیت کے لیے ) تین شرطیں ہیں: پہلی یہ کہ اس گناہ کو چھوڑ دے (جس سے وہ تو بہ کر رہا ہے ) (٢) یہ کہ اپنے اس فعل (گناہ) پر نادم ہو (٣) یہ کہ وہ پختہ ارادہ کرے کہ آئندہ کبھی یہ گناہ نہیں کرے گا۔ اگر تین شرطوں میں سے ایک بھی شرط مفقود ہوگی تو تو بہ صحیح نہیں ہوگی۔ اگر اس گناہ کا تعلق کسی آدمی سے ہے تو اس کے لیے چار شرطیں ہیں۔ تین تو مذکورہ بالا ہیں اور چوتھی یہ کہ وہ صاحب حق کا حق ادا کرے۔ اگر کسی کا مال یا کسی قسم کی کوئی چیز ناجائز طریقے سے لی ہو تو اسے واپس کرے اگر تہمت لگائی تو اس کی حدا اپنے نفس پر لگائے یا اس سے معافی طلب کر کے اس کو راضی کرے۔","",{"k":"صحيح الجامع (٦٨٠٢)، سنن الكبرى للبيهقي (١٠/١٥٤)۔"}],[102,"سیدنا ابو ہریرہ نی اہلیہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بعض گناہ ایسے ہیں جن کا کفارہ نماز، روزہ، حج اور عمرہ نہیں بن سکتے۔ صحابہ نے عرض کیا: پھر کون سی چیز ان کا کفارہ بن سکتی ہے؟ آپ نے فرمایا: گزران کی طلب میں غم اور فکر مالک سے اسے صرف یحیی بن بکیر ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن سلام اکیلے ہیں۔ احمد بن یحیی فرماتے ہیں: میں نے کہا کہ ابن بکیر نے کیسے سن لیا حالانکہ انہوں نے آپ کے علاوہ کسی اور سے نہیں سنا؟ تو فرمایا: میں ابن بکیر کے پاس بیٹھا ہوا تھا تو اس کے بعد ایک آدمی آیا، اس کی حالت ضعف کا ذکر ہوا، سو ابن بکیر نے فرمایا: ہم کو مالک نے بیان کیا اور یہ حدیث ذکر کی (جو او پر مذکور ہوئی ہے)۔ السلسلة الضعيفة: ٢/ ٤٢٥، رقم: ٩٢٦، ضعيف الجامع، رقم:",""],[103,"سیدہ فاطمہ بنی النہا سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے عقیق کی انگوٹھی پہنی وہ ہمیشہ خیر اور بھلائی ہی دیکھے گا۔“ یہ حدیث مالک سے ابوبکر بن شعیب ہی روایت کرتے ہیں، اسے روایت کرنے میں زہیر بن عباد کیلئے ہیں۔","",{"k":"السلسلة الضعيفة (١/٣٠٧، ٢٣٠)، الموضوعات لابن الجوزى ابن الجوزي (١/٥٧)۔"}],[104,"سیدنا عبد اللہ بن حکیم بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے یہ لکھا جبکہ ہم جہینہ کی سرزمین میں تھے کہ: ”میں نے تمہیں مردار کے چمڑے (کے استعمال ) کی رخصت دی تھی۔ مگر آئندہ مردار کے چمڑے اور پٹھے سے نفع حاصل نہ کرو۔“ ابوسعید بصری سے اسے صرف یحیی بن ایوب ہی روایت کرتے ہیں، فضالہ بن مفضل اپنے والد سے اسے روایت کرنے میں اکیلے ہیں۔","",{"k":"السلسلة الصحيحة (٦/٣١١، ٢٨١٢.٣١١/٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مردار کے چمڑے سے فائدہ نہیں اٹھانا چاہیے لیکن یہ اس وقت ہے جب رنگے بغیر استعمال کیا جائے رنگنے کے بعد چمڑے کے استعمال کی رخصت ہے جیسا کہ نبی معظم لم نے فرمایا: (( أيما اهاب دبغ فقد طهر )) ( جس چمڑے کو رنگ دیا جائے وہ پاک ہو جاتا ہے۔“ (صحیح سنن ابن ماجه كتاب اللباس، رقم: ٢٩٠٧) معلوم ہوا کہ رنگنے سے پہلے چمڑا نجس ہوتا ہے۔ مالکیہ، حنابلہ، شافعیہ، حنفیہ یہی موقف رکھتے ہیں۔ (بداية المجتهد: ٧٦/١) امام شوکانی جماللہ بھی اسی کو ترجیح دیتے ہیں۔ (السيل الجرار: ٤٠/١)"}],[105,"سیدہ عائشہ علی الشیا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” سیاہ دانے (کلونجی ) میں موت کے سوا ہر بیماری کی شفا ہے۔ یہ حدیث جو ابی بکر، حضرت عائشہ سے روایت کرتے ہیں، صرف اسی سند سے روایت کی گئی ہے، اسے روایت کرنے میں عبید اللہ بن موسیٰ اکیلے ہیں۔ (١) مذکورہ روایت سے معلوم ہوا کہ بیماری کے لیے علاج کروانا جائز ہے یہ توکل کے خلاف نہیں۔ (٢) اللہ نے کلونجی میں شفا رکھی ہے۔ کلونجی پھوڑے پھنسیوں میں بہت مفید ہے۔ ازواج مطہرات میں سے کسی ایک کی انگلی میں پھنسی نکلی ہوئی تھی تو نبی معظم ماے کرام نے پوچھا: ” کیا تمہارے پاس کلونجی ہے؟ تو انہوں نے کہا: ہاں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” کہ اس پر کلونجی رکھ۔ موت کا اپنے وقت مقرر پر آنا ضروری ہے اس لیے اس کی کوئی دوا نہیں۔ انسان کچھ تدبیر کرے، لاکھ دوائیاں استعمال کرے، کتنا ہی سرمایہ دار کثیر الوسائل ہو مگر کوئی چیز ایسی نہیں جو موت کو ٹال سکے، کیوں کہ قانونِ الہی ہے: ﴿ كُلُّ نَفْسٌ ذَائِقَةُ الْمَوْتِ ہر نفس نے موت کا ذائقہ چکھنا ہے","",{"k":"صحیح بخاری، رقم : ٥٦٨٧ سنن ابن ماجة (٣٤٤٧)۔"}],[106,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی صلی اللہ علیہ وسلم، سیدنا ابو بکر اور سیدنا عمر نیا اینجا کو جنازے کے آگے آگے چلتے ہوئے دیکھا۔ یہ حدیث بکر بن مضر سے صرف محمد بن سفیان ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ جنازے کے آگے چلنا جائز ہے۔ اسی طرح سیدنا مغیرہ","",{"k":"سنن ابن ماجه (١٤٨٢)، قال الالبانی صحیح۔","f":"بن شعبہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” پیدل چلنے والا جنازے کے پیچھے، اس سے آگے، اس کے دائیں اور اس کے بائیں، اس کے قریب ہو کر چل سکتا ہے۔“ (صحیح ابو داؤد، کتاب الجنائز، رقم: ٢٧٢٣) اختلاف اس میں ہے کہ پیچھے چلنا افضل ہے یا آگے؟ جمہور، احمد، مالک، شافعی میہ کے نزدیک جنازے کے آگے چلنا افضل ہے۔ سیدنا ابو بکر، عمر، عثمان، ابن عمر، ابو ہریرہ بیٹی ایم اسی کے قائل ہیں۔ ابو حنیفہ اللہ کے نزدیک جنازے کے پیچھے چلنا افضل ہے۔ سیدنا علی بنی اہلیہ سے بھی یہی موقف ثابت ہے۔ (نیل الاوطار: ١٨/٣ كتاب الام: ٤٥٥/١) ابن حزم جماللہ فرماتے ہیں: پیدل چلنے والا جہاں چاہے چلے لیکن ہمارے نزدیک پسندیدہ پیچھے چلنا ہی ہے۔ (المحلى بالاثار: ٣٩٣/٣ امام شوکانی براللہ فرماتے ہیں: سوار جنازے سے پیچھے اور پیدل چلنے والا آگے چلے۔ (نیل الاوطار: ١٨/٣) شیخ البانی اللہ کے نزدیک پیچھے چلنا افضل ہے کیونکہ رسول اللہ علیم نے فرمایا: ((واتبعوا الجنائز)) جنازوں کے پیچھے چلو‘ (احکام الجنائز: ص ٩٦)"}],[107,"سیدنا ابو قتادہ فی اللہ نے بیان کیا: ایک شخص نبی سے کام کے پاس آیا تو آپ سے قیامت کے متعلق پوچھنے لگا: تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تو نے اس کے لیے کیا تیاری کر رکھی ہے؟ وہ کہنے لگا: اللہ تعالیٰ اور اس کے رسول ملے تعلیم کی محبت (میرے پاس موجود ہے )۔ آپ نے فرمایا: \" تم قیامت کے دن اس شخص کے ساتھ ہو گے جس سے محبت کرتے ہو۔“ یہ حدیث ابو قتادہ سے صرف اسی سند سے مروی ہے اسے روایت کرنے میں ابوصخر اکیلے ہیں۔","",{"k":"صحیح بخاری (٣٦٨٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ آدمی قیامت کے دن اپنے محبوب کے ساتھ ہو گا۔ سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ ہمیں اسلام لانے کے بعد کسی بات سے اتنی زیادہ مسرت نہ ہوئی جتنی نبی مکرم لئے علیکم کے اس ارشاد گرامی ((فانك مع من احببت )) ”بے شک تو اسی کے ساتھ ہوگا جس کے ساتھ تو نے محبت کی “ سے ہوئی سیدنا انس رضی اللہ عنہ نے مزید کہا: ”میں اللہ تعالیٰ، اس کے رسول ملنے نیم، سیدنا ابو بکر اور سیدنا عمر نای نینجا سے محبت کرتا ہوں اور مجھے امید ہے کہ میں (آخرت میں) انہی کے ساتھ ہوں گا اگر چہ میں نے ان کے برابر اعمال نہیں کیے۔ (صحیح مسلم)"}],[108,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی جمعہ کے لیے آئے تو وہ غسل کرے۔“ یہ حدیث بیع سے صرف عبدالملک ہی روایت کرتے ہیں۔ ١٠٩","",{"k":"صحیح بخاری (٩١٩)۔"}],[109,"سیدنا انس بنی اہلیہ سے روایت ہے کہ نبی ملے یا جب بیمار ہوتے تو کلونجی کی ہتھیلی پھانک لیتے اور اس کے اوپر پانی اور شہد پی لیتے تھے۔“ یہ حدیث نبی کریم طلے تم سے صرف اسی سند سے ہی مروی ہے۔ و-ه-","",{"k":"ضعيف الجامع الصغير (٤٣٣٩)، مجمع الزوائد (٥/٨٧)۔"}],[110,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”صرف اونٹوں اور گھوڑوں کی دوڑ کے مقابلے انعام حلال ہے۔ ابی عبداللہ الجندعی سے اسے صرف سلیمان بن بیار ہی روایت کرتے ہیں اور ابن لیسار سے صرف ابو الاسود محمد بن عبدالرحمن روایت کرتے ہیں، اسے روایت کرنے میں لیٹ بن عبید اللہ ا کیلے ہیں۔ سبق کا معنی ہے دوڑ وغیرہ کے لیے مقابلے میں مالی انعام مقرر کرنا۔ خف: اونٹ، حافر، گھوڑے۔ اس روایت سے معلوم ہوتا ہے کہ مقررہ انعام پر دوڑ کا مقابلہ کرانا جائز ہے اگر تو انعام دوڑ لگانے والے فریقین کے علاوہ کسی اور کی طرف سے ہو (مثلاً حاکم وغیرہ کی طرف سے ) تو بلا اختلاف یہ جائز ہے لیکن اگر دوڑ لگانے والے آپس میں انعام مقرر کریں تو یہ جوا ہونے کی وجہ سے ناجائز ہے۔ نیز حدیث کا ظاہر یہی ہے کہ مقرر انعام پر مقابلے بازی صرف مذکورہ دونوں کھیلوں میں ہی جائز ہے۔ ایک حدیث میں ہے کہ اونٹوں، گھوڑوں اور تیراندازی کے سوا اور کسی چیز میں مسابقت جائز نہیں۔ (صحیح ابو داؤد، كتاب الجهاد، رقم: ٢٥٧٤) امام مالک، شافعی عدالت اسی کے قائل ہیں۔ جبکہ عطاء اللہ نے ہر کھیل میں اسے جائز قرار دیا ہے۔ (سبل السلام: ٢٦٤/٤)","",{"k":"صحیح سنن نسائی (٣٥٨٧)، قال الالباني۔"}],[111,"سیدنا عبداللہ ابن عمر بنی النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی شخص کسی دوسرے کو ”اے کافر کہتا ہے تو ان میں سے ایک پر کفر واجب ہو جاتا ہے۔“ بکیر سے اسے صرف ابو الاسود ہی روایت کرتے ہیں اور ابو الاسود سے صرف عبید اللہ بن ابی جعفر روایت کرتے ہیں، اسے روایت کرنے میں لیٹ اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ کسی مسلمان کو بلاوجہ کا فر کہنا سخت منع ہے کیونکہ اس میں وجوہ کفر نہ پائے گئے تو کہنے والا کافر قرار پائے گا۔ سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس شخص نے کسی آدمی کو کافر کہہ کر پکارا یا کہا: اے اللہ کے دشمن! جب کہ وہ ایسا نہ ہو، تو وہ بات اسی کی طرف لوٹ آتی ہے۔:١١٢ (صحیح بخاری، کتاب الادب، رقم: ٦٠٤٥)","",{"k":"المعجم الكبير للطبراني (١٤٦/١١)۔"}],[112,"فضل کہتے ہیں میں نے سیدنا معاویہ رضی اللہ عنہ سے سنا اور آپ کے پاس عورتوں کے بالوں کا ایک گچھا تھا، آپ فرما رہے تھے کہ قرطہ کی بیٹی نے مجھے خبر دی ہے کہ عورتیں یہ پہنتی ہیں۔ اور یہ اللہ تعالیٰ کی تم پر رحمت ہے کہ میں نے یہ بات معلوم کر لی ہے کیونکہ میرے پاس اس کا علم ہے۔ میں نے رسول اللہ مل علم سے سنا آپ فرما رہے تھے: ”جس نے اپنے بالوں میں ایسا اضافہ کیا جو ان میں پہلے شامل نہیں تھا تو وہ ان میں جھوٹ کو ملا رہا ہے۔ یہ حدیث صفوان بن سلیم سے صرف عبید اللہ بن ابی جعفر ہی روایت کرتے ہیں، اسے روایت کرنے میں لیٹ اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (٢٦٣/١٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مصنوعی بال (وگ) حرام ہیں، اگر چہ بال سر پر ہوں یا نہ ہوں۔ جیسا کہ سیدہ اسماء بنی النہا سے روایت ہے کہ ایک عورت نے نبی ملل علیم سے پوچھا کہ میری بیٹی کو حصبہ ( جلد کی بیماری) لگی جس سے اس کے بال جھڑ گئے ہیں اور میں نے اس کی شادی کر دی ہے۔ تو کیا میں اس کے مصنوعی بال لگا دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ نے مصنوعی بال لگانے والی اور لگوانے والی پر لعنت فرمائی ہے۔‘(صحیح بخاری، کتاب اللباس، رقم: ٥٩٤١) ١١٣"}],[113,"سیدہ عائشہ بنی النہا سے روایت ہے کہ نبی علی اسلام نے فرمایا: ”کمر کا درد گردے کی رگ کا درد ہوتا ہے۔ جب یہ اپنی جگہ سے حرکت کرتا ہے تو تکلیف دیتا ہے، اس لیے اس کا علاج اُبلے ہوئے پانی سے کیا کرو۔“ یہ حدیث زہری سے صرف عبدالرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں مسلم اکیلے ہیں۔","",{"k":"السلسة الضعيفه (٣/٢٢٢، ١٢٢٣)، قال الالباني، موضوع۔"}],[114,"سیدنا ابو ہریرہ بنی الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جبریل علیہ سلام سے کہا: ” کیا آپ کا رب بھی صلوۃ پڑھتا ہے؟ انہوں نے کہا: جی ہاں، میں نے کہا: ”اس کی صلوۃ کیا ہے؟ تو انہوں نے کہا: ((سُبُّوحٌ قُدُّوسٌ سَبَقَتْ رَحْمَتِي غَضَبِى )) میں ہر عیب سے پاک نہایت مقدس ذات ہوں، میری رحمت میرے غضب سے آگے بڑھ گئی","",{"k":"السلسلة الضعيفة (٣/٣٨٥)، رقم : ١٣٨٢ الزوائد: ١٠/ ٢١٣ قال الالبانى، موضوع. مجمع۔"}],[115,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اے علی تم نے ”دو نمازوں سے منع فرمایا (١) ایک نماز عصر کے بعد سورج غروب ہونے تک (٢) دوسری صبح کے بعد سورج کے طلوع ہونے تک اور عید الفطر و عید الاضحی کے دن روزہ رکھنے سے۔ اور فرمایا: ” کوئی عورت اپنی پھوپھی یا خالہ پر نکاح کر کے نہ دی جائے اور چادر کے اشتمال الصماء سے ( ٹھوس اور مضبوط لپیٹنے سے کہ ہاتھ نہ کھل سکیں ) اور اس سے بھی کہ کوئی شخص سر ہانے میں اس طرح گھٹے کھڑے کر کے پیٹھ سے باندھ کر نہ بیٹھے کہ اس کی شرمگاہ پر کچھ نہ ہو۔ اور اس سے بھی کہ کوئی عورت دو دنوں کی مسافت تک بغیر خاوند یا ذی محرم کے سفر کرے۔ اور تین مسجدوں کے علاوہ کسی طرف کجاوے کس کے سفر کیا جائے (١) میری مسجد (٢) مسجد حرام (٣) مسجد اقصی‘ یہ حدیث ابوسعید سے صرف اس سند سے ہی مروی ہے، اسے روایت کرنے میں ابن لہیعہ اکیلے ہیں","",{"k":"٤٢٤٣ : مسند احمد (٣٧٩/١٣)، رقم۔"}],[116,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے شراب اور اس کی قیمت کو حرام کیا، خنزیر کا گوشت اور اس کی قیمت، مردار اور اس کی قیمت کو حرام کیا ہے۔ “ ابوزناد سے یہ حدیث صرف عبدالوہاب بن بخت ہی روایت کرتے ہیں، ابن وہب اسے روایت کرنے میں اکیلے ہیں۔ نا معلوم ہوا کہ مذکورہ چیزیں حرام ہیں۔ اور ان کی تجارت بھی حرام ہے۔ ()) اس حدیث سے ثابت ہوا کہ شراب حرام ہے۔ لہذا ادویات وغیرہ میں اس کا استعمال حرام ہے اور اس کی تجارت بھی حرام ہے۔ (٢) اسی طرح خنزیر زندہ ہو یا مردہ اس کے تمام اجزا نجس اور حرام ہیں، ان حرام اشیا کی خرید وفروخت نہیں ہو سکتی۔ (٣) مردار کی قیمت حرام ہے، لیکن اگر مردار کے چمڑے کو رنگا جائے جبکہ وہ حلال جانور کا ہو تو اس کی قیمت لینا جائز ہے۔","",{"k":"♦، سنن ابی داؤد (٣٤٨٥)، قال الالباني صحیح، السنن الكبرى للبيهقي (١٢/٦)۔"}],[117,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے وہ کہتے ہیں رسول اللہ علیم خبیر آئے تو کہا گیا: اللہ کے رسول ملے گدھے ختم ہو گئے تو رسول اللہ صلی اللہ علیہ وسلم نے ابوطلحہ کو حکم دیا تو انہوں نے یہ آواز لگائی کہ اللہ تعالیٰ اور اس کے رسول ملے عام تمہیں پالتو گدھوں کے گوشت سے منع فرماتے ہیں کیونکہ وہ پلید ہیں۔“ ابن عون سے صرف جریر ہی روایت کرتے ہیں اور اسے ابن وہب اکیلے روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ پالتو گدھے کا گوشت کھانا حرام ہے۔ یہ ناپاک ہے۔ سیدنا براء بن عازب ضمنی الیہ کی روایت میں پالتو گدھوں کے کچے اور پکے ہر طرح کے گوشت کی حرمت کا ذکر ہے۔(صحیح بخاری، کتاب المغازی، رقم: ٤٢٢٦)","",{"k":"داؤد، رقم : ١ ٣٨٠٩ : صحیح بخاری، خیبر (٤١٩٨)، سنن ابو۔"}],[118,"سیدہ عائشہ منی اش با بیان کرتی ہیں کہ مجھے سیدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا کہ وہ رسول اللہ علیم کے ساتھ انصار کے ایک شخص کے نکاح کے موقع پر موجود تھا، نبی ٹیم نے خطبہ ارشاد فرمایا: اور نکاح کیا اور فرمایا: الفت، محبت اور اچھے شگون پر اپنے ساتھی کے سر پر دف بجاؤ اور کچھ ٹوکرے آ گئے جس میں فروٹ اور شکر تھی تو وہ لوگوں میں بانٹ دیئے گئے، کچھ لوگ اسے لینے سے رک گئے تو رسول اللہ صلی عالی ام نے فرمایا: ”بردباری کتنی خوبصورت ہوتی ہے کیا تم یہ نہیں لوٹتے؟ لوگوں نے کہا: رسول اللہ ملیم آپ نے فلاں دن لوٹنے سے منع فرمایا تھا آپ نے فرمایا: ” میں نے تمہیں لشکروں کے ٹوٹنے سے منع کیا تھا۔ ولیموں کے لوٹنے سے منع نہیں کیا تھا۔ تم کو ٹو“ معاذ رضی اللہ عنہ کہتے ہیں: اللہ کی قسم! میں نے رسول اللہ نے تم کو دیکھا کہ آپ ہمیں اس لوٹ کی تعریف کے طور پر حَبَّذا کہتے اور ہم انہیں کہتے۔“ یہ حدیث اوزاعی سے صرف بشر بن ابراہیم ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (٤/٢٩٠)، السنن الكبرى للبيهقي: ٢٨٨/٧ . ٢٩٠۔"}],[119,"سيدنا عبداللہ ابن عباس نیلی اینجا سے روایت ہے کہ وہ استثناء (ان شاء اللہ ) کو ضروری سمجھتے چاہے سال بعد ہی کیوں نہ ہو۔ پھر یہ آیت پڑھی: ﴿ وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلُ ذَالِكَ غَدَّ إِلَّا أَنْ يَشَاءَ اللهُ وَاذْكُرْ رَبَّكَ إِذَا نَسِيتَ اور کسی چیز کے متعلق یہ نہ کہو کہ اس کو میں کل کروں گا مگر یہ کہ اللہ چاہے اور جب تم بھول جاؤ تو اپنے رب کو یاد کرو۔ آپ فرماتے: ((إِذَا ذَكَرْتَ)) یعنی جب یاد آئے تو کہہ سکتے ہو۔ “ اعمش سے کہا گیا کہ آپ نے یہ مجاہد سے سنا ہے؟ فرمایا: مجھے یہ لیث نے از مجاہد بیان کیا۔ یہ حدیث اعمش سے صرف ابو معاویہ ہی روایت کرتے ہیں، اسے روایت کرنے میں بیچی اکیلے ہیں۔","",{"k":"السنن الكبرى للبيهقى (٤٨/١٠)، المعجم الكبير للطبراني (٣٢٣/١٠)۔","f":"مذکورہ روایت سے معلوم ہوا کہ اپنے کلام میں یا قسم میں ان شاء اللہ کہنا چاہیے اگر وہ بھول جائے تو جب یاد آئے وہ پڑھ لے خواہ کتنی مدت ہی کیوں نہ گزرگئی ہو۔ جیسا کہ سیدنا عبداللہ ابن عم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس نے کسی کام پر قسم اٹھائی اور ان شاء اللہ بھی کہ دیا تو اس پر قسم توڑنے کا کفارہ نہیں۔“ (سنن ابو داؤد، کتاب الايمان والنذور، رقم: ٣٢٦١، اسناده صحيح) معلوم ہوا کہ قسم کھاتے وقت ان شاء اللہ کہہ دیا جائے تو پھر اس قسم کو توڑنے پر کفارہ لازم نہیں آتا۔ کیونکہ اسے اللہ کی مشیت پر موقوف کر دینا درحقیقت وہ پختہ قسم ہے ہی نہیں جسے توڑنے پر کفارہ واجب کیا گیا ہے۔"}],[120,"سیدنا بلال بن عبد اللہ بن عمر کہتے ہیں ایک دن عبد اللہ بن عمر رضی اللہ عنہما لگے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عورتوں کے جو حصے اور فائدے مساجد سے متعلق ہیں وہ ان پر بند نہ کرو“ میں نے کہا: میں تو ضرور اپنے گھر والوں پر بند کروں گا اور جو چاہے وہ اپنے اہل کو منع کر دے تو میری طرف میرے باپ نے توجہ کی اور کہا: اللہ تعالیٰ تجھ پر لعنت کرے اور اللہ تعالیٰ تجھ پر لعنت کرے۔ اللہ تعالیٰ تجھ پر لعنت کرے۔ تو مجھ سے نہیں سن رہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ان کو منع نہ کیا جائے تو تو کہتا ہے کہ میں اپنے اہل کو منع گا پھر آپ رو پڑے اور غضب ناک حالت میں اٹھ کھڑے ہوئے۔ یہ حدیث عرابی بن معاویہ سے صرف بیٹی بن بکیر ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ عورتیں مسجد میں جاسکتی ہیں اس روایت سے ایک اہم مسئلہ کی وضاحت ہوتی ہے کہ کسی مسلمان کے لیے جائز نہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے فرمان کے مقابلے میں اپنی سوچ اور فہم کو اہمیت دے۔ اس پر اصرار میں کفر کا اندیشہ ہے جیسا کہ ارشاد باری تعالیٰ ہے ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ إِذَا قَضَى اللهُ وَرَسُولُةٌ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ ﴾ (الاحزاب: ٣٦) کسی بھی مومن مرد یا عورت کو حق نہیں کہ جب اللہ اور اس کا رسول کسی معاملے کا فیصلہ فرما دیں تو انہیں اپنے معاملے کا اختیار ہو۔“","",{"k":"صحیح مسلم (١٤/٤٤٢)، الجامع الصغير (٣٧٤٢)، المعجم الكبير للطبرانی (٩/٢١١)۔"}],[121,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اذان کہنے والے کو اس کے آواز کی دوری تک معاف کیا جاتا ہے۔ یہ حدیث حفص سے یحی الجعفی ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ اذان بلند آواز سے کہنی چاہیے۔ کیونکہ یہ اسلام اور مسلمانوں کا شعار ہے لیکن آواز کی یہ بلندی اس طرح اور اس حد تک ہو کہ اس میں کراہیت اور بھدا پن پیدا نہ ہو۔ کیونکہ رفع صوت کے ساتھ حسن صوت بھی مطلوب اور پسندیدہ ہے۔","",{"k":"وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ . المعجم الكبير للطبرانی (١٩/١٠٥)۔","f":"(٢) یہ بھی معلوم ہوا کہ مؤذن کے گناہ اذان کی وجہ سے معاف ہو جاتے ہیں۔ ایک حدیث میں ہے سیدنا ابوسعید خدری روی اہلیہ نے کہا: میں دیکھتا ہوں کہ تم کو جنگل میں رہ کر بکریاں چرانا بہت پسند ہے اس لیے جب کبھی بکریوں کے ساتھ تم کسی بیابان میں موجود ہو اور ( وقت ہونے پر ) نماز کے لیے اذان دو تو اذان دیتے ہوئے اپنی آواز خوب بلند کرو، کیونکہ مؤذن کی آواز اذان کو جہاں تک بھی کوئی انسان، جن یا کوئی چیز بھی سنے گی تو قیامت کے دن اس کے لیے گواہی دے گی۔ سیدنا ابوسعید خدری رضی اللہ عنہ نے فرمایا کہ میں نے یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی تھی۔ (صحیح بخاری، رقم: ٣٢٩٦)"}],[122,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ اللهُ يَتَوَفَّى الْأَنْفُسَ حِيْنَ وتها \"اللہ تعالیٰ جانوں کو ان کے مرنے کے وقت فوت کر دیتا ہے۔ زندوں اور مردوں کی روحیں خواب میں ملتی ہیں تو ایک دوسرے سے سوال و جواب کرتی ہیں، پھر اللہ تعالیٰ مردوں کی روحوں کو روک لیتا ہے اور زندوں کی روحیں ان کے جسموں میں بھیج دیتا ہے۔ مطرف سے اس حدیث کو صرف موسیٰ ہی روایت کرتے ہیں۔ معلوم ہوا کہ، روحیں آپس میں ملاقات کرتی ہیں۔ جب آدمی مرتا ہے اور جب و سوئیں، کیونکہ نیند کوموت کی بہن ( چھوٹی موت ) کہا جاتا ہے۔ وَهُوَ الَّذِي يَتَوَفَّكُمْ بِأَلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُمْ بِالنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيْهِ لِيُقْضَى أَجَلٌ مسمى (الانعام: ٦٠) اور وہ ایسا ہے کہ رات میں تمہاری روح کو (ایک گونہ) قبض کر دیتا ہے اور جو کچھ تم دن میں کرتے ہو اس کو جانتا ہے پھر تم کو جگا اٹھاتا ہے۔“ معلوم ہوا کہ جب آدمی سوتا ہے اس کی روح کو قبض کر لیا جاتا ہے جب ان دونوں کی روحیں آپس میں ملتی ہیں تو سونے والے کی روح واپس لوٹ آتی ہے مرنے والے کی روح کو روک لیا جاتا ہے۔","",{"k":"مجمع الزوائد (٧/١٠٠)۔"}],[123,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے وہ کہتے ہیں رسول اللہ علیم نے فرمایا: ” شہداء نہر جنت کے دروزے پر ایک نہر نہر بارق پر سبز گنبد میں ہیں ان پر ان کا رزق جنت سے صبح و شام آتا ہے۔‘ یہ حدیث حضرت ابن عباس سے صرف اس سند سے مروی ہے، محمد بن اسحاق اسے روایت کرنے میں اکیلے ہیں۔ مذکورہ روایت میں شہدا کی فضیلت کا تذکرہ ہے کہ اللہ تعالیٰ کے ہاں ان کو رزق دیا جاتا ہے جیسا کہ ارشاد باری تعالی ہے: وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ اَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ ﴾ (آل عمران: ١٦٩) ”جو لوگ اللہ کی راہ میں شہید کیے جائیں انہیں ہرگز مردہ نہ سمجھو، بلکہ وہ زندہ ہیں اپنے رب کے پاس رزق دیے جاتے ہیں۔“","",{"k":"صحيح الجامع الصغير (٣٧٤٢)، المعجم الكبير للطبراني (٩/٢١١)۔"}],[124,"سیدنا عبداللہ ابن عمربنی انا نے فرمایا: ایک شخص حق لینے کے لیے ایک دوسرے شخص سے چمٹ گیا اور اس پر اصرار کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو ( حق کا مطالبہ کرے تو وہ شرافت سے طلب کرے پورا ادا ہو یا ادھورا۔“ مذکورہ روایت سے معلوم ہوا کہ اپنا حق لینے کے لیے انسان کو احسن انداز سے مطالبہ کرنا چاہیے۔ اگر اس نے حق لینا ہے تو اس پر ظلم نہ کرے، گالی گلوچ اور فتنہ وفساد سے پریشانی نہ بنائے۔ بلکہ ارشاد باری تعالی ہے: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ (البقرة: ٢٨٠) اور اگر وہ تنگ دست ہے تو اسے خوش حالی تک مہلت دینا ہے۔“ ہاں اگر اس آدمی کے پاس پیسے موجود ہوں اور وہ ادا نہیں کرتا تو اس کی بے عزتی کرنا اور سزا دینا جائز ہے۔ لیکن حرام کا مرتکب ہونا جائز نہیں ہے۔","",{"k":"المعجم الكبير للطبراني (١١/١٤٧)۔"}],[125,"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا: نبی علیم ہمارے پاس تشریف لائے، میرا ایک چھوٹا بھائی تھا، آپ نے فرمایا: ”اے ابو عمیر! تیرے پرندے کو کیا ہوا (اس کی ایک چھوٹی چڑیا تھی جس سے وہ کھیلتا تھا مر گئی تھی۔ یہ حدیث ابن شوذب سے صرف ضمر ہ ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ اولاد نہ ہونے کے باوجود کنیت رکھنا جائز ہے۔ (٢) چھوٹے بچے کی کنیت بھی رکھنا جائز ہے۔ (٣) معلوم ہوا کہ مسیح کلام کرنا جائز ہے اور جائز حدود میں ہنسی مزاح کی بات میں کوئی حرج نہیں۔اسی طرح پرندے پال لینا اور ان سے کھیلنا بھی مباح ہے۔ (٤) بچوں سے دل لگی کی باتیں کرنا جائز ہے۔","",{"k":"صحیح بخاری، رقم : ٦١٢٩ سنن ابی داؤد (٤٩٦٩)۔"}],[126,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کسی زخم کے ٹھیک ہونے سے پہلے اس کا قصاص نہ لیا جائے۔ یہ حدیث شعمی سے صرف عنبہ بن سعید قاضی الری اور عنبہ سے صرف ابن مبارک ہی روایت کرتے ہیں اسے مہدی بن جعفر ا کیلے روایت کرتے ہیں۔","",{"f":"مذکورہ حدیث سے معلوم ہوا کہ زخم کے ٹھیک ہونے سے قبل کسی سے قصاص نہ لیا جائے، کیونکہ ہوسکتا ہے کہ اس سے انسان فوت ہو جائے یا آدمی کا زخم درست ہو جائے۔ جیسا کہ عبدالرحمان بن عجم نے سیدناعلی ضیا اللہ پر قاتلانہ حملہ کیا تو سیدناعلی ضیا اللہ نے فرمایا: اس کو قتل نہ کرنا اگر میں شہید ہو گیا تو (قصاص میں قتل کر دینا اگر بچ گیا تو اس کے معاملے پر غور کروں گا۔ (ابن اثیر: ٤ / تاريخ اسلام: ١٥/١، مولانا معین الدین ندوی)"}],[127,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول الله من علم نے سیدنا علی رضی اللہ عنہ کے دونوں بیٹوں سیدنا حسن اور حسین کے سر منڈوانے کے متعلق حکم فرمایا: پس انہیں مونڈا گیا پھر ان کے (بالوں کے وزن کے برابر چاندی صدقہ کی آپ کو ذبح کرنے کے لیے جانور نہ ملا۔","",{"k":"ارواء الغليل (٤/٤٠٥)۔","f":"(١) مذکورہ روایت سے معلوم ہوا کہ ساتویں دن سر منڈانا سنت ہے۔ جیسا کہ نبی معظم لئے علیم نے فرمایا: ”ہر بچہ اپنے عقیقہ کے عوض گروی ہوتا ہے پیدائش کے ساتویں روز اس کا عقیقہ کیا جائے، اس کا نام رکھا جائے، اور سر کے بال منڈائے جائیں۔“ (صحیح سنن ابو داؤد، کتاب الضحايا، رقم: ٢٤٦٣)\n(٢) اسی طرح سر کے بالوں کے برابر چاندی صدقہ کی جائے گی۔ علامہ ابن قدامہ اللہ فرماتے ہیں: اگر کوئی بچے کے بالوں کے وزن کے برابر چاندی صدقہ کر دے تو بہتر ہے۔(المغنی: ٣٩٧/١٣) سید سابق ملالہ فرماتے ہیں: بالوں کے ہم وزن چاندی کا صدقہ کر دینا چاہیے اگر یہ میسر ہو۔\n(٣) بچی کی طرف سے ایک اور بچے کی طرف سے دو جانور ذبح کرنا بھی مسنون ہے"}],[128,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بوڑھے","",{"k":"صحيح مسلم (١٠٤٦)، السلسلة الصحيحة (١٩٠٦)، سنن ترمذی (٢٣٣٨)۔","f":"آدمی کا دل دو چیزوں کی محبت میں جوان ہوتا ہے ایک زندگی کی محبت میں اور دوسرا مال کی محبت میں۔“ اس حدیث کو یحیی بن سعید سے عمارہ بن غزیہ ہی روایت کرتے ہیں، ابن لہیعہ اسے روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ آدمی بوڑھا ہو جاتا ہے تو اس کا دل دو چیزوں کے بارے میں جوان ہوتا چلا جاتا ہے۔\n(١) زندگی کی حرص میں کہ مجھے زیادہ زندگی مل جائے\n(٢) دنیا کی دولت اکٹھی کرنے کے لیے۔ اسی لیے تو نبی مکرم ملے تم نے فرمایا: اگر ابن آدم کے پاس سونے کی ایک وادی ہو تو وہ چاہے گا دوسری وادی بھی ہو، اور اس کے منہ کو صرف ( قبر کی مٹی ہی بھرتی ہے، اور اللہ تعالیٰ اس کی توبہ قبول کرتا ہے جو تو بہ کرے یعنی حرص اور جمع مال سے۔“ (سنن ترمذی، کتاب الزهد، رقم: ٢٣٣٧) یعنی جب آدمی جیتا ہے تو مال پر، مرتا ہے تو مال پر۔"}],[129,"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم اکثر یہ کلمات پڑھا کرتے تھے: ((اللَّهُمَّ اِنّى اَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْبُخْلِ وَالْجُبْنِ وَالْعَجْزِ وَالْكَسَلِ وَمِنْ ضَلَعِ الدَّيْنِ وَمِنْ غَلَبَةِ الرِّجَالَ )) ”اے اللہ اغم اور دکھ سے، بخل، بزدلی، عاجزی اور سستی سے اور قرضے کے بوجھ اور لوگوں کے غالب آجانے سے تیری پناہ چاہتا ہوں۔","",{"k":"صحيح الجامع الصغير (١٢٨٩)، سلسلة الصحيحه (٤/١١٥، ١٥٤١)۔","f":"مذکورہ حدیث سے معلوم ہوا غم، دکھ، بخل، بزدلی، سستی اور قرضہ وغیرہ اخلاق رزائل سے ہیں اور ان سے اللہ تعالیٰ کی پناہ مانگتے رہنا چاہیے۔ ١٣٠"}],[130,"سيدنا ابو ہریرہ رضی نے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” اللہ تعالیٰ فرماتا ہے میں تمام شرکا کی بہ نسبت شرک سے زیادہ بے نیاز ہوں تو جو شخص میرے ساتھ کسی کو شریک کرے تو وہ سارا عمل اسی کے لیے ہو جاتا ہے، پس جو شخص میرے ساتھ کسی کو شریک کرے تو وہ سارا عمل اس کے لیے ہو جاتا ہے۔“ (١) مذکورہ حدیث سے معلوم ہوا ریا کاری کرنے والے کے اعمال اللہ تعالیٰ کے ہاں قبول نہیں ہوتے۔ (٢) کسی اور کو شریک کرنے کا مطلب ریا کاری کے لیے اعمال کرنا ہے۔ (٣) ریا کاری شرک اصغر ہے جس عمل میں ریا کاری آگئی وہ عمل تباہ ہو گیا تاہم یہ شرک اکبر نہیں جس کی سزا دائمی جہنم کا عذاب ہے","",{"k":"کر کنز العمال (٤٨٢/٣)، سنن ابن ماجه، رقم: ٤٢٠٢ فائد۔"}],[131,"رفاعہ بن رافع کہتے ہیں میں نے اپنے باپ سے سنا وہ کہہ رہے تھے کہ جبریل عالینام نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: تم میں اہل بدر کی کیا حیثیت ہے؟ تو آپ علینا نے فرمایا: ”وہ ہم میں سے افضل شمار ہوتے ہیں جبرئیل علینا نے کہا: ہم میں سے بھی جو فرشتے غزوہ بدر میں حاضر ہوئے وہ ہمارے افضل فرشتے ہیں۔“ مذکورہ حدیث سے معلوم ہوا کہ بدر کی لڑائی میں شریک ہونے والے صحابی دوسرے صحابیوں سے افضل ہیں۔ اسی طرح بدر میں شریک ہونے والے فرشتے دوسرے فرشتوں سے افضل ہیں۔ کیونکہ یہ حق و باطل کا پہلا معرکہ تھا جس میں تین سو تیرہ صحابہ کرام بھی ایم کے مقابلے میں مشرکین مکہ ایک ہزار (١٠٠٠) کے قریب تھے۔ اللہ تعالیٰ نے غزوہ بدر میں آسمان سے فرشتے نازل فرمائے تھے۔ جیسا کہ ارشاد باری تعالیٰ ہے۔ إِذْ يُوْحِيَ رَبُّكَ إِلَى الْمَلَئِكَةِ إِنِّي مَعَكُمْ فَقَبْتُوا الَّذِينَ آمَنُوا سَأُلْقِي فِي قُلُوبِ الَّذِيْنَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْأَعْنَاقِ وَ اضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍ ﴾ (الانفال: ١٢) اس وقت کو یاد کرو جب کہ آپ کا رب فرشتوں کو حکم دیتا تھا کہ میں تمہارے ساتھ ہوں سو تم ایمان والوں کی ہمت بڑھاؤ میں ابھی کفار کے قلوب میں رعب ڈالے دیتا ہوں، سو تم گردنوں پر مارو اور ان کے پور پور پر مارو۔“","",{"k":"صحیح بخاری (١٣١٣٩٩٢)، معرفة الصحابة لابي نعيم (٣٦٦/٧، ٢٣٤٨)۔"}],[132,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جب میری امت متکبرانہ چال چلنے لگے گی اور فارس و روم ان کے خدمت گار ہو جائیں گے تو اس وقت ان میں سے بعض کو بعض پر مسلط کر دیا جائے گا۔“","",{"k":"بعضهم على بعض . )) ١٠٦٦٠ السلسلة الصحيحه (٣٠٣، ٩٥٦)، صحيح الجامع (٨٠١)، سنن ترمذی (٢٢٦١)۔","f":": اس حدیث میں امت میں اختلاف و افتراق کے سبب کو بیان کیا اور وہ عاجزی و انکساری کا خاتمہ ہے۔:١٣"}],[133,"عویمر بن اشقر سے روایت ہے کہ انہوں نے اپنی قربانی ذبح کی تو ایک پیالے میں سالن ڈالا اور اسے نبی صلی اللہ علیہ وسلم کے پاس لے آئے۔ آپ نے پوچھا: ”یہ کیا ہے؟“ انہوں نے کہا: یہ میری قربانی کا گوشت ہے۔ آپ نے فرمایا: ”وہ کب ذبح کیا؟“ انہوں نے کہا: نماز سے پہلے ذبح کیا تو آپ نے اسے دوبارہ قربانی کرنے کا حکم فرمایا۔“ مذکورہ حدیث سے معلوم ہوا کہ قربانی کا جانور، نماز عید کے بعد ذبح کرنا چاہیے۔ جو پہلے کرے گا اس کی قربانی نہیں عام گوشت ہے۔ جیسا کہ سیدنا ابو بردہ ولی اہلیہ نے نماز عید سے پہلے قربانی کی بکری ذبح کر دی تو آپ میم نے فرمایا: \"یہ تیری بکری ( قربانی یا صدقہ نہیں) بلکہ صرف گوشت کی بکری ہے۔“(صحیح بخاری، رقم: ٥٥٥٦) قبولیت اعمال کے لیے ان کا موافق سنت ہونا بہت ضروری ہے۔","",{"k":"ذبح، رقم: ٣١٥٣. مجمع الزوائد (٢٤/٤)، سنن ابن ماجه۔"}],[134,"عبد اللہ بن زید مازنی رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے استسقاء میں جب لوگوں کو حکم دیا کہ وہ اپنے ہاتھ اٹھا ئیں تو آپ پر ایک سیاہ چادر تھی آپ نے اس کے نچلے حصے کو بدلنے کا ارادہ کیا تو اس کو بھاری سمجھا اور وہ آپ پر غالب آ گئی۔ آپ نے اس کی اس جانب کو پکڑا جو کندھوں پر تھی تو اس کے دو کنارے ایک دوسرے سے بدل دیئے۔ اور اس کی جو جانب پیٹھ کی طرف تھی اس کو باہر کر دیا۔“ یہ احادیث عمارہ بن غزیہ سے صرف ابن لہیعہ ہی روایت کرتے ہیں۔ قائده صلاة الاستسقا: اس نماز کو کہتے ہیں جو باران رحمت طلب کرنے کے لیے ادا کی جاتی ہے۔ ایک حدیث میں قحط سالی کا سبب ماپ تول میں کمی اور بارش سے محرومی کا سبب زکاۃ کی عدم ادائیگی کو قرار دیا گیا ہے۔ (صحیح سنن ابن ماجه، كتاب الفتن، رقم: ٤٠١٩) نماز استسقاء سے متعلقہ چند اہم امور درج ذیل ہیں۔ (١) اس نماز کو کھلے میدان میں ادا کیا جائے۔ (٢) اس کے لیے اذان و اقامت کی ضرورت نہیں۔ (٣) صرف دل میں نیت کرے کہ میں نماز استسقاء ادا کر رہا ہوں۔ (٤) بلند آواز سے قراءت کی جائے۔ (٥) لوگ عجز وانکساری کا اظہار کرتے ہوئے نماز کے لیے جائیں۔ (١) انفرادی اور اجتماعی طور پر تو بہ، استغفار، ترک معاصی اور رجوع الی اللہ کا عہد کیا جائے۔ (٧) کھلے میدان میں منبر پر خطبے اور دعا کا اہتمام کیا جائے، تا ہم منبر کے بغیر بھی جائز ہے۔ (٨) سورج نکلنے کے بعد یہ نماز پڑھی جائے بہتر یہی ہے رسول اللہ صلی اللہ علیہ وسلم نے سورج نکلتے ہی پڑھی تھی۔ (٩) جمہور علماء کے نزدیک امام نماز پڑھا کر خطبہ دے تا ہم قبل از نماز بھی جائز ہے۔ (١٠) نماز گاہ میں امام قبلہ رخ کھڑا ہو کر دونوں ہاتھ اتنے بلند کرے کہ بغلوں کی سفیدی نظر آنے لگے۔ مذکورہ روایت میں چادر پلٹنے کا تذکرہ ہے۔ چادر پلٹنے کا آسان طریقہ یہ ہے کہ اپنے ہاتھوں سے کمر کے نیچے سے چادر کا دایاں کنارہ بائیں ہاتھ سے اور بایاں کنارہ دائیں ہاتھ سے پکڑ کر اوپر کو لے آئیں۔ اس طرح چادر اوپر نیچے دائیں، بائیں سب اطراف سے پلٹ جاتی ہے۔ چادر نہ اوڑھی ہو تو رومال ہی کے ساتھ یہ عمل کرے تا کہ سنت نبوی پر عمل کا ثواب حاصل ہو۔ ہاتھوں کی پشتوں کو آسمان کی طرف کرنا اور چادروں کو پلٹنا، یہ نیک فالی کے طور پر ہے یعنی یا اللہ! جس طرح ہم نے اپنے ہاتھ الٹے کر لیے ہیں اور چادروں کو پلٹ لیا ہے تو بھی موجودہ صورت کو اسی طرح بدل دے اور بارش برسا کر قحط سالی ختم کر دے اور تنگی کو خوش حالی میں بدل دے۔","",{"k":"سنن ابی داؤد (١٠٥٥)، قال الالباني صحیح، السنن الكبرى للبيهقي (٣٥١/٣)۔"}],[135,"ابن بریدہ اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کوئی فوجی دستہ یا لشکر بھیجتے تو فرماتے: ”اللہ کی راہ میں اس شخص سے جنگ کرو جو اللہ سے کفر کرے۔خیانت، دھوکہ اور مثلہ نہ کرنا، بچوں اور بوڑھوں کو قتل نہ کرنا۔ آپ ان کے امیر کو فرماتے: ”جب تم کسی قلعہ یا بستی کا محاصرہ کرو تو ان کو تین باتوں میں سے ایک بات پسند کر لینے کی دعوت دو (١) کہ وہ اسلام میں داخل ہو جائیں (٢) جزیہ دے دیں (٣) یا پھر تم ان سے جنگ کرو، اور جب تم کسی قلعے یا بستی کا محاصرہ کرو اور وہ اللہ تعالیٰ کے فیصلے پر آنا چاہیں تو انہیں اللہ تعالیٰ کے فیصلے پر نہ لاؤ کیونکہ تمہیں ان کے متعلق اللہ تعالیٰ کے فیصلہ کا کوئی علم نہیں کہ تم نے واقعی اللہ کے فیصلے کو پالیا ہے یا نہیں لہذا انہیں اپنے اور اپنے ساتھیوں کے فیصلے پر لاؤ اور جب تم کسی قلعہ والوں یا بستی والوں کا محاصرہ کر لو تو اگر وہ تم سے اللہ تعالیٰ یا اس کے رسول کا ذمہ دینے کا مطالبہ کریں تو انہیں اللہ تعالیٰ اور اس کے رسول کا ذمہ نہ دو بلکہ انہیں اپنا اور اپنے ساتھیوں کا ذمہ دو۔ کیونکہ اگر تم مجبوری یا لاعلمی میں اپنے عہد کی خلاف ورزی کرو تو یہ اللہ اور اس کے رسول کے عہد کی خلاف ورزی کرنے سے بہتر ہے۔“ سعید بن ابی ھلال سے اس حدیث کو صرف خالد بن یزید ہی روایت کرتے ہیں، اسے ابن لہیعہ روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جب حاکم لشکر کو جہاد کے لیے روانہ کرے تو اس کو امیر لشکر کو نصیحت کرنی چاہیے۔ یہ بھی معلوم ہوا کہ دوران جنگ مقتولین کا مثلہ کرنا، مال غنیمت میں خیانت اور عہد شکنی کا مرتکب ہونا حرام ہے۔ یہ بھی پتہ چلا کہ اگر کفار کو دعوت اسلام نہ دی گئی ہو تو پھر لڑائی سے پہلے انہیں دعوت دینا واجب ہے۔ جمہور اسی کے قائل ہیں جبکہ امام مالک ہو اللہ نے کہا ہے کہ کفار کو اسلام کی دعوت دینا واجب نہیں پہلے دعوت پہنچی ہو یا نہ پہنچی ہو۔ اور حنابلہ نے کہا ہے کہ کفار کو دعوت دینا کسی صورت میں بھی واجب نہیں۔ پہلا موقف ہی راجح ہے، امام ابن منذر اور امام صنعانی اللہ بھی اسی کے قائل ہیں۔ (المغنی: ٢٩/١٣) نيل الاوطار: ٧٠٠/٤ - سبل السلام: ١٧٦٠/٤) یہ بھی معلوم ہوا کہ کفار کے نابالغ بچوں، بوڑھوں اور عورتوں کو قتل کرنا جائز نہیں۔ یہ بھی معلوم ہوا کہ اگر دوران جنگ کفار اللہ کے فیصلے کے مطابق صلح کرنا چاہیں تو ایسا نہیں کرنا چاہیے کیونکہ کسی کو کیا معلوم کہ اللہ کا فیصلہ کیا ہے اس لیے صرف اپنے فیصلے پر اور اپنے عہد و پیمان پر صلح کرنا چاہیے۔","",{"k":"صحيح الجامع الصغير (٥/٤٠٥، ١٩٥٨)، قال الشيخ الالباني۔"}],[136,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی علیم نے فرمایا: ” جمعے کے دن امید بھری گھڑی کو نماز عصر سے لے کر سورج غروب ہونے کے درمیان وقت میں تلاش کرو۔ اور یہ صرف اتنی ہے یعنی ایک مٹھی ہوتی ہے۔ یہ حدیث موسیٰ بن وردان سے صرف ابن لھیعہ ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جمعہ کے دن ایک ایسی گھڑی ہے جس میں ہر دعا کرنے فائد والے کی (جائز) دعا قبول کی جاتی ہے، یہ گھڑی عصر کے بعد ہے۔ لیکن ایک حدیث میں ہے۔ سیدنا ابو بردہ رضی اللہ عنہ اپنے والد سے روایت کرتے ہیں کہ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے کہ وہ گھڑی امام کے منبر پر بیٹھنے سے لے کر نماز پوری ہونے تک ( کے درمیانی وقت میں ) ہے۔“ (صحیح مسلم، کتاب الجمعه، رقم: ٨٥٣، سنن ابو داؤد، رقم: ١٠٤٩) اس گھڑی کے تعین میں اختلاف ہے زیادہ ظاہر دو قول ہیں۔ جن کا بیان مذکورہ بالا دو احادیث میں ہوا ہے۔ اس سلسلے میں زیادہ مناسب قول یہ معلوم ہوتا ہے کہ اس گھڑی کو نماز جمعہ سے لے کر دن کے آخر تک تلاش کیا جائے اور اس دوران کثرت سے دعا کی کوشش کی جائے۔ جیسا کہ شیخ ابن جبرین نے اسی طرف اشارہ فرمایا ہے۔ (فتاوی اسلامیه: ٤٠/١)","",{"k":"سنن ترمذی (٤٨٩)، السلسلة الصحيحة (٨٢/٦، ٢٥٨٣)۔"}],[137,"عبد الله بن حارث بن جزء الزبیدی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی مرد اور عورت کو رجم کیا، میں بھی رجم کرنے والوں میں شامل تھا۔“ یہ حدیث عبداللہ بن جزء ز بیدی سے صرف اسی سند سے مروی ہے،ابن لھیعہ اسے روایت کرنے میں اکیلے ہیں۔ یہ واقعہ بالاختصار یوں ہے کہ یہودی ایک عورت اور مرد کو نبی معظم صلی اللہ علیہ وسلم کے پاس لائے جنہوں نے زنا کا ارتکاب کیا تھا۔ آپ صلی اللہ علیہ وسلم نے پوچھا کہ تمہاری کتاب میں ان کے متعلق کیا حکم ہے؟ انہوں نے جواب دیا: ہم انہیں ذلیل و رسوا کرنے کے لیے ان کا منہ کالا کر کے گدھے پر بٹھا کر شہر میں چکر لگاتے ہیں۔ آپ صلی اللہ علیہ وسلم نے بطور ثبوت انہیں تو رات لانے کا حکم دیا۔ چنانچہ وہ تورات لا کر اسے پڑھنے لگے اور جب آیت رجم پر پہنچے تو اس پر ہاتھ رکھ دیا۔ سیدنا عبد اللہ بن سلام نبی اللہ نے فرمایا: اللہ کے رسول! اسے کہیے کہ اپنا ہاتھ اٹھائے، پس جب اس نے اپنا ہاتھ اٹھایا تو اس کے نیچے آیت رجم موجود تھی۔ چنانچہ آپ صلی اللہ علیہ وسلم نے ان دونوں کو رجم کرا دیا۔ اس سے معلوم ہوا کہ اسلامی ریاست میں مقیم غیر مسلم بھی اگر کسی جرم کا ارتکاب کریں گے تو ان پر حد جاری کی جائے گی تاکہ معاشرے کا امن و امان برقرار رہ سکے۔ یہ بھی معلوم ہوا کہ اگر کوئی غیر مسلم شرعی عدالت میں فیصلہ کرانے کے لیے آئے تو کتاب وسنت کے مطابق ہی اس کا فیصلہ کیا جائے گا۔","",{"k":"مجمع الزوائد (٦/٢٧١)۔"}],[138,"سیدنا جابر بن عبد اللہ فی اللہ سے روایت ہے کہ نبی ملے عام نے خشک کھجوروں اور منتقے کا اکٹھا نبیذ بنانے سے منع فرمایا۔ اسی طرح انگور اور تر کھجور کا بھی اکٹھا نبیذ بنانے سے منع فرمایا۔ یہ حدیث عمرو بن دینار سے صرف ابن لھیۃ ہی روایت کرتے ہیں۔","",{"k":"سنن نسائی (٥٥٧١)، سنن ابن ماجه (٣٣٩٥)، قال الالبانی، صحیح۔","f":"مذکورہ روایت سے معلوم ہوا کہ دو مختلف اجناس کا نبیذ بنانا جائز نہیں۔ امام نووی حمداللہ نے دو مختلف جنسوں کا اکٹھا نبیذ بنانے سے ممانعت کا سبب یہ بیان کیا ہے کہ اس سے جلد نشہ پیدا ہو جاتا ہے۔ (شرح مسلم: ١٧٣/٧) اس بات میں اختلاف کیا گیا ہے کہ حدیث میں موجود ممانعت حرمت کے لیے ہے یا کہ کراہت کے لیے؟ جمہور: یہ ممانعت حرمت کے لیے نہیں۔ امام خطابی، احمد، شافعی، اسحاق، قرطبی نیلم کے نزدیک ممانعت حرمت کے لیے ہے۔ امام ابو حنیفہ، ابو یوسف رحمہ اللہ فرماتے ہیں: ”جب الگ الگ یہ دونوں اشیا حلال ہیں تو جمع میں حرمت کیسی؟ (نیل الاوطار: ٢٦٩/٥ معالم السنن: ٢٦٩/٤)"}],[139,"سیدہ عائشہ بنی ان با بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تمام شعبان کے روزے رکھتے مگر اس سے بہت کم روزے نہ رکھتے۔ یہ حدیث اسود بن علاء سے صرف جعفر بن ربیعہ ہی روایت کرتے ہیں۔ ایک حدیث میں ہے سیدہ عائشہ نیلی نیہا فرماتی ہیں کہ: ”میں نے نبی معظم صلی اللہ علیہ وسلم کو","",{"k":"سنن نسائی (٢٣٥٦)۔","f":"رمضان کے علاوہ کسی اور مہینے کے مکمل روزے رکھتے ہوئے نہیں دیکھا اور میں نے آپ صلی اللہ علیہ وسلم کو کسی مہینے میں شعبان سے زیادہ روزے رکھتے ہوئے نہیں دیکھا۔ (صحیح بخاری، کتاب الصوم، رقم: ١٩٦٩) معلوم ہوا کہ رمضان کے علاوہ کسی بھی مہینے کے پورے روزے رکھنا چاہیے اسی طرح تمام مہینوں میں سب سے زیادہ شعبان کے روزے رکھتے تھے۔"}],[140,"سيدنا ابو قتادہ انصاری رضی اللہ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ لوگوں کو نماز پڑھا رہے تھے اور سیدہ امامہ بنت ابی العاص بھی لوہا آپ کے کندھے پر تھیں جب سجدے میں جاتے تو اسے نیچے اتار دیتے۔“ اندن مذکورہ حدیث سے معلوم ہوا کہ کسی کم سن بچے کو اٹھا کر نماز ادا کرنے سے نماز باطل نہیں","",{"k":"صحیح بخاری (٥٩٩٦)، سنن ابو داؤد (٩١٨)۔","f":"ہوتی خواہ نماز فرض ہو یا نفل، خواہ انسان امام، مقتدی یا منفرد ہو۔ امام مالک ہم اللہ اور بعض دیگر اہل علم کا خیال ہے کہ ایسا کرنا درست نہیں وہ اس حدیث کی تین طرح سے تاویل کرتے ہیں۔\n(١) یہ نفل نماز کی بات ہے فرض کی نہیں۔\n(٢) نبی معظم صلی اللہ علیہ وسلم نے بوقت ضرورت اسے اٹھایا کیونکہ کوئی دوسرا اسے اٹھانے والا نہیں تھا۔\n(٣) یہ حدیث منسوخ ہو چکی ہے۔ اس کا جواب یوں دیا گیا ہے کہ مسلم شریف میں واضح طور پر موجود ہے کہ آپ امامت کرا رہے تھے جس سے پتا چلتا ہے کہ نماز فرض تھی نفل نہیں۔ دوسری بات کہ بوقت ضرورت ایسا کیا یہ بھی درست نہیں، کیونکہ آپ صلی اللہ علیہ وسلم گھر میں آپ کے اہل وعیال اور خادم موجود تھے۔ تیسری بات حدیث منسوخ ہو چکی ہے دعوی بلا دلیل ہے۔ اس لیے راجح موقف یہ ہے کہ اٹھا سکتا ہے۔"}],[141,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: میرا باپ حج کئے بغیر فوت ہو گیا، کیا میں اس کی طرف سے حج کر سکتا ہوں؟ آپ نے فرمایا: ” اگر تیرے باپ پر کوئی قرضہ ہو تو کیا تو اسے ادا کرے گا؟“ اس نے کہا: جی ہاں، آپ نے فرمایا: ” تو اللہ کا قرضہ ادائیگی کا زیادہ حق دار ہے۔ اس حدیث کو اعمش سے صرف عبید اللہ بن عمر وہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (١٩/٤)۔"}],[142,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، ایک دن ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ آپ صلی اللہ علیہ وسلم کے پاس یہود آئے تو آپ صلی اللہ علیہ وسلم نے انہیں دیکھا کہ وہ سفید ریش ہیں۔ آپ مطلئے علیم نے فرمایا: ” تم اس کا رنگ کیوں نہیں بدلتے؟ تو کسی نے کہا: وہ اسے پسند نہیں کرتے۔ آپ نے فرمایا: ”مگر تم ضرور اس رنگ کو بدلو لیکن سیاہ رنگ سے بچو۔ یہ حدیث سعد بن اسحاق سے ابن لھیعہ ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد: ٥/ ١٦٠ سنده حسن۔","f":"(١) معلوم ہوا کہ یہودیوں کی مخالفت کرنی چاہیے ان کے طریقوں کو نہیں اپنانا چاہیے۔\n(٢) اسی طرح سیاہ خضاب سے اپنے بالوں کو رنگنا جائز نہیں ہے۔ جیسا کہ سیدنا جابر رضی اللہ عنہ فرماتے ہیں کہ فتح مکہ والے دن سیدنا ابو بکر رضی اللہ عنہ کے والد سیدنا ابو قحافہ ضل الله ( ان کا نام عثمان بن عامر تھا) کو رسول اللہ لے سین کی خدمت میں پیش کیا گیا، ان کا سر اور داڑھی سفیدی میں ثغامہ (بوٹی) کی طرح تھی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس کے سفید بالوں کو بدل دو اور ان کو سیاہ کرنے سے بچو۔“ (صحیح مسلم، كتاب اللباس والزينة، رقم: ٢١٠٢)"}],[143,"سیدنا بریدہ بنی امیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اگر داؤد علی نام کا رونا رضی اور ساری زمین والوں کا رونا اکٹھا سیدنا آدم علینا کے رونے کے برابر رکھا جائے تو آدم علیندا کے رونے کے برابر نہیں ہو سکتا۔“ یہ حدیث مسعر سے احمد بن بشیر ہی روایت کرتے ہیں، اسے روایت کرنے میں بیٹی بن سلیمان اکیلے ہیں۔ ١٤٤","",{"k":"مصنف ابن ابی شیبه (٨/٢٩٨)۔"}],[144,"سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ! ہم امر بالمعروف اور نہی عن المنکر کب ترک کر دیں گے حالانکہ یہ نیکی کے اعمال کے سردار ہیں؟ آپ نے فرمایا: ”جب تمہیں وہ چیز پہنچ جائے گی جو بنی اسرائیل کو پہنچی تھی۔ میں نے عرض کیا: یا رسول اللہ! بنی اسرائیل کو کیا چیز پہنچی تھی؟ آپ نے فرمایا: ” جب تمہارے اچھے لوگ برے لوگوں کے ساتھ نرم رویہ اختیار رکھیں گے، دین کی سمجھ اور علم برے لوگوں میں چلا جائے گا اور اختیار و حکومت ذلیل اور گھٹیا لوگوں میں چلا جائے گا۔ تو اس وقت فتنہ تمہیں شبہے میں ڈال دے گا تم اس پر ٹوٹ پڑو گے اور وہ تم پر ٹوٹ پڑے گا۔“ یہ حدیث اعمش سے صرف عمار بن سیف ہی روایت کرتے ہیں اور عمار سے صرف ابوسعید تعلمی ہی روایت کرتے ہیں، اسے روایت کرنے میں یحی بن سلیمان الجعفی اکیلے ہیں۔ ١٤٥","",{"k":"الْجُعْفِيُّ . مجمع الزوائد (٢٨٦/٧)، سنده ضعيف . عنہ۔"}],[145,"سيدنا حذیفہ بن یمان رضی اللہ عنہ نے بیان کیا جبریل عالی سلام نبی صلی اللہ علیہ وسلم کے پاس آئے اور کہنے لگے: اے محمد صلی اللہ علیہ وسلم! میری طرف آپ سے زیادہ محبوب نبی کبھی نہیں ہوا جن کی طرف میں بھیجا گیا ہوں کیا میں آپ پر اللہ تعالیٰ کے ناموں میں سے کچھ نام نہ بتاؤں جو اسے اس کے ان تمام ناموں سے زیادہ محبوب نام ہیں جن سے اس کو پکارا جائے۔ یوں کہو: ((يَا نُورَ السَّمَوَاتِ وَالْأَرْضِ يَا زَيْنَ السَّمَوَاتِ وَالْأَرْضِ يَا جَبَّارَ السَّمَوَاتِ وَالأَرْضِ يَا عِمَادَ السَّمَوَاتِ وَالْأَرْضِ يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا قَيُّوْمَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا صَرِيخَ الْمُسْتَصْرِحِيْنَ وَيَا ١١٠٩١ غِيَاثَ الْمُسْتَغِيْثِيْنَ وَمُنْتَهَى الْعَابِدِينَ الْمُفْرِجَ عَنِ الْمَكْرُو بِيْنَ الْمُرَوَّحَ عَنِ الْمَعْصُومِينَ وَمُجِيبَ دُعَاءِ الْمُضْطَرِيْنَ وَكَاشِفَ الْكَرْبِ وَيَا إِلَهَ الْعَالَمِيْنَ وَيَا أَرْحَمَ الرَّاحِمِيْنَ تَزُولُ بِكَ كُلُّ حَاجِةٍ )) اے آسمانوں اور زمین کے نوراے آسمانوں اور زمین کی زینت اور آسمانوں اور زمینوں کے زبر دست اے آسمانوں اور زمین کو قائم رکھنے والے! اے آسمانوں اور زمینوں کو بنانے والے اے بزرگی اور عزت والے، اے مدد مانگنے والوں کے مددگار، اے کشادگی اور مدد طلب کرنے والوں کی کشادگی اور مدد دینے والے اور اے عبادت کرنے والوں کے پہنچنے کی آخری جگہ۔ اے مصیبت زدوں کی مصیبت کھولنے والے، اے معصوموں کو آرام دینے والے، اے مجبوروں کی دعاء قبول کرنے والے، اے مصیبت کھو لنے والے، اے جہانوں کے معبود، اے تمام رحم کرنے والوں سے زیادہ رحیم! ہر ایک ضرورت تیرے ذریعے ہی پوری ہوتی ہے۔“ یہ حدیث منصور سے صرف سلام بن سلم روایت کرتے ہیں، اسے روایت کرنے میں محاربی اکیلے ہیں۔","",{"k":"متروك . مجمع الزوائد: ١٠/ ١٧٨ سنده ضعيف فيه سلام بن مسلم الطويل وهو۔"}],[146,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، سیدنا خالد بن ولید رضی اللہ عنہ نے نبی اللے تعلیم کے پاس اپنی رات کی بیداری کی شکایت کی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم اپنے بستر پر جاؤ تو یہ دعا پڑھو: ((اللَّهُمَّ دنده رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظَلَّتْ وَرَبُّ الْاَرْضِينَ السَّبْعِ وَمَا أَقَلَّتْ وَرَبِّ الرِّيَاحِ وَمَا أَذَرَّتْ كُنْ لِيْ جَاراً مِّن شَرِّ خَلْقِكَ)) ”اے اللہ! ساتوں آسمانوں اور اس چیز کے رب جس پر انہوں نے سایہ کیا۔ اور سات زمینوں کے پروردگار اور اس چیز کے رب جو انہوں نے اٹھا رکھی ہے۔ اور ہواؤں کے رب اور جو انہوں نے اڑا دیا۔ اپنی مخلوق کی برائی سے میرا ہمسایہ بن جا۔“ یہ حدیث عالقمہ سے صرف حکیم بن ظہیر ہی روایت کرتے ہیں۔","",{"k":"السنن الكبرى للبيهقي (٢٥٢/٥)، معرفة الاثار للطحاوی:٢٢/٦ سنده ضعیف۔"}],[147,"سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: زمین پر جو بھی مسلمان مرد اللہ سے کوئی دعا کرے تو اللہ تعالیٰ اس کو ضرور وہ چیز دے دیتا ہے یا اس سے اتنی برائی مٹا دیتا ہے۔ بشرطیکہ وہ گناہ یا قطع رحمی کی دعا نہ ہو جب تک وہ جلدی نہ کرے۔“ صحابہ نے سوال کیا: یا رسول اللہ سے یہ جلدی کرنا کس طرح ہوتا ہے؟ آپ نے فرمایا: ” کہ وہ یوں کہے: میں نے دعا کی، دعا کی اور وہ قبول نہ ہوئی۔ لوگوں میں سے ایک شخص بولا۔ یا رسول اللہ صلی اللہ علیہ وسلم تب تو ہم بہت سا اجر سمیٹ لیں گے؟ آپ نے فرمایا: ”اللہ کے پاس بہت زیادہ ہے۔“ (١) مذکورہ حدیث سے معلوم ہوا کہ دعا کی وجہ سے گناہ معاف ہو جاتے ہیں اور جائز حاجات اللہ تعالیٰ پوری فرماتے ہیں۔ (٢) یہ بھی معلوم ہوا کہ رشتہ داری کو توڑنے والے کی دعا قبول نہیں ہوتی جیسا کہ ایک اور حدیث میں ہے کہ رسول اللہ میم نے فرمایا کہ: \"مسلمان جب دعا کرتا ہے تو اللہ تعالیٰ اس کی دعا کو قبول کرتا ہے بشرطیکہ اس کی دعا میں گناہ اور رشتہ داری کو توڑنا نہ ہو۔ (مسند احمد: ١٨/٣، اسناده صحیح (٣) یہ بھی معلوم ہوا کہ جلد باز کی بھی دعا قبول نہیں ہوتی۔","",{"k":"مصنف ابن ابی شیبه (٢٤/٧)، مشکل الآثار (٢/٣٦٥، ٨٣٦)۔"}],[148,"سیدنا ابو ایوب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کسی مومن کی جان لے لی جاتی ہے اسے اللہ کے بندوں میں سے رحمت والے لوگ ملتے ہیں جس طرح تم اہل دنیا سے خوش خبری دینے والے سے ملاقات کرتے ہو تو وہ کہتے ہیں اپنے ساتھی کو مہلت دو کہ یہ کچھ آرام کرے کیونکہ وہ سخت تکلیف میں ہے پھر وہ اس سے سوال کرتے ہیں فلاں شخص کا کیا حال ہے اور فلاں عورت کا کیا حال ہے کیا اس نے شادی کی ہے اور جب وہ اس سے ایسے شخص کے متعلق سوال کرتے ہیں جو اس سے پہلے فوت ہو گیا ہو تو وہ کہتے ہیں دوری ہو وہ تو مجھ سے پہلے فوت ہو گیا تھا تو وہ کہیں گے ((إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ)) ہم اللہ کے لیے ہیں اور ہم اسی کی طرف لوٹنے والے ہیں۔“ اس کو تو اپنی ماں ہاویہ کی طرف لے جایا گیا ہے وہ بری ماں ہے اور بری پالنے والی ہے اور آپ نے فرمایا: تمہارے اعمال اپنے قریبی رشتہ داروں پر اور اہل آخرت سے تمہارے قبیلے والوں پر پیش کئے جاتے ہیں۔ اگر اچھے ہوئے تو وہ خوش اور بشارت حاصل کرتے ہیں اور کہتے ہیں اے اللہ! یہ تیرا فضل اور تیری رحمت ہے تو اس پر اپنی نعمت پوری کر اور اسی پر اسے موت دے۔ اور برے آدمی کا عمل بھی ان پر پیش کیا جاتا ہے تو وہ کہتے ہیں: اے اللہ! اس کی نیک عمل کی طرف راہنمائی کر جس سے تو اس پر راضی ہو اور اسے اپنے قریب کر لے۔ یہ دونوں حدیثیں مکحول سے صرف زید بن واقد اور ہشام بن غاز ہی روایت کرتے ہیں، ان دونوں سے مسلمہ بن علی روایت کرنے میں اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني: ٤ / ١٧٦ سنده ضعيف . هذا۔"}],[149,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: ”اللہ تبارک و تعالیٰ فرماتا ہے: میرے بندوں میں سے مجھے سب سے زیادہ پیارے وہ ہیں جو ( وقت ہو جانے پر ) ان میں سے جلد روزہ افطار کریں۔ یہ حدیث زبیدی سے صرف سلمہ بن علی ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی (٧٠٠)، ضعيف الجامع الصغير (٤٠٤١)۔","f":"مذکورہ روایت سنڈا کمزور ہے تاہم روزہ جلدی افطار کرنے کی فضیلت دیگر احادیث سے ثابت ہے جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”لوگ ہمیشہ خیر و عافیت سے رہیں گے۔ جب تک روزہ افطار کرنے میں جلدی کریں گے۔“ (صحیح بخاری، کتاب الصوم، رقم: ١٩٥٧) ایک حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” لوگ روزہ افطار کرنے میں جب تک جلدی کرتے رہیں گے، دین غالب رہے گا۔ یہود و نصاری تاخیر سے افطار کرتے ہیں۔“ (صحیح ابو داؤد، رقم: ٢٠٦٣) معلوم ہوا کہ تاخیر سے افطار کرنا یہود و نصاریٰ کا طریقہ ہے۔ حافظ ابن حجر رحمہ اللہ فرماتے ہیں: اس زمانے میں جو منکر بدعات ایجاد کر لی گئی ہیں ان میں یہ بھی ہے کہ لوگوں نے افطار میں تاخیر اور سحری میں جلدی کی ہے جو کہ سنت کی مخالفت ہے یہی وجہ ہے کہ ان میں خیر کم اور شر زیادہ ہے۔ (فتح الباری: ١٩٩/٤) ١٥٠"}],[150,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو توں میں نماز ادا کرنا نماز کے پورا ہونے سے ہے۔ یہ حدیث مغیرہ سے صرف علی بن عاصم ہی روایت کرتے ہیں، اسے روایت کرنے والے موسیٰ بن ابی سہل اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم جوتوں میں نماز پڑھنا درست ہے جیسا کہ رسول اللہ علئے علیم نے فرمایا: ”یہود کی مخالفت کرو یہ لوگ اپنے جوتوں یا موزوں میں نماز نہیں پڑھتے۔“ ·:١٥١ (سنن ابو داؤد، رقم: ٦٥٢، اسناده صحيح معلوم ہوا کہ جوتوں میں نماز پڑھنا درست ہے۔","",{"k":"مجمع الزوائد: ٢/ ٥٤ سنده ضعيف۔"}],[151,"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ نبی صلی اللہ علیہ وسلم نے سیدہ حفصہ منی اشیا کو طلاق دے دی تو لوگ اس سے غم زدہ ہو گئے۔ ان کے ماموں سیدنا عثمان بن مظعون نیلی ہے اور ان کے بھائی قدامہ ان کے پاس گئے وہ دونوں ان کے پاس ہی تھے اور غمگین تھے کہ رسول اللہ ٹی ایم سیدہ حفصہ بنی نیوبا کے پاس آئے اور فرمانے لگے: حصہ علیا للعجبا ابھی ابھی میرے پاس جبریل عالی اسلام آئے اور کہنے لگے سیدہ حفصہ منی اشیا سے رجوع کرلو کیونکہ یہ بڑی روزہ دار اور رات کو قیام کرنے والی ہے اور یہ جنت میں بھی آپ کی بیوی ہوگی۔“ یہ حدیث شعبہ سے بیٹی بن ابی بکیر ہی روایت کرتے ہیں، اسے روایت کرنے میں موسیٰ بن ابی سہل اکیلے ہیں۔ نا مذکورہ حدیث سے معلوم ہوا کہ، طلاق کے بعد رجوع کیا جا سکتا ہے یہ رجوع کا حق پہلی","",{"k":"السلسلة الصحيحه (٥/٦، ٢٠٠٧)، ٤٣٥١ : صحيح الجامع، رقم۔","f":"اور دوسری طلاق کے بعد عدت کے دوران ہے۔ (الطلاق: ٢) سیدہ حفصہ بنی النجپا کے رجوع کا حکم اللہ تعالیٰ نے دیا ہے۔ مذکورہ حدیث سے سیدہ حفصہ بنی اشیا کی شان کا بھی اثبات ہے۔ نبی معظم ملت علی ایم نے طلاق کیوں دی تھی؟ اس لیے کہ سیدہ حفصہ بنی ہوا کی طبیعت میں تھوڑی سی سختی تھی۔ / /٥/٥"}],[152,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تین طرح کی بیماری والوں کی بیمار پرسی نہیں کی جاتی (١) جس کی آنکھ دکھ رہی ہو (٢) ڈاڑھ درد والا (٣) پھوڑے والا۔“ یہ حدیث اوزاعی سے صرف مسلمہ بن علی ہی روایت کرتے ہیں۔","",{"k":"ضعيف الجامع الصغير (٢٥٦٦)، المعجم الكبير (١٩/١٠٦)۔"}],[153,"سیدنا انس ولی اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے یہ آیت اس طرح تلاوت کی الْعَيْنُ بِالْعَيْنِ وَالأنفُ بالانف (رفع کے ساتھ یہ حدیث زہری سے صرف ابوعلی بن یزید اور ابوعلی سے یونس ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن مبارک اکیلے ہیں۔ ١٥٤","",{"k":"سنن ابی داؤد۔"}],[154,"سیدنا بہبر بن حکیم اپنے باپ سے وہ ان کے دادا سے روایت کرتے ہیں کہ نبی ل علم نے کسی الزام میں ایک آدمی کو قید کیا۔ آپ سے اس بارے میں بات کی گئی تو آپ نے اسے چھوڑ دیا۔“ یہ حدیث بہر سے صرف معمر ہی روایت کرتے ہیں۔ انده مذکورہ روایت سے معلوم ہوا کہ کسی شخص پر الزام ہو مگر حقیقت واضح نہ ہو تو اسے حقیقت واضح ہونے تک تحقیق کی غرض سے مختصر وقت کے لیے قید کرنا جائز ہے تاہم قید کا عرصہ بلاوجہ غیر معمولی طور پر لمبا کرنا ( جیسا کہ آج کل معمول ہے ) شرعاً محل نظر ہے اس سے بہت سے مفاسد جنم لیتے ہیں۔","",{"k":"مستدرك حاكم (٢١٤/١، ٤٣٢)۔"}],[155,"سیدنا عقبہ بن عامر رضی اللہ عنہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس پر اللہ تعالیٰ کوئی انعام فرمائے، اور وہ اس کو اگر باقی رکھنا چاہے تو کثرت سے ((لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ)) پڑھے۔ یعنی ” گناہوں سے بچنے اور نیکی کرنے کی طاقت اللہ تعالیٰ کی توفیق کے بغیر حاصل نہیں ہوسکتی۔ “ پھر آپ نے یہ آیت تلاوت فرمائی: ﴿ وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةٌ إِلَّا بِاللهِ» یعنی باغ والوں میں سے ایک نے دوسرے کو کہا جب تو باغ میں گیا تھا تو تو نے ((مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللهِ . )) کیوں نہیں پڑھا؟ یہ حدیث ابن لصعیہ سے صرف خالد بن بیج ہی روایت کرتے ہیں۔","",{"k":"ضعيف الجامع الصغير (٥٤٩١)، مجمع الزوائد (٩٩/١٠)۔"}],[156,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو لوگ دنیا میں نیکی والے ہیں وہ آخرت میں بھی نیکی والے ہوں گے، اور جو لوگ دنیا میں برائی والے ہیں وہ آخرت میں بھی برائی والے ہوں گے۔“ یہ حدیث یونس سے صرف ابن علیہ ہی روایت کرتے ہیں، اسے بیٹی بن خالد بن حیان روایت کرنے میں اکیلے ہیں۔ اندن معروف اچھے اعمال اور اچھے اخلاق کے لیے استعمال کیا جاتا ہے اور منکر برے اعمال اور بُرے اخلاق کے لیے استعمال ہوتا ہے۔ نبی معظم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ”کہ جو شخص دنیا میں اچھے کاموں میں لگے گا، آخرت میں اچھے لوگوں میں شمار ہو گا اور اپنے اعمال کا اچھا بدلہ پائے گا۔ اور اس کے اچھے اعمال ہی اس کے سامنے آئیں گے جو اس کی نجات اور فلاح کا ذریعہ ہوں گے۔ اس کے برعکس جو لوگ دنیا میں برے اعمال اور بُرے اخلاق میں لگے رہتے ہیں، آخرت میں ان کے یہ اعمال ان کے سامنے آئیں گے اور ان کا بدلہ پائیں گے یعنی جو شخص جیسا کرے گا ویسا بھرے گا۔","",{"k":"مسند الشهاب (١/٢، ٢٩١)، دلائل النبوة للبيهقي (٣٤١/٦، ٢٤٠٨)۔"}],[157,"سیدنا علی رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! کیا مہدی ہم میں۔ ہوں گے یا ہمارے غیر سے؟ آپ نے فرمایا بلکہ ہم سے ہوں گے جس طرح اللہ تعالیٰ نے ہم سے اس کا افتتاح کیا اسی طرح ہم پر یہ سلسلہ ختم ہو گا اور ہمارے ذریعے شرک سے بچائے جائیں گے، اور کھلی عداوت کے بعد ہماری وجہ سے اللہ تعالیٰ ان کے دلوں میں الفت ڈالے گا، جس طرح شرک کی عداوت کے بعد ہماری وجہ سے اللہ نے ان کے دلوں میں الفت ڈالی۔ سیدنا علی رضی اللہ عنہ نے کہا: کیا وہ مومن ہوں گے یا کافر؟ آپ نے فرمایا: ” فتنے میں ڈالے گئے کافر ہوں گے۔“ یہ حدیث ابی زرعہ عمرو بن جابر سے ابن لھیعہ ہی روایت کرتے ہیں، اُن سے روایت کرنے میں محمد بن سفیان اکیلے ہیں۔","",{"k":"مجمع الزوائد (٣١٧/٧)، فيه عمرو بن جابر كذاب۔","f":"مذکر وہ روایت موضوع ہے۔"}],[158,"سیدنا عبد اللہ بن سلام فی الی رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ سے قیامت کی پہلی شرطوں کے متعلق پوچھا گیا تو آپ نے فرمایا: ” قیامت کی پہلی شرط یہ ہے کہ مشرق سے ایک آگ نکلے گی جو لوگوں کو مغرب کی طرف جمع کرے گی۔ یہ حدیث حمید سے صرف ابو خالد الاحمر روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ قیامت کی پہلی نشانیوں میں سے آگ ہے جو مشرق سے نکلے گی تو مغرب کی جانب لوگوں کو جمع کرے گی۔ یعنی یہ یمن کے شہر عدن سے آگ نکلے گی جو پوری دنیا میں پھیل جائے گی اور لوگوں کو محشر کی طرف جمع کرے گی جو لوگ محشر کو بھاگ رہے ہوں گے ان کی تین اقسام ہوں گی: پہلی قسم، جو سوار ہو کر مشرق سے بھاگ رہے ہوں گے۔ دوسری قسم، جو کبھی سوار ہوں گے اور کبھی گریں گے۔ جب کہ تیسری قسم وہ ہو گی جسے آگ ہانکے گی اور پیچھے رہ جانے والوں کو تلف کر دے گی یہاں تک کہ لوگ محشر میں جمع ہو جائیں گے۔ ١٥٩","",{"k":"المعجم الكبير للطبراني (١٨/٤٢٢)، مجمع الزوائد (١٣/٨)۔"}],[159,"سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے عید الفطر اور عید الاضحیٰ کی رات میں نماز ادا کی تو جس دن دل مر جائیں اس دن اس کا دل نہیں مرے گا۔“ یہ حدیث ثور سے صرف عمر بن ہارون ہی روایت کرتے ہیں، اسے روایت کرنے میں جریرا کیلے ہیں۔ مذکورہ روایت موضوع ہے۔","",{"k":"السلسة الضعيفه (٢/٩٧، ٥٢٠)، سنن ابن ماجه (١٧٨٢)۔"}],[160,"سیدنا عبد اللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میری امت جب اسے پل صراط پر لایا جائے گا تو اس کا شعار ہو گا: ((يَا لَا إِلَهَ إِلَّا أَنْتَ)) ہوگا اے وہ ذات! جس کے سوا کوئی معبود نہیں۔“",""],[161,"سیدنا عبد اللہ بن عمر و ضیا المیہ سے روایت ہے کہ رسول اللہ علی اسلام نے فرمایا: ”جو شخص کھجور پسند کرتا ہے اللہ اسے پسند کرتا ہے۔“ یہ حدیث عبد اللہ بن عمرو سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں یحییٰ بن خالد بن حیان اکیلے ہیں۔ الله روو","",{"k":"ضعيف الجامع (١٧٢٦)، المعجم الكبير للطبراني (٩٠/٢٠)۔"}],[162,"عامر شعمی کہتے ہیں: میں نے سیدنا عبد اللہ بن عباس اور سیدنا عبد اللہ بن عمر فی الشیبا سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز رات میں کیسے ہوتی تھی؟ انہوں نے کہا: آپ تیرہ رکعت پڑھتے تھے آٹھ رکعتیں اور تین وتر پڑتے اور دو رکعتیں فجر ہونے کے بعد پڑھتے۔ عامر شعمی کہتے ہیں میں مدینے آیا تو نبی صلی اللہ علیہ وسلم کی رات کی نماز کے متعلق پوچھا تو سب تیرہ رکعت پر متفق تھے جن میں ( تین ) وتر اور دو رکعت فجر سے پہلے کی بھی تھیں۔“","",{"k":"المعجم الكبير للطبراني (٢٣٨/١٠، ٢٤٠٤)۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے کہ قیام اللیل گیارہ رکعتیں ہیں جیسا کہ سیدہ عائشہ بنی شیبا سے روایت ہے کہ رسول اللہ علی علیکم رمضان اور غیر رمضان میں گیارہ رکعات سے زیادہ نہیں پڑھتے تھے۔ (صحیح بخاری، کتاب الصوم، ابواب التراويح، رقم: ١١٤٧) قیام اللیل، قیام رمضان، نماز تہجد اور نماز تراویح ایک ہی نماز کے مختلف نام ہیں۔ یہ بھی معلوم ہوا نماز تراویح گیارہ رکعات ہے (جن میں سے آٹھ نفل ہیں اور باقی تین وتر ) امام مالک اللہ اسی کے قائل ہیں جبکہ امام احمد رحمہ اللہ، امام شافعی اللہ اور امام ابو حنیفہ ہمالہ کا موقف یہ ہے کہ نماز تراویح بیس رکعات ہیں۔ (المغنى: ٦٠٤/٢ - عمدة القارى: ٢٠١/٩ - تحفة الاحوذي: ٢٠٨/٣) انہوں نے جن روایات سے استدلال کیا ہے ان میں سے کوئی بھی ضعف سے خالی نہیں۔ (تحفة الاحوذى: ٦١٢/٣ لہذا پہلا موقف راجح ہے۔ امام شوکانی جماللہ اور مولانا عبد الرحمان مبارکپوری ہاللہ نے بھی اسی کو ترجیح دی ہے۔ (نیل الاوطار: ٢٦٩/٢ - تحفة الاحوذى: ٦٠٨/٣) مذکورہ حدیث سے یہ بھی معلوم ہوا کہ فجر کی دو سنتیں نماز فجر سے پہلے پڑھنی ہیں۔ ١٦٣"}],[163,"سیدہ عائشہ منی یا تنہا سے روایت ہے کہ میں رسول اللہ صلے سم کے کپڑے سے منی کھرچ دیا کرتی تھی۔ (ایک دوسری روایت میں ہے) سیدہ عائشہ بنی الجھا کہتی ہیں: میں منی کو کھرچ دیتی تھی اور اپنی انگلی سے ہتھیلی پر کیا اور اسے کہا کہ اس طرح کھر چتی تھی یعنی نبی صلی اللہ علیہ وسلم کے کپڑے سے۔ اسی طرح مسعر سے ابو عنبس سے، انہوں نے قاسم سے، انہوں نے حضرت عائشہ فنی اہلیہ سے روایت ہے اور ہم کو نہیں معلوم کہ مسعر حفص بن سلم سے روایت کرتے ہیں۔ ابونعیم نے اسے ابو منبس سے روایت اور مسعر کی اس اسناد میں مخالفت کی ہے۔ ایک حدیث میں ہے کہ سیدہ عائشہ بنی النھا فرماتی ہیں رسول اللہ نے تم اپنے کپڑے","",{"k":"صحيح مسلم (٢٨٨)، سنن ابو داؤد (٢٧١)، المعجم الكبير للطبرانی (٥٣/١، ٤٩)۔","f":"سے ) منی کو دھویا کرتے تھے پھر اسی کپڑے میں نماز کے لیے نکلتے اور میں اس (کپڑے) میں دھونے کا نشان دیکھ رہی ہوتی تھی۔ (صحیح بخاری، کتاب الوضوء، رقم: ٢٢٩) ان روایات سے معلوم ہوا کہ اگر کسی کے کپڑے کو منی لگ جائے تو اسے چاہیے کہ دھو کر اسے صاف کرے۔ اگر خشک ہو چکی ہو تو صرف اسے کھرچ دینا ہی کافی ہے۔ فقہاء نے انہی احادیث سے استدلال کرتے ہوئے منی کے پاک یا ناپاک ہونے کا حکم لگایا ہے۔ امام ابو حنیفہ اور مالک عبداللہ نے منی کو نا پاک کہا ہے (البتہ امام ابوحنیفہ رحمہ اللہ کا کہنا ہے کہ اگر منی خشک ہو تو بغیر دھوئے محض کھر چنے سے ہی کپڑا پاک ہو جاتا ہے ) انہوں نے اُن تمام احادیث سے دلیل لی ہے جن میں منی کو دھونے کا حکم ہے۔ نیز ان کا کہنا ہے کہ یہ پیشاب کی جگہ سے خارج ہوتی ہے۔ اس لیے ناپاک ہے۔ امام شافعی اور امام احمد عدالت نے کہا ہے کہ منی پاک ہے کیونکہ کھرچنے سے یقینا صحیح طور پر صفائی نہیں ہوتی مگر پھر بھی آپ صلی اللہ علیہ وسلم اس کپڑے میں نماز پڑھ لیتے تھے۔ اگر منی ناپاک ہوتی تو اللہ تعالیٰ بذریعہ وحی اطلاع دے دیتے، جیسا کہ نماز میں جو تیوں پر لگی گندگی کی اطلاع دی تھی۔ (کتاب الام: ١٢٤/١، المغنى: ٤٩٧/٢) ١٦٤"}],[164,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ السلام نے قریش اور انصار میں بھائی چارے کا رشتہ قائم کیا تو سعد بن الربیع اور عبد الرحمن بن عوف رضی اللہ عنہ کو بھائی بھائی بنا یا۔ سعد بن الربیع نی اللہ نے عبدالرحمن بن عوف رضی اللہ عنہ سے کہا: میرا کچھ مال ہے میں اسے اپنے اور تیرے درمیان بانٹتا ہوں اور میری دو بیویاں ہیں ان کو دیکھو جو تمہیں اچھی لگے تو میں اسے طلاق دیتا ہوں تو جب وہ عدت گزار لے تو اس سے نکاح کر لو۔ انہوں نے کہا: اللہ تعالیٰ تیرے اہل و مال میں برکت عطا فرمائے، مجھے بازار کا راستہ بتا دو جب وہ بازار سے واپس آئے تو کچھ کھجور میں اور پنیر بیچا کر لے آئے۔ ( کچھ دنوں بعد ) رسول اللہ صلی اللہ علیہ وسلم نے مجھ پر ایک زرد نشان دیکھا تو پوچھا: ”یہ کیا ہے؟“ میں نے کہا: میں نے انصار کی ایک عورت سے شادی کی ہے۔ آپ نے پوچھا: ”اسے کتنا حق مہر ادا کیا ہے؟ میں نے کہا: ایک گٹھلی کے وزن برابر سونا۔ آپ نے فرمایا: ” ولیمہ کروا گر چہ ایک بکری ہی ہو۔“ (١) جب مہاجرین اپنے وطن مکہ کو چھوڑ کر مدینہ آئے تو بہت پریشان ہونے لگے۔ گھر بار اموال واقارب کے چھوٹنے کا غم تھا۔ نبی معظم ملنے کی ہم نے اس موقع پر انصار اور مہاجرین میں بھائی چارہ قائم کرا دیا۔ جس کی وجہ سے مہاجر اور انصار دونوں آپس میں ایک دوسرے کو حقیقی بھائی سے زیادہ سمجھنے لگے جس کی واضح مثال مذکورہ حدیث میں ہے۔ (٢) مذکورہ حدیث سے معلوم ہوا کہ سیدنا عبد الرحمان بن عوف نیل لینہ نے جو حق مہر دیا وہ کھجور کی ایک گٹھلی کے برابر سونا ( تقریباً سوا تولہ)۔ اس سے ان لوگوں کا رد ہوتا ہے جو کہتے ہیں کہ حق مہر سوا بتیس روپے ہے۔ (انسان کو اپنی استطاعت کے مطابق حق مہر ادا کرنا چاہیے۔) (٣) شادی (یا غم کے موقع پر بھی) قریب و بعید کے عزیز و اقارب کو کسی اہم مقصد کے بغیر جمع کرنا کوئی سنت نہیں ہے۔ ایک چھوٹی سی بستی میں رہتے ہوئے سیدنا عبد الرحمان بن عوف ولی اللہ کی شادی ہوئی اور رسول اللہ صلی اللہ علیہ وسلم کو خبر بھی نہیں دی گئی۔ (٤) معلوم ہوا کہ اصل سنت ولیمہ ہے۔ حسب استطاعت جو میسر آئے بکری ہو یا کم و بیش کچھ اور جیسا کہ سیدنا انس رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ مال یتیم کا ایک ولیمہ کھایا جس میں روٹی تھی نہ گوشت (راوی کہتے ہیں کہ ) میں نے پوچھا: اے ابو حمزہ! (سیدنا انس رضی اللہ عنہ کی کنیت تھی ) پھر وہ کیا چیز تھی؟ انہوں نے کہا: کھجوریں اور سنو۔ (دیکھئے آئندہ حدیث ) لیکن اس اعتبار سے دیکھا جائے تو ہماری شادیاں، سراسر اسلامی تعلیمات کے خلاف ہیں۔ مثلاً لمبی چوڑی بارا تیں اور پھر ان کی پر تکلف ضیافت۔ اسی طرح ویسے میں انواع و اقسام کے کھانوں کی بھر مار اور دیگر رسومات ہیں۔ اسراف و تبذیر اور فضولیات کی اسلام میں کوئی گنجائش نہیں۔ ١٦٥","",{"k":"صحیح بخاری کتاب البيوع (٢٠٤٩)، سنن ابو داؤد (٣٧٤٤)۔"}],[165,"سیدنا انس رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کا ایک ولیمہ کھایا جس میں روٹی تھی نہ گوشت۔ میں نے کہا: اے ابوحمزہ! پھر وہ کیا چیز تھی؟ انہوں نے کہا: کھجوریں اور ستو “ یہ دونوں حدیثیں یحیی بن سعید سے سلیمان بن بلال ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١/٣٠٦، ٧٢٨)، مسند احمد (٢٦٦/٣)، رقم: ١٣٨٣٢ قال الالبانی صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ ولیمہ کرنا مسنون ہے اور جو میسر ہو وہ پیش کر دینا چاہیے ضروری نہیں کہ گوشت ہی"}],[166,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”آگ پر پکی ہوئی چیز ( کھانے ) سے وضو کرو","",{"k":"الله و صحیح مسلم، مما ست النار (٣٥٢)۔"}],[167,"في الے علم کی زوجہ محترمہ سیدہ ام حبیبہ علی الجھا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو آگ پر پکی ہوئی چیز (کھانے ) سے وضو کرنے کا حکم فرماتے ہوئے سنا۔“ زہری فرماتے ہیں: ابوسفیان، راوی حدیث ام حبیبہ کی بہن کے بیٹے تھے۔ یہ دونوں حدیثیں بکر بن سوارہ سے صرف جعفر بن ربیعہ ہی روایت کرتے ہیں۔","",{"k":"قَالَ الزُّهْرِيُّ: وَأَبُو سُفْيَانَ: ابْنُ أُخْتِ أُمِّ حَبِيبَةَ . لَمْ يَرْوِ هَذَيْنِ الْحَدِيثَيْنِ عَنْ بِكْرِ بْنِ سَوَادَةَ إِلَّا جَعْفَرُ بْنُ رَبِيعَةَ . السنن الكبرى للبيهقي (١/١٣٢)، سنن نسائی (١٧٣)، قال الالباني صحيح۔"}],[168,"سیدہ عائشہ اور سیدہ ام سلمہ نیلی انجا روایت کرتی ہیں کہ رسول اللہ علیم جنبی حالت میں صبح کرتے اور پھر (غنسل کیسے بغیر ) روزہ رکھتے۔“ یہ حدیث عراک بن مالک سے جعفر بن ربیعہ ہی روایت کرتے ہیں۔","",{"k":"وور سنن ابی داؤد (٢٣٨٨)، قال الالبانی صحیح۔"}],[169,"سیدہ عائشہ نیا نہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم اپنی ازواج مطہرات میں سے جنبی حالت میں صبح کرتے پھر آپ اس دن روزے کی حالت میں صبح کرتے۔“ یہ حدیث عبد اللہ بن ابی سلمہ سے صرف ابوز بیر ہی روایت کرتے ہیں اور ابوزبیر سے خالد بن یزید ہی روایت کرتے ہیں، اسے روایت کرنے میں بکر بن مضرا کیلے ہیں۔","",{"k":"تقدم تخريجه انظر (١٦٨)۔","f":"ان احادیث سے معلوم ہوا کہ اگر حالت جنابت میں صبح ہو جائے تو روزہ درست ہے۔ جمہور علماء اور امام نووی اللہ وغیرہ اسی کے قائل ہیں۔ (نیل الاوطار: ١٨٦/٣) نیز جس روایت میں ہے کہ جسے حالت جنابت میں فجر ہو جائے وہ روزہ نہ رکھے۔ (صحيح مسلم، کتاب الصيام، رقم: ١١٠٩) اس کے متعلق امام ابن منذر جماللہ نے کہا ہے کہ اس حدیث کے متعلق سب سے اچھی بات جو میں نے سنی ہے وہ یہ ہے کہ یہ منسوخ ہو چکی ہے۔ حافظ ابن حجر اللہ اور امام شوکانی اللہ بھی اسی کے قائل ہیں۔ (شرح مسلم للنووى: ٤٤٣/٤ نيل الاوطار: ١٨٦/٣) مذکورہ حدیث سے معلوم ہوا کہ رمضان کی راتوں میں بیوی سے ہم بستری مباح و درست ہے۔"}],[170,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ نبی تعلیم نے فرمایا: ”میں تمام رسولوں کا راہنما ہوں، اور اس میں کوئی فخر نہیں اور میں آخری نبی ہوں، اس میں بھی کوئی فخر نہیں، میں پہلا سفارش کرنے والا ہوں، اور پہلا شخص ہوں جس کی سفارش قبول کی جائے گی اور اس میں بھی کوئی فخر نہیں۔“ یہ حدیث عطاء سے صرف صالح بن عطاء ہی روایت کرتے ہیں اور صالح سے جعفر بن ربیعہ ہی روایت کرتے ہیں، اسے روایت کرنے میں بکر بن مضرا کیلے ہیں۔ اند مذکورہ حدیث سے معلوم ہوا کہ نبی معظم ملنے ہی تمام انبیا لاسلام سے افضل ہیں لیکن ایسا","",{"k":"الزوائد: ٢٥٤/٨ سنده جيد . السنن دارمی، المقدمة (٤٩)، سنن ابو داؤد، رقم : (٤٦٧٣)، مجمع۔","f":"انداز نہیں اختیار کیا کہ جس سے دوسرے انبیا علیل سے کام کی تنقیص ہو یا کوئی تقابل ہی سامنے آئے۔"}],[171,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جامع مسجد میں ایک فرض نماز اس حج کے برابر ہے جو ہر قسم کے گناہ اور لغو سے پاک ہو، اور نفل نماز حج مقبول کی طرح ہے۔ اور جامع مسجد میں پڑھے گئی نماز کو اس کے علاوہ دیگر مساجد کی بہ نسبت پانچ سو نماز پر فضیلت دی گئی ہے۔“ یہ حدیث نافع سے عطاء ہی روایت کرتے ہیں اور عطاء سے نوح بن ذکوان روایت کرتے ہیں، اسے روایت کرنے میں زہیر بن عباد کیلے ہیں۔ .١٧٢","",{"k":"ضعيف الجامع الصغير (٣٥٦٨)، المعجم الكبير للطبراني (١١/١٤٧)، السلسلة الضعيفة (٣٨٠٦)۔"}],[172,"\"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو قبلہ رو ہو کر پیشاب کرتے ہوئے دیکھا۔ ابوقتادہ سے یہ حدیث صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"قال الالبانی ضعیف. سنن ترمذی، رقم۔","f":"صحیح روایات سے یہ ثابت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے قبلہ رخ ہو کر پیشاب کیا جیسا کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ میں سیدہ حفصہ نا اہوجا کے گھر ( کی چھت) پر چڑھا تو میں نے نبی مکرم ملنے علم کو شام کی طرف منہ اور کعبہ کی طرف پشت کر کے قضائے حاجت کرتے ہوئے دیکھا۔ (صحیح بخاری، رقم: ١٤٥،صحیح مسلم، رقم: ٢٦٦) سیدنا جابر رضی اللہ عنہ کا بیان ہے کہ نبی معظم صلی اللہ علیہ وسلم نے ہمیں پیشاب کے وقت قبلہ رخ ہونے سے منع فرمایا لیکن میں نے آپ کو آپ کی وفات سے ایک سال پہلے قبلہ کی طرف رخ کرتے ہوئے دیکھا۔ (صحیح ابو داؤد، رقم: ١٠ اسناده حسن) ایک حدیث میں ہے کہ پیشاب وغیرہ کرتے وقت قبلہ کی جانب منہ کرو نہ ہی پیٹھ بلکہ مشرق اور مغرب کی جانب رخ کرلو۔ (صحیح بخاری، کتاب الصلوة، رقم: ٣٩٤) ان روایات میں تطبیق یوں ہے کہ یہ ممانعت کھلی فضا میں ہے عمارت یا تعمیر شدہ بیت الخلا میں نہیں۔ جنہوں نے دیکھا قبلہ کی جانب قضائے حاجت کرتے ہوئے تو انہوں نے فضا میں نہیں بلکہ گھر میں دیکھا تھا۔ سیدنا عبد اللہ ابن عمر رضی اللہ عنہما کے عمل سے بھی اس کی تائید ہوتی ہے۔ مروان اصفر جواللہ بیان کرتے ہیں کہ میں نے سیدنا عبداللہ ابن عمر رضی اللہ عنہما کو دیکھا، انہوں نے قبلہ کی جانب اپنی سواری بٹھائی، پھر اس کی طرف پیشاب کرنے لگے۔ میں نے کہا: اے ابوعبد الرحمان! کیا اس سے منع نہیں کیا گیا تھا؟ انہوں نے کہا: کیوں نہیں لیکن اس عمل سے صرف فضا میں منع کیا گیا ہے اور جب تمہارے اور قبلہ کے درمیان کوئی اوٹ یعنی دیوار وغیرہ حائل ہو تو اس میں کوئی حرج نہیں۔ (صحیح ابو داؤد، كتاب الطهارة، رقم"}],[173,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سات موتوں سے پناہ مانگی (١) اچانک موت (٢) سانپ کے ڈسنے سے (٣) درندے کے کھا جانے سے (٤) غرق ہونے سے (٥) جل جانے سے (٦) کسی چیز پر گرنے یا ان پر کوئی چیز گر جائے (٧) جنگ سے بھاگتے ہوئے قتل ہو جانے سے","",{"k":"مجمع الزوائد: المعجم الكبير للطبراني (٢/٩١)، مسند احمد (٢/١٧١٣١٨/٢)، قال الشيخ شعیب الارناؤط: اسناده ضعيف۔"}],[174,"ابو عبد الرحمن الحبلی روایت کرتے ہیں، انہوں نے رسول اللہ علیم کے آزاد کردہ غلام ثوبان رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں پسند نہیں کرتا کہ مجھے اس آیت کے عوض میں تمام دنیا اور جو کچھ اس میں ہے سب مل جائے: يَا عِبَادِيَ الَّذِيْنَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَّحْمَةِ الله الایہ ”اے میرے بندو! جنہوں نے اپنی جانوں پر زیادتی کی تم اللہ کی رحمت سے نا امید نہ ہونا۔“ ١٧٥","",{"k":"﴾ [الزمر: ٥٣] . )) الآية . ضعيف الجامع الصغير (٤٩٨٠)، السلسلة الضعيفة (٤٤٠٩)، مسند احمد (٥/٢٧٥، ٢٢٤١٦)۔"}],[175,"سیدنا علی بن ربیعہ کہتے ہیں: سیدنا علی رضی اللہ عنہ نے ایک خچر پر مجھے اپنے پیچھے بٹھا لیا۔ انہوں نے اپنا پاؤں رکاب میں ڈالا تو کہا: ((بسم اللهِ )) شروع اللہ کے نام سے۔“ جب اس پر برابر ہو کر بیٹھ گئے تو کہنے لگے: ((الْحَمْدُ لِلَّهِ)) تمام تعریف اللہ کے لیے ہے۔“ جب سب کام مکمل ہو گیا تو کہا: ((الْحَمْدُ لِلَّهِ الَّذِى سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ)) تمام تعریف اس ذات کے لیے ہے جس نے ہمارے لیے اس سواری کو مسخر کر دیا اور ہم اس کو اپنے تابع بنا سکنے والے نہیں تھے، اور بے شک ہم اپنے رب کی طرف ہی لوٹ کر جانے والے ہیں۔ پھر تین دفعہ اللہ تعالیٰ کی تعریف کی پھر تین دفعہ ((الله اكبر ) ) کہا، پھر ((اللَّهُمَّ اغْفِرْ لِي ذَنْبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ )) اے الله! میرے گناہ معاف کر دے تیرے بغیر گناہوں کو کوئی بھی معاف نہیں کرتا۔“ کہا اور ہنسے، تو میں نے عرض کیا: آپ کیوں ہنسے ہیں؟ آپ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھا تو آپ کاسلام نے بھی اسی طرح کیا اور پھر مسکرائے تو میں نے کہا: یا رسول اللہ! آپ کس چیز سے ہنسے ہیں؟ تو آپ نے فرمایا ” میں اللہ رب العزت کے اپنے بندے پر تعجب سے ہنسا ہوں، جو بندہ یہ دعا پڑھتا ہے: ((اللَّهُمَّ اغْفِرْ لِي ذَنْبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ اللہ تعالیٰ فرماتا ہے اس کو معلوم ہے کہ میرے سوا کوئی اور گناہوں کو معاف نہیں کرتا۔‘“ یہ حدیث mer Rangers Zeo شقیق الازدی، شقیق از دی کا نام شقیق بن ابی عبداللہ ہے، سے صرف یونس بن خباب اور یونس سے عبدربہ بن سعید ہی روایت کرتے ہیں، اسے ابن لھیعہ اکیلے ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی، رقم : (٣٤٤٦، ٢٦٠٢)، الدعا للطبراني (٢/٣١٦، ٧١٠)۔","f":"(١) مذکورہ روایت سے معلوم ہوا کہ مذکورہ دعا سفر میں پڑھنا مسنون ہے۔ رگاب، اس آہنی حلقے کو کہتے ہیں جو گھوڑے کی زین میں دونوں طرف لٹکا رہتا ہے جس پر پیر رکھ کر سوار گھوڑے پر چڑھتا ہے پاؤں رکھتے وقت بسم اللہ، اور بیٹھ کر مذکورہ دعائیں پڑھی جائیں۔\n(٢) مذکورہ حدیث سے سیدنا علی رضی اللہ عنہ کا نبی معظم ملنے دین کی اتباع کا جو جذبہ تھا اس کا بھی اثبات ہے۔"}],[176,"سيدنا ابو ہریرہ میل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی شخص اپنی بیوی کے پاس آئے تو پردہ کرے کیونکہ جب وہ پردہ نہیں کرتا تو فرشتے اس سے شرما کر نکل جاتے ہیں اور شیطان آ جاتا ہے جب ان کے درمیان اولاد ( پیدا) ہو گی تو اس میں شیطان حصہ دار ہو گا۔“ یہ حدیث یحیی بن ابی کثیر سے صرف ابوالمنیب الجرشی اور ابوالمنیب سے عبید اللہ بن زحر ہی روایت کرتے ہیں، اسے روایت کرنے میں بیچی بن ایوب اکیلے ہیں۔","",{"k":"السلسلة الضعيفة (٣٣٩/٤، ١٨٤٠)، ضعيف الجامع (٢٧٨)، المعجم الكبير للطبرانی (١٠٨/١٩)۔"}],[177,"سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: \"یقیناً اللہ عز وجل فرماتا ہے: جب میں اپنے بندے کی دو پیاری چیزیں ( آنکھیں) لے لیتا ہوں اور وہ صبر کرتا ہے،اس سے ثواب حاصل کرنے کی نیت رکھتا ہے تو میں ان کے عوض اسے جنت دے دیتا ہوں۔“","",{"k":"المعجم الكبير للطبرانی (١٩/١٠٨)، سنن ترمذی (٢٤٠)، قال الالباني صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ آنکھوں کی تکلیف پر صبر کرنے والا اور اللہ کی رضا پر راضی رہنے والا قیامت کے دن اللہ تعالیٰ کی جنت کا حق دار ٹھہرے گا۔ بلکہ ایک حدیث میں ہے اللہ تعالیٰ فرماتے ہیں کہ میں تیرے لیے ثواب دینے میں جنت کے سوا کسی اور چیز پر راضی نہیں ہوں گا۔ (بخاری، ادب المفرد، رقم: ٥٣٥)"}],[178,"سیدنا ابو ہریرہ فی المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص کسی مسلمان کی کوئی دنیوی مصیبت دور کرتا ہے اللہ تعالیٰ اس کی آخرت کی مصیبتوں میں سے ایک مصیبت دور کر دیتا ہے۔ اور جو شخص کسی مسلمان کی پردہ پوشی کرتا ہے اللہ تعالیٰ قیامت کے روز اس کے عیوب کی پردہ پوشی کرے گا۔ اور جو شخص کسی مسلمان پر آسانی کرتا ہے اللہ تعالیٰ قیامت کے روز اس پر آسانی کرے گا۔ اور اللہ تعالیٰ بندے کی مدد میں رہتا ہے جب تک بندہ اپنے مسلمان بھائی کی مدد میں رہتا ہے۔“ یہ دونوں حدیثیں عبید اللہ بن زحر سے صرف بچی بن ایوب ہی روایت کرتے ہیں، اسے سعید بن ابی مریم روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث میں، مسلمان کی مدد کرنا اور پردہ پوشی کرنے کے ثواب کا تذکرہ ہے۔ فائد","",{"k":"صحيح مسلم (٩٩٠)، صحيح الجامع (٦٢٨٧)، سنن ابی داؤد (٤٨٩٣)۔"}],[179,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بلال کی مثال شہد کی مکھی کی طرح ہے جو صبح سویرے نکلتی ہے اور میٹھا کڑوا سب کھاتی ہے، پھر وہ سارا میٹھا ہو جاتا ہے۔“ یہ حدیث حضرت ابو ہریرہ رضی اللہ عنہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں بیٹی بن ایوب اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٩/١٠٩)، ضعيف الجامع (٥٢٤٨)، السلسلة الضعيفة (٢٠٠٢.١١٠١)۔"}],[180,"سيدنا اسید بن حضیر رضی اللہ عنہ سے روایت ہے کہ ایک دفعہ وہ سورہ بقرہ پڑھ رہے تھے اور ان کا گھوڑا باندھا ہوا تھا تو وہ اپنی رسی میں گھومنے لگا تو انہوں نے اپنا سر اٹھایا تو اچانک انہیں آسمان و زمین کے دمیان قندیل کی مانند کوئی چیز لٹکتی ہوئی نظر آئی۔ وہ صبح نبی صلی اللہ علیہ وسلم کے پاس گئے اور انہیں بتایا۔ تو آپ نے فرمایا: ”اے اسید بن حضیر یہ پڑھتے رہو: کیا تمہیں معلوم ہے یہ کیا تھا؟ یہ سکینت اور تسلی تھی جو تیری آواز کے قریب آئی اگر تم پڑھتے رہتے تو لوگ صبح اسے دیکھ لیتے۔ یہ حدیث از ابوسعید از اسید بن حضیر صرف اسی سند سے روایت کی گئی ہے، اسے روایت کرنے میں بیٹی بن ایوب اکیلے ہیں۔ نان مذکورہ حدیث سے معلوم ہوا کہ قرآن مجید کی تلاوت سننے کے لیے فرشتے آسمان سے","",{"k":"صحیح بخاری (٥٠١٨)۔","f":"نازل ہوتے ہیں۔ جیسا کہ ارشاد باری تعالیٰ ہے: إِن قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا (بنی اسرائیل: ٧٨) فجر کی نماز میں قرآن سننے کے لیے فرشتے حاضر ہوتے ہیں۔“"}],[181,"سیدنا عبد الله بن عمر رضی اللہ عنہ نے بیان کیا، ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے جبکہ ہم فجر کے بعد نماز پڑھ رہے تھے۔ آپ نے فرمایا: \"فجر کے بعد فجر کی دو رکعت کے علاوہ اور کوئی نماز نہیں۔“ یہ حدیث محمد بن ابی ایوب سے صرف عبید اللہ بن زحر ہی روایت کرتے ہیں، اسے روایت کرنے میں یحیی بن ایوب اکیلے ہیں۔","",{"k":"سنن ترمذی (١٩)، قال الالبانی صحیح، سنن ابو داؤد (٢٧٨)۔","f":"مذکورہ روایت سے معلوم ہوا کہ طلوع فجر کے بعد فرضوں سے پہلے صرف دو رکعت سنتیں ہی پڑھی جائیں۔ تاہم رات کے وتر دن چڑھے پڑھنا مشکل ہوں تو اس وقت میں ادا ئیگی جائز ہے۔ جیسا کہ حدیث میں ہے کہ جو شخص وتر کے وقت سویا رہ جائے جب صبح ہو تو وہ وتر پڑھ لے۔ (صحیح سنن ترمذی، رقم: ٣٧٨)"}],[182,"سیدنا عامر بن سعد کہتے ہیں کہ اسامہ بن زید رنا الیہ نے میرے والد سعد رضی اللہ عنہما کو بتایا ایک شخص رسول اللہ لئے تعلیم کے پاس حاضر ہوا تو کہنے لگا میں اپنی عورت سے عزل کرتا ہوں۔ آپ نے فرمایا: ” کیوں؟“ اس نے کہا: بچے پر شفقت کرتے ہوئے تو آپ نے فرمایا: اگر اس لیے کرتے تو نہ کرو۔ یہ تو روم اور فارس کو بھی مضر نہیں۔“ یہ حدیث حضرت اسامہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابونضر اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ حالت رضاعت میں ہم بستری کرنا جائز ہے۔","",{"k":"السنن الكبرى للبيهقى ٤٦٥/٧، صحیح مسلم (٤٤٢)، سنن ابو داؤد، رقم : ٣٨٨٢۔ مسند احمد (٢٠٣/٥، ٢١٨١٨)۔"}],[183,"ابو الزبیر نے بیان کیا، سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے عزل ( بیوی سے جماع کرتے ہوئے انزال کے وقت شرم گاہ باہر نکال لینا تا کہ حمل نہ ہو سکے ) کے متعلق پوچھا گیا تو انہوں نے کہا: ہم یہ کام رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں کرتے تھے تو ہم پر کوئی عیب نہیں لگایا جاتا تھا۔“ یہ حدیث ثور بن زید سے صرف یحیی بن ایوب ہی روایت کرتے ہیں۔","",{"k":"النكاح، رقم :١٤٣٨ . مجمع الزوائد (٤٩/٢)، سنن ابو داؤد (٢١٧٢)، صحیح مسلم۔","f":"مذکورہ حدیث سے معلوم ہوا کہ عزل کرنا جائز ہے لیکن نبی معظم صلی اللہ علیہ وسلم نے اس کو پسند نہیں فرمایا لیکن اس کو ناجائز بھی نہیں کہا۔"}],[184,"سيدنا ابو عبیدہ بن الجراح رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جمعہ کے روز فجر کی نماز باجماعت پڑھنے سے اور کوئی نماز بہتر و افضل نہیں۔ اور میں یہی سمجھتا ہوں کہ جو شخص بھی تم میں سے اس میں حاضر ہو جائے تو اس کو بخش دیا جاتا ہے۔ یہ حدیث ابو عبیدہ سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں بیٹی بن ایوب اکیلے ہیں۔ ٨٥","",{"k":"ضعيف الجامع (٣٩٢٨)، السلسلة الضعيفة (٣/٢٢٠، ١٢٢١)، مجمع الزوائد (٢/١٦٨)۔"}],[185,"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے اچھی طرح وضو کیا، پھر اپنا لباس درست کیا اور پھر مسجد کو نکلا تو اس کے لیے ہر قدم کے بدلے دس نیکیاں لکھی جاتی ہیں اور جب تک وہ نماز کا انتظار کرتا رہتا ہے نماز ہی میں شمار ہوتا ہے اور وہ اپنے گھر سے نکلنے کے وقت سے لے کر گھر واپس جانے تک نمازیوں میں لکھا جاتا ہے۔ یہ حدیث عقبہ بن عامر سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں عمرو بن حارث اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٢/١٦٧)، مسند احمد (٤/١٥٩)، قال الشيخ شعیب الارناؤط: حدیث صحیح۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ مسجد کی طرف چل کر جانا، پھر نماز کا انتظار کرنا بہت بڑا ثواب ہے۔\n(٢) اس میں نماز با جماعت ادا کرنے کی فضیلت بھی ہے، اور اس کی فضیلت کا بیان بھی ہے، کیونکہ ہر قدم کے عوض دس نیکیاں مل جائیں گی۔ ایک حدیث میں ہے کہ ایک قدم گناہ کو مٹائے گا دوسرا قدم درجہ بلند کرے گا۔ (صحیح مسلم، رقم: ٦٦٦) یہ بھی معلوم ہوا کہ نماز کے انتظار کے لیے بیٹھنے کا بہت زیادہ ثواب ہے۔ یہ ثواب گھر واپس پلٹنے تک ہے۔"}],[186,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے رسول اللہ علیم نے فرمایا: \"قل هُوَ اللهُ أَحَدٌ تہائی قرآن کے برابر ہے اور ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ چوتھائی قرآن کے برابر ہے، اور آپ انہیں فجر کی دورکعتوں (سنتوں) میں پڑھا کرتے تھے اور آپ فرماتے: ” ان دو رکعت میں پورے زمانے کی مرغوبات موجود ہیں۔ پہلی حدیث میں قل ھو اللہ احد اور قل یا ایھا الکافرون، لیث سے صرف عبید اللہ بن زحر ہی روایت کرتے ہیں، اسے روایت کرنے میں بیٹی بن ایوب اکیلے ہیں۔","",{"k":"سنن ترمذی (٢٨٩٤)، السلسلة الصحيحة (٥٨٦)۔","f":"(١) مذکورہ روایت میں سورۃ اخلاص اور سورہ کافرون کی فضیلت کا اثبات ہے۔ معلوم ہوا کہ سورہ اخلاص ایک مرتبہ پڑھ لینا اجر و ثواب میں ایک تہائی قرآن پڑھنے کے برابر ہے۔ اس سورت میں اللہ کی تو حید کا بیان اور اس کے کسی کے ہم سر ہونے کی نفی ہے۔ اس سے اندازہ کیا جا سکتا ہے کہ اللہ تعالیٰ کو اپنی توحید کا بیان کتنا پسند ہے۔ اسی طرح سورہ کافرون کی تلاوت کرنے سے یقیناً چوتھائی قرآن مجید کی تلاوت کا ثواب مل جاتا ہے۔ لیکن قرآن مجید کی باقاعدہ تلاوت سے قاری کو جو فوائد حاصل ہوتے ہیں مثلاً ایمان میں اضافہ، تقویٰ اور نیکی میں اضافہ، اللہ کا ڈر پیدا ہونا، جنت کی طلب اور جہنم کی پناہ کی فکر کرنا، اسی طرح دیگر مسائل اور احکام سے آگاہ ہونا وغیرہ۔ ان تمام فوائد سے قاری محروم رہتا ہے پس یہ برابری محض اجر و ثواب کے اعتبار سے ہے باقی امور کے اعتبار سے نہیں۔ واللہ اعلم بالصواب۔\n(٢) مذکورہ حدیث سے معلوم ہوا کہ مذکورہ سورتیں فجر کی سنتوں میں تلاوت کرنا مسنون ہیں۔ اسی طرح قُولُوا آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا» (البقره: ١٣٦) آخر تک اور دوسری میں ﴿أَمَنَّا بِاللَّهِ وَاشْهَدُ بِأَنَّا مُسْلِمُونَ (آل عمران: ٥٢) ایک اور روایت میں ہے کہ دوسری رکعت میں یہ آیت تلاوت کرتے: تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ) (صحیح مسلم، کتاب صلاة المسافرين، رقم: ٧٢٧) یہ بھی معلوم ہوا کہ ایک آیت یا سورت کافی عرصے تک آدمی اس کی تلاوت کر سکتا ہے۔"}],[187,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے حکم فرمایا کہ ہر باغ سے کھجور کا گچھا مسجد کے لیے دیا جائے۔ یہ حدیث عبید اللہ بن عمر سے صرف الدراور دی ہی روایت کرتے ہیں۔ ایک حدیث میں ہے کہ نبی مکرم ملے ایام نے کھجوروں کا پھل توڑنے والے سب لوگوں کو حکم دیا تھا کہ جو کوئی دس وسق کھجور کائے وہ ایک خوشہ مساکین کے لیے مسجد میں لڑکا دیا کرے۔“ (سنن ابو دائود، كتاب الزكاة، رقم: ١٦٦٢) یہ امر ارشاد و استحباب تھا ( وجوب کے لیے نہیں ) عشر اس کے علاوہ ہوتا تھا جو کہ واجب ہے۔","",{"k":"الدراوردي . مجمع الزوائد (٣/٧٧)، المعجم الكبير للطبراني (١١/١٤٨)، صحیح ابن حبان (٣٢٨٨)، قال الشيخ شعیب الارناؤط : رجال ثقات۔"}],[188,"سیدنا ابو ہریرہ رضی اللہ عنہ اور سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ما علیم نے فرمایا: ”علی بن ابی طالب رضی اللہ عنہ کے روز میرے حوض والا ہو گا، اس میں آسمان کے ستاروں کی طرح بہت زیادہ پیالے ہوں گے، اور میرے حوض کی فراخی اور کشادگی اتنی ہے جتنی جابیہ سے صنعاء تک ہے۔“ یہ حدیث موسیٰ بن وردان سے صرف ان کے بیٹے سعید اور سعید سے ابن لھیعہ ہی روایت کرتے ہیں، اسے روایت کرنے میں روح بن صلاح اکیلے ہیں۔","",{"k":"مجمع الزوائد (٣٦٧/١٠)، سنده ضعيف فيه روح بن صلاح وهو ضعيف۔"}],[189,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، جب فاطمہ بنت اسد بن ہاشم ” جو سیدنا علی نا ا ل لینے کی والدہ تھیں فوت ہو گئیں تو نبی صلی اللہ علیہ وسلم ان کے ہاں تشریف لائے، اور ان کے سر کے پاس بیٹھ گئے اور فرمایا: ”اماں جان! اللہ تعالی تم پر رحم کرے میری ماں کے بعد آپ میری ماں تھیں آپ خود بھوکی رہ کر مجھے سیر کر دیتیں، خودنگی رہ کر مجھے لباس پہنا دیتیں۔ خود اچھا کھانا نہ کھاتیں بلکہ مجھے کھلا دیتیں تم اس سے اللہ تعالیٰ کی رضا مندی اور آخرت کے گھر کی فلاح چاہتی تھیں۔ پھر حکم دیا کہ انہیں تین تین بار غسل دیا جائے جب کافور والا پانی پہنچا تو رسول اللہ صلی اللہ علیہ وسلم نے خود اپنے ہاتھ سے اسے ان پر ڈالا۔ پھر آپ نے اپنی قمیص اتار کر انہیں پہنا دی۔ پھر اس کے اوپر انہیں کفن پہنایا گیا۔ پھر آپ نے اسامہ بن زید، ابو ایوب انصاری، عمر بن خطاب بنی اسلیم اور ایک سیاہ غلام کو بلایا کہ وہ ان کی قبر کھو دیں۔ تو انہوں نے ان کی قبر کھودی جب لحد تک پہنچے تو آپ نے اپنے ہاتھ سے کھودی اور اپنے ہاتھ سے مٹی نکالی۔ جب آپ فارغ ہوئے تو اُس کے اندر جا کر لیے اور کہا: ((اللَّهُ الَّذِى يُحْيِي وَيُمِيتُ وَهُوَ حَى لَا يَمُوْتُ اغْفِرْ لَا مِّنْ حَاطِبَةَ بِنْتَ أَسَدٍ وَلَقَتْهَا حُجْتَهَا وَوَسِّعْ عَلَيْهَا مُدْخَلَهَا بِحَقِّ نَبِيِّكَ وَالْأَنْبِيَاءِ الَّذِينَ مِنْ قَبْلِى فَإِنَّكَ أَرْحَمُ الرَّاحِمِينَ . )) الله وه ذات ہے جو زندہ کرتا ہے اور مارتا بھی ہے، اور وہ خود زندہ ہے اسے کبھی موت نہیں آئے گی۔ اے اللہ! میری ماں فاطمہ بنت اسد کو معاف کر دے اور اس کو اس کی دلیل الہام فرما دے۔ اور اس کے داخل ہونے کی جگہ وسیع کر اپنے نبی اور مجھ سے پہلے نبیوں کے حق کے ساتھ تو تمام رحم کرنے والوں سے زیادہ رحم کرنے والا ہے۔“ پھر آپ نے چار تکبیریں کہیں، پھر آپ، عباس اور ابو بکر صدیق خیلی اہلیہ نے انہیں قبر داخل کر دیا۔“ یہ حدیث عاصم الاحول سے صرف سفیان ثوری روایت کرتے ہیں، اسے روایت کرنے میں روح بن صلاح اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (٨٣/١٨)، مجمع الزوائد (٢٥٦/٩)، فيه روح بن صلاحوهو ضعيفٌ۔"}],[190,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ملے ایام سے گمشدہ بکری کے متعلق پوچھا گیا: آپ نے فرمایا: ”وہ تیری یا تیرے کسی دوسرے بھائی کی ہے یا پھر بھیڑیے کی ہے“ اور آپ سے گم ہونے والے اونٹ کے متعلق پوچھا گیا تو آپ نے فرمایا: ”تجھے اس سے کیا سروکار؟ اس پر اس کا پینا اور اس کا جوتا ہے، اسے کھلے چھوڑ دوحتی کہ اس کا مالک آکر اس کو لے جائے۔“ یہ حدیث ابن عجلان سے صرف یحیی بن ایوب ہی روایت کرتے ہیں۔ سامنے آئی ہیں۔ مذکورہ حدیث میں گم شدہ چیزوں کا تذکرہ ہے۔ اور مذکورہ حدیث سے ان کی دو اقسام (١) وہ نقدی، مختلف ساز و سامان اور ایسے جانور ہیں جو درندوں سے اپنی حفاظت نہیں کر سکتے۔ (٢) دوسری قسم ان جانوروں کی ہے جو اپنی حفاظت خود کر سکتے ہیں۔ انہیں نہ تو اٹھانے کی ضرورت ہے اور نہ ہی حفاظت کی مثلاً گمشدہ اونٹ۔ اور اہل علم نے گائے، ہرن اور پرندوں وغیرہ کو بھی اسی پر قیاس کیا ہے کیونکہ وہ ( گائے قوت کے ساتھ، ہرن بھاگ کر اور پرندے اڑ کر ) اپنی حفاظت کر سکتے ہیں۔ پہلی قسم کی جو چیزیں ہیں تو ان کو اٹھا کر سال بھر اس کی تشہیر کرنا چاہیے اگر کوئی معمولی چیز ہے تو اس کو اٹھا کر استعمال کیا جا سکتا ہے تشہیر کرنے کی ضرورت نہیں۔","",{"k":"المعجم الكبير للطبرانی (١٩/١١٠)، صحیح بخاری، مجمع الزوائد (٤/١٦٧)، سنن ابی داؤد (١٧١٢)۔"}],[191,"سیدنا جابر رنا الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے ان سبزیوں سے کوئی سبزی کھائی تو وہ ہماری مسجد کے قریب بھی نہ آئے (١) لہسن (٢) گندنا (٣) پیاز (٤) مولی۔ کیونکہ فرشتے اس چیز سے تکلیف محسوس کرتے ہیں جس سے آدمی تکلیف محسوس کرتے ہیں۔“ یہ حدیث ہشام بن حسان سے صرف یحیی بن راشد ہی روایت کرتے ہیں، اسے روایت کرنے میں سعید بن عفیر اکیلے ہیں۔","",{"k":"صحیح مسلم (٥٦١)، سنن نسائی (٧٠٧)، سنن ابو داؤد (٣٨٢٢)۔","f":"لہسن، گندنا، پیاز، مولی اگر کھائی جائے تو اس سے بڑی ناگوار بو آتی ہے جس سے ساتھ والے لوگ اور فرشتے اذیت محسوس کرتے ہیں، اس لیے اس کیفیت میں مسجد میں آنے سے سختی سے منع کیا گیا ہے۔ اور اس پر قیاس ہے تمباکو اور ایسی سبزیاں جن کے نتیجے میں ناگوار ڈکار آتی ہے۔ اور یہ بھی کہ منہ کو گندہ رکھنا مسواک نہ کرنا انتہائی قبیح عادت ہے۔"}],[192,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے روز ایک بڑا، موٹا آدمی آئے گا مگر اس کا وزن مچھر کے پر کے برابر بھی نہ ہوگا۔ پھر آپ نے یہ آیت پڑھی فلا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزن ”ہم ان کے لیے قیامت کے دن کوئی وزن قائم نہیں کریں گے۔“ یہ حدیث ابوز ناد سے صرف مغیرہ بن عبدالرحمن ہی روایت کرتے ہیں اسے روایت کرنے میں سعید بن ابی مریم","",{"k":"♦، المعجم الكبير للطبرانی (١٩/١١٠)، صحیح بخاری (٤٧٢٩)۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ کافروں کے اعمال کا وزن ہی نہیں ہو گا۔ کیونکہ موحدوں کے اعمال کا وزن ہو گا جبکہ کفار کے اعمال حسنات سے بالکل خالی ہوں گے۔\n(٢) یہ بھی معلوم ہوا کہ قیامت کے دن ترازور کھے جائیں گے جن پر اعمال تو لے جائیں گے۔"}],[193,"سیدنا ابو امامہ بن ثعلبہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے اپنے مالکوں کے علاوہ کسی اور کو اپنا آقا بنا لیا تو اس پر اللہ تعالیٰ، فرشتوں اور تمام لوگوں کی لعنت ہے۔ اللہ تعالیٰ اس کا کوئی نفل قبول کرے گا نہ قرض اور جس نے میرے شہر میں کوئی بدعت ایجاد کی یا کسی بدعتی کو جگہ دی تو اُس پر بھی اللہ تعالیٰ، فرشتوں اور تمام لوگوں کی لعنت ہے اس کی کوئی نفل عبادت قبول ہوگی نہ کوئی فرض۔“ یہ حدیث ابوامامہ بن ثعلبہ سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں عبداللہ بن منیب اکیلے ہیں۔ ان (١) مذکورہ حدیث سے معلوم ہوا کہ غلام کا اپنی نسبت بدل لینا حرام ہے اس کام سے اس","",{"k":"صحیح بخاری (٦٧٥٥)۔","f":"کی عبادت قبول نہیں کی جائے گی۔ (٢) یہ بھی معلوم ہوا کہ مدینہ منورہ میں بدعت پھیلانے والا لعنتی ہے۔ (٣) بدعت اور بدعتی سے نبی عالی سلام کی نفرت بھی واضح ہوئی۔"}],[194,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ بے شک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس نے نماز کے لیے اذان کہنے والے کی اذان سن کر یہ دعا پڑھی تو اللہ تعالیٰ اس کی دعا قبول فرما لیتا ہے: ((اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلوةِ الْقَائِمَةِ صَلَّ عَلَى مُحِمَّدٍ وَارْضَ عَنِّي رِضَاءٌ لَّا سَخَطَ بَعْدَه )) ”اے اللہ! اس پوری پکار کے رب اور کھڑی ہونے والی نماز کے مالک محمد صلی اللہ علیہ وسلم پر درود بھیج اور مجھ سے ایسا راضی ہو جا کہ جس کے بعد ناراضی بالکل نہ ہو۔“ یہ حدیث ابو زبیر سے صرف ابن لھیعہ ہی روایت کرتے ہیں اور حضرت جابر رضی اللہ عنہ سے یہ حدیث اسی سند سے ہی مروی ہے۔ مذکورہ روایت کمزور ہے تا ہم صحیح روایت میں ہے سیدنا جابر فی اللہ سے مروی ہے کہ رسول اللہ علے سلیم نے فرمایا: ”جس نے اذان سن کر یہ دعا کی اس کے لیے روز قیامت میری شفاعت واجب ہو جائے گی: ((اللهم رب هذه الدعوة التامة والصلاة القائمة ات محمد الوسيلة والفضيلة وابعثه مقاما محمودا الذي وعدته (صحیح بخاری، کتاب الاذان، رقم: - سنن ابی داؤد، رقم: ٥٢٩) ”اے اس دعوت کامل اور قائم ہونے والی نماز کے رب! محمد صلی اللہ علیہ وسلم کو وسیلہ اور فضیلت (بلند مرتبہ ) عطا فرما اور انہیں اس مقام محمود پر پہنچا دے جس کا تو نے ان سے وعدہ کیا ہے۔“ اس دعا کے علاوہ نبی معظم عام پر دورد پڑھنا بھی مسنون ہے جیسا کہ ایک حدیث میں ہے رسول اللہ ل علم نے فرمایا: \"جب تم مؤذن کو سنو تو اسی طرح کہو جیسے وہ کہتا ہے پھر مجھ پر درود پڑھو۔“ (صحیح مسلم، رقم: ٣٧٤، سنن ابی داؤد، رقم: ٥٢٣) اسی طرح ایک روایت میں ہے کہ جو اذان سن کر یہ کلمات کہے گا اس کے گناہ بخش دیے جائیں گے:::١٩٥ منجم اوسط طبرانی ١ ((اشهد ان لا اله الا الله وحده لا شريك له وان محمدا عبده ورسوله رضيت بالله ربا وبمحمد رسولا وبالاسلام دينا )) (صحیح مسلم، رقم: ٣٨٦۔ سنن ابی داؤد، رقم: ٥٢٥)","",{"k":"مسند احمد (٣٣٧/٣)، رقم : ١٤٦٥٩ قال الشيخ شعیب الارناؤط: اسناده ضعيف، مجمع الزوائد (١/٣٣٢)، ضعيف الترغيب والترهيب (١٧١)۔"}],[195,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: دجال ایک آنکھ سے کانا ہو گا اور تمہارا رب کانا نہیں ہے۔ اور دجال کی آنکھوں کے درمیان کا فرلکھا ہوا ہو گا جس کو ا مومنوں میں سے ہر کا تب و غیر کا تب سب پڑھ سکیں گے، اس کے پاس جنت اور جہنم دونوں ہوں گی پس اس کی جہنم جنت ہوگی اور اس کی جنت جہنم ہو گی۔“ یہ حدیث حضرت معاذ سے اسی سند سے ہی مروی ہے، بیٹی بن بکیر اسے روایت کرنے میں اکیلے ہیں۔","",{"k":"صحیح بخاری (٧٤٠٨)، مسند احمد (٣/٢٠٧)، صحيح الجامع (٧٨٧٥)۔","f":"مذکورہ حدیث میں دجال کے حلیہ کا تذکرہ ہے۔\n(١) دجال کانا ہو گا اور خدائی دعویٰ کرے گا حالانکہ ناقص ہونا خدا کی شان نہیں۔\n(٢) اس کی پیشانی پر کافر لکھا ہو گا جس سے مومن پہچان لیں گے۔\n(٣) پس وہ جس کو آگ کہے گا، وہ جنت ہوگی۔ مراد یہ ہے کہ حقیقت میں آگ اس کی باغ ہو جائے گی مومنوں کے لیے اور باغ اس کا آگ ہو جائے گا اس کے تابع داروں کے لیے۔"}],[196,"سیدنا شداد بن اوس اپنے باپ سے روایت کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ریا کو شرک اصغر شمار کرتے تھے۔ یہ حدیث یعلی بن شداد سے صرف عمارہ بن غزیہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اور بیچی بن ایوب اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ریا کاری شرک اصغر ہے۔ اور ریا کاری منافقوں کی نشانی ہے۔ جیسا کہ ارشاد باری تعالیٰ ہے: إنَّ الْمُنفِقِينَ يُخْدِعُونَ اللَّهَ وَ هُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلُوةِ قَامُوا كُسَالَى يُرَآءُ ونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلا) (النساء: ١٤٢) منافق اللہ کو دھوکا دیتے ہیں اللہ ان کو دھوکا کی سزا دینے والا ہے، جب نماز پڑھتے ہیں تو بڑی ستی سے اور لوگوں کو دکھانے کے لیے پڑھتے ہیں تبھی تو نماز میں ذکر بہت کم کرتے ہیں۔“ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((ان اخوف ما اخاف عليكم الشرك الاصغر )) (مسند احمد: ٤٢٨/٥، اسناده صحيح میں تم پر سب سے زیادہ شرک اصغر سے ڈرتا ہوں۔“ صحابہ کرام رضی اللہ عنہم نے پوچھا: شرک اصغر کیا ہے؟ آپ ملے لیے تم نے فرمایا: ” الریاء: ریا کاری ہے۔“","",{"k":"مجمع الزوائد (١٠/٢٢٢)۔"}],[197,"سیدہ عائشہ بنی تنہا سے روایت ہے کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلمن کوگم پایا جبکہ آپ میرے پاس تھے، میں نے انہیں تلاش کیا تو میں نے آپ کو سجدہ کرتے ہوئے پایا، آپ نے اپنی انگلیوں کے کنارے قبلہ رخ کیے ہوئے تھے، میں نے آپ سے یہ دعاسنی آپ کہہ رہے تھے ((أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِمَغْفِرَتِكَ مِنْ عُقُوبَتِكَ وَبِكَ مِنْكَ أَثْنِي عَلَيْكَ لَا أَبْلُغْ كُلَّ مَا فِيْكَ)) ”اے اللہ میں تیری رضا کے ساتھ تیرے غصے سے اور بخشش کے ساتھ تیری سزا سے پناہ چاہتا ہوں اور تیری ( رحمت کے ساتھ ) تیری عقوبت سے پناہ چاہتا ہوں میں تیری تعریف کرتا ہوں میں ان تمام صفات کو نہیں پہنچ سکتا جو تجھ میں ہیں۔ جب فارغ ہوئے تو فرمانے لگے: ”اے عائشہ علی شی! تیرے شیطان نے تجھے پکڑ لیا تھا میں نے پوچھا: کیا آپ کا کوئی شیطان نہیں ہے؟ آپ نے فرمایا: ”ہر آدمی کا ایک شیطان ہے، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ کا بھی ہے؟ آپ نے فرمایا: ”ہاں میرا بھی ہے لیکن میں نے اللہ سے دعا کی تو اللہ نے اس کے خلاف میری مدد فرمائی اس لیے وہ میرے تابع ہو گیا۔ یہ حدیث ابونضر سالم سے عمارہ بن غزیہ ہی کرتے ہیں، اسے روایت کرنے میں بیٹی بن ایوب ہیں۔ انون مذکورہ حدیث سے معلوم ہوا کہ سجدہ میں مذکورہ دعا پڑھنا مسنون ہے۔ اس کے علاوہ بھی","",{"k":"سنن نسائی (٣٩٦٠)، قال الالباني، صحیح الاسناد۔","f":"سجدہ میں نبی معظم مالے علیم سے بے شمار دعائیں ثابت ہیں۔"}],[198,"سيدنا ابو سعید خدری رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرما رہے تھے: ” پانچ نمازیں ایک دوسری کے درمیان کے لیے کفارہ ہیں۔ “ اور آپ نے فرمایا: بھلا بتاؤ اگر ایک آدمی کے کام کاج کی جگہ سے اور اس کے گھر کے درمیان پانچ نہریں ہوں جب وہ اپنے کام کاج کی جگہ جاتا ہے تو جو اللہ چاہے وہ اتنا کام کرتا ہے۔ اسے میل یا پسینہ پہنچتا ہے جب بھی وہ اس نہر پر سے گزرتا ہے غسل کرتا ہے تو یہ نسل کرنا اس کی میل کچیل سے کچھ بھی باقی نہیں رہنے دیتا۔ اس طرح نمازیں ہیں جب بھی کوئی گناہ کا کام کرتا ہے یا جو اللہ تعالیٰ چاہتا ہے پھر نماز پڑھتا ہے، دعا کرتا ہے اور استغفار کرتا ہے تو اس کے سارے گناہ معاف ہو جاتے ہیں۔“ یہ حدیث ابوسعید سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں بیچی بن ایوب اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ پانچ وقت کی نمازیں گناہوں کا کفارہ ہو جاتی ہیں۔ لیکن اس نماز سے جو سنت کے مطابق خشوع و خضوع کے ساتھ پابندی سے ادا کی جائے نہ کہ اپنے من مانے طریقے سے اور جب جی چاہا پڑھ لینے سے۔ ایک حدیث میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” پانچ نمازیں، جمعہ سے دوسرے جمعے تک ( کا وقفہ ) ان (صغیرہ) گناہوں کا کفارہ ہے جو اس کے درمیان ہوں گے جب تک کبیرہ گناہوں کا ارتکاب نہ کیا جائے۔ (صحیح مسلم، كتاب الطهارة، رقم: ٢٣٣)","",{"k":"المعجم الكبير للطبراني (٥/٢٨٠، ٥٣٠٧)، صحیح مسلم، رقم ٥/ ٢٨٠ : (٦٦٧)، مجمع الزوائد (١/٢٩٨)۔"}],[199,"سیدنا سمرہ بن جندب رضی اللہ عنہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا کہ کوئی مہاجر کسی دیہاتی کے لیے بیع کرے۔“ یہ حدیث قتادہ سے صرف سعید بن ابی عرو بہ روایت کرتے ہیں، اسے روایت کرنے میں صدقہ بن عبداللہ ا کیلے ہیں۔ ایک حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: (( ولا يَبعُ حَاضِرٌ لِبَادِ)) (صحیح بخاری، رقم: ٢١٥٨، مسلم، رقم:١٥٣١) کوئی شہری کسی دیہاتی کا سامان نہ بیچے۔“ امام نووی رحمہ اللہ فرماتے ہیں: ہمارے اصحاب کے نزدیک اس سے مراد یہ ہے کہ ایک اجنبی آدمی دیہاتی سے یا دوسرے شہر سے ایسا ساز و سامان جس کی سبھی کو ضرورت ہے، اس روز کے نرخ کے مطابق فروخت کرنے کے لیے لے کر آتا ہے مگر اسے شہری کہتا ہے کہ اس سامان کو میرے پاس چھوڑ دو تا کہ میں اسے بتدریج اعلی نرخ پر بیچ دوں۔ (شرح مسلم للنووى: ٤٢٥/٥) اس حدیث کی وجہ سے جمہور علماء اور امام شافعی رحمہ اللہ نے یہ موقف اپنایا ہے کہ شہری کے لیے کسی بھی دیہاتی کا سامان بیچنا حرام ہے۔","",{"k":"سنن ابی داؤد (٣٤٣٩)، المعجم الكبير للطبراني (٣٤٩/٦، ٦٧٢٦)۔"}],[200,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تبارک و تعالیٰ فرماتے ہیں: میں نے اپنے نیک بندوں کے لیے وہ کچھ تیار کر رکھا ہے جو کسی آنکھ نے دیکھا ہے، نہ کسی کان نے سنا ہے، اور نہ ہی کسی انسان کے دل پر اس کا گزرا ہوا ہے۔“ نان مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ نے جنت میں جو نعمتیں ایمان والوں کو عطا کرنی ہیں ان کو چھپا کر رکھا ہے، جیسا کہ ارشاد باری تعالیٰ ہے: فَلا تَعْلَمُ نَفْسٌ مَّا يُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ﴾ (السجده: ١٨) کوئی نفس نہیں جانتا جو کچھ ہم نے ان کی آنکھوں کی ٹھنڈک کے لیے پوشیدہ کر رکھا ہے جو کچھ کرتے .:٢٠١ ہیں یہ اس کا بدلہ ہے۔“","",{"k":"صحیح بخاری (٣٢٤٦)، السلسلة الصحيحة (١٠٨٦)، سنن ترمذی (٣١٩٧)۔"}],[201,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” پہلا شخص جس نے ابراہیم کالینا کا دین بدل دیا تھا وہ عمرو بن لحی بن قمعہ بن خندف ابوخزاعہ تھا۔“ یہ حدیث صالح مولی التوامہ سے صرف ابن ابی ذئب ہی روایت کرتے ہیں اور ابن ابی ذئب سے صرف عبد اللہ بن یزید البکری روایت کرتے ہیں، اسے روایت کرنے میں ہشام بن عمارا کیلے ہیں۔ نان مذکورہ حدیث سے معلوم ہوا کہ جس نے سب سے پہلے سیدنا ابراہیم علیسلام کے دین کو بدلا وہ عمرو بن لھی تھا۔ اس کو سزا کیا ملی؟ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: کہ میں نے (معراج کی رات ) عمرو بن عامرلحی کو دیکھا کہ وہ دوزخ میں اپنی آنتیں کھینچ رہا ہے، اور یہ وہی شخص ہے جس نے بتوں کے نام پر جانور آزاد کرنے کا طریقہ ایجاد کیا۔ (صحیح بخاری، کتاب التفسير، رقم: ٤٦٢٣) عمرو بن لحی دولت مند تھا، جیسا کہ حافظ ابن کثیر جماللہ نے محمد بن اسحق کے حوالہ سے نقل کیا کہ عمرو بن عامر لحی نے ہیں اونٹوں کی آنکھیں پھوڑی تھیں۔ عرب جاہلوں کا یہ عقیدہ تھا کہ جس کے پاس ایک ہزار اونٹ ہو جائے وہ ایک اونٹ کی آنکھیں پھوڑ دے تا کہ ہزار اونٹ کو نظر بد نہ لگے اس نے ہیں اونٹوں کی آنکھیں پھوڑ کر بتایا کہ یہ بیس ہزار اونٹوں کا مالک ہے۔ پھر ارزقی اور سہیلی کے حوالے سے لکھا کہ یہ بعض دفعہ ایام حج میں دس ہزار اونٹ ذبح کرتا، ہر سال دس ہزار جوڑے تقسیم کرتا اور حاجیوں کو گھی،ستو اور شہد کے بنائے ہوئے کھانے کھلاتا،سنتو گھول کر پلاتا۔ اسی وجہ سے اتنی شہرت و عزت ملی کہ اس کے قول و فعل کو لوگ شریعت سمجھنے لگے۔ (البدايه والنهايه: ١٨٧/٢)","",{"k":"السلسلة الصحيحه (٤٢١/٢، ١٦٧٧)، صحيح الجامع الصغير (٢٥٨٠)، المعجم الكبير للطبراني (٢٠٦/٩)۔"}],[202,"سیدنا ابو ہریرہ فی اللہ نے بیان کیا رسول اللہ مٹے علیم نے فرمایا: 'پانچ اشخاص پر جمعہ ضروری نہیں۔ (١) عورت (٢) مسافر (٣) غلام (٤) بچہ (٥) اور دیہاتی لوگ۔“ یہ حدیث مالک سے صرف ابراہیم بن حماد بن ابی حازم ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد: ٢/ ١٧٠ ضعيف الجامع الصغير (٢٨٦١)، المعجم الكبير للطبرانی (١١١/١٩)۔","f":"مذکورہ روایت کمزور ہے تاہم صحیح روایت میں ہے نبی معظم مسلم نے فرمایا: ”جمعہ باجماعت ادا کرنا ہر مسلمان پر حق و واجب ہے مگر چار طرح کے افراد اس سے مستقلی ہیں۔ غلام، عورت، بچہ اور مریض۔ (سنن ابی داؤد، کتاب الصلاة، رقم: ١٠٦٧، اسناده صحيح) معلوم ہوا کہ ان پر جمعہ فرض نہیں اگر یہ پڑھ لیں تو کوئی حرج نہیں لیکن اگر وہ نہ پڑھیں تو نماز ظہر ادا کرنا ہوگی۔ کیا مسافر پر جمعہ فرض ہے یا کہ نہیں؟ جو روایات مسافر کے متعلق آتی ہیں کہ اس پر واجب ہے یا کہ نہیں وہ ضعیف ہیں۔ تاہم جمہور علماء کا یہ موقف ہے کہ مسافر پر جمعہ واجب نہیں۔ (ان کی دلیل یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے دوران حج جمعہ نہیں بلکہ ظہر پڑھی تھی اور یہی موقف راج ہے۔ دیہات کے لوگوں کو بھی جمعہ کے لیے مساجد میں حاضر ہونا چاہیے۔ جیسا کہ ام المومنین سیدہ عائشہ بنا انا بیان کرتی ہیں کہ لوگ اپنے ڈیروں سے اور مدینہ کے بالائی علاقوں (عوالی) سے جمعہ کے لیے آیا کرتے تھے۔ (سنن ابی داؤد، رقم: ١٠٥٥، صحیح بخاری، رقم: ٩٠٢) (عوالی) کی آبادیاں مدینہ منورہ سے تین سے آٹھ میل کی مسافت تک تھیں۔"}],[203,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ کی تین حرمتیں ہیں جس نے ان کی حفاظت کی اللہ تعالیٰ اس کے دین اور دنیا کے معاملے کی حفاظت کرے گا۔ اور جس نے انہیں ضائع کر دیا تو اللہ تعالیٰ اس کی کسی چیز کی حفاظت نہیں کرے گا۔‘“ کہا گیا: یا رسول اللہ صلی اللہ علیہ وسلم! وہ کون کون سی ہیں؟ آپ نے فرمایا: (١) اسلام کی حرمت (٢) میری حرمت (٣) میرے قرابت داروں کی حرمت۔“ یہ حدیث عمران بن محمد بن سعید بن مسیب سے ابراہیم بن حماد کے سوا کوئی روایت نہیں کرتا، ہم نہیں جانتے کہ عمران بن محمد بن سعید بن مسیب اس کے علاوہ بھی کوئی مسند حدیث بیان کرتے ہوں۔","",{"k":"كنز العمال (١٥/٨٤٠، ٤٣٣٣٨)، مجمع الزوائد (١/٨٨)، فيه ابراهيم بن حماد بن ابی حازم وهو ضيعفٌ. ور الله۔"}],[204,"سيدنا ابو ہریرہ نیا لینے سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کوئی بیماری متعدی نہیں ہوتی، الو اور ماہ صفر کی نحوست کوئی چیز نہیں۔“ اور صحت مند جانوروں کے پاس بیمار جانور نہ لائے جائیں۔ یہ حدیث مالک سے صرف نافع ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن صالح اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کوئی بیماری متعدی نہیں ہوتی لیکن مذکورہ حدیث کے","",{"k":"صحیح بخاری (٥٧٥٧)، سنن ابن ماجه (٣٥٤١)، المعجم الكبير للطبراني (١١١/١٩)۔","f":"آخر میں ہے کہ صحت مند جانوروں کے پاس بیمار جانور نہ لائے جائیں، یہ ممانعت اس غرض سے ہے کہ کم علم لوگ لا یعنی اوہام میں مبتلا نہ ہوں۔ ہام: اہل عرب کے توہمات میں یہ بات بھی تھی کہ اگر کوئی قتل ہو جائے اور اس کا بدلہ نہ لیا جائے تو اس مردے کی کھوپڑی سے ایک پرندہ (الو) نکلتا ہے جو اس کے اوپر منڈلاتا رہتا ہے اور آواز لگاتا ہے: پیاس، پیاس۔ اگر بدلہ لے لیا جائے تو وہ مطمئن ہو جاتا ہے ورنہ نہیں۔ اس وہم کی بنا پر وہ لوگ جیسے بھی بن پڑتا بدلہ لینے پر اصرار کرتے تھے۔ صفر: کچھ لوگ صفر کے مہینے کو منحوس جانتے تھے، اور اس میں اہم کام سرانجام نہیں دیتے تھے جیسا کہ آج بھی جاہل صفر کے مہینے میں شادیاں نہیں کرتے"}],[205,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بر بری کا ایمان اس کے حلق سے نیچے نہیں اترتا۔ یہ حدیث ابن ابی ذئب سے عبد المنعم ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (١٩/١١٢)، سنن ابی داود (٣٩١١)، السلسلة الضعيفة (٣٣٧٧)، قال الالبانی منکر، ضعيف الجامع الصغير (٢٣٦٨)۔"}],[206,"سیدنا مستورد فہری ضیا اللہ کا بیان ہے کہ میں نے رسول اللہ صلم کو فرماتے ہوئے سنا: ” قریش کا ذکر کیا تو فرمایا: ان میں چار حصلتیں ہیں (١) وہ فتنے کے وقت سب سے زیادہ اصلاح کرنے والے ہیں (٢) مصیبت کے بعد بہت جلد اس سے سنبھلتے ہیں (٣) پیچھے ہٹنے کے بعد دوبارہ بہت جلد حملہ کرتے ہیں اور (٤) یتیم اور مسکین کے حق میں بہت اچھے ہیں، سب سے بڑھ کر بادشاہوں کے ظلم کو بہت روکنے والے ہیں۔“ یہ حدیث لیث سے صرف ابن وہب ہی روایت کرتے ہیں، اسے روایت کرنے میں عبدالملک بن شعیب بن لیث اکیلے ہیں۔","",{"k":"صحيح مسلم (٢٨٩٨)، ♦، مجمع الزوائد (٢٦/١٠)۔","f":"مسلم شریف میں روایت ہے کہ نبی معظم تعلیم نے فرمایا: ”نصاری میں چار حصلتیں ہیں وہ مصیبت کے وقت نہایت بردبار ہیں اور مصیبت کے بعد سب سے جلد سنبھلتے ہیں اور پیچھے ہٹنے کے بعد سب سے پہلے پھر جلد حملہ کرتے ہیں اور بہتر ہیں سب لوگوں میں مسکین یتیم اور ضعیف کے لیے اور ایک پانچویں خصلت ہے جو نہایت عمدہ ہے سب لوگوں سے زیادہ وہ بادشاہوں کے ظلم کو روکتے ہیں۔“ (صحیح مسلم، کتاب الفتن، رقم: ٢٨٩٨)"}],[207,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ( رمضان کے ) مہینے سے ایک یا دو دن پہلے (رمضان کے استقبال کے طور پر ) روزہ نہ رکھو مگر جو شخص پہلے روزے رکھتا چلا آ رہا ہو وہ یہ بھی رکھ لے۔“ یہ حدیث لیث سے اُن کے بیٹے شعیب ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ مہینے کے استقبال کے لیے روزہ رکھنا جائز نہیں تاہم وہ SSSSC شخص اس سے مستثنیٰ ہے جس کا روزے رکھنا معمول ہو یعنی اگر کوئی ہر سوموار اور جمعرات کو روزے رکھتا ہے تو وہ رکھ سکتا ہے۔","",{"k":"السلسلة الصحيحه (٢/٦٤، ٩٦٥)، ترمذی (٦٨٥)، سنن نسائی (٢١٧٤)۔"}],[208,"ایک آدمی سیدنا عبداللہ ابن عباس نیا اینجا کے پاس آیا، کہنے لگا: میں نے نذر مانی ہے کہ میں اپنے آپ کو ذبح کروں گا سیدنا عبداللہ ابن عباس را اینجا نے کہا: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللهِ أسْوَةٌ حَسَنَةٌ (٢٢/٣٣) تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں بہترین نمونہ ہے پھر یہ آیت پڑھی ﴿وَفَدَيْنَاهُ بِذِبْحٍ عَظِیم (٣٧ ١٠٧) ایسا آدمی مینڈھا ذبح کرے تو اس نے مینڈھا ذبح کر دیا۔“ یہ ریث یحی بن سعید سے صرف لیٹ ہی روایت کرتے ہیں اور لیث سے ابن وہب روایت کرتے ہیں اسے عبدالملک بن شعیب اکیلے ہی روایت کرتے ہیں۔","",{"k":"السنن الكبرى للبيهقي (٧٣/١٠)، مجمع الزوائد (١٣٩١٤)، رجال الصحيح۔","f":"مذکورہ روایت سے معلوم ہوا کہ جو اپنے آپ کو ذبح کرنے کی نذر مانے تو اس کو چاہیے کہ وہ اپنی جگہ جانور ذبح کرے۔"}],[209,"سیدنا کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم ان کے متعلق جو شعر کہتے ہو اس میں ان کو اس طرح تکلیف ہوتی ہے گویا کہ تم انہیں تیروں سے چھلنی کر رہے ہو۔ یعنی مشرکین کی ہجو کرنا ان پر بہت گراں ہے۔“ یہ حدیث موسیٰ بن عقبہ سے صرف محمد بن عبد اللہ ہی روایت کرتے ہیں، اسے روایت کرنے میں یعقوب زہری اکیلے ہیں۔","",{"k":"السلسلة الصحيحه (٤/٤٤٨، ١٩٤٩)، سنن الكبرى للبيهقي (١٠/٢٣٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مشرکوں کی ہجو کرنا چاہیے جیسا کہ سیدنا حسان بن ثابت ضي الله شاعر رسول مشرکوں کی ہجو کرتے تھے۔ سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا نبی معظم صلی اللہ علیہ وسلم نے سیدنا حسان رضی اللہ عنہ سے فرمایا: \"مشرکین مکہ کی تم بھی ہجو کرو یا ( یہ فرمایا کہ ) ان کی ہجو کا جواب دو۔ سیدنا جبریل علینا تمہارے ساتھ ہیں۔ (صحیح بخاری، رقم: ٣٢١٣) پھر سیدنا حسان رضی اللہ عنہ نے ایسا جواب دیا کہ مشرکین کے دھوئیں اڑ گئے ان کی ساری حقیقت کھول کر رکھ دی۔ ایک شعر سیدنا حسان رضی اللہ عنہ کا یہ ہے؟:٢١٠ لنا من كل يوم من معرك اب او قتال او هجاء یعنی ہم تو ہر روز معرکہ کی تیاری میں مشغول ہیں تم سے جنگ کرنے میں یا تم کو جواباً برا کہنے میں یا تمہاری ہجو کرنے میں"}],[210,"سیدنا زید بن خالد جہنی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ میم نے اپنے صحابہ میں کچھ قربانیاں تقسیم فرما ئیں تو مجھے بھی ایک سال کا بکری کا بچہ عطا فرمایا، میں نے اسے موٹا تازہ پایا تو میں آپ کے پاس گیا۔ اور کہا: اللہ کے رسول ملے دیدیم! وہ تو جذع ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے قربان کر دو۔“ مذکورہ روایت سے معلوم ہوا کہ بھیڑ کا جذع قربانی پر جائز ہے۔ یہ کس وقت جائز ہے","",{"k":"سنن ابی داؤد (٢٧٩٨)، قال الالباني حسن صحيح۔","f":"کہ جب دو دانت والا جانور نہ ملے۔ جیسا کہ سیدنا مجاشع بن مسعود ضیا الیہ بیان کرتے ہیں کہ ”ایک مرتبہ بکریاں بہت کم ہو گئیں۔ تو ایک منادی نے نبی ملنے ستم کا پیغام سنایا کہ اب بھیٹر کا جذع دوندے کی طرح چلے گا۔ (سنن ابی داؤد، رقم: كتاب الضحايا: ٢٧٩٩، قال الشيخ الالباني: صحيح.) بھیڑ کی نسل سے جو جذع ہو گا وہی ذبح ہوگا نہ کہ بکرے اور دوسرے جانوروں کی نسل سے"}],[211,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ سیدنا سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس نذر کے متعلق سوال کیا جو ان کی والدہ کے ذمے تھی۔ تو آپ نے فرمایا: ” اس کی طرف سے (نذر) پوری کرو۔“","",{"k":"صحیح بخاری (٢٧٦١)، سنن ابی داؤد (٣٣٠٧)، سنن ترمذی (١٥٤٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اگر میت کے ذمہ کسی مشروع کام کی نذر ہو یا دیگر حقوق ہوں تو ورثاء پر اس کی ادائیگی لازم ہے (خواہ میت نے اس کی وصیت نہ بھی کی ہو ) بطور خاص اولاد پر۔ یہ بھی معلوم ہوا کہ جو حقوق و واجبات والدین کے ذمہ ہوں انہیں ادا کر دیا جائے۔اس سے یہ بھی معلوم ہوا کہ میت کو صدقہ و خیرات روزے اور غلام کی آزادی وغیرہ کا ثواب پہنچتا ہے۔"}],[212,"سيدنا ابی بن کعب رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کے زمانے میں سو دینار حاصل کر لیے۔ پھر انہوں نے حدیث کے آخر تک بیان کیا۔“ سیدنا ابی بن کعب رضی اللہ عنہ فرماتے ہیں: کہ مجھے ایک تھیلی ملی، جس میں سو دینار تھے، میں نبی معظم مالے علم کی خدمت میں آیا۔ آپ مطلئے علیم نے فرمایا: ” ایک سال تک اس کا اعلان کرو۔“ (صحيح بخارى، كتاب اللقطة، رقم: ٢٤٢٦، سنن ابی داؤد، رقم: ١٧٠١) اگر کوئی چیز مل جائے تو کم از کم ایک سال تک اعلان کرنا چاہیے اس کے بعد اپنے استعمال میں لا سکتا ہے اگر اس کا مالک آجائے تو پھر اس کو واپس لوٹانا ہوگا۔","",{"k":"مسند احمد (١٤٣/٥، ٢١٣٢٢)، قال الشيخ الشعيب الأرناؤط، صحیح۔"}],[213,"سیدنا سہل بن سعد ساعدی نی یہ بیان کرتے ہیں، ایک شخص نے پردے سے نی نے ان کو جھانک کر دیکھا اور آپ صلی اللہ علیہ وسلم کے ہاتھ میں ایک کنگھی تھی۔ آپ ملنے صلی اللہ علیہ وسلم نے فرمایا: اگر مجھے معلوم ہوتا کہ یہ مجھے دیکھ رہا ہے تو میں اس کی آنکھ پھوڑ دیتا۔“ مذکورہ حدیث سے معلوم ہوا کہ اجازت لینے سے پہلے کسی کے گھر میں نظر ڈالنا درست نہیں۔ کیونکہ اجازت لینے سے پہلے اگر نظر ڈال لی تو گویا کہ اندر ہی آگیا۔ اجازت لینے کی ضرورت تو اس لیے ہے کہ کسی کے گھر میں یا کسی کے جسم پر نظر نہ پڑے کیونکہ بغیر اجازت کے نظر ڈالنا ممنوع ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے نبی معظم صلی اللہ علیہ وسلم نے ارشاد فرمایا: ” اگر کوئی آدمی تیرے گھر میں جھانکے اور تو نے اس کو کنکری مار دی جس سے اس کی آنکھ پھوٹ گئی تو تجھ پر کوئی گناہ نہیں۔“ (صحیح بخاری، ادب المفرد، رقم: ١٠٦٩) معلوم ہوا شرع نے چادر اور چار دیواری کے تحفظ کا بہت زیادہ خیال رکھا ہے","",{"k":"صحیح بخاری (٦٢٤١)، صحیح مسلم (٢١٥٦)۔"}],[214,"سیدنا صفوان بن یعلی اپنے باپ اور چچا سے بیان کرتے ہیں کہ وہ دونوں غزوہ تبوک میں نکلے تو ایک شخص نے دوسرے کو دانتوں سے کاٹا تو اس نے اپنا ہاتھ اس کے منہ سے اپنی طرف کھینچا تو اس کے اگلے ثنیہ (دانت) نکل آئے وہ نبی صلی اللہ علیہ وسلم کے پاس آیا قصاص طلب کر رہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \" کیا یہ اپنا ہاتھ تیرے منہ میں چھوڑ دیتا اور تو سانڈھ کی طرح اس کو چباتا رہتا۔ پھر نبی صلی اللہ علیہ وسلم نے اس کے دانتوں کے قصاص اور دیت کو لغو قرار دے دیا۔:٢١٥","",{"k":"يَطْلُبُ الْقِصَاصَ فَقَالَ النَّبِيُّ صلى الله عليه وسلم: ((أَفَكَانَ يَدَعُ يَدَهُ فِي فِيكَ تَقْضَمُهَا كَمَا يَقْضَمُ الْفَحْلُ ؟. (( فَأَبْطَلَهَا رَسُولُ اللَّهِ . صحیح بخاری (٤٤١٧)، سنن ابی داؤد (٤٥٨٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اگر اپنا دفاع کرتے ہوئے حملہ آور کو کوئی نقصان پہنچے تو اس کا وہ ذمہ دار نہیں ہوگا جس نے اپنا دفاع کیا کیونکہ حملہ آور کے مقابلے میں اپنا دفاع ضروری ہے۔"}],[215,"سیدہ عائشہ نبی اللہ نے بیان کیا، میں نے کبھی بھی نبی صلی اللہ علیہ وسلم کو اتنا ہنستے ہوئے نہیں دیکھا کہ حلق کا اندر والا حصہ ( کوا) دیکھ سکتی آپ تو صرف مسکراتے تھے۔ اور جب بادل یا ہوا دیکھتے تو آپ کے چہرے پر اس کے اثرات معلوم کیے جا سکتے تھے۔“ یہ حدیث ابونضر سے عمرو بن حارث ہی روایت کرتے ہیں، اُن سے روایت کرنے میں ابن وہب اکیلے ہیں۔","",{"k":"صحیح بخاری، رقم: ٠.٩١ (٤٨٢٨)، سنن ابی داؤد (٥٠٩٨)۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ زور سے کھلکھلا کر اور از حد منہ کھول کر ہنسنا نامناسب اور وقار کے خلاف ہے، چاہیے کہ ایسے مسکرانے کو اپنی عادت بنایا جائے جو سنت ہے۔ کیونکہ زیادہ ہنسنا دل کو مردہ کر دیتا ہے۔\n(٢) تیز ہوا ( آندھی ) یا بادل کو دیکھ کر اس کی خیر کی دعا کرنا چاہیے اور عذاب سے پناہ مانگنا چاہیے۔ جیسا کہ حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم کوئی بادل کا ٹکڑا دیکھتے تو کام کاج چھوڑ دیتے اور یہ دعا پڑھتے: ((اللهم انى اعوذ بك من شرها)) (سنن ابی داؤد، کتاب الادب، رقم: ٥٠٩٩) ”اے اللہ! میں اس کے شر سے تیری پناہ چاہتا ہوں۔\""}],[216,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کی راہ میں قتل ہونے والا شہید ہے، اللہ کی راہ میں غرق ہونے والا شہید ہے، اور اللہ کی راہ میں پیٹ کی بیماری والا شہید ہے۔ یہ حدیث عطاء سے صرف ابوالنضر ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٢٨٣٩)، سنن نسائی (٣١٦٣)۔","f":"مذکورہ حدیث اور دیگر اسی طرح کی احادیث سے ثابت ہوتا ہے کہ شہید تین قسم کے ہیں:\n(١) دنیوی اور اخروی دونوں لحاظ سے شہید جیسے وہ لوگ جو میدان جہاد میں شہید ہو جاتے ہیں۔\n(٢) اخروی لحاظ سے شہید جیسا کہ اس حدیث اور دیگر احادیث میں طاعون کی بیماری سے مرنے والا، پیٹ کی بیماری، ڈوب کر مرنے والا وغیرہ شامل ہیں۔\n(٣) دنیوی مقاصد کے حصول کے لیے جنگ کرتے ہوئے قتل ہونے والے یا میدان جنگ سے راہ فرار اختیار کرتے ہوئے قتل ہونے والے شہید نہیں کہلائیں گے، لیکن ان کو دنیاوی لحاظ سے شہید کہا جاتا ہے) (مرعاة، شرح مشكاة: ٤١/٢)"}],[217,"سيدنا عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”چاندی چاندی کے عوض برابر برابر ہونا چاہیے اس میں کسی طرف سے زیادتی درست نہیں۔“ یہ حدیث ابونصر سے صرف یزید بن ابی حبیب ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"لسنن الكبرى للبيهقى ٢٨٤/٥، صحيح مسلم، وبيع الذهب يا الذهب (١٥٨٨)۔"}],[218,"سیدنا عون بن عبد اللہ کہتے ہیں مجھے میرے باپ نے چند کلمات سکھائے اور کہا عمر بن خطاب رضی اللہ عنہما نے یہ کلمات مجھے سکھائے انہوں نے کہا: مجھے یہ رسول اللہ صلی اللہ علیہ وسلم نے سکھائے: ((التَّحِيَّاتُ الصَّلَوَاتُ الطَّيِّبَاتُ المُبَارَكَاتُ لِلَّهِ، السَّلامُ عَلَى النَّبِيِّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، وَالسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ)) تمام زبانی، بدنی اور مالی عبادات، برکت والی اللہ کے لیے ہیں۔ نبی صلی اللہ علیہ وسلم پر سلام اور اللہ کی رحمت اور برکتیں ہوں اور ہم پر اور اللہ تعالیٰ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد ملے عام اس کے بندے اور اس کے رسول ہیں۔ یہ حدیث عبد اللہ بن عتبہ بن مسعود کی از حضرت عمر صرف اسی سند سے ہی روایت کی گئی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ (١) ایک حدیث میں ہے کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول","",{"k":"ابو داؤد، رقم : ٩٧٤ . صحيح مسلم (٤٠٢)، سنن۔","f":"اللہ صل علیم میں تشہد اس اہتمام سے سکھاتے تھے جیسے کہ قرآن سکھاتے۔ (سنن ابی داؤد، کتاب الصلوة، رقم: ٤٠٣) اس میں اشارہ ہے کہ یہ واجب ہے امام ابوحنیفہ، مالک، شافعی بیشہ کا کہنا ہے کہ درمیانہ تشہد واجب نہیں۔ جبکہ امام احمد، لیث، اسحاق ہم نے اسے واجب کہا ہے۔ (المغنی: ٢١٧/٢ نیل الاوطار: ١٠٣/١) آخری تشہد کے متعلق امام احمد اور امام شافعی عبداللہ کا موقف ہے کہ یہ واجب ہے جبکہ امام مالک ہراللہ نے سلام تک بیٹھنا لازم قرار دیا ہے تشہد کو واجب نہیں کیا۔ (بداية المجتهد: ١٢٥/١ المغنى: ٥٣٢/١) (٢) تشہد کے مختلف الفاظ ہیں سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کی روایت میں ہے: التحيات لله والصلوات والطيبات السلام عليك)) (صحیح بخاری، رقم: - صحیح مسلم، رقم: انظر: رقم الحديث: ٦٨٣) سیدنا عبداللہ ابن مسعود ضیا اللہ والی روایت میں موجود تشہد کے الفاظ زیادہ افضل ہیں۔ امام احمد، ابوحنیفہ عبداللہ اور جمہور علماء نے اسی کو اختیار کیا ہے"}],[219,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کا جھنڈا سیاہ تھا اور چھوٹے جھنڈے کا رنگ سفید تھا جس پر لکھا ہوا تھا: (( لا اله الا اللهُ مُحَمَّدٌ رَّسُوْلُ اللهِ “ یہ حدیث حضرت ابن عباس سے صرف اس سند سے ہی مروی ہے، اسے روایت کرنے میں حیان بن عبید اللہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جہاد میں جھنڈے کا اہتمام کرنا مستحب ہے۔ سیدنا جابر رضی اللہ عنہ فرماتے ہیں کہ نبی معظم صلی اللہ علیہ وسلم مکہ میں داخل ہوئے اور آپ کا جھنڈا سفید تھا۔ صحیح سنن ابی داؤد: رقم (٢٢٥٩ بہر حال قرون اولیٰ میں جھنڈوں کا کوئی رنگ اور سائز مخصوص نہ ہوتا تھا بلکہ کوئی بھی رنگ اختیار کر لیا جاتا تھا۔","",{"k":"مجمع الزوائد (٥/٣٢١)، سنن ترمذی (١٦٨١)، قال الالباني، حسن۔"}],[220,"سیدنا عقبہ بن عامر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی شخص سامان فروخت کرے، اور اگر اس میں کوئی عیب ہو تو وہ اس کو نہ چھپائے۔“ یہ حدیث یزید بن ابی حبیب سے صرف ابن لھیعہ ہی روایت کرتے ہیں اور عقبہ سے صرف اس سند سے ہی مروی ہے۔","",{"k":"مجمع الزوائد:٤ / . ٨٠، اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ چیز فروخت کرتے وقت سیدھی سیدھی بات کرنا چاہیے یہ نہیں کہ چیز خراب ہو اور کہے یہ چیز اچھی ہے۔ حالانکہ وہ چیز بھی ہو۔"}],[221,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو گویا کہ میں آپ کی بغلوں کی سفیدی دیکھ رہا ہوں۔ یہ حدیث صالح مولی التوامہ سے سعید بن ایوب ہی روایت کرتے ہیں، اسے روایت کرنے میں روح بن صلاح اکیلے ہیں۔:٢٢٢ مذکورہ حدیث سے معلوم ہوتا ہے کہ سجدے میں نبی معظم صلی اللہ علیہ وسلم کا معمول تھا کہ آپ اپنے بازو پہلوؤں سے اس قدر جدا رکھتے تھے کہ آپ کی بغلوں کی سفیدی ظاہر ہونے لگتی، اس لیے اس کیفیت سے سجدہ کرنا مسنون ہے۔ اس حدیث سے یہ بھی معلوم ہوتا ہے کہ آپ ملنے کی یمن کی بغلیں باقی جسم کی طرح سفید تھیں","",{"k":"المعجم الكبير للطبرانی (١٩/١١٣)، مسند احمد (٣٤٣/١، ٣١٩٧)، قال الشيخ شعيب الأرناؤط صحيح وغيره۔"}],[222,"سیدنا حارث بن اصمہ سے روایت ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم سے ملا جب کہ آپ صلی اللہ علیہ وسلم قضائے حاجت سے فارغ ہو کر نکلے تھے اور میں نے آپ کو سلام کیا تو آپ نے مجھے کوئی جواب نہ دیا یہاں تک کہ اپنا ہاتھ دیوار پر مارا اور اس سے چہرے اور ہاتھوں پر مسح کیا، پھر مجھے سلام کا جواب دیا۔“ یہ حدیث عبید اللہ بن ابی جعفر سے صرف سعید بن ابی ایوب ہی روایت کرتے ہیں، اسے روایت کرنے میں روح بن صلاح اکیلے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ کا ذکر باوضو ہو کر کرنا افضل ہے۔ (٢) یہ بھی معلوم ہوا کہ تیم وضو کے قائم مقام ہے جبکہ پانی دستیاب نہ ہو۔","",{"k":"سنن ابی داؤد (٣٢٩)، قال الالبانی، صحیح۔"}],[223,"يزيد بن ابی عبید کہتے ہیں مجھے سلمہ بن اکوع نے بتایا کہ جس دن مسلمانوں نے خبیر فتح کیا تو رسول اللہ ملت علی ایم نے دیکھا کہ آگ جل رہی ہے تو آپ صلی اللہ علیہ وسلم نے پوچھا یہ کیسی آگ ہے؟“ انہوں نے کہا: یہ پالتو گدھوں کے گوشت پر جل رہی ہیں آپ ملے لی تم نے فرمایا: ”جو کچھ ان برتنوں میں ہے اسے گرا دو اور انہیں توڑ دو یعنی یہ ہنڈیاں توڑ دو لوگوں میں سے ایک آدمی بولا یا ہم انہیں دھو لیں؟ آپ ملئے علیم نے فرمایا: ” ( ٹھیک ہے ) یا دھولو۔“","",{"k":"صحیح بخاری کتاب المظالم (٢٤٧٧)، سنن ابن ماجه (٣١٩٥)۔"}],[224,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول الله ل عم سوره ﴿ إِذَا السَّمَاءُ انْشَقَّتْ اور اِقْرَأْ بِاسْمِ رَبَّكَ الَّذِي خَلَقَ میں سجدہ کرتے تھے۔‘ یہ حدیث واہب بن عبداللہ سے صرف ضمام ہی روایت کرتے ہیں، اسے روایت کرنے میں یحیی بن یزید الصدفی اکیلے ہیں۔","",{"k":"مصنف ابن ابی شیبه (١/٤٥٨)، سنن ترمذی، رقم :٣ (٥٧٣)، سنن ابی داؤد، رقم : ١٤٠٧ قال الالباني، صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سجدہ تلاوت مشروع ہے، تاہم سجدہ تلاوت کے حکم میں اختلاف ہے بعض اس کو واجب اور بعض مستحب کہتے ہیں۔"}],[225,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے: ”جو شخص مر گیا اور اس پر کسی کی بیعت نہ ہو تو اس کی موت جاہلیت کی موت ہوگی۔“ یہ حدیث امیہ بن محمد سے عطاف بن خالد ہی روایت کرتے ہیں اور اسے روایت کرنے میں بیٹی بن بکیرا کیلے ہیں۔","",{"k":"صحيح مسلم (١٨٥١)، المعجم الكبير للطبراني (١٤٩/١١)۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ مسلمانوں کی جماعت کے ساتھ رہنا ضروری ہے۔\n(٢) معلوم ہوا کہ مسلمان حکمران کی اطاعت کرنا واجب ہے، اور اس کی بیعت واطاعت سے انحراف کرنا، مسلمانوں کی جماعت سے الگ ہو جانا بغاوت کرنا ناجائز ہے۔\n(٣) یہ بھی معلوم ہوا کہ جو حاکم وقت کی اطاعت جائز کاموں میں نہیں کرتا، اور اسے اسی حال میں موت آگئی تو وہ جاہلیت کی موت مرے گا۔ اسے جاہلیت کی موت کے ساتھ اس لیے تشبیہ دی گئی ہے کہ اسلام سے قبل امیر کی اطاعت کا کوئی تصور نہ تھا۔ اس میں لوگ اپنی عار اور ذلت محسوس کرتے تھے۔ اسلام نے اس طوائف الملو کی کا خاتمہ کر کے انہیں نظم وضبط کا پابند بنایا اور امیر کی اطاعت کی تاکید فرمائی تا ہم اس سے وہ امیر مراد ہے جو حاکم وقت، بادشاہ ہے نہ کہ مسلمانوں کی محدود جماعتوں کے بے اختیار امیر مراد ہیں۔"}],[226,"سیدنا ابو ہریرہ ضیا اللہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”جو شخص اندھا دھند پتھر، عصا یا کوڑا پھینکنے سے قتل ہو جائے تو وہ قتل خطا ہو گا اس کی دیت قتل خطا کی دیت ہوگی۔ اور جس شخص کو جان بوجھ کر قتل کر دیا جائے تو اس میں قصاص ہو گا۔ اور جو شخص اس (قصاص) کے سامنے رکاوٹ بن جائے تو اس پر اللہ تعالیٰ کی لعنت اور غضب ہو گا اس کا نفل قبول کیا جائے گا نہ فرض۔“ یہ حدیث عمرو بن دینار از طاؤس از حضرت ابو ہریرہ بنایا یہ صرف حمزہ انصیمی ہی روایت کرتے ہیں، ان کے علاوہ از عمرو از طاؤس از حضرت ابن عباس روایت کرتے ہیں۔","",{"k":"سنن ابی داؤد (٤٥٣٩)، مجمع الزوائد (٦/٢٨٦)، قال الالباني صحيح لغيره۔","f":"الله\n(١) مذکورہ روایت سے معلوم ہوا کہ عصا یا کوڑا مارنے سے جو قتل ہو جائے اس کی دیت قتل خطا کی دیت ہو گی۔ سیدنا عبد اللہ بن عمرو بن عاص نیلی اہلیہ سے روایت ہے رسول اللہ مٹے ندیم نے فرمایا: دقتل خطا اور قتل شبہ عمد جوکوڑا اور لاٹھی مارنے سے واقع ہو کی دیت سو اونٹ ہے ان میں سے چالیس اونٹنیاں ایسی ہوں گی جن کے پیٹوں میں ان کے بچے ہوں گے۔ (سنن ابی داؤد، کتاب الديات، رقم: ٤٥٨٨، سنن ابن ماجه رقم: ٢٦٢٧، اسناده حسن)\n(٢) اگر قتل عمد ثابت ہو جائے تو قصاص واجب ہے۔ واضح رہے کہ اہل علم نے قتل کی تین اقسام بیان کی ہیں۔ (١) قتل عمد (٢) قتل شبه عمد\n(٣) قتل خطا۔ قتل عمد سے مراد ایسا قتل ہے جس سے مکلف شخص کسی شخص کو ایسے آلے سے مارنے کی نیت کرے جس میں اغلب گمان یہی ہو کہ وہ اسے قتل کر دے گا ( مثلاً بندوق، تلوار، یا تیر وغیرہ) (٢) قتل شبه عمد وہ قتل جس میں مکلف کسی کو ایسی چیز سے مارنے کا ارادہ کرے جس سے عموماً انسان مرتا نہیں مثلاً چھڑی، کنکری یا چھوٹا پتھر وغیرہ اور اس سے وہ شخص مر جائے۔اس میں قصاص نہیں بلکہ دیت واجب ہوگی۔ (٣) قتل خطاء قتل خطا یہ ہے کہ مارنا کسی اور کو تھا لیکن قتل کوئی اور ہو گیا مثلاً شکاری گولی تو شکار کی طرف چلائے لیکن کسی انسان کو لگ جائے۔ اسی طرح اگر کوئی کنواں کھودے تو اس میں کوئی انسان گر جائے وغیرہ۔اس میں دیت اور کفارہ (ایک گردن کی آزادی ) لازم آئے گی۔ (فقه السنة: ١٦/٣)"}],[227,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ابو ہریرہ رضی اللہ عنہ امیر کے پاس نہ جانا۔ اور اگر اس بارے میں تم مجبور ہو جاؤ تو میری سنت سے تجاوز نہ کرنا، اور اس کی تلوار سے خوف زدہ نہ ہونا۔ اور اس کی تلوار یہ ہے کہ تم انہیں اللہ سے ڈرنے اور اس کی فرماں برداری اختیار کرنے کا حکم دو۔“ یہ حدیث زید بن اسلم سے اُن کے بیٹے عبد الرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں عبدالمنعم بن بشیرا کیلے ہیں۔ میں ٢٨","",{"k":"المعجم الكبير للطبرانی (١١٤/١٩)، مجمع الزوائد (٥/٢٤٦)، فيه عبد المنعم بن بشير الانصارى وهو متهم بالوضع۔"}],[228,"سیدنا عمر بن ابی سلمہ ضیا المیہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو کچھ کھانا پیش کیا تو آپ نے اپنے صحابہ کرام نبی سلیم کو فرمایا: ”اللہ تعالیٰ کا نام لو اور ہر آدمی اپنے آگے سے کھائے۔“ یہ حدیث عبد الرحمن بن سعد سے ابو اسود ہی روایت کرتے ہیں اور اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ مذکورہ حدیث میں کھانے کے آداب بتلائے گئے ہیں: (١) بسم اللہ پڑھ کر کھانے یا پینے کا آغاز کیا جائے۔ (٢) دوسرا ادب یہ ہے کہ اپنی طرف سے اور اپنے سامنے سے کھایا جائے۔ دوسروں کے سامنے سے چن چن کر مت کھاؤ۔ یہ اس صورت میں ہے کہ جب کسی بڑے برتن (طباق، سینی، یا تھالی وغیرہ) میں بیک وقت کئی افراد مل کر کھائیں اور کھانا بھی ایک ہی قسم کا ہو۔ اگر انواع و اقسام کی چیزیں ہوں (جیسے مختلف پھل وغیرہ) تو پھر دوسرے لوگوں کی طرف سے بھی ہاتھ بڑھا کر چیز لینا جائز ہوگا۔","",{"k":"صحیح بخاری (٧٣٩٨)، سنن ابی داؤد (٣٧٧٧)، السلسلة الصحيحة (٥/٦١، ٢٠٦٢)۔"}],[229,"سیدنا ابو ہریرہ بنی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عبد اللہ بن ابی بن سلول کے پاس سے گزرے جبکہ وہ ایک سائے میں بیٹھا ہوا تھا، وہ کہنے لگا: ابن ابی کبشہ نے ہم پر گرد ڈال دی۔ اس کا بیٹا عبد اللہ بن عبد اللہ کہنے لگا: اس ذات کی قسم جس نے آپ کو عزت دی! اور آپ پر کتاب نازل کی! اگر آپ چاہتے ہیں تو میں اس کا سر آپ کے پاس لے کر آ جاتا ہوں؟ تو آپ نے فرمایا: ”نہیں، بلکہ تم اپنے باپ کے ساتھ نیکی کرو، اور اس سے اچھا میل جول رکھو۔“ یہ حدیث محمد بن عمرو سے صرف شیب بن سعید ہی روایت کرتے ہیں، اسے روایت کرنے میں زید بن بشرا کیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (١١٥/١٩)، مجمع الزوائد (١/١٠٩)، صحیح ابن حبان (٤٢٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ کافر و منافق والدین کے ساتھ بھی حسن سلوک کرنا چاہیے۔ رئیس المنافقین عبد اللہ بن ابی نے اپنی زبان سے دین اسلام کا اظہار کیا لیکن دل سے اس کی تصدیق نہ کی۔ معلوم ہوا کہ مسلمانوں کے ساتھ لڑائی کرنا جائز نہیں اگر چہ وہ منافق، فاسق کیوں نہ ہوں، لیکن اس عبد اللہ بن ابی کا بیٹا سچا مسلمان تھا، جس کا نام بھی عبد اللہ رضی اللہ عنہ انہوں نے آپ صلی اللہ علیہ وسلم سے اجازت طلب کی کہ میں اپنے باپ کو قتل کر دوں، واہ سبحان اللہ! صحابہ کرام رینی استان مین کے اندر کس طرح ایمانی جذ بہ اور محبت رسول تھی۔ نبی معظم صلی اللہ علیہ وسلم نے اجازت نہیں دی بلکہ باپ ہونے کی وجہ سے حسن سلوک کا حکم دیا۔"}],[230,"سیدنا عبداللہ ابن عمر ربی الیہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو وراثت اسلام سے قبل تقسیم ہو گئی وہ اسی طرح رہے گی، اور جس وراثت کو زمانہ اسلام نے پالیا تو وہ اسلام کے طریقے پر تقسیم ہوگی۔“ یہ حدیث نافع سے عقیل کے سوا اور عقیل سے ابن لھیعہ کے سوا کسی نے روایت نہیں کی، محمد بن رمح اس کی روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ اسلام لانے کے بعد آدمی کو کتاب وسنت کو اپنانا چاہیے نہ کہ زمانہ جاہلیت والی رسموں کو کیونکہ ایسا آدمی جو جاہلیت کے اعمال پر کار بند ہو اس نے یا تو اسلام قبول ہی نہیں کیا، یا کیا ہے تو پھر اسلام کو دین نہیں سمجھا، اس لیے واجب ہے کہ عقائد وعبادات کے بعد مالی اور غیر مالی سب معاملات اصول اسلام کے مطابق عمل میں لائے جائیں۔","",{"k":"♦، سنن ابی داؤد (٢٩١٤)، المعجم الكبير للطبراني (٩/٤٠١)، قال الالبانى، صحیح۔"}],[231,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حسد (رشک) دو چیزوں میں (درست) ہے۔ ایک وہ شخص جس کو اللہ تعالیٰ نے قرآن مجید عطا فرمایا تو اس نے اس پر عمل کیا اس کے حلال کو حلال اور اس کے حرام کو حرام جانا۔ اور ایک وہ شخص ہے جس کو اللہ تعالیٰ نے مال دیا تو اس نے اس کے ذریعے اپنے قرابت داروں اور رشتہ داروں سے صلہ رحمی کی اور اس میں اللہ تعالیٰ کی اطاعت کی۔“ اس حدیث میں حسد بمعنی رشک ہے شریعت نے حسد کی شدید مذمت کی ہے جب کہ","",{"k":"المعجم الكبير للطبراني (٩١/٢٠)۔","f":"رشک کی حوصلہ افزائی فرمائی ہے جیسا کہ مذکورہ حدیث سے واضح ہے"}],[232,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے صحابہ سے فرمایا: ” کیا تم جانتے ہو مسلمان کون ہے؟ انہوں نے کہا: اللہ تعالیٰ اور اس کے رسول بہتر جانتے ہیں۔ آپ نے فرمایا: جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں۔“ صحابہ نے پوچھا: اور مومن کون ہے؟ آپ نے فرمایا: جس سے لوگ اپنی جانوں اور مالوں کے حوالے سے مطمئن اور بے خوف ہوں۔ “ انہوں نے پوچھا: اور مہاجر کون ہے؟ آپ نے فرمایا: ”جو شخص برائی ترک کر دے اور وہ اس سے اجتناب کرے۔“ یہ دونوں حدیثیں موسیٰ بن علی سے صرف روح بن صلاح ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ کامل مسلمان وہ ہے جس کی زبان اور ہاتھ سے دیگر مسلمان محفوظ رہیں کوئی تکلیف نہ پائیں۔ ”من سلم المسلمون اسلام کا ماخذ ہی سلم ہے جس کے معنی صلح جوئی، خیر خواہی مصالحت کے ہیں، زبان سے ایذا رسانی میں غیبت، گالی گلوچ، بدگوئی وغیرہ جملہ عادات داخل ہیں۔ ہاتھ کی ایذا رسانی میں چوری، ڈاکہ، مار پیٹ، قتل و غارت وغیرہ وغیرہ۔ اگر اس معیار پر آج تلاش کیا جائے تو کتنے مسلمان ملیں گے جو حقیقی مسلمان کہلانے کے مستحق ہوں گے، غیبت، بدگوئی، گالی گلوچ تو عوام کا ایسا شیوہ بن گیا ہے گویا یہ کوئی عیب ہی نہیں ہیں۔ (٢) دوسرا سوال مومن کے متعلق کیا گیا، معلوم ہوا کہ مسلمان اور مومن میں فرق ہے، اور ایمان کا درجہ اسلام سے بڑھ کر ہے، جیسا کہ قرآن وحدیث کے دلائل سے ثابت ہے لیکن اگر الگ الگ دونوں استعمال ہوں گے تو ہر لفظ دوسرے لفظ کے معنی اور حکم پر مشتمل ہوگا۔ معلوم ہوا کہ لوگوں کی نظروں میں امین ہونا مومن کی نشانی ہے۔ جیسا کہ ارشاد باری تعالی ہے: ﴿ قَدْ أَفْلَحَ الْمُؤْمِنُونَ وَالَّذِيْنَ هُمْ لِأَمَانَتِهِمْ وَعَهْدِهِمْ راعُونَ (المومنون: ١تا٨) (٣) یہ بھی معلوم ہوا کہ گناہوں کو چھوڑ دینا ہی اصل ہجرت ہے۔ (٤) حقیقی مہاجر وہ ہے جو دارالحرب سے نکل کر دار الالسلام میں آئے۔ جس ہجرت کا ذکر اس حدیث میں:٢٣٣ - ٥- ہوا ہے یہ حکماً ہجرت ہے۔ ٢٣","",{"k":"سنن ترمذی (٢٦٢٧)، سنن ابو داؤد (٢٤٨١)، ادب المفرد (١١٤٤)، السلسلة الصحيحه ٤٨/٢ (٥٤٩)، المعجم الكبير للطبراني (٩١/٢٠)۔"}],[233,"سیدنا زہرہ بن معبد قریشی اپنے دادا عبد اللہ بن ہشام کے ساتھ بازار کو کھانا خرید نے جاتے سیدنا عبد اللہ بن عم رضی اللہ عنہ اور سیدنا عبد اللہ بن زبیر علی اسلیم انہیں ملتے تو کہتے: ہم کو بھی اس میں RSC Disa شریک کرنا۔ وہ اس لیے یہ بات کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے برکت کی دعا کی تھی۔“ یہ حدیث حضرت عبداللہ بن عمر اور حضرت عبداللہ بن زبیر یا اینجا سے اسی سند سے مروی ہے، اسے روایت کرنے میں ابن وہب اکیلے ہیں۔ نبی معظم مالے مریم نے سیدنا عبد اللہ بن ہشام رضا ال لینے کے لیے برکت کی دعا کی تھی جس کی وجہ سے اللہ تعالیٰ نے ان کے کاروبار میں بہت زیادہ برکت ڈالی تھی۔ سیدنا عبد اللہ بن عمر اور سیدنا عبد اللہ بن زبیر نی انا کا فرمانا کہ ہم کو طعام میں شریک کر لیں اس سے کھانے کے غلہ جات، گندم، چاول وغیرہ مراد ہیں۔ درخواست کرتے کہ ہم کو تجارت میں شریک کر لیں، کیونکہ نبی معظم نے کی برکتوں سے ہم بھی","",{"k":"صحیح بخاری (٢٥٠٢)۔","f":"حاصل کریں۔ چنانچہ اکثر ایسا ہوتا تھا کہ یہ سب حضرات بہت نفع کما لیتے۔ سیدنا عبد اللہ بن ہشام نبی اللہ کے متعلق آتا ہے کہ (ایک اونٹ مع غلہ نفع میں حاصل کر لیتے)۔ (صحیح بخاری، رقم: ٢٥٠٢)"}],[234,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ شعم قبیلے کی ایک عورت نے آپ تعلیم سے حجۃ الوداع کے موقع پر فتویٰ پوچھا: اس نے عرض کیا: یا رسول اللہ! اللہ تعالیٰ کا اپنے بندوں پر حج کا فریضہ میرے باپ کو بڑھاپے اور عمر رسیدہ ہونے کی صورت آپہنچا ہے، مگر وہ سواری پر جم کر بیٹھ نہیں سکتے تو اگر میں ان کی طرف سے حج کروں تو ان کی طرف سے ادا ہو جائے گا؟ تو نبی صلی اللہ علیہ وسلم نے فرمایا ہاں۔“ فائد (١) مذکورہ حدیث سے معلوم ہوا کہ اگر انسان انتہائی بوڑھا ہو یا شدید مریض ہو کہ جس کے تندرست ہونے کی امید ہی نہ ہو، اور اس پر حج فرض ہو چکا ہو تو اس کی طرف سے کوئی دوسرا حج کر سکتا ہے اسے حج بدل کہتے ہیں۔ لیکن یہ یادر ہے کہ اگر اس شخص کے تندرست ہونے کی امید ہو تو پھر کوئی اور اس کی طرف سے حج نہیں کر سکتا۔ شیخ ابن باز نے بھی یہی فتویٰ دیا ہے۔ (مجموع الفتاوى لابن باز: ٤٠٣/١٢) (٢) حج بدل وہ آدمی کر سکتا ہے جس نے پہلے خود حج کر رکھا ہو۔","",{"k":"نعم . )) ابی داؤد، رقم : ١٨٠٩ . صحیح بخاری (٤٣٩٩)، سنن۔"}],[235,"سیدنا عبد اللہ ابن عباس خلیل اللہ نے بیان کی، رسول اللہ علیم نے فرمایا: ”جو شخص یہ کہے کہ اللہ تعالیٰ ہماری طرف سے محمد صلی اللہ علیہ وسلم کو وہ جزا عطا فرمائے جس کے وہ اہل ہیں تو وہ ہزار دن (اس کا ثواب) لکھنے والے ستر ہزار فرشتوں کو تھکا دے گا۔“ یہ حدیث عکرمہ سے صرف جعفر بن محمد ہی روایت کرتے ہیں اور جعفر سے صرف معاویہ بن صالح روایت کرتے ہیں، اسے روایت کرنے میں ھانی بن متوکل اکیلے ہیں۔:٢٣٦","",{"k":"السلسلة الضعيفة (٧٦/٣، ١٠٧٧)، المعجم الكبير (٩/٤٠٧)، ضعيف الترغيب و الترهيب (١٠٣٦)۔"}],[236,"سیدنا ابو موسی اشعری رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص بیمار ہو جائے یا سفر کرے ( اور وہ عمل نہ کر سکے ) تو اس کے لیے اتنا ہی اجر ہو گا جس طرح وہ حالت صحت اور گھر میں مقیم ہونے کی حالت میں عمل کیا کرتا تھا۔ یہ حدیث مسعر سے صرف حفص بن غیاث ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن ابی الحواری اکیلے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ کا خاص لطف و کرم اور فضل و احسان ہے که اگر آدمی بیماری یا سفر جیسی مجبوری سے اپنے ذکر و عبادات کے معمولات پورے نہ کر سکے تو اللہ تعالیٰ اس کے اعمال نامہ میں اپنے حکم سے وہ معمولات لکھواتا ہے جو بندہ تندرستی اور اقامت کی حالت میں کیا کرتا تھا۔ (٢) اور انسان کو اپنی صحت و تندرستی اور فراغت کی قدر کرتے ہوئے اپنے وقت کو نیک اعمال بجالانے میں صرف کرنا چاہیے تا کہ اگر بعد میں بیماری یا سفر کی وجہ سے وہ عمل نہ کر سکے تو ثواب مل سکے۔","",{"k":"سنن ابی داؤد (٣٠٩١)، الادب المفرد (٥٠٠)، المعجم الكبير للطبراني: ٢٠ / ١٧٢ قال الالبانی حسن۔"}],[237,"سیدہ عائشہ علی العنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے ہاتھ سے خوشبو لگائی، پھر وہ اپنی عورتوں کے پاس گئے، پھر احرام کی حالت میں صبح کی۔“","",{"k":"صحیح بخاری (١٥٣٩)، سنن ابی داؤد (١٧٤٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ احرام سے قبل خوشبو لگانا سنت ہے، لیکن حالت احرام میں خوشبو لگانا درست نہیں ہے۔ جمہور، امام شافعی، ابو حنیفہ، احمد، ثوری، ابو یوسف بیشہ اسی کے قائل ہیں۔ امام مالک، محمد بن حسن، زہری رحمہم اللہ نے کہا ہے کہ احرام باندھتے وقت خوشبو لگانا جائز نہیں۔ (فتح الباری: ١٧٨/٤، شرح مسلم للنووی: ٣٢/٥، نیل الاوطار: ٣٠٨/٣)"}],[238,"سیدنا ابو برید اپنے باپ سے روایت کرتے ہیں انہوں نے کہا: رسول اللہ صلئے علیم نے فرمایا: ”میں نے تم کو تین باتوں سے منع کیا تھا: (١) قبروں کی زیارت سے تو اب ان کی زیارت کیا کرو، اور کوئی فضول بات نہ کرو۔ (٢) میں نے تم کو قربانیوں کے گوشت سے منع کیا تھا تو اب وہ کھاؤ اور ذخیرہ کرو۔(٣) اور میں نے تم کو چند برتنوں میں نبیذ بنانے سے منع کیا تو اب تم سب برتنوں میں پی لیا کرو مگر نشہ آور چیز نہ پینا۔“ یہ حدیث حماد بن ابی سلیمان سے صرف عبد اللہ بن بکیر ہی روایت کرتے ہیں۔","",{"k":"و، و، سنن نسائی (٤٤٢٩)، سنن ابی داؤد (٣٢٩٨)، صحيح الجامع الصغير (٢٤٧٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ پہلے قبروں کی زیارت کرنا منع تھا بعد میں نبی معظم ما علیم نے اجازت دے دی۔ ایک روایت میں ہے کہ قبروں کی زیارت کرو کیونکہ ((فانها تذكركم الاخره)) (صحیح مسلم، کتاب الجنائز: ٩٧٧) یہ تمہیں آخرت کی یاد دلاتی ہیں۔“ (٢) پہلے نبی معظم صلی اللہ علیہ وسلم نے تین دن سے زیادہ گوشت کو ذخیرہ کرنے سے منع فرمایا تھا بعد میں رخصت دے دی۔ تاہم اگر آج بھی ضرورت مند غر با زیادہ ہوں تو ذخیرہ اندوزی سے اجتناب کرنا چاہیے۔ (٣) چند برتنوں میں نبیذ بنانے سے منع فرمایا تھا اس کی وجہ یہ تھی کہ وہ برتن شراب میں استعمال ہوتے تھے اس وجہ سے پھلوں کے دوسرے مشروبات میں تخمیر پیدا کر سکتے تھے۔ اگر وہ لوگوں کے پاس موجود بھی تھے تو اب اس قباحت سے پاک ہو چکے تھے۔ اس لیے اجازت دے دی۔ واللہ اعلم ٢٣٩"}],[239,"سیدہ فاطمہ بنت قیس بنی النوجا سے روایت ہے کہ ان کے خاوند نے انہیں تین طلاقیں دے دیں تو نبی صلی اللہ علیہ وسلم نے اسے رہائش اور خرچہ نہیں دلایا۔“ مذکورہ حدیث سے معلوم ہوا کہ طلاق بائنہ کے بعد شوہر پر نہ خرچہ لازم ہے اور نہ رہائش الا کہ عورت حاملہ ہو تو خرچہ لازم ہے، جیسا کہ نبی سے ہم نے سیدہ فاطمہ بنت قیس بنا (جو کہ تیسری طلاق والی تھیں) سے کہا: تیرے لیے خرچہ نہیں الا کہ تو حاملہ ہوتی ( تو تجھے خرچ دیا جاتا)۔ (صحیح مسلم، کتاب الطلاق، رقم: ١٤٨٠)","",{"k":"صحیح مسلم (٣٧١٤٨٠)، سنن ترمذی (١١٨٠)، سنن ابی داؤد (٢٢٨٨)۔"}],[240,"سیدنا عبد الرحمن بن افلح کہتے ہیں کہ صحابہ کی ایک جماعت نے مجھے سیدنا عبداللہ ابن عمر بنی اہلیہ کے پاس بھیجا، وہ آپ سے نماز وسطی کے متعلق پوچھ رہے تھے۔انہوں نے کہا: ہم باتیں کرتے تھے کہ وہ نماز وہی ہے جس میں رسول اللہ صلی اللہ علیہ وسلم کو قبلہ کی طرف موڑا گیا تھا اور وہ نماز ظہر ہے۔“ یہ حدیث عبدالرحمن بن افلح، حضرت ابن عمر سے صرف اسی سند سے روایت کرتے ہیں، اسے روایت کرنے میں موسیٰ بن ربیعہ اکیلے ہیں راجح بات یہ ہے کہ نماز وسطی سے مراد نماز عصر ہے جیسا کہ صحیح بخاری میں آتا ہے کہ عصر کی نماز غزوہ خندق والے دن قضا ہو گی تو نبی معظم صلی اللہ علیہ وسلم نے ان لوگوں کے لیے بد دعا کی کہ انہوں نے ہم کو صلوۃ وسطی نہیں پڑھنے دی۔ (صحیح بخاری، کتاب الجهاد، رقم: ٢٩٣١)","",{"k":"المعجم الكبير للطبرانی (١٤٩/١١)، مجمع الزوائد (١/٣٠٩)۔"}],[241,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”روشن اور چمک دار رات اور دن میں مجھ پر بہت درود بھیجا کرو کیونکہ تمہارا درود مجھ پر پیش کیا جاتا ہے۔","",{"k":"السلسة الضعيفة (٥/٢٥٢، ٢٢٥٣)، المعجم الكبير للطبراني (١٩/١١٥)، ضعيف الجامع (١١٠٥)۔"}],[242,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی شخص نماز کا قصد کرے تو سب سے پہلے سجدے کی جگہ کو درست اور برابر کرے اور اس کو ایسے ہی نہ چھوڑ دے۔ یہاں تک کہ جب سجدے کے لیے جھکے تو پھونک کر سجدہ کرنے لگے کیونکہ تم میں سے کسی کا اپنی پھونک ماری ہوئی جگہ پر سجدہ کرنے سے آگ کی چنگاری پر سجدہ کرنا بہتر ہے۔“","",{"k":"ضعيف الجامع الصغير (٦١٥)، المعجم الكبير : ١٩ / ١١٥ . (۔"}],[243,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”نماز ایک بہترین موضوع ہے ( اللہ تعالیٰ نے عبادات میں سے جسے مشروع قرار دیا ہے ) تو جو شخص اسے زیادہ کرنے کی طاقت رکھتا ہو وہ اس کو زیادہ کرے۔“ یہ ساری احادیث محمد بن کعب القرظی، حضرت ابو ہریرہ سے اسی سند سے روایت کرتے ہیں، اسے ابومودود روایت کرنے میں اکیلے ہیں۔","",{"k":"صحيح الجامع الصغير (٣٨٧٠)، المعجم الكبير للطبراني (١٩/١١٦)، صحيح الترغيب والترهيب (٣٩٠)۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے کہ نماز اللہ تعالیٰ کے ساتھ ہم کلام ہونے کا بہترین ذریعہ ہے لہذا آدمی کو چاہیے کہ اس کو لمبا کرے۔ یعنی قیام، رکوع، سجود وغیرہ اور سنت نبوی سے علم کے مطابق ادا کرے۔"}],[244,"سیدنا ابو رافع ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ایک مینڈھا ذبح کیا، پھر کہا: یہ میری طرف سے اور میری امت کی طرف سے ہے۔ یہ حدیث عمارہ بن غزیہ سے صرف یحییٰ بن ایوب ہی روایت کرتے ہیں۔ ایک بکری کا اپنے گھر کے تمام افراد کی طرف سے کفایت کرنا تو بالکل صحیح ثابت ہے۔ جیسا کہ سیدنا ابو ایوب انصاری رضی اللہ عنہ لینے سے سوال کیا گیا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں قربانیاں کیسے ہوتی تھیں تو انہوں نے کہا: عہد رسالت میں آدمی اپنی طرف سے اور اپنے گھر والوں کی طرف سے ایک بکری قربان کرتا تھا۔ وہ اسے کھاتے تھے اور کھلاتے تھے حتی کہ لوگوں نے تکبر شروع کر دیا تو اس طرح ہو گیا جو تم آج دیکھ رہے ہو۔ (صحیح سنن ابن ماجه، کتاب الاضحی، رقم: ٢٥٤٦) مگر لوگوں کی جماعت کی طرف سے ایک بکری کا ذبح کرنا صرف رسول اللہ سے کم کی خصوصیت تھی۔","",{"k":"سنن ابی داؤد (٢٨١٠)، مجمع الزوائد (٤/٢٢)۔"}],[245,"سیدنا حذیفہ بن یمان رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب ایک مومن دوسرے مومن کو ملے تو اسے سلام کہے، اس کا ہاتھ پکڑ کر مصافحہ کرے تو اس کے گناہ اس طرح جھڑ جاتے ہیں جس طرح درخت کے پتے جھڑتے ہیں۔ یہ حدیث ولید بن ابی الولید سے صرف موسیٰ بن ربیعہ ہی روایت کرتے ہیں۔","",{"k":"السلسلة الصحيحة (٢/٥٢٦، ٢٠٠٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سلام کے ساتھ مصافحہ کرنا چاہیے کیونکہ اس سے محبت میں اضافہ ہوتا ہے، اور اللہ تعالیٰ گناہوں کو مٹا دیتے ہیں۔ صحابہ کرام رضی اللہ عنہم میں بھی اسی طرح ہی کرتے تھے کہ جب ملاقات ہوتی ایک دوسرے سے مصافحہ کرتے تھے۔ سیدنا انس بن مالک یا یہ فرماتے ہیں کہ جب یمن والے آئے تو نبی معظم مالے علیم نے فرمایا: ”اہل یمن آگئے ہیں اور وہ تم میں سے زیادہ نرم دل ہیں اور وہ پہلے لوگ ہیں جو مصافحہ لے کر آئے ہیں۔ (بخاری ادب المفرد، رقم: ٩٦٧) نبی معظم صلی اللہ علیہ وسلم نے اہل یمن کی اس خصوصیت سے تعریف فرمائی ہے کہ وہ مصافحہ کرتے ہیں۔ ٢٤٦"}],[246,"سیدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا، ”ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بادل کے دن قبلے کے علاوہ دوسری جانب نماز ادا کر لی جب نماز پوری کر لی، سلام پھیرا تو سورج روشن ہو گیا۔ ہم نے کہا: اللہ کے رسول! ہم نے قبلے کے خلاف جانب نماز پڑھ لی ہے؟ آپ نے فرمایا: ” تمہاری نماز اپنے حق کے ساتھ اللہ عز وجل تک اٹھالی گئی ہے۔ یہ حدیث ابراہیم بن ابی علیہ سے صرف اسماعیل بن عبداللہ اور اسماعیل سے صرف ابو داؤد ہی روایت کرتے ہیں، اسے روایت کرنے میں ہشام بن سلام اکیلے ہیں۔","",{"k":"مجمع الزوائد (١٥/٢)، فيه احمد بن رشدين، قال ابن عدی۔"}],[247,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اللہ تعالیٰ نے حق کو عمر بن خطاب رضی اللہ عنہ کی زبان اور دل پر جاری کیا ہے۔ یہ حدیث ابراہیم بن ابی عبلہ سے صرف ھانی بن عبدالرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں معلی بن الولید ا کیلے ہیں۔ مذکورہ روایت میں سیدنا عمر رضی اللہ عنہ کی فضیلت کا اثبات ہے۔ اس عظیم ترین مدح کے با وجود سیدنا عمر رضی اللہ عنہ عن الخطا نہیں ہیں۔ جہاں کہیں محسوس ہوا کہ ان کا قول و فعل قرآن وسنت کے مطابق نہیں ہے صحابہ کرام بی ایم نے ان سے اختلاف کیا۔ غیر مشروط اطاعت کے لائق صرف محمد رسول اللہ سے ہم ہیں۔ ٢٤٨","",{"k":"سنن ابی داؤد (٢٩٧٢)، سنن ♦، ترمذی، رقم : ٣٦٨٢ قال الالباني صحیح۔"}],[248,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ بے شک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی شخص اپنے بھائی سے دن میں کئی دفعہ ملاقات کرے تو وہ اسے سلام کہے۔“ فائد مذکورہ حدیث سے معلوم ہوا کہ جب بھی ملاقات ہو ایک دوسرے کو سلام کہنا چاہیے۔ بلکہ ایک حدیث میں ہے کہ سیدنا ابو ہریرہ بیا نیہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی اپنے بھائی سے ملے تو اسے سلام کہے۔ پس اگر ان کے درمیان کوئی درخت، دیوار، یا پھر حائل ہو جائے اور پھر دوبارہ ملے تو بھی سلام کہے۔ (سنن ابی داؤد، کتاب الادب، رقم: ٥٢٠٠، بخاری ادب المفرد، رقم: ١٠١٠، اسناده صحیح اس کا مطلب یہ نہیں کہ جدا ہوتے وقت سلام کی ضرورت نہیں بلکہ رسول اللہ علیم نے فرمایا: ”جب تم میں سے کوئی شخص مجلس میں پہنچے تو سلام کہے، اگر اس کا ارادہ بیٹھنے کا ہو تو بیٹھ جائے پھر جب اٹھے تو سلام کہے، کیونکہ پہلے سلام کا حق دوسرے سے زیادہ نہیں ہے۔ (صحيح الجامع الصغير، رقم: ٤٠٠)","",{"k":"کر المعجم الكبير للطبراني (١١/١٥٠)، حلية الاولياء (٥/١٣)۔"}],[249,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کو یہ بات اچھی لگے کہ اس کی عمر دراز کی جائے اور اس کے رزق میں فراخی کی جائے تو وہ رشتہ داری کو ملا کر رکھے۔“ یہ حدیث ابی زبیر سے صرف عمرو بن حارث ہی روایت کرتے ہیں، اسے روایت کرنے میں رشدین اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ صلہ رحمی کرنے والے کے لیے اللہ تعالیٰ عمر اور مال میں","",{"k":"صحیح بخاری، رقم: صحیح مسلم (٤٧٤٤، ٤٧٤٥، ١٩٧٦)۔","f":"اضافہ کر دیتے ہیں۔"}],[250,"سیدنا انس بن مالک نبی اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عزوجل فرماتا ہے: جب میں اپنے بندے کو اس کی دو پیاری چیزوں ( آنکھوں ) کے ساتھ آزماتا ہوں اور وہ صبر کرے تو میں اس کو اس کے عوض میں جنت عنایت کر دیتا ہوں۔ یہ حدیث مطلب سے ابن ھاد روایت کرتے ہیں، اسے روایت کرنے میں رشدین اکیلے ہیں۔","",{"k":"صحیح بخاری (٥٦٥٣)، صحيح الجامع الصغير (٤٣٠٢)، الادب المفرد (٥٣٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ جب کسی بندے کو آنکھوں کی تکلیف میں مبتلا کرتے ہیں تو اگر وہ اس پر صبر کرتا ہے اور اللہ تعالیٰ کی رضا پر راضی رہتا ہے تو اس کے عوض اللہ تعالیٰ اس کو جنت عطا کریں گے۔ .٥١"}],[251,"سیدنا زید بن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم داخل ہوئے جبکہ بلال صبح کے لیے اقامت کہہ رہے تھے۔ آپ نے دیکھا کہ ایک آدمی صبح کی دو رکعت پڑھ رہا تھا۔ تو آپ نے فرمایا: ” کیا دونوں نمازیں اکٹھی پڑھ رہے ہو؟“ یہ حدیث زید بن ثابت سے اس سند سے ہی مروی ہے، اُن سے روایت کرنے میں عبدالمنعم بن بشیرا کیلئے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جب اقامت ہو جائے تو فرض نماز کے علاوہ کوئی اور نماز نہیں ہوتی اگر فجر کی سنتیں ہوں تو وہ بھی نہ پڑھی جائیں بلکہ فرضوں کے بعد پڑھ لے۔","",{"k":"السلسلة الصحيحة (٦/٨٧، ٢٥٨٨)۔"}],[252,"اسحاق بن عبد اللہ طفاوی کہتے ہیں ”سیدنا عبداللہ بن عمر رضی اللہ عنہما جب بھی رسول اللہ الے علم کو یاد کرتے تو ضرور رو پڑتے۔“ یہ حدیث اسحاق بن عبد اللہ الطفا وی سے صرف عمر بن محمد ہی روایت کرتے ہیں، اسے روایت کرنے میں ولید بن مسلم اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١١/١٥٠)، فيه احمد بن رشدين قال ابن عديو غيره۔"}],[253,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے بدھ، جمعرات اور جمعہ کا روزہ رکھا تو اللہ تعالیٰ اس کے لیے جنت میں ایک گھر بنا دیتا ہے جس کا اندرونی حصہ باہر سے اور بیرونی حصہ اندر سے نظر آتا ہے۔ یہ حدیث میمون بن مہران سے صرف صالح بن جبلہ ہی روایت کرتے ہیں، اسے روایت کرنے میں شہاب بن خراش اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (٢٨٨/٧)، السلسلة الضعيفة (٥١٩٣)، ضعيف الترغيب و الترهيب (٦٣٠)۔"}],[254,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ انھوں نے نبی صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”جس نے بدھ جمعرات اور جمعہ کا روزہ رکھا تو اللہ تعالیٰ اس کے لیے موتیوں، یاقوت اور زبرجد کا محل بنا دیتا ہے، اور اس کے لیے آگ سے براءت کی سند لکھ دیتا ہے۔“ یہ حدیث انس سے صرف ابوقبیل المعافری ہی روایت کرتے ہیں، ان کا نام حی بن یومن ہے۔ ٢٥٥","",{"k":"ضعيف الترغيب و الترهيب (٦٣٢)، السلسلة الضعيفه (٥١٩٤)۔"}],[255,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے فرمایا: ” اگر عوالی کے رہنے والوں میں سے کوئی آدمی رسول اللہ نے تم کو نصف رات کے وقت جو کی روٹی کی طرف دعوت دیتا تو پھر بھی آپ اس کی دعوت قبول فرما لیتے۔“ یہ حدیث اعمش سے صرف ابو مسلم اور ابو مسلم سے عمرو بن عثمان ہی روایت کرتے ہیں، اسے روایت کرنے میں بیٹی بن سلیمان اکیلے ہیں۔ مذکورہ حدیث میں دعوت کی اہمیت کا اثبات ہے کہ نبی معظم نے ان کو کوئی دعوت دیتا اگر چہ معمولی کھانا ہوتا اور وہ جگہ بھی دور ہوتی (مدینہ منورہ کے جنوب مشرق کی جانب کی آبادیوں کو عوالی (بالائی علاقے ) اور شمال کی جانب کے علاقے کو سافلہ ( نشیبی علاقہ کہتے تھے ) پھر بھی رسول اللہ ملت اعلام جایا کرتے تھے۔ حدیث شریف میں آتا ہے کہ مسلمان کے مسلمان پر چھ حق ہیں۔ ان میں سے ایک حق یہ ہے) ((واذا دعاك فاجبه)) (صحیح مسلم، کتاب السلام) اور جب وہ تجھے دعوت دے تو اس کو قبول کر۔“ ایک حدیث میں ہے کہ ((ومن لم يجب الدعوة فقد عصى الله ورسوله)) جس نے دعوت قبول نہ کی اس نے اللہ اور اس کے رسول کی نافرمانی کی۔“","",{"k":"سنن ابو داؤد، رقم : ١٠٥٥-٤٠٤، المعجم الكبير للطبراني (١/٤٤، ٤١)، مجمع الزوائد (١٤٢٢١)، رجاله ثقات۔"}],[256,"سیدنا سہل بن سعد رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص بھی ( حج یا عمرے کا) تلبیہ یعنی ((لبَّيْكَ اللَّهُمَّ لَبَّيْكَ)) کہے تو اس کے دائیں، بائیں تمام پتھر اور درخت بھی تلبیہ کہتے ہیں۔“ یہ حدیث معاویہ بن صالح سے صرف ابن وھب ہی روایت کرتے ہیں،اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔","",{"k":"سنن ترمذی (٨٢٨)، المعجم الكبير للطبراني (٤٠٢/٥، ٥٦٠٩)، قال الالباني، صحیح۔","f":"مذکورہ حدیث میں تلبیہ پکارنے کی فضیلت کا تذکرہ ہے۔ یہ بھی معلوم ہوا کہ تلبیہ اونچی آواز سے پکارنا چاہیے کیونکہ اونچی آواز سے پکارے گا تو تب ہی پتھر اور درخت سنیں گے اور وہ تلبیہ پکاریں گے۔ جیسا کہ رسول اللہ العلیم نے فرمایا: ”میرے پاس جبریل علینام تشریف لائے اور انہوں نے مجھے حکم دیا کہ میں اپنے صحابہ کو اونچی آواز سے تلبیہ پکارنے کا حکم دوں۔“ صحیح) (سنن ابی داؤد، رقم: - سنن ترمذی، رقم: ٨٢٩، اسناده"}],[257,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اسلام نے فرمایا: ” جو شخص جمعہ پڑھنے آئے تو وہ فنسل کرے۔ یہ حدیث عبداللہ بن سعید بن ابی ہند سے صرف بکر بن صدقہ روایت کرتے ہیں، اسے روایت کرنے میں حامد بن بیٹی اکیلے ہیں۔","",{"k":"صحيح بخاری (٨٧٧)۔"}],[258,"سیدنا عبداللہ ابن عمر نبی الیہ سے روایت ہے کہ نبی مٹے علیم نے فرمایا: ”جو شخص جمعے کو آئے تو وہ غسل کرے۔ یہ حدیث علاء بن برد سے صرف موسیٰ بن ناصح ہی روایت کرتے ہیں۔","",{"k":"تقدم تخريجه: انظر (١٨، ٢٥٧)۔"}],[259,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ نے فرمایا: ”جو شخص جمعہ کو آئے تو وہ غسل کرے۔“ یہ حدیث ابن ابی اولیس سے صرف اُن کے بیٹے ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن محمد بن مالک بن انس اکیلے ہیں۔ ٦٠","",{"k":"تقدم تخريجه، انظر (١٨، ٢٥٧)۔"}],[260,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: انبیا علی اسلام کے مابین ایک کو دوسرے پر فضیلت نہ دو۔“","",{"k":"صحیح بخاری (٦٩١٦)، سنن ابو داؤد (٤٦٦٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ انبیاء کرام کو ایک دوسرے پر فضیلت نہیں دینا چاہیے۔ اس سے امت میں افتراق کا فتنہ پیدا ہونا ممکن ہے، کیونکہ ایک کسی نبی کو افضل کہے گا تو دوسرا کسی اور کو۔ جس نبی کو کسی نے مفضول قرار دیا ہو گا اس کے ماننے والے خواہ مخواہ دوسرے انبیا السلام کے بارے میں ناروا باتیں کریں گے یہ سارا معاملہ فتنہ انگیز ہے اس لیے نبی معظم ملنے سلیم نے کسی نبی کو دوسرے پر فضیلت دینے کا سلسلہ ہی بند کر دیا۔ تا ہم اللہ تعالیٰ نے انبیا علیالسلام کو ایک دوسرے پر فضیلت دی ہے، جیسا کہ ارشاد باری تعالیٰ ہے: تلك الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ﴾ (البقره: ٣٥٣) مگر نام لے کر کہیں بھی نہیں کہا کہ فلاں نبی فلاں سے افضل ہے۔ ٢٠١"}],[261,"سيدنا كعب بن مالک نبی الیہ سے روایت ہے کہ رسول اللہ علیم نے مدینہ کی دو پہاڑیوں کی جگہ کو حرام قرار دیا ہے کہ وہاں کے وحشی جانوروں کا شکار نہ کیا جائے۔“","",{"k":"·:٢٦١ سنن ابو داؤد (٢٠٣٤)، قال الالبانى، صحيح۔","f":"ابو داؤد میں ہے نبی معظم تعلیم نے ارشاد فرمایا: ”مدینہ منورہ عاشر (عیر ) اور ثور (دو پہاڑوں) کے مابین حرم ہے۔ (سنن ابی داؤد، كتاب المناسك، رقم: ٢٣٤) یہ اس طرح حرم اور محترم ہے جیسا کہ مکہ مکرمہ ہے۔ (٢) یہ بھی معلوم ہوا کہ حرم کی حدود میں شکار نہیں کرنا چاہیے۔"}],[262,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم اور سیدنا ابو بکر وسیدنا عمر بنی الجھا دونوں عیدوں کے موقع پر خطبہ سے پہلے نماز عید پڑھا کرتے تھے۔“ مذکورہ حدیث سے معلوم ہوا کہ نماز عید کے بعد خطبہ دینا مسنون ہے۔ اس کی ایک اور واضح دلیل یہ ہے کہ نبی معظم من این عید الفطر اور عید الاضحی کے روز عید گاہ کی طرف تشریف لے جاتے، اور سب سے پہلے آپ صلی اللہ علیہ وسلم جس چیز کی ابتدا فرماتے وہ نماز ہوتی، نماز سے فارغ ہو کر لوگوں کی طرف رخ پھیر کر کھڑے ہو جاتے، لوگ اپنی صفوں میں ہی ہوتے آپ صلی اللہ علیہ وسلم انہیں نصیحت فرماتے اور احکام جاری فرماتے۔ (صحیح بخاری، کتاب الجمعة، رقم: ٩٥٦، صحیح مسلم، رقم: امام شوکانی اللہ کا بھی یہی فتویٰ ہے کہ خطبہ نماز عید کے بعد دیا جاۓ۔ (نیل الاوطار: ٥٩٣/٢) سب سے پہلے جس شخص نے نماز عید سے پہلے خطبہ دے کر سنت کی مخالفت کی تھی وہ مروان (اموی خلیفہ ) تھا۔ یہی وجہ ہے کہ اسی وقت سیدنا ابوسعید خدری رضی اللہ عنہ نے کھڑے ہو کر فرمایا تھا! اے مروان: تو نے سنت کی مخالفت کی ہے تو نے نماز سے پہلے خطبہ شروع کر دیا ہے۔ (صحیح مسلم، کتاب الایمان، رقم: ٤٩، سنن ابی داؤد، رقم: ١١٤٠) ٦٣","",{"k":"صحیح بخاری (٩٦٣)، سنن نسائی (٥٦٤)۔"}],[263,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ طلیعے علیم نے فرمایا: ”وسیلہ اللہ کے پاس ایک درجہ ہے جس سے اوپر کوئی درجہ نہیں، اس کے متعلق اللہ تعالیٰ سے سوال کرو کہ وہ درجہ مجھے عنایت فرمائے۔“","",{"k":"صحيح الجامع الصغير (١٩٨٨)، مسند احمد (٣/٨٣)، السلسلة الصحيحة، رقم : ) ٣٥٧۔","f":"وسیلہ کی جمع وسائل آتی ہے۔ اس کا معنی ہے ایسی چیز جس کے ذریعے کسی دوسری چیز تک پہنچا جائے اس سے مراد جنت میں ایک مقام ہے۔ وہ نبی معظم صلی اللہ علیہ وسلم کو نصیب ہوگا۔ اس لیے نبی معظم الے علیم نے فرمایا: اذان کے بعد یہ دعا پڑھا کرو۔ ((اللهم رب هذه الدعوة الخ ) حديث"}],[264,"سیدنا معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عمر بھر کے لیے دی گئی چیز وراثت کا مقام رکھتی ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ عمر بھر کے لیے دی ہوئی چیز بعد میں اس کے ورثا میں تقسیم ہو جائے گی۔ اہل علم نے اس کی تین اقسام بیان کی ہیں۔ (١) مطلق طور پر عمر بھر کے لیے ہبہ کر دینا۔ (٢) موہوب کی زندگی کی شرط پر دینا۔ (٣) یوں کہنا کہ یہ تمہارے لیے ہے، اور تمہارے بعد تمہارے ورثا کے لیے ہے۔ تیسری صورت جمہور کا موقف ہے اور یہی راجح ہے۔ (فتح الباری: ٢٨٢/٥ نیل الاوطا: ٧٤/٤) ٦٥","",{"k":"سنن نسائی (٣٧١٦)، سنن ابی داؤد (٣٥٥٣)، المعجم الكبير للطبراني (١٤/٢٣٨)، قال الالباني، صحیح۔"}],[265,"سیدنا ابو تميم بن حارث بن صمہ انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ایم نے فرمایا: ”نمازی کے آگے سے گزرنے والا اگر چالیس تک ( گزرنے کے بجائے ) کھڑا رہے تو یہ اس کے آگے سے گزرنے سے بہتر ہے۔“","",{"k":"صحیح بخاری، صحيح مسلم (٥٠٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مذکورہ سخت وعید سے بچنے کے لیے نمازی کے آگے سے گزرنے سے اجتناب کرنا ضروری ہے۔ اور نمازی کے لیے بھی یہی بہتر ہے کہ وہ ایسی جگہ نماز نہ پڑھے جہاں سے لوگوں کا گزرنا ضروری ہو۔ اس حدیث کی وجہ سے امام نووی اللہ اور امام صنعانی اللہ نے نمازی کے آگے سے گزرنا حرام قرار دیا ہے۔ (شرح مسلم: ٤٦٥/٣، سبل السلام: ٣٢٧/١) حدیث کے ظاہری الفاظ سے معلوم ہوا کہ وعید صرف نمازی کے آگے سے گزرنے والے کے لیے ہے، آگے بیٹھنے، لیٹنے والے یا کھڑے ہونے والے کے لیے نہیں، جمہور علماء کا یہی قول ہے۔ امام ابن قیم اور شیخ الاسلام امام ابن تیمیہ رحمہما اللہ نے بھی یہی موقف اختیار کیا ہے۔ (توضیح الاحکام: ٦١/٢) یہاں یہ بات بھی یادر ہے کہ یہ گناہ اس وقت ہے جب نمازی نے اپنے سامنے سترہ نہ رکھا ہو ورنہ سترے کے پیچھے سے کوئی بھی گزرسکتا ہے جیسا کہ فرمان نبوی ہے کہ \"پالان کے پچھلے حصے کے برابر کوئی چیز تم میں سے کسی ایک کے سامنے موجود ہو تو پھر جو بھی اس کے سامنے سے گزر جائے اسے نقصان نہیں پہنچا سکتا۔ (صحیح مسلم، کتاب الصلاة، رقم: ٤٩٩، سنن ابی داؤد، رقم: ٢٨٥) اسی طرح اگر انسان با جماعت نماز ادا کر رہا ہو اور اس کے سامنے سے کوئی گزر جائے تو کوئی نقصان نہیں کیونکہ اس وقت مقتدیوں کے لیے امام سترہ کے قائم مقام ہوتا ہے جیسا کہ نبی معظم تعلیم نے خود سامنے سترہ رکھا لیکن صحابہ دین اسلام کو سامنے سترہ رکھنے کا حکم نہیں دیا۔ (صحیح بخاری، رقم: ٧٦، صحيح مسلم، رقم: ٤ ٥٠) نمازی کے لیے سترے کو لازم قرار دیا گیا ہے، متعدد احادیث میں اس کا حکم موجود ہے سیدنا ابوسعید خدری اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی نماز پڑھے تو سترے کی طرف نماز پڑھے اور اس کے قریب ہو کر کھڑا ہو )۔ (صحیح ابو داؤد، کتاب الصلاة، رقم: ٢٤٦) سیدہ عائشہ بنی الشیا سے مروی ہے کہ صرف سترہ کی جانب ہی نماز پڑھو۔ (ابن خزیمه، رقم: ٨٠٠، حاکم: ٢٥١/١) جمہور علماء نے اسے مستحب کہا ہے۔ (سبل السلام: ٣٢٩/١) امام شوکانی، ابن حزم، علامہ ناصر الدین البانی ریشم نے اسے واجب قرار دیا ہے۔ (نیل الاوطار؛ ١٩٨/٢ المحلى: ٨/٤، تمام المنة ص ٣٠٠) سترے اور نمازی کے درمیان کتنا فاصلہ ہونا چاہیے؟ اس کے متعلق یہ حدیث پیش نظر رہنی چاہیے کہ نبی معظم مالے علیم نے کعبہ میں داخل ہو کر نماز پڑھی تو دیوار اور آپ صلی اللہ علیہ وسلم کے درمیان تین بازوؤں کا فاصلہ تھا۔ (صحیح بخاری، رقم: ٥٠٦، مسند احمد: ١٣/٦)"}],[266,"سیدہ عائشہ نبی الیہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: کنوئیں میں زائد جمع پانی کسی سے نہ روکا جائے۔“ مذکورہ حدیث سے معلوم ہوا کہ زائد پانی کو روکنا نہیں چاہیے، جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”پانی، آگ اور گھاس کو نہ روکا جائے۔“ (ارواء الغليل: ٩٠٧/٦، سنن ابن ماجه رقم: ٢٤٧٣، اسنادہ صحیح) مطلب یہ ہے کہ جب یہ چیزیں ذاتی ضروریات سے زائد ہوں تو بوقت ضرورت لوگوں کو ان سے روکنا جائز نہیں۔ یہ اس وقت ہے جب کسی کی ملکیت نہ ہو۔ البتہ جو پانی کسی کی ملکیت میں ہو مثلاً مشکیزے یا برتنوں میں یا کنواں وغیرہ تو اسے بیچنا اور خریدنا جائز ہے۔ جیسا کہ سیدنا عثمان رضی اللہ عنہ نے بئر رومہ خرید کر مسلمانوں کے لیے وقف کر دیا تھا۔ (صحیح بخاری، رقم: ٢٧٧٨، سنن ترمذی، رقم: ٣٦٩٩) ٢٦٧","",{"k":"السنن الكبرى للبيهقي (١٥٢/٦)، مسند احمد (١١٢/٦)، قال الشيخ شعيب الارناؤط: حديث صحيح۔"}],[267,"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بات کا اعتبار اس طرح کیا جائے گا جس طرح تم سمجھتے ہو۔“","",{"k":"مجمع الزوائد: ١/ ١٣٥ فيه احمد بن رشدين كذبه ابن عدى وغيره۔"}],[268,"سیدہ عائشہ بین النہا سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کسی کو ضرر دیا جائے نہ کسی سے ضر ر لیا جائے۔“ مذکورہ روایت سے معلوم ہوا کہ کسی مسلمان کو تکلیف پہنچانا جائز نہیں اور اگر کوئی تکلیف پہنچائے تو اس کو جواباً اتنا ہی ضرر پہنچانا جائز ہے، اس سے زاید ظلم ہوگا، جبکہ معاف کر دینا بہتر ہے۔","",{"k":"سنن ابن ماجه (٢٣٤١)، سنن ابی داؤد (٣٦٣٥)، قال الالباني صحيح لغيره۔"}],[269,"سیدنا عبداللہ ابن عباس بنایا نہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے خط کے متعلق پوچھا گیا تو آپ نے فرمایا: ”یہ نقل شدہ علم یا پہلے لوگوں کا باقی ماندہ علم ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ علم کو لکھنا جائز ہے بلکہ یہ زیادہ بہتر ہے۔ جیسا کہ خلیفہ عمر بن عبد العزیز ہماللہ نے ابوبکر بن حزم کو خط لکھا کہ تمہارے پاس رسول اکرم نے یتیم کی جتنی بھی حدیثیں ہوں، ان پر نظر (غور وفکر ) کرو اور انہیں لکھ لو کیونکہ مجھے علم دین اور علماء دین کے مٹنے کا اندیشہ ہے۔ اور نبی معظم ملنے کی یکم کے علاوہ کسی کی حدیث قبول نہ کرو۔ اور لوگوں کو چاہیے کہ علم پھیلائیں اور (ایک جگہ جمع ہوکر ) بیٹھیں، تا کہ جاہل بھی (علم کے بارے میں ) جان لے اور علم چھپانے ہی سے ضائع ہوتا ہے۔ (صحیح بخاری کتاب العلم، رقم: (٣٤)","",{"k":"المعجم الكبير للطبراني (٢٩٩/١٠، ١٠٧٢٥)۔"}],[270,"سيدنا محمد بن عبد اللہ بن جحش سے روایت ہے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے اگر کوئی آدمی اللہ کی راہ میں شہید ہو جائے، پھر زندہ کیا جائے، پھر شہید ہو جائے تو پھر بھی وہ جنت میں اس وقت تک داخل نہیں ہو گا جب تک اس کے ذمہ قرض نہ ادا کیا جائے حالانکہ قیامت کے روز وہاں سونا ہو گا نہ چاندی۔ وہاں تو صرف نیکیاں یا برائیاں ہوں گی۔“ فائد مذکورہ حدیث سے معلوم ہوا کہ قرض ادا کرنا ضروری واجب ہے باوجود اس کے کہ شہید کا بہت زیادہ مقام و مرتبہ ہے لیکن قرض اس کو بھی معاف نہیں اگر قرض ادا نہ ہو تو آدمی جنت میں نہیں جا سکے گا۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی مکرم سے تم نے فرمایا: ”مومن کی جان اس کے قرض کی وجہ سے لٹکی رہتی ہے جب تک اسے ادا نہ کر دیا جائے۔ (سنن ترمذی: کتاب الجنائز، رقم: ١٠٧٨، اسنادہ صحیح) معلق: کا مطلب ہے کہ اس کی نجات یا عذاب کا فیصلہ قرض کی ادائیگی تک موقوف رہتا ہے۔","",{"k":"سنن نسائی (٤٦٨٤)، المعجم الكبير للطبراني (١٤/١٤١)، قال الالبانى، حسن۔"}],[271,"سیدنا عبداللہ ابن مسعودرضی اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: غفلت کرنے والوں میں اللہ تعالیٰ کا ذکر کرنے والا اس طرح ہے جس طرح جنگ سے بھاگنے والوں میں صبر و استقامت اختیار کرنے والا ہے۔“","",{"k":"ضعيف الجامع الصغير (٣٠٣٦)، السلسلة الضعيفة (٦٧٢)، المعجم الكبير للطبراني (١٦/١٠، ٩٧٩٧)۔"}],[272,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو بھی امیر ہو چاہے وہ دس یا اس سے زیادہ آدمیوں پر ہی کیوں نہ ہو وہ قیامت کے روز زنجیروں میں جکڑا ہوا آئے گا تو اللہ تعالیٰ جو چاہے اسے معاف کر دے یا جو چاہے اسے سزا دے دے۔“","",{"k":"کی سنن دارمی (٢٥١٥)، المعجم الكبير للطبراني (١٩/١١٦)، اسناده صحیح۔","f":"ایک حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((کلکم راع و کلکم مسئول عن رعيته فالامير الذي على راع وهو مسئول عن رعيته)) ( ادب المفرد: ٢٠٦) ایک اور حدیث میں نبی معظم مالے سلیم نے فرمایا: \" تم یقیناً حکومت اور امارت کی حرص کرو گے (لیکن یاد رکھو، یہ قیامت والے دن ندامت کا باعث ہوگی۔“ (صحیح بخاری، کتاب الاحکام، رقم: ٧١٤٨) ان روایات سے معلوم ہوا کہ آدمی کا حکومت یا کسی ذمہ داری سے بچنا بہتر ہے اگر کسی کو سونپ دی گئی تو اس کو چاہیے کہ وہ عدل و انصاف کرے کسی پر ظلم و زیادتی نہ کرے۔ اگر اس نے لوگوں پر ظلم و زیادتی کی تو وہ اللہ کے ہاں مجرم ہو گا اور اسے قیامت کے دن شرمندگی کا سامنا کرنا پڑے گا۔"}],[273,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: جس شخص نے بلا عذر تین جمعے چھوڑ دیئے، اللہ تعالیٰ اس کے دل پر مہر لگا دیتا ہے۔“","",{"k":"١٠٥٢: سنن ابو داؤد، رقم : ٢ سنن ترمذی، رقم : (٥٠٠)، سنن نسائی (١٣٦٩)، قال الالبانی حسن صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ تین جمعے چھوڑ دینا بہت بڑی بدنصیبی اور سزا ہے۔ ایک حدیث میں ہے کہ ”لوگ نماز جمعہ چھوڑنے سے ضرور باز آجائیں ورنہ اللہ تعالیٰ ان کے دلوں پر مہر لگا دے گا اور پھر وہ غافلوں میں سے ہو جائیں گے۔“ (صحیح مسلم، كتاب الجمعة، رقم: ٨٦٥) ان احادیث سے یہ بھی معلوم ہوا کہ نماز جمعہ کی ادائیگی واجب ہے۔ اس حدیث کے علاوہ یہ مسئلہ قرآن سے بھی ثابت ہے ارشاد باری تعالیٰ ہے ایمان والو! جمعہ کے دن نماز کی اذان دی جائے تو تم اللہ تعالیٰ کے ذکر کی طرف دوڑ پڑو اور خرید وفروخت چھوڑ دو۔“ (الجمعه: ٩) جمہور علماء نے جمعہ کو فرض عین جبکہ دیگر اکثر فقہا نے اسے فرض کفایہ کہا ہے۔ (معالم السنن: ٢٤٤/١) راجح قول فرض عین کا ہی ہے۔ ٢٧٤"}],[274,"سيدنا عبداللہ ابن عباس ریلی یہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگوں والے، آنکھوں والے نرمینڈھے کی قربانی دی۔“","",{"k":"سنن ابو داؤد (٢٧٩٦)، سنن ابن ماجه (٣١٢٨)، السنن الكبرى للبيهقى (٢٧٣/٩، قال الالبانی، صحیح۔","f":"مذکورہ حدیث سے قربانی کی مشروعیت ثابت ہوتی ہے اور اس پر مسلمانوں کا اجماع ہے۔ (المغنی: ٣٦٠/١٣) کیونکہ اللہ تعالیٰ نے قرآن میں فرمایا: فَصَلِّ لِرَبِّكَ وَانْحَرُ﴾ (الكوثر: ٢) اپنے رب کے لیے نماز پڑھ اور قربانی کر۔“ یہ بھی معلوم ہوا کہ بے عیب جانور ذبح کرنے چاہیں۔ نبی معظم ملنے کے نام سے خصی اور غیر خصی دونوں جانوروں کی قربانی ثابت ہے۔ ٢٧٥"}],[275,"سیدنا عبداللہ ابن عباس ریلی لینا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن خیانت نہیں کرتا۔“ مذکورہ حدیث سے معلوم ہوا کہ مومن خائن نہیں ہوسکتا کیونکہ خیانت کرنا، منافق کی نشانیوں میں سے ایک نشانی ہے۔ جیسا کہ نبی معظم سے تم نے فرمایا: ” منافق کی تین نشانیاں ہیں: جب وہ بات کرے، جھوٹ بولے، جب وعدہ کرے، اس کے خلاف کرے، جب اس کے پاس امانت رکھی جائے تو خیانت کرے۔“ (صحیح بخاری، کتاب الایمان، رقم: ٣٣، صحیح مسلم، رقم: ٥٩):٢٧٦ اسی طرح ارشاد باری تعالی ہے: إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْآمَنتِ إِلَى أَهْلِهَا (النساء: ٥٨) بلا شبہ اللہ تعالیٰ تمہیں حکم دیتا ہے کہ امانتیں، امانت والوں کو ادا کرو۔“","",{"k":"المعجم الكبير للطبراني (٤٢٨/٩)، صحيح الجامع الصغير (٧٧٣٨)۔"}],[276,"سیدہ عائشہ بین النہا سے روایت ہے رسول اللہ علیم نے فرمایا: ”مسواک منہ کی صفائی اور رب کی رضا مندی کا سبب ہے۔ یہ حدیثیں سعید بن ابی ایوب سے صرف روح بن صلاح ہی روایت کرتے ہیں۔ مذکورہ روایت میں مسواک کی فضیلت کا اثبات ہے۔ مطهرة طہارت کا سبب اور ذریعہ۔ مِطْهَرَةٌ (میم کے نیچے زیر) کے معنی ہیں۔ آلہ تطہیر۔ گویا ایک طرف منہ کی صفائی اور پاکیزگی کا ذریعہ ہے تو دوسری طرف رضائے رب کا ذریعہ اور وسیلہ ہے۔ ایک حدیث میں ہے سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب نیند سے بیدار ہوتے تو اپنا منہ مسواک سے خوب صاف کرتے۔ (صحیح بخاری، کتاب الوضوء، رقم: ٢٤٥، صحيح مسلم، رقم ٢٥٥)","",{"k":"صحیح بخاری (٢٠٧)۔"}],[277,"سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم پر ( امیر کا حکم ) سننا اور ماننا واجب ہے خواہ وہ تمہیں پسند ہو خواہ ناپسند، اپنی خوشی میں بھی اور اپنی نا خوشی میں بھی اور تم پر دوسروں کو ترجیح دیے جانے کی صورت میں بھی اور حکمرانوں سے حکومت کے بارے میں نہ جھگڑو۔“ یہ حدیث سہیل بن حسان کلبی سے ابو شریح ہی روایت کرتے ہیں۔","",{"k":"صحيح مسلم، رقم : ١٨٣٦ مجمع الزوائد (٩/١٣٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حکمرانوں کی اطاعت کرنا ضروری ہے اگر چہ تمھیں کوئی ذاتی نقصان ہو یا تمھیں اہمیت نہ دی گئی ہو بلکہ تم سوسائٹی کے مفادات کے پیش نظر ہر صورت میں حکمرانوں کی اطاعت کرو۔ سوائے نافرمانی کے کاموں کے۔ جیسا کہ ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَاَطِيْعُوا الرَّسُولَ وَ أُولِي الْأَمْرِ مِنْكُمْ﴾ (النساء: ٥٩) ”اے ایمان والو! اطاعت کرو اللہ کی اور اطاعت کرو رسول کی اور ان کی جو تمہارے حکمران ہیں۔“"}],[278,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب جہنمیوں کو جہنم کی طرف چلا کر لے جایا جائے گا تو وہ انہیں آگے سے ملے گی اور ایک ہی دفعہ انہیں جلا دے گی۔ کسی ہڈی پر گوشت نہیں چھوڑے گی مگر اس کو وہ ایڑی کے پچھلی جانب ڈال دے گی۔“ یہ حدیث عبداللہ بن ابی الہذیل سے صرف ابوسنان ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن سلیمان الاصبہانی اکیلے ہیں۔","",{"k":"ضعيف الترغيب والترهيب، رقم : ١ (٢١٧١)، السلسلة الضعيفة (٣٠٢)، المعجم الكبير للطبراني ١١٦/٩١۔"}],[279,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک صاع (تقریباً اڑھائی کلو ) کھجور یا ایک صاع جو فطرانہ ادا کیا کرتے تھے۔“ یہ حدیث حضرت لیث بن سعد سے صرف ان کا بیٹا ہی روایت کرتا ہے۔ مذکورہ حدیث سے معلوم ہوا کہ صدقہ فطر کی مقدار ایک صاع ہے خواہ جنس کوئی بھی ہو۔ جمہور علماء اسی کے قائل ہیں۔ جبکہ احناف کا کہنا ہے کہ گندم اور منقی سے نصف صاع بھی کفایت کر جاتا ہے۔ (انہوں نے چند ضعیف روایات سے استدلال کیا ہے جو قابل حجت نہیں۔) (كتاب الام: ٩٠/٢ - كتاب المغنى: ٢٨٧/٤ - الهداية: ١١٧/١) جمہور کا موقف ہی رائج ہے، امام شوکانی رحمہ اللہ، امام ابن قدامہ اللہ اور سعودی مستقل فتوی کمیٹی نے بھی اسی کے مطابق فتوی دیا ہے۔ (نیل الاوطار: ١٤٧/٣ - المغنى: ٢٨٥/٤ - فتاوى اللجنه: ٣٦٩/٩)","",{"k":"صحیح بخاری (٥٠١٧)، سنن ابی داؤد (١١)۔"}],[280,"سیدنا ابو قتادہ نبی اللہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”شہید قتل کی صرف اتنی تکلیف محسوس کرتا ہے جتنی تم میں سے کوئی شخص چیونٹی کے کاٹنے سے تکلیف محسوس کرتا ہے۔“ یہ حدیث ابو قتادہ سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں عیسی بن حمادا کیلے ہیں۔","",{"k":"سنن ترمذی (٦٦٨)، سنن نسائی، رقم : ٣١٦١. صحيح الجامع الصغير (٣٧٤٥)، السنن الكبرى للبيهقي : ١٦٤/٩ . (۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ نے شہادت کی موت کو بہت زیادہ آسان بنا دیا ہے تا کہ لوگ شہادت سے نہ گھبرائیں۔ یہی وجہ ہے کہ شہید بار بار عرض کرے گا اللہ مجھے زمین پر بھیج تا کہ میں دوبارہ لڑائی کرتے ہوئے شہید ہو جاؤں۔ سیدنا انس بنی اللہ سے روایت ہے نبی معظم ملنے صلی اللہ علیہ وسلم نے فرمایا: ” شہید کے سوا جنت میں جانے والا کوئی شخص ایسا نہیں جو دنیا میں لوٹنے کو پسند کرے گا اور (یہ کہ ) اس کے لیے زمین میں کوئی چیز ہو۔ وہ آرزو کرے گا کہ وہ ٠١١٠٩ ١٠١ دوبارہ دنیا میں جائے اور دس مرتبہ شہید کیا جائے۔ (صحیح بخاری، کتاب الجهاد، رقم: ٢٨١٧)"}],[281,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے دس دفعہ قُلْ هُوَ اللهُ اَحَدٌ پڑھی تو اس کے لیے جنت میں ایک محل بنا دیا جاتا ہے۔ اور جو شخص اس کو میں دفعہ پڑھے تو اس کے لیے دو محل بنا دیے جاتے ہیں۔ اور جس نے تمہیں دفعہ اس کو پڑھا تو اس کے لیے تین محل بنا دیئے جاتے ہیں۔“ یہ حدیث زھرہ بن معبد سے متصل الاسناد مروی ہے اور ان سے خالد بن حمید ہی روایت کرتے ہیں، اسے روایت کرنے میں بھانی بن المتوکل اکیلے ہیں،٤٢٩ مذکورہ روایت کمزور ہے تاہم سورہ اخلاص کی فضیلت بہت زیادہ ہے۔ جو دیگر صحیح احادیث سے ثابت ہیں","",{"k":"سنن دارمی، رقم:، المعجم الكبير للطبرانی (١٩/١١٧)۔"}],[282,"سيدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کسی عورت کے لیے جائز نہیں کہ اس کا خاوند گھر میں موجود ہو اور وہ اس کی اجازت کے بغیر (نفلی) روزہ رکھے، اور نہ یہ درست ہے کہ وہ اس کے گھر میں کسی ایسے شخص کو آنے کی اجازت دے جسے وہ پسند نہ کرتا ہو۔ اور اگر وہ عورت اپنی کمائی ہوئی چیز سے صدقہ کرے تو اس (کے خاوند ) کے لیے بھی اس کے صدقے کا آدھا ثواب ہوگا۔“ نانه (١) مذکورہ حدیث سے معلوم ہوا کہ نفلی عبادت کے مقابلے میں شوہر کے حقوق کی ادائیگی زیادہ اہم وضروری ہے۔ (٢) یہ بھی معلوم ہوا کہ بیوی کو شوہر کی تسکین کے لیے انتہائی حساس اور ذمہ دار ہونا چاہیے۔ کسی غیر مرد کا خاوند کی اجازت کے بغیر اس کے گھر میں داخل ہونا بھی منع ہے۔ (٣) اگر عورت اپنے خاوند کے مال سے خرچ کرتی ہے تو آدھا ثواب ملے گا۔ یہ اس مال کی بات ہے جو عورت کو خاوندخوراک کے لیے دیتا ہے اگر اس سے صدقہ کرتی ہے تو ثواب دونوں کو برابر برابر ملے گا۔","",{"k":"صحیح بخاری (٥١٩٥)، سنن ابو داؤد (٢٤٥٨)، المعجم الكبير للطبرانی (١٩/١١٧)۔"}],[283,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: عورت ٹیڑھی پسلی سے پیدا کی گئی ہے، اور ٹیڑھی ہوتے ہوئے ہی تم اس سے میل جول رکھ سکتے ہو، اگر تم اسے سیدھا کرنے چلے تو اسے توڑ دو گے، اور اس کو توڑ دینا اس کو طلاق دینا ہے۔“ یہ دونوں حدیثیں مسلم بن ولید بن رباح سے صرف یزید بن عبد اللہ بن ھاد ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ عورتوں کے ساتھ حسن سلوک کرنا چاہیے کیونکہ عورت فطری طور پر مرد سے کمزور بھی ہے اور کج فطرت اور کم عقل بھی۔ بنا بریں زیادہ عقل اور زیادہ صبر وقوت رکھنے والے مرد کو قتل اور عفو و درگذر سے کام لیتے ہوئے اس کے ساتھ حسن سلوک کا ہی اہتمام کرنا چاہیے۔ جو لوگ عورت کے ساتھ بے رحمانہ اور متشددانہ رویہ اختیار کرتے اور سوچتے ہیں کہ اس طرح وہ اسے سیدھا کر لیں گے، وہ خام خیالی میں مبتلا ہوتے ہیں، اور ان کا گھر جہنم کدہ بنا رہتا ہے، یا پھر طلاق کی وجہ سے اجڑ جاتا ہے، اور اگر بچے بھی ہوں تو ان کی زندگیاں الگ برباد ہو جاتی ہیں۔","",{"k":"صحيح مسلم (١٤٦٦/٦٠)، صحيح الجامع (٩٦٠)۔"}],[284,"سیدنا ابو ایوب انصاری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم دین کی ذمے داری اس کے اہل افراد کے سپر د کرو تو پھر تم دین پر نہ روؤ لیکن اس پر تب روؤ جب تم نا اہل لوگوں کو اس کی ذمے داری سونپ دو۔ یہ حدیث ابوایوب سے صرف اس سند سے ہی مروی ہے،اسے روایت کرنے میں حاتم اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (٢١٦/٤٠)، ضعيف الجامع الصغير، رقم: ٢١٨٨ السلسلة الضعيفة (٣٧٣)، مسند احمد (٢٢/٥)۔"}],[285,"سیدنا عبد اللہ بن حارث بن جزء ز بیدی کہتے ہیں رسول اللہ علیم نے فرمایا: ” کچھ لوگ مشرق کی جانب سے نکلیں گے تو وہ مہدی کی حکومت کے لیے راستہ ہموار کریں گے۔“ یہ حدیث عبداللہ بن حارث سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"الجامع، رقم : ٦٤٢١ . سنن ابن ماجه، ضعيف۔"}],[286,"سیدنا عبداللہ ابن عباس بنایا جا سے روایت ہے وہ اسے مرفوع بیان کرتے ہیں، فرمایا: ”جو شخص دس آدمیوں پر بھی حاکم بنا تو وہ قیامت کے روز اس طرح آئے گا کہ اس کا ہاتھ گردن سے بندھا ہوا ہو گا یہاں تک کہ ان لوگوں اور اس کے مابین فیصلہ کر دیا جائے۔ اعمش سے صرف محاربی ہی روایت کرتے ہیں، اسے روایت کرنے میں جعفی اکیلے ہیں۔","",{"k":"سنن دارمی (٢٥١٥)، المعجم الكبير للطبرانی (٢٨٢/١٠)، مسند ٠٩/٠٩/٠١ احمد (٤٣١/٢)، قال الشیخ شعیب الارناؤط، اسناده قوی۔"}],[287,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے میری وفات کے بعد میری قبر کی زیارت کی تو وہ اس شخص کی طرح ہے جس نے میری زندگی میں میری زیارت کی۔“ مذکورہ روایت سخت ضعیف ہے۔","",{"k":"السلسة الضعيفه (١/١٢٤، ٤٧)، ضعيف الجامع الصغير (٥٥٥٣)، السنن الكبرى للبيهقي (٢٤٦/٥)، قال الالبانيموضوع۔"}],[288,"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں انہوں نے کہا کہ ”جنت کی حورعین زعفران خوشبو سے پیدا کی گئی ہیں۔ یہ دونوں حدیثیں لیث سے صرف اسی سند سے ہی مروی ہیں، ان کو روایت کرنے میں علی بن حسن بن ہارون الانصاری اکیلے ہیں۔","",{"k":"مجمع الزوائد (٤١٩/١٠)، سنده ضعیف۔","f":". تاہم جنت کی حوریں یا قوت اور مرجان کی طرح رنگت میں سرخ ہوں گی۔ جیسا کہ ارشاد باری تعالی ہے: ﴿ كَأَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُ (الرحمن: ٥٨)"}],[289,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بے شک اللہ تعالیٰ نے حق کو سیدنا عمر رضی اللہ عنہ کی زبان اور دل پر جاری کر دیا ہے۔ یہ حدیث ضحاک بن عثمان سے ابن ابی حازم ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی (٣٦٨٢)، قال الالباني صحیح۔"}],[290,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے چھ چیزیں یاد کر لی ہیں (١) نکاح سے پہلے طلاق نہیں ہوتی۔ (٢) ملکیت سے پہلے آزادی نہیں ہوتی (٣) نافرمانی کی کوئی بھی نذر پوری نہ کی جائے (٤) بلوغت کے بعد یتیمی ختم ہو جاتی ہے (٥) کسی دن، رات تک چپ رہنا جائز نہیں (٦) روزے میں وصال جائز نہیں احمد بن صالح فرماتے ہیں کہ عبداللہ بن ابی احمد بن جحش مدینہ منورہ کے کبار تابعین میں شمار ہوتے ہیں، ان کی ملاقات حضرت عمر بن خطاب فضل اللہ سے ہوئی ہے، یہ حضرت سعید بن میٹب سے عمر میں بڑے ہیں۔ یہ حدیث عبداللہ بن ابی احمد سے صرف اسی سند سے روایت ہے۔ اسے روایت کرنے میں احمد بن صالح اکیلے ہیں۔","",{"k":"عَبْدُ اللَّهِ بْنُ أَبِى أَحْمَدَ بْنِ جَحْشٍ مِنْ كِبَارِ تابِعِيِّ الْمَدِينَةِ، قَدْ لَقِيَ عُمَرَ بْنَ الْخَطَّابِ، وَهُوَ أَكْبَرُ مِنْ سَعِيدِ بْنِ الْمُسَيِّبِ .. لا يُرْوَى هَذَا الْحَدِيثَ عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَحْمَدَ إِلَّا بِهَذَا الْإِسْنَادِ، تَفَرَّدَ بِهِ أَحْمَدُ بْنُ صَالِحٍ . ارواء الغليل (٨٠/٥)، سنن ابو داؤد (٢٨٧٣)، السنن الكبرى للبيهقي (٧/٣٢٠)، رجاله ثقات۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ نکاح سے پہلے طلاق نہیں، کیونکہ نکاح سے پہلے طلاق کی کوئی حیثیت نہیں ابھی یہ طلاق کا مالک ہی نہیں۔ مثلاً کوئی کہے کہ جب میری شادی ہو تو میری بیوی کو طلاق یا کہے کہ اگر میری فلاں عورت سے شادی ہو تو اسے طلاق وغیرہ وغیرہ،اگر بعد میں اس کی شادی ہو جائے تو اس کی بیوی کو طلاق واقع نہیں ہوگی۔ بلکہ اس کی بات لغوشمار ہو گی۔ امام شافعی اور امام احمد بینم اور امام شوکانی جم اللہ کا بھی یہی موقف ہے۔ (نيل الأوطار: ٣٣٥/٤، سعودی فتوی کمیٹی کا بھی یہی فتویٰ ہے، فتاوی اللجنة: ١١/٢٠)\n(٢) اسی طرح کوئی آدمی مالک بنے بغیر تو آزاد نہیں کر سکتا، ہاں اگر اس کی ملکیت میں ہے تو آزاد کرے گا تو وہ آزاد شمار ہوگا۔\n(٣) یہ بھی معلوم ہوا کہ اللہ کی نافرمانی کی نذر کو پورا نہ کرنا چاہیے بلکہ اس کا کفارہ ادا کر دینا چاہیے نذر کا کفارہ قسم کا کفارہ ہے جیسا کہ نبی معظم سے ہم نے فرمایا: ((کفارۃ النذر کفارہ الیمین)) قسم کا کفارہ کیا ہے؟ ارشادِ باری تعالیٰ ہے: (صحیح مسلم، کتاب النذر، رقم: ١٦٤٥) فَكَفَّارَتُةٌ إِطْعَامُ عَشَرَةِ مَسْكِيْنَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيْكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَّمْ يَجِدْ فَصِيَامُ ثَلَثَةِ أَيَّامٍ﴾ (المائده: ٨٩) ’اس (یعنی قسم ) کا کفارہ دس محتاجوں کو کھانا دینا ہے اوسط درجے کا جو اپنے گھر والوں کو کھلاتے ہو یا ان کو کپڑا دینا یا ایک غلام لونڈی آزاد کرنا ہے اور جس کو مقدور نہ ہو تو تین دن کے (مسلسل) روزے ہیں۔\n(٤) بلوغت کے بعد یتیمی ختم، کیونکہ یتیم بچہ بالغ ہونے کے بعد اپنے امور کا خود ذمہ دار ہو جاتا ہے اور اس سے یتیمی کے احکام اٹھ جاتے ہیں اگر وہ فی الواقع دانا اور سمجھدار ہو تو خرید وفروخت اور نکاح وغیرہ کے معاملات میں اس کا اپنا فیصلہ رائج ہو گا۔ لیکن اگر وہ ان معاملات میں دانا نہیں تو ولی ہی اس کا نگران رہے گا جیسے کہ ارشاد باری تعالیٰ ہے: وَابْتَلُوا الْيَتْلَى حَتَّى إِذَا بَلَغُوا النِّكَاحَ فَإِنْ أَنَسْتُمْ مِّنْهُمْ رُشْدًا فَادْفَعُوا إِلَيْهِمْ آمُوَالَهُمْ (النساء: ٦) ”اور یتیموں کو آزماتے رہو، پھر اگر تم ان میں بھلائی اور حسن تدبیر پاؤ تو ان کے مال ان کے حوالے کر دو۔“\n(٥) چپ کا روزہ قبل از اسلام لوگوں کا معمول تھا۔ اسلام میں اس سے منع کر دیا گیا ہے اور اللہ کا ذکر کرنے اور خیر کے ساتھ بولنے کا حکم دیا گیا ہے۔ (١) وصال سے مراد یہ ہے کہ آدمی ارادی طور پر ہر دو یا اس سے زیادہ دن تک روزہ افطار نہ کرے، اور مسلسل روزہ رکھے وہ رات کو کچھ کھائے نہ سحری کے وقت، معلوم ہوا کہ وصال کرنا جائز نہیں بلکہ یہ صرف نبی معظم ملنے دی ایم کی خصوصیت تھی"}],[291,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ سے تم نے فرمایا: ”آخر زمانہ میں ایسا فتنہ ہوگا جس میں لوگ الگ الگ کیے جائیں گے جس طرح سونا اور چاندی اپنی اپنی کانوں سے الگ کیا جاتا ہے۔ “ یہ حدیث حضرت علی سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابن لھیعہ خاندان مذکورہ حدیث سے معلوم ہوا کہ فتنے میں سرگرم ہونا ممنوع ہے اور اس سے بچنا ضروری ہے۔ سب سے بڑا فتنہ یہ ہو گا کہ عام لوگ بے دین ہو کر اپنی من مرضی کے تابع ہوتے ہوئے وقتی","",{"k":"مجمع الزوائد (٧/٣٠٨)، مستدرك حاكم (٤/٩٧)، سندہ صحیح۔","f":"حاصل کرنے کے درپے ہوں گے اور دوسروں کو بھی اس پر مجبور کریں گے اور لوگ ان کے اس فتنہ میں مشغول ہو جائیں گے، جس طرح موجودہ حالات میں لوگ فتنوں کا شکار ہیں۔"}],[292,"سیدہ عائشہ بنی انہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے بائیں ہاتھ سے کھایا تو اس کے ساتھ شیطان بھی کھاتا ہے، اور جس شخص نے بائیں ہاتھ سے کچھ پیا تو اس کے ساتھ شیطان بھی پیتا ہے۔“ یہ حدیث اسماعیل بن ابی حکیم سے موسیٰ بن سرجس اور موسیٰ سے یزید بن ھاد ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ دائیں ہاتھ سے کھانا پینا چاہیے، کیونکہ بائیں ہاتھ سے کھانے پینے والے کے ساتھ شیطان شریک ہو جاتا ہے۔ ایک حدیث میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں سے کوئی کھائے تو اپنے دائیں ہاتھ کے ساتھ کھائے اور جب پیسے تو اپنے دائیں ہاتھ سے پیے کیونکہ شیطان اپنے بائیں ہاتھ کے ساتھ کھاتا ہے اور بائیں ہاتھ کے ساتھ پیتا ہے۔ (صحیح مسلم، کتاب الاشربة","",{"k":"مجمع الزوائد: ٥/ ٢٥ . ١٩: صحیح مسلم (٢٠١٩)۔"}],[293,"سیدنا سہل بن سعد رضی اللہ عنہ سے روایت ہے، انہوں نے رسول اللہ صلع کھڑے ہوکر پیشاب کرتے ہوئے دیکھا۔ مذکورہ حدیث سے معلوم ہوا کہ اضطراری کیفیت میں کھڑے ہو کر پیشاب کرنا جائز ہے۔ بشرطیکہ اس کے چھینٹوں سے بچاؤ ممکن ہو۔ سیدنا عبد اللہ بن دینار رضی اللہ عنہ بیان کرتے ہیں کہ میں نے سیدنا عبد اللہ بن عمر رضا الیہ کو کھڑے ہو کر پیشاب کرتے ہوئے دیکھا۔ (موطا: ٥٠/١) ابن منذر اللہ فرماتے ہیں: بیٹھ کر پیشاب کرنا مجھے پسند ہے لیکن کھڑے ہو کر بھی جائز ہے، اور یہ سب رسول اللہ صلی اللہ علیہ وسلم سے ثابت ہے۔ (شرح مسلم للنووی: ١٣٣/١) شیخ البانی اللہ فرماتے ہیں: یہی بات راجح ہے۔ (ارواء الغلیل: ٩٥/١) ایک روایت میں ہے سیدہ عائشہ منی نیہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس وقت سے کھڑے ہوکر پیشاب نہیں کیا جب سے آپ صلی اللہ علیہ وسلم پر قرآن نازل کیا گیا۔ (سلسلة صحيحه، رقم: ٢٠١، سنن ترمذی، رقم: ١٢) فی الحقیقت یہ حدیث ہمارے موقف کے مخالف نہیں ہے۔ کیونکہ سیدہ عائشہ بنی النھا کو جس قدر علم تھا انہوں نے اتنا ہی بیان کر دیا لہذا انہیں گھر کے معاملات کا تو علم تھا لیکن گھر کے باہر کے معاملات کی انہیں اطلاع نہیں ہوئی ( اور کھڑے ہو کر پیشاب کرنے کا واقعہ گھر سے باہر پیش آیا )۔ (نیل الاوطار: ١٥١/١، تحفة الاحوذى: ٧٦/١) بہر حال کھڑے ہو کر پیشاب کرنا درست ہے تب جب پیشاب کے قطروں اور چھینٹوں سے مکمل طور پر اجتنا ب کیا جائے کیونکہ پیشاب کے قطروں سے پر ہیز نہ کرنے کی وجہ سے ایک شخص کو قبر میں عذاب دیا جا رہا تھا۔ (صحیح مسلم، کتاب الطهارة، رقم: ٢٩٢) ٢٩٤","",{"k":"صحیح بخاری (٢٢٢)، سنن ابو داؤد (٢٣)، مجمع (٢٢٢)، الزوائد (١/٢٠٦)۔"}],[294,"اسی سند سے نبی صلی اللہ علیہ وسلم سے مروی ہے، آپ نے فرمایا: ”لوگ قیامت کے روز پیدل چل کر، ننگے پاؤں، بے ختنہ اکٹھے کیے جائیں گے۔ کسی نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! عورتیں مردوں کی طرف دیکھیں گی؟ آپ نے فرمایا: ”ہر آدمی کا اپنا ایسا حال ہو گا جو اسے دوسروں کی حالت دیکھنے سے بے نیاز کر دے گا۔“ یہ دونوں حدیثیں مصعب بن ثابت سے صرف ابراہیم بن حماد سے روایت کرتے ہیں اور ابوحازم سے صرف مصعب بن ثابت ہی روایت کرتے ہیں۔","",{"k":"إِلَّا إِبْرَاهِيمُ بْنُ حَمَّادٍ، وَلَا رَوَاهُمَا عَنْ أَبِي حَازِمٍ إِلَّا مُصْعَبُ بْنُ ثَابِتٍ . تقدم تخريجه، انظر (٥١)۔"}],[295,"سیدہ عائشہ علی النیہا نے بیان کیا، ”رسول اللہ تم اتنی نماز پڑھا کرتے تھے حتی کہ آپ کے پاؤں پھٹ جاتے، پھر بعد میں آپ بھاری ہو گئے تو بیٹھ کر نماز پڑھتے۔ جب ارادہ کرتے کہ سورت ختم کریں تو کھڑے ہو کر اس کو پوری کرتے پھر رکوع کرتے۔“ یہ حدیث عبداللہ بن یزید بن سرمز سے رشدین ہی روایت کرتے ہیں، اسے روایت کرنے میں زہیر بن عبادا کیلے ہیں۔ مذکورہ حدیث میں نبی معظم صلی اللہ علیہ وسلم کے اسوہ حسنہ کو بیان کیا گیا ہے۔ یہ بھی معلوم ہوا کہ رات کی نفل نماز پورے اطمینان، سکون اور خشوع وخضوع کے ساتھ ادا کی جائے۔ یہ بھی معلوم ہوا کہ اگر بیماری کی وجہ سے یا جسم کے بھاری یا کسی اور وجہ سے کھڑا ہونا ممکن نہ ہو تو بیٹھ کر نماز پڑھے اور جب تلاوت ختم کرنے کے قریب ہو تو وہ کھڑا ہو جائے اور پھر رکوع کرے۔ ٢٩٦","",{"k":"صحیح بخاری کتاب التفسیر، سنن نسائی (١٦٤٥)۔"}],[296,"سیدنا معقل بن یسار رضی اللہ عنہ علیہ وسلم سے روایت ہے کہ رسول اللہ علیم نے فرمایا: ” فتنے میں عمل کرنا میری طرف ہجرت کرنے کی طرح ہے۔“ یہ حدیث محمد بن جمادہ سے صرف بیٹی بن عقبہ ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ فتنوں کے زمانے میں اللہ ذوالجلال کی عبادت کرنا ہجرت کی طرح ہے۔ مطلب یہ ہے کہ جس طرح اللہ اور اللہ کے رسول کی خاطر ہجرت کرنے کا بہت بڑا اجر ہے بلکہ ہجرت سے سابقہ گناہ معاف ہو جاتے ہیں اسی طرح اس کی فضیلت ہے۔ (٢) یہ کہ جس طرح ہجرت کرنا، یعنی اپنا وطن، رشتہ داروں، تعلق والوں کو چھوڑ نا بڑا مشکل ہے اور بڑی ہمت والا کام ہے اسی طرح جب فتنے ہی فتنے ہوں تب اللہ کی عبادت کرنا دین اسلام پر قائم ہونا بڑی خوش قسمتی کی علامت ہے۔ ٢٩٧","",{"k":"صحیح مسلم (٢٩٤٨)، سنن ترمذی (٢٢٠١)۔"}],[297,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس امت کی بھی کبھی شکلیں بدلی گئیں تو اس کی نسل باقی نہیں رہی۔“ یہ حدیث زہری سے صرف زبیدی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جب کسی قوم کی شکل بدلی جاتی ہے تو اس کی نسل باقی نہیں رہتی۔ جو لوگ کہتے ہیں کہ یہ بندر تبدیل شدہ شکلیں ہیں ان لوگوں کا مذکورہ حدیث سے رد ہو رہا ہے۔","",{"k":"السلسلة الصحيحة (٥/٢٦٣، ٢٢٦٤)۔"}],[298,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ سے ایک آدمی کے پاس سے گزرے جو اپنے دو بیٹوں کے درمیان ان کے سہارے سے چل رہا تھا۔ آپ نے اس کے متعلق پوچھا: لوگوں نے کہا: اس نے نذر مانی ہے کہ پیدل چل کر حج کرے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس شخص کے اپنی جان کو عذاب میں مبتلا کرنے کی اللہ تعالیٰ کو کوئی ضرورت نہیں اور آپ نے اس کو حکم دیا کہ وہ سواری پر سوار ہو کر حج کرے۔“ یہ حدیث لیث بن سعد سے اُن کے بیٹے ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ اگر نذر مانے والا اس کو پورا کرنے کی طاقت نہ رکھتا ہو تو اس کو توڑ کر اس کا کفارہ ادا کرے جیسا کہ سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ سیدنا عقبہ بن عامر بنا الیہ کی بہن نے نذر مانی کہ وہ پیدل چل کر بیت اللہ جائے گی تو نبی صلی اللہ علیہ وسلم نے اسے حکم فرمایا کہ سوار ہو اور قربانی کر۔ (سنن ابی داؤد، کتاب الايمان والنذور، رقم: ٣٢٩٦، اسناده حسن)","",{"k":"صحیح مسلم (١٦٤٠)۔"}],[299,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا ابو ذر رضی اللہ عنہ نے کہا: اللہ کے رسول! دولت مند لوگ اجر حاصل کر گئے وہ ہماری طرح نماز ادا کرتے ہیں، اور ہماری طرح روزہ بھی رکھتے ہیں، اور ان کے پاس زائد مال ہے جو ہمارے پاس نہیں کہ ہم صدقہ کر سکیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ابوذر بیان کیا میں تمہیں ایسے کلمات نہ سکھا دوں جن کے ذریعے تم اپنے سے آگے بڑھنے والے کو پہنچ جاؤ اور جو شخص تم سے پیچھے ہو وہ تم تک نہ پہنچ پائے گا البتہ وہ شخص جس نے تمہارے جیسا عمل کیا؟ سیدنا ابوذر رضی اللہ عنہ نے کہا: یا رسول اللہ ملئے علیم ہی آپ ضرور بتائیں۔ آپ نے فرمایا: ” ہر نماز کے بعد ((سُبْحَانَ اللهِ، اَلْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ)) تینتیس تینتیس بار پڑھو اور اس وظیفے کو اس کلمے کے ساتھ ختم کرو (( لا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ)) “ یہ حدیث اوزاعی سے صرف رشدین ہی روایت کرتے ہیں۔","",{"k":"صحيح مسلم، الخ (٣٢٩٧)، سنن ابو داؤد (١٥٠٤)۔","f":"ि اس حدیث سے معلوم ہوا کہ ہر نماز کے بعد مذکورہ اذکار کرنا مسنون ہے۔ ایک حدیث میں ہے کہ غفرت خطاياه وان كانت مثل زبد البحر)) (صحیح مسلم، کتاب المساجد، رقم: ٥٩٦) اس کے تمام گناہ معاف کر دیئے جاتے ہیں خواہ وہ سمندر کی جھاگ کے برابر ہی کیوں نہ ہوں۔“ ان اذکار کی عظیم فضیلت بھی معلوم ہوئی کہ ان کے ذریعے اللہ تعالی گناہوں کو مٹا دیتا ہے۔"}],[300,"سیدنا ابن عمر رضی اللہ عنہما نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا کہ ایک نبی علم کے پاس آیا، آپ نے اس سے مصافحہ کیا، پس نبی ملت علی ایم نے اس آدمی سے اپنا ہاتھ نہیں کھینچا حتی کہ اس آدمی نے خود اپنا ہاتھ کھینچ لیا، پھر اس نے آپ نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم عثمان آئے ہیں۔ آپ اللہ علیہ نے فرمایا: ”وہ اہل جنت کا ایک آدمی ہے۔ یہ حدیث سفیان سے صرف روح بن صلاح ہی روایت کرتے ہیں۔ مذکورہ حدیث سے نبی معظم صلی اللہ علیہ وسلم کے حسن سلوک، اپنے صحابہ کے ساتھ محبت اور","",{"k":"سنن ابو داؤد (٤٧٩٤)، المعجم الكبير للطبرانی (١١/٣٥)، مجمع الزوائد (٨٧/٩)، قال الالبانی، حسن. شخص۔","f":"شفقت کا اثبات ہے۔"}],[301,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان نبی ملے لیکن جب کسی قوم کے ہاں روزہ افطار کرتے تو کہتے: ” تمہارے ہاں روزہ دار روزہ افطار کرتے رہیں، تمہارا کھانا نیک لوگ کھاتے رہیں اور تم پر فرشتے ( رحمت کے ساتھ ) نازل ہوتے رہیں۔ یہ حدیث از وکیع از سفیان صرف زہیر بن عباد ہی روایت کرتے ہیں، لوگوں نے اس طرح روایت کی ہے: وکیع از ہشام اور انہوں نے سفیان کا ذکر نہیں کیا۔ مذکورہ حدیث سے معلوم ہوا کہ میزبان کے لیے دعا کرنا مسنون ہے۔ ایک حدیث میں یہ دعا آتی ہے: ((اللهم بارك لهم فى ما رزقتهم فاغفر لهم فارحمهم)) (صحیح مسلم، کتاب الاشربة، رقم: ٢٠٤٢) ”اے اللہ! تو نے ان اہل خانہ کو جو کچھ دیا ہے اس میں برکت عطا فرما ان کی غلطیاں اور کوتاہیاں معاف فرما اور ان پر رحم فرما۔“","",{"k":"سنن ابو داؤد (٣٨٥٤)، سنن ابن ماجه (١٧٤٧)، صحيح الجامع الصغير (١١٣٧)۔"}],[302,"سیدنا عثمان بن عفان سے روایت ہے کہ انہوں نے تین تین دفعہ وضو کیا، پھر فرمایا: میں نے رسول اللہ لئے علیم کو یہ فرماتے ہوئے سنا: ”جس نے میرے اس وضو کی طرح وضو کیا تو اس کے گناہ اس کے چہرے، ہاتھوں اور پاؤں سے نکل جاتے ہیں۔ یہ حدیث ابن عجلان سے سفیان ہی روایت کرتے ہیں، اسے روایت کرنے میں حامد بن بیٹی اکیلے ہیں۔","",{"k":"صحيح مسلم (٢٢٧)، سنن ترمذی (٢)، سنن ابن ماجه (٢٨٢)۔","f":"مذکورہ حدیث سے وضو کی فضیلت ثابت ہوتی ہے کہ اس کی وجہ سے اللہ تعالیٰ صغیرہ گناہوں کو معاف کر دیتا ہے۔ ایک روایت میں ہے کہ سیدنا عثمان رضی اللہ عنہ نے وضو کیا اور فرمایا: ” میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے اس طرح وضو کی طرح وضو کرتے ہوئے دیکھا، پھر آپ نے فرمایا: ” جو اس طرح وضو کرے تو اس کے پہلے (صغیرہ) گناہ معاف کر دیئے جاتے ہیں، اور اس کی نماز اور اس کا مسجد کی طرف چل کر جانے کا ثواب ایک زائد چیز ہے۔“ (صحیح مسلم، كتاب الطهارة، رقم: ٢٢٩) معلوم ہوا کہ مسجد کی طرف چل کر جانا اور اس میں نماز پڑھنا مزید ثواب اور رفع درجات کا باعث ہے۔"}],[303,"سیدنا ابو حمزہ بن عبد اللہ بن عتبہ کہتے ہیں میں نے اپنے باپ عبد اللہ بن عتبہ سے پوچھا: تم نبی صلی اللہ علیہ وسلم کی کون سی چیز یاد رکھتے ہو؟ انہوں نے کہا: ” مجھے یہ یاد ہے کہ آپ نے مجھے پکڑا جبکہ میں پانچ یا چھ سال کا تھا تو مجھے اپنی گود میں بٹھا لیا اور اپنا مبارک ہاتھ میرے سر پر پھیرا، پھر میرے اور میرے بعد میرے والدین کے لیے برکت کی دعا فرمائی۔“ یہ حدیث عبداللہ بن عتبہ سے اسی سند سے مروی ہے، اسے روایت کرنے میں موسیٰ بن عون اکیلے ہیں۔ (١) مذکورہ حدیث سے نبی مکرم ملے تعلیم کا بچوں کے ساتھ شفقت و پیار ثابت ہوتا ہے۔ (٢) معلوم ہوا کہ بچے کے سر پر شفقت کا ہاتھ رکھنا مسنون ہے۔ (٣) یہ بھی معلوم ہوا کہ بچوں اور دوسرے لوگوں کے لیے دعائیں کرنا نبی مکرم مے نیم کی سنت ہے۔","",{"k":"مجمع الزوائد (٣٩٩/٩)۔"}],[304,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ملے عالم نے بیع غرر (دھوکے کی بیع) سے منع فرمایا۔“ لگا کر بیع کرنا جائز ہے۔ مذکورہ حدیث سے معلوم ہوا کہ دھوکہ دینے والی بیع منع ہے ہاں دھوکہ نہ دینے کی شرط جیسا کہ حدیث میں ہے کہ نبی معظم علیم نے فرمایا: سودا کرتے وقت کہہ دیا کرو کہ کوئی فریب دھوکہ نہیں ہوگا۔“ (صحیح بخاری، کتاب البيوع، رقم: ٢١١٧، صحیح مسلم، رقم: ١٥٣٣)","",{"k":"صحیح مسلم، سنن ترمذی (١٢٣٠)، سنن ابو داؤد (٣٣٧٦)۔"}],[305,"اسی سند سے روایت ہے کہ نبی ملنے کی ایم نے کنکری کی بیع سے منع فرمایا۔ مذکورہ حدیث سے معلوم ہوا کہ بیع الحصاۃ (یعنی کنکری پھینک کر بیچ کرنا ) منع ہے۔ مطلب یہ ہے کہ خرید نے والا یا بیچنے والا کہے کہ جب میں یہ کنکری پھینک دوں بیچ پختہ ہو جائے گی، یا جس چیز پر بھی کنکری پڑی وہ دے دوں گا یا لے لوں گا، خرید و فروخت کا یہ انداز ممنوع ہے، کیونکہ اس میں دھوکہ ہے۔ آج کل بھی ایسا جوا رائج ہے کہ آپ کا نشانہ جس چیز پر لگ جائے اتنی قیمت میں وہ آپ کی ہوگی۔ ٣٠٦","",{"k":"انظر ما قبله۔"}],[306,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بیوؤں اور مسکین کے لیے دوڑ دھوپ کرنے والا اللہ کی راہ میں جہاد کرنے والے کی طرح ہے۔“ کام ہے۔","",{"k":"صحیح بخاری (٦٠٠٧)، ♦، سنن ترمذی (١٩٧٩)، الادب المفرد (١٣١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بیواؤں اور مساکین کی خدمت کرنا بہت زیادہ ثواب کا اصل میں بیوہ اور مسکین کا نام بطور تمثیل کے ہے، مراد معاشرے کے ضرورت مند، نادار اور معذور افراد ہیں۔ ان کی کفالت، خبر گیری اور ان کے لیے دوڑ دھوپ کو اجر میں جہاد فی سبیل اللہ کے برابر قرار دے کر اسلام نے اس کام کی اہمیت کو واضح کر دیا ہے۔ مسلمان اس کو نہ سمجھیں تو اور بات ہے ورنہ اسلام نے معاشرے کے بے سہارا افراد کی امداد اور خیر خواہی کا حق ادا کر دیا ہے۔ اس سے یہ بھی معلوم ہوا کہ عبادت صرف نماز پڑھ لینا یا روزہ رکھ لینا ہی نہیں ہے، بلکہ ہر عمل صالح عبادت ہے، اور ضعفاء ومساکین کی خبر گیری بھی عبادت ہے۔ ٣٠٧"}],[307,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جمعے کے دن غسل کرنا ہر بالغ آدمی پر واجب ہے۔“","",{"k":"صحیح بخاری (٢٦٦٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ غسل جمعہ واجب ہے۔ ٣٠٨"}],[308,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ السلام نے فرمایا: قرآن کی مثال جب اس کو پڑھنے والا شخص اس کی نگہداشت کرے اور رات اور دن اس کے ساتھ قیام کرے تو SSGSS وہ بندھے اونٹوں کی طرح ہے کہ جب ان کا مالک ان کی نگہداشت کرے گا تو وہ انہیں قابو میں رکھے گا۔ اگر وہ ان کی رسیاں کھول دے گا تو وہ چلے جائیں گے۔ اسی طرح قرآن پڑھنے والے کی مثال ہے۔“","",{"k":"صحیح بخاری، صحیح مسلم (٧٨٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قرآن مجید کی دیکھ بھال کرنا چاہیے، اور اس کو بھلا دینے سے ڈرنا چاہیے۔ قرآن پاک کی نگہداشت اس طرح ہے کہ پابندی سے اس کی تلاوت کی جائے مکمل حافظ ہو یا کچھ اجزا کا حافظ جتنا بھی یاد ہوا سے پڑھتا رہے گا تو یادر ہے گا۔ اگر قرآن پاک سے غفلت کی جائے تو انسان اتنی تیزی سے بھولتا ہے کہ اتنی تیزی سے اونٹ بھی رہی تڑوا کر نہیں بھاگتا، یہ تیزی سے بھول جانے میں تشبیہ ہے۔"}],[309,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ جب انہوں نے رافع بن خدیج کی یہ حدیث سنی کہ رسول اللہ صلی اللہ علیہ وسلم نے کرائے پر زمین دینے سے منع فرمایا ہے۔“ تو ابن عمر رضی اللہ عنہما نے فرمایا: ” ہم اسے راہٹ کی نالی کی پیداوار پر اور اس سے جو بھو سے وغیرہ سے نکلے اس کے کچھ حصے پر دیا کرتے تھے۔“ سیدنا حنظلہ بن قیس رضی اللہ عنہ سے روایت ہے کہ میں نے سیدنا رافع بن خدیج ہی اللہ سے","",{"k":"سنن ابی داؤد (٣٣٨٩)، المعجم الكبير للطبراني (١٥٣/١١)۔","f":"سونے اور چاندی کے عوج زمین کو ٹھیکے پر دینے کے متعلق دریافت کیا تو انہوں نے کہا: اس میں کوئی حرج نہیں۔ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگ اس شرط پر زمین ٹھیکے پر دیا کرتے تھے کہ جو کچھ پانی کی نالیوں اور ندیوں کے کناروں پر پیدا ہو گا اور کھیتی کا کچھ حصہ میں لوں گا۔ تو کبھی یہ حصہ تباہ ہو جاتا اور وہ سلامت رہتا اور کبھی یہ سلامت رہتا اور وہ تباہ ہو جاتا، لوگ صرف اسی طرح زمین ٹھیکے پر دیتے تھے۔ پس اس لیے نبی معظم صلی اللہ علیہ وسلم نے اس سے منع فرمایا تھا، البتہ اگر کوئی چیز مقرر اور ذمہ میں لی گئی ہو تو پھر کوئی حرج نہیں۔ (صحیح مسلم، كتاب البيوع، رقم: ١٥٤٧، سنن ابی داؤد، رقم: معلوم ہوا کہ نقدی یا معلوم منافع کے بدلے زمین کو ٹھیکے پر دینا جائز ہے۔ جن روایات میں ممانعت ہے ان سے مراد یہ ہے کہ زمین کو ٹھیکے پر دیتے وقت کسی خاص حصے کی پیداوار کو اپنے لیے مخصوص کر لینا جیسا کہ عہد رسالت میں لوگ کیا کرتے تھے۔ اس کا نقصان یہ ہوتا تھا کہ کبھی ایک حصے میں پیداوار زیادہ ہو جاتی اور دوسرے حصے میں نہ ہوتی تو مالک کو فائدہ ہو جاتا اور ٹھیکیدار کو نقصان، کبھی اس کے برعکس ہوتا۔ ٣١٠"}],[310,"سیدنا عبداللہ ابن عم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ لوگوں کے حواشی کا ان کی اجازت کے بغیر دودھ دوہا جائے۔ یہ حدیث اسامہ بن زید سے زین بن شعیب ہی روایت کرتے ہیں، ان سے عبدالاعلیٰ بن عبد الواحد الکلاعی اکیلے ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ بغیر اجازت جانوروں کا دودھ دھونا منع ہے۔ اگر شرعی عذر کے بغیر کسی کے جانوروں کا اس قدر دودھ دھو لیا، جس کی قیمت چوری کے نصاب کو پہنچتی ہو تو اس پر چوری کی حد لگے گی۔","",{"k":"صحيح مسلم (١٧٢٦)، سنن ابو داؤد (٢٦٢٣)، المعجم الكبير للطبراني (١٥٣/١١)۔"}],[311,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی ملے جب چاند دیکھتے تو کہتے: ((هِلَالُ خَيْرٍ وَرُشْدِ أَمَنْتُ بِالَّذِي خَلَقَكَ فَعَدَلَكَ)) (اللہ کرے) یہ چاند خیر و بھلائی اور ہدایت کا ہو! میں اس ذات پر ایمان لایا ہوں جس نے تجھے پیدا کیا پھر برابر کیا۔ یہ حدیث بیٹی سے زہیر ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد (٥٠٩٢)، قال الالبانی: سنده ضعیف۔","f":"مذکورہ روایت کمزور ہے۔ تاہم درج ذیل دعا نبی معظم مالٹے علیم سے ثابت ہے: (( اللهم اهله علينا بالامن والايمان والسلامة والاسلام ربي وربك الله . )) (سنن ترمذی، کتاب الدعوات، رقم: ٣٤٥١، مسند احمد: ١٦٤/١) اسی طرح دوسری دعا:٣١٢ ((الله اكبر، اللهم اهله علينا بالامن والايمان والسلامة والاسلام والتوفيق لما تحب ربنا وترضى ربنا وربك الله (سنن دارمی، کتاب الصوم: ٣٣٦/١، اسنادہ صحیح)"}],[312,"سیدنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس کھیتی میں جو اپنی جڑوں ہی سے تری حاصل کرے اور جسے نہریں سیراب ہوں اس پر دسواں حصہ مقرر کیا ہے۔ اور جس کو پانی زمین سے نکال کر سیراب کیا جائے اس میں نصف عشر ( بیسواں حصہ)۔“ یہ حدیث یزید بن ابی حبیب سے صرف ابن لھیعہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن ابی مریم اکیلے ہیں۔ باری تعالیٰ ہے: مذکورہ حدیث سے معلوم ہوا کہ زرعی پیداوار کی زکاۃ دینا ضروری ہے۔ جیسا کہ ارشاد وَاتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾ (الانعام: ١٤١) اس کی کٹائی کے دن اس کا حق ادا کرو۔“ یہ بھی معلوم ہوا کہ ادائیگی فصل کاٹنے کے موقع پر ہے، اگر سال میں دو فصلیں ہوں گی تو عشر بھی دو مرتبہ ادا کرنا ضروری ہوگا کیونکہ اس میں سال گزرنے کی شرط نہیں ہے بلکہ فصل کا ہونا شرط ہے وہ جب بھی ہو اور جو بھی ہو۔ اگر زمین بارانی ہے یعنی بارش، قدرتی چشموں وغیرہ سے سیراب ہوتی ہے، اور اس پر کچھ خرچ نہیں ہوتا تو اس کی پیدوار سے دسواں حصہ ( عشر ) ادا کیا جائے۔ اگر زمین غیر بارانی ہے ( چاہی یا نہری ہے جس کی سیرابی پر آبیانہ وغیرہ کی صورت میں اخراجات برداشت کرنے پڑتے ہیں یا ٹیوب ویل کے ذریعے سے اسے سیراب کیا جاتا ہے تو اس سے نصف العشر (بیسواں حصہ ادا کیا جائے گا۔) ٣١٣","",{"k":"سنن ابی داؤد (١٥٩٨)، المعجم الكبير للطبراني ١١٠١ ٤٢١/١٠ (١٢٩٣٢)، قال الالبانى، صحیح۔"}],[313,"سیدنا مستورد بن شداد رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” یہ امت پہلی امتوں کے طریقوں کو ترک نہیں کرے گی بلکہ ان کے مطابق چلے گی۔“ یہ حدیث مستورد سے صرف اسی سند سے مروی ہے اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ موجودہ امت پہلی امتوں کے طریقوں کو نہیں چھوڑے گی بلکہ ان کے شانہ بشانہ چلے گی۔ مثلاً پہلی امتوں کے علماء کی طرح اس امت میں بھی علماء سوء ہوں گے،نصاری نے جس طرح بدعات شروع کیں اس امت میں بھی ہوں گی۔ عقائد اور اعمال ان کے مطابق ہوں گے۔ جیسا کہ موجودہ دور میں ہیں۔ اسی طرح شادی بیاہ اور موت، غم میں یہود و نصاریٰ کی ہزاروں رسمیں مسلمانوں نے اختیار کر لیں ہیں۔","",{"k":"صحيح الجامع الصغير (٧٢١٩)، مجمع الزوائد ٢٦١/٧۔"}],[314,"سیدنا عوف بن مالک ابھی بھی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے قرآن کا ایک حرف بھی پڑھا تو اس کے لیے نیکی لکھی جائے گی۔ میں یہ نہیں کہتا کہ الم ایک حرف ہے، بلکہ الف ایک حرف ہے، لام ایک حرف میم ایک حرف ہے۔“ یہ حدیث عوف بن مالک سے اسی سند سے مروی ہے، اسے روایت کرنے میں سلیمان بن ہلال اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم ترمذی شریف میں ہے سیدنا عبد اللہ بن مسعود بنی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اللہ کی کتاب (قرآن مجید ) کا ایک حرف پڑھا اس کے لیے ایک نیکی ہے اور ایک نیکی دس نیکیوں کے برابر ہے۔ میں نہیں کہتا کہ الم، ایک حرف ہے، بلکہ الف ایک حرف ہے، لام ایک حرف ہے اور میم ایک حرف ہے۔ (یعنی یہ تین حرفوں سے مرکب ہے اور دس ضرب تین یعنی ٣٠ نیکیاں پڑھنے والے کو ملیں گی ) (سنن ترمذی ابواب ثواب القرآن، رقم: ٢٩١٠، اسناده مذکورہ حدیث میں قرآن پاک کی تلاوت کی فضیلت کا اثبات ہے۔ صحی","",{"k":"مجمع الزوائد (٧/١٦٣)۔"}],[315,"سعيد بن عبید کہتے ہیں انہوں نے سیدنا زید بن ثابت رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ میں قرآن مجید لکھا کرتا تھا۔ مذکورہ حدیث میں سیدنا زید بن ثابت رضی اللہ عنہ کی فضیلت کا تذکرہ ہے کہ یہ کاتب وحی تھے یہ بہت بڑا شرف ہے۔ سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ نبی معظم صلی اللہ علیہ وسلم کے زمانے میں چار آدمی جن کا تعلق قبیلہ انصار سے تھا قرآن مجید جمع کرنے والے تھے۔ سیدنا ابی بن کعب، سیدنا معاذ بن جبل، سیدنا ابو زید، اور سیدنا زید بن ثابت رضی اللہ عنہ۔ (صحیح بخاری، کتاب المناقب، رقم: ٣٨١٠)","",{"k":"مجمع الزوائد (٢٥٧/٨)، المعجم الكبير للطبراني (٥٥/٥)۔"}],[316,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ میں داخل ہوئے تو کعبہ میں تین سو ساٹھ بت تھے، آپ صلی اللہ علیہ وسلم انہیں ایک لکڑی سے مارتے جو آپ مسلم کے پاس تھی اور فرماتے: جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقاً حق آ گیا اور باطل مٹ گیا بے شک باطل نابود ہونے والا ہے۔“ یہ حدیث جامع بن ابی راشد سے صرف سفیان بن عیینہ ہی روایت کرتے ہیں، اسے روایت کرنے والے ابو صالح الحرانی اکیلے ہیں۔","",{"k":"کر صحیح بخاری، صحیح مسلم (١٧٨١)۔","f":"پہلی آیت جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ الخ (بنی اسرائیل: ٨١) جَاءَ الْحَقُّ وَمَا يُبْدِي الْبَاطِلُ وَمَا يُعِيدُ (السباء: ٤٩) حق سے مراد دین اسلام اور باطل سے مراد بت اور شیطان ہے، باطل ختم ہو گیا ہے اب وہ سر اٹھانے کے قابل نہیں رہا۔ بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ (الانبياء: ١٨) بلکہ ہم سچ کو جھوٹ پر پھینک مارتے ہیں پس سچ جھوٹ کا سر توڑ دیتا ہے اور وہ اسی وقت نابود ہو جاتا ہے۔"}],[317,"سیدنا عبد الله بن ہشام رضی اللہ عنہ نے بیان کیا، ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے، جبکہ آپ سیدنا عمر بن خطاب ضیا اللہ کا ہاتھ پکڑے ہوئے تھے، سیدنا عمر یا اللہ کہنے لگے: اللہ کی قسم! آپ مجھے میری اپنی جان کے سوا ہر چیز سے زیادہ محبوب ہیں۔ آپ نے فرمایا: ” نہیں۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جب تک میں تمہیں تمہاری اپنی جان سے زیادہ محبوب نہ بن جاؤں۔“ سیدنا عمر بنی لینہ نے کہا: تو آپ اب مجھے میری جان سے بھی زیادہ محبوب ہیں۔ آپ نے فرمایا: ”اب ( تم کامل مومن ہو ) اے عمر!“ فائد ضروری ہے۔ مذکورہ حدیث سے معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم سے محبت کرنا ہر چیز سے زیادہ فرض، یہ بھی معلوم ہوا کہ رسول معظم سے علم کی محبت آپ کی اقتدا او فرمانبرداری سب سے بلند و بالا ہے۔ استاد ہو یا پیر مرشد یا امام مجتہد، والدین سب سے مقدم جناب رسول کریم صلے علیم کی شخصیت ہے محبت کے یہی معنی ہیں یہ نہیں کہ زبان سے یا رسول اللہ پکار لیا یا آپ کا نام مبارک سن کر انگوٹھوں کو چوم لیا یا نسبتاً عقا ئد تصنیف کر لیے۔ یہ سب رسمی اور بدعی طریقے اللہ کے ہاں کام آنے والے نہیں ہیں۔ قرآن پاک میں صاف ارشاد ہے: إن كُنتُمْ تُحِبُّونَ اللهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ) (آل عمران: ٣١) اگر تم اللہ تعالیٰ سے محبت رکھتے ہو تو میری تابعداری کرود، خود اللہ تعالیٰ تم سے محبت کرے گا۔“ دوسری جگہ یہ ارشاد باری تعالیٰ ہے: قُلْ إِنْ كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ الخ (التوبة: ٢٤) آپ (مومنین سے ) فرمائیے! اگر تمہارے باپ اور تمہارے بیٹے اور تمہارے بھائی، تمہاری بیویاں اور تمہارا کنبہ اور وہ مال جو تم نے کمائے ہیں اور وہ کاروبار جس کے مندے کا تم اندیشہ کرتے ہو۔ اور وہ مکانات جنہیں تم پسند کرتے ہو۔ تمہیں اللہ تعالیٰ سے اور اس کے رسول ملے تم سے اور اس کی راہ میں جہاد کرنے سے زیادہ پیارے ہیں تو اللہ تعالیٰ کے آنے والے حکم (عذاب) کا انتظار کرو","",{"k":"صحیح بخاری (٣٦٩٤)۔"}],[318,"سيدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آگ سے ایک گردن نکلے گی اس کی ایک زبان ہوگی جس سے وہ کلام کرے گی، اور دو آنکھیں ہوں گی جن سے وہ دیکھے گی، کہے گی: مجھے حکم ہوا ہے کہ جابر اور سرکش اور جو اللہ کے ساتھ کسی اور معبود کو پکارے اور جو کسی کو ناحق قتل کر دے (انہیں جلا ڈالوں )۔‘“","",{"k":"سنن ترمذى (٢٥٧٤)، السلسلة الصحيحة (٥١٢)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جہنم کی دو آنکھیں ہیں جن سے وہ دیکھے گی، زبان ہے جس سے بات کرے گی۔ جیسا کہ ارشاد باری تعالیٰ ہے::٣١٩ يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلاتِ وَتَقُولُ هَلْ مِنْ مَّزِيدٍ (ق: ٣٠) قیامت کے دن ہم جہنم سے پوچھیں گے، کیا تو بھر گئی ہے؟ اور وہ کہے گی: کیا اور کچھ ہے؟“ ایک حدیث میں ہے کہ جہنم کے کان ہیں جس سے وہ سنے گی ((واذ نان تسمعان)) (سنن ترمذی کتاب صفة جهنم باب ما جاء في صفة النار)"}],[319,"سيدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں سے کوئی شخص نماز ادا کر رہا ہو تو اپنی نظر آسمان کی طرف نہ اٹھائے۔ کہیں اس کی نظر اچک نہ لی جائے۔“ یہ حدیث از زهری از عبید الله از ابوسعید صرفر یزید بن ابی حبیب روایت کرتے ہیں، اسے روایت کرنے میں ابن مذکورہ حدیث سے معلوم ہوا کہ نماز میں آسمان کی طرف نظریں اٹھا نا سخت منع ہے۔ امام نووی اللہ نے فرمایا: نماز میں اس عمل کی حرمت پر اجماع ہے۔ شیخ عبداللہ بسام جماللہ فرماتے ہیں کہ امام نووی اللہ کی مراد، جمہور علماء کا اجماعہ ے کیونکہ امام احمد جماللہ نے اسے صرف مکر وہ کہا ہے۔ امام ابن حزم اللہ نے تو یہاں تک کہا ہے کہ نماز میں آسمان کی طرف نظریں اٹھانے سے نماز باطل ہو جاتی ہے۔ (سبل السلام: ٤٣٨/١) اس ممانعت کا سبب یہ بیان کیا جاتا ہے کہ یہ عمل آداب نماز اور خشوع و خضوع جو روح نماز ہے کے خلاف ہے۔ ٣٢٠","",{"k":"سنن ابو داؤد (٩١٣)، سنن نسائی (١٣٣٨)، صحيح الجامع الصغير (٧٤٩)۔"}],[320,"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے اس لڑکے یعنی عمر بن عبد العزیز اللہ سے زیادہ کسی اوار کو رسول اللہ صلی اللہ علیہ وسلم کی نماز کے مشابہ نہیں دیکھا۔“ یہ حدیث ربیعہ سے صرف عبد الرحمن بن عمر ہی روایت کرتے ہیں، ان سے روایت کرنے میں رشدین اکیلے ہیں۔ معلوم ہوا عمر بن عبدالعزیز جماللہ انتہائی نیک و پارسا شخصیت کے مالک تھے کہ آپ جماللہ کی نیکی اور فضل کی گواہی صحابہ کرام مینی نسیم نے بھی دی","",{"k":"سنن نسائی (١١٣٥)، مسند احمد: ٣/ ١٦٢ قال الالباني، حسن۔"}],[321,"سیدہ عائشہ علی الینا نے بیان کیا، رسول اللہ صلے عام رات کو نماز پڑھتے جب کہ میں آپ اور قبلے کے درمیان لیٹی ہوتی تھی۔“ یہ حدیث ربیعہ سے صرف سلیمان بن ہلال ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن وہب اکیلے ہیں۔","",{"k":"صحیح بخاری (٣٨٤)، صحیح مسلم۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بیوی اگر شوہر کے قریب یا سامنے لیٹی ہوئی ہو تو نماز صحیح ہے۔ اسی طرح کوئی سامنے سویا ہو تو نمازی کی نماز صحیح ہے۔ ٣٢٢"}],[322,"سیدنا رافع بن خدیج رضی اللہ عنہ نے بیان کیا، ہم اپنی زمین کرائے پر دیا کرتے تھے تو آپ صلی اللہ علیہ وسلم نے ہمیں اس سے منع فرمایا۔ احمد بن رشدین فرماتے ہیں کہ ابومعدان، مکہ کے رہنے والے جلیل القدر محدث تھے۔ یہ حدیث ابو معدان سے صرف زمین بن شعیب ہی روایت کرتے ہیں۔ ٣٢٣","",{"k":"المعجم الكبير للطبراني (٣٤١/٤)۔"}],[323,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: بے شک ایک شخص لوگوں سے مانگتا ہے یہاں تک کہ جب وہ قیامت کو آئے گا تو اس کے چہرے پر گوشت کا ٹکڑا بھی نہ ہوگا۔“ یہ حدیث صفوان بن سلیم سے صرف عبید اللہ بن ابی جعفر ہی روایت کرتے ہیں۔","",{"k":"صحيح بخاری (١٤٧٤)، صحيح الجامع الصغير (٥٨١٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بلا ضرورت سوال کرنا درست نہیں ہے ایسے سائل کے چہرے پر قیامت کو گوشت نہیں ہوگا، گو یا بلا ضرورت سوال کرنے کا نتیجہ دنیا اور آخرت دونوں جہاں میں ذلت و رسوائی ہے۔ ایک حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص لوگوں سے مال میں اضافہ کرنے کے لیے سوال کرتا ہے تو وہ آگ کے انگارے کا سوال کرتا ہے۔ (اسے اختیار ہے کہ ) وہ کم طلب کرے یا زیادہ۔“ (صحیح مسلم، کتاب الزكاة، رقم: ١٠٤١) اس سے یہ بھی معلوم ہوا کہ بغیر ضرورت کے سوال کرنا بہت بڑا جرم ہے۔ لہذا ہمیں پیشہ ور بھکاریوں کی حوصلہ شکنی کرنی چاہیے۔ ٣٢٤"}],[324,"سیدنا علی بن ابی طالب نیل اللہ کا بیان ہے کہ میں نے رسول اللہ ملنے کی کمی سے سنا، آپ کم فرمارہے تھے: ”جس نے کسی بیمار کی بیمار پرسی کی، اس کے ساتھ ستر ہزار فرشتے مقرر کر دیئے جاتے ہیں جو اس کے لیے دعا کرتے رہتے ہیں۔ یہ حدیث صفوان بن سلیم سے صرف اسحاق بن عبداللہ ہی روایت کرتے ہیں، اسے روایت کرنے والے ابن لھیعہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مریض کی عیادت کرنا بہت بڑا ثواب ہے سیدنا ثوبان نا الیہ سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان جب اپنے مسلمان بھائی کی عیادت کرتا ہے تو واپس آنے تک وہ جنت کے تازہ پھلوں کے چننے میں مصروف رہتا ہے۔ آپ سے پوچھا گیا: خُرفة الجنه کیا ہے؟:٣٢٥ لم نے فرمایا: اس کے تازہ پھل۔ (صحیح مسلم، كتاب البر والصلة، رقم: ٢٥٦٨)","",{"k":"السنن الكبرى للبيهقي (٣٨١/٣)، مسند احمد (١/١١٨)، سنن ترمذی (٩٦٩)۔"}],[325,"سیدنا معمر بن عبد اللہ عدوی کا بیان ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرما رہے تھے کھانا کھانے کے بدلے میں برابر برابر ہونا ضروری ہے۔“ یہ حدیث ابونضر سے صرف عمرو بن حارث ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن وہب اکیلے ہیں۔","",{"k":"صحیح مسلم (١٥٩٢)، صحيح الجامع الصغير (٣٩٥٢)۔"}],[326,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اس ( بد بودار ) درخت سے کھایا، وہ ہماری مسجد کے قریب بھی نہ آئے یہاں تک کہ اس کی بد بواس سے جاتی رہے۔“ یہ حدیث ابونضر سے صرف جبیر بن حکیم ہی روایت کرتے ہیں اور جبیر سے عمرو بن حارث روایت کرتے ہیں، اسے روایت کرنے میں رشدین اکیلے ہیں۔","",{"k":"صحیح بخاری (٨٥٣)، سنن ابو داؤد (٣٨٢٥)۔"}],[327,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما کہتے ہیں میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور مجھ پر ایک کپڑا تھا جو زرد رنگ سے رنگا ہوا تھا جب آپ نے اس کو مجھ پر دیکھا تو آپ نے اسے نا پسند کیا اور فرمایا: ”یہ کفار کا لباس ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ زرد رنگ کا کپڑا پہننا منع ہے نبی معظم تعلیم نے فرمایا: یہ کفار کا لباس ہے۔ جبکہ سیدنا براء رضی اللہ عنہ فرماتے ہیں (( رايته من حلة حمراء)) ”میں نے آپ صلی اللہ علیہ وسلم کو سرخ لباس میں دیکھا۔“ (صحیح بخاری، رقم: ٣٥٥١۔ سنن ابو داؤد، رقم: ٤٠٧٢) یہ دونوں احادیث ایک دوسری کی مخالف نہیں بلکہ ممانعت اس خاص سرخ رنگ سے ہے جو صرف عصفر بوٹی سے رنگنے سے حاصل ہوتا ہے۔ (نیل الاوطار: ٥٧١/١، تحفة الاحوذی: ٣٩٣/٥)","",{"k":"صحيح الجامع (٢٢٧٣)، السنن الكبرى للبيهقي (٣/٢٤٥)۔"}],[328,"سیدنا اسامہ بن زید خلیل جا نے بیان کیا میں گواہی دیتا ہوں کہ میں نے رسول اللہ م کو یہ کہتے ہوئے سنا ہے ”بے شک اللہ تعالیٰ کسی بدگو، تکلف سے بدگوئی کرنے والے کو پسند نہیں فرماتا۔ یہ حدیث حضرت اسامہ سے اسی سند سے مروی ہے۔","",{"k":"المعجم الكبير للطبرانی (١/١٧٠)، الادب المفرد (٣٢١)، صحیح الجامع الصغير (١٨٧٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بد زبانی کرنے والے، تکلف سے بدگوئی کرنے والے اور طعن و تشنیع کرنے والے سے اللہ تعالیٰ محبت نہیں کرتا۔ الفاحش فحش، فاحشہ، فحشا سے مراد وہ قول یا فعل ہے جو بہت ہی فتیح ہو زنا کو اسی لیے فاحشہ کہتے ہیں۔ شدید بخل کو فحشا کہتے ہیں۔ ارشاد باری تعالیٰ: الشَّيْطنُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُمْ بِالْفَحْشَاءِ﴾ (البقرہ: ٢٦٨) میں یہی مراد ہے۔ گالی دینا، بے حیائی کی بات کرنا بھی فحش سے ہے اور اس حدیث میں بھی یہی مراد ہے۔"}],[329,"سیدہ عائشہ رضی عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”چور کا ہاتھ ڈھال کی قیمت یا اس سے زائد، ربع دینار یا اس سے زائد کے علاوہ نہیں کاٹا جائے گا۔“ یہ حدیث ابوالنضر سے صرف ابن لھیعہ ہی روایت کرتے ہیں۔ مذکورہ روایت میں ہے کہ کتنی مالیت کی چوری پر چور کا ہاتھ کاٹا جائے گا۔ اصطلاح فقہاء میں چوری یہ ہے کہ کوئی آدمی کسی کے مملوکہ مال کو اس کے محفوظ مقام سے چھپ کر اٹھا لے۔ حدیث سے معلوم ہوا کہ دینار کا چوتھائی حصہ یا ڈھال کی قیمت کے برابر اگر چور اتنی یا اس سے زائد مالیت کی چیز چرائے گا تو پھر اس کا ہاتھ کاٹا جائے گا بصورت دیگر نہیں۔ جمہور علما اور خلفائے اربعہ اسی کے قائل ہیں۔ احناف کا کہنا ہے کہ ہاتھ کاٹنے کا نصاب دس درہم ہے اور اہل ظاہر نے کہا ہے کہ چوری کم مالیت کی ہو یا زیادہ کی قرآنی آیت کے عموم اور حدیث کی وجہ سے ہاتھ کاٹ دیا جائے گا۔ جمہور کا موقف گذشتہ صحیح احادیث کے مطابق ہونے کی بنا پر راج ہے۔","",{"k":"صحیح بخاری (٦٧٨٩)۔"}],[330,"سیدہ عائشہ ریلی اینجا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے ربع دینار یا اس سے زائد ( کی چوری ) پر ہی ہاتھ کاٹا جائے گا۔“ یہ حدیث سلیمان بن یسار سے صرف بکیر اور بکیر سے صرف مخرمہ ہی روایت کرتے ہیں۔","",{"k":"٣٣١ صحیح مسلم (١٦٨٤/٣)۔"}],[331,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اسے فرمایا: \"عائشہ! اگر بیہودگی اور مخش گوئی کوئی آدمی ہوتا تو برا آدمی ہوتا اور اگر حیا کوئی آدمی ہوتا تو سچائی والا آدمی ہوتا۔“ یہ حدیث ایوب","",{"k":"ضعيف الجامع الصغير (٣١٦٢)۔","f":"بن موسیٰ سے صرف عمر و بن حارث ہی روایت کرتے ہیں، اُن سے روایت کرنے میں ابن وہب اکیلے ہیں۔ اس حدیث میں بے ہودگی، بے حیائی کے ترک کرنے کی ترغیب اور زیور حیا سے آراستہ ہونے کی تاکید ہے۔ مذکورہ روایت کمزور ہے۔ تاہم سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس چیز میں بے ہودگی ہوگی وہ اسے عیب دار کر دے گی اور جس چیز میں حیا ہو گا وہ اسے خوب ا صورت بنا دے گا۔ (سنن ترمذی ابواب البر والصلة رقم: ٩٧٤، اسناده (صحیح) ٣٣٢"}],[332,"سیدہ عائشہ منی یالنیہا نے بیان کیا، میں نے طواف افاضہ سے پہلے اپنے ہاتھ سے نبی تعلیم کو خوشبو لگائی۔ یہ حدیث ایوب بن موسیٰ سے صرف عبد اللہ بن عامر ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن ابی حازم اکیلے ہیں۔","",{"k":"صحیح بخاری، کتابب اللباس تطيب المرأه (٥٩٢٢)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ طواف افاضہ سے قبل خوشبو لگانا درست ہے۔ (طواف افاضہ یہ رکن حج ہے )۔ جیسا کہ ارشاد باری تعالیٰ ہے: وَلْيَطَّوْفُوا بِالْبَيْتِ الْعَتِيقِ﴾ (الحج: ٢٩):٣٣٣ اور حجاج کو چاہیے کہ بیت اللہ کا طواف کریں۔“ اس طواف میں رمل ہے نہ کندھا ننگا رکھنا ہے کیونکہ اس طواف کے بعد حاجی مکمل حلال ہو جاتا ہے۔"}],[333,"سیدنا عبد اللہ المزنی یا اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بچے کا عقیقہ کیا جائے اور اس کے سر پر خون نہ لگایا جائے۔“ مذکورہ حدیث سے معلوم ہوا کہ عقیقہ کرنا سنت ہے، جیسا کہ نبی مکرم لیے علیم نے فرمایا: ہر بچہ اپنے عقیقہ کے ساتھ گروی ہوتا ہے (لہذا) ساتویں دن اس کی طرف سے جانور ذبح کیا جائے،اس کا سر مونڈا جائے اور نام رکھا جائے۔“ (سنن ابن ماجه، کتاب الذبائح، رقم: ٣١٦٥، سنن ابی داؤد، رقم: ٢٨٣٨) دوسری بات یہ معلوم ہوئی کہ نبی مکرم اے علیم نے خون لگانے سے منع فرمایا ہے۔ خون کس طرح لگاتے تھے؟ جب جانور ذبح کیا جا رہا ہوتا اس کے چند بال کاٹ کر رکھ دیتے حتی کہ وہ تازہ تازہ خون اس کے سر پر دھاگے کی مانند بہنے لگتا پھر اس کا سر دھویا جاتا اور بال مونڈ دیے جاتے۔ اسی طرح جو اپنے مکان کی بنیا د رکھتے ہوئے جانور کا خون بنیادوں میں گراتے ہیں یا نئی گاڑی خرید کر اس کے ٹائروں وغیرہ کو خون لگاتے ہیں تو یہ بھی زمانہ جاہلیت کی باتوں میں سے ہے جن کی اسلام نے نفی کی ہے۔","",{"k":"سنن ابن ماجه (٣١٦٦)، السلسلة الصحيحة (٢٤٥٢)۔"}],[334,"اس سند سے روایت ہے کہ رسول اللہ اے علی تم نے فرمایا: اونٹ میں بھی فرع ( پہلا بچہ غیر اللہ کے نام پر ذبح کرنا) ہے اور بکریوں میں بھی فرع ( غیر اللہ کے نام پر پہلا بچہ ذبح کرنا) ہے ( یہ حکم منسوخ ہو گیا۔“ یہ دونوں حدیثیں ایوب بن موسیٰ سے صرف عمرو بن حارث ہی روایت کرتے ہیں، ان دونوں کو روایت کرنے میں ابن وہب اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ فرع ابتدائے اسلام میں تھا۔ فرع کا مطلب ہے کہ بکری اور اونٹ کا پہلا بچہ، کفار غیر اللہ کے نام پر کرتے تھے اور مسلمان اللہ کے نام پر مگر بعد میں جب قربانی کا حکم ہوا تو اس کو منسوخ کر دیا گیا۔","",{"k":"السلسلة الصحيحة (٤٩٥/٤، ٤، ١٩٩٦)، السنن الكبرى للبيهقي (٣٠٣/٩)۔"}],[335,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ بے شک رسول اللہ صلی اللہ علیہ وسلم وادی محسر میں آئے تو اپنی سواری کو چلایا اور فرمایا: کنکریاں لے لو۔“ یہ حدیث ایوب بن موسیٰ سے صرف ابن لھیعہ ہی روایت کرتے ہیں، اسے روایت کرنے میں اشہب اکیلے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ وادی محسر سے تیزی کے ساتھ گزرنا چاہیے۔ وادی محسر ایک ایسی وادی ہے جہاں اصحاب فیل پر عذاب نازل ہوا تھا۔ اس لیے آپ صلی اللہ علیہ وسلم نے وہاں سے جلدی جلدی گزرنے کا حکم دیا ہے۔ اس کے بعد منی پہنچ کر یوم اخر ١٠ ذی الحجہ کو سب سے پہلے جمرہ عقبہ کو کنکریاں مارنی چاہئیں۔","",{"k":"المعجم الكبير للطبراني (١٥٣/١١)۔"}],[336,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ علیم نے فرمایا: قریب ہے کہ تم میں سے کوئی ایک بکریوں کا ایک ریوڑ لے کر دو یا تین میل تک چلا جائے پھر جمعہ آئے تو وہ اس میں حاضر نہ ہو۔ اسی طرح تین جمعے ہوتا رہے تو اللہ تعالیٰ اس کے دل پر مہر لگا دیتا ہے۔“","",{"k":"تقدم تخریجه، انظر (٢٧٣)۔","f":"مذکورہ حدیث میں ان لوگوں کے لیے سخت وعید ہے جو اپنے کاروبار میں ہی مشغول رہتے ہیں۔ نماز جمعہ میں شرکت نہیں کرتے"}],[337,"سيدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: حسن اور حسین ( ا ) اللہ کے عرش مجید کی بالیاں ہیں مگر وہ لٹکی ہوئی نہیں۔ نیز آپ نے فرمایا: ”جب جنت والے جنت میں ٹھہر جائیں گے تو جنت کہے گی: اے میرے رب! تو نے مجھ سے وعدہ کیا تھا کہ میں اپنے ارکان میں سے دورکنوں کے ساتھ تجھے خوبصورت بنا دوں گا۔ اللہ تعالیٰ فرمائے گا: کیا میں نے تجھے حسن اور حسین کے ذریعے خوب صورت نہیں بنایا؟ یہ دونوں حدیثیں ابن لھیعہ سے صرف حمید بن علی ہی روایت کرتے ہیں۔","",{"k":"کر ضعيف الجامع الصغير (٢٧٨٣)، مجمع الزوائد (٩/١٨٤)۔"}],[338,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم سے روایت کیا کہ آپ ان کے پاس سے گزرے جبکہ وہ بیٹھ کر نماز پڑھ رہے تھے۔ تو آپ سے سلیم نے فرمایا: ”بیٹھنے والے کے لیے کھڑے ہو کر نماز پڑھنے والے سے آدھا اجر ہے۔ یہ حدیث اعمش سے صرف عیسی بن یونس ہی روایت کرتے ہیں، اسے روایت کرنے والے ابو صالح الحرانی اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ بیٹھ کر نماز پڑھنے والے کو کھڑا ہونے والے کی نسبت آدھا ثواب ملے گا۔ یہ اس وقت ہے جب کوئی طاقت ہوتے ہوئے کسی عذر کے بغیر بیٹھ کر نماز پڑھے اگر کوئی:٣٣٩ بیمار یا ضعیف کھڑا نہیں ہو سکتا تو بیٹھ کر پڑھنے سے وہ ان شاء اللہ پورا اجر پائے گا۔","",{"k":"صحيح الجامع الصغير (٣٨٢٨)، صحیح مسلم، رقم :٧٣٥۔ سنن ابی داؤد (٩٥٠)، المعجم الكبير للطبراني (٣١١/١، ٧٤١)۔"}],[339,"سیدہ عائشہ منی اشیا کا بیان ہے ”رسول اللہ صلی اللہ علیہ وسلم سے عورتوں کے حق مہر میں بارہ اوقیوں کی سنت جاری ہو گئی۔ اور ایک اوقیہ چالیس درہم کا ہوتا ہے اس طرح یہ چار سو اسی (٤٨٠ ) ہو گئے اور جنابت کے غنسل میں ایک صاع اور وضو میں دو رطل کی سنت جاری ہو گئی اور صاع آٹھ رطل کا ہوتا ہے اور جو کچھ زمین سے گندم، جو، منقہ اور کھجور پیدا ہو جب پانچ وسق تک پہنچ جائیں تو اس میں صدقہ کی سنت جاری ہوگی۔ وسق ساٹھ صاع کا ہوتا ہے تو یہ تین سو صاع ہو گئے اس صاع کے ساتھ جس کے مطابق سنت جاری ہے۔ رسول اللہ علیم کی سنت جاریہ یہ بھی ہے کہ غسل جنابت ایک صاع پانی سے ہو اور وضو دو رطل سے، ایک صاع آٹھ رطلوں کا ہوتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کی سنت جاریہ یہ بھی ہے کہ جو زمین سے گندم، جو، کشمش نکلے، جب پانچ وسق ہو جائیں اور وسق ساٹھ صاع کا ہوتا ہے تو یہ کل تین سو صاع ہو جائیں گے۔ اسی ایک صاع کے ساتھ سنت جاری ہے۔ یہ حدیث منصور بن معتمر سے صرف صالح بن موسیٰ ہی روایت کرتے ہیں۔","",{"k":"منجم اوسط طبرانی١ مجمع الزوائد: ٣ ٧٠ فيه صالح بن موسى الطلحى وهو ضعيفٌ۔"}],[340,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”صرف دو میں سے ایک آدمی روتا ہے ایک فاجر جو اپنے گناہ پورے کر لے یا نیک آدمی جو اپنی نیکی مکمل کر لے۔“","",{"k":"المعجم الكبير للطبرانی (١١/١٥٤)، مجمع الزوائد:٣/ ٢٠ فيه رشدين بن سعد وهو ضعيف . وهو۔"}],[341,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے شراب پی اللہ تعالیٰ اس کے پیٹ سے ایمان کا نور نکال دیتا ہے۔“","",{"k":"المعجم الكبير للطبراني (١٩/١١٨)، ضعيف الجامع الصغير (٥٦٤٥)، ضعيف الترغيب و الترهيب (١٤٨١)، سنن ابو داؤد (٤٠٧٩)۔"}],[342,"\"رسول اللہ تعلیم کے آزاد کردہ غلام سیدنا ثوبان رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب عمامہ باندھتے تو آپ اپنے عمامے کو اپنے آگے اور اپنے پیچھے لٹکاتے تھے۔“ یہ حدیث معاویہ بن صالح سے صرف حجاج بن رشدین ہی روایت کرتے ہیں، حضرت ثوبان سے یہ حدیث صرف اسی اسناد سے مروی ہے۔ مذکورہ روایت کمزور ہے۔ تاہم صحیح حدیث میں ہے کہ سیدنا جعفر بن عمرو بن حریث اپنے والد سے روایت کرتے ہیں انہوں نے کہا: میں نے نبی صلی اللہ علیہ وسلم کو منبر پر دیکھا، آپ پر سیاہ پگڑی تھی اس کے کنارے کو آپ نے اپنے کندھوں کے درمیان لڑکا یا ہوا تھا۔::٣٤٣ (صحیح مسلم، کتاب الحج، رقم: ١٣٥٩، سنن ابی داؤد، رقم: ٤٠٧٧)","",{"k":"مسند ابی یعلی (٨٥)، مجمع الزوائد (٥/١٢٠)۔"}],[343,"سيدنا سعد بن ابی وقاص رضی اللہ عنہ نے بیان کیا میں نے رسول اللہ صلی اللہ علیہ وسلم فرماتے ہوئے سنا: ”ان (امراء) کو اس وقت تک صدقات دیتے رہو جب تک وہ پانچوں نمازیں پڑھتے رہیں۔ حضرت سعد سے یہ حدیث مرفوعاً اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ھانی بن المتوكل کیلئے ہیں۔ وهو ٣٤٤","",{"k":"مجمع الزوائد (٣٨٠)، فيه هاني ابن المتوكل وضعيف۔"}],[344,"سیدنا عبد الرحمن بن ابی زید بن ارقم کا بیان ہے، میں ام المؤمنین ام سلمہ نبی پا کے پاس گیا تو انہوں نے پوچھا: کہاں سے آئے ہو؟ میں نے کہا: اہل کوفہ سے۔ انہوں نے کہا: تم وہی ہو جو نبی طل علم کو گالیاں دیتے ہو؟ میں نے کہا: ہم کو تو معلوم نہیں کون نبی صلی اللہ علیہ وسلم کو گالیاں دیتا ہے؟ فرمایا: کیا تم علی ضیا اللہ پر لعنت نہیں کرتے؟ اور جو ان سے محبت کرے تم اس پر لعنت کرتے ہو اور رسول اللہ صلی اللہ علیہ وسلم سیدنا علی رضی اللہ عنہ سے محبت کرتے تھے۔ یہ حدیث عبدالرحمن بن اخی زید بن رقم سے صرف یزید بن ابی زیاد ہی روایت کرتے ہیں اور یزید سے صرف عمرو بن ابی المقدام ہی روایت کرتے ہیں، اسے روایت کرنے میں یوسف بن عدی اکیلے ہیں۔ مذکورہ حدیث سے سیدنا علی المرتضی نبی اللہ کی فضیلت کا اثبات ہے۔ معلوم ہوا کہ سیدنا علی فضل اللہ کو برا بھلا کہنا، بغض رکھنا، گندی زبان استعمال کرنا، گویا کہ نبی معظم مالے علم کے ساتھ ایسا کرنا ہے۔ اور جو ایسا کرتا ہے وہ منافق ہے کیونکہ منافق آدمی کو نبی معظم صلی اللہ علیہ وسلم سے کچی عقیدت و محبت نہیں ہوتی اور مومن کو کچی عقیدت اور محبت ہوتی ہے۔ حدیث شریف میں ہے سیدنا علی رضی اللہ عنہ فرماتے ہیں: نبی معظم صلی اللہ علیہ وسلم نے مجھ سے عہد فرمایا تھا: ”صرف مومن تم سے میرے ساتھ صرف مومن ہی محبت کرے گا جبکہ منافق شخص ہی مجھ سے بغض رکھے گا۔ (صحیح مسلم، کتاب الایمان، رقم: ٧٨)","",{"k":"مسند احمد: ٦/ ٣٢٣ قال الشيخ شعيب الأرناؤط، اسناده صحیح۔"}],[345,"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ”اگر قبیلہ معد سے کوئی یہاں ہے تو وہ کھڑا ہو جائے تو میں اٹھنے لگا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” بیٹھ جاؤ۔ پھر آپ ملے سلیم نے دوبارہ یہی فرمایا تو میں اٹھ کھڑا ہو آپ صلی اللہ علیہ وسلم نے فرمایا: ” بیٹھ جا آپ ملے لیے تم نے پھر یہی فرمایا: میں کھڑا ہو گیا تو آپ ملنے سلیم نے فرمایا: ”بیٹھ جاؤ، پھر میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم کون سے قبیلے سے تعلق رکھتے ہیں؟ آپ ملنے سلیم نے فرمایا: ” تم قضاعہ بن مالک بن حمیر سے ہو۔“ یہ حدیث معروف بن سوید سے صرف ابن لھیعہ میں روایت کرتے ہیں، اسے روایت کرنے میں فضالہ بن مفضل اکیلے ہیں۔ ٤٦","",{"k":"المعجم الكبير للطبرانی (٢٧١/١٢)۔"}],[346,"سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا علی ربی الیہ سے کہا: جس کا میں مولی ہوں تو علی بھی اس کا مولیٰ ہے۔ یہ حدیث طاؤس سے صرف اُن کے بیٹے ہی روایت کرتے ہیں اور طاؤس کے بیٹے سے صرف معمر اور ابن عیینہ ہی روایت کرتے ہیں، اسے روایت کرنے میں عبدالرزاق اکیلے ہیں۔ .٣:٤٧","",{"k":"سنن ترمذی (٣٧١٣)، قال الالباني: صحيح۔"}],[347,"سیدنا عبد اللہ ابن عباس والی جا سے روایت ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ جب خلیفہ بنائے گئے تو لوگوں کو عورتوں کے متعہ سے منع کر دیا اور کہا: یہ ایسی چیز ہے کہ اس میں لوگوں کو اس وقت رخصت دی گئی جبکہ لوگ تھوڑے تھے اور پھر بعد میں یہ حرام کر دی گئی اور جو شخص آج کے دن کے بعد بھی یہ کام کرے گا تو میں اس پر سزا ڈالوں گا۔ یہ حدیث ابونضرہ سے صرف براء بن عبد اللہ ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نکاح متعہ منسوخ ہو چکا ہے۔","",{"k":"سنن ابن ماجه (١٩٧٣)، قال الالباني :حسن۔"}],[348,"سیدنا عمر بن خطاب نبی المیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے روز تمام بندوں میں سے مقام و مرتبے کے لحاظ سے افضل انسان انصاف والا مہربان حکمران ہے۔ اور اللہ کے بندوں میں سے اللہ کے نزدیک مقام و مرتبے کے لحاظ سے سب سے براشخص اعتدال سے کام نہ لینے والا ظالم ہے۔“ یہ حدیث اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ فائد مذکورہ روایت کمزور ہے تاہم عدل و انصاف کرنے والے حکمران کی بہت زیادہ فضیلت ہے۔ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”انصاف کرنے والے اللہ کے پاس نور کے منبروں پر ہوں گے۔“ (صحیح مسلم، کتاب الامارة، رقم: ١٨٢٧)","",{"k":"♦، سنن ترمذی (١٣٢٩)، السلسلة الضعيفه (١٥٦/٣، ١١٥٧)، مجمع الزوائد (٥/١٩٧)۔"}],[349,"محمد بن حنفیہ اپنے باپ سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شراب پینے میں اسی درے لگائے۔ یہ حدیث ابن حنفیہ سے صرف اسی سند سے مروی ہے،اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم، سیدنا علی ضیا اللہ سے روایت ہے کہ نبی اکرم علیم نے ( شرابی کو ) چالیس کوڑے لگوائے۔ (صحیح مسلم، کتاب الحدود، رقم: ١٧٠٧)","",{"k":"كنز العمال (١٢٦٨٧)، نصب الرايه (٣/٣٥١)۔"}],[350,"سیدہ عائشہ بنایا تنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی ازواج مطہرات سے جنبی ہونے کی حالت میں صبح کرتے اور پھر آپ اپنا روزہ پورا کرتے۔“ یہ حدیث عبداللہ بن ابی سلمہ سے صرف ابوز بیر ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔:٣٥١","",{"k":"وور مسند احمد (٦/٣٤)، قال الشیخ شعیب الارناؤط، اسناده صحيح۔"}],[351,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ عورت کی کسی ایسے مرد سے شادی کی جائے کہ اس کے نکاح میں اس کی پھوپھی یا اس کی خالہ موجود ہو۔","",{"k":"صحیح بخاری (٥١٠٩)۔","f":"مذکورہ روایت سے معلوم ہوا کہ ایک وقت میں پھوپھی بھتیجی یا خالہ، بھانجی کو جمع کرنا حرام ہے۔ یہ حرمت عارضی ہے کیونکہ مختلف اوقات میں بعد از طلاق یا وفات ہونے پر نکاح کر لینے میں کوئی حرج نہیں ہے۔ امام شافعی اللہ فرماتے ہیں کہ اس کی حرمت پر اجماع ہے۔ (شرح مسلم: ٢٠٧/٥)"}],[352,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے وہ رسول اللہ صلی اللہ علیہ وسلم سے اسی طرح بیان کرتے ہیں۔","",{"k":"٨-٠ تقدم تخريجه، انظر (٣٥١)۔"}],[353,"سيدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” سونا سونے ابوسعید کے بدلے میں برابر برابر ہے اور چاندی چاندی کے بدلہ میں برابر برابر ہے۔“","",{"k":"صحیح بخاری (٢١٧٦)۔"}],[354,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم بالوں کا ایک گچھا لے کر باہر نکلے تو فرمایا: ”یقینا بنی اسرائیل کی عورتیں اپنے سروں میں اس طرح کی چیز بناتی تھیں تو انہیں لعنت کی گئی اور ان پر مسجد میں حرام کر دی گئیں۔ یہ حدیث از عروه از حضرت ابن عباس صرف ابوالاسود ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مصنوعی بال جوڑ نا حرام ہیں۔ (٢) معلوم ہوا کہ بنی اسرائیل کی عورتوں کو اللہ کی حدود کو پامال کرنے کی وجہ سے مساجد سے روک دیا گیا تھا۔ جیسا کہ سیدہ عائشہ بنی الہا فرماتی ہیں کہ اگر رسول اللہ ملنے کی یہ صورت حال دیکھ لیتے جو عورتوں نے اپنائی ہے تو انہیں مسجدوں میں آنے سے منع فرما دیتے جیسے کہ بنی اسرائیل کی عورتوں کو روک دیا گیا تھا۔ (صحیح بخاری، کتاب الاذان، رقم: ٨٦٩، سنن ابی داؤد، کتاب الصلاة، رقم: ٥٦٩)","",{"k":"سنن ابو داؤد (٥٦٩)، المعجم الكبير للطبراني (٩/١٦٨)۔"}],[355,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”فطری امور پانچ ہیں (١) ختنہ کرانا (٢) زیر ناف بال مونڈنا (٣) مسواک کرنا (٤) ناخن کاٹنا (٥) اور بغلوں کے بال اکھیڑنا۔“ یہ حدیث از عروه از حضرت ابو ہریرہ صرف ابو اسود روایت کرتے ہیں، اُن سے روایت کرنے میں ابن","",{"k":"مسلم، رقم : ٤٩ . صحیح بخاری (٥٨٨٩)، صحیح۔","f":"فطرت کے لغوی معنی ہیں، ابتدا، اختراع ( گھڑنا) یا ایسی چیز بنانا جس کی پہلے کوئی مثال نہ ہو۔ لیکن یہاں مراد وہ جبلت یعنی مزاج و طبیعت ہے جس پر انسان کی ولادت ہوئی ہے بعض نے اس کی تعریف اس طرح کی ہے وہ قدیم طریقہ جسے انبیا السلام نے پسند فرمایا تھا اور تمام قدیم شریعتیں اس پر متفق رہیں گویا کہ وہ پیدائشی معاملہ ہے اور ہم کو بھی اس کی اقتدا کا حکم دیا ہے۔ ایک روایت میں دس امور کا تذکرہ ہے\n(١) مونچھیں کتروانا\n(٢) داڑھی بڑھانا\n(٣) مسواک کرنا\n(٤) ناک میں پانی چڑھانا\n(٥) ناخن تراشنا (١) جوڑوں کا دھونا (٧) بغلوں کے بال اکھیڑ نا (٨) زیر ناف بالوں کی صفائی کرنا (٩) استنجا کرنا (١٠) اور کلی کرنا۔ (صحیح مسلم، کتاب الطهارة، رقم: ٢٦١) ان تمام امور کو اختیار کرنا واجب ہے اور یہ اسلامی شعائر بھی ہیں۔ ٣٥٦"}],[356,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”با جماعت نماز ادا کرنا اکیلے نماز پڑھنے سے پچیس گنا افضل ہے۔ یہ حدیث امام مالک سے صرف امام شافعی ہی روایت کرتے ہیں۔ مذکورہ حدیث میں باجماعت نماز پڑھنے کی فضیلت کا تذکرہ ہے۔:٣٥٧","",{"k":"صحیح بخاری (٦٤٥)۔"}],[357,"سیدنا جابر بن عبد اللہ علی الیہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بقیع الغرقد کی طرف گئے تو وضو کیا، چہرہ اور ہاتھ دھوئے، پھر سر کا مسح کیا، پھر دائیں ہاتھ سے اپنے پاؤں پر پانی چھڑ کا اور ان کو یہ حدیث سلمہ بن عبد اللہ بن حصین سے صرف ابن لھیعہ ہی روایت کرتے ہیں۔ مذکورہ روایت کمزور ہے تاہم سیدنا حمران علی اہلیہ بیان کرتے ہیں کہ سیدنا عثمان رضی اللہ عنہ نے وضو کا پانی منگوایا۔ پھر تین مرتبہ اپنی دونوں ہتھیلیوں کو دھویا، پھر کلی کی، پھر ناک میں پانی چڑھایا اور اسے جھاڑا، پھر اپنے چہرے کو تین مرتبہ دھویا، پھر اپنے دائیں بازو کو کہنی تک تین مرتبہ دھویا، پھر بائیں کو اسی طرح دھویا، پھر اپنے سر کا مسح کیا، پھر اپنے دائیں پاؤں کو ٹخنوں تک تین مرتبہ دھویا، پھر بائیں کو اسی طرح دھویا، پھر فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے اس وضو کی طرح وضو کرتے دیکھا تھا۔::٣٥٨ (صحیح بخاری، کتاب الوضوء، رقم: ١٥٩، صحيح مسلم، رقم: ٢٢٦) یہ نبی معظم صلی اللہ علیہ وسلم کے وضو کا مختصر سا طریقہ ہے۔ ٣٣٨","",{"k":"مجمع الزوائد (١/٢٣٣)، فيه ابن لهيعة وهو ضعيف۔"}],[358,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما سے روایت ہے مسلمانوں کے کچھ آدمی مشرکوں کے ساتھ تھے وہ ان کی جماعت کو بڑھا رہے تھے پس تیر آتا جسے پھینکا جاتا تو وہ ان میں سے کسی مسلمان کو لگ جاتا پس وہ اسے قتل کر دیتا یا اسے تلوار مار کر قتل کر دیا جاتا تو اللہ تعالیٰ نے ان کے بارے میں یہ آیت نازل فرمائی: الَّذِينَ تَتَوَفَّاهُمَ الْمَلَئِكَةُ ظَالِمِي أَنْفُسِهِمْ قَالُوا فِيْمَا كُنْتُمْ قَالُوا كُنَّا مُسْتَضْعَفِيْنَ فِي الأرض جن لوگوں کو فرشتے فوت کر دیتے ہیں جبکہ اپنی جانوں پر ظلم کر رہے ہوتے ہیں تو کہتے ہیں تم کس حال میں تھے وہ کہنے لگے ہم زمین میں کمزور سمجھے جاتے تھے۔ ( آخر آیت تک )‘ یہ حدیث اسود سے صرف ابن لھیعہ ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٤٥٩٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اسلام اور مسلمانوں کے خلاف کسی مسلمان کے لیے دشمنوں کی فوج میں بھرتی ہونا جائز نہیں"}],[359,"سیدنا ابو ہریرہ نبی اللہ سے روایت ہے کہ نبی ملنے یاتم نے فرمایا: ” کسی شخص کا غیر متعلق باتوں کو چھوڑ دینا اس کے اسلام کے اچھا ہونے میں سے ہے۔ یہ حدیث زہری سے ابوسلمہ اور ان سے صرف عبدالرزاق بن عمر اور قرہ بن عبد الرحمن ہی روایت کرتے ہیں۔","",{"k":"。 سنن ترمذی (٢٣١٧)، ابن حبان، رقم: ٢٢٩ قال الالبانی: صحیح۔","f":"معلوم ہوا کہ بے مقصد چیزوں کو چھوڑ دینا آدمی کے اسلام کی خوبی ہے۔ ((ما لا يعنيه)) جو کام اس سے متعلق نہ ہو۔“ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کے جامع کلمات کا نمونہ ہے یعنی الفاظ کم ہیں مگر معنی و مفہوم بہت زیادہ ہے۔ مذکورہ حدیث میں بے مقصد اور بے فائدہ اقوال کا ترک بھی شامل ہے اور بے فائدہ اعمال و عقائد کا ترک بھی، اگر آدمی ہر بات اور ہر کام سے پہلے یہ سوچے کہ مجھے اس کام کا دنیا یا آخرت میں کیا فائدہ ہے تو بے شمار با تیں اور بے شمار کام خود بخود اس سے چھوٹ جائیں گے۔ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہو وہ اچھی بات کہے یا خاموش رہے۔“ (صحیح بخاری، رقم: ٦٤٧٥) ٣٦٠"}],[360,"سیدہ عائشہ منی اشنو جا نے بیان کیا، میں نے رسول اللہ نے ہم کو یہ فرماتے ہوئے سنا ہے: ”اے اللہ! جو شخص میری امت کے معاملات کا والی و ذمے دار بن جائے، پھر وہ میری امت کے ساتھ نرمی سے پیش آئے تو اس کے ساتھ تو بھی نرمی کر۔ اور جو شخص ان پر سختی کرے تو اس کے ساتھ تو بھی سختی کر۔“ یہ حدیث عمر و بن حارث سے صرف ابن لھیعہ روایت کرتے ہیں۔ ابوعلی الہمدانی کا نام تمامہ بن شفی ہے۔","",{"k":"صحيح مسلم (١٨٢٨)، صحيح الجامع الصغير (١٣١٢)۔","f":"مذکورہ حدیث میں مسلمانوں کے بادشاہوں، وزیروں، افسروں، جوں، فوجی کمانڈروں، اساتذہ کرام اور کسی بھی قسم کی ذمہ داری رکھنے والوں کو مسلمانوں کے ساتھ نرمی کرنے کی تاکید کی گئی ہے اور ان پر سختی کرنے اور مشقت ڈالنے سے منع کیا گیا ہے۔ رسول اللہ علی علیم نے اپنی امت پر مشقت ڈالنے والے کے حق میں بد دعا فرمائی کہ اللہ تعالیٰ اس پر مشقت ڈالے، اور نرمی کرنے والے کے حق میں دعا فرمائی کہ اللہ تعالیٰ اس کے ساتھ نرمی کرے۔ اگر حاکم عوام پر مشقت ڈالے گا تو رسول اللہ صلی اللہ علیہ وسلم کی بد دعا کی بدولت اللہ تعالیٰ بھی اس پر مشقت ڈال دے گا، اور اگر وہ ان پر نرمی کرے گا تو رسول اللہ صلی اللہ علیہ وسلم کی دعا کی وجہ سے اللہ تعالیٰ بھی اس سے نرمی فرمائے گا۔ ٦١"}],[361,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”شہید تین قسم کے ہیں (١) ایمان دار آدمی جو اچھے ایمان والا ہو، دشمن کو ملے تو اللہ تعالیٰ کو سچ کر دکھائے یہاں تک کہ قتل ہو جائے ایسے شخص کی طرف لوگ قیامت کے روز اپنی نظر اٹھا اٹھا کر دیکھیں گے۔ دوسرا وہ شخص ہے جو ایمان دار ہے اور عمدہ ایمان والا ہے دشمن کا سامنا کیا تو اس کو ایک گمنام تیر آیا اور اس کو مار ڈالا تو یہ دوسرے درجے کا شہید ہو گا۔ تیسرا شخص وہ مومن ہے جس نے گناہ بھی کئے ہوں گے وہ دشمن کے مقابل ہوا تو اللہ تعالیٰ کو اپنا ایمان سچ کر دکھایا یہاں تک کہ قتل ہو گیا تو یہ تیسرے درجے کا شہید ہے۔“ یہ حدیث حضرت عمر سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ ٣٦٢","",{"k":"سنن ترمذی (١٦٤٤)، مسند احمد: ١/ ٢٢ قال الالبانی، ضعیف۔"}],[362,"سیدنا عبد اللہ بن زید رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” جس چیز کو آگ نے چھوا ہو اس آگ پر پکی ہوئی چیز کھانے سے وضو (لازم ہو جاتا ) ہے۔‘ یہ حدیث زہری سے صرف محمد بن ابی حفصہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن مبارک اکیلے ہیں۔ منسوخ ہے۔ مذکورہ روایت میں ہے کہ آگ کی پکی ہوئی چیز کھانے سے وضو کرنا چاہیے۔ لیکن یہ حکم","",{"k":"صحيح مسلم، مما مست النار (٣٥١)۔"}],[363,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ سیدنا ابو بکر صدیق،سیدنا عمر فاروق اور دیگر صحابہ ٹی ایم سے کچھ لوگ نبی ملت علی ایم کی وفات کے بعد بیٹھے تو انہوں نے سب سے بڑے گناہوں کا ذکر کیا مگر انہیں اس کا کوئی علم نہ تھا، تو مجھے سیدنا عبد اللہ بن عمرو بن العاص رضی اللہ عنہما کے پاس ان سے پوچھنے کے لیے بھیجا۔ انہوں نے مجھے بتایا کہ سب سے بڑا گناہ شراب پینا ہے۔ میں نے جا کر انہیں بتایا تو انہوں نے اس سے انکار کر دیا اور سب ان کی طرف اٹھ کھڑے ہوئے۔ انہوں نے ان کو بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بنی اسرائیل کے ایک بادشاہ نے ایک آدمی کو پکڑا تو اسے اختیار دیا کہ وہ شراب پئے یا ایک بچے کو قتل کرے یا زنا کرے یا خنزیر کا گوشت کھائے، اگر وہ ایسا نہ کرے گا تو وہ اس کو مار ڈالیں گے تو اس نے شراب پینا پسند کر لیا پھر جب اس نے شراب پی لی تو انہوں نے جو کچھ بھی اس سے کرانا چاہا وہ اس سے باز نہ رہ سکا (اور سب برے کام کر لیے اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس وقت فرمایا: ”جو بھی شراب پیئے تو اس کی چالیس روز کی نماز قبول نہ ہو گی۔ اور جب تک اس کے مثانے میں اس سے کچھ بھی باقی موجود ہو اور وہ اس حالت میں فوت ہو جائے تو اس پر جنت حرام ہو گی،اگر وہ چالیس دن کے اندر اندر مر گیا تو وہ جاہلیت کی موت مرے گا۔‘“ یہ حدیث حضرت عبداللہ بن عمر سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں الدراور دی اکیلے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ شراب کبیرہ گناہوں میں سے ہے۔ (٢) یہ بھی معلوم ہوا کہ شرابی کی چالیس دن تک نماز قبول نہیں ہوتی۔ (٣) یہ بھی معلوم ہوا کہ اگر شرابی بغیر تو بہ کے مر گیا تو اس پر جنت حرام ہو جائے گی۔ (٤) اگر وہ فوت ہوا تو اسلام پر اس کی موت نہیں ہوگی کیونکہ شراب حرام ہے۔ جیسا کہ ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَنِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ إِنَّمَا يُرِيدُ الشَّيْطُنُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَ عَنِ الصَّلُوةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ (المائده: ٩٠ تا ٩١) ”اے ایمان والو! بات یہی ہے کہ شراب اور جوا اور تھان اور فال نکالنے کے پانسے کے تیر یہ سب گندی باتیں، شیطانی کام ہیں۔ ان سے بالکل الگ رہو تا کہ تم فلاح پا جاؤ۔ شیطان تو چاہتا ہے کہ شراب اور جوئے کے ذریعے سے تمہارے درمیان میں عداوت اور بغض ڈال دے اور اللہ تعالیٰ کی یاد سے اور نماز سے تم کو باز رکھے سواب بھی باز آجاؤ۔“","",{"k":"المعجم الكبير للطبراني (١٤٢/٢٠)، السلسلة الصحيحة (١٩٤/٦)، الترغيب والترهيب، رقم: ٢٣٧ . محيح۔"}],[364,"سیدہ عائشہ نون النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بلی کے متعلق فرمایا کہ وہ نجس نہیں۔“","",{"k":"مجمع الزوائد (١٠/١٦٢)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بلی نجس نہیں ہے۔ سیدنا ابو قتادہ بیانیہ کے لیے وضو کا پانی رکھا گیا تھا، اچانک ایک بلی آئی اور اس سے پانی پینے لگی۔ یہ دیکھ کر سیدنا ابوقتادہ رضی اللہ عنہ نے بلی کے لیے برتن کو مزید جھکا دیا اور اس نے پانی پی لیا۔ پھر لوگوں نے اس کے متعلق دریافت کیا تو انہوں نے فرمایا: میں نے رسول اللہ نے ہم سے سنا ہے ”بلی ناپاک نہیں۔“ سنن ابی داؤد، کتاب الطهارة، رقم: ٧٥، سنن ترمذی، رقم: ٩٢) اس حدیث سے یہ ثابت ہوا کہ بلی خود نا پاک ہے نہ وہ چیز جسے وہ چھولے یا جس میں منہ ڈال لے، البتہ یہ شرط ہے کہ بلی کے منہ کو کوئی ناپاک چیز نہ لگی ہو۔ امام ابن عبد البر جاللہ فرماتے ہیں کہ اس حدیث میں یہ دلیل ہے کہ جس چیز کا رکھنا ہمارے لیے حلال کیا گیا ہے اس کا جوٹھا بھی پاک ہے۔ (توضیح الاحکام: ١٤٠/١)"}],[365,"سيدنا حسن بن علی بن ابی طالب رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تم جہاں کہیں بھی ہو مجھ پر درود بھیجو کیونکہ تمہارا درود مجھ تک پہنچتا ہے۔“ یہ حدیث حسن بن علی سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابن ابی مریم اکیلے ہیں۔","",{"k":"سنن ابو داؤد (٢٠٤٢)، صحيح الجامع الصغير (٣١٦٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ نے تم پر صلاۃ وسلام پڑھنے کے لیے سفر کی مشقت اٹھانے کی کوئی ضرورت نہیں، انسان جہاں کہیں ہو اس کا درود آپ ملے یکم کو پہنچا دیا جاتا ہے۔ سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: (( ان الله في الارض ملائكة سياحين يبلغوني من امتى السلام)) اللہ کے فرشتے زمین پر چلتے ہیں، وہ مجھے میری امت کا سلام پہنچاتے ہیں۔“ فضل الصلوة على النبي، رقم: ٢١)"}],[366,"سيدنا حسین بن علی رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حسن اور ি حسین جنت کے جوانوں کے سردار ہوں گے۔“ یہ حدیث حضرت حسن سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں احمد بن عمر و الحمیر ی اکیلے ہیں۔","",{"k":"سنن ترمذی (٣٧٦٨)، المعجم الكبير للطبرانی (٦١/٣، ٢٥٣٤)، قال الالبانی، صحیح۔","f":"مذکورہ حدیث میں جنت کے شہزادوں کی فضیلت کا اثبات ہے۔"}],[367,"سیدنا اسامہ بن شریک زنی اہلیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم منی کی مسجد میں تھے کہ آپ کے پاس دیہات کے کچھ لوگ آئے تو انہوں نے کہا: اللہ کے رسول ملے یکم! جو کچھ انسان کو عطا ہوا اس میں سب سے بہتر چیز کون سی ہے؟ آپ نے فرمایا: ”اچھے اخلاق۔ یہ حدیث اشعث بن سوار سے صرف حفص بن غیاث ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١/٢٠٠)، صحیح ابن حبان (٤٧٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اچھا اخلاق سب سے بہترین چیز ہے بلکہ اچھا اخلاق قیامت کے دن ترازو میں سب سے زیادہ بھاری ہوگا۔ سیدنا ابو الدرداء رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ترازو میں کوئی چیز اچھے اخلاق سے زیادہ بھاری نہ ہوگی۔“ (سنن ابو داؤد، رقم: ٤٧٩٩، سلسلة صحيحه، رقم: ٨٧٦)"}],[368,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”وہ مومن جو لوگوں سے میل جول رکھے اور وہ اس کو تکلیف دیں تو وہ ان کی ایذا پر صبر کرے، اس مومن سے افضل ہے جو لوگوں سے میل جول نہیں رکھتا کہ وہ اس کو تکلیف دیں تو وہ ان کی تکلیف پر صبر کرے۔“ یہ حدیث از اعمش از حبیب، ابوبکر الداھری ہی روایت کرتے ہیں، اسے روایت کرنے میں زھیر بن عباد کیلے ہیں۔","",{"k":"سنن ابن ماجه (٤٣٢١)، المعجم الكبير للطبرانی (١١/١٥٥)، سنن ترمذى (٢٥٠٧)، قال الشيخ الالباني: صحیح۔","f":"مذکورہ حدیث میں لوگوں کے ساتھ میل جول رکھنے والے شخص کی فضیلت کا تذکرہ ہے۔ لوگوں سے علیحدگی اختیار کرنے میں کئی فوائد ہیں مثلاً گناہوں سے بچنا، نیکی کے لیے وقت کا بچ جانا، ریا کاری سے بچنا، لوگوں کی تکلیفوں سے محفوظ رہنا وغیرہ۔ مگر لوگوں کے ساتھ مل جل کر رہنے والا اور ان کی تکلیفوں پر صبر کرنے والا زیادہ بہتر اور زیادہ اجر کا مستحق ہے کیونکہ وہ اجتماعی عبادات نماز، زکاۃ، حج وغیرہ میں شریک رہ سکتا ہے، امر بالمعروف و نہی عن المنکر اور جہاد فی سبیل اللہ کا فریضہ انجام دے سکتا ہے، ماں باپ رشتہ داروں اور دوسرے لوگوں کے حقوق ادا کر سکتا ہے، علم حاصل کر سکتا ہے اور علم کا نور آگے پھیلا سکتا ہے۔"}],[369,"سیدہ عائشہ منی اشیا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اختیار دیا تو ہم نے آپ کو پسند کر لیا، اور اسے طلاق شمار نہیں کیا گیا۔ یہ حدیث سعید بن جبیر سے صرف عطاء بن دینار ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔ (١) اگر شوہر بیوی سے کہے تجھے اختیار ہے خود کو اختیار کر لو یا پھر مجھے اور نیت طلاق کی ہو پھر اگر بیوی نے اپنے آپ کو اختیار کر لیا تو طلاق ہو جائے گی۔ اور اگر شوہر کو اختیار کر لے تو نہیں ہوگی۔ (٢) فتوحات کے نتیجے میں جب مسلمانوں کی مالی حالت پہلے کی نسبت کچھ بہتر ہو گئی تو انصار و مہاجرین کی عورتوں کو دیکھ کر ازواج مطہرات رضوان اللہ علیھن نے بھی نان و نفقہ میں اضافے کا مطالبہ کر دیا۔ تو نبی معظم الے علی کی سخت ناراض ہوئے حتی کہ بیویوں سے علیحدگی اختیار کر لی جو ایک مہینے تک جاری رہی، بالآخر اللہ تعالیٰ نے یہ آیت نازل فرمائی: يَأَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَوةَ الدُّنْيَا وَزِيْنَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَ أسرحُكُنَّ سَرَاحًا جَبِيلًا الخ (الاحزاب: ٢٨ تا ٢٩) ”اے نبی! اپنی بیویوں سے کہہ دے اگر تم دنیا کی زندگی اور اس کی زینت کا ارادہ رکھتی ہو تو آؤ میں تمھیں کچھ سامان دے دوں اور تمھیں رخصت کر دوں، اچھے طریقے سے رخصت کرنا۔ اس کے بعد نبی معظم صلی اللہ علیہ وسلم نے سب سے پہلے سیدہ عائشہ ولی او یا کو یہ آیات سنا کر اختیار دیا تو سیدہ عائشتہ رویا نونها نے کہا میں اللہ اور رسول کو اختیار کرتی ہوں، یہی بات دیگر ازواج مطہرات نے فرمائی، کسی نے رسول اللہ صل علی یم کو چھوڑ کر دنیا کو ترجیح نہیں دی۔","",{"k":"صحیح بخاری (٥٢٦٢)، صحیح مسلم (١٤٧٧)۔"}],[370,"سیدنا وہب بن منبش رضی اللہ عنہ سے روایت ہے کہ نبی ملنے ہیم نے فرمایا: ” رمضان میں عمرہ کرنا ( ثواب کے لحاظ سے ) حج کے برابر ہے۔ یہ حدیث از سفیان از فراس صرف عبد العزیز بن ابان ہی روایت کرتے ہیں، اسے روایت کرنے میں حامد بن بیٹی اکیلے ہیں۔","",{"k":"صحیح مسلم، سنن ترمذی (٩٣٩)، سنن ابن ماجه (٢٩٩١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رمضان میں عمرہ کرنے کی بہت زیادہ فضیلت ہے اس سے حج کا ثواب حاصل ہوتا ہے۔ حج کے برابر ہونے کا مطلب، حج جیسا اجر وثواب ہے یہ مطلب نہیں ہے کہ اس سے فریضہ حج ادا ہو جائے گا اور اس کے بعد اس کی ضرورت نہیں رہے گی۔ رمضان میں عمرے کی یہ فضیلت غالباً اس لیے ہے کہ اس طرح ایک وقت میں دو عبادتوں کا اجتماع ہو جاتا ہے۔"}],[371,"سیدنا عبادہ بن صامت رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم رمضان مبارک میں مشرق کی طرف سرخ ستون دیکھو تو اپنے ایک سال کا کھانا ذخیرہ کر لو کیونکہ یہ بھوک کا سال ہو گا۔“ یہ حدیث ام عبد الله بنت خالد سے صرف بشر بن بکر ہی روایت کرتے ہیں، اسے روایت کرنے میں زید بن بشرا کیلئے ہیں۔ ٣٧٢","",{"k":"ضعيف الجامع الصغير (١٥٢/٣، ١٥٢٧)۔"}],[372,"سیدنا عبد اللہ بن ابی سرح نے بیان کیا، ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ میں سے دس صحابہ ابوبکر، عمر، عثمان، علی، زیبر و غیر هم بی ای نسیم حراء پر تھے کہ اچانک وہ حرکت کرنے لگا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ”حراء ٹھہر جا کیونکہ تجھ پر صرف ایک نبی، ایک صدیق یا ایک شہید ہے۔“ یہ حدیث عبداللہ بن سعد سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"صحیح مسلم (٢٤١٧/٥)، سنن ترمذی (٣٦٩٦)۔","f":"اہل سنت کا اس پر ایمان ہے کہ نبی مکرم ملنے نیم کے تمام صحابہ جنتی ہیں تاہم کچھ صحابہ کرام رضوان اللہ علیہم اجمعین کو نبی معظم صلی اللہ علیہ وسلم نے اپنی زبان مبارک سے جنت کی بشارت دی ان خوش نصیب میں سے دس وہ ہیں جن کو عشرہ مبشرہ کہا جاتا ہے۔ سیدنا ابو بکر، عمر، عثمان، علی،طلحہ، زبیر، سعد بن ابی وقاص، عبد الرحمان، سعید بن زید، ابو عبیدہ رضی السلام"}],[373,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”جب تم میں سے کوئی آدمی نماز میں ہو اور اس کے آگے سے کوئی گزرے تو اس کو رو کے اگر وہ انکار کرے تو وہ اس سے جہاد کرے۔“ یہ حدیث از رباح بن عبیده از عبدالرحمن بن ابوسعید صرف عمرو بن عثمان بن وہب ہی روایت کرتے ہیں۔ قاسم بن مالک اسے روایت کرنے میں منفرد ہیں۔","",{"k":"صحيح مسلم (٥٠٥)، سنن ابو داؤد (٦٩٧)۔","f":"ایک حدیث میں ہے اور سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی سترہ سامنے رکھ کر نماز پڑھنے لگے اور کوئی آدمی اس کے سامنے (یعنی سترے اور نمازی کے درمیان) سے گزرنے لگے تو نمازی کو چاہیے کہ اسے روکنے کی کوشش کرے اگر وہ باز نہ آئے تو اس سے لڑائی کرے کیونکہ وہ شیطان ہے۔“ (صحيح بخاری، کتاب الصلاة، رقم: ٥٠٩، صحيح مسلم، رقم: ٥٠٥، سنن ابی داؤد، رقم: ٧٠٠١) معلوم ہوا کہ جب نمازی نے سترہ رکھا ہو اور کوئی اس کے اور سترے کے درمیانی فاصلے سے گزرنا چاہے تو نمازی کو اسے پہلے اشارے وغیرہ سے روکنا چاہیے لیکن اگر گزرنے والا نہ رکے تو اس سے لڑائی بھی کی جاسکتی ہے۔ جمہور علماء نے اس عمل کو مستحب جبکہ اہل ظاہر نے اسے واجب قرار دیا ہے۔ ان احادیث سے یہ بھی معلوم ہوا کہ اتنے عمل سے نماز باطل نہیں ہوتی۔ (فتح الباری: ١٦٧/٢،شرح مسلم للنووى: ٤٦٤/٢)"}],[374,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا کہ رسول اللہ میم نے کدو کے برتن اور تارکول والے برتن میں نبیذ بنانے سے منع فرمایا۔“","",{"k":"صحيح مسلم (١٩٩٢)، سنن ابی داود (٣٦٩٠)۔","f":"اسلام سے پہلے جن برتنوں میں لوگ شراب بنایا کرتے تھے رسول اللہ صلی اللہ علیہ وسلم نے ان میں نبیذ ( پھلوں، کھجور، کشمش اور دیگر خشک یا تر پھلوں کا پانی کے ذریعے بنایا ہوا آمیزہ جو بطور مشروب استعمال ہوتا تھا ) بنا کر پینے سے منع فرما دیا۔ ان میں سے دو کا تذکرہ مذکورہ حدیث میں ہے۔ الدباء: بڑے سائز کے کدو جب خشک ہو جاتے تو ان کے اندر کا گودا وغیرہ نکال کر سخت خول کو برتن کے طور پر استعمال کیا جاتا تھا۔ افریقہ کے ملکوں میں آج بھی اس کا رواج ہے وہاں ایسے کدو بھی پائے جاتے ہیں جو نیچے سے گول ہوتے ہیں اور اوپر کی طرف ان کی گردن لمبی ہوتی ہے۔ ان کو بھی اندر سے خالی کر کے مشروب وغیرہ کے برتن کے طور پر استعمال کیا جاتا ہے۔ مزفت: وہ برتن جس کے اندر روغن زفت ملایا گیا ہو۔ یہ تارکول سے ملتا جلتا معدنی روغن ہے۔ زفت ملنے کا مقصد بھی وہی تھا کہ ہوا کا گزر نہ ہو اور شراب سازی کے لیے عمل تخمیر جلد اور شدت سے شروع ہو جائے۔"}],[375,"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سونا بدلے چاندی سود ہے مگر جب نقد بنقد ہو گندم بدلے گندم کے سود ہے مگر نقد بنقد اور کھجور بدلے کھجور کے سود ہے مگر نقد بنقد ہو۔“","",{"k":"وَالْبُرُّ بِالْبُرِ رِبًا إِلَّا هَاءَ وَهَاءَ، وَالتَّمْرُ بِالتَّمْرِ رِبًا إِلَّا هَاءَ وَهَاءَ)) کر صحیح مسلم (١٥٨٦)، سنن ابو داؤد (٣٣٤٨)۔","f":"اسلام نے ہم جنس اشیا کے تبادلے میں کمی بیشی یا ادھار دونوں کو ربا قرار دیا ہے اس کو شرعی اصطلاح میں ربا الفضل کہا جاتا ہے۔ بیع، صرف یعنی سونے کو چاندی یا ایک کرنسی کو دوسری کرنسی کے عوض بیچنے کی صورت میں مقدار میں کمی بیشی جائز ہے۔ ایک سو گرام سونے کے بدلے کئی سو گرام چاندی یا ایک ریال کے بدلے کئی روپے خریدنا بیچنا درست ہے۔ مگر ادھار کی اجازت نہیں۔ اگر آپ ریال کے عوض روپے خریدنا چاہتے ہیں تو جس وقت ریال دیں اسی وقت روپے حاصل کر لیں۔ اگر ایک طرف سے بھی تاخیر ہوئی تو اسلام کی رو سے یہ سود ہو گا۔ یہ آج کل کا عام مشاہدہ ہے کہ کرنسیوں کی شرح تبادلہ اور سونے چاندی کا نرخ لمحہ بہ لمحہ بدلتا رہتا ہے فوری تبادلہ نہ ہو اور ایک چیز دے کر اس کے بدلے دوسری چیز حاصل کرنے میں تاخیر ہو گی تو نرخ بدل چکا ہوگا۔ مذکورہ حدیث میں یہی بیان ہوا ہے۔"}],[376,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ نے ہم ایک ٹب میں غسل کرتے اور وہ ایک ڈول ہے، اور میں اور آپ ایک ہی برتن سے غسل کرتے تھے۔ مذکورہ حدیث سے معلوم ہوا کہ میاں بیوی دونوں ایک برتن میں اکٹھے غسل کر سکتے ہیں۔ نیز یہ بھی معلوم ہوا کہ میاں بیوی ایک دوسرے کے مکمل بدن کو ( قابل ستر اعضا سمیت) دیکھ سکتے ہیں۔ اور یہ بات اللہ تعالیٰ کے اس فرمان سے بھی ثابت ہوتی ہے: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ إِلَّا عَلَى اَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ﴾ (المؤمنون: ٥ تا ٦ ) اور وہ (مومن ) لوگ اپنی شرمگاہوں کی حفاظت کرتے ہیں، سوائے اپنی بیویوں اور لونڈیوں کے یقیناً یہ ملامت زدہ نہیں ہیں۔“","",{"k":"صحیح بخاری (٢٥٠)۔"}],[377,"سیدہ عائشہ بنی ہو یا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ سے حرم میں قربانی کا جانور بھیجتے تو میں آپ کی قربانی کے ہار بلتی تھی پھر محرم جس چیز سے اجتناب کرتا ہے آپ اس سے اجتناب نہ کرتے تھے۔“ مذکورہ حدیث میں ان لوگوں کا رد ہو رہا ہے جو کہتے ہیں کہ جب انسان ہدی بھیج دے اور اس کو قلادہ بھی پہنا دے تو اس پر احرام واجب ہو جاتا ہے، مگر مذکورہ حدیث سے معلوم ہوا کہ اگر آدمی نے عملاً احرام نہ باندھا ہو تو وہ محرم نہیں ہوتا اور نہ ہی اس پر احرام واجب ہو جاتا ہے۔","",{"k":"صحيح مسلم (١٣٢١)، سنن ابو داؤد (١٧٥٨)، سنن ترمذی (٩٠٨)۔"}],[378,"سیدہ عائشه رو یا علی بابا نے بیان کیا، صفیہ بنت حی مینی اشیا کو طواف افاضہ کرنے کے بعد حیض آگیا تو میں نے اس کے حیض کا رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا۔ آپ طلاے علی تم نے فرمایا: ” کیا وہ ہمیں روک لے گی؟ میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم! اس نے طواف افاضہ کر لیا ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”تو پھر وہ کوچ کرے۔“ مذکورہ حدیث سے معلوم ہوا کہ عورت نے طواف افاضہ کر لیا ہو اور بعد میں اسے حیض آ جائے تو وہ طواف وداع کیسے بغیر جاسکتی ہے۔","",{"k":"صحیح بخاری، سنن ابی داؤد (٢٠٠٣)۔"}],[379,"\"سیدنا سلیمان بن سیار سے روایت ہے کہ شعم قبیلہ کی ایک عورت نے رسول اللہ ما علیم سے حجتہ الوداع میں فتویٰ پوچھا جبکہ فضل بن عباس آپ کے ردیف تھے۔ اس نے کہا: اللہ کے رسول! اللہ تعالیٰ کا بندوں پر فریضہ حج میرے باپ پر اس وقت آیا جبکہ وہ بوڑھا ہو گیا ہے اور وہ سواری پر جم کر نہیں بیٹھ سکتا اگر میں اس کی طرف سے حج کروں تو کیا اسے کافی ہو جائے گا؟ آپ نے فرمایا: ”ہاں۔“ مذکورہ حدیث سے معلوم ہوا کہ کسی کی طرف سے حج کرنا جائز ہے۔","",{"k":"صحیح بخاری، انظر (١٤٨٤)۔"}],[380,"سیدنا بشیر بن سعد رضی اللہ عنہ رضی اللہ عنہ کو لے کر رسول اللہ میم کے پاس آئے اور عرض کیا میں نے اپنے اس بیٹے کو غلام ہبہ کیا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ” کیا تو نے اپنے تمام بچوں کو یہ عطیہ دیا؟ اس نے کہا: نہیں۔ آپ نے فرمایا: ”پھر یہ بھی واپس لے لو۔“ مذکورہ حدیث سے معلوم ہوا کہ والدین کو اپنی اولاد کے درمیان انصاف کرنا چاہیے، اگر والدین عطیہ و ہدیہ دینا چاہیں تو سب کو برابر دیں اگر کوئی بچہ زیادہ خدمت کرتا ہو تو وہ اس کی اپنی سعادت ہے جس کا اجر اسے اللہ کے ہاں ملے گا، خدمت گزار، غیر خدمت گزار چھوٹے، بڑے، عالم، جاہل، اور عاقل وغیرہ میں کوئی تمیز نہ کرے۔ اگر کسی کو ترجیح دے گا تو ظلم ہوگا۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((اعدلوا بين ابنائكم، اعدلوا بين ابنائكم)) (سنن ابی داؤد، كتاب الاجارة، رقم: ٣٥٤٤، اسنادہ صحیح) اپنی اولاد میں عدل کرو، اپنی اولاد میں عدل کرو۔“","",{"k":"صحیح بخاری، صحیح مسلم (١٦٢٣)۔"}],[381,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ علیم نے فرمایا: ” جو آدمی کھجور کے درختوں کی پیوند کاری کرے پھر وہ درخت فروخت کر دے تو ان کا پھل پیوند کاری کرنے والے کو ملے گا الا یہ کہ خریدنے والا شرط لگالے۔“ (١) مذکورہ حدیث سے معلوم ہوا کہ پیوند لگانے کے بعد اگر کھجور کا درخت فروخت کیا جائے تو پیوند کرنے والے کا اس سال درخت ہو گا لیکن اگر شرط نہ لگالے خرید نے والا تو خریدار کی ہو گی ورنہ مالک ہی کا رہے گا۔ (٢) یہ بھی معلوم ہوا کہ بیچ وشراء میں ایسی مناسب شرطوں کا لگانا جائز ہے، اور پھر معاملہ شرطوں کے ساتھ ہی طے سمجھا جائے گا۔","",{"k":"سنن نسائی (٤٦٣٥)، صحيح مسلم (١٥٤٣)۔"}],[382,"سیدنا عبداللہ ابن عمر علی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عمر بن خطاب نیل الیہ کو ایک قافلے میں پایا جبکہ عمر نا اہلیہ اپنے باپ کی قسم اٹھا رہے تھے۔ آپ صلی اللہ علیہ وسلم نے بلند آواز سے فرمایا: ”خبردار! اللہ تعالیٰ تمہیں اپنے باپوں کی قسم اٹھانے سے منع فرماتا ہے۔ جو شخص قسم اٹھائے تو وہ اللہ کی قسم اٹھائے یا چپ رہے۔ مذکورہ حدیث سے معلوم ہوا کہ اللہ تعالیٰ کے علاوہ کسی کی قسم اٹھانا جائز نہیں۔ شیخ عبد اللہ بسام اللہ نے فرمایا: قدیم زمانوں سے لوگوں کا یہ عقیدہ چلا آرہا تھا کہ جس کی قسم اٹھائی جائے وہ قسم اٹھانے والے پر تسلط و غلبہ رکھتا ہے اور مافوق الاسباب بھی اسے نفع و نقصان دینے پر قادر ہے جب قسم اٹھانے والا اپنی قسم پوری کرے تو وہ اس سے راضی ہوتا ہے اور اسے نفع پہنچاتا ہے اور اگر وہ راضی نہ ہو تو وہ اسے نقصان پہنچاتا ہے اور اس طرح اللہ تعالیٰ اور اس کی صفات کے علاوہ دوسروں کے نام کی قسم اٹھانا اللہ کے ساتھ شرک بن جاتا ہے۔ (توضیح الاحکام: ١٠٨/٧) اس اعتقاد کے ساتھ غیر اللہ کی قسم اٹھا نا صریحاً شرک ہے، اور اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے جس نے اللہ کے علاوہ کسی اور کی قسم اٹھائی یقینا اس نے شرک کیا۔“ (صحیح ابو داؤد، رقم: ٢٧٨٧) سیدنا عبد اللہ بن مسعود ضیا اللہ نے فرمایا تھا کہ مجھے غیر اللہ کے نام کی سچی قسم اٹھانے سے اللہ کے نام کی جھوٹی قسم اٹھانا زیادہ پسند ہے۔ (صحیح الترغيب و الترهيب، رقم: ٢٩٥٣) بعض حضرات نے یہ اعتراض اٹھایا ہے کہ اللہ تعالیٰ نے غیر اللہ کی قسم اٹھانے سے منع کیا ہے لیکن قرآن میں متعدد مقامات پر خود غیر اللہ کی قسم اٹھائی ہے مثلاً سورج وغیرہ کی قسم، اس کا جواب یہ دیا گیا ہے کہ یہ صرف اللہ تعالیٰ کے ساتھ خاص ہے اور اللہ تعالیٰ جو کرے اس جیسا کرنا ہمارے لائق نہیں اور لوگوں سے ان کے افعال کے متعلق سوال ہو گا لیکن اللہ تعالیٰ سے اس کے کیے ہوئے کام کے متعلق کوئی سوال نہیں کر سکتا۔","",{"k":"صحیح بخاری (٦٦٤٦)، صحيح مسلم (١٦٤٦)، سنن ابی داؤد (٣٢٤٩)۔"}],[383,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ آپ صلی اللہ علیہ وسلم کے صحابہ بنی السلام ނ کچھ لوگوں کو خواب میں لیلۃ القدر دکھائی گئی کہ وہ رمضان کے آخری سات دنوں میں ہوگی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میں تمہارا خواب سن رہا ہوں کہ وہ آخری سات دنوں کے مطابق ہے تو جو شخص اس کو تلاش کرنا چاہے تو وہ اسے آخری سات دنوں میں تلاش کرے۔“ ایک روایت میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: \"لیلۃ القدر کو رمضان المبارک کے آخری عشرے کی طاق راتوں میں تلاش کرو۔“ (صحیح بخاری، کتاب فضل ليلة القدر، رقم: ٤١٧) امام شوکانی رحمہ اللہ نے شب قدر کی تعیین کے متعلق پینتالیس (٤٥) مختلف اقوال نقل فرمائے ہیں۔ نيل الاوطار: ٢٦٣/٣، ٢٦٦) لیکن ان تمام اقوال میں راجح یہ ہے کہ شب قدر آخری عشرے کی طاق راتوں میں ہے۔ اس کی تائید اُن روایات سے ہوتی ہے جن میں آپ مطلے تم نے آخری عشرے کی طاق راتوں میں شب قدر کو تلاش کرنے کا حکم دیا۔ (صحیح بخاری، کتاب فضل ليلة القدر، رقم: ٢٠١٧، صحیح مسلم، رقم: ١١٢٩، سنن ترمذی، رقم: - مسند احمد: ٥٠/٦) حافظ ابن حجر ہاللہ، امام شوکانی، شیخ الاسلام ابن تیمیہ ہملہ نے اسی قول کو ترجیح دی ہے۔ (فتح البارى: ٧٩٥/٤، نیل الاوطار: ٢٧١/٣، مجموع الفتاوى: ٢٨١/٢٥) ٣٨٤","",{"k":"صحیح بخاری (١١٥٨)۔"}],[384,"سیدنا عبد اللہ ابن عمر بنی اہلیہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: ” تم میں سے کوئی آدمی کو اس کے بیٹھنے کی جگہ سے نہ اٹھائے کہ پھر وہ خود وہاں بیٹھ جائے۔“ (Y)) ٣٨٥","",{"k":"صحیح مسلم (٢١٧٧)۔"}],[385,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کوئی آدمی کسی کی بیچ پر بیچ نہ کرے اور نہ ہی کسی کے پیغام نکاح پر پیغام نکاح بھیجے۔“ مذکورہ حدیث سے معلوم ہوا کہ بیج پر بیع جائز نہیں۔ فائد اس کی صورت یہ ہے کہ ایک آدمی کہتا ہے کہ تو اس سودے کو فسخ کر دے اور میں تہیں اس سے عمدہ و بہترین، یا زیادہ قیمت دیتا ہوں۔ یہ چیز آپ مجھے دے دیں۔ حافظ ابن حجر جماللہ نے فرمایا: اس کی حرمت میں کوئی اختلاف نہیں۔ (فتح الباری: ٨٨/٥) (٢) یہ بھی معلوم ہوا کہ اگر کسی مسلمان بھائی نے کہیں پیغام نکاح بھیجا ہو تو وہاں اپنا پیغام نکاح بھیجنا ممنوع ہے۔ جمہور علماء نے اس ممانعت کو حرمت پر محمول کیا ہے۔ (نیل الاوطار: ٤ / ٨٠، فتح الباری: ٢٥٠/١٠) امام نووی، ابن قدامه، سعودی مستقل فتوی کمیٹی اسی کے قائل ہیں۔ (شرح مسلم: ٢١٤/٥، المغنی لابن قدامه: ٥٧٠/٩، فتاوى اللجنه الدائمه: ٥١/١٨) بعض اہل علم کی رائے یہ ہے کہ اگر کہیں رشتے کی بات چل رہی ہو اور ابھی پختہ نہ ہوئی ہو تو کوئی اور بھی پیغام نکاح بھیج سکتا ہے۔ جیسا کہ سیدہ فاطمہ بنت قیس بنیان با کوسیدنا معاویہ، ابوجم والا دونوں نے پیغام نکاح بھیج رکھا تھا لیکن ان میں سے کسی کے ساتھ بھی ابھی بات پختہ نہیں ہوئی تھی۔ امام شوکانی جماللہ نے اس موقف کا رد کرتے ہوئے کہا یہاں یہ احتمال موجود ہے کہ ایک کو دوسرے کے پیغام بھیجنے کا علم ہی نہ ہو۔ (نیل الاوطار: ١٨١/٤)","",{"k":"صحيح مسلم (١٤١٢)، سنن ابو داؤد (٢٠٨١)۔"}],[386,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس عمر شخص کی عصر کی نماز فوت ہو جائے تو گویا کہ اس کا اہل اور مال ہلاک ہو گیا۔“ مذکورہ حدیث سے معلوم ہوا کہ عصر کی نماز ادا نہ کرنا بہت بڑا گناہ ہے۔ وتر کے معنی ہیں کم کر دیا گیا یا چھین لیا گیا۔ پس وہ شخص بغیر اہل اور مال کے تنہا رہ گیا اس لیے ایک مسلمان کو نماز عصر کے فوت کرنے سے اسی طرح بچنا چاہیے جیسے کہ وہ گھر والوں سے اور مال کے فوت ہونے سے ڈرتا . ہے۔ سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس نے عصر کی نماز چھوڑ دی پس تحقیق اس کے عمل برباد ہو گئے۔“ (صحیح بخاری، کتاب مواقيت الصلاة: ٥٥٣) ٣٨٧","",{"k":"صحیح بخاری، رقم۔"}],[387,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ اس نے رسول اللہ صلی اللہ علیہ وسلم کو سنا بلکہ آپ مشرق کی طرف چہرہ مبارک کیے ہوئے فرمارہے تھے خبر دار! فتنہ اس طرف سے ہو گا جہاں سے شیطان کا سینگ طلوع ہوتا ہے۔“","",{"k":"صحیح بخاری (٧٠٩٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نبی معظم ملاے علی تم نے پیش گوئی فرمائی کہ فتنے مشرق کی طرف سے اٹھیں گے۔ شیطان طلوع اور غروب کے وقت اپنا سر سورج پر رکھ دیتا ہے تا کہ سورج پرستوں کا سجدہ شیطان کے لیے ہو۔ مدینہ منورہ کے مشرق کی طرف عراق، ایران وغیرہ ممالک واقع ہوئے ہیں ان ہی ممالک سے بہت سے فتنے شروع ہوئے تاتاریوں کا فتنہ بھی ادھر ہی سے شروع ہوا جنہوں نے بہت سے اسلامی ممالک کو برباد کر دیا۔ دجال بھی جو مشرق سے آئے گا اسی طرح یا جوج ماجوج آئیں گے۔"}],[388,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے جو غلام شرکا کا ساجھی ہو اور ان میں سے ایک نے اپنا حصہ آزاد کر دیا تو اگر اس کے پاس مال ہو تو اس کے لیے انصاف سے قیمت لگا کر اس کو آزاد کرنے والے کی طرف سے وہ سالم آزاد ہو جائے گا۔“","",{"k":"المعجم الكبير للطبراني (١٥٦/١١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ اگر کوئی غلام دو یا زیادہ افراد کی ملکیت میں ہو اور ان ि میں سے کوئی ایک اپنے حصے کا غلام آزاد کرنا چاہے تو اسے چاہیے کہ مکمل غلام کی قیمت لگائے اور پھر اگر اس کے پاس اتنی مالیت ہو تو وہ اپنے باقی شرکا کو انصاف کے ساتھ ان کے حصے ادا کر دے اور غلام کو آزاد کرا دے۔لیکن اگر آزاد کرنے والے کے پاس مزید اتنا مال نہیں جو اس کی مکمل قیمت کے برابر ہو تو پھر غلام کو اتنا مال کما کر لانے کی زحمت دی جائے گی جو دوسرے شرکا کے حصص کے برابر ہو۔ جب وہ حصص مالکان کو ادا کر دیے جائیں تو غلام آزاد ہو جائے گا۔"}],[389,"سیدنا عبداللہ بن عمر نبی اللہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص شکاری کتے اور چارپایوں کے کتے کے علاوہ کوئی اور کتا رکھتا ہے تو اس کے اجر سے روزانہ دو قیراط کم ہو جاتے ہیں۔“ مذکورہ حدیث سے معلوم ہوا کہ شوقیہ طور پر کتا رکھنا جائز نہیں ہے جو ایسا کرے گا تو روزانہ دو قیراط اس کے ثواب سے کم ہوتے رہیں گے۔","",{"k":"٥٤٨٠ : صحیح بخاری، رقم : ٨٠ صحیح مسلم (١٥٧٤)۔"}],[390,"سیدنا عبد اللہ بن عم رضی اللہ عنہ نے خبر دی کہ رسول اللہ سے ہم نے فرمایا: ”جب کسی مسلمان شخص کے پاس کوئی وصیت کرنے کے قابل چیز ہو تو اس کا حق نہیں کہ وہ دو راتیں بھی گزارے مگر اس کی وصیت اس کے پاس لکھی ہونی چاہیے","",{"k":"صحیح بخاری (٢١٧٦، ٢٧٣٨)، سنن ابو داؤد، سنن ترمذی، رقم: ٩٧٤)۔"}],[391,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ عامر بن ربیعہ نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی جنازے کو دیکھے تو اگر وہ اس کے ساتھ پیدل چلنے والا نہ ہو تو وہ کھڑا ہو جائے یہاں تک کہ وہ اس کے پیچھے رہ جائے یا اس سے پہلے وہ نیچے رکھ دیا جائے۔“","",{"k":"صحیح بخاری کتاب الجنائز (١٣٠٨)، سنن ابو داؤد (١٣٠٨)۔","f":"یہ حکم منسوخ ہو چکا ہے جیسا کہ سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جنازوں کو دیکھ کر کھڑے ہو جایا کرتے تھے مگر بعد میں بیٹھنے لگ گئے تھے۔ (صحیح مسلم، کتاب الجنائز، رقم: ٩٦٢) معلوم ہوا کہ کھڑے ہونے والا حکم منسوخ ہے۔ شیخ الالبانی ہمالہ کا قول ہے کہ یہ حکم منسوخ ہو چکا ہے۔ (احکام الجنائز: ص ١٠٠) امام مالک، ابوحنیفہ، شافعی یہ اسی کے قائل ہیں۔ (نیل الاوطار: ٢٣/٣)"}],[392,"سیدنا عبداللہ ابن عباس نی اینجا بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص صدقہ کرے، پھر وہ اس صدقے میں لوٹے (یعنی واپس لے لے ) تو اس کی مثال اس کتے کی سی ہے جو قے کرنے کے بعد اسے چاٹ لیتا ہے۔“ یہ حدیث ایوب بن موسیٰ سے صرف عیسی بن جابر الصعید کی ہی روایت کرتے ہیں، اسے روایت کرنے میں ان کا بیٹا اکیلا ہے، ہم نے اسے صرف ابن رشدین سے لکھا ہے۔ مذکورہ حدیث سے معلوم ہوا کہ کسی کے لیے حلال نہیں کہ اپنا دیا ہوا ہد یہ یا صدقہ واپس لے لے۔ کیونکہ واپس لینا، اخلاق و مروت کے منافی ہے۔ علاوہ ازیں کسی کو از خود دے کر اس سے واپس لینا اس کے لیے بے عزتی اور تکلیف کا باعث ہے۔ اس لیے مثال بھی کتے کی دی ہے بلکہ ایسے آدمی کی تمام لوگوں کے سامنے بے عزتی کرنا چاہیے جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جب کوئی ہبہ کرنے والا عطیہ واپس لینے لگے تو اسے برسر عام کھڑا کیا جائے اور جو واپس لے رہا ہو اس کے متعلق پوچھا جائے پھر وہ چیز اسے واپس دے دی جائے۔ (سنن ابی داؤد، کتاب الاجارة، رقم: ٣٥٤٠)","",{"k":"صحیح مسلم (١٦٢٢)، سنن ابو داؤد (٣٥٣٨)۔"}],[393,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی طلب علم نے فرمایا: ” نیک خواب اللہ کی طرف سے ہے، اور غمناک خواب شیطان کی طرف سے ہے۔ ایک خواب وہ ہوتا ہے جو آدمی اپنے آپ سے بیان کرتا ہے ( یعنی اپنے دل کے خیالات ) جب کوئی شخص ناپسندیدہ خواب دیکھے تو اٹھ کر دو رکعت نماز پڑھ لے اور میں خواب میں طوق کو نا پسند کرتا ہوں اور بیڑیوں کو پسند کرتا ہوں کیونکہ یہ دین میں ثابت قدمی ہے۔ اور مومن کا خواب نبوت کے چھیالیس اجزا میں سے ایک جز ہے آخر زمان میں مومن کا کوئی بھی خواب جھوٹا نہ ہو گا۔ اور تم میں سے جو شخص سچ بولنے میں جتنا زیادہ ہو گا اتنا ہی اس کا خواب سچا ہو گا۔“ یہ حدیث از معمر از قتادہ صرف عبید اللہ بن عمرو روایت کرتے ہیں، اسے روایت کرنے میں عبداللہ بن جعفرا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نیک خواب اللہ تعالیٰ کی طرف سے ہوتا ہے، اور برا شیطان کی طرف سے۔ (١) برا خواب جب دیکھا جائے تو اس کی نحوست سے بچنے کے لیے انسان کو تعوذ پڑھتے ہوئے اپنی بائیں طرف تھوکنا اور پہلو بھی بدل لینا چاہیے۔ لیکن افضل یہ ہے کہ جیسا کہ مذکورہ روایت میں بھی ہے کہ اُٹھ کر نماز پڑھے اور خواب کسی سے بیان نہ کرے۔ (٢) معلوم ہوا کہ اگر کوئی آدمی یہ دیکھے کہ میں قید میں ہوں تو یہ اس کے دین پر ثابت قدمی کی دلیل ہے۔ مومن کے خواب کو نبوت کا چھیالیسواں حصہ کہا گیا ہے اور اسی طرح یہ بھی خبر دی گئی ہے کہ قرب قیامت کو مومن کے خواب بچے ہوں گے۔","",{"k":"صحیح بخاری (٣٢٩٢)۔"}],[394,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، تمہارے نبی صلی اللہ علیہ وسلم جب رکوع یا سجدہ میں ہوتے تو یہ دعا پڑھتے: ((سُبحَانَكَ وَبِحَمْدِكَ اَسْتَغْفِرُكَ وَأَتُوبُ اِلَيْكَ)) ”پاک ہے تو (اے اللہ ) اور ساتھ تیری تعریف کے، میں تجھ سے معافی چاہتا ہوں اور تیری طرف تو بہ کرتا ہوں۔“ یہ حدیث حماد سے صرف زید بن ابی انیسہ اور زید سے عبید اللہ بن عمرو ہی روایت کرتے ہیں، اسے روایت کرنے میں عبداللہ بن جعفرا کیلے ہیں اور حضرت ابن مسعود سے یہ حدیث صرف اسی سند سے مروی ہے۔ نبی معظم صلی اللہ علیہ وسلم سے سجدہ اور رکوع کی حالت میں مختلف الفاظ پڑھنے ثابت ہیں۔ بخاری شریف کی روایت کے یہ الفاظ ہیں۔ ((سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)) (صحيح بخارى كتاب التفسير، رقم: ٤٩٦٨) کیونکہ اللہ ذوالجلال نے جب ﴿ إِذَا جَاءَ نَصْرُ اللهِ ﴾ سورت نازل کی تو اس میں یہ حکم دیا تھا فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا ” سوا اپنے رب کی حمد کے ساتھ تسبیح کیجئے اور اس سے استغفار کیجئے بے شک وہ تو بہ قبول کرنے والا ہے، تو نبی معظم صلی اللہ علیہ وسلم نے مذکورہ دعا کو رکوع اور سجدے میں اپنا معمول بنالیا۔ یہ الفاظ دونوں طرح نبی معظم طاے علی تم سے ثابت ہیں: ((سبحانك اللهم بحمدك استغفرك واتوب اليك، سبحانك اللهم ربنا وبحمدك اللهم اغفر لي)) کیونکہ ان دعاؤں میں تسبیح، تحمید اور استغفار تینوں جمع ہیں۔","",{"k":"ابو داؤد، رقم : ٥٠١٩ . المعجم الكبير للطبراني (٤٩٧/٨)، السلسلة الصحيحة (٢٠٨٤)، سنن۔"}],[395,"سیدنا رافع بن خدیج فی اللہ نے بیان کیا، ”رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسے کام سے منع فرمایا جو ہمارے لیے","",{"k":"قال الالباني: صحيح. :، : سنن ترمذی (١٣٨٤)، المعجم الكبير للطبراني۔","f":"مند تھا۔ مگر رسول اللہ صلی اللہ علیہ وسلم کا حکم سر آنکھوں پر ہے۔ آپ نے ہمیں منع فرمایا کہ ہم زمین کی بعض آمدن کے عوض یا چاندی کے عوض زمین قبول کریں۔ اور ہمیں حجام ( کچھنے لگانے والے) کی کمائی سے بھی منع فرمایا۔ یہ حدیث از ابوحصین از مجاہد سے از ابن رافع صرف ابوعوانہ ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن عیسی اکیلے ہیں۔ اسے ابوبکر بن عیاش و غیره از ابوحصین از مجاہد از رافع سے خود روایت کرتے ہیں۔ فائدة مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام مینی بیان میں کس قدر نبی معظم ملنے کی یمن کے مطبع اور فرمانبردار تھے اگر ظاہر طور پر کوئی نقصان بھی نظر آتا تو بھی وہ نبی معظم صلی اللہ علیہ وسلم کی سنت کو اختیار کرتے اور اسی کو یا فائدہ ہی فائدہ سمجھتے تھے۔:٣٩٦ اور لیکوه"}],[396,"رسول اللہ صلی اللہ علیہ وسلم کے غلام سیدنا ثوبان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرا حوض عمان سے بلقا تک وسیع ہوگا، اس کا پانی شہد سے میٹھا، کستوری سے زیادہ خوشبو دار، اور دودھ سے زیادہ سفید ہوگا۔ اس کے پیالے آسمان کے ستاروں کی طرح لاتعداد ہوں گے۔ جس نے ایک دفعہ پی لیا وہ کبھی بھی پیاسا نہ ہو گا۔ اور سب سے پہلے جو لوگ میرے پاس لائے جائیں گے وہ مہاجرین میں سے فقیر لوگ ہوں گے، جو پراگندہ سروں والے میلے کپڑوں والے ہوں گے۔ جو نرم و نازک اور خوشحال عورتوں سے نکاح نہ کریں گے، اور ان کے لیے دروازے بھی نہ کھولے جائیں گے۔“ یہ حدیث عباس بن سالم سے صرف محمد بن مہاجر ہی روایت کرتے ہیں۔ نبی معظم اے علی تم نے فرمایا: ”ہر نبی کے لیے ایک حوض ہے اور تمام انبیا علیواسلام آپس میں ایک دوسرے پر فخر کریں گے کہ کس کے حوض پر پانی پینے والے زیادہ آتے ہیں۔ اور میں امید رکھتا ہوں کہ میرے حوض پر آنے والے سب سے زیادہ ہوں گے۔ (سنن ترمذی، کتاب صفة القيامة، اسناده صحيح) حوض کوثر کی ایک سمت اتنی طویل ہے کہ جتنا عمان سے بلقا ہے۔ ایک روایت میں ہے کہ جتنا مدینہ اور عمان کے درمیان فاصلہ ہے۔ عمان اردن کا دارالخلافہ ہے جو کہ مدینہ منورہ سے ایک ہزار کلومیٹر کے فاصلہ پر ہے۔ یہ بھی معلوم ہوا کہ حوض کوثر پر سونے چاندی کے جام ہوں گے جن کی تعداد آسمان کے تاروں جتنی ہوگی۔ مذکورہ حدیث سے غربا مہاجرین کی عظمت کا بھی ثبوت ملتا ہے۔ اور یہ بھی معلوم ہوا کہ سب سے پہلے آنے والے اور سیراب ہونے والے مہاجر (جنہوں نے نبی معظم طلق علم کے زمانے میں مکہ سے مدینہ ہجرت کی ) فقراء ہوں گے۔","",{"k":"سنن ابن ماجه کتاب الزهد (٤٣٠٣)، سنن ترمذی (٢٢٤١)، قال سَالِمٍ الالبانی: صحیح۔"}],[397,"سیدنا ابو الدرداء رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایسا نہ ہو کہ تم میں سے کسی کے متعلق مجھ سے حوض پر جھگڑا کیا جائے تو میں کہوں یہ میرے ساتھیوں میں سے ہے تو مجھے کہا جائے گا: آپ کو معلوم نہیں کہ آپ کے بعد انہوں نے کیا بدعات جاری کی تھیں۔ سیدنا ابو الدرداء نے کہا: یا رسول اللہ نے یکم! دعا کریں کہ اللہ تعالیٰ مجھے ایسے لوگوں میں نہ کرے۔ آپ نے فرمایا: تم ان میں سے نہیں ہو۔“ یہ حدیث مسلم بن مشکم سے صرف یزید بن ابی مریم ہی روایت کرتے ہیں۔ پلٹیں گے۔ فائد مذکورہ حدیث سے معلوم ہوا کہ بدعتی لوگ نبی معظم ملنے کے حوض سے محروم واپس کیونکہ یہ وہ نام نہاد مسلمان ہوں گے جنہوں نے دین میں نئی نئی بدعات نکال کر دین کا حلیہ بگاڑ دیا تھا مجالس مولود، مروجه نتیجه، فاتحہ، قبر پرستی اور عرس کرنے والے، تعزیہ پرستی کرنے والے، اولیاء اللہ کے مزارات کو مثل مساجد بنانے والے مکار قسم کے پیر فقیر، مرشد و امام، یہ سارے لوگ اس حدیث کے مصداق ہیں۔ ظاہر سے مسلمان نظر آتے ہیں لیکن اندر سے شرک و بدعات میں غرق ہو چکے ہیں پس بدعات سے بچنا ہر مخلص مسلمان کے لیے ضروری ہے۔ اللہ تعالیٰ ہمیں بدعات سے محفوظ فرمائے۔ (آمین)","",{"k":"١١٠١ يزيد بن ابي مريم . المعجم الكبير للطبراني (٢٥٥/٢٠)، اسناده صحیح۔"}],[398,"سیدنا عبداللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عنقریب تم پر کچھ امراء ہوں گے وہ جو کچھ جانتے ہیں اس کے مطابق عمل کریں گے اور وہ ایسے کام کریں گے جن کا انہیں حکم کیا جاتا ہے اور ان کے بعد ایسے امراء ہوں گے جو ایسے اعمال کریں گے جنہیں وہ نہیں جانتے اور ایسے کام کریں گے جن کا انہیں حکم نہیں دیا جائے گا۔ جس نے ان کا انکار کیا وہ سلامت رہے گا مگر وہ شخص جو راضی ہوا اور ان کے پیچھے لگ گیا ( تو وہ تباہ ہو گیا )۔“ یہ حدیث از اوزاعی از زہری، سالم سے صرف مسلمہ ہی روایت کرتے ہیں، اور معافی بن عمران و غیره از اوزاعی از ابراهیم بن مره از زهری از ابی سلمہ سے روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جائز کاموں میں حکمرانوں کی اطاعت ضروری ہے اور ناجائز کاموں میں ان کی اطاعت حرام ہے۔ جیسا کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان مرد پر (اپنے مسلمان حکمران کی بات) سننا اور ماننا فرض ہے وہ بات اسے پسند ہو یا ناپسند، مگر یہ کہ اسے گناہ کرنے کا حکم دیا جائے۔ پس جب اسے اللہ کی نافرمانی کا حکم دیا جائے تو پھر اس پر سننا اور ماننا فرض نہیں ( بلکہ انکار ضروری ہے)۔ (صحیح بخاری، کتاب الاحكام، رقم: ٧٢٠٢)",""],[399,"سیدنا عبادہ بن صامت فنی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: دستم میں جو شخص فوت ہو جائے اور اس کے لیے اللہ کے پاس خیر ہو تو وہ پسند نہیں کرتا کہ وہ تمہاری طرف واپس جائے چاہے اسے پوری دنیا دے دی جائے مگر شہید وہ پسند کرتا ہے کہ وہ دوبارہ جائے اور دوبارہ قتل ہو جائے۔“ یہ حدیث زید بن واقد سے صرف ہیثم بن حمید ہی روایت کرتے ہیں۔","",{"k":"السلسلة الصحيحة (٥/٢٢٧، ٢٢٢٨)، سنن نسائی (٣١٥٩)۔","f":"(١) معلوم ہوا کہ دنیوی نعمتوں کی آخرت کے مقابلے میں کچھ حیثیت نہیں ہے۔\n(٢) جو لطف شہادت میں ہے وہ جنت کی نعمتوں میں بھی نہیں۔ ٤٠٠"}],[400,"سیدنا ابو کبشہ انماری بنی اللہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی غزوہ میں روانہ ہوئے تو ہم نے ایک جگہ پڑاؤ ڈالا ہم وہاں آپ کے پاس گئے تو آپ نے اپنے ہاتھ اٹھائے اور فرمایا: ایمان اور حکمت اس طرف تخم اور جذام کی طرف ہے۔ یہ حدیث از عروہ بن رویم از ابو کبشہ صرف محمد بن مہاجر ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٦/٢٠٠)، مجمع الزوائد (٥٦/١٠)، فيه عروة بن رويم اللخمي وهو ضعيف۔"}],[401,"حیان ابو النضر کا بیان ہے، میں سیدنا واثلہ بن استقع علی ای کو ملا تو انہوں نے کہا: میں نے رسول اللہ علیم سے سنا آپ فرما رہے تھے اللہ عزوجل فرماتا ہے میں اپنے بارے میں اپنے بندے کے گمان کے پاس ہوتا ہوں اگر اچھا گمان کرے گا تو اچھا ہو گا اگر برا کرے گا تو برا ہوگا۔“ یہ حدیث یزید بن عبیدہ سے صرف محمد بن مہاجر ہی روایت کرتے ہیں۔","",{"k":"ور ل و ه و ور صحیح مسلم، مسند احمد (٤/١٠٦)۔","f":"مذکورہ حدیث سے معلوم ہوا انسان اللہ تعالیٰ کے متعلق جیسا گمان رکھتا ہے اللہ رب العزت بھی اس کے ساتھ ویسا ہی معاملہ فرماتے ہیں لہذا انسان کو اللہ تعالیٰ کے متعلق اچھا گمان رکھنا چاہیے۔"}],[402,"سیدنا عتبہ بن عبد السلمی نے بیان کیا، ایک اعرابی رسول اللہ نیم کے پاس آیا تو اس نے عرض کیا، آپ کا حوض کیسا ہے جس کے متعلق آپ بیان کرتے ہیں؟ آپ نے فرمایا: ”جتنا بیضاء سے بصری تک فاصلہ ہے اللہ تعالیٰ جنت کے پانی سے میری مدد کرے گا کوئی انسان نہیں جانتا کہ کس سے پیدا ہوا اور اس کے دونوں کنارے کہاں ہیں تو سیدنا عمر رضی اللہ عنہ نے اللہ اکبر کہا، تو آپ نے فرمایا: ” حوض پر فقراء مہاجرین جائیں گے جو اللہ کی راہ میں لڑائی کرتے ہیں اور اللہ کی راہ میں انہیں موت آ جاتی ہے تو مجھے امید ہے اللہ تعالیٰ مجھے پانی کا کنارہ دے دے کہ میں وہاں سے پانی پی لوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے رب نے مجھے سے وعدہ کیا ہے کہ وہ میری امت سے ستر ہزار آدمی حساب کے بغیر جنت میں داخل کرے گا، پھر ہر ہزار ستر ہزار کی سفارش کرے گا۔ پھر میرا رب تین مٹھیاں بھر کر نکالے گا تو سیدنا عمر رضی اللہ عنہ نے اللہ اکبر کہا، ” اور فرمایا پہلے ستر ہزار جو ہوں گے اللہ تعالیٰ نے ان کی سفارش ان کی اولاد، آباء اور قبیلوں کے متعلق قبول فرمائے گا اور مجھے امید ہے کہ میں ان مٹھیوں میں سے کسی مٹھی کے آخر میں ہوں گا۔ ایک اعرابی نے پوچھا: یا رسول اللہ صلی اللہ علیہ وسلم! وہاں پھل بھی ہوگا؟ آپ نے فرمایا: ”ہاں اور اس میں ایک درخت ہو گا جس کو طوبی کہیں گے وہ جنت الفردوس کے مطابق ہوگا تو اس نے پوچھا: ہمارے کس درخت کے مشابہ ہو گا؟ آپ نے فرمایا: ” تیری زمین کے کسی درخت کے مشابہ نہیں ہو گا لیکن کیا تم شام گئے ہو؟“ اس نے کہا: نہیں بلکہ وہ شام کے ایک درخت کے مشابہ ہو گا جس کو جوزہ کہتے ہیں ایک تنے سے پیدا ہوتا ہے پھر اس کا اوپر والا حصہ پھیل جاتا ہے اس نے کہا: اس کے تنے کا موٹا پا کتنا ہو گا؟ تو آپ نے فرمایا: ”اگر تیرے گھر کا جوان اونٹ چلنے لگے تو چلتے چلتے اس کی ہنسلی کی ہڈی بڑھاپے سے ٹوٹ جائے تو پھر بھی اس کا موٹاپا اور بڑائی ختم نہ ہو۔“ اس نے پوچھا: یا رسول اللہ صلی اللہ علیہ وسلم! وہاں انگور بھی ہیں؟ آپ فرمایا: ”ہاں! اس نے پوچھا اس کے خوشے کتنے بڑے بڑے ہوں گے؟ آپ نے فرمایا: اتنی مسافت که سیاه وسفید رنگ والا کوا ایک مہینہ مسافت چلتا رہے تو وہ نہ پھرے اور نہ تھکے پھر بھی اس کی بڑائی ختم نہ کر سکے تو اس نے پوچھا: اس کا ایک دانہ کتنا بڑا ہو گا؟ آپ نے پوچھا: ” کیا تیرے باپ نے اپنی بکریوں میں کوئی بڑی چیز ذبح کی۔“ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ”اس کا چمڑا اتار کر تیری ماں کو دیا کہ اس کو دباغت دے دے اور پھر اس کو پھاڑ کر ہمارے لیے ڈھال بنا ہم اس سے اپنے مویشیوں کو پانی پلائیں۔ اس نے کہا: جی ہاں! تو انہوں نے کہا: پھر تو یہ مجھ کو اور میرے گھر والوں کو سیر کر دے گا۔ نبی میم نے فرمایا اور تیرے قبیلے کے عام لوگوں کو بھی کافی ہوگا۔ یہ حدیث عقبہ بن عبد سے زید بن سلام کی حدیث کے علاوہ روایت نہیں کی گئی اور نہ زید سے معاویہ بن سلام اور یحیی بن ابی کثیر کے سوا کسی نے روایت کی۔","",{"k":"كر المعجم الكبير للطبراني (٥٦/١٢، ١٣٧٥٩)، مجمع الزوائد (٤١٣/١٠)۔"}],[403,"سیدنا ابو امامہ باہلی رضی اللہ عنہ نے بیان کیا کہ ایک آدمی نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا آدم علینام نبی تھے؟ تو آپ نے فرمایا: ”ہاں“ انہوں نے پوچھا: ان کے اور نوح علی سلام کے درمیان کتنا عرصہ ہوا تھا؟ آپ نے فرمایا: ” بیس قرن ( زمانہ “ اس نے پوچھا نوح علیل نام اور ابراہیم علینا) کے درمیان کتنی مدت ہوئی؟ آپ نے فرمایا: ”دس قرن گزرے تھے۔“ اس نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! کتنے رسول ہوئے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” تین سو پندرہ رسول ہوئے ہیں۔“ یہ حدیث ابو امامہ سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے والے معاویہ بن سلام اکیلے ہیں۔ ٤٠٤","",{"k":"مجمع الزوائد (١/١٩٦)، مستدرك حاكم (٢/٢٨٨)، صحیح ابن حبان (٦١٩٠)، قال الشيخ شعيب الأرناؤط، سندہ صحیح۔"}],[404,"ابو سعید انماری رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلے علی یتیم نے فرمایا: ”میرے رب نے مجھ سے یہ وعدہ کیا کہ وہ میری امت میں سے ستر ہزار افراد کو حساب کے بغیر جنت میں داخل کرے گا۔ اور ہر ہزارستر ہزار کی سفارش کرے گا پھر میرا رب تین لہیں اپنی ہتھیلی سے (سے بھر کر باہر نکالے گا )۔‘، قیس نے کہا: میں نے ابوسعید سے پوچھا: کیا تم نے خود یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے؟ انہوں نے کہا: ہاں! اپنے کانوں سے سنی اور میرے دل نے اس کو یاد کر رکھا ہے۔ ابوسعید کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اور یہ اگر اللہ تعالیٰ نے چاہا تو آپ کی امت کے تمام مہاجرین اس میں آجائیں گے اور باقی کو اللہ تعالیٰ ہمارے دیہاتیوں سے پورا کرے گا۔“ یہ حدیث ابوسعید الا نماری سے اسی سند سے روایت ہے،اسے روایت کرنے میں معاویہ بن سلام اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ امت محمدیہ صلے علیم کے ستر ہزار افراد بلا حساب و کتاب جنت میں داخل ہوں گے۔ یہ بھی معلوم ہوا کہ ہر ہزار کے ساتھ مزید ستر ہزار جنت میں داخل ہوں گے۔ یہ بھی معلوم ہوا کہ مز ید اللہ تعالیٰ تین بھرے ہوئے لپ (جن کی تعداد اللہ تعالیٰ ہی جانتے ہیں ) بھی جنت میں بھیجیں گے۔ مذکورہ حدیث سے جہمیہ کا رد ہوتا ہے جو کہ حثیات کے منکر ہیں۔ ٤٠٥","",{"k":"کر سنن ترمذى (٢٤٣٧)، صحیح ابن ماجه (٤٢٨٦)، مجمع الزوائد (٤٠٩/١٠)۔"}],[405,"سیدنا عبد اللہ بن فروخ نے سیدہ عائشہ رضی یا لوبیا سے سنا، وہ یہ حدیث بیان کر رہی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بنی آدم میں سے ہر انسان تین سو ساٹھ جوڑوں پر پیدا ہوا۔“ مذکورہ روایت سے معلوم ہوا کہ ہر انسان کے (٣٦٠) جوڑ ہیں۔","",{"k":"صحيح مسلم (١٠٠٧)، المعجم الكبير للطبراني (١٢٤/٩)۔","f":"مفصل روایت مسلم شریف میں اس طرح ہے: سیدنا ابو ہریرہ یا اللہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر روز جب آفتاب نکلتا ہے تو ہر آدمی کے ایک ایک جوڑ پر صدقہ واجب ہوتا ہے دو آدمیوں کے درمیان انصاف کر دینا بھی صدقہ ہے، کسی کی مدد کر دینا، کسی کو سواری پر چڑھا دینا یا اس کا مال سواری پر رکھوا دینا یہ بھی صدقہ ہے۔“ (صحیح مسلم، رقم: ١٠٠٩) دوسری مسلم شریف کی روایت میں اس طرح ہے: سیدنا ابو ذر علی اہلیہ سے روایت ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” تم میں سے ہر آدمی اس حال میں صبح کرتا ہے کہ اس کے ذمے اس کے ہر جوڑ پر صدقہ ہوتا ہے۔ سبحان اللہ کہنا صدقہ ہے، الحمد للہ کہنا صدقہ ہے، لا الہ الا اللہ کہنا صدقہ ہے، اللہ اکبر کہنا صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، برائی سے روکنا صدقہ ہے اور ان کے مقابلے میں چاشت کی دورکعتیں بھی کفایت کر جاتی ہیں جو کوئی انہیں ادا کرتا ہے۔ (صحیح مسلم، کتاب صلاة المسافرين، رقم: ٧٢٠) معلوم ہوا کہ چاشت کی دور کعتیں ادا کر لینے سے تمام جوڑوں کا صدقہ ادا ہو جاتا ہے"}],[406,"سیدنا عبد اللہ بن عمر اور سیدنا ابو ہریرہ ضلی اینجا نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے۔ لوگ جمعے ترک کرنے سے باز آجائیں ورنہ اللہ تعالیٰ ان کے دلوں پر مہر کر دے گا، پھر وہ غافلوں میں سے ہو جائیں گے۔“ ٤٠٧","",{"k":"صحیح مسلم (٨٦٥)، صحيح الجامع الصغير (٥٤٨٠)، مستدرك حاكم (٢/٩٣، ٢٤٣٣)۔"}],[407,"سیدنا سہل بن حنظلیہ سے روایت ہے کہ غزوہ حنین کے موقع پر وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے تو انہوں نے لمبا سفر کیا یہاں تک کہ شام ہو گئی اور نماز کا وقت ہو گیا، تو ایک گھوڑ سوار آیا اور کہنے لگا: یا رسول اللہ مطلعے علم میں آپ کے آگے آگے چلتا گیا ہوں یہاں تک کہ فلاں فلاں پہاڑ پر چڑھ گیا تو میں بنو ہوازن کے پاس پہنچ گیا وہ سارے کے سارے آچکے تھے وہ اپنی عورتوں، اونٹوں اور بکریوں ہ ا سمیت حسنین کے مقام پر جمع ہو گئے ہیں۔ پس رسول اللہ ملنے لیے یکم مسکرائے اور فرمانے لگے: ” یہ سب کی سب چیزیں ان شاء اللہ مسلمانوں کی قیمتیں ہوں گی۔ پھر فرمایا: ” آج رات کون ہمارا پہرہ دے گا؟“ انس بن ابی مرثد غنوی بھی اللہ نے کہا: یا رسول اللہ! یہ کام میں کروں گا۔ تو آپ نے فرمایا: ”سوار ہو جا تو وہ اٹھے ایک گھوڑے پر سوار ہو گئے۔ اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے انہیں فرمایا: ”اس گھائی کی طرف جاؤ یہاں تک کہ اس اوپر والی جانب پر پہنچ جاؤ۔ ایسا نہ ہو کہ رات میں ہم تمہاری طرف سے دھوکہ کھا جائیں، جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم اپنی نماز کی جگہ کی طرف گئے تو دو رکعت نماز پڑھی، پھر فرمایا: ”کیا تم نے اپنا سوار دیکھا؟“ ایک آدمی نے کہا: یا رسول اللہ! ہم نے اسے محسوس نہیں کیا، پھر نماز کے لیے تکبیر کہی گئی تو نبی ملنے یہ نماز میں گھائی کی طرف توجہ کرنے لگے، جب آپ نے نماز پوری کی اور سلام پھیرا تو فرمایا: ” خوش ہو جاؤ۔ تمہارا سوار واپس آ گیا“ تو ہم بھی درختوں میں سے گھائی کی طرف دیکھنے لگے۔ دیکھا کہ واقعتا وہ آ پہنچا یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آکر کھڑا ہو گیا، اور کہنے لگا: میں جاتا رہا حتی کہ اس وادی کے اوپر والی جانب پہنچ گیا جہاں کا مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا جب صبح ہوئی تو میں دونوں گھاٹیوں پر چڑھا میں نے دیکھا مجھے کوئی بھی نظر نہیں آیا۔ تو رسول الله ملل علیم نے فرمایا: ” تو نے جنت واجب کر لی اب اس کے بعد تو کوئی عمل نہ کرے تو پھر بھی کوئی حرج نہیں۔“ یہ حدیث اس اسناد کے علاوہ روایت نہیں کی گئی، معاویہ بن سلام اس کو روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ","",{"k":"سنن ابو داؤد (٢٥٠١)، السلسلة الصحيحة (١/٣٧٧، ٣٧٨)۔","f":"(١) جہادی مہموں اور دیگر اہم مواقع پر پہرے کا انتظام حسب ضرورت مشروع ومسنون بلکہ واجب ہے اور تو کل کے خلاف نہیں۔\n(٢) نماز کے دوران بلاوجہ التفات ممنوع ہے مگر اہم ضرورت کے پیش نظر مباح ہے مگر اس بات کا خیال رہے کہ منہ پھیر کر نہ دیکھا جائے۔\n(٣) صحابی رسول نے، فرمان رسول کے ظاہر الفاظ پر اس شدت سے تعمیل کی کہ ساری رات گھوڑے کی پیٹھ پر گزار دی۔ ٤٠٨"}],[408,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ''جس نے ہر مہینے میں تین دفعہ صبح کے وقت شہد چاٹ لیا تو اس کو کوئی بڑی مصیبت نہیں پہنچے گی","",{"k":"سنن ابن ماجه (٣٤٥٠)، ضعيف الجامع الصغير (٥٨٣١)۔"}],[409,"سیدنا علی ضیا اہلیہ سے روایت ہے کہ نبی صلی علی ایم نے فرمایا: ”جس نے اللہ کی راہ میں گھوڑا باندھا تو اس کا چارہ اور اس کا چلنا پھرنا قیامت کے روز اس کے اعمال کے ترازو میں رکھا جائے گا۔“ مذکورہ حدیث میں مجاہدین کے گھوڑوں کی فضیلت کا تذکرہ ہے۔ بخاری شریف میں اس طرح حدیث ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اللہ پر ایمان رکھتے اور اس کے وعدے کی تصدیق کرتے ہوئے، اللہ کی راہ میں گھوڑا پالا، تو یقیناً اس کی گھاس، اس کی سیرابی، اس کی لید اور اس کا پیشاب، قیامت والے دن اس کے پلڑے میں ہوگا۔ (صحیح بخاری، کتاب الجهاد، رقم: ٢٨٥٣) معلوم ہوا کہ گھوڑے کی مذکورہ تمام چیزیں، نیکیاں بن جائیں گی اور گھوڑا پالنے والے کے اعمال میں شامل ہو کر ترازو میں تو لی جائیں گی۔ جہاد فی سبیل اللہ کے لیے گھوڑوں کو تیار رکھنا بڑی فضیلت والا عمل ہے خود اللہ تعالیٰ نے مجاہدین کے گھوڑوں کی قسمیں اٹھائی ہیں۔ ارشاد فرمایا: وَالْعَدِيتِ ضَبْحًا فَالْمُورِيتِ قَدْحًا فَالْمُغِيرَتِ صُبْحًاهِ فَأَثَرْنَ بِهِ نَفْعًاهِ فَوَسَطْنَ بِهِ جمعان (العاديات: ١ تا ٥) د ختم ہے ان ( گھوڑوں) کی جو پیٹ اور سینے سے آواز نکالتے ہوئے دوڑنے والے ہیں، پھر جوسم مار کر چنگاریاں نکالنے والے ہیں، پھر جو صبح کے وقت دھاوا بولتے ہیں، پھر اس کے ساتھ غبار اڑاتے ہیں، پھر اس کے ساتھ کسی جماعت کے درمیان جا گھستے ہیں۔“ ٤١٠","",{"k":"صحيح الجامع الصغير (٣٣٥٠)، المعجم الكبير للطبراني (١/٤١٥، ٤١٦)۔"}],[410,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ ملے عام نکلے تو آپ تعلیم کے سامنے ایک اعرابی آیا، اس نے عرض کیا، قیامت کب آئے گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” تو نے اس کے لیے کیا تیاری کر رکھی ہے؟“ اس نے کہا: میں نے تو ایسی کوئی تیاری نہیں کی جس پر میں اپنی تعریف کر سکوں صرف اتنی بات ہے کہ میں اللہ تعالیٰ اور اس کے رسول الے ان سے محبت رکھتا ہوں۔ تو آپ نے فرمایا: ” تو اس شخص کے ساتھ ہو گا جس سے تو محبت کرتا ہے۔ حضرت انس سے یہ حدیث ابو اصلیح کے علاوہ اور کوئی روایت نہیں کرتا ہے۔","",{"k":"تقدم تخريجه، انظر (١٠٧)۔"}],[411,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی سے تم نے فرمایا: جس رات مجھے معراج کرائی گئی، میں نے دیکھا کہ کچھ لوگوں کی زبانیں آگ کی قینچیوں سے کائی جا رہی ہیں میں نے کہا: جبرائیل یہ کون لوگ ہیں؟“ انہوں نے کہا: ”یہ آپ کی امت کے خطیب ہیں جو لوگوں کو ان باتوں کا حکم دیتے جو خود نہیں کرتے تھے۔“ یہ حدیث سلیمان تیمی سے صرف عیسی بن یونس ہی روایت کرتے ہیں۔","",{"k":"السلسلة الصحيحة (١/٢٩٠، ٢٩١)، صحيح الجامع الصغير (١٢٩)، مسند احمد (٣/١٨٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ بے عمل خطبا کا انجام نہایت ہی برا ہوگا۔ اللہ تعالیٰ ہم کو اس انجام سے محفوظ فرمائے۔ معلوم ہوا کہ دائی جو کہے اس کے مطابق عمل ہونا چاہیے۔ اگر عمل نہ کرے گا تو یہ اللہ تعالیٰ کی ناراضگی کا سبب ہے۔ جیسا کہ ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ، كَبُرَ مَقْتًا عِنْدَ اللهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ﴾ (الصف: ٢تا٣) ”اے ایمان والو! تم ایسی بات کیوں کہتے ہو جس پر خود عمل نہیں کرتے ہو، یہ بات اللہ کو بہت ہی زیادہ ناپسند ہے کہ تم وہ بات کہو جس پر خود عمل نہیں کرتے۔“ ٤١٢"}],[412,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن کا ازار نصف پنڈلیوں تک ہونا چاہیے۔ اس (نصف پنڈلی) کے اور ٹخنوں کے درمیان تک کوئی گناہ نہیں اور جو ٹخنوں سے نیچے ہو گا وہ آگ میں ہو گا۔“ یہ حدیث نعیم مجمر سے صرف علاء بن عبد الرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں زید بن ابی انیسہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ چادر شلوار ٹخنوں کے اوپر رکھنی چاہیے۔ ٤١٣","",{"k":"سنن ابن ماجه (٥٥٧٣)، صحيح الجامع الصغير (٩١٩)۔"}],[413,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرا لہو و لعب سے کوئی تعلق ہے نہ لہو ولعب مجھ سے کوئی تعلق ہے۔“ یہ حدیث عمرو بن ابی عمرو سے صرف ابوز کیر ہی روایت کرتے ہیں۔","",{"k":"الادب المفرد للبخاری (٧٨)، المعجم الكبير للطبراني (٢٦٣/١٤)، رقم : ١٦١٥٢ قال الالباني صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ باطل چیزیں نبی معظم ملنے کو ناپسند تھیں، امام بخاری اللہ نے ادب المفرد میں اس باب کے تحت اس حدیث کو نقل فرمایا کہ ((باب الغناء واللهو)) ”باب، گانا اور کھیل۔ مذکورہ حدیث سے معلوم ہوا کہ نبی معظم ملنے ان کو فضول کاموں، لایعنی چیزوں، اور ناجائز وفضول کھیلوں سے سخت نفرت تھی اور ایک مسلمان کو بھی ان چیزوں سے بچنا چاہیے۔ ٤١٤"}],[414,"سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے مجھے اور سیدنا معاذ بن جبل خلال اللہ کو یمن کی طرف بھیجا تو میں نے کہا: یا رسول اللہ ملنے میرینم! ہمیں کوئی وصیت فرما ئیں تو آپ ملنے یا تم نے فرمایا: ”آپس میں اتفاق رکھنا، اختلاف نہ کرنا، آسانی پیدا کرنا مشکل میں نہ ڈالنا۔“ یہ حدیث زھیر سے صرف عمر و بن عثمان ہی روایت کرتے ہیں۔ ভ مذکورہ حدیث سے معلوم ہوا کہ حکمرانوں کو اپنی رعایا سے گھل مل کر رہنا چاہیے، کوئی ایسا کام نہ کرنا چاہیے جس سے امت میں اختلاف ہو۔ لوگوں کے لیے شرعی دائرہ کے اندر ہر ممکن آسانی پیدا کرنا بختی کے ہر پہلو سے بچنا یہ قیمتی ہدایات ہیں جن کا ہر عالم، مبلغ، خطیب، مدرس، مرشد، ہادی کے پیش نظر رہنا ضروری ہیں۔ ٤١٥","",{"k":"صحیح بخاری، صحيح مسلم (١٧٣٣)۔"}],[415,"سيدنا وائل بن حجر فضل اللہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ نے رکوع کیا تو آپ نے اپنے ہاتھ اپنے گھٹنوں پر رکھے۔ یہ حدیث از عاصم بن کلیب از حضرت عبدالجبار بن وائل صرف ابوعوانہ ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن عیسی اکیلے ہیں۔","",{"k":"صحیح . سنن ابو داؤد (٧٣٤)، قال الالباني۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رکوع میں اپنی ہتھیلیوں کو گھٹنوں پر رکھنا چاہیے، مختلف احادیث میں اس کی کیفیت بتلائی گئی ہے۔ جیسا کہ رسول اللہ سے ہم نے میں الصلاہ کو حکم دیا کہ حالت رکوع میں ہتھیلیوں کو گھٹنوں پر رکھو اور انگلیوں کے درمیان فاصلہ کرو۔ (صفة صلاة النبي صلی اللہ علیہ وسلم: ص: ١٣٠) (٢) رسول اللہ صلے عام حالت رکوع میں گھٹنوں کو مضبوطی سے پکڑ لیتے اور اپنی کہنیاں پہلوؤں سے دور رکھتے تھے۔ (صحیح ترمذی، رقم: ٢١٤) (٣) نبی معظم صلی اللہ علیہ وسلم جب رکوع کرتے تو اپنی انگلیوں کے درمیان فاصلہ کرتے"}],[416,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ سے تم نے فرمایا: ”جو شخص گمراہی کے جھنڈے تلے مارا جائے جبکہ وہ عصبیت کی بنیاد پر جنگ کرتا ہے یا عصبیت کی بنیاد پر مدد کرتا ہے تو اس کی موت جاہلیت کی موت ہے۔ یہ حدیث سوید بن حجر سے صرف حجاج بن حجاج الباہلی ہی روایت کرتے ہیں، اسے روایت کرنے میں قرعہ بن سویدا کیلے ہیں۔","",{"k":"صحیح مسلم (١٨٥٠)، سنن نسائی (٤١١٤)، سنن ابن ماجه (٣٩٤٨)۔"}],[417,"سیدہ ام سلمہ بنا یا بیان کرتی ہیں کہ ان کی ایک بکری تھی جس کا وہ دودھ دھوتی تھیں۔ نبی صلی اللہ علیہ وسلم نے اسے نہ دیکھا تو اس کے متعلق ام سلمہ نبی اشیا سے دریافت کیا: ام سلمہ نے کہا: یا رسول اللہ الے ایل این وہ مرگئی ہے، آپ نے فرمایا: ” تو تم نے اس کے چمڑے سے","",{"k":"سنن دار قطنی (٤٩/١، ٢٨)، نصب الرايه (٢٤٠/١٢)، اسناده ضعيف، فيه فرج بن فضاله و هو ضعيف۔","f":"کیوں نہیں اٹھایا؟“ انہوں نے کہا: یا رسول اللہ علیم! وہ مردار ہو گئی تھی۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ” اس کا رنگنا اس کو پاک کر دیتا ہے جس طرح شراب کا سرکہ بنانا اسے حلال کر دیتا ہے۔“ یہ حدیث یحیی بن سعید سے صرف فرج بن فضالہ ہی روایت کرتے ہیں۔ تاہم اگر حلال جانور مردار ہو جائے تو اس کا چمڑا رنگنے سے پاک ہو جاتا ہے جیسا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرماتے تھے: ”چھڑے کو جب رنگ لیا جائے تو وہ پاک ভ ہو جاتا ہے۔(صحیح مسلم، کتاب الحيض: ٣٦٦، سنن ابی داؤد، رقم: ٤١٢٣)"}],[418,"سیدنا زارع سے روایت ہے جو وفد عبد القیس میں تھے۔ انھوں نے کہا جب ہم مدینے میں آئے تو ہم جلدی جلدی اپنی سواریوں سے اترنے لگے تاکہ نبی صلی اللہ علیہ وسلم کے ہاتھوں اور پاؤں کو چومیں اور منذر الاشج انتظار کرنے لگا تو وہ چمڑے سے بنے ہوئے اپنے تھیلے کی طرف گیا وہاں سے لباس پہنا، پھر نبی الے علم کے پاس آیا تو نبی صلی اللہ علیہ وسلم نے اسے فرمایا: ”تجھ میں دو خو بیاں ہیں جنہیں اللہ تعالیٰ پسند کرتا ہے بردباری اور عدم مبلت۔‘ منذر نے کہا: تمام تعریفیں اس اللہ کے لیے ہیں جس نے مجھے ایسی دو خصلتوں پر پیدا کیا جنہیں وہ اور اس کا رسول پسند کرتے ہیں۔“ یہ حدیث ام ابان سے صرف مطر بن عبد الرحمن ہی روایت کرتے ہیں۔ مذکورہ روایت میں شیخ البانی ملالہ کے نزدیک پاؤں کا ذکر صحیح نہیں۔","",{"k":"سنن ابو داؤد (٥٢٢٥)، قال الالبانی، حسن دون ذكر الرجلين، السنن الكبرى للبيهقي (١٠٢/٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حوصلہ مند اور باوقار انسان کو جلد بازی زیب نہیں دیتی۔ اچھی عادتیں فطری ہوں تو اللہ عزوجل کی حمد کرنا چاہیے اور ان پر کار بند رہنا چاہیے۔ اگر اچھی عادتیں نہ ہوں تو انسان کو اچھی عادتوں کو اپنانے کی کوشش کرنی چاہیے۔ ان علماء و مبلغین کے لیے بھی غور کا مقام ہے جو سختیوں اور نفرتوں کے پیکر ہیں۔ هداهم الله"}],[419,"ایک آدمی سیدنا عبداللہ ابن عمر رضی اللہ عنہما کے پاس آیا تو ان سے اس آیت کے متعلق سوال کیا: ﴿وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ ” یعنی ان سے اس وقت تک جنگ کرو یہاں تک کہ فتنہ نہ رہے۔ تو سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے کہا: ”بے شک ہم نے نبی ملل علم کے ساتھ ہو کر اس وقت تک جنگ کی که فتنہ باقی نہ رہا پس تو اور تیرے ساتھی جائیں اور اس وقت تک جنگ کرو کہ فتنہ پیدا ہو۔“ یہ حدیث میمون بن مہران سے صرف ابو اصیح ہی روایت کرتے ہیں۔","",{"k":"کر صحیح بخاری (٤٦٥٠)، صحيح مسلم۔","f":"بخاری شریف میں مفصل روایت آتی ہے۔ جس میں اس آدمی کا نام بھی مذکور ہے۔ یہ حبان یا علاء بن عرار نامی تھا۔ (دیکھئے بخاری، رقم: ) اس نے کہا کہ تم اس آیت کے بموجب ﴿وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ تم (سیدنا علی اور معاویہ نی الجھا دونوں سے ) کیوں نہیں لڑتے تو سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے فرمایا کہ وہ تو کافروں کے ساتھ تھی موجودہ جنگ خانگی ہے، ہم اللہ کے دین کے لیے کافروں سے لڑائی کرتے ہیں تا کہ ان کا غرور ٹوٹ جائے اور مسلمان ان کی ایذا سے محفوظ رہیں اور تم دنیا کی سلطنت اور حکومت حاصل کرنے کے لیے لڑ رہے ہو۔ یہ تو آپ کی جنگ ہے اس سے تو مزید فتنہ برپا ہوگا۔"}],[420,"سیدنا جابر بن عبد اللہ فی اللہ نے بیان کیا، عقیل بن ابی طالب نے غزوہ موتہ میں ایک آدمی سے مقابلہ کیا تو اس کو قتل کر ڈالا تو رسول اللہ ملتے سی ایم نے ان کو اس کی انگوٹھی اور اس کا ساز و سامان انہیں عطا فرما دیا۔“ یہ حدیث ابن عقیل سے صرف شریک ہی روایت کرتے ہیں، اسے روایت کرنے میں اسماعیل بن عبداللہ بن زرارہ اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم امیر کسی آدمی کو اس کی اچھی کارکردگی پر انعام دے سکتا ہے جیسا کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک دستے میں روانہ کیا تو ہمارے حصے میں بارہ بارہ اونٹ آئے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایک اونٹ مزید بطور نفل عنایت فرمایا۔ (صحیح مسلم، رقم: ١٧٤٩، سنن ابی داؤد، رقم: ٢٧٤٥) ٤٢١","",{"k":"٤٢٠ مجمع الزوائد (٣٣١/٥)، اسناده ضعيف۔"}],[421,"سيدنا نعمان بن بشیر رضی اللہ عنہما بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے منبر کے پاس تھا تو ایک شخص کہنے لگا: اسلام کے بعد اگر میں حاجیوں کو پانی پلاتا رہوں اور اس کے سوا کوئی عمل بھی نہ کروں تو مجھے کوئی پرواہ نہیں۔ دوسرے نے کہا: اگر میں اسلام کے بعد مسجد حرام کو آباد کرنے کے علاوہ کوئی عمل بھی نہ کروں تو مجھے کوئی پروانہیں۔ ایک اور شخص نے کہا: جو کچھ تم نے کہا: اللہ کی راہ میں جہاد کرنا اس سے بہتر ہے۔ تو انہیں سیدنا عمر بنی اللہ نے ڈانٹا اور فرمایا: تم منبر رسول ملے کے پاس آواز بلند کرتے ہو ایسا نہ کرو۔ وہ دن جمعے کا تھا جب میں نے جمعے کی نماز پڑھ لی تو اندر گیا اور جس میں تم نے اختلاف کیا اس کے متعلق آپ صلی اللہ علیہ وسلم سے مسئلہ پوچھا تو اللہ تعالیٰ نے یہ آیت نازل فرمائی: ﴿اَجَعَلْتُمْ سِقَايَةَ الْحَاجِ وَعِمَارَةَ الْمَسْجِدِ الْحَرَامِ كَمَنْ امَنَ بِالله الآية \" کیا تم نے حاجیوں کو پانی پلانا اور مسجد حرام کو آباد کرنا اس شخص کی طرح کر دیا جو اللہ تعالیٰ پر ایمان لائے۔ ( آخر آیت تک)‘ یہ حدیث حضرت نعمان سے صرف اسی اسناد کے ساتھ روایت کی گئی ہے۔ مذکورہ قرآنی آیت اور حدیث سے معلوم ہوا کہ ایمان باللہ، ایمان بالآخرت اور جہاد فی یل اللہ سب سے زیادہ اہمیت وفضیلت والے عمل ہیں۔ گفتگو کے حوالے سے اصل اہمیت وفضیلت تو جہاد کی بیان کرنا تھی لیکن ایمان رحمہ اللہ کے بغیر چونکہ کوئی بھی عمل مقبول نہیں، اس لیے پہلے اسے بیان کیا گیا۔ بہر حال اس سے ایک تو یہ معلوم ہوا کہ جہاد فی سبیل اللہ سے بڑھ کر کوئی عمل نہیں۔ دوسرا یہ معلوم ہوا کہ اس کا سبب نزول مشرکین کے مزعومات فاسدہ کے علاوہ خود مسلمانوں کا بھی اپنے طور پر بعض عملوں کو بعض پر زیادہ فضیلت دینا تھا جب کہ یہ کام شارع کا ہے نہ کہ مومنوں کا، مومنوں کا کام تو ہر اس بات پر عمل کرنا ہے جو اللہ اور رسول کی طرف سے انہیں بتلائی جائے۔","",{"k":"صحیح مسلم (١٨٧٩)۔"}],[422,"سیدنا عمر و بن عبسہ رضی اللہ عنہ نے بیان کیا، جب رسول اللہ صلے علی تیم مبعوث ہوئے تو تب میں آپ ملئے علیم کے پاس آیا آپ اس وقت چھپے ہوئے تھے میں نے ان سے کہا: آپ کیا ہیں؟ تو آپ نے فرمایا: ”میں نبی ہوں“ میں نے کہا: نبی کیا ہوتا ہے؟ آپ نے فرمایا: ”اللہ کا پیغام پہنچانے والا۔ میں نے کہا: اللہ ٣٩ نے تمہیں بھیجا ہے؟ آپ نے فرمایا: ”ہاں۔ میں نے کہا: کیا پیغام دے کر بھیجا؟ آپ نے فرمایا: ”کہ تم اللہ کی بندگی کرو اور بتوں کو توڑ دو، رشتہ داریوں کو ملا کر رکھو میں نے کہا: ہاں! آپ کو اس نے بھیجا ہے۔ اس کام میں تمہاری پیروی کس نے کی ہے؟ آپ نے فرمایا: ” ایک آزاد اور ایک غلام یعنی ابو بکر اور بلال۔ تو عمرو بن عبسہ کہا کرتے تھے کہ میں چوتھا مسلمان تھا۔ پس میں نے اسلام قبول کر لیا، پھر میں نے عرض کیا: اللہ کے رسول! میں آپ کی اتباع کروں؟ آپ نے فرمایا: \"نہیں! بلکہ تم اپنی قوم کے پاس چلے جاؤ جب یہ سنو کہ ہم غالب آ گئے ہیں تو ہمارے پاس آجانا۔ یہ حدیث عباس بن سالم سے صرف محمد بن مہاجر ہی روایت کرتے ہیں۔ (١) معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کی دعوت کیا تھی۔","",{"k":"♦، صحیح مسلم۔","f":"(٢) ابتدائی طور پر آپ کی دعوت کو آزادلوگوں میں سے سیدنا ابوبکر رضی اللہ عنہ نے قبول کیا جبکہ غلاموں میں سے سیدنا بلال رضی اللہ عنہ نے۔"}],[423,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما کہتے ہیں جو کچھ رسول اللہ صلی اللہ علیہ وسلم نے نہ بند کے متعلق فرمایا وہی کچھ قمیض کے متعلق بھی ہے۔“ فائد مذکورہ حدیث سے معلوم ہوا کہ مردوں کا اپنی شلوار قمیض ٹخنوں سے نیچے رکھنا حرام ہے۔","",{"k":"سنن ابو داؤد (٤٠٩٥)، قال الالبانی، صحیح۔"}],[424,"سیدنا ابو درداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنی مجلس سے اٹھتے اور واپسی کا ارادہ ہوتا تو اپنے جوتے یا اپنے اوپر کی کوئی چیز چھوڑ جاتے۔“ مسلم شریف میں ہے نبی معظم ملے سلیم نے فرمایا: \"جو شخص اپنی جگہ سے اٹھ کر جائے اور پھر واپس لوٹ آئے تو وہی اس جگہ کا زیادہ حق دار ہے۔ (صحیح مسلم، کتاب السلام، رقم: ٢١٧٩، سنن ابی داؤد، رقم: ٤٨٥٣) تا ہم اگر جلسے یا بڑی مجلس وغیرہ سے اٹھے اور واپس آنا ہو تو بہتر یہ ہے کہ کپڑا وغیرہ رکھ کر جائے۔ ٤٢٥","",{"k":"سنن ابو داؤد (٤٨٥٤)، مجمع الزوائد (٧١٠)، قال الالباني ضعيف۔"}],[425,"سیدنا ابو بکرہ ضیا الیہ بیان کرتے ہیں کہ ہم نبی صلی اللہ علیہ وسلم کے پاس تھے کہ آپ صلی اللہ علیہ وسلم نے ایک چھوٹا دستہ کسی طرف بھیجا تو ایک آدمی آپ ملنے سلام کے پاس خوش خبری لے کر آیا کہ دشمن کی سر براہ ایک عورت ہے تو آپ ملنے کی ام سجدے میں گر گئے پھر اپنا سر اٹھایا تو آپ یہ فرما رہے تھے: ” جب مردوں نے عورتوں کی اطاعت شروع کر دی تو مرد ہلاک ہو گئے۔“ مذکورہ روایت کمزور ہے تاہم عورت کی حکمرانی جائز نہیں ہے۔ ٤٢٦","",{"k":"السلسلة الضعيفة (٢/١٣، ٤٣٦)، ضعيف الجامع الصغير (٦٠٩٧)، مسند احمد (٥/٤٥)۔"}],[426,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے روایت ہے انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” استحاضہ والی عورت ایک حیض سے دوسرے حیض تک غسل کرے۔“ یہ حدیث اوزاعی سے صرف سلمہ بن کلثوم ہی روایت کرتے ہیں، اسے روایت کرنے میں بقیہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ استحاضہ والی عورت حیض کے بعد غسل کرے اور دوسرے حیض تک یہ عمل جاری رکھے۔ استحاضہ کا خون حیض سے الگ ہوتا ہے اور یہ کسی رگ کے پھٹنے کی وجہ سے آتا ہے۔ ابو داؤد میں سیدہ اسماء بنت عمیس بنای ایشیا کی حدیث ہے کہ اسے چاہیے کہ ٹب میں بیٹھ جائے جب پانی کے او پر زردی دیکھے تو ظہر اور عصر ( دونوں نمازوں) کے لیے ایک غسل کرے اسی طرح مغرب اور عشا کے لیے ایک غسل کرے اور فجر کے لیے بھی ایک غسل کرے اور ان کے درمیان وضو کرتی رہے۔ سنن ابی داؤد، كتاب الطهارة، رقم: ٢٩٦، اسناده صحیح) ظہر وعصر کے لیے ایک غسل مغرب و عشا کے لیے ایک غسل اور فجر کے لیے ایک غسل کی نبی معظم ملنے کی یکم نے ترغیب دلائی ہے لیکن یہ غسل واجب نہیں بلکہ مستحب ہے جیسا کہ سیدہ فاطمہ بنت ابی جحش بینی انا کو نبی معظم ال کی ایم نے فرمایا: ” جب استحاضہ کا خون ہو تو وضو کر اور نماز پڑھ۔ ( صحیح سنن ابی داؤد، رقم: ٣٢٥)","",{"k":"صحيح الجامع الصغير (٦٦٩٩)، مجمع الزوائد (١/٢٨١)، المعجم الكبير للطبرانی (٩٧١)۔"}],[427,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو اس نے عرض کیا: اللہ کے رسول! ہمارے لیے بھاؤ مقرر کر دیجئے تو آپ نے فرمایا: ”نہیں! بلکہ میں اللہ سے دعا کرتا ہوں، پھر ایک اور آدمی نے یہی بات کہی کہ ہمارے لیے بھاؤ مقرر کر دیں۔ آپ نے فرمایا: ”نہیں بلکہ اللہ تعالیٰ ( نرخ) بڑھاتا اور کم کرتا ہے اور میں امید رکھتا ہوں کہ اللہ تعالیٰ کو اس حال میں ملوں کہ کسی کا میرے ذمے کوئی حق نہ ہو۔ “ یہ حدیث حضرت ابو ہریرہ بنایا لینے سے صرف علاء بن عبدالرحمن ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ چیزوں کے ریٹ مقرر کرنا درست نہیں ہے۔ نبی معظم ملنے ان کا یہ فرمان کہ اللہ ہی (چیزوں کی قیمت گھٹانے بڑھانے والا ہے۔موجودہ اکنامکس کے تصورات سے صدیوں پہلے کی بات ہے۔ آپ صلی اللہ علیہ وسلم نے اس کے ذریعے سے معیشت کا ایک بنیادی اصول بیان فرمایا ہے اور منڈی کے عوامل کے آزاد ر ہنے کو انصاف اور عدل قرار دیا۔ قیمتوں کے تقرر سے کسی نہ کسی کا حق ضرور مارا جاتا ہے اس لیے اس سے اجتناب کا حکم دیا۔ اللہ تعالیٰ سے دعا کا مفہوم یہی ہے کہ وہ چیزوں کی پیداوار میں برکت عطا کرے اور ضرورت پوری کرنے کا متبادل انتظام کر دے۔ حکومت کو یہی کرنا چاہیے کہ وہ مہنگائی توڑنے کے لیے رسد میں اضافے کی کوشش کرے اور متبادل طریقے تلاش کرے۔ یہ مہنگائی کا کامیاب علاج ہے، جبکہ قیمتیں مقرر کرنے کے باوجود منڈی میں ان پر عمل نہیں ہوتا اور چیزوں کی چور بازاری شروع ہو جاتی ہے جن سے لوگوں کی اذیت میں اضافہ ہو جاتا ہے۔","",{"k":"سنن ابو داؤد (٣٤٥)، سنن ابن ماجه (٢٢٠٠)، سنن ترمذی (١٣١٤)، قال الالبانی، صحیح۔"}],[428,"سيدنا عبد اللہ رضی اللہ عنہ سے روایت ہے کہ وہ جس وقت نماز شروع کرتے تو یہ دعا کرتے: ((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ )) (آخر تک) نبی صلی اللہ علیہ وسلم کے فرمان کے مطابق۔“ یہ حدیث خصیف سے صرف عتاب ہی روایت کرتے ہیں، اسے روایت کرنے میں یوسف بن یونس اکیلے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ تکبیر تحریمہ کے بعد دعائے استفتاح پڑھنا چاہیے۔ دعائے استفتاح کے مختلف الفاظ نبی معظم صلی اللہ علیہ وسلم سے ثابت ہیں۔ (١)((اللهم باعد بيني وبين خطاياى الخ)) (صحیح بخاری، کتاب الاذان، رقم: ٧٤٤) (٢)((انى وجهت وجهي للذي فطر السموت الخ)) (صحيح مسلم، کتاب صلاة المسافرين، رقم: ٧٧١) (٣) ((سبحانك اللهم وبحمدك الخ )) ( صحيح سنن ابی داؤد، رقم: ٧٠٢) (٤) ((اللهم لك الحمد انت نور السموت والارض الخ)) صحیح سنن ابی داؤد، رقم: (٦٩٨ امام شافعی اللہ نے، انی وجهت وجھی الذی)) والی دعا کو ترجیح دی ہے۔ امام ابو حنفیہ جماللہ نے ((سبحانك اللهم وبحمدك)) کو ترجیح دیتے ہیں۔ امام مالک ہم اللہ نے کہا ہے دعائے استفتاح کے علاوہ سورۃ فاتحہ سے نماز شروع کی جائے۔ راجح بات یہی ہے کہ دعائے استفتاح مختلف احادیث میں مختلف الفاظ کے ساتھ ثابت ہے لہذا ان میں سے کسی ایک کو اختیار کر لینا کافی ہے۔ (واللہ اعلم)","",{"k":"سنن ترمذی (٢١٣)، قال الالباني، صحیح۔"}],[429,"سیدنا ابن عم رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص سلام کہنے سے پہلے سوال کرے تو تم اس کو جواب نہ دو۔“ مذکورہ حدیث سے معلوم ہوا کہ سلام کہنا ضروری ہے کیونکہ یہ ایک مسلمان کا دوسرے مسلمان پر حق ہے، جیسا کہ نبی مکرم صلے علیم نے فرمایا: ” مسلمان کے مسلمان پر چھ حق ہیں: ((اذا لقيته فسلم عليه)) (صحیح مسلم، کتاب السلام، رقم: ٢١٦٢) ”جب تو اس سے ملے تو سلام کہہ کیونکہ مسلمانوں کو ایک دوسرے کے حقوق کا خیال رکھنا چاہیے اس لیے فرمایا کہ گفتگو سے قبل السلام علیکم کہا جائے۔ ٤٣٠","",{"k":"السلسلة الصحيحة (٢/٣١٥، ٨١٦)، صحيح الجامع الصغير (٣٦٩٩)، المعجم الكبير للطبرانی (١١/١٥٧)۔"}],[430,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب اس امت کے آخری لوگ پہلے لوگوں پر لعنت کریں گے تو جس کے پاس علم ہو وہ اس کو ظاہر کرے کیونکہ اُس دن علم کو چھپانے: اس شخص کی طرح ہے جو اس چیز کو چھپاتا ہے جو محد سے علم پر نازل ہوئی۔“",""],[431,"سیدنا ابو بکرہ رضی الہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس نے کسی معاہد (زمی) کو قتل کیا تو وہ جنت کی خوشبو نہیں پائے گا۔ حالانکہ اس کی خوشبو پانچ سو سال کی مسافت سے پائی جاتی ہے۔ یہ حدیث شبیب بن شیبہ سے محمد بن سعید القرشی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ذمی سے کیے گئے عہد کی وفا کرنا چاہیے اور اس کو قتل نہیں کرنا چاہیے۔ مُعَاهَد (ھا پر زبر) یعنی ایسا شخص جو کافر ہوتے ہوئے حکومت اسلامیہ میں رہ رہا ہو اور ٹیکس وغیرہ ادا کرتا ہو تو اسے ذمی اور معاہد کہتے ہیں۔","",{"k":"سنن ابن ماجه (٢٦٨٦)، سنن ابو داؤد (٢٧٦٠)، قال : صحیح۔"}],[432,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ لیے علم کو دیکھا کہ آپ اپنی پیشانی پر بالوں کے گچھے پر سجدہ کر رہے تھے۔ یہ حدیث حکیم بن عمیر سے صرف ابوبکر بن ابی مریم ہی روایت کرتے ہیں۔:٤٣٣ مذکورہ روایت کمزور ہے، تاہم ضرورت کے تحت کپڑا رکھنا جائز ہے۔","",{"k":"مجمع الزوائد (٢/١٢٥)، اسناده ضعيف فيه ابو بكر بن ابى مريم وهو ضعيف۔"}],[433,"سیدنا سعد بن ابی وقاص رضی اللہ عنہ نے بیان کیا نبی صلی اللہ علیہ وسلم سے اس آیت کے متعلق پوچھا گیا: ﴿ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ اَرْجُلِكُمْ یعنی الله تعالیٰ اس بات پر قادر ہے کہ تم پر تمہارے اوپر سے یا تمہارے پاؤں کے نیچے سے عذاب بھیج دے۔“ رسول اللہ لم نے فرمایا: ” یہ بات ہونے والی ہے مگر ابھی اس کی تاویل نہیں آئی۔ حضرت سعد سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابوبکر بن ابی مریم اکیلے ہیں۔","",{"k":"سنن ترمذی (٣٠٦٦)، مسند احمد : ١ / ١٧٠ قال الالبانى، ضعیف۔"}],[434,"سيدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آخری دور میں کچھ ایسے لوگ ہوں گے جو علانیہ طور پر تو بھائی ہوں گے جبکہ پوشیدہ طور پر دشمن ہوں گے۔ کسی نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! یہ بات کیسے ہوگی؟ فرمایا: ” کیونکہ بعض لوگوں کو بعض سے دلچسپی اور رغبت ہوگی اور بعض کو بعض سے ڈر ہو گا۔“ یہ حدیث حضرت معاذ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابوبکر بن ابی مریم اکیلے ہیں۔ ٤٣٥","",{"k":"مسند احمد (٥/٢٣٥)، مجمع الزوائد: ٧ / ٢٨٦ ضعيف، قال الشيخ شعيب الارناؤط: اسناده ضعیف۔"}],[435,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”میں نے ارادہ کیا کہ حکم دوں کہ نماز کھڑی کر دی جائے، پھر میں ایک آدمی کو حکم دوں تو وہ لوگوں کو نماز پڑھائے، پھر میں ایک گٹھا ایندھن کا لاؤں، اور پھر میں ایسے لوگوں کی طرف جاؤں جو اپنے گھروں میں ہیں مگر نماز کو حاضر نہیں ہوتے تو ان پر ان کے گھروں کو جلا ڈالوں۔“ یہ حدیث عدی بن ثابت سے صرف زید بن ابی اُنیسہ ہی روایت کرتے ہیں۔ ٤٣٦","",{"k":"صحیح مسلم (٦٥١)، سنن ابو داؤد (٥٤٨)۔"}],[436,"سیدنا عامر بن ربیعہ کہتے ہیں کہ ثقیف کے ابو تمام نامی ایک آدمی نے رسول اللہ لئے تعلیم کو ایک برتن میں بطور تحفہ شراب پیش کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے ابو تمام! یہ تو حرام کر دی گئی ہے اس نے کہا: یا رسول اللہ! اس کی قیمت لے کر خرچ کر دیں، تو نبی صلی اللہ علیہ وسلم نے فرمایا؟ جس ذات نے اس کا پینا حرام کیا ہے اس نے اس کی قیمت بھی حرام کی ہے۔ یہ حدیث ابو بکر بن حفص سے صرف زید بن ابی انیسہ ہی روایت کرتے ہیں اور حضرت عامر بن ربیعہ سے یہ حدیث اسی سند سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ حرام چیز کا ہدیہ دینا اور اسے فروخت کرنا ناجائز و حرام ہے۔ جیسا کہ سیدنا ابو ہریرہ بنی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بے شک اللہ تعالیٰ نے شراب اور اس کی قیمت ( یعنی خرید وفروخت) کو حرام کیا ہے۔ (سنن ابی داؤد، رقم: ٣٤٨٥، اسناده صحيح) ٤٣٧","",{"k":"وَلَا يُرْوَى عَنْ عَامِرِ بْنِ رَبِيعَةَ إِلَّا بِهَذَا الْإِسْنَادِ . سنن نسائی (٤٦٦٤)، مجمع الزوائد (٨٩/٤)، قال الالباني: صحيح۔"}],[437,"سیدنا جابر فی اللہ نے بیان کیا، ہم تین دن سے زائد قربانیوں کا گوشت نہیں رکھتے تھے پھر ہمیں رسول اللہ علی علیم نے حکم دیا کہ ہم کھائیں اور ذخیرہ کریں۔“ زید سے صرف عبید اللہ بن عمرو ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قربانی کرنے والا اس سے صدقہ کرے،خود کھائے اور ذخیرہ بھی کر سکتا ہے۔ سیدنا سلمہ بن اکوع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے جو کوئی قربانی کرے تیسرے دن کے بعد اس کے گھر میں اس سے کوئی چیز باقی نہ ہو۔ پس اگلے سال صحابہ نے عرض کیا: اللہ کے رسول! کیا اس سال بھی ہم اس طرح کریں جس طرح ہم نے گذشتہ سال کیا تھا؟ آپ ملے نعلیکم نے فرمایا: ”کھاؤ، کھلاؤ اور ذخیرہ کرو۔ بلاشبہ اس سال لوگ مشقت میں تھے تو میں نے ارادہ کیا کہ تم ان کی مدد کرو۔“ (صحیح بخاری، کتاب الاضاحی، رقم: ٥٥٦٩، صحيح مسلم، رقم: ٥١٠٩) معلوم ہوا کہ جہاں فقراء و مساکین کی کثرت ہو وہاں قربانی کا گوشت ان میں تقسیم کرنے کی بجائے ذخیرہ کر لینا صحیح نہیں ہے۔ البتہ جہاں معاملہ اس کے برعکس ہو تو وہاں اس کی گنجائش ہے۔ ٤٣٨","",{"k":"عبيد الله بن عمرو . صحیح مسلم (١٩٧)، سنن نسائی (٤٤٢٦)۔"}],[438,"سيدنا جریر بن عبداللہ بلی رضی اللہ عنہ نے بیان کیا میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا وہ سورہ مائدہ کے نازل ہونے کے بعد موزوں پر مسح کرتے تھے۔ یہ حدیث حمید بن مالک سے صرف اسماعیل بن عیاش ہی روایت کرتے ہیں۔","",{"k":"سنن ابی داؤد، رقم : ١٥٤ . صحیح بخاری، رقم :٢٠٥۔۔","f":"مشروع ہے۔ مذکورہ حدیث سے معلوم ہوا کہ موزوں پر مسح کا حکم منسوخ نہیں بلکہ موزوں پر مسح کرنا سیدنا جریر رضی اللہ عنہ ہجری کے شروع میں مسلمان ہوئے، اور آیت وضو يَأَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إلَى الصَّلوةِ فَاغْسِلُوا وُجُوهَكُمْ وَايْدِيَكُمْ ﴾ (المائده: (٦) اس میں سر کے مسح کا ذکر ہے موزوں کا نہیں بلکہ پاؤں دھونے کا حکم ہے تو بعض لوگوں کا خیال تھا کہ موزوں پر مسح کرنا منسوخ ہے۔ سیدنا جریر ضیا اللہ نے واضح کیا کہ اس سورت کے نزول کے بعد اسلام لایا ہوں اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو وضو کرتے اور موزوں پر مسح کرتے دیکھا ہے لہذا یہ عمل جائز اور مسنون ہے۔ منسوخ سمجھنا درست نہیں۔"}],[439,"سیدنا طفیل بن عمرو دوسی ضیا اللہ کہتے ہیں مجھے سیدنا ابی بن کعب رضی اللہ عنہ نے قرآن مجید پڑھایا تو میں نے اس کو ایک کمان بطور ہدیہ دی وہ اسے گلے میں ڈال کر نبی صلی اللہ علیہ وسلم کے پاس گیا تو آپ نے اسے فرمایا ” اس نے اسے جہنم میں سے گلے میں ڈال لیا، میں نے کہا اللہ کے رسول! ہم بسا اوقات ان کے کھانے پر آ جاتے ہیں تو ہم اس سے کھاتے ہیں آپ نے فرمایا: \"جو چیز تیرے لیے بنائی گئی ہو پھر اگر تو نے اسے کھا لیا تو اس کو اپنے حصے کے ساتھ کھاؤ گے اور جو چیز تمہارے علاوہ کسی اور کے لیے بنائی جائے تو تم بھی آگئے ہو اور اس سے کھا لیا تو اس میں کوئی حرج نہیں۔“ یہ حدیث طفیل بن عمرو سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں اسماعیل بن عیاش اکیلے ہیں۔","",{"k":"مجمع الزوائد (٩٥/٤)، سنده ضعيف۔"}],[440,"سیدہ فاطمہ بنی شیما سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے کہا: ہماری ماں خدیجہ کہاں ہیں؟ آپ نے فرمایا: ” ایک خول دار موتی کے گھر میں جس میں نہ کوئی لغو بات ہو گی اور نہ تھکاوٹ ہو گی۔ سیدہ مریم اور فرعون کی بیوی آسیہ کے درمیان ہوں گی۔ سیدہ فاطمہ نے کہا: کیا اس خول دار موتی سے؟ آپ نے فرمایا: نہیں! بلکہ موتیوں اور یا قوت اور لؤلؤ سے جڑاؤ کئے ہوئے میں۔“ یہ حدیث حضرت فاطمہ سے صرف اسی سند سے مروی ہے، اُن سے روایت کرنے میں صفوان اکیلے ہیں۔","",{"k":"صحیح بخاری، مجمع الزوائد (٢٢٣/٩)، مسند الشاميين (١٠٢٤)۔","f":"مذکورہ حدیث میں سیدہ خدیجتہ الکبری فنی اشیا کی فضیلت کا تذکرہ ہے۔ سیدہ خدیجہ والا لانها بنت خویلد بن اسد بن عبد العزی نبی معظم نے یمن کی سب سے پہلی بیوی تھیں، نکاح کے وقت ان کی عمر ٤٠ سال جبکہ آپ صلی اللہ علیہ وسلم کی عمر ٢٥ سال تھی، رسول اللہ صلی اللہ علیہ وسلم کی ان سے اولا د بھی ہوئی اور پیغمبر اسلام ملے ایم کی اولین محسنہ بھی تھیں۔ بخاری شریف میں ہے نبی معظم صلی اللہ علیہ وسلم نے سیدہ خدیجہ نالیوں کو جنت میں موتیوں کے ایک محل کی بشارت دی تھی۔ جہاں کوئی شور وغل ہوگا نہ ممکن ہوگی۔ (صحیح بخاری، کتاب المناقب، رقم: ٣٨١٩) ٤٤١"}],[441,"\"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فاسقوں کے کھانے کی دعوت قبول کرنے سے منع فرمایا۔ یہ حدیث عمران بن حصین سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عبدالرحیم بن مطرف اکیلے ہیں۔ ٤٤٢","",{"k":"السلسلة الضعيفة (٥٢٢٩)، ضعيف الجامع الصغير (٦٠٢٩)، مجمع الزوائد (٥٤/٤)۔"}],[442,"سیدنا ابو ذر رضی اللہ عنہ کہتے ہیں جب رمضان کا آخری عشرہ ہوا تو نبی لئے علیم مسجد میں اعتکاف بیٹھے۔ جب آپ نے بائیسویں دن عصر کی نماز پڑھی تو فرمایا: ”ہم آج کی رات ان شاء اللہ قیام کریں گے جو ہمارے ساتھ قیام کرنا چاہے تو وہ قیام کر لے یہ تیئیسویں رات ہے تو آپ نے عشاء کے بعد ہمیں نماز پڑھائی یہاں تک کہ ایک تہائی رات گزرگئی تو آپ فارغ ہوئے۔ جب چوبیسویں رات ہوئی تو کچھ نہیں فرمایا، اور نہ ہی قیام کیا، جب پچیسویں رات ہوئی تو چو بیسویں کے دن عصر کے بعد کھڑے ہوئے اور فرمایا: ” ہم آج کی رات ان شاء اللہ قیام کریں گے یعنی پچیسویں تاریخ کو، تو جو شخص چاہے تو قیام کرئے، پس آپ نے نماز پڑھی یہاں تک کہ آدھی رات گزر گئی۔ جب چھبیسویں رات ہوئی کھڑے ہوئے اور فرمایا: ” ہم ان شاء اللہ قیام کریں گے یعنی ستائیسویں رات کو تو جو شخص قیام کرنا چاہے قیام کر لے۔“ سیدنا ابو ذر بھی یہ کہتے ہیں ہم نے قیام میں طاقت اور مضبوطی کا اظہار کیا تو آپ نے ہمارے ساتھ قیام کیا یہاں تک کہ دو تہائی رات گزرگئی۔ پھر آپ مسجد کے ایک خیمے میں چلے گئے میں نے آپ سے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم تو صبح تک آپ کے ساتھ قیام کرنے کے طمع میں تھے۔ آپ نے فرمایا: ” ابوذر! تو نے اپنے امام کے ساتھ نماز پڑھی اور جب وہ فارغ ہوا اسی وقت تم بھی فارغ ہوئے تو تمہارے لیے تیری اس ساری رات کا قیام لکھا جائے گا۔“ یہ حدیث شریح بن عبید سے صرف صفوان بن عمرو ہی روایت کرتے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ نماز تراویح باجماعت پڑھنا مشروع ہے۔ سیدہ عائشہ على النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک رات مسجد میں نماز پڑھائی۔ صحابہ نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ یہ نماز ادا کی۔ دوسری رات آپ صلی اللہ علیہ وسلم نے یہ نماز پڑھائی تو نمازیوں کی تعداد بہت بڑھ گئی۔ تیسری یا چوتھی رات تو یہ تعداد ایک بڑے اجتماع کی صورت اختیار کر گئی۔ لیکن نبی معظم ملنے ام اس رات نماز پڑھانے کے لیے تشریف نہ لائے۔ صبح کے وقت آپ صلی اللہ علیہ وسلم نے فرمایا: جتنی بڑی تعداد میں تم لوگ جمع ہو گئے تھے۔ میں نے اسے دیکھا لیکن یہ خدشہ میرے باہر آنے کے لیے رکاوٹ بنا رہا کہ کہیں یہ نماز تم پر فرض نہ کر دی جائے۔“ سیدنا عبد الرحمن بن عبد القاری جماللہ فرماتے ہیں کہ میں رمضان کی ایک رات سیدنا عمر رضی اللہ عنہ کے ساتھ مسجد میں گیا سب لوگ متفرق اور منتشر تھے۔ کوئی اکیلا نماز پڑھ رہا تھا اور کوئی کسی کے پیچھے کھڑا تھا۔ یہ دیکھ کر سیدنا عمر رضی اللہ عنہ نے فرمایا: انی اری لو جمعت هولاء على قارئ واحد لكان امثل)) ”میرا خیال یہ ہے کہ اگر میں تمام لوگوں کو ایک قاری کے پیچھے جمع کر دوں تو زیادہ مناسب ہوگا۔ چنانچہ انہوں نے اسی عزم وارادے کے ساتھ سیدنا ابی بن کعب ضیا اللہ کو ان کا امام مقرر کر دیا۔ (صحیح بخاری، رقم: ٢٠١٠) معلوم ہوا بہتر یہ ہے کہ نماز تراویح باجماعت ادا کی جائے۔","",{"k":"مسند احمد (٥/١٧٢)، قال الشيخ شعيب الأرناؤط، حدیث صحیح۔"}],[443,"سیدنا ابوریحانہ بیانیہ نے بیان کیا، رسول اللہ ٹیم نے فرمایا: ”جو شخص اپنے نو کفار آباء کی طرف منسوب کرے، وہ ان کے ذریعے عزت چاہتا ہو تو وہ ان کا دسواں آگ میں ہوگا۔‘“ یہ حدیث ابوریحانہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابوبکر بن عیاش اکیلے ہیں۔ ٤٤٤","",{"k":"السلسلة الضعيفة (٥/٤٣٠)، رقم : (٢٤٣١)، ضعيف الجامع الصغير (٥٤٨٨)، مسند احمد (٤/١٣٤)، مجمع الزوائد (٨٥/٨)۔"}],[444,"سيدنا ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ابو منذر! مجھے حکم ہوا ہے کہ تجھ پر قرآن مجید پیش کروں تو انہوں نے کہا: میں اللہ پر ایمان لایا ہوں، آپ کے ہاتھوں پر ہوا ہوں اور آپ سے میں نے سیکھا ہے وہ کہتے ہیں کہ نبی ملنے سلیم نے وہی بات دہرائی تو انہوں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا وہاں میرا ذکر ہوا؟ آپ نے فرمایا: ”ہاں! تیرے نام اور نسب کے ساتھ تیرا ذکر ملا اعلیٰ میں ہوا ہے۔ انہوں نے کہا: تب اللہ کے رسول آپ پڑھیں۔“ مذکورہ روایت سے معلوم ہوا کہ کسی سے قرآن مجید سننا مشروع ہے۔ سیدنا انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابی بن کعب رضی اللہ عنہ سے فرمایا: اللہ تعالیٰ نے مجھے حکم دیا ہے کہ میں تمہارے سامنے سورۃ البینہ تلاوت کروں۔ سیدنا ابی بی الیہ نے عرض کیا: کیا اللہ تعالیٰ نے آپ مطلئے علیم کے سامنے میرا نام لیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہاں! ابی بن کعب رضی اللہ عنہ یہ سن کر خوشی سے ) رونے لگے۔ (صحیح مسلم، کتاب صلاة المسافرين ) سیدنا ابی رضی اللہ عنہ قراء کرام رضی اللہ عنہ میمن کے استاد تھے۔ سیدنا عمر بنی اہلیہ نے اپنے عہد خلافت میں نماز تراویح باجماعت ادا کرنے کے لیے انہیں ہی امام مقرر فرمایا تھا۔","",{"k":"مجمع الزوائد (٣١٢/٩)۔"}],[445,"سیدنا ابی بن کعب رضی اللہ عنہ نے عرض کیا: اللہ کے رسول صلی اللہ علیہ وسلم! بخار کا کیا بدلہ ہے؟ آپ نے فرمایا: ” بخار والے کی نیکیاں جاری رہتی ہیں جب تک اس کا قدم ہلتا رہے یا اس کی رگ پھڑکتی رہے“ تو انہوں نے دعا کی: اے اللہ! میں تجھ سے بخار کا سوال کرتا ہوں جو مجھے تیرے راستے میں نکلنے یا تیرے گھر کی طرف جانے یا تیرے نبی کی مسجد میں جانے سے نہ روک سکے۔ کہتے ہیں: کوئی بھی ایسی شام نہیں گزری جب کہ انہیں بخار نہ ہوا ہو۔“ یہ دونوں حدیثیں معاذ بن محمد بن ابی سے صرف محمد بن عیسی الطباع ہی روایت کرتے ہیں۔ ٤٤٦","",{"k":"ابی، السلسلة الضعيفة (٤٧٥/٦، ٣٣٨٧)، مجمع الزوائد: د (٢/٣٠٥)۔"}],[446,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی ایسا شخص تمہارے پاس پیغام نکاح لائے جس کے دین اور اخلاق کو تم پسند کرتے ہو تو اس کا نکاح کر دو اگر ایسا نہ کرو گے تو زمین پر فتنہ اور لمبا چوڑا فساد پھیل جائے گا۔“ یہ حدیث ابن عجلان سے صرف عبدالحمید بن سلیمان ہی روایت کرتے ہیں۔ اندن ) مذکورہ حدیث سے معلوم ہوا کہ رشتہ داریاں دین و اخلاق حسنہ کی بنیاد پر جوڑنی چاہئیں۔ (٢) اگر دین دار رشتہ ٹھکرادیا جائے تو اللہ کی ناراضی کا سامنا کرنا پڑتا ہے۔ ٤٤٧","",{"k":"کی سنن ترمذی (١٠٨٤)، قال الالبانی حسن۔"}],[447,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے اپنے کسی غزوہ میں فرمایا: \" کثرت سے (اکثر اوقات ) جوتے پہنا کرو کیونکہ جب تک جوتے پاؤں میں رہیں تو انسان سوار ہی کی طرح) ہوتا ہے۔ یہ حدیث مثنیٰ سے صرف حسن بن حبیب ہی روایت کرتے ہیں۔","",{"k":"کے صحیح مسلم (٢٠٩٦)، سنن ابو داؤد (٤١٣٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جوتا پہن کر چلنا بہتر ہے کیونکہ جس طرح سوار کو پاؤں میں تکلیف نہیں پہنچتی اسی طرح جوتا پہننے والوں کو بھی تکلیف کا خدشہ نہیں ہوتا، اور انسان کو چاہیے کہ سفر میں جوتا عمدہ اور مضبوط استعمال کرے تاکہ کسی قسم کی پریشانی کا سامنانہ کرنا پڑے۔"}],[448,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے، انہوں نے کہا: میں نے رسول اللہ الے علم کو یہ فرماتے ہوئے سنا: آپ صلی اللہ علیہ وسلم نے فرمایا: ” جب قیامت کا دن ہوگا اللہ تعالیٰ اپنے بندوں سے ایک بندے کو بلائے گا تو اس سے اس کے جاہ کے متعلق پوچھے گا: جس طرح وہ اس سے اس کے مال کے متعلق پوچھے گا۔“ یہ حدیث عبداللہ بن دینار سے صرف سلیمان بن ہلال ہی روایت کرتے ہیں، اسے روایت کرنے میں یوسف بن یونس اکیلے ہیں۔","",{"k":"ضعيف الجامع الصغير (٦٦١)، مجمع الزوائد (١٠/٣٤٦)۔"}],[449,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے ہر شخص سے اس کا رب پوچھے گا: اللہ تعالیٰ فرمائے گا اے میرے بندے! تجھے میرے متعلق کس نے دھو کے میں ڈال دیا۔ تو نے رسولوں ( علیالسلام ) کو کیا جواب دیا؟ یہ حدیث ھلال الوزان سے صرف شریک ہی روایت کرتے ہیں، اسے روایت کرنے میں اسحاق بن عبداللہ ا کیلے ہیں۔ ٤٥٠","",{"k":"بن عبد الله وهو ضعيف . المعجم الكبير للطبراني (١٨٢/٨)، رقم: ٨٨٩٩ سنده ضعيف، فيه شريك۔"}],[450,"سیدنا براء بن عازب رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم عشا کی نماز میں والتین والزیتون پڑھا کرتے تھے۔“ یہ حدیث اسماعیل بن ابی خالد سے صرف عبید اللہ بن عمر وہی روایت کرتے ہیں، اسے روایت کرنے میں عبید بن ہشام اکیلے ہیں۔ ابو داؤد میں ہے سیدنا براء بن عازب رضی اللہ عنہما فرماتے ہیں کہ ”ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں نکلے، آپ مالی علیم نے ہمیں عشا کی نماز پڑھائی تو آپ سے ہم نے اس کی ایک رکعت میں سورہ وَالتَّيْنِ وَالزَّيْتُونِ تلاوت فرمائی۔ (سنن ابی داؤد، رقم: ١٢٢١) معلوم ہوا کہ سفر میں امام کو چاہیے کہ نماز مختصر پڑھائے۔ مقتدیوں کے احوال کا خاص خیال رکھے۔ ٤٥١","",{"k":"صحیح مسلم (٤٦٤)، صحيح بخاری (٧٦٩)۔"}],[451,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، یہ چیز سنت سے ہے کہ فطر کے دن نماز عید کے لیے جانے سے پہلے کچھ کھا لیا جائے۔ اور قربانی کے دن نماز سے واپس آ کر کھائے۔“ یہ حدیث ابن جریج سے صرف ابن علیہ ہی روایت کرتے ہیں، اسے روایت کرنے والے اسحاق بن عبداللہ ا کیلیے ہیں۔","",{"k":"سنن ترمذی (٥٤٢)، صحيح ابن حبان (٢٨١٢)، قال شعیب الارناؤط، اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ عید الفطر سے قبل کچھ کھانا اور عید الاضحیٰ کے لیے جانے سے پہلے کچھ نہ کھانا مستحب ہے۔\n(١) عید الفطر سے پہلے کوئی میٹھی چیز کھانا مستحب ہے۔ جیسا کہ سیدنا انس ویلی اہلیہ سے روایت ہے کہ رسول اللہ علیم عید الفطر کے لیے نکلنے سے پہلے طاق عدد میں کھجوریں کھایا کرتے تھے۔ (صحیح بخاری، کتاب الجمعة، رقم: ٩٥٣)\n(٢) اور نبی معظم نے ایام عید الاضحیٰ سے قبل کوئی چیز نہیں کھاتے تھے بلکہ نماز عید الاضحی کے بعد قربانی کے گوشت سے ابتدا کرتے تھے۔ ٤٥٢"}],[452,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اپنی داڑھی کا خلال کیا۔“ یہ حدیث حمید سے صرف اسماعیل بن جعفر ہی روایت کرتے ہیں، اسے روایت کرنے میں اسحاق بن عبداللہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ داڑھی کا خلال کرنا مسنون ہے۔امام مالک، شافعی، ثوری یہ کا موقف ہے کہ یہ مستحب ہے جبکہ امام ابوحنیفہ، احمد، الحق میشم کا موقف ہے کہ وضو میں مستحب اور غسل جنابت میں واجب ہے۔ امام شوکانی اللہ فرماتے ہیں: انصاف کا تقاضا یہی ہے کہ یہ حدیث وجوب پر دلالت نہیں کرتی کیونکہ اس میں نبی معظم ملنے کی ایم کے فعل کا ذکر ہے اور فعل سے وجوب ثابت نہیں ہوتا۔ (نیل الاوطار: ٢٣٦/١)","",{"k":"سنن ترمذی (٣١)، سنن ابن ماجه (٤٣١)، قال الالباني: صحيح۔"}],[453,"سیدنا ابو قتادہ نی اہلیہ نے بیان کیا، ایک دفعہ ہم نبی علیم کے ساتھ نماز ادا کر رہے تھے کہ آپ صلی اللہ علیہ وسلم نے اپنے پیچھے کچھ آدمیوں کے چلنے پھرنے کی آواز سنی جب آپ نماز سے فارغ ہوئے تو آپ ملے یکم فرمایا: ” تمہارا کیا معاملہ ہے؟ انہوں نے کہا: ہم نے نماز کی طرف جلدی کی، آپ نے فرمایا: اس طرح نہ کیا کرو تم میں سے جو پالے وہ پڑھ لے اور جو فوت ہو جائے اس کی قضا دے دو۔“ یہ حدیث یحیی بن ابی کثیر سے صرف شیبان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نماز کے لیے آتے ہوئے سکون و وقار کوملحوظ رکھنے کا حکم ہے اور جلد بازی یا دوڑ کر آنا منع ہے، نیز اس سے یہ بھی معلوم ہوا کہ جو نماز امام کے ساتھ انسان نہ پاسکے اسے بعد میں اٹھ کر پورا کر لینا چاہیے۔ اس مسئلے میں اختلاف ہے کہ بعد میں جماعت کے ساتھ ملنے کی صورت میں امام کے ساتھ پڑھی ہوئی نماز پہلی رکعتیں شمار ہوں گی یا پچھلی، جمہور اہل علم کا کہنا ہے کہ یہ نماز پہلی شمار ہوگی۔ جبکہ امام ابوحنیفہ اللہ نے یہ موقف اپنایا ہے کہ یہ رکعتیں پچھلی نماز شمار ہوں گی۔ (نیل الاوطار: ٣٨٢/٢) جمہور کا موقف راجح ہے۔ (السببل الجرار: ٢٦٦/١) ভ کیونکہ آپ صلی اللہ علیہ وسلم نے فرمایا: ” جو نماز رہ جائے اس کی قضا دو۔“ سیدناعلی ضیا اللہ سے مروی ایک روایت میں ہے کہ تم امام کے ساتھ جو نماز پا لو وہ تمہاری پہلی نماز ہے۔ (السنن الكبرى للبيهقي: ٢٩٩/٢)","",{"k":"صحیح بخاری، صحیح مسلم (٦٠٣)۔"}],[454,"سیدنا عبد اللہ بن عدی بن حمراء نے بیان کیا، رسول اللہ نے تم حزورہ پر ٹھہرے تو فرمایا: اللہ کی قسم! میں جانتا ہوں کہ تو اللہ تعالیٰ کی بہتر اور پیاری سرزمین ہے اگر مجھے تجھ سے نکالا نہ جاتا تو میں کبھی بھی نہ نکلتا۔ یہ حدیث ابن زہری کے بھائی کے بیٹے سے صرف الدراور دی ہی روایت کرتے ہیں۔ (١) معلوم ہوا مکہ مکرمہ کرہ ارض کی بہترین جگہ ہے۔ (٢) اہل مکہ نے نبی صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ بھی ایم کو ہجرت پر مجبور کیا تھا۔ (٣) آبائی وطن اور جائے پیدائش سے محبت فطری امر ہے۔ ٤٥٥","",{"k":"صحيح مسلم (١٣٩٤)، سنن ترمذی (٣٩٢٥)۔"}],[455,"سیدنا عبد الرحمن بن سالم بن عویم بن ساعدہ عن ابیہ عن جدہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تم کنواری عورتوں سے نکاح کرو کیونکہ وہ شیریں دہن، زیادہ بچے پیدا کرنے والی اور تھوڑی چیز پر ہی زیادہ خوش ہو جانے والی ہوتی ہیں۔“ مذکورہ حدیث سے معلوم ہوا کہ کنواری لڑکی سے شادی بیوہ یا مطلقہ کی نسبت زیادہ بہتر ہے کیونکہ کنواری لڑکی سے شادی زیادہ مرغوب ہے اور کنواری بیوی میں بنی کھیل فطرتا اور بالعموم بہت زیادہ ہوتا ہے بخلاف بیوہ یا مطلقہ بیوی کے یہ عمل نفسیاتی صحت کے لیے بہت عمدہ ہے۔ نیز اس سے یہ بھی معلوم ہوا کہ میاں بیوی میں لہو ولعب جائز وحق ہے۔ تاہم کچھ اور وجوہات سے بیوہ سے شادی کرنا بھی باعث فضیلت ہے جیسا کہ نبی مکرم سے علم کا عمل اس پر شاہد ہے۔ ٤٥٦","",{"k":"السلسلة الصحيحة (٢/١٢٢، ٦٢٣)، سنن ابن ماجه (١٨٦١)، مجمع الزوائد (٢٥٩/٤)۔"}],[456,"اسی سند سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے مجھے پسند فرمایا اور میرے لیے میرے ساتھی بھی پسند فرمائے تو انہیں میرے وزیر، معاون اور سرال بنا دیا۔ تو جو انہیں برا بھلا کہے گا اس پر اللہ کی فرشتوں اور تمام لوگوں کی لعنت ہے۔“ یہ دونوں حدیثیں عویم بن ساعدہ سے اسی سند سے ہی مروی ہیں، ان سے روایت کرنے میں محمد بن طلحہ تیمی اکیلے ہیں۔ ٤٥٧","",{"k":"السلسلة الضعيفة (٣٨/٧، ٣٠٣٦)، ضعيف الجامع الصغير (١٥٣٦، ٢٥٩٥)۔"}],[457,"سیدنا عبد اللہ بن جعفر کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تبارک و تعالیٰ مقروض کے ساتھ ہوتا ہے یہاں تک کہ اس کا قرض ادا کر دیتا ہے جب کہ وہ قرضہ اللہ تعالیٰ کی ناپسندیدہ جگہ کے لیے نہ ہو۔ “ یہ حدیث عبد اللہ بن جعفر سے اسی سند سے مروی ہے، اسے روایت کرنے میں ابن ابی فدیک اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جو آدمی قرض لیتا ہے، پھر اس کی نیت ادا کرنے کی ہو تو اللہ تعالیٰ اس آدمی کی مدد فرماتا ہے، اس کے لیے قرض اتارنا آسان ہو جاتا ہے، بشرطیکہ وہ قرض لی ہوئی رقم اللہ کی ناپسندیدہ جگہ پر خرچ نہ کی گئی ہو۔ ٤٥٨","",{"k":"الرائق . صحيح الجامع الصغير (١٨٢٥)، سنن دارمی۔"}],[458,"\"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑا ہوا تو لوگوں نے اس کے کھڑا ہونے میں عاجزی دیکھی تو کہنے لگے: فلاں آدمی کو کس چیز نے عاجز کر دیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم نے اپنے بھائی کا گوشت کھایا اور اس کی غیبت کی۔“ یہ حدیث موسیٰ بن وردان سے حماد بن ابی حمید ہی روایت کرتے ہیں۔","",{"k":"الله ضعيف الترغيب والترهيب (١٦٨١)، مجمع الزوائد (٨/٩٤)۔"}],[459,"سیدنا جابر بن عبد اللہ نبی اللہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جو شخص جس چیز کا مالک نہ ہوا سے طلاق دینے کا اختیار ہے نہ کسی کو آزاد کرنے کا اختیار ہے جس کا وہ مالک نہ ہو۔ یہ حدیث صدقہ بن یزید سے صرف عبداللہ بن یزید ہی روایت کرتے ہیں۔","",{"k":"تقدم تخريجه انظر (٨٩)۔"}],[460,"سیدنا عامر بن ربیعہ رضی اللہ عنہ کا بیان ہے کہ میں ایک تاریک رات میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا ہم نے ایک جگہ پڑاؤ ڈالا، تو ایک آدمی پتھر لے کر سجدہ کی جگہ پر جمع کرنے لگا اور اس طرف نماز پڑھنے لگا جب صبح ہوئی تو ہمیں معلوم ہوا کہ ہم نے نماز قبلہ کی طرف نہیں پڑھی تو ہم نے عرض کیا: اللہ کے رسول! ہم نے اس رات قبلہ کی طرف نماز نہیں پڑھی، تو اللہ تعالیٰ نے یہ آیت نازل فرمائی: وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَمَا تَوَلُّوا فَقَمَّة وَجْهُ اللَّهُ اللہ ہی کے لیے مشرق اور مغرب ہے تو جدھر بھی تم منہ کرو ادھر ہی اللہ کا چہرہ ہے۔“ یہ حدیث عاصم بن عبید اللہ سے صرف ابوالربیع السمان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ اگر آدمی غیر قبلہ کی طرف منہ کر کے نماز پڑھ لیتا ہے اور اس کو نماز کے بعد علم بھی ہو جاتا ہے تو نماز درست ہے دوبارہ نماز ادا کرنے کی ضرورت نہیں ہے۔ شیخ عبد العزیز بن باز رماللہ نے بھی یہی فتویٰ دیا ہے۔(فتاویٰ ابن باز، مترجم: ٥٦/١) امام ابن قدامہ اللہ کا بھی یہی موقف ہے۔ (المغنی لابن قدامه: ١١١/٢) امام شوکانی جماللہ اور علامہ عبد الرحمان مبارکپوری جماللہ کا بھی یہی موقف ہے۔ (نیل الاوطار: ٦٧٧/١ تحفة الاحوذى: ٣٣٥/١) تاہم فقہا کا اس مسئلہ میں اختلاف ہے۔ احناف اور حنابلہ کا تو موقف ہے کہ دوبارہ پڑھنے کی ضرورت نہیں وہ نماز درست ہے، جبکہ مالکیہ نے کہا ہے کہ اس نماز کا اگر وقت باقی ہو تو اسے دوبارہ پڑھنا لازم ہے۔ شافعیہ کا موقف ہے کہ اس کا وقت باقی ہو یا نہ ہوا سے دوبارہ پڑھنا واجب ہے۔ (الفقه الاسلامی: ٧٦١/١) راجح موقف احناف اور حنابلہ کا ہے۔ (واللہ اعلم) اگر دوران نماز قبلہ کا علم ہو جائے تو دوران نماز رخ بدل لینا چاہیے۔ جیسا کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے مروی روایت میں ہے کہ جب اہل قبا کو دوران نماز ایک صحابی نے قبلہ بدل جانے کا فرمان الہی سنایا تو انہوں نے نماز ہی میں شام سے کعبہ کی جانب رخ پھیر لیا۔ (صحیح بخاری، رقم: ٤٠٣، سنن ترمذی، رقم: ٤٣١) امام ابن قدامہ اللہ نے بھی یہی موقف اختیار کیا ہے۔ (المغنی لابن قدامه: ١١٣/١) ·:٤٦١","",{"k":"سنن ابو داؤد (١٠٤٥)، السنن الكبرى للبيهقي (١١/٧)۔"}],[461,"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”سب سے پہلے جس کے لیے (بال صفا ) پاؤڈر بنایا گیا اور حمام میں داخل ہوا وہ سلیمان بن داؤد علی نام تھے جب وہ اس میں داخل ہوئے اور اس کی حرارت اور گرمی محسوس کیا تو کہنے لگے: او ہو یہ تو اللہ کے عذاب میں سے ہے۔ اوہو، او ہو۔اس سے پہلے کہ او ہو کرنا کچھ","",{"k":"الكبير للطبراني: ٢٠/ ١٧٢ . السلسلة الضعيفة (٢٧٠٤)، ضعيف الجامع الصغير (٢١٤٦)، المعجم۔","f":"نہ دے۔“ یہ حدیث ابو موسیٰ سے صرف اسی سند سے مروی ہے اسے روایت کرنے میں ابراہیم بن مہدی اکیلے ہیں۔"}],[462,"سیدنا جابر رضی اللہ عنہ کہتے ہیں: نفاس والی عورتوں کے لیے چالیس دن مقرر کیے گئے ہیں۔“ یہ حدیث اشعث سے صرف ابو خالد ہی روایت کرتے ہیں۔","",{"k":"سنن دارمی (٩٥٤)، قال الشيخ حسين سلیم اسد: اسناده صحيح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نفاس کی مدت زیادہ سے زیادہ چالیس دن ہے۔ جمہور علماء اسی کے قائل ہیں۔ جبکہ امام شافعی اللہ فرماتے ہیں کہ نفاس کی زیادہ سے زیادہ مدت ساٹھ (٦٠) دن ہے۔ (المغنى: ٣٤٥/١، المحلى: ٢٠٣/٢) راجح موقف جمہور کا ہے۔ ابن قدامہ، امام شوکانی، علامہ عبد الرحمان مبارکپوری رحمہم اللہ کا موقف بھی چالیس دنوں والا ہے۔ اگر چالیس دنوں کے بعد بھی خون آتا رہے تو اس کے متعلق شیخ محمد بن ابراہیم آل شیخ کا یہ فتویٰ ہے کہ اگر تو عورت کی پہلے سے یہ عادت ہو ( کہ اسے ہر بچے کی ولادت پر چالیس روز سے اوپر یا دو تین دن خون آتا رہا ہے ) تو وہ اسی کے مطابق عمل کرے گی، اگر ایسا نہیں تو وہ چالیس دن پورے کرنے کے بعد غسل کرے گی اور نماز اور روزے رکھے گی۔ (فتاوى المراة المسلمة: ٢٩٧/١) نفاس کی کم از کم کوئی مدت نہیں، اگر ایک روز کے بعد بھی خون ختم ہو جائے تو عورت پاک تصور کی جائے گی۔ امام شافعی اور احمد نے اسی کے قائل ہیں۔ امام ابو حنیفہ جماللہ نے اس کی کم از کم مدت گیارہ دن مقرر کی ہے جو بلا دلیل ہے۔ (کتاب الام للشافعي: ٦٤/١، المغنى: ٤٢٨/١) علاوہ ازیں نفاس والی عورت تمام احکامات میں حائضہ کی مانند ہی ہے یعنی وہ نماز ادا کر سکتی ہے نہ روزہ رکھ سکتی ہے، نہ شوہر اس سے ہم بستری کر سکتا ہے، وہ قرآن پاک پڑھ سکتی ہے نہ وہ دوران حج طواف بیت اللہ کر سکتی ہے۔ اس پر اہل علم کا اجماع ہے۔ (نیل الاوطار: ٤١٥/١) ٤٦٣"}],[463,"سیدنا جابر بن عبد اللہ صلی اللہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” لوگوں کے ساتھ نرمی اور حسن سلوک سے پیش آنا بھی صدقہ ہے۔ یہ حدیث یوسف بن محمد سے صرف موسیٰ بن عیسی ہی روایت کرتے ہیں۔","",{"k":"کر ضعيف الجامع الصغير (٥٢٥٥)، صحیح ابن حبان (٤٧١)۔"}],[464,"سيدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے سیدہ ام سلمہ نبیل الشیبا في سے گھر کے سامان ( کو حق مہر قرار دینے ) پر شادی کی جس کی قیمت دس درہم تھی۔ یہ حدیث حمید سے صرف عمرو بن الازھر ہی روایت کرتے ہیں۔ ٤٦٥","",{"k":"اسد: اسناده ضیعف . مسند ابی یعلی (٣٣٨٥)، مجمع الزوائد (٤/٢٨٢)، قال حسین سلیم۔"}],[465,"سیدنا انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” امام کا سترہ پیچھے اقتدا کرنے والوں کا بھی سترہ ہے۔ یہ حدیث عاصم سے صرف سوید ہی روایت کرتے ہیں، اسے روایت کرنے میں ربیع اکیلے ہیں۔","",{"k":"السلسلة الضعيفة (٣٢٩٥)، ضعيف الجامع الصغير (٣٢٥٠)۔","f":"مذکورہ روایت کمزور ہے تاہم یہ درست ہے کہ امام کا سترہ مقتدیوں کو بھی کفایت کر جاتا ہے۔ جیسا کہ امام بخاری ہراللہ نے باب باندھا ہے: ((سترة لامام ستره من خلفه)) اس کی تحت یہ روایت نقل فرمائی کہ سیدنا عبد اللہ بن عباس یا اللہ نے فرمایا میں ایک گدھی پر سوار ہو کر آیا میں اس زمانہ میں بالغ ہونے کے قریب تھا۔ رسول اللہ ملے لیکن منی میں لوگوں کو نماز پڑھا رہے تھے۔ لیکن آپ ملے اہم دیوار کے سامنے نہ تھے۔ میں صف کے بعض حصے سے گذر کر سواری سے اترا۔ اور میں نے گدھی کو چرنے کے لیے چھوڑ دیا اور صف میں داخل ہو گیا۔ پس کسی نے مجھ پر اعتراض نہیں کیا۔ (صحیح بخاری، کتاب الصلاة، رقم: ٤٩٣) ٤٦٦"}],[466,"سیدنا عبد اللہ ہوزنی سیدنا بلال مؤذن رسول ملے کو حلب میں مسواک کر رہے تھے۔ وہ کہتے ہیں: میں نے کہا: بلال! مجھے بتاؤ نبی صلی اللہ علیہ وسلم کام کاج کس طرح کرتے تھے؟ سیدنا بلال رضی اللہ عنہ نے کہا: ” آپ کی کوئی چیز بھی نہیں تھی بلکہ جب سے اللہ تعالیٰ نے آپ کو مبعوث فرمایا وفات تکمیں آپ کے معاملات کا ذمہ دار تھا۔ جب کوئی مسلمان آپ کے پاس آتا اگر آپ اس کو نگا دیکھتے تو مجھے حکم دیتے تو میں قرض لیتا اور چادر خرید کر پہناتا اور اسے کھانا کھلاتا۔ مشرکین میں سے ایک آدمی میرے پاس آیا، کہنے لگا: بلال! میرے پاس بہت مال ہے تو تم میرے بغیر کسی سے قرض نہ لیا کرو تو میں اسی طرح کرنے لگا۔ ایک دن میں نے وضو کیا اور اذان کہنے کے لیے کھڑا ہوا، وہ مشرک تاجروں کی جماعت لے کر میرے پاس آ گیا۔ جب مجھے دیکھا تو کہنے لگا: اے حبشی! میں نے کہا: جی حاضر ہوں۔ پھر مجھے سخت باتیں کہیں۔ وہ کہنے لگا: تجھے معلوم ہے کہ مہینے کے درمیان اور تیرے درمیان کتنے دن ہیں؟ میں نے کہا: مہینہ قریب ہی ہے۔ کہنے لگا: تیرے اور مہینے میں چار دن باقی ہیں۔ جتنی رقم تیرے نام پر بقایا ہے اس کے عوض میں تجھے پکڑ لوں گا کیونکہ میں نے جو کچھ بھی تجھے دیا ہے وہ تیری یا تیرے ساتھی کی عزت کے طور پر نہیں دیا بلکہ اس لیے دیا ہے کہ تجھے غلام بنا لوں۔ پھر تجھے پہلے کی طرح اپنی بکریاں چرانے پر لگا دوں جس طرح تو پہلے بکریاں چرایا کرتا تھا۔ تو میرے دل میں بھی وہ بات آگئی جو تمام لوگوں کے دلوں میں آتی ہے۔ میں گیا اور نماز کے لیے آذان کہی۔ جب عشا کی نماز پڑھ چکا اور نبی صلی اللہ علیہ وسلم اپنے گھر لوٹے تو میں نے آپ سے اجازت طلب کی انہوں نے دے دی۔ میں نے کہا: اللہ کے رسول صلے یکم! وہ مشرک جس سے میں قرض لیا کرتا تھا وہ مجھے ایسی اور ایسی باتیں کہتا ہے اور آپ کے پاس بھی اتنی دولت نہیں کہ آپ قرضہ ادا کر سکیں اور میرے پاس بھی نہیں اس لیے وہ مجھے رسوا کرے گا، تو مجھے اجازت دیں کہ میں ان بعض قبائل کے پاس جاؤں جو مسلمان ہو چکے ہیں تاکہ اللہ تعالیٰ اپنے رسول ملے تم کو اتنا مال عطا فرما دے کہ اس شخص کا قرض ادا ہو جائے۔ پھر میں آپ کے گھر سے نکل کر اپنے گھر آگیا تو میں نے اپنی تلوار تھیلا اور جوتے اپنے سر کے پاس رکھ لیے اور اپنا چہرا آسمان کے کناروں کی طرف کر لیا جب میں تھوڑی دیر سویا تو بیدار ہو گیا۔ پھر جب میں نے دیکھا کہ ابھی کافی رات باقی ہے تو میں پھر سو گیا جب صبح اول کی روشنی پھوٹی تو میں نے نکل جانا چاہا تو اچانک ایک آدمی دوڑتا ہوا پکارنے لگا: بلال! بلال، نبی صلی اللہ علیہ وسلم بلا رہے ہیں، میں آپ کے پاس چلا گیا تو نا گہاں میں نے دیکھا کہ چار سواریاں اپنے بوجھوں سمیت بیٹھی ہوئی ہیں۔ میں آپ کے پاس آیا اور اجازت مانگی۔ آپ نے فرمایا: ”خوش ہو جاؤ اللہ تعالیٰ نے تیرا قرض سارا ادا کر دیا ہے میں نے اللہ کی تعریف کی۔ آپ نے فرمایا: ” تو بیٹھی ہوئی چار سواریوں کے پاس سے نہیں گزرا؟ میں نے کہا: جی ہاں! آپ نے فرمایا: ” یہ سب لدوں سمیت تیرے لیے ہیں، ان کے اوپر کپڑے اور کھانا ہے جو فدک کے بڑے سردار نے مجھے بطور تحفہ بھیجے ہیں ان کو قبضہ میں لے لو اور اپنا قرض ادا کرو تو میں نے ایسے ہی کیا، ان کے لدے اتار دیے اور ان کے آگے چارا ڈال دیا، پھر صبح کی اذان دینے کھڑا ہو گیا۔ جب نبی سے تم صبح کی نماز پڑھ چکے تو میں بقیع کی طرف چلا گیا کان میں انگلی دے کر یہ اعلان کیا جس نے نبی صلی اللہ علیہ وسلم سے قرضہ لینا ہو وہ حاضر ہو جائے پھر میں وہ مال بیچتا رہا اور قرض ادا کرتا رہا جب زمین آپ کے ذمہ کوئی قرض نہ رہا، یہاں تک کہ میرے ہاتھ میں دو یا ڈیڑھ اوقیہ سونا بیچ گیا تو میں مسجد گیا دن کا اکثر حصہ جاچکا تھا۔ نبی صلی اللہ علیہ وسلم اکیلے بیٹھے ہوئے تھے میں نے آپ کو سلام کیا، آپ نے مجھے کہا ”تو نے کیا کیا؟“ میں نے کہا: اللہ نے اپنے رسول کا سارا قرضہ ادا کر دیا کچھ بھی باقی نہ رہا۔ آپ نے پوچھا: ” کچھ باقی بچا ہے؟ میں نے کہا: جی ہاں۔ آپ نے فرمایا: ”دیکھو مجھے اس سے آرام پہنچاؤ بے شک میں اپنے گھر والوں میں سے کسی کے پاس اس وقت تک نہیں جاؤں گا حتی کہ تم مجھے اس سے آرام پہنچا دو۔“ پھر شام تک ہمارے پاس کوئی نہ آیا جب رسول اللہ سے تم نے عشا کی نماز پڑھ لی تو مجھے بلایا اور پوچھا ” کیا کیا؟“ میں نے کہا: وہ سونا میرے پاس ہے کیونکہ ابھی تک کوئی نہیں آیا۔ آپ اس وجہ سے رات کو صبح تک مسجد میں رہے دوسرے دن نمازیں پڑھیں جب شام ہوئی تو دو سوار آ گئے تو میں ان دونوں کو لے گیا پھر کھانا کھلایا اور کپڑے لے کر دیئے جب عشا کی نماز پڑھی تو مجھے بلایا تو فرمایا: ” جو تمہارا معاملہ ہے اس کا کیا بنا؟“ میں نے عرض کیا: اللہ کے رسول! اللہ تعالیٰ نے آپ کو اس سے آرام بخش دیا ہے تو آپ نے اللہ اکبر کہا، اور اللہ تعالیٰ کی حمد بیان کی اس خوف سے کہ کہیں اس رقم کے ہوتے ہوئے موت نہ آ جائے جبکہ یہ مال آپ کے پاس ہو۔ پھر میں آپ کے پیچھے چلا گیا، آپ اپنی ازواج مطہرات کے پاس گئے تو ایک ایک کو سلام کیا، پھر اپنی رات گزارنے کی جگہ پر آئے یہ ہے وہ کام جس کے متعلق تو نے مجھ سے سوال کیا ہے۔“ یہ حدیث بلال سے اسی اسناد سے مروی ہے، اسے روایت کرنے میں معاویہ بن سلام اکیلے ہیں۔","",{"k":"المعجم الكبير للطبراني (١/٤٨٠)۔","f":"مذکورہ حدیث سے معلوم ہوتا ہے مسلم و غیر مسلم سے قرض لینا جائز ہے، قرض لینے کے جواز پر اجماع ہے۔ (المغنی: ٣١٣/٤) ٤٦٧"}],[467,"رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام سیدنا ثوبان نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑا تھا تو یہود کے علماء میں سے ایک عالم آپ کے پاس آیا، وہ کہنے لگا ”اے محمد آپ پر سلام ہو تو میں نے اس کو ایسا دھکا دیا کہ قریب تھا کہ وہ گر جاتا۔ میں نے اسے کہا: تو نے یا رسول اللہ صلی اللہ علیہ وسلم کیوں نہیں کہا؟ یہودی نے کہا: ہم انہیں اس نام سے پکارتے ہیں جو ان کے گھر والوں نے ان کا نام رکھا ہے تو رسول اللہ علیم نے فرمایا: ” میرا وہ نام جو میرے گھر والوں نے رکھا ہے وہ محمد ہی ہے۔ یہودی نے کہا: میں آپ سے کچھ پوچھنے آیا ہوں۔ آپ نے اسے کہا: اگر میں تجھے اس کا بتا دوں تو تجھے اس کا","",{"f":"ہوگا تو وہ کہنے لگا: میں اس کو اپنے کانوں سے سنوں گا۔ آپ صلی اللہ علیہ وسلم کے پاس ایک چھڑی تھی آپ نے اس کے ساتھ زمین کو کریدا، آپ نے فرمایا: ”پوچھو؟“ یہودی نے کہا: جب اس زمین اور آسمان کے علاوہ دوسری زمین بدل دی جائے گی تو لوگ کہاں ہوں گے؟ آپ نے فرمایا: ”وہ پل کے اس طرف تاریکی میں ہوں گے“ اس نے کہا: سب سے پہلے کون لوگ گزریں گے؟ آپ نے فرمایا: ” فقراء مہاجرین “ یہودی نے کہا: جس وقت وہ جنت میں داخل ہوں گے تو ان کو کیا پیش کیا جائے گا؟ آپ نے فرمایا: ” مچھلی کے جگر کا زائد حصہ۔ یہودی نے کہا: اس کے بعد ان کا کھانا کیا ہوگا؟ آپ نے فرمایا: ” ان کے لیے جنت کا بیل ذبح کیا جائے گا۔ گا۔“ ( صحیح حدیث مدیث میں ”نور“ یعنی بیل کا لفظ آتا ہے ) یہ وہ بیل ہو گا جو اس کے اطراف میں چرتا پھرتا ہے۔اس نے کہا: پھر ان کا پینا کیا ہو گا؟ آپ نے فرمایا: ” وہ اس چشمے سے پئیں گے جس کا نام سلسبیل ہو گا۔“ یہودی نے کہا: آپ سچ فرما رہے ہیں اور آپ ملت عیلم واقعی نبی ہیں۔ اس نے کہا: اور میں آپ سے ایسی چیز پوچھنے آیا ہوں کہ جسے صرف نبی ہی جانتا ہے یا ایک دو اور آدمی۔ آپ نے فرمایا: ”کہ اگر میں تمہیں بتا دوں تو تجھے کوئی فائدہ ہوگا۔ اس نے کہا: میرے کان سنیں گے۔ آپ نے فرمایا: ”پوچھ؟ اس نے کہا: میں بچے کے متعلق پوچھنے آیا ہوں؟ آپ نے فرمایا: ” مرد کا پانی سفید اور عورت کا پیلا ہوتا ہے جب یہ دونوں اکٹھے ہو جاتے ہیں تو مرد کی منی عورت کی منی پر غالب آجائے تو اللہ کے حکم سے بچہ ہو جاتا ہے۔ اور اگر عورت کی منی مرد کی منی پر غالب آ جائے تو اللہ کے حکم سے بچی پیدا ہو جاتی ہے۔“ یہودی نے کہا: آپ صلی اللہ علیہ وسلم نے سچ فرمایا اور آپ ملنے کی تم واقعی نبی ہیں۔ پھر وہ واپس چلا گیا۔ نبی مٹے علیکم نے فرمایا: جو کچھ اس نے مجھ سے پوچھا ہے اس وقت تک اس کا مجھے علم نہ تھا حتی کہ اللہ نے مجھے اس کا علم عطا فرما دیا۔ یہ مکمل حدیث حضرت ثوبان سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں معاویہ بن سلام اکیلے ہیں۔\n(١) مذکورہ حدیث سے معلوم ہوا کہ اہل جنت کی سب سے پہلی مہمان نوازی مچھلی سے کی جائے گی۔\n(٢) دوسرا کھانا جنتی بیل کے گوشت کا ہو گا۔\n(٣) اور سب سے پہلا مشروب سلسبیل نامی چشمہ سے پلایا جائے گا۔\n(٤) یہ بھی معلوم ہوا کہ عورت اور مرد دونوں کے نطفے سے بچہ پیدا ہوتا ہے۔ جب مرد کی منی عورت کی منی پر غالب آ جاتی ہے تو تب بچہ اور جب عورت کی منی غالب ہو تب بچی پیدا ہوتی ہے۔ ٤٦٨"}],[468,"سیدنا ابو امامہ رضی اللہ عنہ بیان کرتے ہیں میں نے نبی الے علم کو فرماتے ہوئے سنا قرآن پڑھا کرو یہ اپنے پڑھنے والے کے لیے قیامت کے دن سفارشی ہو گا۔ دو روشن سورتیں البقرہ اور آل عمران بھی پڑھو یہ قیامت کے دن دو بادلوں کی طرح آئیں گی یا پرندوں کے دو جھنڈوں کی طرح صفیں باندھے ہوئے آئیں گی اپنے پڑھنے والے کے متعلق جھگڑا کریں گی۔ سورۃ البقرۃ پڑھا کرو اس کا پڑھنا باعث برکت ہے اور اس کا چھوڑ نا باعث حسرت ہے اور باطل ( جادوگر ) اس کی طاقت نہیں رکھتے۔“ یہ حدیث زید سے صرف معاویہ بن بیٹی ہی روایت کرتے ہیں۔","",{"k":"صحيح الجامع الصغير (١١٦٥)، المعجم الكبير للطبراني (١٢٦/٧، ٧٤٢٢)۔","f":"مذکورہ حدیث میں سورہ بقرہ اور آل عمران کی فضیلت کا بیان ہے۔ یہ دونوں سورتیں پڑھنے والوں کے حق میں سفارش کریں گی، قاری کی مغفرت کے لیے اللہ تعالیٰ سے جھگڑا کریں گی۔ سیدنا نواس بن سمعان کلابی خیلی اس لیے کہتے ہیں: میں نے نبی مکرم نے کو فرماتے ہوئے سنا ہے قیامت کے روز قرآن مجید لایا جائے گا اور جو لوگ قرآن پر عمل کرتے تھے وہ بھی لائے جائیں گے۔سورہ بقرہ اور سورہ آل عمران آگے آگے ہوں گی۔ اس کے بعد نبی معظم ملنے کی ہم نے ان دونوں سورتوں کی تین مثالیں دیں جنہیں میں آج تک نہیں بھولا۔\n(١) وہ دونوں سورتیں بادل کے دوٹکڑوں کی طرح ہوں گی یا\n(٢) دو کالے رنگ کی چھتریاں ہوں گی جن میں روشنی چمک رہی ہوگی یا\n(٣) دو قطار میں پرندوں کی ہوں گی وہ اپنے صاحب کی طرف سے جھگڑا کریں گی۔ (صحیح مسلم، کتاب صلاة المسافرين، باب فضل قراءة القرآن، رقم: ٨٠٥)"}],[469,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب امت پندرہ خصلتیں اپنائے گی تو ان کو مصیبت آجائے گی۔ (١) مال غنیمت اپنی دولت سمجھیں گے (٢) امانت کو غنیمت سمجھیں گے (٣) زکوۃ کو تاوان خیال کریں گے (٤) آدمی اپنی بیوی کی اطاعت کرے گا (٥) اپنی ماں کی نافرمانی کرے گا (٦) مسجدوں میں آوازیں بلند ہو جائیں (٧) آدمی اپنے دوست سے نیک سلوک رکھے گا (٨) اپنے باپ سے بدسلوکی کرے گا (٩) آدمی کی عزت اس کی شرارت سے بچنے کے لیے کی جائے گی (١٠) قوم کا ذمہ دار نہایت ذلیل شخص ہو گا (١) گانے والی عورتیں حاصل کی جائیں گی (١٢) اور گانے کے آلات استعمال کیسے جائیں گے (١٣) شراب پی جائیں گی (١٤) ریشم پہنے جائے گے (١٥) تو پھر شکلیں بدل جانے اور زمین میں دھنسنے کا انتظار کرو۔“ یہ حدیث یحیی سے صرف فرج بن فضالہ ہی روایت کرتے ہیں۔ ٤٧٠","",{"k":"سنن ترمذی (٢٢١٠)، السلسلة الضعيفة (١١٧٠)۔"}],[470,"سیدنا ابو ذر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ابو ذر! تیرا اس وقت کیا حال ہو گا جب تو گھٹیا لوگوں میں رہ جائے گا؟ اور آپ نے اپنے ایک ہاتھ کی انگلیاں دوسرے ہاتھ کی انگلیوں میں داخل کیں، تو میں نے عرض کیا: اللہ کے رسول! آپ مجھے کیا حکم فرماتے ہیں؟ آپ نے فرمایا: ”صبر ٢٩ کرنا، صبر کرنا۔ لوگوں سے ان کے طبائع اور ان کے مقام و مرتبے کے لحاظ سے معاملہ کرو اور ان کے اعمال میں ان سے موافقت نہ کرو۔“ یہ حدیث ابوذر سے اسی سند سے ہی مروی ہے اسے روایت کرنے میں ابو تو بہا کیلے ہیں۔ ٤٧١","",{"k":"السلسلة الضعيفة (١٨٦/٣، ١١٨٧)، مجمع الزوائد (٧/٢٨٣)۔"}],[471,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اس حال میں صبح کی کہ اسے دنیا کی فکر ہوئی تو اس کا اللہ تعالیٰ سے کوئی تعلق نہیں اور جو شخص مسلمانوں کا خیال نہ کرے تو وہ مسلمانوں میں سے نہیں ہو گا جس نے کسی مجبوری کے بغیر خوشی سے اپنے آپ کی بے توقیری کی تو وہ ہم میں سے نہیں ہے۔‘ یہ حدیث صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں یزید بن ابی ربیعہ ا کیلے ہیں۔ مذکورہ روایت کمزور ہے۔","",{"k":"السلسة الضعيفة (١/٣٨٧، ٣١٠)، مجمع الزوائد (١/١٩٢)۔"}],[472,"سیدنا عبداللہ ابن عباس والی جا سے روایت ہے کہ اللہ تعالیٰ کا یہ فرمان: أوْ آثَارَةٍ مِنْ عِلْم یا کوئی نقل شدہ علم\" کہتے ہیں یعنی عمدہ خط ( لکیر )۔‘ یہ حدیث ابن عون سے صرف عمرو بن الازھر ہی روایت کرتے ہیں۔","",{"k":"ضعيف الترغيب والترهيب (٢/١٧١، ١٨٨٢)۔"}],[473,"سیدنا یزید بن خمیر نے بیان کیا، میں نے عبد اللہ بن بسر سے سوال کیا پہلے لوگوں کے مقابلے میں ہمارا کیا حال ہو گا؟ انہوں نے کہا: سبحان اللہ! اگر وہ قبر سے باہر آ جائیں تو تمہیں نہ پہچان سکیں مگر یہ کہ تمہیں حالت نماز میں کھڑا پائیں۔“ یہ حدیث عبد اللہ بن بسر سے صرف یزید بن خمیر ہی روایت کرتے ہیں، اسے روایت کرنے میں صفوان بن عمر وا کیلئے ہیں۔ مذکورہ روایت سے پتا چلا کہ عبد الله بن بسر نے فرمایا کہ لوگوں نے اپنی عادتیں تبدیل کر لی ہیں، یعنی مسلمانوں والے کا مکو چھوڑ کر دوسروں کے کاموں میں مشغول ہو چکے ہیں۔ تا ہم نماز سے یہ ..:٤٧٤ پہچانے جا سکتے ہیں کہ یہ مسلمان ہیں۔","",{"k":"مجمع الزوائد (٢٠/١٠)، سنده حسن۔"}],[474,"سیدنا عبد اللہ بن زبیر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس شخص کو عمری دیا گیا تو وہ اس کے لیے اور اس کے بعد پچھلوں کے لیے بھی ہو گا جو بعد میں آئے گا وہ اس کا وارث ہو گا۔ اور جس کو رقھمی دیا گیا تو وہ عمری کی طرح ہی ہے۔ اسے حفص بن میسرہ، ابن زبیر سے روایت کرتے ہیں۔ عمری، عمر سے ماحوذ ہے یعنی وہ چیز جو زندگی بھر کے لیے دی جائے۔ یہ نام اس لیے رکھا گیا ہے کہ جاہلیت میں ایک آدمی کسی دوسرے آدمی کو گھر دیتا تو کہتا: میں نے اسے تیری عمر اور زندگی تک مباح قرار دیا ہے پھر کہا جاتا تھا کہ فلاں کے لیے عمری ہے۔ (المنجد: ص ٥٨٢) رقمی، مراقبہ سے ماخوذ ہے اس کا نام یہ اس لیے رکھا گیا ہے کیونکہ اس میں دونوں ایک دوسرے کے مرنے کا انتظار کرتے ہیں تا کہ وہ چیز اس کی طرف لوٹ آئے (جو زندہ رہ گیا ہے ) اس کی صورت یہ ہے کہ ایک شخص کسی کو کچھ ہبہ کرے اس شرط پر کہ اگر تم پہلے فوت ہو گئے تو یہ چیز میری طرف لوٹ آئے گی اور اگر میں پہلے فوت ہو گیا تو یہ تمہاری ہو جائے گی۔ (نیل الاوطار: ٧٤/٤)","",{"k":"مجمع الزوائد (٤/١٥٧)۔"}],[475,"سیدنا انس بھی اللہ سے روایت ہے کہ رسول اللہ نے ہم نے فرمایا: ” اپنی صفیں سیدھی رکھو کیونکہ صف کا سیدھا رکھنا نماز کے حسن (ادائیگی ) میں سے ہے۔ اسے مسعر سے صرف بشر بن السری ہی روایت کرتے ہیں اور بشر سے صرف ابن ابی عمر ہی روایت کرتے ہیں۔","",{"k":"صحيح مسلم (٤٣٥)، سنن ابو داؤد (٦٦٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ صفوں میں جڑ کر کھڑا ہونا، صف سیدھی رکھنا، یہ نماز کی خوبیوں میں سے ایک خوبی ہے بلکہ ابو داؤد میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: صفوں کو برابر کرنا نماز کی تکمیل کا حصہ ہے۔ سنن ابی داؤد، کتاب الصلاة، رقم: ٦٦٨) ٤٧٦"}],[476,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تین آدمی ہوں تو دو آدمی ایک کو چھوڑ کر آپس میں سرگوشی نہ کریں۔ اسے ابن عجلان سے صرف اُن کے بیٹے عبداللہ ہی روایت کرتے ہیں۔","",{"k":"صحیح مسلم (٢١٨٣)، سنن ابو داؤد (٤٨٥١)۔"}],[477,"سیدہ عائشہ بنی الہا فرماتی ہیں ایک آدمی نبی صلی اللہ علیہ وسلمن کی خدمت میں حاضر ہوا تو اس نے عرض کیا، اللہ کے رسول! اللہ کی قسم! آپ مجھے اپنی جان سے بھی زیادہ عزیز اور محبوب ہیں اور آپ مجھے گھر والوں اور اولاد سے بھی زیادہ پیارے ہیں۔ میں گھر میں آپ کو یاد کرتا ہوں تو میں صبر نہیں کرتا حتی کہ آپ کی خدمت میں حاضر ہو کر آپ کا دیدار کر لیتا ہوں۔ اور جب میں اپنی موت اور آپ کی موت کو یاد کرتا ہوں اور جانتا ہوں کہ آپ جنت میں جائیں گے اور انبیا السلام کے ساتھ ہوں گے اور اگر میں جنت چلا گیا تو مجھے ڈر ہے کہ میں آپ کو نہیں دیکھ سکوں گا تو آپ نے اسے جواب نہ دیا حتی کہ جبریل علی نام یہ آیت لے کر آ گئے: ﴿وَمَن يطع الله والرَّسُولَ فَأَوْلَعَكَ مَعَ الَّذِينَ أَنْعَمَ اللهُ عَلَيْهِمْ مِّنَ النَّبِيِّينَ وَالصَّدِيقِينَ الآية اور جو اللہ تعالیٰ اور اس کے رسول کی اطاعت کرے تو یہ ان لوگوں کے ساتھ ہو گا جن پر اللہ نے انعام فرمایا ہے انبیا بیلیم، صدیقین،شہداء اور صالحین۔“","",{"k":"مجمع السلسلة الصحيحة (٤٣٢/٦، ٢٩٣٣)، الزوائد : ٧/۔","f":"مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام رضی اللہ عنہم کو نبی معظم ملے ای ایم کے ساتھ بہت زیادہ محبت اور عقیدت تھی کہ جنت میں محرومی دیدار کا اندیشہ پیدا ہوا کہ نبی معظم صلی اللہ علیہ وسلم کا تو بہت اعلیٰ مقام ہو گا آپ لے کریم انبیا علیلا سلام کے ساتھ ہوں گے اور ہم کہیں نچلے درجے میں ہوں گے۔ تو اللہ ذوالجلال نے فرمایا: جنت میں پیغمبر کی رفاقت حاصل کرنے کے لیے اللہ اور رسول کی اطاعت کی ضرورت ہے۔ اور اس حدیث میں اللہ اور رسول کی اطاعت کا صلہ بتلایا جا رہا ہے ایک اور حدیث میں آتا ہے: ((المرء مع من احب)) آدمی اسی کے ساتھ ہوگا جس سے اس کو محبت ہوگی۔ (صحیح بخاری، كتاب الادب، باب علامة حب الله عز و جل صحيح مسلم، کتاب البر والصلة، رقم: ١٦٤٠)"}],[478,"سيدنا عبداللہ ابن عباس بیا اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” لونڈی پر جب تک وہ شادی شدہ نہ ہو حد نہیں ہے جب وہ شادی کر لے تو اس کی حد شادی شدہ آزاد عورت سے نصف ہوگی۔“ بسیدنا عبداللہ ابن عباس ریلی لا کا اپنا موقف تھا وہ قرآن کی اس آیت سے استدلال کرتے تھے فاذا احصن ” جب وہ شادی کر لیں۔ “ ( تب انہیں سزا دو )۔ (تفسیر فتح القدير: ٤٥٠/١) تا ہم بخاری شریف میں ہے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ اگر کوئی غیر شادی شدہ باندی زنا کرے (تو اس کا کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: کہ اسے کوڑے لگاؤ۔ اگر پھر زنا کرے تو پھر کوڑے لگاؤ۔ پھر بھی اگر زنا کرے تو اسے بیچ دوخواہ بالوں کی ایک رسی ہی کے بدلے میں وہ فروخت ہو۔ (صحیح بخاری، رقم: ٢١٥٣، ٢١٥٤)","",{"k":"السنن الكبرى للبيهقي (٢٤٣/٨)۔"}],[479,"سیدنا عبداللہ ابن عباس ریلی اینجا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے حاملہ عورت کے ساتھ وضع حمل سے قبل وطی کرنے سے منع فرمایا۔ اس سے مراد قیدی بن کر آنے والی حاملہ عورتیں ہیں جیسا کہ سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی مکرم ملے ہم نے او طاس کی قیدی عورتوں کے متعلق فرمایا: حاملہ سے اس وقت تک ہم بستری نہ کی جائے جب تک وہ حمل وضع نہ کر لے۔ اور غیر حاملہ کے ساتھ اس وقت تک ہم بستری نہ کی جائے جب تک وہ ایک حیض عدت نہ گزارے۔ (سنن ابی داؤد، رقم: ٢١٥٧، حاکم: ١٩٥/٢، احمد: ٢٨/٣) اس قسم کی لونڈیوں سے ہم بستری اس لیے منع ہے تا کہ براءت رحم حاصل ہو جائے یعنی کسی اور کے حمل میں اپنا نطفہ نہ ملا دیا جائے۔ یہاں یہ بھی یادر ہے کہ یہ علت جس طرح قیدی عورتوں میں ہے اسی طرح خریدی ہوئی بطور ہد یہ حاصل شدہ یا اس کی مثل کسی ذریعے سے حاصل کی ہوئی لونڈیوں کو بھی شامل ہے۔ ٤٨٠","",{"k":"سنن ابو داؤد (٢١٥٧)، ارواء الغليل (٥/١٣٩)، قال الالبانی: صحیح۔"}],[480,"سيده بسرة بنت صفوان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اپنی شرم گاہ کو ہاتھ لگایا اس پر وضو واجب ہو جاتا ہے۔ یہ حدیث مالک سے صرف ابو علقمہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ شرم گاہ کو چھونے سے وضو واجب ہو جاتا ہے۔ ایک دوسری حدیث میں ہے سیدنا طلق بن علی بنی المیہ سے روایت ہے کہ ایک آدمی نے عرض کیا: میں نے اپنی شرم گاہ کو چھوا ہے یا اس نے کہا کہ آدمی نماز میں اپنی شرم گاہ کو چھو لے تو کیا اس پر (دوبارہ ) وضو کرنا لازم ہے؟ نبی مکرم ملے تم نے فرمایا: نہیں! یہ تو تمہارے اپنے جسم کا ایک ٹکڑا ہے۔“ (سنن ابی داؤد، کتاب الطهارة رقم: ١٨٢، سنن ترمذی، رقم: ٨٥، اسناده صحیح بظاہر یہ دونوں احادیث متعارض ہیں۔ ان میں تطبیق یوں ہے کہ اگر کسی حائل ( مثلاً کپڑے وغیرہ) کے اوپر سے شرم گاہ کو چھوا جائے تو وضو نہیں ٹوٹتا اور اگر بغیر کسی حائل کے چھوا جائے تو وضو ٹوٹ جاتا ہے اس کی تائید اس بات سے ہوتی ہے کہ رسول اللہ ملنے کی ایم نے فرمایا: \"جو شخص اپنی شرم گاہ کو بغیر کسی پردے کے چھوٹے تو اس پر وضو واجب ہے۔ (مسند احمد: ٣٣٣/٢۔ مسند شافعی: ٣٤/١) سعودی مستقل فتوی کمیٹی نے بھی یہی فتویٰ دیا ہے۔ (فتاوی اللجنة: ٢٦٣/٥) البتہ فقہا نے اس مسئلے میں اختلاف کیا ہے۔ امام شافعی، احمد، مالک ڈیم کا موقف یہ ہے کہ شرم گاہ کو چھونے سے وضو ٹوٹ جاتا ہے (ان کی دلیل حدیث بسرہ ہے ) امام ابن حزم واللہ کا بھی یہی موقف ہے۔ (المحلی: ٣٣٩/١) جبکہ امام ابو حنیفہ، ابو یوسف، اور امام محمد کی رائے یہ ہے کہ شرم گاہ کو چھونے سے وضو نہیں ٹوٹتا۔ (انہوں نے حدیث طلق سے استدلال کیا ہے)۔ (نیل الاوطار: ٣٠٣/١ المغنی: ١٧٨/١):٤٨١ راجح بات یہ ہے کہ پردے کے بغیر چھوا جائے تو وضوٹوٹ جاتا ہے۔ درمیان میں پردہ حائل ہو تو وضو نہیں ٹوٹتا۔","",{"k":"سنن نسائی (٤٤٤)، سنن ابن ماجه (٤٨١)، قال الالبانی: صحیح۔"}],[481,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایک آدمی جنت میں داخل ہو گا تو جنت میں ہر گھر والا اور ہر کمرے والا اُسے خوش آمدید کہے گا اور اسے اپنی طرف دعوت دے گا۔ سیدنا ابو بکر بنی العین نے عرض کیا، اللہ کے رسول! آپ کیا خیال فرماتے ہیں کہ اس دن یہ شخص کون ہوگا؟ آپ نے فرمایا: ”جی ہاں! ابوبکر! وہ تم ہی ہو گے۔“ مذکورہ حدیث سے سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت معلوم ہوئی، جس طرح صدیق ول اللہ کو جنت کا ہر گھر والا آواز دے گا اسی طرح جنت کے آٹھوں دربان بھی بلائیں گے۔ جیسا کہ نبی مکرم مطلئے علیم نے فرمایا: جنت کا دربان ہر کسی کو آواز لگا کر کہے گا: ادھر سے داخل ہو جاؤ، جو نمازی ہو گا اسے نماز والے دروازے سے آواز آئے گی، جو روزے والا ہو گا اسے روزے والے سے آواز آئے گی۔ سیدنا ابو بکر صدیق ضل اللہ نے کہا: کیا کوئی ایسا بھی ہو گا جسے ہر دروازے سے آواز آئے گی؟ نبی مکرم طلت علیم نے فرمایا: ”ہاں ایسا بھی ہوگا اور میرا یقین ہے کہ تو ان میں سے ہے۔“ (صحیح بخاری، کتاب الصوم، رقم: ١٨٩٧) ٤٨٢","",{"k":"المعجم الكبير للطبرانی (٣٠٨/٩)، مجمع الزوائد (٤٦/٩)، صحيح ابن حبان (٦٨٦٧)۔"}],[482,"سیدہ ام کلثوم نے بیان کیا، بسرہ بنت صفوان میرے پاس آئیں تو انہوں نے مجھے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ”ام اکلثوم بنت عقبہ کو منگنی کا پیغام کس نے بھیجا؟“ میں نے کہا: فلاں اور فلاں نے۔ آپ نے فرمایا: تم نے عبد الرحمن بن عوف کو کیوں نظر انداز کر دیا ہے؟ وہ مسلمانوں کا سردار ہے اور ان میں سے نہایت پسندیدہ ہے۔\"","",{"k":"مستدرك حاكم (٣/٣٥٠)، سنده ضعيف۔"}],[483,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ایک ہی غسل سے اپنی (ایک سے زیادہ ) ازواج مطہرات کے پاس جاتے تھے۔ یہ حدیث از معمر از ثابت صرف سفیان بن عیینہ ہی روایت کرتے ہیں اور از سفیان ثوری وغیرہ از معمر از قتادہ اسے روایت کرتے ہیں۔","",{"k":"صحیح مسلم (٣٠٩)، سنن ابی داؤد (٢١٨)۔","f":"مذکورہ حدیث سے معلوم ہو آدمی ایک غسل کے ساتھ اپنی ایک سے زائد ازواج کے -ه ساتھ ہم بستری کرسکتا ہے۔"}],[484,"سیدنا عبداللہ ابن عمر بنی اہلیہ سے روایت ہے کہ جب نبی صلی اللہ علیہ وسلم کا موذن عشا کے وقت بارش والی رات ان کے پاس آتا تو آپ اسے حکم فرماتے کہ وہ اذان کے بعد یوں کہے: ((أَنْ صَلُّوا فِی رِحَالِكُمْ)) یعنی اپنے گھروں میں نماز ادا کرو۔“ مذکورہ حدیث سے معلوم ہوا کہ بارش یا اور کسی عذر کی وجہ سے گھر میں نماز پڑھ لینے کی اجازت ہے۔ ٤٨٥","",{"k":"صحیح بخاری (٦٦٦)، صحيح مسلم (١٠٦٣)۔"}],[485,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ملنے کریم نے فرمایا: ” کیا تمہیں معلوم ہے کہ جہنم کی آگ کی نسبت تمہاری آگ کی کیا مثال ہے؟ وہ تمہاری آگ کے دھوئیں سے ستر گنا زیادہ سیاہ ہے۔“ یہ حدیث امام مالک سے صرف معن ہی روایت کرتے ہیں، اسے روایت کرنے میں ابراہیم بن منذر","",{"k":"صحيح الترغيب والترهيب (٢٤٦/٣)، المعجم الكبير للطبراني (١٩/١٢٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ دنیا کی آگ سے جہنم کی آگ ستر گنا سخت ہے۔ یہی وجہ ہے کہ نبی مکرم اللہ علیم نے فرمایا: ” قیامت کے دن سب سے ہلکے عذاب والا وہ شخص ہو گا جس کے قدموں کے نیچے آگ کا انگارہ رکھا جائے گا اور اس کی وجہ سے اس کا دماغ کھول رہا ہو گا۔“ (صحیح بخاری، رقم: ٦٥٦١) ٤٨٦"}],[486,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عز وجل فرماتا ہے: بے شک میں نے ایک آدمی کے لیے اس کے جسم کو صحیح و تندرست کر دیا اور اس پر رزق وسیع کر دیا، پھر بھی اس نے میری طرف ہر چار سال میں حج و عمرہ کے لیے قصد نہ کیا تو وہ شخص نہایت بدنصیب ہے۔“ یہ حدیث سفیان سے صرف عبدالرزاق ہی روایت کرتے ہیں۔","",{"k":"السلسلة الصحيحة (١٦٦٢)، صحيح الجامع الصغير (١٩٠٩)، سنن الكبرى للبيهقى ٢٦٢/٥۔","f":"مذکورہ حدیث سے معلوم ہوا کہ استطاعت رکھنے والے کو چار، پانچ سال کے بعد حج کرنا چاہیے، جس حدیث میں ہے کہ نبی مکرم ملنے علیم سے سوال کیا گیا کیا حج ہر سال فرض ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” ایک مرتبہ ہی واجب ہے جو زیادہ کرے گا تو وہ نفلی ہو گا۔“ (سنن ابی داؤد، كتاب المناسك، رقم: ١٧٢١، سنن ابن ماجه رقم: ٢٨٨٦، اسنادہ صحیح) یہ حدیث ان احادیث سے متعارض نہیں ہے بلکہ صاحب استطاعت مسلمان پر حج زندگی میں صرف ایک مرتبہ فرض ہے، لیکن جن کو اللہ ذوالجلال نے ہمت دی ہے استطاعت ہے تو ان کو چاہے کہ چار پانچ سال بعد وہ حج کریں یہ فرض نہیں بلکہ نفلی حج ہو گا جو نہ جائے گا وہ بدنصیب ہے کیونکہ حج کا بہت زیادہ ثواب ہے اور ثواب سے محرومی بدنصیبی کے علاوہ کچھ نہیں۔ ٤٨٧"}],[487,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا لوگوں میں سے آپ میم کو کس سے زیادہ محبت ہے؟ آپ سے تم نے فرمایا: \"عائشہ بنایا جب لوگوں نے کہا ہم عورتوں سے متعلق نہیں پوچھ رہے۔ آپ ملے سلیم نے فرمایا: ” تب اس کا باپ ( مجھے بہت محبوب ہے۔)‘“ مذکورہ حدیث سے معلوم ہوا کہ نبی علی نام کو تمام صحابہ کرام رضی اللہ عنہم میں سے سیدنا ابوبکر صدیق بنی اہلیہ سے زیادہ محبت اور پیار تھا۔ جمہور علماء کا بھی یہی موقف ہے کہ تمام صحابہ میں سیدنا ابو بکر صدیق نبی الیہ سے افضل ہیں۔ سیدنا ابو بکر نبی الیہ کی فضیلت کے متعلق دیکھئے: ٤٨٨","",{"k":"مسلم، رقم : ٢٣٨٤ . صحیح بخاری، صحيح۔"}],[488,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ العلیم نے فرمایا: ”اے بنی طلحہ! تم یہ (ڈول) یعنی کعبہ کی دربانی لے لو ہمیشہ ہمیشہ کے لیے تم سے کوئی ظالم ہی اس کو چھین سکتا ہے۔“ یہ حدیث ابن ابی ملیکہ سے صرف عبد اللہ بن مؤمل ہی روایت کرتے ہیں، اسے روایت کرنے میں معن بن عیسی ہی روایت کرتے ہیں۔","",{"k":"تفرد به معن بن عیسی مجمع الزوائد (٣/٢٨٥)۔","f":"مذکورہ حدیث سے سیدنا عثمان بن مظعون ضیا اللہ کی فضیلت معلوم ہوئی اللہ ذوالجلال نے ان کی شان میں درج ذیل آیت نازل فرمائی: ه إنَّ اللهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْآمَنتِ إِلَى أَهْلِهَا﴾ (النساء: ٥٨) اللہ تعالیٰ تمہیں تا کیدی حکم دیتا ہے کہ تم امانت والوں کی امانتیں انہیں پہنچا دو۔“ تو نبی مکرم علی علیہم نے انہیں خانہ کعبہ کی چابیاں دے کر فرمایا: یہ تمہاری چابیاں ہیں آج کا دن وفا اور نیکی کا دن ہے۔ (ابن کثیر ) اب تک سیدنا عثمان بن مظعون نیل الہیہ کے خاندان کے پاس بیت اللہ شریف کی چابیاں موجود ہیں۔ ٤٨٩"}],[489,"سيدنا عمر و بن امیہ ضمری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے تین آدمی بھیجے۔ ایک قیصر کی طرف، ایک کسریٰ کی طرف اور ایک اسکندریہ کی طرف۔ عمرو بن العاص نبی اللہ کو نجاشی کی طرف بھیجا۔ جب عمر و یا یہ نجاشی کے پاس پہنچے تو انہوں نے دیکھا کہ جو بھی اس کے پاس آتا تھا وہ اس کے پاس سینے پر ہاتھ رکھ کر سر جھکائے کھڑکی سے داخل ہوتا تھا، جب عمرو نے کھڑکی دیکھی اور ان کے اندر جانے کا طریقہ دیکھا تو پیٹھ پھیر لی اور الٹے پاؤں چل کر اندر گئے جب اندر چلے گئے تو برابر سیدھے کھڑے ہو گئے تو حبشی گھبرا گئے اور انہیں قتل کرنے کا ارادہ کرنے لگے۔ انہوں نے سیدنا عمروضی الیہ سے پوچھا: کیا وجہ ہے کہ تم ہمارے طریق کے مطابق اندر داخل نہیں ہوئے؟ انہوں نے فرمایا: ہم اس طرح تو اپنے نبی سے بھی نہیں کرتے۔ حالانکہ اگر اس طرح کیا جائے تو وہ اس کے زیادہ حق دار ہیں۔ نجاشی نے کہا: اسے چھوڑ دو اس نے سچ کہا ہے۔“ یہ حدیث عمرو بن امیہ سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔","",{"k":"مجمع الزوائد (٣٩/٨)، اسناده ضعيف۔"}],[490,"سيدنا عبد الرحمن بن عثمان تیمی کہتے ہیں میں نے رسول اللہ نے تم کو دیکھا کہ جب عیدین سے فارغ ہوتے تو آپ نماز کی جگہ کے درمیان آکر کھڑے ہو جاتے، پھر لوگوں کی طرف دیکھتے کہ وہ کس طرف جاتے ہیں، اور ان کی کیا سمت ہے پھر تھوڑی دیر ٹھہرتے اور پھر چل پڑتے۔“ یہ حدیث عبدالرحمن بن عثمان سے اسی سند سے مروی ہے، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔ ٤٩١","",{"k":"مجمع الزوائد (٢٠٦/٢)، اسناده ضعيف۔"}],[491,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم اور ہم بھی آپ کے ساتھ بنی عبد مناف کے دروازے سے داخل ہوئے یہ وہی دروازہ تھا جس کو لوگ باب بنی شیبہ کہتے ہیں۔ ہم آپ کے ساتھ مدینہ کی طرف باب الحزورہ کی طرف گئے جس کو باب الخیاطین بھی کہتے ہیں۔“ یہ حدیث مالک سے ورس صرف عبداللہ بن نافع ہی روایت کرتے ہیں، اسے روایت کرنے والے مروان بن ابی مروان اکیلے ہیں۔ المعجم الكبير للطبراني: ١١ / ١٥٨، مجمع الزوائد: ٣/",""],[492,"سیدنا علی رضی اللہ عنہ سے متعلق مروی ہے کہ انہوں نے حجر اسود کو بوسہ دیا اور کہا: ((أيْمَانًا بِكَ وَتَصْدِيقاً بِكِتَابِكَ وَاِتِّباعاً سُنَّةَ نَبِيَّكَ . ( ) ''اے اللہ! تجھ پر ایمان لاتے ہوئے، اور تیری کتاب کی تصدیق کرتے ہوئے، اور تیرے نبی کی سنت کی پیروی کرتے ہوئے","",{"k":"المعجم الكبير للطبرانی (٣٠٢/١١)، السلسلة الضعيفة (٣/٤٨، ١٠٤٩)۔"}],[493,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما کہتے ہیں: سیدنا عمر بن الخطاب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مردوں کی بہترین صف ان کی پہلی اور ان کی بری صف آخری ہے جب کہ عورتوں کی بہترین صف ان کی آخری اور بری صف پہلی ہے۔“ یہ حدیث حضرت عمر بن خطاب سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ مردوں کی پہلی اور عورتوں کی آخری صف بہترین صف ہے۔ مردوں کی پہلی صف اس لیے بہترین ہے کیونکہ پہلی صف کی فضیلت رسول اللہ میم نے بطور خاص بیان فرمائی ہے فرمایا: ”اگر لوگوں کو اذان اور پہلی صف کے اجر کا علم ہو جائے تو وہ انہیں صرف قرعہ اندازی کے ذریعے ہی حاصل کر سکیں تو ضرور قرعہ ڈالیں۔“ (صحیح مسلم، کتاب الصلاة، رقم: ٦٦٠) ایک دوسرا فرمان یوں ہے کہ اللہ تعالیٰ اور اس کے فرشتے پہلی صفوں پر رحمت نازل فرماتے ہیں۔ (صحیح سنن ابی داؤد، رقم: نیز اس لیے بھی اسے بہتر کہا گیا ہے کیونکہ اس میں انسان امام کے قریب ہوتا ہے، وعظ ونصیحت کے وقت کامل یک سوئی اختیار کرتا ہے اور عورتوں کے ساتھ اختلاط سے بھی بچارہتا ہے وغیرہ وغیرہ۔ جبکہ آخری صف میں یہ","",{"k":"صحیح مسلم (٤٤٠)، سنن ابو داؤد (٦٧٨)، سنن ترمذی (٢٢٤)۔","f":"حاصل نہیں ہوتے، عورتوں کی آخری صف کو اس لیے بہتر کہا گیا ہے کیونکہ ان کے حق میں پردہ اور مردوں کی نظروں سے دوری ہی بہتر ہے۔ لیکن یہ اس صورت میں ہے جب عورتیں مردوں کے پیچھے نماز پڑھیں اور جب عورتیں مردوں سے الگ مقام پر نماز پڑھیں تو پھر ان کی پہلی صف بھی افضل ہو سکتی ہے۔"}],[494,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: گذشتہ امتوں کی عمر کے مقابلے میں تمہاری عمر ایسے ہے جیسے عصر سے غروب آفتاب کا وقت ہوتا ہے۔‘ مالک سے صرف معن ہی روایت کرتے ہیں، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ پہلی امتوں کی عمریں بہت طویل تھیں اور اس امت کی عمریں چھوٹی ہیں، گویا کہ اگلی امتوں کی عمریں طلوع آفتاب سے عصر تک اور ہماری عصر سے لے کر غروب آفتاب تک جو اگلے وقت کی ایک چوتھائی ہے۔","",{"k":"صحیح بخاری (٥٠٢١)، سنن ترمذی (٢٨٧١)۔"}],[495,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ”اگر وہ انکار کرے تو اس کو واپس کرو اگر وہ انکار کرے تو اس سے لڑائی کرو کیونکہ وہ شیطان ہے یعنی نمازی کے آگے سے گزرنے والا۔ یہ حدیث صفوان سے صرف الدر اور دی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جب نمازی نے سترہ رکھا ہو اور کوئی اس کے اور سترے کے درمیانی فاصلے سے گذرنا چاہے تو نمازی کو اسے پہلے اشارے وغیرہ سے روکنا چاہیے لیکن اگر گزرنے والا نہ رکے تو اس سے لڑائی بھی کی جاسکتی ہے۔ جمہور علماء نے اس عمل کو مستحب جبکہ اہل ظاہر نے اسے واجب قرار دیا ہے۔ یہ بھی معلوم ہوا کہ اتنے عمل سے نماز باطل نہیں ہوتی۔ (فتح الباری: ١٦٧/٢، شرح مسلم للنووى: ٤٦٤/٢)","",{"k":"صحیح بخاری، رقم ة (٥٠٩)، المعجم الصغير للطبراني ٥٧/١ (٥٤)۔"}],[496,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی السلام نے فرمایا: ” جب رات کا کھانا آ جائے اور نماز کے لیے تکبیر بھی کہہ دی جائے تو پہلے کھانا کھالو۔“ یہ حدیث از معمر از قتادہ صرف عبد الله بن مبارک ہی روایت کرتے ہیں۔","",{"k":"صحیح مسلم (٥٥٧)، سنن الكبرى للبيهقى (٧٢٣، سنن ترمذی (٣٥٣)۔","f":"یہ حکم اس لیے دیا گیا ہے تا کہ انسان پوری توجہ اور کامل خشوع و خضوع سے نماز ادا کر سکے کیونکہ عین ممکن ہے کہ اگر انسان اس صورت میں بھی کھانا چھوڑ کر نماز شروع کر دے تو اس کا دھیان نماز میں کھانے کی طرف ہی لگا رہے اور وہ نماز میں یک سوئی اختیار نہ کر سکے جو حقیقی مطلوب شریعت ہے۔ اس حدیث سے یہ بھی اخذ کیا جا سکتا ہے کہ انسان کو ہر ایسے کام سے اجتناب کرنا چاہیے جو نماز میں غفلت اور حضور قلب کے خاتمے کا سبب بنے۔ جمہور علماء کا موقف ہے کہ اس حدیث میں جو کھانے کو نماز سے پہلے تناول کرنے کا حکم ہے وہ استحباب کے لیے ہے جب کہ اہل ظاہر نے اسے وجوب پر محمول کیا ہے۔"}],[497,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”اے بنی عبد مناف! اے بنی عبد المطلب! اگر تم اس مسجد کے معاملے کے ذمہ دار بنائے جاؤ تو اس بیت اللہ شریف کا طواف کرنے اور اس مسجد میں نماز پڑھنے سے کسی کو منع نہ کرو چاہے دن اور رات کی جس گھڑی میں کوئی نماز پڑھے۔ یہ حدیث از ابن جریج از عطاء از حضرت ابن عباس صرف سلیم بن مسلم ہی روایت کرتے ہیں۔","",{"k":"٠٨٨٠ سنن ابو داؤد (١٨٩٤)، سنن ترمذی (٨٦٨)، قال الالبانی: صحیح۔","f":"صحیح احادیث میں ایک عام حکم وارد ہے کہ نماز فجر کے بعد نماز نہیں حتی کہ سورج اچھی طرح واضح ہو جائے اور عصر کے بعد نماز نہیں حتی کہ سورج غروب ہو جائے۔(صحیح بخاری، کتاب مواقیت الصلاة، رقم: صحیح مسلم، رقم: ٨٢٧) الہذا یہ فرمان اس کا مخصص ہے کہ بیت اللہ میں عصر کے بعد اور اسی طرح فجر کے بعد طواف جائز ہے چنانچہ اس کے بعد ان ممنوعہ اوقات میں طواف کی رکعتیں بھی جائز ہوں گی۔"}],[498,"سیدنا عبداللہ ابن عباس ولی اللہ سے روایت ہے کہ نبی ملنے ہیم نے فرمایا: ”جس شخص نے رات گزاری اور اس کے ہاتھ پر چکناہٹ ہو، پس کوئی چیز اسے تکلیف پہنچا دے تو پھر وہ صرف اپنی ذات ہی کو ملامت کرے۔ یہ حدیث از سفیان از زهری از عبید اللہ صرف زبیر بن بکار ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کھانا کھانے کے بعد ہاتھ دھونا مستحب ہے بالخصوص سونے سے پہلے کیونکہ چکنائی کی بو پا کر کوئی کیڑا مکوڑا کاٹ سکتا ہے۔","",{"k":"سنن ابو داؤد (٣٨٥٢)، قال الالبانی:صحیح۔"}],[499,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” یہ مکہ ہے اس کو اللہ نے اس دن حرام قرار دیا جس دن آسمانوں اور زمین کو پیدا کیا تو یہ قیامت کے دن تک کے لیے حرام ہے نہ اس کا گھاس کاٹا جائے اور نہ اس کا درخت کاٹا جائے اور نہ اس کا شکار بھگایا جائے اور اعلان کرنے والے کے علاوہ کوئی شخص وہاں کی گری ہوئی چیز نہ اٹھائے۔“ تو سیدنا عباس رضی اللہ عنہ نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! مگر اذخر گھاس؟ فرمایا: ”ہاں صرف اذخر گھاس کا کاٹنا درست ہے )۔ یہ حدیث سفیان سے صرف سعید بن عبدالرحمن ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مکہ حرم ہے اس میں قتل وخون ریزی، جانور کا شکار کرنا یا درخت وغیرہ کا ئنا حرام ہے۔ مدینہ منورہ کی حرمت کا بھی یہی مفہوم ہے۔ مذکورہ حدیث سے یہ بھی معلوم ہوا کہ مکہ میں گری پڑی چیز وہی اٹھا سکتا ہے جو اس کے اعلان و تشہیر کا ارادہ رکھتا ہے۔ یہ بھی معلوم ہوا کہ صرف اذخر گھاس کو کاٹا جاسکتا ہے۔","",{"k":"صحیح بخاری (١١٢)۔"}],[500,"”سیدنا عبداللہ ابن عباس بنی پہنچا سے روایت ہے کہ ”نبی صلی اللہ علیہ وسلم نے انہیں اپنے اپنے اہل خانہ کے ضعیف افراد ( عورتوں اور بچوں) میں مزدلفہ سے منی کی طرف پہلے بھیج دیا تھا۔“ اسے سفیان سے صرف بشر ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کمزور، بیمار، بوڑھے، بچے اور عورتیں وغیرہ مزدلفہ میں پوری رات گزارے بغیر بھی منی جا سکتے ہیں۔ جیسا کہ سیدہ عائشہ ضیا فیہا سے مروی ہے کہ سیدہ سودہ بنی الجھا نے مزدلفہ کی رات آپ کے علم سے اجازت طلب کی کہ وہ آپ صلی اللہ علیہ وسلم سے پہلے واپس آجائیں ( یہ اجازت انہوں نے اس لیے طلب کی ) بھاری جسم والی تھیں (لہذا آہستہ آہستہ چلتی تھیں) آپ صلی اللہ علیہ وسلم نے انہیں اجازت دے دی۔ (صحیح بخاری، کتاب الحج، رقم: ١٦٨٠، صحیح مسلم، رقم: ١٢٩٠)","",{"k":"السلسلة الصحيحة (١٢٩٣)، سنن ابو داؤد (١٩٣٩)۔"}],[501,"سیدنا عبداللہ ابن عباس زنی اینجا نے بیان کیا، سیدنا عمر بن خطاب رضی اللہ عنہ نے مجھے سحری کے کھانے پر دعوت دی اور فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اس کا نام مبارک کھانا رکھا ہے۔“ یہ حدیث حضرت عمر سے صرف اسی سند سے مروی ہے، ہم کو معلوم نہیں کہ ابن عیینہ نے محمد بن ابراہیم، ابو معمر عیسی بن السر بی حجوافی کوفی کے بھائی سے روایت کی ہو۔ مذکورہ حدیث سے معلوم ہوا کہ سحری کو غدا ( یعنی صبح کا کھانا ) کہنا جائز ہے۔ یہ بھی معلوم ہوا کہ سحری کا کھانا مبارک ہے۔ اگر انسان کو چاہت نہ بھی ہو تب بھی ایک دو لقمے یا کھجور، یا کسی مشروب کے چند گھونٹ ضرور لے لینے چاہئیں تا کہ اس برکت سے حصہ مل جائے۔ سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بلاشبہ اللہ تعالیٰ سحری کھانے والوں پر رحمت بھیجتا ہے اور فرشتے ان کے لیے دعا کرتے ہیں۔ (صحیح الترغيب و الترهيب، رقم: ١٠٦٦) وهو","",{"k":"السلسلة الصحيحة (٢٩٨٣)، سنن ابو داؤد (٢١٣)، سنن نسائی (٢١٦٣)۔"}],[502,"سیدہ عائشہ بینی انہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو اٹھتے تو آپ کے لیے مسواک اور وضو کا پانی رکھ دیا جاتا۔ اسے سعد سے صرف زرارہ اور زرارہ سے صرف بہر ہی روایت کرتے ہیں، اسے روایت کرنے میں حماد بن سلمہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ رات کو اٹھنے کے بعد مسواک اور وضو کرنا مستحب ہے۔ کیونکہ مسواک کرنے کے بہت زیادہ فواید ہیں۔ سب سے بڑا","",{"k":"سنن ابو داؤد (٥٦)۔","f":"یہ ہے کہ مسواک اللہ تعالیٰ کی رضا مندی کا ذریعہ ہے اور اس سے منہ بھی پاک صاف ہو جاتا ہے۔ اور یہ بات روز روشن کی طرح واضح ہے کہ اللہ تعالیٰ کے پسندیدہ کام کرنے ہی سے اس کی رضا مندی حاصل ہوتی ہے لہذا مسواک کرتے وقت بھی یہی نیت اور ارادہ ہو کہ اس سے ہمارا اللہ ہم سے راضی ہو جائے گا۔"}],[503,"سیدنا انس بنی اہلیہ نے بیان کیا، ہم رسول اللہ علیم کے زمانے میں نماز مغرب سے قبل دو رکعت نماز پڑھا کرتے تھے۔ یہ حدیث مختار سے صرف منصور ہی روایت کرتے ہیں، اسے روایت کرنے میں سعید بن سلیمان اکیلے ہیں۔","",{"k":"صحیح بخاری (٧٢٥)، سنن ابو داؤد (١٢٨٢)۔","f":"ناندن . ایک اور حدیث ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مغرب سے پہلے نماز پڑھو، مغرب سے پہلے نماز پڑھو، پھر تیسری مرتبہ فرمایا؛ ( یہ حکم اس کے لیے ہے) جو پڑھنا چاہے آپ صلی اللہ علیہ وسلم نے یہ اس کراہت کے باعث فرمایا کہ کہیں لوگ اسے سنت (لازمہ) نہ بنالیں۔ (صحیح بخاری، کتاب الجمعة، رقم: ١١٨٣، سنن ابی داؤد، رقم: (١٢٨١) تیسری حدیث میں ہے کہ نبی مکرم ملے ہم نے مغرب سے پہلے دورکعتیں ادا فرمائیں۔ (ابن حبان، رقم: ٦١٧) معلوم ہوا کہ غروب آفتاب کے بعد اور نماز مغرب سے پہلے دو رکعت نفل نماز مستحب ہے اور یہ آپ ملنے کی یکم سے قولی، فعلی، اور تقریری (حدیث کی تینوں اقسام) سے ثابت ہے۔ اس لیے اذان اور جماعت مغرب کے درمیان اتنا وقفہ ہونا چاہیے کہ نمازی دو نفل ادا کر سکے اور حدیث کے ان الفاظ کہ کہیں لوگ اسے سنت نہ بنالیں کا مقصد یہ نہیں کہ آپ صلی اللہ علیہ وسلم نے ان رکعات کو مستحب نہیں سمجھا، بلکہ ان سے مقصود یہ ہے کہ کہیں لوگ ان رکعات کو ایسا مستقل طریقہ نہ بنالیں کہ پھر جسے چھوڑ نا نا جائز سمجھیں حالانکہ ان رکعات کو چھوڑنے میں بھی کوئی گناہ نہیں۔ ٥٠٤"}],[504,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے نزد یک احسان کے لحاظ سے سیدنا ابو بکر نیا لینے سے بڑھ کر اور کوئی نہیں۔ اس نے اپنے مال اور جان سے میری غم خواری کی اور اپنی بیٹی کا مجھ سے نکاح کر دیا۔ یہ حدیث ابن جریج سے صرف ارطاۃ ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن صالح اکیلے ہیں۔ مذکورہ حدیث میں سیدنا ابو بکر ضیا اللہ کی فضیلت کا اثبات ہے نبی معظم ملنے کی تم پر احسانات کے اعتبار سے سب سے زیادہ احسانات سیدنا ابو بکر رضی اللہ عنہ کے ہیں۔ جیسا کہ بخاری شریف میں بھی آتا ہے کہ نبی مکرم لے ہم نے فرمایا: ” اپنی صحبت اور مال کے ذریعہ مجھ پر سیدنا ابو بکر رضی اللہ عنہ کا سب سے زیادہ احسان ہے، اگر میں رب کے علاوہ کسی اور کو دوست بنا تا تو سیدنا ابوبکر بنی ان کو بناتا “ (صحیح بخاری، کتاب المناقب، رقم: ٣٦٥٤)","",{"k":"السلسلة الصحيحة (٢١٣/٥، ٢٢١٤)، صحيح الجامع الصغير، رقم :، ٥٥١٧ مجمع الزوائد (٤٦/٩)۔"}],[505,"سیدنا ابو یعلی بنی المیہ نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک جنگ میں تھے تو پالتو گدھوں کے گوشت سے ہنڈیاں اہلنے لگیں تو آپ نے ان کے گرا دینے کا ہمیں حکم دیا، اور ہم میں سے ہر دس آدمیوں کے لیے ایک بکری تقسیم کی۔“ یہ حدیث ابو خالد سے صرف ہاشم ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن عمران اکیلے ہیں۔","",{"k":"مجمع الزوائد (٥/٤٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نبی مکرم نے علیم نے اپنے صحابہ کرام رضوان اللہ علیہم اجمعین کو پالتو گدھے کھانے سے روک دیا، یہ غزوہ خیبر کے موقع پر حرام کیا گیا تھا۔ (صحیح بخاری، کتاب المغازي، رقم: ٤١٩٨)"}],[506,"سیدنا اسامہ بن زید ضیا الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ” کوئی مسلمان کافر کا وارث بن سکتا نہ کا فرکسی مسلمان کا۔ یہ حدیث حضرت قیس سے صرف علی بن جعد ہی روایت کرتے ہیں۔ اس حدیث سے معلوم ہوا کہ نہ تو کافر مسلمان کا وارث بن سکتا ہے اور نہ ہی مسلمان کافر کا۔ جمہور علماء اسی کے قائل ہیں۔ اور بعض اہل علم نے تو اس پر اجماع کا دعویٰ کیا ہے، البتہ امام احمد جماللہ نے کہا ہے کہ مسلمان اپنے آزاد کردہ کا فر غلام کا وارث ہو سکتا ہے کیونکہ حدیث میں ہے ((الولاء لمن اعتق)) ولاء ( آزاد کردہ غلام کا سازوسامان ) اس کا ہے جس نے آزاد کیا۔“ (المغنی: ٣٤٨/٦)","",{"k":"٦٧٦٤ صحیح بخاری، رقم : صحیح مسلم، رقم : ١٦١٤ . فائده۔"}],[507,"\"سیدنا انس رضی اللہ عنہ نے بیان کیا، ام سلیم نے مجھے رسول اللہ صلی اللہ علیہ وسلمن کی طرف بھیجا، کیونکہ انہوں نے آپ کے لیے کھجوروں اور پنیر کا حلوہ بنایا تھا میں نے آپ کو ان کے ایک درزی غلام کے گھر پایا اُس نے بھی آپ کے لیے ایک کھانا بنایا جس میں مکئی اور کدو تھے تو آپ کدو کھانے لگے اور اپنی انگشت شہادت سے ملکئی الگ کرنے لگے میں نے کہا: اللہ کے رسول مستم! ام سلیم نے آپ کے لیے کھجور اور پنیر کا حلوہ بنایا ہے اور وہ چاہتی ہیں کہ آپ اس میں سے تناول فرمائیں۔ پس آپ تشریف لائے اور اس میں سے کچھ کھایا۔ ام سلیم نے عرض کیا، اللہ کے رسول! انس کے لیے دعا فرما ئیں تو آپ نے فرمایا: اے اللہ! اس کی عمر دراز فرما، اس کا مال اور اولاد زیادہ کر اور اس کو معاف فرما۔ یہ حدیث معاذ الاعور سے صرف حماد بن زید ہی روایت کرتے ہیں، اسے روایت کرنے میں خالد بن خداش اکیلے ہیں۔","",{"k":"♦، السلسلة الصحيحه (٦/٤٠، ٢٥٤١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ درازئی عمر، مال اولاد کی برکت کی دعا کرنا مستحب ہے۔ سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ ((فد عالى بثلاث، فدفنت مائة وثلاثة، وان ثمرتي لتطعم في السنة مرتين، وطالت حياتى حتى استحييت من الناس، وارجوا المغفرة)) \" آپ صلی اللہ علیہ وسلم نے تین چیزوں کی دعا فرمائی تھی (اولاد کی کثرت کا یہ حال ہے ) میں (اپنی اولاد میں سے ) ایک سوتین کو دفن کر چکا ہوں ( مال کی کثرت کا یہ حال ہے ) کہ میرے پھل سال میں دوبار کھائے جاتے ہیں اور میری زندگی اتنی دراز ہوگئی کہ میں لوگوں سے شرمانے لگا ہوں اور ( تیسری دعا کے مطابق ) میں مغفرت کی امید بھی رکھتا ہوں۔“ (صحیح بخاری: ادب المفرد، رقم: ٦٥٣، اسناده صحيح)"}],[508,"سيدنا حسن رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر یہ بات نہ ہوتی کہ کتے بھی دیگر مخلوقات کی طرح ایک مخلوق ہیں تو میں ان کو مار ڈالنے کا حکم دیتا پس تم ان میں سے ہر کالے سیاہ کتے کو مار ڈالو۔“ مذکورہ حدیث سے معلوم ہوا کہ کالے کتے کو مارنا جائز ہے۔ ایک حدیث میں ہے کہ نبی مکرم طلع علیم نے فرمایا: ” کالا کتا شیطان ہے۔“ (صحیح مسلم، رقم: ٥١٠، سنن ابی داؤد، رقم: ٧٠٢)","",{"k":"سنن ترمذی، سنن ابو داؤد (٢٨٤٥)، قال الالباني : صحیح۔"}],[509,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”لوٹنے والے، جھپٹا مار کر چھینے والے اور خیانت کرنے والے پر ہاتھ نہیں کاٹا جائے گا۔ یہ حدیث زہری سے صرف یونس ہی روایت کرتے ہیں اور یونس سے صرف ابن وہب ہی روایت کرتے ہیں، اسے روایت کرنے میں ابو معمرا کیلے ہیں۔","",{"k":"٠١ سنن نسائی (٤٩٧٥)، سنن ابو داؤد (٤٣٩٢)، قال الالبانی:صحیح۔","f":"منتهب: جوز بر دستی غلبہ پا کر مال چھین لے، قوت یا اسلحہ کے زور پر۔ مختلس: جو کسی کا مال جھپٹا مار کر سلب کرے۔ خَائِن: وہ ہے جو ظاہر خیر خواہ ہو جبکہ خفیہ دھوکہ وفریب کرنے والا ہو۔ معلوم ہوا کہ ان تینوں کا ہاتھ نہیں کاٹا جائے گا۔ شافعیہ اور حنفیہ اسی کے قائل ہیں۔ (تحفة الاحوذی: ٨٣٥/٤) جبکہ امام احمد جماللہ نے کہا ہے کہ ان سب کا ہاتھ کاٹا جائے گا۔ (نیل الاوطار: ٥٨٣/٤) امام نووی حاللہ نے فرمایا کہ قاضی عیاض اللہ نے فرمایا: اللہ تعالیٰ نے ہاتھ کاٹنے کی سزا چور پر واجب کی ہے جبکہ اس کے علاوہ اختلاس، انتہاب اور غصب میں نہیں۔ (شرح صحیح مسلم، رقم: ١٩٩/٦) پہلا موقف ہی راجح ہے۔"}],[510,"سیدنا عبداللہ ابن عمر ضیا اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”محرم (حالت احرام والا ) نکاح کرے نہ پیغام نکاح بھیجے اور نہ اس پر پیغام نکاح بھیجا جائے اور نہ ہی تم میں سے کوئی شخص اپنے (مسلمان) بھائی کی بیع پر بیع کرے اور نہ اپنے بھائی کے پیغام نکاح پر پیغام نکاح بھیجے الا یہ کہ وہ اجازت دے دے (تو درست ہے۔ یہ حدیث از حضرت نافع از حضرت ابن عمر صرف عمر ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن وہب اکیلے ہیں۔","",{"k":"صحيح مسلم (١٤٠٩/٤٣)۔","f":") مذکورہ حدیث سے معلوم ہوا کہ حالت احرام میں، نکاح اور منگنی کرنا جائز نہیں۔ (٢) یہ بھی معلوم ہوا کہ مسلمان کی بیع پر بیع کرنا بھی درست نہیں ہے۔ اور اسی طرح پیغام نکاح پر پیغامِ نکاح بھیجنا جائز نہیں لیکن اگر وہ چھوڑ دے یا اجازت دے دے تو تب درست ہے۔"}],[511,"سيدنا جویریہ رضی اللہ عنہا کا بیان ہے، جب رسول اللہ صلی اللہ علیہ وسلم فوت ہوئے آپ نے اس دن صرف سفید خچر۔ ہتھیار اور زمین چھوڑی، آپ نے انہیں صدقہ قرار دے دیا تھا۔“ یہ حدیث ابو اسحاق سے صرف اسرائیل سے روایت کرتے ہیں، اسے روایت کرنے میں مکمل اکیلے ہیں۔","",{"k":"٥١١ ور کود مؤمل . رقم : ٣٥٩٥ . صحیح بخاری، سنن نسائی۔","f":"معلوم ہوا کہ نبی مکرم ملنے انم نے خچر، اسلحہ، اور زمین کے علاوہ ترکہ میں کچھ بھی نہیں چھوڑا اور یہ وہ زمیں تھی جو فدک کا آدھا حصہ اور وادی القری کا تہائی حصہ اور خیبر کے شمس میں سے آپ کا حصہ اور بنی نفیر میں سے جو آپ ملنے کی ایم نے چن لی تھی ان ہی چیزوں کو سیدہ فاطمہ زہراء علی انہوں نے سیدنا ابو بکر بنی لینے سے ان کی خلافت کے زمانہ میں مانگا۔ سیدنا ابو بکر ضیا اللہ نے یہ حدیث سنائی کہ نبی مکرم ملے تم نے فرمایا کہ ”ہم پیغمبروں کا کوئی وارث نہیں ہوتا ہم جو چھوڑ جائیں وہ صدقہ ہے۔ آپ صلی اللہ علیہ وسلم کا حقیقی ورثہ علوم کتاب وسنت کا لافانی خزانہ ہے جس کے حاصل کرنے کی عام اجازت ہی نہیں بلکہ تاکید شدید ہے کہ اس کو حاصل کیا جائے۔ ٥١٢"}],[512,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رمضان کے مہینے میں آواز ہے، اور ذی القعدہ میں قبیلے الگ الگ کئے جاتے ہیں۔ اور ذی الحجہ میں حاجی سے چھینا جاتا ہے۔“ یہ حدیث شہر بن حوشب سے صرف بشتری ہی روایت کرتے ہیں، اسے روایت کرنے میں نوح بن قیس اکیلے ہیں۔","",{"k":"ضعيف . المعجم الكبير للطبرانی (١٢٣/١٩)، مجمع الزوائد (٧/٣١٠)، سنده۔"}],[513,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”عورت جب گھر سے باہر نکلے جبکہ اس کا خاوند اس بات کو ناپسند کرتا ہو تو آسمان میں ہر فرشتہ اس پر لعنت کرتا ہے، اور واپس آنے تک جنوں اور انسانوں کے سوا ہر چیز جس پر سے وہ گزرتی ہے وہ اس پر لعنت کرتی رہتی ہے۔ یہ حدیث عمرو بن دینار سے صرف محمد بن زید ہی روایت کرتے ہیں، اسے روایت کرنے میں سوید بن عبدالعزیز ا کیلیے ہیں۔ ٥١٤","",{"k":"المعجم الكبير للطبرانی (١١/١٥٩)، السلسلة الضعيفة (٢/١٠١، ١١٠٢)۔"}],[514,"سیدنا انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا کہ وہ ایک دن سیدہ عائشہ ریلی ایشیا کے پاس گئے تو انہوں نے کہا: میرے ماں باپ آپ صل علی تم پر قربان ہوں! مجھے اللہ تعالیٰ کا وہ نام بتائیں کہ جس کے ذریعے دعا کی جائے تو وہ قبول کرے جب اس کے ذریعے مانگا جائے تو وہ عطا فرما دے؟ تو نبی صلی اللہ علیہ وسلم نے ان سے اعراض کیا وہ اٹھیں، وضو کیا، پھر کہا: ((اللَّهُمَّ إِنِّي أَسْتَالُكَ مِنَ الْخَيْرِ كُلِّهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَبِاسْمِكَ الْعَظِيْمِ الَّذِي إِذَا دُعِيْتَ بِهِ أَجَبْتَ وَإِذَا سُئِلْتَ بِهِ أَعْطَيْتَ )) ”اے اللہ میں تجھ سے ہر خیر مانگتی ہوں جو جانتی ہوں اور جو میں نہیں جانتی، اور تیرے اس اسم عظیم کے وسیلے سے جس کے ذریعے اگر تجھ سے دعا کی جائے تو تو قبول کرتا ہے اور اگر کچھ مانگا جائے تو تو عطا فرما دیتا ہے۔“ تو آپ نے فرمایا: ”اللہ کی قسم! وہ انہی ناموں میں ہے جن کے وسیلے سے تو نے دعا کی ہے۔“ یہ حدیث حضرت غالب القطان سے صرف محمد بن عبداللہ العصری ہی روایت کرتے ہیں، اسے روایت کرنے میں القواریری اکیلے ہیں۔","",{"k":"سنن ابن ماجة (٣٨٥٩)، ضعيف الجامع الصغير (١١٩٣)۔"}],[515,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ سے روایت کرتے ہیں انہوں نے کہا: میں نبی صلی اللہ علیہ وسلم کے زمانے میں ایک مجلس میں بیٹھا تھا کہ اس سے پہلے یا بعد کبھی کوئی بیٹھنا اس سے زیادہ قابل رشک نہیں ہوا۔ نبی سے ان تشریف لائے جبکہ کچھ لوگ آپ کے حجرے کے پاس قرآن کے بارے میں جھگڑا کر رہے تھے۔ آپ گھر سے نکلے آپ کا چہرہ مبارک غصے سے اتنا سرخ ہو گیا تھا گویا آپ کے چہرے پر انار نچوڑ دیا گیا ہے یا آپ کے چہرے پر خون کے قطرے بہہ رہے ہیں۔ تو آپ نے فرمایا: ”اے میری قوم! کیا تمہیں یہی حکم دیا گیا ہے کہ قرآن کے بارے میں جھگڑا کرو، اور اس کے بعض کو بعض کے ساتھ ٹکراؤ؟ یقیناً قرآن اس طرح نازل نہیں ہوا کہ اس کا کچھ حصہ دوسرے کو جھٹلاتا ہوا اگر کہیں کوئی بات متشابہ نظر آئے تو اس پر ایمان لاؤ۔“ یہ حدیث سلیمان التیمی سے صرف اُن کے بیٹے ہی روایت کرتے ہیں، اسے روایت کرنے والے عمر والناقد ا کیلئے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قرآن مجید کے متعلق جھگڑنا نہیں چاہیے۔ قرآن مجید کی بعض آیات محکمات ہیں، اس سے مراد وہ آیات ہیں، جن میں اوامر و نواہی، احکام و مسائل اور قصص و حکایات ہیں جن کا مفہوم واضح اور اٹل ہے۔ اور کچھ آیات متشابہات، مثلاً اللہ کی ہستی، قضا قدر کے مسائل جنت، دوزخ، ملائکہ وغیرہ، ان میں تاویلات جائز نہیں بلکہ ایمان رکھنا چاہیے، جیسا کہ ارشاد باری تعالیٰ ہے: هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَبَ مِنْهُ ايَتٌ مُحْكَمْتَ هُنَّ أُمُّ الْكِتَبِ وَ أَخَرُ مُتَشْبِهتْ فَأَمَّا الَّذِيْنَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيْلِهِ وَمَا يَعْلَمُ تَأْوِيْلَةَ إِلَّا الله وَالرَّسِحُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِّنْ عِنْدِ رَبَّنَا وَ مَا يَذْكُرُ إِلَّا","",{"k":"المعجم الكبير للطبراني (٢٧٩/٥، ٥٣٠٤)۔","f":"أولُوا الْأَلْبَابِ) (آل عمران: ٧) و ہی اللہ تعالیٰ ہے جس نے تجھ پر کتاب اتاری جس میں واضح مضبوط آیتیں ہیں جو اصل کتاب ہیں اور بعض متشابہ آیتیں ہیں پس جن کے دلوں میں کبھی ہے وہ متشابہ آیتوں کے پیچھے لگ جاتے ہیں فتنے کی طلب اور ان کی مراد کی جستجو کے لیے حالانکہ ان کے حقیقی مراد کو سوائے اللہ تعالیٰ کے کوئی نہیں جانتا اور پختہ و مضبوط علم والے یہی کہتے ہیں کہ ہم تو ان پر ایمان لا چکے یہ ہمارے رب کی طرف سے ہیں اور نصیحت تو صرف عقل مند حاصل کرتے ہیں۔“"}],[516,"سیدنا عبادہ رضی اللہ عنہ ملے تعلیم سے روایت کرتے ہیں کہ آپ نے فرمایا: ” گندم جو کے عوض دو بدلے ایک کے بدلے میں نقد بنقد ہو جبکہ ادھار کی صورت میں درست نہیں۔“ یہ حدیث قتادہ سے صرف سعید بن بشیر ہی روایت کرتے ہیں۔ قانون مذکورہ حدیث سے معلوم ہوا کہ اگر اجناس مختلف ہوں تو کمی بیشی جائز ہے جبکہ بیع نقد ہو جیسا کہ ایک دوسری حدیث میں بھی ہے رسول اللہ علیم نے فرمایا: ”گندم کو جو کے عوض اور جو کو گندم کے عوض جیسے چاہیں فروخت کریں جبکہ وہ نقد بنقد ہوں۔“ (صحیح مسلم، رقم: ١٥٨٧، سنن ابی داؤد، رقم: ٣٣٤٩)","",{"k":"صحيح الجامع الصغير (٧١٨٣)۔"}],[517,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ( نماز میں ضرورت کے وقت ) سبحان اللہ کہنا ہے ( تا کہ امام کو اطلاع ہو سکے ) اور عورتوں کے لیے تالی بجانا۔“ یہ حدیث اشعث سے صرف مروان ہی روایت کرتے ہیں، اسے روایت کرنے میں عیسیٰ بن مساورا کیلے ہیں","",{"k":"صحیح بخاری، سنن ابو داؤد (٩٣٩)، سنن ترمذی (٣٢٩)، مسند احمد (٣/٣٤٨)۔"}],[518,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور اس نے عرض کیا، مجھے کچھ وصیت فرما ئیں۔ تو آپ نے فرمایا: ” قیل و قال ( بہت باتیں، قصے کہانیاں یا تحقیق کے بغیر باتیں بیان کرنا) اور کثرت سے سوال کرنا اور مال کو ضائع کرنا چھوڑ دے۔“ یہ حدیث شعمی سے صرف السری بن اسماعیل ہی روایت کرتے ہیں۔ مذکورہ روایت کمزور ہے۔ تاہم صحیح حدیث میں ہے رسول اللہ مسلم نے ارشاد فرمایا: ”بے شک اللہ تعالیٰ نے تم پر حرام کر دیا ہے ماؤں کو ستانا اور بیٹیوں کو زندہ دفن کرنا اور (خود) کچھ نہ دینا اور دوسروں سے کہنا ) لا مجھے دے اور تمہارے لیے ناپسند کیا ( یہ کہنا کہ ) یہ کہا گیا اور فلاں نے کہا اور زیادہ سوال کرنا اور مال ضائع کرنا۔“ (صحیح بخاری، کتاب الادب، رقم: ٥٩٧٥) قیل و قال، میں کئی چیزیں شامل ہیں۔ (الف) لوگوں کے متعلق سنی سنائی باتیں بلا تحقیق آگے پہنچانا یا تحقیق کر کے دوسروں کو سناتے رہنا پہلی صورت میں جھوٹ اور بہتان کا مرتکب ہوگا دوسری صورت میں غیبت اور چغلی کا ارتکاب کرے گا۔ (ب) لوگوں کے عیوب اور کمزوریاں بیان کرتے چلے جانے سے انسان اپنی حالت سے بے پروا ہو جاتا ہے۔اس لیے قیل و قال کو نا پسند فرمایا۔ (ج) دین کے بارے میں لوگوں کے اختلاف کو بیان کرتے چلے جانا۔ فلاں امام نے یہ کہا، فلاں نے یہ، بعض علماء یوں فرماتے ہیں ایک قول یہ بھی ہے وغیرہ وغیرہ اور پختہ اور اصلی بات کا فیصلہ نہ کرنا۔ كثرة السوال اس میں بھی کئی چیزیں شامل ہیں۔ (الف) رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں رسول اللہ صلی اللہ علیہ وسلم سے زیادہ سوال کرنا اس لیے منع تھا کہ ایسا نہ ہو کہ کسی سوال کرنے سے مسلمانوں کے لیے وہ چیزیں حرام ہو جائیں جو سکوت کی وجہ سے جائز تھیں۔ اسی لیے اللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم سے بکثرت سوال کرنے سے منع کرتے ہوئے فرمایا: ﴿وَلَا تَسْتَلُوْا عَنْ أَشْيَاءَ إِنْ تُبْدَلَكُمْ تَسُؤْكُمْ ﴾ (المائدہ: ١٠١) ایسی چیزوں کے متعلق سوال نہ کرو کہ اگر تمہارے لیے ظاہر کر دی جائیں تو تمہیں بری لگیں۔“ (ب) بلاضرورت لوگوں کے حالات کی جستجو کرنا ان کے ذاتی معاملات کے متعلق پوچھنا خواہ مخواہ کا تجسس ناپسندیدہ عمل ہے۔ (ج) ایسے سوال کرنا جن کا وجود ہی نہیں محض فرضی صورتیں ہیں یا ابھی تک وجود میں نہیں آئیں سلف صالحین اسے سخت ناپسند فرماتے تھے مثلاً بعض رائے پرستوں نے سوال پیدا کیا کہ اگر کتے نے بکری سے جفتی کی اور بچہ مشترک پیدا ہوا تو حلال ہے یا حرام؟ پھر خود ہی جواب دیا کہ دیکھنا چاہیے گوشت اور گھاس سامنے رکھ کر اگر گھاس کھاتا ہے تو حلال ہے گوشت کھاتا ہے تو حرام۔ اگر دونوں کھائے تو اس کو مارا جائے اگر بھونکے تو کتے کے حکم میں ہے ورنہ بکری کے۔ اگر دونوں آواز میں کرتا ہو تو ذبح کیا جائے اگر او جھری نکلے تو کھایا جائے ورنہ نہیں۔ () علماء کو پھنسانے اور نیچا دکھانے کے لیے سوال کرنا اکرام مسلم کے خلاف ہے اور اکرام علم کے بھی خلاف ہے۔ اضاعة المال: مال ضائع کرنا، ناجائز جگہوں میں خرچ کرنا یا اپنی حیثیت سے بڑھ کر خرچ کرنا مال کو ضائع کرنا ہے۔","",{"k":"ضعيف الجامع الصغير (٢٩٧٢)، مجمع الزوائد (٣٠٢/١٠)۔"}],[519,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب بنی اسرائیل میں نقائص اس طرح پیدا ہوئے کہ ایک آدمی جب اپنے بھائی کو ایک بار ) گناہ کرتے دیکھتا تو وہ اس کو اس سے منع کرتا، پھر وہ اگلے روز اسے ملتا تو وہ اس کے ساتھ میل جول رکھنے اور اکٹھے کھانے پینے سے اس کو اس کے گناہ کے ارتکاب کرنے سے نہ روکتا تو اللہ تعالیٰ نے ان کے دلوں کو ایک دوسرے سے ملا دیا۔ان کے بارے میں قرآن نازل ہوا۔ لُعِنَ الَّذِيْنَ كَفَرُوا مِنْ بَنِي إِسْرَاءِ يُلَ عَلَى لِسَانِ دَاوُدَ وَ عِيسَى ابْنِ مَرْيَمَ ذُلِكَ بِمَا عَصَوْا وَ كَانُوا يَعْتَدُونَ ”بنی اسرائیل میں سے جو لوگ کافر ہوئے ان پر داود اور عیسی ابن مریم کی زبانی لعنت کی گئی، یہ اس وجہ سے ہوا کہانھوں نے نافرمانی کی اور وہ حد سے گزر جاتے تھے۔ پھر نبی صلی اللہ علیہ وسلم نے فرمایا: ” ہر گز نہیں اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے! تم اس وقت تک (عذاب سے نہیں ) بیچ سکتے جب تک تم ظالم کا ہاتھ پکڑ کر اس کو اسے حق قبول کرنے پر مجبور نہ کرو۔“ یہ حدیث سفیان سے صرف عبدالکریم حنفی اور عبداللہ بن مبارک اور اشجعی ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد، سنن ابن ماجه، رقم : ٠٦ (٤٠٠٦)، السلسلة الضعيفة (١٠٤/٣، ١١٠٥)۔","f":"مذکورہ روایت کمزور ہے تاہم اگر فاسقوں، ظالموں، اہل بدعت کے ساتھ اللہ کے لیے بغض نہ رکھا جائے اور مقاطعہ نہ ہو بلکہ ان کے ساتھ آزادانہ اختلاط ہو یوں کہ شرعی غیرت بھی اٹھ جائے تو اس کا عقاب انتہائی شدید ہوتا ہے، جیسا کہ بنی اسرائیل کی تاریخ اور امت اسلامیہ کی موجودہ صورت حال سے ظاہر ہے۔ ٥:٢٠"}],[520,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی نے ہم جب وضو کرتے تو اپنی داڑھی کا خلال کیا کرتے تھے۔ یہ حدیث رحیل سے صرف شجاع بن ولید ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذى (٣١)، قال الالباني : صحیح۔"}],[521,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ولی راہنمایا حاکم کے بغیر نکاح نہیں ہوتا۔ یہ حدیث مسنداً حضرت سفیان سے صرف ابن داؤد اور بشر اور ابن مہدی ہی روایت کرتے ہیں اور قواریری اسے روایت کرنے میں اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ عورت کے نکاح کے لیے ولی وسر پرست یعنی والد، اس کی عدم موجودگی میں دادا پھر چا وغیرہ کی اجازت شرط ہے ولی کی اجازت کے بغیر عورت کا نکاح منعقد نہیں ہوتا۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”جس عورت نے اپنے ولی کی اجازت کے بغیر نکاح کیا تو اس کا نکاح باطل ہے۔ (سنن ابی داؤد، کتاب النكاح، رقم: ٢٠٨٣، سنن ترمذی، رقم: ١١٠٢، اسناده صحیح) جمہور علماء کا موقف ہے کہ ولی کی اجازت ضروری ہے۔ امام ابن منذر جماللہ نے فرمایا ہے کہ کوئی صحابی بھی اس امر کا مخالف نہیں۔ البتہ امام ابوحنیفہ ہمالہ نے یہ موقف اپنایا ہے کہ ولی کی اجازت کسی صورت میں بھی ضروری نہیں۔ اہل ظاہر نے کنواری کے لیے ولی کی اجازت کو ضروری قرار دیا ہے جبکہ شوہر دیدہ کے لیے نہیں۔ (فتح الباری: ١٨٧/٩،بداية المجتهد: ٢٠/٣) راجح موقف جمہور ہی کا ہے۔ امام ابن قدامہ، شیخ شمس الحق عظیم آبادی، علامہ عبد الرحمان مبارک پوری، سعودی مستقل فتوی کمیٹی کا موقف بھی جمہور والا ہے۔ (المغنی لابن قدامه: ٣٤٥/٩، عون المعبود: ١٩١/٢، تحفة الاحوذى: ٢٤١/٤، فتاوى اللجنة الدائمة: ١٤١/١٨) نیز جس روایت میں ہے کہ شوہر دیدہ عورت اپنے نفس کے متعلق اپنے ولی سے زیادہ حق رکھتی ہے۔ (صحیح مسلم، رقم: ١٤٢١، سنن ابی داؤد، رقم: ٢٠٩٨) اس کا مطلب یہ نہیں کہ شوہر دیدہ عورت خود جہاں چاہے اپنا نکاح کر سکتی ہے۔ بلکہ اس سے مراد یہ ہے کہ شوہر دیدہ جہاں چاہے اس کے اولیاء کو وہاں اس کا نکاح کر دینا چاہیے یعنی شوہر دیدہ کی رضامندی کو ترجیح دینا چاہیے۔ عورت کے نکاح کے لیے ولی کی اجازت شرط ہونے سے یہ بات بھی ثابت ہوئی کہ کورٹ میرج شرعاً جائز نہیں یعنی لڑکے اور لڑکی کا بھاگ کر عدالت میں نکاح کر لینا حرام ہے کیونکہ لڑکی کو اپنے سر پرست کی اجازت حاصل نہیں اور ایسا ہر نکاح باطل و کالعدم ہے جس میں ولی کی اجازت شامل نہ ہو۔","",{"k":"سنن ابو داؤد (٢٠٨٣)، مجمع الزوائد (٤/٢٨٦)، السنن الكبرى للبيهقي (١٢٤/٧)۔"}],[522,"سیدنا زید بن ارقم بنی اللہ نے بیان کیا، رسول اللہ سے تم نے فرمایا: ”جو شخص مونچھیں نہ کٹائے وہ ہم میں سے نہیں۔“ یہ حدیث ذکریا بن یحیی سے صرف جریر ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جو مونچھیں نہ کٹائے وہ نبی مکرم ملے یمن کے طریقے پر نہیں ہے بلکہ یہود و نصاریٰ اور مجوسیوں کے طریقے پر ہے۔ جیسا کہ سیدنا انس صلی اللہ فرماتے ہیں کہ رسول اللہ ملنے کام نے فرمایا: ” مونچھیں کتر اؤ اور داڑھیاں بڑھاؤ اور یہودیوں کے ساتھ مشابہت اختیار نہ کرو۔“ (شرح معانی الاثار: ٣٣٣/٢) ایک دوسری حدیث میں ہے کہ مونچھوں کو خوب اچھی طرح کاٹو اور داڑھیوں کو بڑھاؤ دو اور مجوسیوں کی مخالفت کرو۔“ (صحیح مسلم، كتاب الطهارة، باب خصال الفطرة، رقم: ٢٦٠)","",{"k":"سنن ترمذی (٢٧٦١)، مسند احمد (٤/٣٦٨)، صحيح الجامع الصغير (٦٥٣٣)۔"}],[523,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جس نے صبح و شام یہ دعا پڑھی تو اسے کوئی چیز ضرر نہیں دے سکے گی: ((اَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) ”میں اللہ تعالیٰ کے کامل کلمات کے ساتھ اس چیز کے شر سے پناہ چاہتا ہوں جو اس نے پیدا کی۔“ معلوم ہوا کہ موذی جانوروں اور انسانوں کے شر سے پناہ مانگنے کے لیے یہ بہترین دعا ہے۔","",{"k":"صحیح مسلم (٢٧٠٨)۔","f":"کلمات، سے مراد اللہ کا کلام، اس کے فیصلے اور قدرت ہے۔ تامات، سے مراد، ہر نقص اور عیب سے پاک۔"}],[524,"سیدنا عبد اللہ ابن عباس نبی یا اللہ تعالی کے اس فرمان: ﴿ إِذَا جَاءَ نَصْرُ اللهِ وَالْفَتْحُ ” جب اللہ کی مدد آ پہنچی اور فتح کے متعلق فرماتے ہیں کہ یہاں فتح مکہ مراد ہے اس میں نبی ملنے کی ام کو ان کی وفات کی خبر دی گئی ہے کہ آپ اپنے رب سے بخشش مانگیں اور جان لیں کہ آپ کی وفات کا وقت قریب آ گیا ہے۔“ یہ حدیث سفیان سے صرف سوید ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ سورۃ النصر میں نبی مکرم صلے علیم کی وفات کی طرف اشارہ ہے۔ (٢) نبی مکرم انے کے متعلق سیدہ عائشہ علی ال جہا فرماتی ہیں کہ اس سورت کے نازل ہونے کے بعد آپ صلی اللہ علیہ وسلم نے کوئی نماز نہیں پڑھی جس میں یہ نہ پڑھا ہو۔ (سبحانك ربنا وبحمدك اللهم اغفرلی)) (صحیح بخاری، کتاب التفسير، رقم: ٤٩٦٧) ایک روایت میں ہے کہ نبی مکرم مے عین رکوع اور سجدے میں کثرت سے یہ دعا پڑھتے تھے: ((سبحانك اللهم ربنا وبحمدك اللهم اغفرلی)) (صحیح بخاری، کتاب التفسير، رقم: ٤٩٦٨) ٢٥","",{"k":"المعجم الكبير للطبراني (١٠/١٩٧، ١٢٢٧٥)۔"}],[525,"سيدنا كعب بن عجرہ نبی الیہ کہتے ہیں کہ عمرہ حدیبیہ میں رسول اللہ صلی اللہ علیہ وسلم میرے پاس سے گزرے اور میرے سر کی جوئیں زیادہ ہو گئیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” کعب! یہ تو بہت تکلیف ہے تو میں نے کہا: جی ہاں! کیا اس کی کوئی رخصت ہے؟ تو آپ نے فرمایا: ”ہاں۔ ایک قربانی کر یا تین دن کے روزے رکھ یا چھ مسکین کو کھانا کھلا۔ یہ حدیث سفیان سے صرف سوید ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (٣/٣٣٥)۔"}],[526,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے روایت ہے، کہ رسول اللہ صلی اللہ علیہ وسلم سے گری ہوئی چیز کے متعلق پوچھا گیا جو رہائش والی زمین پانی بہنے کی جگہ میں ملے۔ آپ نے فرمایا: ”اس کی ایک سال تک پہچان کرواتا رہے اگر اس کا مالک آجائے ( تو اس کے حوالے کی جائے ) ورنہ وہ تیرے لیے ہے“ اور اس گری ہوئی چیز کے متعلق پوچھا گیا: جو دشمن کے علاقے سے ملے، فرمایا: ”اس میں سے اور دفن شدہ مال میں سے شمس دیا جائے اور آپ سے گم شدہ بکری کے متعلق پوچھا گیا تو آپ نے فرمایا: ”وہ تیرے لیے یا تیرے بھائی کے لیے یا پھر بھیڑیے کے لیے ہے۔“ اور اونٹوں میں سے گم شدہ کے متعلق پوچھا گیا تو آپ نے فرمایا: انہیں چھوڑ دو ان کا جوتا اور پینا ان کے پاس ہے وہ پانی پر آ جاتے ہیں اور درختوں سے کھا لیتے ہیں۔“ پھر آپ سے پہاڑ کے باڑے میں چرائی ہوئی چیز کے متعلق پوچھا گیا تو آپ نے فرمایا: ”اس کو چند ضر ہیں ماری جائیں اور اس پر دوہرا تاوان ڈالا جائے۔ اور جب جانوروں کے باڑے سے ہو تو ڈھال کی قیمت کو پہنچ جائے جو ایک دینار ہے تو اس میں ہاتھ کاٹنا ہے اگر اس سے کم ہو تو اسے چند ضر ہیں ماری جائیں اور تاوان اس پر دو گنا کیا جائے۔“ یہ حدیث سفیان سے صرف سوید ہی روایت کرتے ہیں۔","",{"k":"سنن نسائی (٢٤٩٦)۔","f":"نمبر ١٩٠۔ رکاز کے متعلق دیکھئے فوائد حدیث نمبر ١٢٠٦۔ بکری یا اونٹ کے متعلق دیکھئے فوائد حدیث مذکورہ حدیث سے یہ بھی معلوم ہوا کہ جب مال مسروقہ ڈھال کی قیمت کو پہنچ جائے تو پس چور کا ہاتھ کاٹا جائے گا مذکورہ حدیث میں وضاحت آ گئی ہے کہ وہ ایک دینار بنتا ہے۔ ( دوسری حدیث میں ڈھال ہے جس کی قیمت تین درہم تھی )۔ (صحیح بخاری، رقم: ٦٧٩٥، صحيح مسلم، رقم: ١٦٨٦)"}],[527,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑ کر فرمایا: ”دو مومن آپس میں ملتے ہیں اور ہر ایک دوسرے کا ہاتھ پکڑتا ہے اور جب وہ اس کا ہاتھ پکڑتا ہے تو وہ محض اللہ کے لیے دوستی کی وجہ سے پکڑتا ہے تو جب وہ جدا ہوتے ہیں تو ان کے گناہ معاف ہو جاتے ہیں۔“","",{"k":"کی صحيح الجامع الصغير (٥٧٧٨)، سنن ترمذی (٢٧٢٧)، سنن ابو داؤد (٥٢١٢)۔","f":"مذکورہ حدیث میں مصافحہ کی فضیلت کا اثبات ہے۔مسلمانوں کا ایک دوسرے کے ساتھ خوش دلی سے ملنا اور مصافحہ کرنا آپس میں محبت کے اضافے اور اللہ تعالیٰ کی طرف سے بخشش کا ذریعہ ہے۔ مصافحہ ایک مسنون اور مستحب عمل ہے۔"}],[528,"سیدنا حصین بن محصن نے اپنی پھوپھی سے روایت کیا ہے کہ وہ رسول اللہ مطلعے علیم کے پاس گئیں تو آپ نے انہیں فرمایا: ” کیا تو خاوند والی ہے؟ انہوں نے کہا: جی ہاں! آپ نے فرمایا: ” تو اس کے لیے کیسی ہے؟ اس نے کہا: میں اس کے حق میں کوئی کوتا ہی نہیں کرتی مگر جہاں میں عاجز آ جاؤں۔ آپ نے فرمایا: ”دیکھ لینا کہ تو اس سے کس مقام پر ہے کیونکہ وہ تیری جنت بھی ہے اور تیری دوزخ بھی ہے۔“ یہ حدیث اوزاعی سے صرف شعیب بن اسحاق ہی روایت کرتے ہیں۔","",{"k":"١٩٠٢٥ : مسند احمد (٣٤١/٤، ٢٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ خاوند کی اطاعت و فرمانبرداری عورت کے لیے جنت میں جانے کا باعث ہے اسی طرح خاوند کی ناراضی و نافرمانی عورت کے لیے جہنم کا باعث ہے۔ ایک حدیث میں ہے سیدہ ام سلمہ ولی او با بیان فرماتی ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس عورت کا انتقال اس حال میں ہوا کہ اس کا خاوند اس سے خوش تھا وہ جنت میں جائے گی۔“ (سنن ترمذی، ابواب الرضاع، رقم: ١١٦١)"}],[529,"سیدنا حذیفہ ضیا اللہ کہتے ہیں: جس شخص کو یہ پسند ہو کہ وہ ایسے آدمی کو دیکھے جو وقار، ٹھہراؤ، دین میں خوبصورت اور اچھا چال چلن والا ہونے میں گھر سے نکلنے سے لے کر واپس آنے تک نبی ملنے کی ام کے زیادہ مشابہ ہو تو وہ عبد اللہ بن مسعود فضل اللہ کو دیکھ لے۔“ یہ حدیث از اعمش از یزید صرف داھر الرازی ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری، سنن ترمذی (٢٨٠٧)، المعجم الكبير للطبراني (٤٨٣/٧)۔","f":"مذکورہ حدیث میں سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کی فضیلت کا تذکرہ ہے۔ یہ بنی ہذیل سے ہیں۔ نبی مکرم ملے تعلیم کے خادم خاص، سفر، حضر میں ہر جگہ نبی مکرم طلئے علیم کی خدمت کرتے، بہت بڑے عالم زاہد اور فقیہ تھے ساٹھ سال سے زائد عمر پا کر ٣٢ ہجری میں فوت ہوئے رضی اللہ عنہ عبد اللہ بن مسعود رضی اللہ عنہ نبی مکرم ملے تعلیم کے عمل کے لحاظ سے، چال چلن کے لحاظ سے بالکل مشابہ تھے۔ کیونکہ سیدنا عبد اللہ نبی اللہ کا نبی صلی اللہ علیہ وسلم کے ساتھ اٹھنا بیٹھنا بہت زیادہ تھا۔ سیدنا ابو موسی اشعری رضی اللہ عنہ فرماتے ہیں کہ میں اور میرے بھائی یمن سے (مدینہ طیبہ ) حاضر ہوئے اور ایک زمانے تک یہاں قیام کیا ہم اس پورے عرصہ میں یہی سمجھتے رہتے کہ سیدنا ابن مسعود علی نبی مکرم نے ایم کے گھرانے ہی کے ایک فرد ہیں کیونکہ نبی مکرم ملنے علم کے گھر میں ابن مسعود ضل اللہ اور ان کی والدہ کا ( بکثرت) آنا جانا ہم خود دیکھا کرتے تھے۔ (صحیح بخاری، رقم: ٣٨٦٣)"}],[530,"سیدنا عمار بن یاسر رضی اللہ عنہ نے بیان کیا، بے شک تمہاری ماں بصرہ کی طرف آئی ہیں، رسول اللہ علیم کی دنیا میں زوجہ محترمہ بھی تھیں اور وہ آخرت میں بھی آپ کی زوجہ محترمہ ہوں گی۔“ یہ حدیث ابی حصین سے صرف ابوبکر بن عیاش روایت کرتے ہیں۔ مذکورہ حدیث میں جس کا تذکرہ ہے وہ نبی معظم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ بنی ہو یا ہیں۔","",{"k":"صحیح بخاری (٧١٠٠)، المعجم الكبير للطبراني (٣٤٦/١٦، ١٨٦٣٠)۔","f":"(صحیح بخاری، کتاب الفتن، رقم: ٧١٠٠) یہ سیدہ عائشہ بنی اور ان کی فضیلت ہے کہ دنیا میں نبی مکرم ملنے کی یمن کی زوجہ تھیں اور آخرت کو بھی ہوں گی۔ ٥٣١"}],[531,"سيدنا ابو ہريره وانا الیہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ایک عورت نے ایک بلی کو باندھا، پھر اس کو پانی پلایا، نہ کھانا کھلایا، اور نہ اس کو کھلا چھوڑا کہ وہ زمین کے کیڑے مکوڑے کھاتی حتی کہ وہ باندھی ہوئی ہی مرگئی تو وہ عورت جہنم میں چلی گئی۔ اور ایک بدکار عورت جنت میں اس لیے چلی گئی کہ وہ ایک کنوئیں پر ایک کتے کے پاس سے گزری جو پانی پینا چاہتا تھا مگر پی نہیں سکتا تھا تو اس نے اپنا جوتا یا موزہ اتارا اس کو اپنی اوڑھنی سے باندھا اس طرح پانی نکال کر اس کتے کو پلا دیا یہاں تک کہ اس کو سیراب کر دیا۔ یہ حدیث مغیرہ بن ابی لبید سے صرف محمد بن اسحاق ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ جانوروں کے ساتھ بے دردی اور بے رحمی کا معاملہ اللہ تعالیٰ کو سخت ناراض کرنے اور جہنم میں لے جانے والا عمل ہے۔ اللهم احفظنا منه . (٢) یہ بھی معلوم ہوا کہ جانوروں پر رحم آدمی کو جنت کی طرف لے جائے گا۔ یہ بھی معلوم ہوا کہ کسی گناہ کو کم اور کسی نیکی کو حقیر نہیں جاننا چاہیے۔ ہو سکتا ہے کہ اللہ تعالیٰ معمولی سی نیکی کی وجہ سے مغفرت فرما دے۔ اور جس گناہ کو حقیر سمجھا جا رہا ہے اس کی وجہ سے وہ جہنم میں داخل کر دے۔","",{"k":"صحیح بخاری (٦٠٠٩)، المعجم الكبير للطبرانی (١٩/١٢٤)۔"}],[532,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اللہ کی راہ میں ایک غازی کو سامان جنگ فراہم کر کے) تیار کر دیا تو گویا کہ اس نے خود جنگ کی۔ اور جس شخص نے اچھے طریقے سے اس کے پیچھے اس کے گھر میں دیکھ بھال کی تو اس نے بھی گویا کہ خود جنگ کی۔‘“ یہ حدیث از اوزاعی از بیجی از ابی سلمہ صرف روا دہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ (١) جس نے مجاہد کو اسلحہ دیا جہاد کے لیے تیار کیا تو اس کو مجاہد کے برابر ثواب ملے گا گویا یہ عمل کرنے والا خود اللہ تعالیٰ کی راہ میں جہاد کر رہا ہے جو اجر ایک مجاہد کو ملے گا وہی معاونین کو بھی ملے گا۔ (٢) جو شخص مجاہد کے اہل خانہ کی عمدہ طور سے خبر گیری کرے تو اس کو بھی مجاہد کی طرح پورا پورا ثواب ملتا ہے۔","",{"k":"يَرْوِ صحیح بخاری (٢٨٤٣)، صحيح مسلم (١٨٩٥)۔"}],[533,"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ بیان کرتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس رات گزاری تو آپ قضائے حاجت کے لیے اٹھے، آپ ایک رومی کوٹ پہنے ہوئے تھے: آپ نے استنجا کیا، وضو کیا اور اپنے موزوں پر مسح کیا تو میں نے کہا: یا رسول اللہ! آپ ان کو اتارتے کیوں نہیں؟ آپ نے فرمایا: ”میں نے ان کو حالت وضوء میں پہنا ہے۔ یہ حدیث قاسم بن ولید اور مجاہد صرف عبیدہ بن اسود سے روایت کرتے ہیں، اسے روایت کرنے میں عبداللہ بن عمرو بن ابان اکیلے ہیں۔","",{"k":"سنن نسائی (١٢٥)، صحیح مسلم (٢٧٤)، سنن ابو داؤد (١٥١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ موزوں پر مسح کرنا جائز ہے۔ موزوں پر مسح کرنا اللہ تعالیٰ کی طرف سے مسلمانوں کے لیے ایک رخصت ہے جسے اپنانا چاہیے۔ کیونکہ فرمان نبوی ہے: اللہ تعالیٰ کو یہ بات نہایت پسند ہے کہ اس کی دی ہوئی رخصتوں کو اپنایا جائے۔ (ابن خزیمہ: ٢٥٩/٣) امام نوری اللہ فرماتے ہیں: موزوں پر مسح کرنا اتنے زیادہ صحابہ ٹی ایم سے مروی ہے کہ ان کا شمار نہیں کیا جا سکتا۔ (شرح صحیح مسلم، رقم: ١٧٠/٢) ٥٣٤"}],[534,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”زانی جس وقت زنا کرتا ہے تو وہ مومن نہیں ہوتا، چور جس وقت چوری کرتا ہے تو وہ اس وقت مومن نہیں ہوتا ہو اور شرابی جس وقت شراب پیتا ہے تو وہ اس وقت مومن نہیں ہوتا۔“ ہم نے عرض کیا: اللہ کے رسول نیم! یہ کیسے ہوتا ہے؟ آپ میم نے فرمایا: \" ( اس دوران میں ) ایمان اس سے باہر نکل جاتا ہے جب وہ تو بہ کرتا ہے تو ایمان اس کی طرف واپس آ جاتا ہے۔“ یہ حدیث ابی حمزہ سے صرف ابن ابی لیلیٰ ہی روایت کرتے ہیں، اسے روایت کرنے میں اُن کے بیٹے اکیلے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ ایمان زیادہ اور کم ہوتا رہتا ہے۔ (٢) زنا کرنے، چوری کرنے یا شراب پینے سے آدمی کافر نہیں ہو جاتا البتہ ان افعال کا شمار کبیرہ گناہوں میں ہوتا ہے اور کبیرہ گناہ تو بہ کرنے سے معاف ہو جاتے ہیں اگر کسی کبیرہ گناہ کے مرتکب نے تو بہ نہ کی اور وہ اسی حالت میں فوت ہو گیا تو اس کا معاملہ اللہ تعالیٰ کی مشیت پر موقوف ہے، اگر اللہ تعالیٰ چاہے گا تو اس کو معاف کر دے گا، اگر نہیں چاہے گا تو اس کو سزا ملے گی اور وہ دوزخ میں داخل ہو گا۔ سزا کے بعد اس کو دوزخ سے نکال کر جنت میں داخل کر دیا جائے گا۔ جبکہ کفار و مشرکین ہمیشہ دوزخ کی آگ میں رہیں گے۔ (واللہ اعلم) ٥٣٥","",{"k":"صحیح بخاری کتاب الحدود (٦٧٧٢)، سنن نسائی (٤٨٧٠)، سنن ابو داؤد (٤٦٩٠)۔"}],[535,"سیدہ عائشہ علی النیہا نے بیان کیا، دنیا کی کسی چیز نے نبی صلی اللہ علیہ وسلم کو خوش نہیں کیا اس میں سے صرف تقوی و ورع ہی نے آپ کو خوش کیا۔ نبی معظم اے علی تم دنیا کی رنگینیوں کو پسند نہیں کرتے تھے آپ دنیا پر آخرت کو ترجیح دیتے تھے۔ یہ حدیث قاسم سے صرف ابوالاسود ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"مسند احمد (٦/٦٩)، قال الشيخ شعيب الأرناؤط، حديث ضعيف۔"}],[536,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تبارک و تعالیٰ فرماتا ہے: میں اپنے بندے کے کسی حق کے بارے میں غور نہیں کرتا جب تک میرا بندہ میرے حق کے متعلق غور نہیں کرتا۔ یہ حدیث ابن عباس سے صرف اسی سند سے ہی مروی ہے، اسے روایت کرنے میں سلام الطویل اکیلے ہیں۔","",{"k":"مجمع الزوائد (١٥٣)، طبراني كبير (١/٢١٢١١٢، ١٢٩٢٢)، اسناده ضعيف۔"}],[537,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس شخص نے پہلی صف اس ڈر سے چھوڑ دی کہ کسی دوسرے کو تکلیف ہوگی تو اللہ تعالیٰ اس کو صف اول سے دو گنا اجر دیتا ہے۔“ یہ حدیث ابن عباس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ولید بن فضل اکیلے ہیں۔","",{"k":"سلسلة ضعيفه (٦/٣١٩، ٣٢٦٨)، ٥٠٤٦ قال الشيخ الالباني وضوع، ضعيف الترغيب والترهيب (١/٦٧، ٢٦٠)، مجمع الزوائد (٢/٩٥)۔"}],[538,"سيدنا ابو ہریرہ بنی اہلیہ نے بیان کیا، رسول اللہ تم نے فرمایا: ”جب تم میں سے کوئی شخص وضو کرے تو کلی کرے اور ناک میں پانی چڑھائے اور دونوں کان سر کا حصہ ہیں۔“ یہ حدیث عطاء سے صرف اسماعیل ہی روایت کرتے ہیں، اسے روایت کرنے میں علی بن ہاشم اکیلے ہیں۔","",{"k":"کی سنن ابن ماجه، المعجم الكبير للطبراني (١٩/١٢٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ\n(١) کلی کرنا اور ناک میں پانی چڑھانا سنت ہے۔ مضضمہ منہ میں پانی کو حرکت دینا، استنشاق: ناک میں پانی داخل کرنا، یہ دونوں واجب ہیں۔ جیسا کہ سیدنا لقیط بن صبرہ نبی الیہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم وضو کرو تو کلی کرو۔“ (صحیح سنن ابی داؤد، رقم: ١٣١) دوسری روایت میں ہے کہ ناک میں پانی چڑھانے میں مبالغہ کر والا کہ تم روزے دار ہو۔ صحیح سنن ابی داؤد، رقم: ١٢٩، سنن ترمذی، رقم: ٣٨)\n(٢) یہ بھی معلوم ہوا کہ کانوں کا مسح کرنا بھی مسنون ہے کیونکہ جب دونوں کان سر میں شامل ہیں تو سر کے مسح کے ساتھ کانوں کا مسح بھی کیا جائے گا۔"}],[539,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فرمایا: دستم کیسے ہو گے جبکہ تم جنت کی چوتھائی ہو اور باقی تمام قومیں تین چوتھائی ہوں؟ صحابہ دینی ایم نے کہا: اللہ اور اس کا رسول صلی اللہ علیہ وسلم بہتر جانتے ہیں، پھر فرمایا: ”اگر تم آدھے اہل جنت میں ہو پھر تم کیسے ہو گے؟ صحابہ نفی نسیم نے کہا: یہ تو بہت زیادہ ہے، پھر آپ ملنے سلیم نے فرمایا: ” تمام اہل جنت کی ایک سو میں صفیں ہوں گی جن میں سے استی صفیں تمہاری ہوں گی۔“ یہ حدیث قاسم بن عبد اللہ سے صرف حارث ہی روایت کرتے ہیں، اسے روایت کرنے میں عبد الواحد بن زیادا کیلے ہیں۔","",{"k":"صحیح بخاری، مسند احمد (١/٤٥٣، ٤٣٢٨)۔"}],[540,"سیدنا عبداللہ ابن عباس علی الجھا نے بیان کیا، نبی صلی اللہ علیہ وسلم نے ان (سیدہ میمونہ بنت الحارث ام المؤمنین بنی ) سے شادی کی جبکہ آپ احرام والے تھے، اور ان سے خلوت کی تو آپ حالت احرام میں نہیں تھے، اور وہ سرف کے مقام پر فوت ہوئیں، اور یہ سقیفہ کے نیچے ان کی قبر ہے۔“ یہ حدیث حسن بن دینار سے صرف شعیب بن اسحاق ہی روایت کرتے ہیں۔ یہ سیدنا عبد اللہ بن عباس مبنای ایلیا کا وہم ہے جیسا کہ سعید بن مسیب ہم اللہ فرماتے ہیں کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما کو وہم ہو گیا ہے کہ نبی ملنے سلیم نے حالت احرام میں سیدہ میمونہ بنی الیشیا سے شادی کی۔ (سنن ابی داؤد، رقم: ١٨٤٤، صحيح مقطوع) اس وہم کی بنیاد غالبا یہ ہے کہ چونکہ احرام سے فارغ ہوتے ہی یہ کام ہو گیا تھا اور سیدنا ابن عباس فضل اللہ ویسے بھی صغیر اسن تھے اس لیے انہوں نے سمجھا کہ احرام ہی میں یہ نکاح ہوا تھا۔ (واللہ اعلم)","",{"k":"سنن ابو داؤد (١٨٤٣)، اخبار مكة (٧/٣٧٧)۔"}],[541,"ابو اصیح ہدلی کے باپ کا بیان ہے کہ میں رمضان المبارک ٨ھ ہجری میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ حنین شریک ہوا تو اتفاق سے جمعہ کے دن بارش شروع ہوگئی، رسول اللہ صلی اللہ علیہ وسلم نے بلال فضل اللہ کو حکم دیا کہ وہ بلند آواز سے یوں کہیں: ”لوگو! اپنے ڈیروں پر ہی نماز ادا کر لو۔“ یہ حدیث ابومعاویہ العبادانی سے صرف علی بن جعد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ بارش لوگوں کے لیے مشقت کا باعث ہو تو جمعہ کے لیے مسجد میں حاضری معاف ہے۔ ایسے لوگ اپنے گھروں میں ظہر پڑھیں گے لیکن امام کو چاہیے کہ وہ لوگوں کو جمعہ پڑھائے جیسا کہ نبی معظم ملے عالم نے پڑھایا تھا۔ (فتاویٰ، ابن تیمیه: ٤ ٦٠١/٢)","",{"k":"کی سنن ابن ماجه (٩٣٩)، السنن الكبرى للبيهقي (٣١٨٦)، قال الشيخ الالبانى، صحيح۔"}],[542,"سیدنا عمار بن یاسر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” تیم کے لیے چہرے اور ہتھیلیوں کے لیے ایک دفعہ ہی ہاتھ مٹی پر مارنا کافی ہے۔ یہ حدیث ابان سے صرف عفان ہی روایت کرتے ہیں۔ مذکورہ حدیث میں تیمم کا طریقہ سکھایا گیا ہے۔ مختصر طور پر تیم کا طریقہ یہ ہے کہ نیت کی جائے اور بسم اللہ پڑھ کر دونوں ہاتھوں کو زمین پر مارا جائے، پھر ان میں پھونکا جائے اور پھر دونوں ہاتھوں اور چہرے پر ایک مرتبہ پھیر لیا جائے یہ تیم وضو، اور غسل دونوں سے کفایت کر جاتا ہے۔ فقہا کے درمیان تیم کے طریقے میں اختلاف ہے۔ جمہور علماء امام احمد، اسحاق بینہ کا کہنا ہے کہ تیم میں ہاتھوں اور چہرے پر مسح کے لیے صرف ایک ہی مرتبہ زمین پر ہاتھ مارا جائے گا ( دلیل مذکورہ حدیث ہے ) جبکہ احناف، امام مالک، شافعی رحمہم اللہ کا کہنا ہے کہ تیم یہ ہے کہ زمین پر دو مرتبہ ہاتھ مارا جائے ایک مرتبہ چہرے کے لیے جبکہ دوسری مرتبہ کہنیوں تک دونوں ہاتھوں کے لیے۔ (فتح البارى: ٦٠٦/١، تحفة الاحوذى: ٤٦٦/١) ان کی دلیل ایک کمزور روایت ہے جس میں نبی معظم ملنے سلیم نے فرمایا: ” تیم دوضر میں ہیں ایک چہرے کے لیے اور دوسری کہنیوں تک دونوں ہاتھوں کے لیے۔“ (ضعيف الجامع الصغير، رقم: ٢٥١٩، سلسلة الضعيفه، رقم: ٣٤٢٦) یہ حدیث ضعیف ہے لہذا اس لیے قابل حجت نہیں۔ تیتم میں صرف ایک ضرب ہی کافی ہے۔ امام شوکانی، امام نووی، اور علامہ عبد الرحمان مبارکپوری ہم نے اسی موقف کو ترجیح دی ہے۔ (نیل الاوطار: ٣٩٠/١، تحفة الاحوذى: ٤٧٠/١)","",{"k":"صحیح بخاری، السنن الكبرى للبيقهی (١/٢١٠)، سنن ابو داؤد (٣٢٧)۔"}],[543,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تکبر سے بچو، کیونکہ تکبر ایک شخص میں اس وقت بھی آجاتا ہے جب کہ اس پر بوریا ہو۔“ یہ حدیث طاؤس سے صرف عبداللہ بن حمید ہی روایت کرتے ہیں، اسے روایت کرنے میں سویدا کیلے ہیں۔ ·:٥٤٤ تاہم متکبر آدمی اللہ تعالیٰ کو پسند نہیں اور متکبر آدمی کا ٹھکانہ بھی جہنم ہوگا۔","",{"k":"ضعيف الجامع الصغير، رقم : (٢٢٠٩)، السلسلة الضعيفة: (٥٢٦٣)، مجمع الزوائد (١٠/٢٢٦)۔"}],[544,"سیدنا عبد اللہ بن حذافہ سہمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ نے ہم نے انہیں حکم دیا کہ وہ منی والوں کو دو چادروں میں یہ پکار کر کہیں: ” ان دنوں میں کوئی شخص روزہ نہ رکھے کیونکہ یہ کھانے پینے کے دن ہیں۔“ ماندن . اس سے مراد ایام تشریق ہیں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” ایام تشریق کھانے پینے اور ذکر الہی کے دن ہیں۔ (صحیح مسلم، کتاب الصيام، رقم: ١١٤١) ایام تشریق سے مراد ١١ ١٢ ١٣ ذوالحجہ کے دن ہیں۔ ان ایام کے روزے حرام ہیں، البتہ اگر حج تمتع کرنے والا شخص قربانی کی طاقت نہ رکھتا ہو تو وہ ان ایام میں روزے رکھ سکتا ہے۔ جیسا کہ سیدہ عائشہ اور سیدنا عبد اللہ بن عمر بی ایم سے روایت ہے کہ کسی کو ایام تشریق میں روزے رکھنے کی اجازت نہیں سوائے اس شخص کے جو قربانی کی طاقت نہ رکھتا ہو۔ (صحیح بخاری، کتاب الصوم، رقم: ١٩٩٧، ١٩٩٨)","",{"k":"صحیح مسلم، سنن ابو داؤد (٢٤١٩)، سنن ترمذی (٧٧٣)، مستدرک حاکم (٣/٧٣١)۔"}],[545,"سیدہ عائشہ نیلی و یا بیان کرتی ہیں: میں رات کو آنحضرت ملنے یام کے ساتھ آپ کے بستر پر تھی تو کھسک کر زمین پر جا پڑی تو آپ نے پوچھا: ” تمہارا کیا معاملہ ہے؟ میں نے آپ کو بتایا کہ میں حیض والی ہوگئی ہوں۔ آپ نے مجھے حکم دیا کہ میں رانوں کے نصف تک اپنے اوپر از ار کس کر باندھ لوں اور واپس اپنی جگہ پر لوٹ آؤں۔“","",{"k":"مسند احمد (٦/٣٣٥)، قال الشيخ شعيب الأرناؤط، حدیث صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حائضہ کے ساتھ ہم بستری کے سوا سب کچھ کیا جا سکتا ہے۔ نبی مکرم مالے علم سے حائضہ عورت سے فائدہ اٹھانے کے متعلق دریافت کیا گیا: آپ صلی اللہ علیہ وسلم نے فرمایا: تہبند کے اوپر والا حصہ حلال ہے۔ (صحیح ابوداؤد، رقم: ١٩٧) امام ابن قدامہ اللہ فرماتے ہیں آدمی حائضہ عورت سے شرم گاہ کے علاوہ فائدہ حاصل کر سکتا ہے۔ (المغنی: ٣٥٠/١) شیخ ابن عثیمین اللہ نے بھی اسی کے مطابق فتوی دیا ہے۔ (فتاویٰ منار الاسلام: ١١٣/١)"}],[546,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے نماز کی ایک رکعت پالی تو اس نے ساری نماز پالی۔“ ایک حدیث میں ہے جس نے نماز جمعہ یا کسی اور نماز کی ایک رکعت حاصل کر لی یقیناً اس نے نماز حاصل کرلی۔ (صحیح سنن ابن ماجه، رقم: ٩٢٢) معلوم ہوا جس نے نماز کی ایک رکعت پالی تو اس نے نماز کی ادائیگی اور فضیلت پالی۔ اسی طرح ایک رکعت پالی تو دوسری رکعت پڑھے وگرنہ چار رکعت پڑھے۔ امام شافعی، مالک یہی فرماتے ہیں کہ اگر ایک رکعت نہ ملے تو ظہر کی چار رکعتیں پڑھنا چاہیے۔ جمعہ کی دورکعتیں نہیں۔ (المحلی بالاثار: ٢٨٣/٣) امام ابو حنیفہ اللہ اور ابن حزم واللہ کا یہ موقف ہے کہ دوسری رکعت کے سجدہ یا تشہد میں پہنچے تو تب بھی اپنی بقیہ نماز جمعہ مکمل کرے، ظہر نہ پڑھے۔ (سنن ترمذی مع تحفة الاحوذى: ١٢٤)","",{"k":"صحیح بخاری (٠١)۔"}],[547,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”تم میں سے جو شخص جمعے کو آئے تو وہ غسل کرے۔“","",{"k":"صحیح بخاری (٨٧٧)۔"}],[548,"سیدہ عائشہ یا تنہا سے روایت ہے کہ افلح بن ابی العیس نے مجھ سے اندر آنے کی اجازت مانگی تو میں نے کہا: میں رسول اللہ علیم سے پوچھے بغیر اجازت نہیں دے سکتی۔ میں نے آپ سے پوچھا تو آپ نے فرمایا: ”وہ تمہارے پاس آ سکتے ہیں کیونکہ وہ تمہارے رضاعی چچا ہیں اور رضاعت سے وہی رشتہ حرام ہوتا ہے جو نسب سے حرام ہوتا ہے۔“","",{"k":"صحیح بخاری (٢٦٤٦)، صحيح مسلم (١٤٤٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ دودھ پلانے والی عورت کا شوہر باپ کے قائم مقام ہوتا ہے کیونکہ اسی کے جماع کی وجہ سے عورت میں دودھ پیدا ہوا ہے۔ حافظ ابن حجر جماللہ فرماتے ہیں کہ جمہور صحابہ و تابعین کا یہی موقف ہے۔ (فتح الباری: ٥٥/٩، علامہ عبدالرحمن مبارک پوری رحمہ اللہ بھی اسی کے قائل ہیں۔ تحفۃ الاحوذی: ٣٣٨/٤) کیونکہ سیدہ عائشہ بنا لیجا نے ابوالقعیس کی بیوی کا دودھ پیا تھا اس لیے اس کا بھائی آپ نیلی نیہا کا چچا ہوا اور چچا سے پردہ نہیں۔ اس لیے آپ صلی اللہ علیہ وسلم نے سیدہ عائشہ میل الیہا سے فرمایا کہ انہیں اپنے ہاں آنے دو۔"}],[549,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلے علی کی نماز پڑھتے جبکہ میں آپ کے آگے قبلہ کے سامنے لیٹی ہوتی تھی۔ نان مذکورهروایت سے معلوم ہوا کہ اگر نمازی آدمی کے سامنے کوئی لیٹا ہوا ہو تو نماز درست ہے۔","",{"k":"صحیح بخاری (٣٨٤)۔","f":"٥٥٠"}],[550,"سیدنا ابو ہریرہ فی اللہ نے نبی نے کام سے روایت کیا کہ آپ سے اس شخص کے متعلق پوچھا گیا جو اپنی نماز میں بے وضو ہو جائے تو آپ نے فرمایا: ” جب تک وہ ہوا خارج ہونے کی آواز نہ سنے یا بد بو محسوس نہ کرے اس وقت تک وہ نماز سے نہ ہے۔“","",{"k":"صحیح بخاری (١٣٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ محض شک کی بنا پر وضو نہیں ٹوٹتا بلکہ جب تک ہوا خارج ہونے کا یقین نہ ہو جائے اس وقت تک دوبارہ وضو کرنا ضروری نہیں خواہ کوئی نماز میں ہو یا نہ ہو۔"}],[551,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما بیان کرتے ہیں: میں ایک گدھی پر سوار ہو کر آیا جبکہ میں بلوغت کے قریب تھا اور نبی ملنے کی ہم لوگوں کو نماز پڑھا رہے تھے میں صف کے کچھ حصے کے آگے سے گزر گیا پھر میں نے گدھی کو کھلا چھوڑ دیا اور خود واپس آکر نماز پڑھنے لگا۔ تو آپ نے میری وجہ سے اپنی نماز کا کوئی حصہ بھی نہیں دہرایا۔“ مذکورہ حدیث سے معلوم ہوا کہ باجماعت نماز آدمی ادا کر رہا ہو تو اس کے سامنے سے کوئی گزر جائے تو کوئی نقصان نہیں کیونکہ اس وقت مقتدیوں کے لیے امام سترہ کے قائم مقام ہوتا ہے جیسا کہ حدیث میں ہے کہ نبی معظم صلی اللہ علیہ وسلم نے سترہ رکھا لیکن صحابہ کو سامنے سترہ رکھنے کا حکم نہیں دیا۔ (صحیح بخاری، رقم: ٧٦، صحيح مسلم، رقم: ٥٠٤)","",{"k":"صحیح بخاری (٧٦)۔"}],[552,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ سلم نے فتح مکہ کے سال روزہ رکھا جب کدید پہنچے تو آپ نے روزہ افطار کر دیا اور آپ کے صحابہ نے بھی۔ اور صحابہ کرام آپ کے نئے سے نئے حکم کی پیروی کرتے تھے اور یہی نیا حکم ہی ناسخ محکم اور پکا ہوتا۔“ مذکورہ حدیث سے معلوم ہوا کہ جو شخص روزہ رکھ کر سفر کرے اگر اس کے لیے مشکل ہو تو روزہ افطار کر دینا درست ہے۔ امام احمد، اسحاق را ہو یہ رحمہما اللہ کا یہی موقف ہے کہ روزہ افطار کرنا درست ہے۔ ٥٣","",{"k":"مسلم (١١١٣)، مسند طیالسی (٢٧١٨)۔"}],[553,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” جب تم چاند بیانیہ ملے دیکھو تو روزہ رکھو اور جب چاند دیکھو تو افطار کرو اگر تم پر مطلع ابر آلود ہو جائے تو تمیں پورے کرو۔“ یہ تمام حدیثیں قرہ سے صرف سوید اور رشدین ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (١٨٩٩)۔","f":"مذکورہ حدیث سے معلوم ہوا ہے کہ ماہ رمضان کا چاند دیکھنے سے روزہ فرض ہو جاتا ہے اور ماہ شوال کا چاند دیکھنے سے روزہ چھوڑ نا فرض ہو جاتا ہے۔ البتہ اگر ماہ شعبان کے انتیسویں روز مطلع ابر آلود ہونے کے باعث رمضان کا چاند نظر نہ آئے تو پھر روزہ نہیں رکھنا چاہیے بلکہ شعبان کے تمہیں دن پورے کر لینے چاہئیں۔ ٥٤"}],[554,"سيدنا ابی بن کعب رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے کسی کی نماز جنازہ پڑھی تو اسے ایک قیراط ثواب ملے گا۔ اور جو دفن ہونے تک وہاں موجود رہا تو اس کو دو قیراط اجر ملے گا۔ اور جس نے اس ( بد بودار یعنی مولی اور پیاز وغیرہ سبزی سے کچھ حصہ بھی کھایا تو وہ ہماری مسجد کے قریب نہ آئے۔“ یہ حدیث شیبانی سے صرف جریر ہی روایت کرتے ہیں۔::٥٥٥ (١) معلوم ہوا میت کا جنازہ پڑھنا اور دفن میں شریک ہونا نہایت اجر وثواب کا باعث ہے۔ (٢) یہ بھی معلوم ہوا بو پیدا کرنے والی اشیاء کھا کر مسجد جانا درست نہیں","",{"k":"صحيح مسلم (٥٦٢)، صحيح الجامع الصغير، رقم : ٦١٣٤ . ভ۔"}],[555,"مجاہد کہتے ہیں کہ ایک آدمی سیدنا عبداللہ ابن عمر علی اہلیہ کے پاس آیا اور اس نے کہا: تم سیدنا علی ضیا اللہ کے متعلق کیا کہتے ہو؟ تو انہوں نے کہا: وہ ان کا گھر ہے۔ اس نے کہا: پھر تم سیدنا عثمان علی علیہ کے متعلق کیا کہتے ہو؟ تو انہوں نے کہا: میں ایسے شخص کے متعلق کیا کہہ سکتا ہوں جس نے اللہ کے حقوق کے متعلق کوئی گناہ کیا تو اس نے اسے معاف کر دیا اور تمہارے متعلق کوئی گناہ کیا تو تم نے اسے قتل کر دیا۔“ یہ حدیث مجاہد سے صرف مجالد ہی روایت کرتے ہیں اور مجالد سے صرف ابوبکر بن عیاش روایت کرتے ہیں اور اسے روایت کرنے میں یزید بن مہران اکیلے ہیں۔ مانده سیدنا ابن عم رضی اللہ عنہ نیک اور صاحب فضیلت صحابی ہیں، انتہائی زیرک اور معاملہ فہم انسان تھے، نبی علیم اور آپ کے صحابہ نینی تسلیم کی بہت زیادہ عزت و توقیر کرتے تھے۔ صحابہ دینی اسلام پر اعتراضات کرنے والوں کو دندان شکن جواب دیتے جیسا کہ مذکورہ بالا روایت سے واضح ہے","",{"k":"المعجم الكبير للطبرانی (١١/٤٥، ١٣٣٥١)، مجمع الزوائد: ٩/۔"}],[556,"سیدنا عبداللہ ابن عباس نیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے صحراء اور بیاباں میں رہائش اختیار کی وہ سخت دل ہو جائے گا اور جو شکار کے پیچھے لگ گیا وہ غافل ہو جائے گا، اور جو شخص بادشاہ کے پاس آتا جاتا رہے گا، وہ فتنے کا شکار ہو جائے گا۔ یہ حدیث از سفیان از ایوب بن موسیٰ صرف عبداللہ بن مسلمہ ہی روایت کرتے ہیں، اسے روایت کرنے میں قواریری اکیلے ہیں۔ ابونعیم اور دوسرے لوگ سفیان سے اور سفیان، ابو موسیٰ ایمانی سے روایت کرتے ہیں۔ ناندن جنگل اور شکار میں انسان آزاد ہوتا ہے۔ اختلاط اور اجتماعیت نہ ہونے کی وجہ سے نماز باجماعت کی فضیلت سے محرومی کے علاوہ علماء اور صالحین کی مجالس بھی میسر نہیں ہوتیں اور نہ کوئی معروف و منکر کی تنبیہ کرنے والا ہوتا ہے اس کا اثر طبیعت کی سختی اور غفلت کی صورت میں ظاہر ہوتا ہے۔ جو خسارے کا سودا ہے اسی طرح بادشاہ کی مجلس میں بالعموم یا تو اس کی ہاں میں ہاں ملانا پڑتی ہے یا مخالفت مول لینا پڑتی ہے اور دونوں صورتوں میں امتحان و آزمائش ہے۔ الا ماشاء اللہ","",{"k":"سنن ابو داؤد، رقم : (٢٨٥٩)، السلسلة الصحيحة (٣٤٦/٣، ١٢٧٢)، السنن الكبرى للبيهقي (١٠/١٠١)۔","f":"اس لیے چاہیے کہ انسان ایسی جگہ سکونت اختیار کرے جہاں دونوں سہولتیں میسر ہوں، شہری بھی اور دیہاتی بھی جیسا کہ شہر کی مضافاتی بستیاں ہوتی ہیں۔ ٥٧"}],[557,"سیدنا انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: جس نے بالغ ہونے تک دولڑکیوں کی کفالت کی تو میں اور وہ دونوں اس طرح جنت میں جائیں گے اور آپ نے اپنے انگوٹھے اور اس کے ساتھ والی انگلی سے اشارہ کیا۔ یہ حدیث روح سے صرف ابن مبارک ہی روایت کرتے ہیں۔ اشد. مذکورہ حدیث سے معلوم ہوا کہ لڑکیوں کی پرورش کرنا بہت زیادہ ثواب کا کام ہے۔ ایسی جاہل قو میں بھی ہیں جو لڑکی کو دوسرے گھر کا کوڑا کہتے ہیں۔ اور زمانہ جاہلیت میں تو بچیوں کو عرب کے لوگ زندہ درگور ہی کر دیتے تھے۔ ان سب باتوں کے پیش نظر نبی معظم صلی اللہ علیہ وسلم نے بچیوں کی پرورش کی بہت زیادہ ترغیب دی۔ نبی مکرم ملنے ہیم نے فرمایا: ”جس کسی مسلمان کو دو بیٹیاں ملیں اور اس نے ان کو ساتھ رکھنے میں اچھا سلوک کیا تو وہ دونوں اس کی جنت میں داخل کرا دیں گی۔“ (صحیح بخاری، ادب المفرد، رقم: ٧٧)","",{"k":"سنن ترمذی (١٩١٤)، السلسلة الصحيحة (٣/١٩٤، ١١٢٠)۔"}],[558,"سيدنا عبداللہ ابن عباس ریلی اینجا نے بیان کیا، بچے کے متعلق سات چیزیں سنت میں سے ہیں جو ساتویں دن انجام دی جائیں۔ (١) اس کا نام رکھا جائے (٢) اس کا ختنہ کیا جائے (٣) اس کو تکلیف دینے والی چیز اس سے دور کی جائے (سر کے بال مونڈے جائیں)۔ (٤) اس کے کان میں سوراخ کیا جائے (٥) اس کا عقیقہ کیا جائے (٦) اس کا سر منڈایا جائے (٧) اس کے عقیقے کے خون کو اس سے ملا جائے اور اس::٥٥٩ کے سر کے بالوں کے برابر سونا یا چاندی صدقہ کی جائے۔“ یہ حدیث عبدالملک سے صرف رؤاد ہی روایت کرتے ہیں۔","",{"k":"٥٥٨ ٥٤٣٢ الله ارواء الغليل (٤/٣٨٥)، مجمع الزوائد (٤/٥)، السلسلة الضعيفة، رقم۔"}],[559,"ابو محمد حمانی نے بیان کیا، میں نے سیدنا انس بن مالک رضی اللہ عنہ کو سرخ پوستین پہنے ہوئے دیکھا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہمارے لحاف ہوتے ہم انہیں پہنتے اور ان میں نماز ادا کرتے تھے۔ یہ حدیث راشد سے صرف حسن بن حبیب ہی روایت کرتے ہیں۔","",{"k":"السلسلة صحيح (٦/٢٩٠، ٢٧٩١)، مجمع الزوائد (٥/١٣٠)۔"}],[560,"شعمی جاللہ سے روایت ہے کہ سیدنا عبداللہ ابن عمر ضیا اللہ نے اپنی عورت کو حیض کی حالت میں طلاق دے دی تو سیدنا عمر فی ای بی ملنے کی یمن کی خدمت میں حاضر ہوئے تو آپ نے انہیں حکم دیا کہ وہ اس سے رجوع کرے۔ پھر اگر اس کے دل میں یہی بات پکی ہو کر ظاہر ہو جائے تو اس کی عدت کے شروع میں ہی پاکی کے وقت اس کو طلاق دے دے۔“","",{"k":"سنن ابی داؤد، رقم : ٢١٨٤ . : صحیح مسلم (١٤٧١)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حیض کی حالت میں طلاق دینا درست نہیں ہے۔ ٥٦١"}],[561,"سیدنا عبداللہ ابن عباس ولی الہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اپنے باپ کے علاوہ کسی اور کی طرف اپنے آپ کو منسوب کیا یا جس غلام نے اپنے مالکوں کے علاوہ کسی اور کو اپنا مالک بنا لیا تو اس پر اللہ تعالیٰ، فرشتوں اور تمام لوگوں کی لعنت ہوگی۔“ یہ حدیث وہیب صرف ابن خظیم سے روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ اپنا نسب بدلنا، اور اپنے باپ کو بدل لینا، قوم کو بدل لینا، غلام کا کسی اور کو اپنا مالک بتانا یہ کبیرہ گناہ ہیں۔ بلکہ سیدنا ابو ذر من اللہ سے روایت ہے کہ نبی مکرم ملے تم نے فرمایا: جس شخص نے اپنے آپ کو اپنے باپ کے علاوہ کسی دوسرے کا بیٹا بتایا حالانکہ وہ جانتا ہے کہ میں غلط بیانی کر رہا ہوں تو اس نے کفر کا ارتکاب کیا۔ اور جس نے کسی قوم میں ہونے کا دعوی کیا حالانکہ وہ ان میں سے نہیں ہے تو اسے چاہیے کہ اپنا ٹھکانہ جہنم میں بنا لے۔ (صحیح بخاری، ادب المفرد: ٤٣٣،ا سناده صحيح) ان لوگوں کو اللہ تعالیٰ سے ڈرنا چاہیے کہ جو لوگوں کو دھوکہ دینے کے لیے اپنے باپ بدل لیتے ہیں یا کچھ لوگ اپنی قوم برادری بدل لیتے ہیں۔","",{"k":"٠١١٠: سنن ابو داؤد، رقم : ٥ صحيح مسلم۔"}],[562,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو بھی صبح یا شام ہوتی ہے تو زمین کے حصے ایک دوسرے کو پکار کر کہتے ہیں: اے میرے ہمسائے! کیا کوئی نیک آدمی تجھ پر سے گزرا ہے جس نے تجھ پر نماز پڑھی ہو یا اللہ تعالیٰ کا ذکر کیا ہو؟ اگر وہ کہتا ہے: ہاں۔ تو اس وجہ سے وہ اس کی اپنے اوپر فضیلت سمجھتا ہے۔“ یہ حدیث حضرت انس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں صالح المری اکیلے ہیں۔ ٥٦٣","",{"k":"ضعيف الجامع الصغير (٥١٨٧)، مجمع الزوائد (٢/٦)۔"}],[563,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت والے دن حجر اسود ابو تمہیں پہاڑ سے بھی بڑا ہو کر آئے گا، اس کی ایک زبان اور دو ہونٹ ہوں گے، جس نے اس کو بوسہ دیا ہو گا وہ اس کے لیے گواہی دیں گے اور اللہ تعالیٰ کا دایاں ہاتھ ہو گا جس سے وہ اپنی مخلوق سے مصافحہ کرے گا۔‘ یہ حدیث از عطاء از حضرت عبداللہ بن عمر صرف عبد اللہ بن مؤمل ہی روایت کرتے ہیں۔ ائد مذکورہ روایت کمزور ہے تاہم صحیح حدیث میں ہے نبی مکرم ملنے سلیم نے فرمایا: ”اللہ تعالیٰ قیامت کے دن حجر اسود کو اٹھائے گا، اس کی دو آنکھیں ہوں گی، جس سے وہ دیکھے گا اور زبان ہوگی جس سے وہ بولے گا، بوسہ دینے اور چھونے والوں کے حق میں گواہی دے گا۔ (سنن ترمذی، کتاب الحج، رقم: ٨٧٧) سوید ٥٦٤","",{"k":"المعجم الكبير للطبرانی (٩/٣٨٥، ١١٢٦٩)، مستدرك حاكم: ١/ ٤٥٧ فيه عبد الله بن مؤمل وهو ضعيف۔"}],[564,"سیدنا اسامہ بن زید خیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میں نے اپنے پچھلے مردوں پر عورتوں سے بڑا نقصان دہ فتنہ نہیں چھوڑا۔“","",{"k":"صحیح بخاری (٥٠٩٦)، صحیح مسلم (٢٧٤٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ عورتوں کا فتنہ بہت بڑا فتنہ ہے۔ یہی وجہ ہے کہ دنیا میں جرائم کے تین بنیادی اسباب میں سے ایک ”زن عورت ہے۔ ٥٦٥"}],[565,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارے لیے عورت کبھی ایک عادت پر قائم نہیں رہتی وہ تو پہلی کی طرح ہے کہ اگر تم اسے سیدھا کرو گے تو توڑ دو گے اور اگر چھوڑ دو گے تو اس میں کبھی کے باوجود","",{"k":"صحیح مسلم (١٤٦٨)، سنن ترمذی (١١٨٨)۔","f":"اٹھاتے رہو گے۔“ فائد مذکورہ حدیث سے معلوم ہوا کہ خاوند کو چاہیے وہ اپنی بیوی کے ساتھ نرمی سے پیش آئے، کیونکہ عورت فطری طور پر مرد سے کمزور بھی ہے اور کج فطرت اور کم عقل بھی بنا بریں زیادہ عقل اور زیادہ صبر و قوت رکھنے والے مرد کو قتل اور عفو و درگزر سے کام لیتے ہوئے اس سے حسن سلوک کرنا چاہیے نہ کہ بے رحمانہ اور متشددانہ رویہ اختیار کرنا چاہیے۔ ٥٦٦"}],[566,"سیدہ عائشہ علی النیہا نے بیان کیا، رسول اللہ ملے عام مسجد میں صبح کی نماز پڑھتے اور آپ کے پیچھے مومن خواتین ہوتیں جب آپ سلام پھیر دیتے تو وہ اپنی چادریں لپیٹ کر نکل جاتیں اور اندھیرے کی وجہ سے پہچانی نہ جاتی تھیں۔“","",{"k":"داؤد، رقم : ٤٢٣ . صحیح بخاری، سنن ابو۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نماز فجر اول وقت اندھیرے میں ادا فرماتے تھے پھر اسی طرح خلافت راشدہ میں بھی صحابہ کرام بینی اسلیم کا یہی معمول تھا وہ فجر کی نماز غلس یعنی اندھیرے میں پڑھا کرتے تھے۔ ایک روایت میں ہے کہ نماز فجر صبح کے خوب واضح ہو جانے کے بعد پڑھا کرو یہ تمہارے اجر میں اضافے کا موجب ہوگی۔ (صحیح سنن ابی داؤد، رقم: ٤٠٩) بظاہر یہ روایت پہلی کے خلاف معلوم ہوتی ہے، علماء نے ان میں تطبیق یوں دی ہے: ﴿اسفرو بالصبح ﴾ یہ ارشاد چاندنی راتوں سے متعلق ہے کیونکہ ان راتوں میں صبح صادق کے نمایاں ہونے میں قدرے اشتباہ سا ہوتا ہے بعض نے کہا مطلب یہ ہے کہ طلوع فجر میں کوئی شک باقی نہ رہ جائے۔ امام مالک، شافعی، احمد م کا موقف یہی ہے کہ نماز فجر اندھیرے میں ادا کرنا مستحب ہے لیکن امام ابو حنیفہ، محمد، ابو یوسف یام کی رائے یہ ہے کہ نماز فجر خوب روشن کر کے پڑھنا چاہیے ہمارے علم کے مطابق اس سلسلے میں راجح موقف ائمہ ثلاثہ کا ہے۔ تفصیل کے لیے دیکھئے ( تحفتہ الاحوذی: ١/ ٤٩٨۔ نیل الاوطار:١/ ٤٧٧) ٥٦٧"}],[567,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے نبی صلی اللہ علیہ وسلم سے روایت ہے، آپ نے فرمایا: ” مجھے پکڑنے اور نکاح کے بارے میں چالیس آدمیوں کی طاقت دی گئی ہے۔ ہر مومن کو دس آدمیوں کی طاقت دی گئی ہے۔ اور شہوت کے دس حصے کیے گئے جن میں سے نو حصے عورتوں کو دیے گئے اور ایک حصہ مردوں کو۔ اور اگر ان کی خواہشات کے ساتھ ساتھ ان میں حیا نہ عطا کیا جاتا تو ہر مرد کے ساتھ اس کی شہوت کو بھڑ کانے والی نوعورتیں ہوتیں۔“","",{"k":"مجمع الزوائد: ٤/ ٢٩٣ فيه مغيرة بن قيس وهو ضعيف انظر لسان الميزان (٧٩١٦)۔"}],[568,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: اللہ کی بندیوں کو اللہ کی مسجدوں سے نہ روکو لیکن وہ بھی ان میں زیب وزینت اور خوشبو وغیرہ کے بغیر آئیں۔“ مذکورہ حدیث سے معلوم ہوا کہ اگر عورت مسجد میں جانا چاہے تو اس کے لیے ضروری ہے کہ وہ باپردہ اور سادہ لباس میں جائے جس طرح صحابیات مسجد میں جایا کرتی تھیں۔ تاہم افضل یہ ہے کہ عورتیں گھر میں باپردہ ہو کر نماز پڑھیں جیسا کہ نبی مکرم ملے تعلیم نے فرمایا: ” اپنی عورتوں کو مساجد سے مت روکومگر ان کے گھر ان کے لیے بہتر ہیں۔“ (سنن ابی داؤ، کتاب الصلاة، رقم: ٥٦٧، اسناده صحيح ٥٦٩","",{"k":"مسلم، رقم : ٤٤٢ . سنن ابو داؤد، صحیح۔"}],[569,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھنے والی عورت کے لیے حلال نہیں کہ وہ خاوند یا ذی محرم کے بغیر ایک دن بھی سفر کرے۔“ مذکورہ حدیث سے معلوم ہوا کہ عورت کا محرم کے بغیر سفر کرنا جائز نہیں۔","",{"k":"صحیح بخاری، صحيح مسلم (٣٩)۔","f":"مذکورہ حدیث میں ایک دن کی مسافت کا ذکر ہے بعض روایات میں دو دن اور بعض میں تین دن اور تین راتوں کا ذکر ہے۔ نبی صلی اللہ علیہ وسلم نے سوال کرنے والے کے حالات اور سوال کی نوعیت کے مطابق مختلف جواب دیئے ہیں۔ اس لیے علماء نے لکھا ہے کہ ایک یا دو اور تین دنوں کا اعتبار نہیں، اصل اعتبار سفر کا ہے کہ اتنی مسافت جس کو سفر کہا جا سکے وہ تنہا عورت کے لیے جائز نہیں ہے اس لیے جب تک خاوند یا محرم ساتھ نہ ہو اسے تنہا سفر نہیں کرنا چاہیے۔ بعض علماء نے کہا ہے کہ یہ حکم غیر واجب سفر کے لیے ہے لیکن جو چیز عورت پر فرض ہو، اس کی ادائیگی کے لیے وہ اکیلی بھی سفر کر سکتی ہے۔ اگر کسی وجہ سے محرم کا ساتھ جانا ممکن نہ ہو جیسے فریضہ حج ہے اگر وہ صاحب استطاعت ہے تو حج اس پر فرض ہے۔ اگر خاوند یا کوئی اور محرم نہیں ہے یا اس کے ساتھ جانے کی پوزیشن ভ میں نہیں ہے تو وہ قابل اعتماد قافلے کی دیگر عورتوں کے ساتھ حج کے سفر پر جاسکتی ہے تاہم بعض علماء مطلقا بغیر محرم کے عورت کے سفر کو نا جائز قرار دیتے ہیں۔ چاہے عام سفر ہو یا کسی فریضہ کی ادائیگی کے لیے ہو۔ (فتح البارى، كتاب الحج، باب حج النساء، نيل الأوطار: ٣٢٤/٤) محرم سے مراد وہ شخص ہے جس سے ہمیشہ کے لیے عورت کا نکاح کرنا حرام ہے جیسے باپ، دادا، چا، تایا، ماموں، بھانجا، بیٹا،سر وغیرہ۔"}],[570,"سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: لوگو! عورتوں کا مہر بہت زیادہ نہ کرو کیونکہ اگر یہ لوگوں کے نزدیک عزت والی یا اللہ کے نزدیک تقوی والی بات ہوتی تو رسول اللہ طل علم اس کے زیادہ حق دار ہوتے مگر نبی صلی اللہ علیہ وسلم نے اپنی عورتوں میں سے جس عورت سے بھی نکاح کیا یا جس بیٹی کا بھی نکاح کیا اس کا مہر ١٢ اوقیہ اور ایک نش سے زائد نہ تھا۔ اور کوئی تم میں سے عورت کے مہر کو مہنگا کرتا ہے یہاں تک کہ وہ کہتا ہے کہ میں نے تجھے مشک کا کڑا بھی دینے میں کمی نہیں کی ( راوی کہتا ہے میں غیر خالص عربی لڑکا تھا اس لیے علق القربہ\" کو نہیں جانتا تھا۔“ یہ احادیث مغیرہ سے صرف سوید بن عبدالعزیز ہی روایت کرتے ہیں۔ فائد (١) مذکورہ حدیث سے مہر کی مشروعیت کا ثبوت ملتا ہے۔ (٢) نبی معظم ملنے کی یمن کی ازواج مطہرات، اور بیٹیوں کے حق مہر کی مقدار بھی معلوم ہوتی ہے۔ اوقیه: چالیس درہم کو کہتے ہیں۔ النش: نصف اوقیہ یعنی ہیں درہم۔ ایک حدیث میں ہے نبی معظم علیم نے فرمایا: ” بہترین مہر وہ ہے جس کی ادائیگی آسان ہو۔“ (صحيح الجامع الصغير، رقم: ٣٢٧٩، ابن حبان، رقم: ٤٧٢) معلوم ہوا کہ مہر کی کوئی شرعی مقدار نہیں بلکہ آدمی کی استطاعت کے مطابق ہے۔ امام ابن قدامہ اللہ نے فرمایا: مہر بہت زیادہ قیمتی نہ ہو۔ (المغنی: ١٠١/١٠) سعودی فتوی کمیٹی نے یہ فتویٰ دیا ہے کہ بہت زیادہ بڑھ چڑھ کر مہر مقرر کرنا جائز نہیں کیونکہ یہ چیز شوہر کونگی و مشقت میں مبتلا کرنے کا باعث ہوگی۔ (فتاوی اللجنة: ٧٤/١٩)","",{"k":"♦، سنن ابن ماجه (١٨٨٧)، سنن ابو داؤد، قال الشيخ الالبانی، حسن صحيح۔"}],[571,"سیدنا جابر بن عبد اللہ بنی یہ بیان کرتے ہیں، یہود کہتے تھے، جب کوئی آدمی اپنی عورت کی شرم گاہ میں پیچھے سے جماع کرے تو بچہ بھینگا ہوتا ہے تو اللہ تعالیٰ نے آیت نازل فرمادی: نِسَاءُ كُمْ حَرْثٌ لَّكُمْ یعنی تمہاری عورتیں تمہاری کھیتیاں ہیں۔“","",{"k":"٢٢٣] . )) ١٤٣٥ صحيح بخاری، صحيح مسلم، رقم۔","f":"مذکورہ آیت میں یہودیوں کی تردید کے لیے شریعت نے کہا کہ مباشرت آگے سے کرو ( چٹ لٹا کر ) یا پیچھے سے ( پیٹ کے بل ) یا کروٹ پر جس طرح چاہو جائز ہے لیکن یہ ضروری ہے کہ ہر صورت میں عورت کی فرج ہی استعمال ہو۔ بعض لوگ اس سے یہ استدلال کرتے ہیں ((انسی ششم)) میں تو دبر بھی آجاتی ہے لہذا دبر کا استعمال بھی جائز ہے لیکن یہ بالکل غلط ہے۔ جب قرآن نے عورت کو کھیتی قرار دیا ہے تو اس کا صاف مطلب یہ ہے کہ صرف کھیتی کے استعمال کے لیے یہ کہا جا رہا ہے کہ اپنی کھیتیوں میں جس طرح چاہو آؤ اور یہ کھیتی صرف فرج ہے نہ کہ د بر۔ بہر حال یہ غیر فطری فعل ہے ایسے شخص کو جو اپنی عورت کی دبر استعمال کرتا ہے ملعون قرار دیا گیا ہے۔ نبی مکرم مٹی ایم نے فرمایا: \"ملعون ہے وہ شخص جو بیوی سے دبر میں مباشرت کرتا ہے۔ (سنن ابی داؤد، کتاب النكاح، رقم: ٢١٦٢) ٥٧٢"}],[572,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”زمین کا وہ حصہ جو میری امت پر مجھ سے بعد فتح ہو گا وہ مجھ پر پیش کیا گیا تو اس چیز نے مجھے خوش کر دیا تو اللہ تعالیٰ نے یہ آیت نازل فرمادی: ﴿ وَالاخِرَةُ خَيْرٌ لَكَ مِنَ الأولى \"اور البتہ تمہارے لیے دنیا کی بہ نسبت آخرت بہتر ہے۔“ یہ آیات فرضی تک نازل ہوئیں یعنی عنقریب تجھے تیرا رب وہ کچھ دے گا کہ تو خوش ہو جائے گا۔ پھر اللہ تعالیٰ نے آپ کو جنت میں موتیوں کے ایک ہزار محل دے دیئے جن کی مٹی کستوری کی ہے۔ ہر محل میں ضرورت کی ہر چیز موجود ہوگی۔“ معلوم ہوا مذکورہ آیات میں اللہ ذوالجلال نے دنیا کی فتوحات اور آخرت میں اجر و ثواب کی خوشخبریاں دی ہیں۔ اس میں تسلی دی جا رہی ہے۔ اللہ کی فتح و نصرت، لوگوں کا فوج در فوج اسلام میں داخل ہونا، زمین کے مشارق و مغارب کا آپ کی امت کے قبضے میں آنا، قیامت کے دن آپ کے ہاتھ میں لواء الحمد ہونا، مقام محمود ملنا، شفاعت کبری، امت کی مغفرت، غرض وہ سب کچھ شامل ہے جو اللہ تعالیٰ نے آپ کو دیا اور دے گا۔","",{"k":"السلسلة الصحيحة، رقم : (٢٧٩٠)، مجمع الزوائد (٧/١٣٩)۔"}],[573,"سیدنا انس رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے اس آیت: إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللهَ وَرَسُولَهُ ) یعنی ان لوگوں کا بدلہ جواللہ تعالیٰ اور اس کے رسول سے لڑائی کرتے ہیں۔“ کے متعلق فرمایا کہ یہ لوگ قبیلہ عکل سے تعلق رکھتے ہیں۔“ یہ تمام احادیث معاویہ سے صرف مروان ہی روایت کرتے ہیں۔ ٥٧٤","",{"k":"١٨: صحیح بخاری، صحيح مسلم (٣٠١٨)۔"}],[574,"سيدنا علی رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جس شخص کی آخری بات لا إِلَهَ إِلَّا اللهُ\" ہوئی تو وہ جہنم میں نہیں جائے گا۔ یہ حدیث عطاء سے صرف ابوالاحوص ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبرانی (٢٤/١٥، ١٦٦٥٤)، قال الالباني: صحيح۔","f":"مذکورہ حدیث میں شرف و فضیلت ان کلمہ گولوگوں کے لیے ہے جو عملاً اس کے تقاضے پورے کرتے اور شرک و بدعت سے باز اور بیزار رہے محض رسمی اور رواجی طور پر کلمے کا ورد کرتے رہنے والے اور عملاً شرک و بدعت کے مرتکب اگر مرتے وقت بھی اس انداز میں کلمہ پڑھیں تو انھیں کچھ فائدہ نہ ہوگا۔ ٥٧٥"}],[575,"قیس بن عباد نے بیان کیا، میں نے سیدنا علی بنی لینے سے کہا: آپ اپنے اس جنگی سفر کے متعلق مجھے بتائیں کیا یہ رسول اللہ صلی اللہ علیہ وسلم نے آپ کو حکم دیا ہے؟ انہوں نے فرمایا: یہ میری اپنی رائے ہے جو میں نے خود ہی مناسب سمجھا۔ یہ حدیث یونس سے صرف ابن علیہ ہی روایت کرتے ہیں۔","",{"k":"على، رقم : ٤٦٦٦ . صحیح مسلم (٢٧٧٩)، سنن ابو داؤد۔","f":"سیدنا علی رضی اللہ عنہ کے زمانہ میں سیدنا عثمان رضی اللہ عنہ کی شہادت پر مسلمان دو گروہوں میں بٹ گئے تھے۔ ایک طرف سیدنا علی رضی اللہ عنہ طرف سیدنا معاویہ صلى الله، تنازعات ان کی اپنی اجتہادی آراء تھیں، اور اخلاص،حسن نیت کی وجہ سے دونوں ہی ماجور تھے۔ ٥٧٦"}],[576,"سیدنا عباس بن عبد المطلب رضی اللہ عنہ نے بیان کیا، رسول اللہ سے تم نے مدینہ کی طرف دیکھ کر فرمایا: ” ان اہل مدینہ کو جب تک ستارے گمراہ نہ کر دیں اللہ تعالیٰ نے انہیں بالکل پاک صاف کر دیا ہے۔“ یہ حدیث از یونس از حسن از احنف بن قیس از حضرت عباس از نبی کریم نے تم اسی کی مثل روایت کی گئی ہے۔ ٥٧","",{"k":"مسند ابو یعلی (٦٧١٤)، ضعيف الجامع الصغير (٤٧٠٥)، مجمع الزوائد (٣/٢٩٩)۔"}],[577,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ایک رات عشاء کی نماز کے لیے دیر سے تشریف لائے یہاں تک کہ لوگ سو گئے پھر جاگے تو سیدنا عمر رضی اللہ عنہ ہوئے اور عرض کیا، اللہ کے رسول م م! نماز تو آپ صلی اللہ علیہ وسلم تشریف لائے اور انہیں نماز پڑھائی اور یہ ذکر نہیں کیا کہ انہوں نے وضو کیا۔‘“ یہ حدیث یونس سے صرف حماد ہی روایت کرتے ہیں، اسے روایت کرنے میں یونس بن محمد المؤدب اور ابن عائشہ اکیلے ہیں۔ ایک روایت میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر یہ بات نہ ہوتی کہ میں اپنی امت پر مشقت ڈال دوں گا تو میں انہیں حکم دیتا کہ وہ عشاء کو ایک تہائی رات تک مؤخر کریں۔ (صحیح ترمذی، رقم: ١٤١، سنن ابن ماجه، رقم: ٢٩١) معلوم ہوا کہ نماز عشا تاخیر سے ادا کرنا افضل ہے لیکن یہ یادر ہے کہ یہ تاخیر نصف شب سے تجاوز نہ کرے، کیونکہ نصف شب نماز عشا کا آخری وقت ہے۔ اور یہ بھی یادر ہے کہ صرف عشا ہی ایسی نماز ہے جس میں تاخیر مستحب ہے باقی نمازیں اول وقت میں پڑھنا ہی مستحب ہے۔ نیند کے نواقض وضو ہونے کے متعلق تقریباً علماء کے ٨ مختلف اقوال ہیں۔ جن میں راجح بات یہ ہے کہ مطلقاً نیند ناقض وضو ہے خواہ نیند بیٹھ کر آئے یا لیٹ کر یا کھڑے ہو کر بشر طیکہ وہ گہری ہو اور اس سے شعور زائل ہو جائے۔ امام ابن حزم رحمہ اللہ۔ (المحلى بالاثار: ٢١٢/١) علامہ ناصر الدین البانی رحمہ اللہ۔ (تمام المنة: ص ١٠١) شیخ عبدالعزیز بن باز رحمہ اللہ ( فتاوی ابن باز مترجم:٤٩/١) نے اسی کے مطابق فتوی دیا ہے جبکہ امام شوکانی اللہ کی رائے ہے کہ لیٹ کر تکیہ لگا کر سونے سے وضو ٹوٹتا ہے بصورت دیگر نہیں۔ (نیل الاوطار؛٢٩٣/١) لیکن جن روایات سے معلوم ہوتا ہے کہ صرف لیٹ کر سونے والے کی نیند ہی ناقض الوضوء وہ ضعیف ہیں۔ ( تمام المسنة ص ١٠٢)","",{"k":"صحیح بخاری، صحيح ابن حبان، رقم : ٤٥٤٤ . المعجم الكبير للطبراني ٣٥٩/٩ (١١١٨٣)۔"}],[578,"سيدنا ابو ہریرہ رضی اللہ عنہ نے نبی ملنے کام سے روایت کیا، آپ نے فرمایا: ” جس شخص نے ایسا آدمی دیکھا جس کو مال اور تخلیق میں اس پر فضیلت دی گئی ہے تو وہ ایسے شخص کو دیکھے جو اس سے کم تر درجے کا ہو۔“ یہ حدیث محمد بن جبیر سے صرف ان کے بیٹے سعید ہی روایت کرتے ہیں، اسے روایت کرنے میں عبداللہ بن جعفر ا کیلے ہیں۔ معلوم ہوا کہ دنیا کے معاملے میں اپنے سے کم نعمت والوں کی طرف دیکھنا چاہیے اور دین کے معاملے میں ان کی طرف دیکھنا چاہیے جو اپنے سے اوپر ہیں جیسا کہ ارشاد باری تعالیٰ ہے: وَفِي ذلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ﴾ (المطففين: ٢٦) اور فرمایا: اور اس (جنت) میں ہی ایک دوسرے سے بڑھ کر رغبت کریں وہ لوگ جو ایک دوسرے کے مقابلے میں کسی چیز میں رغبت کرتے ہیں۔“ فَاسْتَبِقُوا الْخَيْرَاتِ﴾ (المائده: ٤٨) پس نیکیوں میں ایک دوسرے سے آگے بڑھو۔“ شریعت نے یہ کیوں حکم دیا ہے کہ دنیا کے معاملے میں اپنے سے کم کی طرف دیکھو۔ نبی مکرم ملے ہم نے خود ہی وضاحت فرما دی، فرمایا: ”اس شخص کی طرف دیکھو جو تم سے نیچے ہے اور اس شخص کی طرف نہ دیکھو جو تم سے اوپر ہے یہ زیادہ لائق ہے کہ تم اللہ کی اس نعمت کو حقیر نہ جانو جو تم پر ہے۔“ (صحیح بخاری، رقم: ٦٤٩٠) معلوم ہوا کہ اگر کوئی شخص انہی لوگوں کی طرف دیکھے گا جنہیں دنیا کی نعمتیں اس سے زیادہ دی گئی ہیں تو خطرہ ہے کہ اس کے دل میں خالق کا شکوہ پیدا ہو جائے یا اس شخص پر حسد ہو جائے، یہ دونوں چیزیں اس کی بربادی کا باعث ہیں۔ لہذا اگر کوئی تندرست ہے تو بیماری میں مبتلا لوگوں کی طرف دیکھے تو اس کو اس سے اللہ کی عطا کردہ صحت پر شکر کی نعمت حاصل ہوگی اگر کوئی بیمار ہے تو اس کی طرف دیکھے جو زیادہ بیمار ہے، بلکہ جس کے اعضاء ہی نہیں ہیں۔ فقیر ہے تو اپنے سے زیادہ محتاج کی طرف دیکھے وغیرہ وغیرہ۔","",{"k":"صحیح بخاری (٦٤٩٠)، صحیح مسلم (٢٩٦٣.٢٩٦٣)۔"}],[579,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، جب ابولؤلؤ نے سیدنا عمر رضی اللہ عنہ کو سنجر مارا تو انہوں نے خیال کیا کہ شاید لوگوں کے ساتھ میری کوئی زیادتی ہوئی ہے جو مجھے معلوم نہیں ہے اس لیے انہوں نے سیدنا عبداللہ ابن عباس نی نیہا کو بلایا اور وہ ان سے محبت کرتے تھے اور اپنے قریب کرتے تھے ان کی بات توجہ سے سنتے تھے انہیں کہنے لگے: میں چاہتا ہوں کہ تم لوگوں سے یہ معلوم کروں کہ یہ کام کس نے کیا ہے؟ سیدنا عبداللہ ابن عباس نا اپنا لوگوں کے جس گروہ سے بھی گزرتے وہ رو ہی رہے تھے۔ تو انہوں نے واپس آ کر یہی جواب دیا کہ میں مسلمانوں کی جس جماعت سے بھی گزرا انہیں روتے ہوئے ہی پایا گویا کہ ان کی پہلوٹی کی اولاد گم ہوچکی ہے۔ پھر آپ نے پوچھا: مجھے کس شخص نے قتل کیا ہے؟ انہوں نے کہا: ابولؤلؤ مجوسی نے جو مغیرہ بن شعبہ کا غلام ہے۔ کہنے لگے: الحمد للہ کہ اس نے مجھے اس شخص کی بات سے نہیں آزمایا جو لا الہ الا اللہ کہتا ہو۔ میں نے تمہیں ان کافروں میں سے کسی کو درآمد کرنے سے منع کیا تھا مگر تم نے میری بات نہ مانی۔ پھر انہوں نے کہا: میرے بھائیوں کو بلاؤ، لوگوں نے پوچھا: کس کو تو انہوں نے کہا: عثمان و علی، طلحہ و زبیر، عبد الرحمن بن عوف اور سعد بن ابی وقاص بھی ایم کو تو انہیں بلایا گیا۔ پھر انہوں نے اپنا سر میری گود میں رکھ دیا۔ جب وہ آگئے تو میں نے کہا: یہ تو آ پہنچے ہیں۔ انہوں نے کہا: میں نے لوگوں کے معاملے میں غور کیا تو تمہیں تمام لوگوں کا سردار اور راہنما پایا، اور یہ کام تم میں ہی رہنا چاہیے جب تک تم سیدھے رہے لوگ درست رہیں گے اگر اختلاف ہوا تو تم میں ہی اختلاف ہو گا۔ سیدنا عبداللہ ابن عباس روہی الجھا کہتے ہیں: جب میں نے اختلاف کا ذکر سنا تو میں نے خیال کیا کہ اختلاف واقع ہوگا کیونکہ بہت کم ہی ایسے ہوتا ہے کہ آپ نے کوئی بات کہی ہو اور میں نے نہ دیکھی ہو پھر آپ کا خون نچڑ گیا تو وہ لوگ اپنی باتیں آہستہ آہستہ کرنے لگے یہاں تک کہ میں ڈرنے لگا کہ وہ اپنے میں سے کسی کی بیعت کر لیں گے۔ میں نے کہا: ابھی امیر المؤمنین زندہ ہیں اور بیک وقت دوخلیفے نہیں ہو سکتے کہ ان میں ایک دوسرے کو دیکھتا ہو۔ سیدنا عمر رض الی یہ کہنے لگے: مجھے اٹھا کر لے جاؤ۔ ہم انہیں اٹھا کر لے گئے وہ کہنے لگے تم تینوں سے مشورہ کرو اور صہیب لوگوں کو نماز پڑھائیں۔ اس نے کہا: امیر المؤمنین! ہم کس سے مشورہ کریں؟ انہوں نے فرمایا: مہاجرین، انصار اور لشکروں کے سرداروں میں سے جو بھی یہاں موجود ہو۔ پھر تھوڑا سا دودھ منگوایا اور پی لیا تو دودھ کی سفیدی زخموں کے راستے باہر نکل آئی تب انہوں نے معلوم کر لیا کہ یہ موت کی نشانی ہے۔ وہ کہنے لگے: اب آنے والی چیز کی ہولنا کی سے بچنے کے لیے اگر مجھ سے ہو سکے تو تمام دنیا کا فدیہ بھی دے دوں مگر وہ میرے کسی کام نہیں آسکتا۔ تمام تعریف اللہ کے لیے ہے کہ میں نے صرف خیر ہی دیکھی ہے۔ تو سیدنا عبد اللہ ابن عباس ریلی اتنا کہنے لگے: جب آپ نے اس طرح کہا ہے تو اللہ تعالیٰ آپ کو جزائے خیر عطا فرمائے۔ کیا ایسے نہیں ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نے اللہ تعالیٰ سے یہ دعا مانگی کہ اللہ تعالیٰ دین اسلام اور مسلمانوں کو تمہاری وجہ سے عزت بخشے جبکہ وہ مکہ میں کفار سے خوف زدہ تھے۔ پھر جب مسلمان ہو گئے تو تمہارا اسلام ہماری عزت کا باعث بنا اور تمہاری وجہ سے اسلام، پیغمبر اسلام ملے علیم اور صحابہ کرام غالب رہے، پھر تم نے مدینہ کی طرف ہجرت کی تو آپ کی ہجرت بھی فتح ثابت ہوئی۔ پھر تم کسی بھی حاضری کی جگہ سے غائب نہیں رہے جہاں بھی نبی صلی اللہ علیہ وسلم تشریف لے گئے آپ بھی وہاں پہنچے، فلاں فلاں دن مشرکین سے جنگ میں آپ موجود تھے۔ پھر نبی صلی اللہ علیہ وسلم جب فوت ہوئے تو آپ سے راضی تھے۔ پھر آپ خلیفہ رسول ملے تعلیم سے آپ کے میثاق کے مطابق معاونت کی، پھر آپ نے آگے آنے والوں کے ذریعے پیچھے ہٹنے والوں کو مارا یہاں تک لوگ خوشی یا ناخوشی سے مکمل اسلام میں داخل ہو گئے۔ پھر جب خلیفہ آپ سے جدا ہوا تو وہ بھی آپ سے خوش تھے۔ پھر آپ مسلمانوں کے بہترین حاکم بنے اور آپ کے ذریعے شہروں کو آباد کیا، اور آپ کی وجہ سے وہ مال جمع کیے، اور دشمن کو دور بھگا دیا، اور ہر گھر والوں کو دین اور رزق میں کشادگی عطا فرمائی۔ پھر اس نے آپ کو شہادت کی موت عطا فرمائی تو آپ کے لیے خوشی اور مبارک ہے تو وہ کہنے لگے اللہ کی قسم! وہ شخص دھوکے میں مبتلا ہو گیا جسے تم نے دھوکے میں ڈالا، پھر کہا: اے عبد اللہ! کیا قیامت کے دن تو میرے حق میں گواہی دے گا؟ انہوں نے کہا: جی ہاں! تو وہ کہنے لگے: تمام تعریف اللہ کے لیے ہے۔ اے عبداللہ! میرا رخسار زمین کے ساتھ لگا دو تو میں نے انہیں اپنی ران سے اپنی پنڈلی پر رکھ دیا۔ انہوں نے پھر کہا: میرا رخسار زمین پر لگا دو پھر آپ نے اپنی داڑھی اور رخسار زمین کے ساتھ لگا دیئے اور کہنے لگے: اے عمر! افسوس تجھ پر اور تیری ماں پر بھی افسوس! اگر تجھے اللہ نے نہ بخشا۔ پھر ان کی روح قبض ہوگئی، اللہ ان پر رحم فرمائے۔ جب ان کی روح قبض ہو گئی تو لوگوں نے سیدنا عبد اللہ بن عمرنا الیہ کو بلایا تو وہ کہنے لگے: مہاجرین اور انصار اور لشکروں کے یہاں موجود سرداروں کے ساتھ مشورہ کرنے کے متعلق میرے والد نے تمہیں جو کہا ہے جب تک تم اس کے مطابق نہیں کرو گے میں تمہارے پاس نہیں آؤں گا۔ حسن بصری کہتے ہیں: وفات کے وقت اللہ تعالیٰ سے سیدنا عمر رضی اللہ عنہ کا خوف اور جو کام انہوں نے کیا تھا جب آپ کے لڑکے کو بتایا گیا تو وہ کہنے لگے اسی طرح ایمان دار آدمی نیکی اور شفقت جمع کرتا ہے جبکہ منافق برائی اور غرور سمیٹتا ہے اللہ کی قسم میں نے موجود اور فوت شدہ لوگوں میں سے کوئی شخص بھی ان سے بڑھ کر خوف وشفقت میں مبتلا نہیں پایا گذشتہ اور باقی ماندہ لوگوں میں سے جو شخص بھی برائی اور غرور میں مبتلا ہو گیا وہ دھوکہ میں مبتلا ہو گیا۔ یہ حدیث عبید اللہ بن عمر سے صرف مبارک بن فضالہ ہی روایت کرتے ہیں۔ مذکورہ روایت سے امیر المؤمنین سیدنا عمر رضی اللہ عنہ کا تقوی خشیت الہی، لوگوں کے ساتھ حسن معاملات کا تعلق معلوم ہوتا ہے۔ (١) سیدنا عبداللہ ابن عباس نو ایشیا کو بھیجا معلوم کرو شاید کہ میری طرف سے زیادتی ہوئی ہو جس کی وجہ سے مجھ پر حملہ کیا گیا۔ پتا چلا کوئی زیادتی نہیں۔ آج کے حکمرانوں کو اس بات سے سبق حاصل کرنا چاہیے کہ اپنی رعایا پر زیادتی پر زیادتی کرتے چلے جاتے ہیں تو نتیجتاً عوام حکمرانوں کے خلاف اٹھ کھڑے ہوتے ہیں۔ (٢) سیدنا عمر بنی اہلیہ نے خلافت کا معاملہ چھ آدمیوں پر چھوڑ دیا کہ ان میں کسی کو منتخب کر لینا۔ جو مسلمانوں کے بہترین آدمی تھے، اپنے رشتہ داروں کو ترجیح نہیں دی۔ (٣) یہ بھی معلوم ہوا کہ بیک وقت دو خلیفہ اور دو امیر جائز نہیں ہیں۔ (٤) جب سیدنا عمر رضی اللہ عنہ عادل اور منصف اور حق پرست اور متبع شرع اور صحابی اور خلیفۃ الرسول کو اللہ کا اتناڈر اور ایک ہم ہیں کہ دنیا میں مگن آخرت سے غافل نہ خوف خدا نہ فکر آخرت اللہ ہمارے حال پر رحم فرمائے۔ (١) سیدناعبداللہ ابن عباس نیا اینجا کا علمی مقام بھی معلوم ہوا۔","",{"k":"مصنف ابن ابي شيبة (٥٧٩/٨)، المعجم الكبير للطبراني (١١/١٦٠)۔"}],[580,"سیدنا ابوسعید خدری رضی اللہ عنہ نے نبی اللہ علیہ تم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ” نماز میں تسبیح مردوں کے لیے ہے (اگر امام بھول جائے تو مقتدی سبحان اللہ کہیں ) اور تالی بجانا عورتوں کے لیے ہے۔“","",{"k":"صحیح بخاری (١٢٠٣)۔"}],[581,"سیدنا حکیم بن حزام رضی اللہ عنہ نے بیان کیا، رسول اللہ علئے علیم نے مجھے منع فرمایا کہ میں ایسی چیز کی بیع کروں جو میرے پاس موجود نہیں۔“ یہ حدیث حماد بن زید سے صرف خالد بن خداش ہی روایت کرتے ہیں۔::٥٨٢ مذکورہ حدیث سے معلوم ہوا کہ جو چیز انسان کے پاس نہ ہو اس کا فروخت کرنا جائز نہیں۔","",{"k":"سنن ترمذی (١٢٣٣)، سنن ابو داؤد، رقم : ٣٥٠٣ . قال الالبانی: صحیح۔"}],[582,"سیدہ عائشہ بنی الجھا نے بیان کیا، جب اپنے اوپر الزام لگائے جانے کے متعلق مجھے خبر ملی تو میں نے ارادہ کیا کہ میں کسی کنویں پر جا کر اپنے آپ کو اس میں گرا ( کر اپنی زندگی کا خاتمہ کر ) لوں“ یہ حدیث ایوب سے صرف حماد بن زید ہی روایت کرتے ہیں، اسے روایت کرنے میں خالد بن خداش اکیلے ہیں۔ ایک عزت والی، پاک دامنه، شریف طاہرہ مطہرہ خاتون پر تہمت لگے تو اس غم وغصہ کی","",{"k":"المعجم الكبير للطبراني (١٦/٤٥٥، ١٨٦٨٢)۔","f":"یہی کیفیت ہوگی، ام المومنین سیدہ عائشہ رضی پہنچا نے بھی اپنی اسی حالت کا ذکر فرمایا ہے"}],[583,"سیدنا عبداللہ ابن عباس بنایا جا نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ عزوجل نے فرمایا: میں جس کی دو پیاری چیزیں یعنی آنکھیں لے لیتا ہوں پھر وہ صبر کرتا ہے اور ثواب کی امید رکھتا ہے تو جنت سے کم بدلہ پر میں اس کے لیے راضی نہیں ہوتا۔“ یہ حدیث ابی بشر سے صرف ہشیم ہی روایت کرتے ہیں اور حضرت ابن عباس سے یہ حدیث اسی سند سے مروی ہے۔","",{"k":"کی سنن ترمذی (٢٤٠١)، سنن ابن ماجه (١٥٩٧)، بخاری ادب المفرد (٥٣٥)۔"}],[584,"سیدنا علی بن ابی طالب رضی اللہ عنہ نے بیان کیا، جب کوئی آدمی مجھے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتا تو میں اس سے حلف لیتا، پس جب وہ قسم اٹھاتا تو میں اس کو سچا مان لیتا۔ اور مجھے سیدنا ابوبکر صدیق رضی اللہ عنہ نے ایک حدیث بیان کی اور سیدنا ابو بکر ضیا اللہ نے سچ کہا کہ رسول اللہ نعیم نے فرمایا: ” جو شخص بھی کوئی گناہ کرتا ہے، پھر وہ دو رکعت نماز پڑھ کر اللہ تعالیٰ سے اس گناہ کی معافی مانگتا تو اللہ تعالیٰ اس کو معاف کر دیتا ہے۔ یہ حدیث معاویہ بن ابی العباس سے صرف مروان ہی روایت کرتے ہیں، اسے روایت کرنے میں عیسی بن مساورا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ توبہ و استغفار کی نیت سے نماز پڑھنا مستحب ہے۔ سیدنا علی یا اللہ کا دیگر صحابہ کرام بی ایم سے احادیث کے سلسلے میں قسم لینا اعتماد مزید کے لیے ہوتا تھا۔ اور فرمان نبوی ملتے تم پر اس وقت عمل واجب ہوتا ہے جب وہ کامل شروط کے ساتھ صحیح ثابت ہو۔ اور سیدنا ابو بکر صدیق رضی اللہ عنہ سے قسم نہ لینا ان کے مرتبے کی بلندی، ان کا احترام، ان کے صدق پر گہرا اعتماد اور ان کے باہمی برادرانہ روابط کا واضح ثبوت ہے۔","",{"k":"سنن ابو داؤد، رقم : ١ (١٥٢١)، سنن ترمذی (٣٠٠٦)، قال الشيخ الالباني، صحیح۔"}],[585,"سيدنا جریر رضی اللہ عنہ نے بیان کیا، میں نے نماز قائم کرنے، زکوۃ ادا کرنے اور ہر مسلمان کی خیر خواہی کرنے پر رسول اللہ صلی اللہ علیہ وسلم کی بیعت کی۔“ یہ حدیث داؤد بن ابی ھند سے صرف اسماعیل بن زکریا ہی روایت کرتے ہیں، اسے روایت کرنے میں سعید بن سلیمان اکیلے ہیں۔","",{"k":"صحیح بخاری (٥٨)، سنن ترمذی (١٩٢٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسلمان کو ایک دوسرے کا خیر خواہ ہونا چاہیے۔ جیسا کہ نبی معظم علیم نے فرمایا: کہ دین، اللہ کی فرمانبرداری، اس کے رسول، اور مسلمان حکمرانوں، اور تمام مسلمانوں کی خیر خواہی کا نام ہے۔ (صحیح بخاری: ٥٨)"}],[586,"\"سیدنا عبد الرحمن بن سمرہ بنی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: عبد الرحمن! امارت و حکومت کا کبھی سوال نہ کرنا، کیونکہ اگر تم نے حکومت بن مانگے لی تو اس پر مدد کی جائے گی اور اگر تو نے وہ مانگ کر لی تو تمہیں اس کی طرف سونپ دیا جائے گا۔ اور جب تم کسی بات پر قسم کھاؤ اور اس کے غیر کو اس سے بہتر سمجھو تو جو چیز بہتر ہے اس پر عمل کرو اور اپنی قسم کا کفارہ دے دو۔“ یہ حدیث سفیان سے صرف سوید ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن المساورا کیلے ہیں۔","",{"k":"صحیح مسلم (١٦٥٢)، سنن ابو داؤد (٢٩٢٩)۔"}],[587,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما کے اس فرمان: ﴿ مَا قَطَعْتُمْ مِنْ لِيْنَةٍ اَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِاِذْنِ اللهِ \" تم جو بھی کھجور کا درخت کاٹ رہے تھے یا اس کو اپنی جڑوں پر کھڑا چھوڑ دیتے تھے تو وہ اللہ کے حکم سے تھا۔“ کے متعلق فرماتے ہیں کہ لينة سے مراد کھجور کا درخت ہے اور لِيُخْزِي الْفَاسِقِينَ ﴾ کا شان نزول یہ ہے کہ مسلمانوں نے انہیں قلعوں سے اترنے کا حکم دیا نیز ان کی کھجوروں کے درخت کاٹنے کا حکم دیا تو ان کے دل میں یہ بات کھٹکی تو مسلمان کہنے لگے ہم نے کچھ درخت تو کاٹ دیئے تو کچھ چھوڑ دیئے تو ہم رسول اللہ صلی اللہ علیہ وسلم سے پوچھیں گے کہ جو درخت ہم نے چھوڑ دیئے ہیں کیا ان کے کاٹنے پر ہمارے لیے کوئی اجر اور چھوڑنے پر کوئی بوجھ اور گناہ تو نہیں؟ اس وقت اللہ تعالیٰ نے یہ آیت نازل فرما دی کہ تم نے جو بھی کھجور کا درخت کاٹ دیا یا اسے اپنی جڑوں پر چھوڑ دیا ہے یہ سب اللہ کے حکم سے ہوا، تاکہ فاسق لوگوں کو اللہ تعالیٰ ذلیل کرے۔“ یہ حدیث حبیب بن ابی عمرہ سے صرف حفص ہی روایت کرتے ہیں، اسے روایت کرنے میں عفان اکیلے ہیں۔","",{"k":"سنن ترمذی (٣٣٠٣)، سنن ابو داؤد (٢٦١٥)، قال الشيخ الالبانی صحیح الاسناد۔","f":"معلوم ہوا کہ جنگی ضرورت اور مصلحت کے تحت آگ لگانا یا مکانات گرانا جائز ہے البتہ محض فساد پھیلانے کی نیت سے کرنا جائز نہیں۔ جیسا کہ مسلمانوں نے ان کے درختوں کو جلایا اور کچھ کو کاٹ دیا مقصد یہود کی رسوائی تھا اور اللہ تعالیٰ نے یہودیوں کو رسوا کیا۔"}],[588,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: \"جو شخص اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتا ہے وہ ازار باندھ کر ہی حمام میں داخل ہو۔ اور جو شخص اللہ تعالیٰ پر اور آخرت کے دن پر ایمان رکھتا ہے وہ اس دستر خوان پر نہ بیٹھے جس پر شراب کا دور چل رہا ہو۔“ یہ حدیث لیث سے صرف حسن ہی روایت کرتے ہیں۔ پہلے زمانے میں شہروں میں، بالخصوص مشرق وسطی میں مخصوص انداز سے اجتماعی غسل خانے بنائے جاتے تھے جہاں موسم کے مطابق پانی وغیرہ مہیا ہوتا تھا۔ اور بعض ایسی بیماریاں جو مالش اور غسل سے قابل علاج ہوتیں ان کا علاج بھی کیا جاتا تھا۔ ان میں مرد، عورتیں سبھی آتے تھے اور پردے کا کوئی خیال نہ رکھا جاتا تھا اسلام نے مردو زن کے اختلاط اور بے پردگی کو حرام قرار دیا اور ان اجتماعی غسل خانوں کی بابت بھی اصلاحی ہدایات بیان فرمائیں۔ نبی مکرم سے ہم نے پہلے مطلق حمام میں جانے سے منع فرما دیا مگر بعد میں مردوں کو اجازت دے دی کہ چادر باندھ کر جا سکتے ہیں (دوسروں کے سامنے عریاں نہ ہوں)۔ (سنن ترمذی کتاب الادب، رقم: ٢٨٠٢، سنن ابی داؤد، رقم اسی طرح معلوم ہوا کہ مومن کے لیے ایسے دستر خواں پر بیٹھنا جائز نہیں جس پر شراب کا دور چلتا","",{"k":"سنن ترمذی (٢٨٠١)، السنن الكبرى للبيهقي (٧/٢٦٦)، قال الشيخ الالباني: حسن۔"}],[589,"سیدنا مجزاہ بن زاہر اپنے باپ سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے عاشورہ کے روزے کا حکم دیا تو پھر فرمایا: ” جو شخص روزہ دار ہے تو وہ اپنا روزہ پورا کرے اور جو روزہ دار نہیں تو وہ اپنے باقی دن کا روزہ مکمل کرے۔“ یہ حدیث مجزاہ سے صرف شریک ہی روایت کرتے ہیں۔","",{"k":"صحيح بخارى (٢٠٠٣)۔"}],[590,"سیدنا عبداللہ ابن عباس نیہا نے بیان کیا، نبی صلی اللہ علیہ وسلم کے پاس سیدنا ابو بکر رضی اللہ عنہ کی ایک ایسی نشست ہوتی جہاں سے وہ صرف سیدنا عباس نبی اللہ ہی کے لیے اٹھتے تھے اور یہ چیز نبی صلی اللہ علیہ وسلم کے لیے خوشی کا باعث تھی۔ ایک دن سیدنا عباس نبی اللہ آئے تو ابو بکر یا اللہ ان کے لیے اپنی مجلس سے ہے تو رسول اللہ ما علیم نے فرمایا: ”کیا وجہ ہے؟ ابو بکر ضی الیہ نے کہا: اللہ کے رسول اللہ ملتے! آپ کے چچا آگئے ہیں تو آپ انہیں دیکھ کر ابو بکر رضی اللہ عنہ کی طرف مسکراتے ہوئے متوجہ ہوئے اور فرمانے لگے: ”یہ عباس ہیں اور یہ سفید کپڑے پہنے ہوئے ہیں اور عنقریب ان کی اولاد ان کے بعد سیاہ لباس پہنے گی، اور ان سے بارہ آدمی بادشاہ ہوں گے۔“ جب عباس رضی اللہ عنہ آئے تو انہوں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! آپ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ کو کیا کہا تھا؟ تو آپ نے فرمایا: ”میں نے اچھی بات ہی کہی ہے، سیدنا عباس رضی اللہ عنہ نے کہا، میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان ہوں! آپ میم اچھی بات ہی فرماتے ہیں۔ آپ نے فرمایا: ”میں نے کہا یہ میرا چچا آ گیا ہے اور یہ سفید لباس پہنے ہوئے ہے مگر عنقریب ان کے بعد ان کی اولا د سیاہ لباس پہنے گی اور اس سے بارہ آدمی بادشاہ ہوں گے۔“ یہ:٥٩١ حدیث اسحاق سے صرف حفص ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن صالح اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٥٤/٩، ١٠٢٧)، قال الهيثمي فيه جماعة لم اعرفهم، مجمع الزوائد (٩/٢٧٠)۔"}],[591,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی نے ان کھجور کے ایک تنے کے پاس خطبہ ملل دیا کرتے تھے، جب منبر بن گیا تو یہ تنا آواز سے رونے لگا، آپ صلی اللہ علیہ وسلم نے دلاسہ دیا تو وہ خاموش ہو گیا۔“ یہ حدیث اوزاعی سے صرف ولید بن مسلم روایت کرتے ہیں، اسے روایت کرنے میں عیسی بن مساورا کیلے ہیں۔","",{"k":"رقم : ١ المعجم الكبير للطبرانی (١٠/٣٣٠، ١٢٦٧٠)، مسند احمد: ٣/۔"}],[592,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں مدینے میں بارش نہ برسی تو بھاؤ مہنگا ہو گیا،لوگوں کو مال ہلاک ہونے کا خطرہ ہو گیا، یہاں تک کہ ہمیں اپنی جانوں کی ہلاکت کا بھی خطرہ محسوس ہونے لگا تو ہم نے عرض کیا، آپ دعا کریں کہ اللہ تعالیٰ بارش برسائیں، پس رسول اللہ علی علیم نے اپنے ہاتھ آسمان کی طرف اٹھائے اللہ کی قسم! ہمیں کہیں بھی بادل کی سفیدی نظر نہ آتی تھی مگر آپ نے ابھی اپنے ہاتھ دعا کر کے سمیٹے بھی نہیں تھے کہ آسمان اس جانب سے اور اس جانب سے پھٹ گیا اور ہر طرف بادلوں کے بڑے بڑے ٹیلے نظر آنے لگے، پھر سات دن اور سات راتیں بارش برستی رہی۔ ایک جمعے سے دوسرے جمعے تک برستی رہی اور آسمان مینہ برساتا رہا تو انہوں (لوگوں) نے عرض کیا: اب تو ہم ڈوب جانے سے ڈر رہے ہیں اس لیے اللہ سے دعا کریں کہ وہ اسے روک لے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ہاتھ اٹھائے دیکھا جبکہ آسمان میں کہیں سے بھی اس کا سبزہ پن نظر نہیں آرہا تھا آپ نے دعا کی ”اے اللہ! ہمارے اردگرد اس کو برسا، اور ہم پر نہ برسا، انس خلیل اللہ کہتے ہیں اللہ کی قسم میں نے دیکھا ابھی آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سمیٹے نہیں تھے کہ بادل چھٹ گئے۔“ مذکورہ حدیث سے معلوم ہوا کہ جمعہ میں بارش کے لیے دعا کرنا درست ہے، اسی طرح بارش یا دیگر اجتماعی امور کے لیے اجتماعی طور پر ہاتھ اٹھا کر دعا کرنا جائز ہے۔ یہ بھی معلوم ہوا کہ دعا کے آداب میں سے ہے کہ ہاتھ اٹھا کر دعا کی جائے۔","",{"k":"صحیح بخاری (٦٠٩٣)، سنن ابو داؤد (١١٧٤)، سنن نسائی (١٥٠٤)۔"}],[593,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” مہینہ عبداللہ انتیس کا ہے، پس جب تم چاند دیکھو تو روزہ رکھ لو اور جب اس (عید کے چاند ) کو دیکھ لوتو روزہ رکھنا بند کر دو، اگر تم پر مطلع ابر آلود ہو تو اندازہ کر لو یعنی تمیں پورے کر لو۔“ یہ حدیث عدی بن فضل سے صرف ابو بلال ہی روایت ·:٥٩٤ کرتے ہیں۔","",{"k":"کر صحیح بخاری کتاب الصوم (١٩٠٩)۔"}],[594,"و سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قریش مجھے تکلیف پہنچانے سے باز رہے حتی کہ ابو طالب وفات پاگئے۔ یہ حدیث ہشام بن عروہ سے صرف قیس ہی روایت کرتے ہیں، اسے روایت کرنے میں ابو بلال اکیلے ہیں۔","",{"k":"و، و، و، وهو ضعيف . مجمع الزوائد (١٥/٦)، كنز العمال، رقم : ٣٤٤٤٠ فيه ابوبلال الاشعرى۔"}],[595,"سیدنا عبد اللہ نے بیان کیا، رسول اللہ نے امی کی سب سے پسندیدہ دعا یہ تھی کہ تین بار دعا کی جائے۔“ یہ حدیث از ابواسحاق از ابوعبیدہ صرف زائده ہی روایت کرتے ہیں، اسے روایت کرنے میں حسین اکیلے ہیں۔ محدثین نے ابو اسحاق سے، انہوں نے محمد بن مرہ سے، انہوں نے عبداللہ سے روایت کی۔ ٩٦","",{"k":"سنن ابو داؤد (١٢٤)، مسند احمد (١/١٤)، مجمع الزوائد (١٠/١٥١)۔"}],[596,"سيدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (بچے کی ولادت کے وقت اس کے چیخنے چلانے کے متعلق) دایہ کی گواہی کو نافذ فرمایا یہ حدیث اعمش سے صرف محمد بن عبدالملک ہی روایت کرتے ہیں۔","",{"k":"السنن الكبرى للبيهقي (١٠/١٥١)، نصب الراية / ٤٥١، مجمع الزوائد۔"}],[597,"فعى جاللہ نے بیان کیا، جب سیدنا حسین بن علی علی پہنچا نے عراق کی طرف خروج کا ارادہ کیا تو انہیں سیدنا عبداللہ ابن عمر بنی الینہ نے کہا: آپ وہاں نہ جائیں کیونکہ نبی نے تم کو دنیا اور آخرت کے درمیان اختیار دیا گیا تو آپ نے آخرت کو پسند کیا، اس لیے آپ میں سے اور آپ کی اولاد میں سے کوئی بھی اسے حاصل نہیں کر سکے گا۔ مگر جب انہوں نے انکار کر دیا تو ابن عمر رضی اللہ عنہما نے کہا: میں تمہیں مقتول سے اللہ کے سپر د کرتا ہوں۔“ یہ حدیث امام شعمی سے صرف یحییٰ بن اسماعیل بن سالم ہی روایت کرتے ہیں اور بیٹی بن اسماعیل سے صرف سعید بن سلیمان اور شبابہ بن سوار ہی روایت کرتے ہیں۔ مذکورہ روایت اور تاریخ اسلام کی بے شمار کتب میں یہ بات موجود ہے کہ سیدنا حسن بن علی نیا این کوصحابہ کرام یعنی ایام میں نے کوفہ کی طرف جانے سے روکا تھا کیونکہ کوفی وفادار نہیں ہیں مگر سیدنا حسین رضی اللہ عنہما ارادے سے باز نہ آئے اور پھر بعد میں میدان کربلا میں کوفیوں نے جو سیدنا حسین فضل اللہ اور ان کے گھر والوں سے جو سلوک کیا وہ تاریخ اسلام کا المناک واقع اور سیاہ باب ہے","",{"k":"صحيح الجامع الصغير (٥٧٩١)، المعجم الكبير (١١/١٦٤)۔"}],[598,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ ملتے سلیم نے فرمایا: ”لوگوں کی بدگمانی سے بچ کر رہو۔ “ یہ حدیث حضرت انس سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں بقیہ اکیلے ہیں۔","",{"k":"السنن الكبرى للبيهقی (١٠/١٢٩)، ضعيف الجامع الصغير (١٨٢)، السلسلة الضعيفة (٣/١٥٠، ١١٥١)۔"}],[599,"سیدنا ابوامامہ نبی الیہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: کم از کم حیض تین دن ہے اور زیادہ سے زیادہ دس دن ہوتا ہے۔ یہ حدیث مکحول سے صرف علاء ہی روایت کرتے ہیں۔ تاہم حیض کے لیے کم از کم یا زیادہ سے زیادہ کوئی وقت یا عمر مقرر نہیں۔ (فتاوى المرأة المسلمة: ٢٦٦/١) ٦٠٠","",{"k":"السلسلة الضعيفة (٣/٤١٣، ١٤١٤)، ضعيف الجامع الصغير (١٠٧٧)۔"}],[600,"سیدنا عدی بن حاتم رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے بیان کیا، آپ نے فرمایا: ”قریب ہے کہ کسی آدمی کو یہ بات فکر مند کرے کہ اس سے اس کا صدقہ کون قبول کرے گا وہ اسے نہیں پائے۔“ یہ حدیث مبارک سے صرف سعید ہی روایت کرتے ہیں۔ فائد نبی مکرم م علیم نے پیش گوئی فرمائی کہ مال اتنا زیادہ ہو جائے گا کہ کوئی زکاۃ لینے والا ہی نہیں ہوگا تاریخ گواہ ہے کہ سیدنا عمر بن عبد العزیز جماللہ کے زمانے میں ایسے ہوا۔ مہاجر بن یزید کا بیان ہے کہ ہم لوگ صدقہ تقسیم کرنے پر مقرر تھے ایک ہی سال میں یہ حال ہو گیا ایک سال پہلے جو لوگ صدقہ لیتے تھے وہ دوسرے سال دوسروں کو صدقہ دینے کے قابل ہو گئے تھے۔ (سیرۃ عمر بن عبد العزیز بص: ٩٠۔ تاریخ اسلام:شاہ معین الدین احمد ندوی: ٥٢٣،٥٢٢/٢) اور پھر قرب قیامت کو سیدنا عیسی علی نام کے زمانے میں بھی ایسا ہوگا۔","",{"k":"صحیح مسلم، رقم : ١٠١١ . مصنف ابن ابي شيبة (٤٥٥/٨)۔"}],[601,"سیدنا عبد اللہ بن عمرو بنی لینہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص بنجر زمین آباد کرے گا تو وہ اسی کی ملکیت ہو جائے گی۔ اور ظالم رگ کا کوئی حق نہیں۔“ یہ حدیث از ہشام از والد خود از حضرت عبداللہ بن عمر وصرف مسلم ہی روایت کرتے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ جو بنجر زمین کو آباد کرے تو وہ زمین اسی کی ہوگی جس نے آباد کی۔ لیکن آج کل حکومت تمام زمینوں کی مالک اور متصرف ہوتی ہے اس لیے پہلے اس سے اجازت لینا قرین قیاس ہے۔ ویسے حکومت کی طرف سے بھی آباد کاری اسکیمیں متعارف کرائی جاتی ہیں۔","",{"k":"ترمذی (١٣٧٨)، قال الشيخ الالباني : صحيح. : سنن ابو داؤد (٣٠٧٣)، سنن۔"}],[602,"سیدہ عائشہ رضی اللہ عنہا نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے کہا: انہوں نے فرمایا: پانچ جانور ہیں جو سب کے سب فاسق ( ضرر رساں) ہیں انہیں حرم میں بھی اور حلال جگہ میں بھی قتل کیا جائے گا اور انہیں محرم بھی قتل کرے گا (١) چیل (٢) سانپ (٣) چوہا (٤) بچھو (٥) کاٹنے والا کتا۔“ یہ حدیث اسماعیل بن امیہ سے صرف ابن ابی لیلیٰ ہی روایت کرتے ہیں، ان سے صرف اُن کی اولاد ہی روایت کرتی ہے۔ مذکورہ حدیث سے معلوم ہوتا ہے کہ مذکورہ جانوروں کو ہر جگہ قتل کر دینا چاہیے، خواہ","",{"k":"صحیح بخاری (١٨٢٩)، صحیح مسلم (٢٠٠)۔","f":"انسان حرم میں ہو یا باہر۔ یہ بھی معلوم ہوا کہ ان جانوروں کو قتل کرنے میں ثواب ہے۔ امام بغوی واللہ فرماتے ہیں کہ مذکورہ جانوروں کو حلت و احترام میں قتل کرنے کے جواز پر اہل علم متفق ہیں۔ علاوہ ازیں امام شافعی اللہ نے ہر ماکول اللحم جانور کو بھی انہی پر قیاس کرتے ہوئے کہا ہے کہ جو شخص حالت احرام میں یا حرم میں ان میں سے کسی (یعنی ماکول اللحم میں سے کسی ) جانور کو قتل کر دے تو اس پر کوئی فدیہ نہیں۔ (كما في الروضة النديه: ٦١٢/١)"}],[603,"همام بن یحیی نے بیان کیا، قتادہ ہراللہ سے اس آدمی کے متعلق پوچھا گیا جس کی صبح کی نماز سے ایک رکعت فوت ہوگئی یہاں تک کہ سورج طلوع ہو گیا تو انہوں نے کہا: مجھے خلاس بن عمرو نے ابو رافع سے بیان کیا کہ ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا آپ نے فرمایا: ”اس کے ساتھ دوسری رکعت ملالے۔“ یہ حدیث قتادہ سے صرف تمام ہی روایت کرتے ہیں۔","",{"k":"الارناؤط اسناده صحیح . المعجم الكبير للطبراني (١٩/١٢٧)، مسند احمد (٢/٤٩٠)، قال شعیب۔","f":"ایک حدیث میں ہے کہ نبی مکرم ملنے سلیم نے فرمایا: ”جس نے طلوع آفتاب سے پہلے نماز فجر کی ایک رکعت پالی اس نے نماز فجر پالی اور جس نے غروب آفتاب سے پہلے نماز عصر کی ایک رکعت پالی اس نے نماز عصر پالی۔(صحیح بخاری، کتاب مواقيت الصلاة، رقم: ٥٧٩، صحیح مسلم، رقم: ٦٠٨) معلوم ہوا کہ طلوع آفتاب اور غروب آفتاب کے وقت نماز کی ابتدا کرنا ہی ممنوع ہے لیکن اگر کوئی پہلے ابتدا کر چکا ہو تو وہ اپنی نماز جاری رکھ سکتا ہے۔ اس سے یہ بھی معلوم ہوا کہ نماز فجر کا وقت طلوع آفتاب تک اور نماز عصر کا وقت غروب آفتاب تک ہے۔ علاوہ ازیں یہ بھی معلوم ہوا کہ طلوع آفتاب اور غروب آفتاب سے پہلے ایک رکعت پانے والے کو چاہیے کہ وہ اپنی باقی نماز بھی مکمل کرے کیونکہ اس کی نماز ادا ہو جائے گی۔ ٦٠٤"}],[604,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب قضائے حاجت سے فارغ ہوتے تو میں آپ صلی اللہ علیہ وسلم کے پاس پانی لاتا آپ ملے لیے تم اس سے استنجاء کرتے اور اپنا ہاتھ زمین پر رگڑتے تھے۔“ یہ حدیث ابوزرعہ سے صرف ابراہیم بن جریر ہی روایت کرتے ہیں، اسے روایت کرنے میں شریک اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ استنجا کے بعد آدمی اپنا ہاتھ زمین پر رگڑ لے یہ مسنون","",{"k":"المعجم الكبير للطبرانی (١٩/١٢٧)، سنن ابن ماجه رقم : ٣٥٨ قال الشيخ الالبانی حسن، سنن نسائی (٥٠)۔","f":"ہے، کیونکہ اس سے بو کا شائبہ بھی نہ رہے گا اور جہاں مٹی میسر نہ ہو وہاں صابن وغیرہ استعمال کر لیا جائے۔ ٦٠٥"}],[605,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آج کے دن گھوڑ دوڑ کا مقابلہ ہے اور کل کے دن آگے بڑھ جانا ہے اور انجام کار جنت یا جہنم ہے، جو آگ میں چلا گیا وہ ہلاک ہو گیا۔ میں اول ہوں، ابو بکر صدیق ضیا یہ نماز پڑھانے والے ہیں، اور عمر بن الخطاب رضی اللہ عنہ لوگ میرے بعد دوڑ و مقابلے کے مطابق ہوں گے۔ جو پہلے ہوگا اور پھر وہ جو اس کے بعد ہوگا۔“ یہ حدیث قرہ سے صرف عبد الرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں ولیدا کیلے ہیں۔ ٦٠٦","",{"k":"المعجم الكبير للطبرانی (١٠/٢٦٥، ١٢٤٧٧)، الضعفاء لابن عدى (٤٠٤/١)۔"}],[606,"مرزوق بیان کرتے ہیں: میں سیدنا ابو ہریرہ رضی اللہ عنہ سے شام میں ملا تو انہوں نے مجھے فرمایا: تم فرزدق ہو؟ میں نے کہا: جی ہاں، انہوں نے کہا: تم شاعر ہو؟ میں نے کہا: جی ہاں، کہنے لگے: اگر تم کچھ عرصہ زندہ رہے تو ایسے لوگوں سے ملو گے جو کہیں گے تیرے لیے تو بہ کی کوئی گنجائش نہیں مگر تم اللہ سے امید توڑنے سے بچ کے رہنا۔ یہ حدیث فرزوق سے صرف حبیب ہی روایت کرتے ہیں، اسے روایت کرنے میں صالح المری اکیلے ہیں","",{"k":"مجمع الزوائد (١٠/٢١٥)، اسناده ضعيف۔"}],[607,"سیدنا عبداللہ ابن عباس ریلی للہا نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: جس شخص نے غلام آزاد کیا تو اس کا ساز و سامان آزاد کرنے والے کا ہو گا۔ اور سیدہ بریرہ بنی نوپا کو صدقہ کا گوشت دیا گیا، تو انہوں نے اس سے کچھ سیدہ عائشہ بینی اشیا کو بطور تحفہ دے دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: وہ اس پر تو صدقہ ہے مگر ہمارے لیے وہ تحفہ ہے۔“ یہ حدیث قتادہ سے صرف ہمام ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا ولاء ( آزادی کی نسبت ) اس کی ہے، جو آزاد کرے گا۔ ولاء کی تعریف یہ ہے کہ، ایسا تعلق جس کی وجہ سے مالک اپنے آزاد کردہ غلام کا وارث بنتا ہے بشرطیکہ اس کے اقربا موجود نہ ہوں۔ (الفرائض: ص ٢٠) (٢) یہ بھی معلوم ہوا کہ اگر کسی کو صدقہ دیا گیا ہوتو وہ دوسرے کو آگے تحفہ دے سکتا ہے۔","",{"k":"صحیح بخاری (١٤٩٥، ١٤٩٤)۔"}],[608,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے مجھے خواب میں دیکھا تو اس نے گویا کہ مجھے بیداری میں دیکھا کیونکہ شیطان میری شکل اختیار نہیں کر سکتا۔“ حضرت عبداللہ بن عمرو سے یہ حدیث اسی سند سے ہی مروی ہے۔","",{"k":"صحيح مسلم (٢٢٦٦)، سنن ترمذی (٢٢٧٦)، سنن ابو داؤد (٥٠٢٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم کا یہ خاصہ ہے کہ شیطان نبی مکرم طالة ملے کی کمی کی شکل اختیار نہیں کر سکتا، تاہم یہ ممکن ہے کہ شیطان کسی بزرگانہ شکل میں آئے اور اس کو مغالطے میں ڈال دے کہ اس نے رسول اللہ صلی اللہ علیہ وسلمن کو خواب میں دیکھا ہے۔ اس لیے ہر مسلمان کو نبی مکرم نے یم کا حلیہ مبارک یاد ہونا چاہیے تا کہ شیطان اس کو دھو کے میں نہ ڈال سکے۔"}],[609,"سیدنا انس بن مالک نبی اللہ نے نبی ملے عام سے روایت کیا، آپ نے جبریل عالی سلام سے اور وہ اللہ تعالیٰ سے روایت کرتے ہیں کہ اللہ تعالیٰ نے فرمایا: ” جس نے میرے کسی دوست کی اہانت کی تو اس نے میرے ساتھ اعلان جنگ کر دیا۔ یہ حدیث عبدالکریم سے صرف صدقہ روایت کرتے ہیں، اسے روایت کرنے میں عمرا کیلے ہیں۔","",{"k":"السلسلة الضعيفة (٤/٢٧٤، ١٧٧٥)، الضعفاء لابن عدى: ٥/۔","f":"مذکورہ روایت کمزور ہے، تاہم اللہ کے ولیوں کا احترام کرنا ضروری ہے۔ اللہ کے دوستوں کی تو ہین نہیں کرنا۔"}],[610,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” میری قبر اور منبر کے درمیان جنت کے باغوں میں سے ایک باغ ہے۔“ یہ حدیث ابن عظیم سے صرف بیٹی ہی روایت کرتے ہیں، اسے روایت کرنے میں ابوحصین اکیلے ہیں۔ مذکورہ حدیث میں یہ ہے کہ میری قبر اور منبر کے درمیان بخاری میں ہے کہ میرے گھر اور منبر کے درمیان، معلوم ہوا کہ نبی معظم سے عیدین کو اللہ تعالیٰ نے پہلے آگاہ کر دیا تھا کہ آپ اس حجرہ میں قیامت تک آرام فرمائیں گے۔ بیان کردہ مبارک قطعہ حقیقتا جنت کا ایک ٹکڑا ہے۔ بعض نے کہا: اس کی برکت اور خوبی کی وجہ سے مجازاً ایسا کہا گیا یا اس لیے کہ وہاں عبادت کرنا خصوصی طور پر دخول جنت کا ذریعہ ہے۔ منبر کے بارے میں جو فرمایا قدرت خداوندی سے یہ بعید نہیں کہ قیامت کے دن حوض کوثر پر اس منبر کو دوبارہ مہیا کر کے آپ صلی اللہ علیہ وسلم کے لیے رکھ دیا جائے۔","",{"k":"بين القبر والمنبر (١١٩٥، ١١٩٦)، صحیح مسلم (١٣٩٠.١١٩٥)، صحیح بخاری کتابفضل الصلاة في مسجد مكة والمدينة۔"}],[611,"سیدنا عمرو بن العاص رضی اللہ عنہ نے بیان کیا، ہمارا یہ خیال نہیں تھا کہ رسول اللہ صلے کے جس دن فوت ہوئے اور وہ کسی آدمی کو دوست رکھتے ہوں پھر اس کو اللہ تعالیٰ جہنم میں داخل کر دے۔ انہیں کہا گیا: آپ کو بھی عامل بناتے تھے؟ تو انہوں نے کہا: اللہ تعالیٰ زیادہ جانتے ہیں۔ مگر آپ ایک آدمی کو دوست رکھتے تھے۔ لوگوں نے کہا: وہ کون شخص ہے؟ تو انہوں نے کہا: آپ عمار بن یاسر کو دوست رکھتے تھے۔‘ یہ حدیث ابن عون سےصرف ازھر ہی روایت کرتے ہیں، اسے روایت کرنے میں عباد کیلے ہیں۔","",{"k":"مجمع الزوائد (٩٢٩٤)، مستدرك حاكم ٤٤٢٣۔","f":"مذکورہ روایت سے نبی مکرم مام کا اپنے صحابہ کے ساتھ جو تعلق تھا اس کا پتا چلتا ہے۔ ہر صحابی کے ساتھ نبی مکرم نے ام اس انداز میں محبت کرتے اور شفقت فرماتے کہ ہر صحابی سمجھتا کہ مجھ سے بڑھ کر نبی مکرم مالے ایک یتیم کسی کے ساتھ محبت نہیں کرتے۔ (٢) سیدنا عمار بن یاسر یا الیہ کی عظمت کا بھی ثبوت ہے کہ نبی مکرم سے عام ان کے ساتھ بہت زیادہ محبت کرتے تھے"}],[612,"سعيد بن فیروز اپنے باپ سے روایت کرتے ہیں کہ ثقیف کا وفد رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو انہوں نے کہا: ہم نے آپ کو دیکھا ہے کہ آپ دو جوتوں میں نماز پڑھ رہے تھے جو کے آگے سے کھلی ہوئی تھیں۔“ یہ حدیث عبدالملک سے صرف حماد ہی روایت کرتے ہیں اور فیروز الدیلمی سے صرف اسی سند سے ہی یہ روایت مروی ہے۔","",{"k":"صحیح بخاری (٥٨٥)، صحيح مسلم (٥٥٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ پاک صاف ستھری جوتیوں میں نماز پڑھنا بلا شک جائز درست ہے۔ اگر جوتیوں کو نجاست لگی ہو تو نجاست کو دور کرنا ضروری ہے۔ ایک حدیث میں ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”یہود کی مخالفت کرو۔ یہ لوگ اپنے جوتوں یا موزوں میں نماز نہیں پڑھتے۔“ (صحیح سنن ابی داؤد، رقم: ٦٠٧)"}],[613,"سيدنا ابو بکر ضیا اللہ نے بیان کیا، جب رسول اللہ صلی اللہ علیہ وسلم نے خیبر فتح کیا تو لوگ لہسن میں پڑ گئے اور اسے کھانے لگے تو رسول اللہ علیم نے فرمایا: ”جس شخص نے اس سبزی سے کچھ کھایا تو وہ ہماری مسجد کے قریب نہ آئے۔“ یہ حدیث مطرف سے صرف عبثر ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن ابحرا کیلے ہیں اور حضرت ابوبکر سے یہ حدیث صرف اسی سند سے مروی ہے۔ ٦١٤","",{"k":"سنن ابو داؤد، رقم : . ٣٨٢٤ : صحيح مسلم (٥٦٢)۔"}],[614,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، میں نے تحر کے دن نبی نے تم کو اپنی سواری پر دیکھا آپ فرما رہے تھے: ” میری امت اپنے حج کے طریقے مجھ سے سیکھ لے کیونکہ میں نہیں جانتا ہو سکتا ہے کہ میں اس سال کے بعد حج نہ کرسکوں۔“ فائد مذکورہ حدیث سے معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم نے حج کا طریقہ، اپنے صحابہ کو سکھا اور اس کی ترغیب بھی دلائی۔ اسی طرح نبی مکرم ملے ہم نے دیگر احکامات بھی صحابہ ٹی ایم کو سکھائے تھے۔","",{"k":"سنن نسائی (٣٠٦٢)، ارواء الغليل (٤/٢٧١)، قال الشيخ الالباني، صحیح۔"}],[615,"سیدنا جابر ضیا المیہ نے بیان کیا، نبی صلی اللہ علیہ وسلم پہلے دن چاشت کے وقت جمرہ عقبہ کی رمی کرتے تھے اور اس کے بعد زوال کے وقت کرتے۔“","",{"k":"صحیح مسلم (١٢٩٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ قربانی کے روز جمرہ عقبہ کو سورج نکلنے کے بعد اور ایام تشریق میں زوالِ آفتاب کے بعد کنکریاں مارنا ہیں، لیکن اگر کسی شخص کو پہلے دن زوال آفتاب تک تاخیر ہو جائے تو پھر اسے زوال کے بعد ہی کنکریاں مار لینی چاہئیں جیسا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ نبی معظم صلی اللہ علیہ وسلم سے کسی نے دریافت کیا کہ میں نے (١٠ ذو الحجہ کے روز ) شام کے بعد رمی کی ہے؟ آپ ملت عیلم نے فرمایا: ” کوئی حرج نہیں۔“ (صحیح بخاری، کتاب الحج، رقم: - سنن ابن ماجه، رقم: ٣٠٥٠) ١٦"}],[616,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، میں نے نبی لئے علیم کو (جمرہ عقبہ کو اتنی بڑی کنکریاں مارتے ہوئے دیکھا جتنی دو انگلیوں سے ماری جانے والی کنکریاں ہوتی ہیں۔“ یہ تمام احادیث مطعم سے صرف ہیثم بن حمید ہی روایت کرتے ہیں، اسے روایت کرنے میں علی بن حجرا کیلے ہیں۔","",{"k":"صحيح مسلم (١٢٩٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ کنکریاں اتنی چھوٹی ہوں جو کہ انگو ٹھے اور شہادت کی انگلی سے پھینکی جاسکیں۔ لفظ خذف کا معنی انگلیوں ( کے پوروں) سے کنکر پھینکنا ( جو کہ تقریباً لوپیسے کے دانے کے برابر ہو) ہے۔ (جو تقریباًلویسے ایک روایت میں ہے کہ نبی مکرم ملے تعلیم نے لوگوں کو چھوٹی کنکریاں پھینکنے کا حکم دیا۔ (المنجد: ص١٩٧) (صحیح سنن ابی داؤد، رقم: ١٧١٣)"}],[617,"سيدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے، جمعے کے دن جمعے کے لیے آنے والے بالغ شخص کے لیے غسل کرنا واجب ہے۔“ یہ حدیث از محمد بن منکدر از عطاء صرف عبدالرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن جعفر ا کیلے ہیں۔","",{"k":"صحیح بخارى (٨٥٨)۔","f":"نہیں کرنا چاہیے۔:٦١٨ مذکورہ روایت سے معلوم ہوا کہ کسی بالغ مسلمان کو بغیر معقول عذر کے اس میں غفلت"}],[618,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ علیم نے گندگی کھانے والے جانور کا گوشت کھانے، اس کا دودھ پینے اور اس پر سوار ہونے سے منع فرمایا۔ یہ حدیث حضرت عمر سے صرف اسماعیل ہی روایت کرتے ہیں۔ جلالہ کی تعریف: جو جانور نجاست و غلاظت کھاتا ہو جلالہ کہلاتا ہے۔ (لسان العرب: ٢/ ٣٣٦) مذکورہ حدیث سے معلوم ہوا کہ گندگی خور جانور کھانا اور اس کا دودھ پینا حرام ہے کیونکہ اس کا گوشت اور دودھ نجاست سے تیار ہوا ہے۔ البتہ ایسے جانور کی گندگی والی حالت بدل جانے سے حرمت کا حکم بھی حلت میں تبدیل ہو جائے گا۔ جیسا کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما دن گندگی خور مرغی کو قید کر کے رکھتے تھے۔ (اور پھر اس کو کھا لیتے تھے )۔ (ارواء الغلیل: ١٥١/٨ اسنادہ صحیح) معلوم ہوا کہ گندگی خور جانور سے اگر نجاست و بد بوزائل ہو جائے تو وہ حلال ہو جائے گا۔","",{"k":"سنن ابو داؤد (٣٧٨٥)، ♦، سنن ترمذی (١٨٢٤)، سنن ابن ماجة (٣١٨٩)، قال الشيخ الالباني، صحیح۔"}],[619,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے اور آپ صلی اللہ علیہ وسلم کے صحابہ بھی اسلیم میں سے کچھ لوگوں نے سر منڈوایا جبکہ ان میں بعض نے سر کے بال کتروائے۔“ یہ حدیث از عبد الحميد بن جعفر صرف حاتم بن اسماعیل ہی روایت کرتے ہیں اور اسے روایت کرنے میں محمد ا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ارکان حج کی بجا آوری کے بعد حاجی کے لیے سر کے بال منڈانے یا کتروانے کی دونوں صورتیں جائز ہیں مگر منڈانے والے افضل ہیں۔ جیسا کہ سیدنا ابو ہریرہ ولی اللہ فرماتے ہیں کہ نبی مکرم ملے تم نے دعا فرمائی: ”اے اللہ! سرمنڈوانے والوں کی مغفرت فرما! صحابہ کرام مینی سلیم نے عرض کیا: اور کتروانے والوں کے لیے (یہی دعا فرمائیے) لیکن نبی مکرم صل علیم نے اس مرتبہ بھی یہی فرمایا: ”اے اللہ! سر منڈوانے والوں کی مغفرت فرما۔ پھر صحابہ کرام بینی السیم نے عرض کیا: اور کتروانے والوں کی بھی۔ تیسری مرتبہ نبی مکرم نے علیم نے فرمایا: ”اور کتر وانے والوں کی بھی مغفرت فرما۔“ (صحیح بخاری، کتاب الحج، رقم: ١٧٢٨، صحیح مسلم، رقم: ١٣٠١) علامہ عبد الرحمان مبارکپوری ہوالہ اور شیخ ابن باز ہراللہ نے بھی یہی فتویٰ دیا ہے کہ حج وعمرہ میں بال منڈوانا کتروانے سے افضل ہے۔ (تحفۃ الاحوذی:٧٨٤/٣۔ فتاوی اسلامیہ: ٢٦٢/٢)","",{"k":"صحیح مسلم (١٣٠١)۔"}],[620,"سیدنا ابو موسیٰ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”جب قیامت کا دن ہوگا اللہ عز وجل محمد صلی اللہ علیہ وسلم کے ہر امتی کو ایک یہودی اور نصرانی دے گا اور فرمائے گا آگ سے اپنی جان چھڑانے کے لیے اس کے ذریعے فدیہ ادا کر دو۔ یہ حدیث صدیق سے صرف حفص ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مسلمانوں کا فدیہ کافر ہوں گے جن کے بدلے اللہ تعالیٰ","",{"k":"الكبير للطبرانی: ٢٠/ ١٧٣ صحيح مسلم (٧٦٧)، المعجم۔","f":"مسلمانوں کو معاف کر دے گا اور کافروں کو جہنم میں ڈال دے گا جو مسلمانوں کے گناہ ہوں گے وہ بھی ان کے ذمے ہوں گے۔"}],[621,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: بہترین سالن سرکہ ہے۔“ یہ حدیث محارب سے صرف حفص ہی روایت کرتے ہیں۔ مذکورہ حدیث سے سرکے کی اہمیت وافادیت کا علم ہوتا ہے۔ ٦٢٢","",{"k":"داؤد، رقم : ٣٨٢٠. صحیح مسلم (٢٠٥٢)، سنن ابو۔"}],[622,"سيدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں پر ایک ایسا وقت آئے گا کہ ایک طاقت ور اونٹ اور دو مشکیزے آدمی کو اپنی تمام ملکیتی چیزوں سے زیادہ محبوب ہوں گی","",{"k":"مجمع الزوائد (٣٣٢٧)، سنده ضعيف . الله۔"}],[623,"\" نیز آپ صلی اللہ علیہ وسلم نے فرمایا: تم ہر قل کا شہر یا قلعہ فتح کرو گے اور اس کے مالوں کو ترکہ میں تقسیم کرو گے اور کسی چیچنے والے کی آواز انہیں سنائی دے گی کہ ان کے گھروں میں پیچھے دجال آ گیا ہے تو ان کے پاس جو کچھ ہو گا وہ اسے وہیں پھینک دیں گے اور نکل کر جنگ کریں گے۔“ یہ دونوں حدیثیں اسماعیل بن ابی خالد سے صرف اسماعیل بن عیاش ہی روایت کرتے ہیں، ان دونوں کو روایت کرنے میں نصر اکیلا ہے۔ ٦٢٤","",{"k":"الزوائد: ٧/ ٣٤٩ . سنن دارمی، المقدمة (٤٨٦)، مجمع۔"}],[624,"سیدہ عائشہ منی نہا سے روایت ہے کہ انہوں نے فرمایا: جو شخص اللہ تعالیٰ سے ملنا پسند کرتا ہے تو اللہ تعالیٰ بھی اس سے ملنا پسند کرتا ہے اور جو اللہ تعالیٰ سے ملنا پسند نہیں کرتا تو اللہ تعالیٰ بھی اس سے ملنا پسند نہیں کرتا۔ مسروق کہتے ہیں: میں نے راوی سے پوچھا: کیا یہ حدیث تو نے سیدہ عائشہ بنی المحیا سے سنی ہے؟ اس نے کہا: جی ہاں، میں مدینہ گیا اور یہ بات سیدہ عائشہ علی اینجا سے ذکر کی اور یہ کہا کہ ہم تو موت کو نا پسند کرتے ہیں تو انہوں نے فرمایا: یہ بات مراد نہیں بلکہ یہ مرنے کے وقت ہو گا مومن دیکھے گا کہ اس کے لیے اللہ کے ہاں کیا کچھ ہے تو وہ اس کی ملاقات کو پسند کرے گا اور کا فرموت کو نا پسند کرتا ہے تو اللہ تعالیٰ بھی اس کو برا سمجھتا ہے۔“ یہ حدیث بکیر سے صرف عقبہ ہی روایت کرتے ہیں اور عتبہ سے صرف ابو اسماعیل اور سے روایت کرنے میں عباد اکیلے ہیں۔","",{"k":"صحیح بخاری کتاب الرقاق (٦٥٠٧)، صحیح مسلم (٢٦٨٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جو اللہ تعالیٰ کی ملاقات کو پسند کرتا ہے اللہ تعالیٰ بھی اس کی ملاقات کو پسند کرتا ہے اور خوش بختی یہ ہے کہ موت کے وقت اللہ کی ملاقات کا شوق غالب ہو اور ترک دنیا کا غم نہ ہو۔ اللہ ہر مسلمان کو اس کیفیت کے ساتھ موت نصیب فرمائے۔ (امین)"}],[625,"سیدنا بریده وانا الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” تو مسجد سے باہر نہ رضی جان حتی کہ میں تمہیں ایک سورت سے ایک ایسی آیت نہ سکھا دوں جو مجھ سے پہلے سلیمان علینا کے علاوہ کسی بھی پیغمبر پر نازل نہیں ہوئی، پس آپ باہر جانے لگے تو جب دروازے کی دہلیز پر پہنچے تو فرمایا: ”تم اپنی نماز اور قراء ت کس چیز سے شروع کرتے ہو؟ میں نے کہا: \"بِسْمِ اللهِ الرَّحْمنِ الرَّحِیم“ سے آپ نے فرمایا: یہی وہ آیت ہے جو میں کہہ رہا تھا۔ پھر آپ نے اپنا دوسرا پاؤں بھی باہر نکالا۔ یہ حدیث ابن بریدہ سے صرف عبد الکریم روایت کرتے ہیں اور عبد الکریم سے صرف یزید ابو خالد ہی روایت کرتے ہیں، اسے روایت کرنے میں سلمہ بن صالح اکیلے ہیں۔","",{"k":"١١٠١٢ مجمع الزوائد (٢/١٠٩)، عبدالکریم بن ابى المخارق وهو ضعيف۔"}],[626,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر نشہ آور چیز خمر ( شراب ) ہے اور جس چیز کے زیادہ مقدار نشہ چڑھائے تو اس قلیل مقدار بھی حرام ہے۔“ یہ حدیث محمد بن عمرو سے صرف اشجعی روایت کرتے ہیں اور اسے روایت کرنے میں مسروق اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ہر نشہ آور مشروب حرام ہے خواہ وہ کسی بھی چیز سے تیار ہو خواہ وہ قلیل مقدار میں ہو یا کثیر میں۔ جمہور علماء اسی کے قائل ہیں البتہ احناف نے کہا ہے کہ خمر سے مراد صرف انگور سے تیار کردہ شراب ہے دیگر اشیا سے تیار کردہ شراب پینے والے پر حد نہیں لگائی جائے گی۔ جب تک اس کے پینے سے نشہ نہ آئے لیکن مذکورہ حدیث سے واضح طور پر تردید ہوتی ہے کہ جس چیز کی زیادہ مقدار نشہ چڑھاتی ہے اس کی تھوڑی مقدار بھی حرام ہے۔ امام قرطبی جراللہ نے فرمایا: مذکورہ حدیث اہل کوفہ کے اس مذہب کو باطل قرار دیتی ہے کہ خمر (شراب) صرف وہی ہے جو انگور سے تیار ہو اور جو انگور کے علاوہ دیگر اشیا سے تیار ہو وہ خمر نہیں۔ ان کا یہ قول لغت عرب، سنت صحیحہ اور عمل صحابہ کے خلاف ہے۔ (توضیح الکلام: ٣٠٩/٦)","",{"k":"سنن ابی داؤد (٣٦٧٩)، قال الشيخ الالباني صحیح سنن ابن ماجه كتاب الاشربه (٣٣٩٢)۔"}],[627,"سیدنا ابن سعید انصاری نے بیان کیا، میں نے انس بن مالک رضی اللہ عنہ سے پوچھا: تم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عصر کی نماز کس وقت پڑھا کرتے تھے؟ انہوں نے کہا: جب سورج سفید اور صاف یہ حدیث یحیی سے صرف عبد اللہ ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ عصر کی نماز اول وقت میں پڑھنا افضل ہے۔ سنن ابی داؤد میں ہے سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلے: ((كان يصلى العصر والشمس بيضاء مرتفعة حية ويذهب الذاهب الى العوالى والشمس مرتفعة)) عصر کی نماز پڑھا کرتے جبکہ سورج سفید، بلند اور زندہ ہوتا تھا اور جانے والا مدینہ کی بالائی آبادی کی طرف جاتا اور سورج بلند ہوتا تھا۔ (سنن ابی داؤد، رقم:، ”صحیح“. امام زہری رواللہ فرماتے ہیں کہ مدینہ کی بالائی آبادیاں دو یا تین میل تک ہوتی تھیں۔ اور کہا میرا خیال ہے کہ یہ فرمایا یا چار میل تک ہوتی تھیں۔ (سنن ابی داؤد، رقم: ٤٠٥)","",{"k":"صحیح مسلم (٦٢١)، سنن ابو داؤد۔"}],[628,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دن اور راتیں اس وقت تک ختم نہیں ہوں گی (قیامت قائم نہیں ہوگی ) حتی کہ کمینہ بن کمینہ شخص دنیا میں سب سے زیادہ سعادت مند نہ ہو جائے۔“ یہ حدیث بیچی سے صرف حفص ہی روایت کرتے ہیں، اسے روایت کرنے میں مخلدا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قیامت کی نشانیوں میں سے ایک یہ بھی نشانی ہے کہ","",{"k":"سنن ترمذی، رقم : ٠٩ (٢٢٠٩)، مسند احمد (٢/٣٢٦)، قال الشيخ الالبانی، صحیح۔","f":"کمینے اور احمق، کے پاس دنیا کے مال کی فراوانی ہوگی۔ گویا احمق لوگوں کے ہاتھوں میں امارت اور امور دنیا کا آنا قیامت کی علامات میں سے ہے۔"}],[629,"هر ماس بن زیاد نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو اپنی اونٹنی پر خطبہ ارشاد فرماتے ہوئے دیکھا آپ نے فرمایا: ”خیانت سے بچو! یہ بہت بری باطنی خصلت ہے، اور ظلم سے بچو! کیونکہ یہ قیامت کے دن تاریکیوں کا باعث ہوگا۔ بخل سے بھی بچو کیونکہ پہلے جو لوگ تھے انہیں بھی بخل نے ہی ہلاک کر دیا یہاں تک کہ انہوں نے خون ریزی اور قطع رحمی کی۔ حضرت ھر ماس سے یہ حدیث اسی سند سے مروی ہے، اسے روایت کرنے میں احمد بن نصر ا کیلے ہیں۔ ا تاہم صحیح روایات میں ان چیزوں کے متعلق تاکیدی حکم موجود ہے جیسا کہ خیانت کے متعلق نبی معظم طاسے تعلیم نے فرمایا (١) ( اية المنافق ثلاث منافق کی تین نشانیاں ہیں جب بات کرے تو جھوٹ کہے، جب وعدہ کرے تو اس کے خلاف کرے، (( واذا ائتمن خان اور جب اس کو امانت دار سمجھا جائے تو وہ خیانت کرے۔ (صحیح بخاری، رقم: ٣٣) (٢) ظلم اور کنجوسی: سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اتقو الظلم فان الظلم ظلمات يوم القيامة واتقوا الشح فانه اهلك من كان قبلكم)) (صحیح مسلم، كتاب البر والصلة) ظلم سے بچو کیونکہ ظلم قیامت کے دن تاریکیوں کی شکل میں ہوگا اور حرص سے بھری ہوئی کنجوسی سے بچو کیونکہ اس نے تم سے پہلوں کو برباد کر دیا۔“ (٣) ظلم کا معنی ہے \" کسی چیز کو اس کی اصل جگہ کے بجائے کسی اور جگہ رکھنا مثلاً کسی کا حق دوسرے کو دے دینا۔ اسی لیے اللہ تعالیٰ نے مشرک کو بھی ظالم کہا ہے کیوں کہ وہ اللہ تعالیٰ کا حق غیر کو دیتا ہے، ارشادِ باری تعالیٰ ہے: إنَّ الشَّرْكَ لَظُلْمٌ عَظِيمٌ﴾ (لقمان: ١٣) ”بے شک شرک بہت بڑا ظلم ہے۔“ اسی طرح نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” جس شخص نے اپنے بھائی پر کوئی ظلم کیا ہو وہ اس سے معاف کر والے کیونکہ وہاں درہم و دینار نہیں اس سے پہلے پہلے کہ اس کے بھائی کے لیے اس کی نیکیاں لی جائیں اگر نیکیاں نہ ہوئیں تو اس کے بھائی کی برائیاں لے کر اس پر ڈال دی جائیں۔ اب ظاہر ہے جب نیکیاں چھن جائیں گی تو نور کہاں سے آئے گا پھر تو اندھیرے ہی اندھیرے رہ جائیں گے۔ (٤) الشح شدید حرص جس کے ساتھ کنجوسی بھی ہو اور وہ آدمی کی عادت بن چکی ہو۔ اللہ تعالیٰ نے بخل اور حرص کی بڑی مذمت فرمائی ہے۔ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأَوْلَئِكَ هُمُ الْمُفْلِحُونَ) (الحشر: ٩) \"جو شخص اپنے نفس کی شدید حرص سے بچالیا گیا تو یہی لوگ کامیاب ہیں۔“ نبی معظم ما م نے فرمایا: ”آدمی میں بدترین خصلت سخت گھبراہٹ میں ڈال دینے والی حد سے بڑھی ہوئی کنجوسی ہے اور دل نکال دینے والی بزدلی ہے۔“ (صحیح سنن ابی داؤد، رقم: ٢١٩٢)","",{"k":"ضعيف الترغيب والترهيب (٢/٤٢، ١٣٤٧)، مجمع الزوائد (٥/٢٣٥)۔"}],[630,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے خطبہ دیا تو فرمایا ” اما بعد!“ یہ حدیث ثابت سے صرف حماد ہی روایت کرتے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ نبی معظم ماے علی تم اپنے خطبہ مبارکہ میں اما بعد کہتے، جس کا مطلب یہ ہے کہ اس (حمدہ وصلاۃ) کے بعد۔ نبی معظم صلی اللہ علیہ وسلم کے خطبہ مبارک کے یہ الفاظ احادیث کی کتابوں میں موجود ہیں: ان الحمد لله نحمده ونستعينه ونستغفره ونعوذ بالله من شرور انفسنا وسيات اعمالنا من يهده الله فلا مضل له ومن يضلل فلا هادى له واشهد ان لا اله الا الله وحده لا شريك له واشهد ان محمداً عبده ورسوله . )) يَأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ حَقَّ تُقَتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُّسْلِمُونَ (آل عمران: ١٠٢) يَأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَّفْسٍ وَاحِدَةٍ وَ خَلَقَ مِنْهَا زَوْجَهَا وَبَكَ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبا (النساء: ١) يَأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَقُولُوا قَوْلًا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا (الاحزاب: ٧٠ تا ٧١) اما بعد! ((فان خير الحديث كتاب الله وخير الهدى هدى محمد ( صلی اللہ علیہ وسلم) وشر الأمور محدثاتها وكل محدثة بدعة وكل بدعة ضلالة وكل ضلالة في النار)) تمام المنة: ص - - ارواء الغليل: ص ٢٠٨)","",{"k":"السنن الكبرى (٣/٣٣٩)۔"}],[631,"سیدنا عبد اللہ ابن عباس ریلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”امن اور عافیت اللہ کی دو ایسی نعمتیں ہیں جن میں بہت سے لوگ خسارے میں ہیں۔“ یہ حدیث خصیف سے صرف ہارون ہی روایت کرتے ہیں۔","",{"k":"ضعف الجامع الصغير (٢٢٩٨)، مجمع الزوائد (١٠/٢٩٢)۔"}],[632,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم ایک جنازے میں چل کر گئے اور جس وقت واپس آئے تو نگی پیٹھ والے گھوڑے پر سوار تھے جس پر صرف اس کی لگام تھی۔ یہ حدیث نصیر سے صرف مخلد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جنازہ کے ساتھ پیدل چلنا اور سواری پر جانا دونوں طرح جائز ہے البتہ سوار سے متعلق نبی معظم صلی اللہ علیہ وسلم نے فرمایا::٦٣٣ ((الراكب يسير خلف الجنازة)) (صحيح سنن ابی داؤد، رقم: ٢٧٢٣) سوار جنازے کے پیچھے چلے۔“ شیخ البانی اللہ فرماتے ہیں کہ سوار ہونا جائز ہے بشرطیکہ جنازے کے پیچھے چلا جائے۔ (احکام الجنائز: ص ٩٦)","",{"k":"صحیح مسلم (٩٦٥)، سنن ابو داؤد (٣١٧٨)، المعجم الكبير للطبراني (٢/٣٤١)۔"}],[633,"سیدنا عبداللہ ابن عباس زنی اشیا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے لیے اللہ تعالیٰ سے وسیلہ مانگو کیونکہ جس آدمی نے بھی دنیا میں میرے لیے اللہ تعالیٰ سے وسیلہ مانگا میں قیامت کے دن اس کے لیے گواہ یا سفارشی بنوں گا۔ یہ حدیث ابن ابی ذئب سے صرف موسیٰ ہی روایت کرتے ہیں۔","",{"k":"سنن نسائی (٦٧٨)، قال الشيخ الالباني صحیح۔","f":"الوسيلة کی جمع وسائل آتی ہے اس کا معنی ہے ایسی چیز جس کے ذریعے کسی دوسری چیز تک پہنچا جائے، اس سے مراد جنت میں ایک مقام ہے جس کے متعلق رسول اللہ نعیم نے فرمایا ” وہ اللہ کے بندوں میں سے صرف ایک کو نصیب ہوگا اور مجھے امید ہے کہ وہ میں ہوں گا۔“ (صحیح مسلم، رقم: ٣٨٤) نبی معظم علت علم کے لیے وسیلہ کس طرح مانگنا ہے اس کی وضاحت نبی معظم صلی اللہ علیہ وسلم نے خود ہی کر دی ہے فرمایا: اذان کے بعد یہ دعا پڑھو: ((اللهم رب هذه الدعوة التامة والصلاة القائمة الخ))) (صحیح بخاری، رقم: ٦١٤، سنن ابی داؤد، رقم: ٥٢٩) تفصیل کے لیے دیکھئے: فوائد حدیث نمبر ١٤٦٦۔ ٦٣٤"}],[634,"سیدنا انس رضی اللہ عنہ نے بیان کیا، میں سیدنا ابو الدرداء رضی اللہ عنہ کی عیادت کرنے ان کے ہاں گیا، تو میں نے کہا: ابو الداداء! کیا آپ چاہتے ہیں کہ آپ صحت مند ہو جائیں اور پھر کبھی بیمار نہ ہوں، تو انہوں نے کہا: میں نے رسول اللہ طل علم کو فرماتے ہوئے سنا: سر درد اور بخار آدمی کو تکلیف پہنچاتے رہتے ہیں یہاں تک کہ اس پر اس کا گناہ رائی کے دانے کے برابر بھی نہیں چھوڑتے۔“","",{"k":"مسند احمد (٥/١٩٩)، ضعيف الجامع الصغير (١٧٩٢)۔","f":"مذکورہ روایت ضعیف ہے تاہم یہ حقیقت ہے کہ بیماری کی وجہ سے اللہ تعالیٰ مومن کے گناہوں کو معاف کر دیتے ہیں۔ جیسا کہ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ نبی معظم تعلیم نے فرمایا: ”جب کوئی مومن بیمار ہوتا ہے تو اللہ تعالیٰ اسے گناہوں سے اس طرح صاف کر دیتے ہیں جیسے بھٹی لوہے کے میل کو صاف کر دیتی ہے۔ (بخاری، ادب المفرد: ٤٩٧ اسنادہ صحیح)"}],[635,"سيدنا بلال رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم بیت اللہ میں داخل ہوئے تو آپ نے وہاں دوسرے ستون کی بائیں جانب دو رکعت نماز ادا کی۔ یہ حدیث ابن ابی لیلی سے صرف عمر و روایت کرتے ہیں۔ منجم اوسط طبرانی ١ مذکورہ حدیث سے معلوم ہوا کہ بیت اللہ شریف میں نماز پڑھنا جائز ہے۔ (٢) یہ بھی معلوم ہوا کہ جسے کعبہ کے اندر جانے کا موقع میسر آ جائے اس کے لیے وہاں دو رکعت پڑھنا مستحب ہے۔ اور جسے موقع نہ ملے تو وہ حطیم کے اندر پڑھ لے وہ بھی کعبہ ہی کا حصہ ہے اور شائد اللہ عز وجل کی یہی حکمت تھی کہ ابتدا سے یہ حصہ کھلا رہ گیا اور تعمیر نہ ہو سکا اس طرح ہر مسلمان کو کعبہ کے اندر نماز پڑھنے کی سہولت ہر وقت میسر رہتی ہے۔","",{"k":"عمرو . مسند احمد (٤١٠/٣)، مجمع الزوائد (٣/٢٩٥)، قال الشيخ شعيب الارناؤط هذا حديث صحيح لغيره۔"}],[636,"سیدنا ابن عمر رضی اللہ عنہما نے بیان کیا، نبی صلی اللہ علیہ وسلم نے فرمایا: ”جب تم سجدہ کرو تو اپنی ہتھیلیاں زمین پر رکھو کیونکہ ہتھیلیاں بھی سجدہ کرتی ہیں جس کا چہرہ سجدہ کرتا ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ دونوں ہتھیلیاں زمین پر لگانی چاہئیں جیسا کہ سیدنا براء ل اللہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تو سجدہ کرے تو اپنی ہتھیلیاں زمین پر رکھ اور کہنیاں زمین سے اٹھا لے۔ (صحیح مسلم كتاب الصلاة، رقم: ٤٩٤) ٦٣٧","",{"k":"٤٩٤ : صحیح مسلم، رقم۔"}],[637,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”زمانے کو گالی نہ دو کیونکہ اللہ تعالیٰ ہی زمانہ ہے۔“ یہ حدیث سعید سے صرف ابراہیم ہی روایت کرتے ہیں، اور ابو زبیر سے صرف سعید روایت کرتے ہیں۔","",{"k":"صحیح بخاری (١٦٨٢)، صحیح مسلم (٢٢٤٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ زمانے کو برا نہیں کہنا چاہیے کیونکہ۔ جو کچھ کرتا ہے وہ اللہ پاک ہی کرتا ہے زمانے کو برا کہنا گویا اللہ پاک ہی کو برا کہنا ہے۔"}],[638,"سیدنا ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم سفید کپڑے اپنے اوپر لازم کر لو۔ انہیں خود بھی پہنا کرو اور اپنے فوت شدگان کو ان میں کفن دیا کرو۔“ یہ حدیث زہری سے صرف موقری ہی روایت کرتے ہیں، اسے روایت کرنے میں علی بن حجرا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ سفید لباس پہنا مستحسن ہے لیکن دوسرے رنگوں کا لباس بھی جائز ہے۔ کیونکہ سفید لباس میں جو وقار اور حسن و رعنائی ہے وہ مردانہ جلال وعظمت کے مطابق ہے جبکہ دوسرے رنگوں میں عورتوں سے مشابہت کا امکان ہے۔","",{"k":"سنن ابن ماجه (٣٥٦٦)، سنن ابو داؤد (٣٨٧٨)، قال الالبانی، صحیح۔"}],[639,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، نبی ملنے یا ہم نے نحر کے دن جمرہ عقبہ کی چاشت کے وقت رمی کی اور باقی تمام جمروں کی زوال کے بعد رمی کی۔“ یہ حدیث ابن جریج سے صرف ابن ادریس ہی روایت کرتے ہیں۔ ि ٦٤٠","",{"k":"سنن ترمذی، قال الشيخ الالبانی صحیح۔"}],[640,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے دو قسم کے لوگوں کو میری شفاعت نصیب نہیں ہوگی (١) ظالم و غاصب حکمران (٢) دین میں غلو کرنے والا۔“ یہ حدیث خلیل سے علاء ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ظالم بادشاہ اور دین میں غلو کرنے والا نبی معظم ملئے علیم کی شفاعت سے محروم ہو جائے گا۔ کیونکہ بادشاہ کا کام ہے کہ وہ اپنی رعایا کے ساتھ حسن سلوک کرے اور ان کے حقوق کا خیال رکھے۔ لیکن جو بادشاہ اپنی رعایا سے ظلم و زیادتی اور دھوکہ وفریب کرتا ہے اس کے لیے حدیث میں بڑی سخت وعید ہے۔ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ کسی بندے کو رعیت کا حاکم بناتا ہے اور وہ خیر خواہی کے ساتھ ان کی نگہداشت نہیں کرتا تو وہ جنت کی خوشبو تک نہیں پائے گا۔“ (صحیح بخاری، کتاب الاحکام، رقم: ٧١٥٠) غلو: کسی کو حد سے زیادہ بڑھا دینا جیسا کہ عیسائیوں نے سیدنا عیسی علینا کو اللہ کا بیٹا بنا دیا تھا، افسوس آج کے مسلمانوں نے رسول اللہ صلی اللہ علیہ وسلم سے متعلق عقیدہ ”نور من نور اللہ گھڑ رکھا ہے اللہ ہمیں باطل عقائد ونظریات اور دین میں افراط و تفریط سے محفوظ فرمائے۔ آمین۔ ·:٦٤١","",{"k":"السلسلة الصحيحة (١/٤٦٩، ٤٧٩)، صحيح الجامع الصغير، رقم : الزوائد (٥/٢٣٥)، ٣٧٩٨ مجمع۔"}],[641,"سيدنا جعفر بن سلیمان مبلی نے بیان کیا، میں نے مالک بن دینار (عابد زاہد سچے بزرگ) کو دیکھا کہ ان کے پیچھے ایک کتا جا رہا ہے تو میں نے کہا ابو یحی! یہ کیا ہے؟ انہوں نے کہا: برے ہم نشین سے یہ بہتر ہے۔\"","",{"k":"حلية الأولياء (٢/٣٨٤)۔","f":"سیدنا مالک بن دینارحمہ اللہ کے قول سے پتا چلتا ہے کہ برے ہم نشین سے کتنا بہتر ہے کیونکہ برے ہم نشین سے ایمان کے ضائع ہونے کا خطرہ ہے۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ” نیک ساتھی کی اور برے ساتھی کی مثال ایسی ہے جیسے کستوری اٹھانے والا اور آگ کی بھٹی دھونکنے والا۔ پس کستوری اٹھانے والا یا تو تجھے (کستوری) عطیہ دے دے گا یا تو خود اس سے خرید لے گا ( یہ دونوں صورتیں نہ ہوں تب بھی ) یا یہ کہ تو اس سے پاکیزہ خوشبو پالے گا اور بھٹی دھونکنے والا یا تو تیرے کپڑے جلا دے گا یا پھر تو اس سے بد بو پائے گا۔“ (صحیح بخاری، کتاب الذبائح، رقم: ٥٥٣٤، صحيح مسلم، رقم: ٢٦٢٨) ٦٤٢"}],[642,"سیدنا سعید بن جبیر نے بیان کیا، ” بنو اسرائیل نے کہا: اے موسیٰ علیام! تیرا پروردگار مخلوق کو پیدا کر کے پھر انہیں عذاب کرے گا؟ تو اللہ تعالیٰ نے وحی نازل فرمائی کہ تم اپنے کھیت میں بیج بود تو اس نے بیج بویا، پھر فرمایا: اسے کاٹو تو انہوں نے کاٹا، پھر فرمایا: اسے اڑاؤ تو انہوں نے اسے اڑایا تو وہ اکٹھا ہو گیا پھر ان سے اللہ نے پوچھا: اب یہ کس کام کا ہے؟ موسیٰ علینا نے کہا: آگ کے لیے ہی مناسب ہے۔ فرمایا: اسی طرح میں اپنی مخلوق میں سے صرف انہی لوگوں کو عذاب دوں گا جو اس کے لائق ہوں گے۔“","",{"k":"مجمع الزوائد (٢٠١٧)۔","f":"مذکورہ روایت سے معلوم ہوا کہ اللہ تعالیٰ اپنے پسندیدہ بندوں کو عذاب نہیں دے گا، بلکہ عذاب ان کو ملے گا جو اللہ تعالیٰ کے نافرمان ہیں جو عذاب کے مستحق ہوں گے، جنہوں نے برے کام کیے ہوں گے۔ کیونکہ اللہ ذوالجلال کسی پر ظلم و زیادتی نہیں کرے گا۔ ٦٤٣"}],[643,"سیدنا ابو ہریرہ ضل اللہ نے بیان کیا، مردوں اور عورتوں نے ایک دوسرے پر فخر کیا تو سیدنا ابو ہریرہ ضیا الہ نے فرمایا: جنت میں مردوں سے زیادہ عورتیں ہوں گی؟ سیدنا عمر بنی اللہ نے لوگوں کی طرف دیکھا اور فرمایا: سیدنا ابو ہریرہ فی اہلیہ نے جو کہا وہ تم سنتے ہو؟ تو سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ مل علم سے سنا آپ فرما رہے تھے: ” پہلی جماعت جو جنت میں جائے گی ان کے چہرے چودہویں رات کے چاند کی طرح ہوں گے، اور دوسری جماعت کے چہرے آسمان میں روشن ترین ستارے کی طرح ہوں گے، اور ہر آدمی کی ان میں سے دو بیویاں ہوں گی۔ ان کی پنڈلی کا گودا چمڑے کے اندر سے دیکھا جا سکتا ہو گا۔ اور جنت میں کوئی مجرد آدمی (جس کی بیوی نہ ہو ) داخل نہیں ہو گا۔“ یہ حدیث از یونس اور حبیب اور حمید صرف حماد سے روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جنت میں زیادہ تعداد عورتوں کی ہوگی اور اسی طرح جہنم میں بھی زیادہ محبت عورتیں ہوں گی معلوم ہوا کہ ہر جنتی کو خواتین میں سے دو بیویاں ملیں گی اور یہ ہم عمر ہوگی، اپنے خاوند سے بہت زیادہ کریں گی جیسا کہ ارشاد باری تعالی ہے: إِنَّا أَنشَأْنَاهُنَّ إِنشَاء فَجَعَلْنَاهُنَّ اَبْكَارًاه عُرُبًا أَتْرَابًاهِ لِاصْحُبِ الْيَمِينِ﴾ (الواقعه: ٣٥ تا ٣٨) ”اہل جنت کی بیویوں کو ہم نئے سرے سے پیدا کریں گے اور انہیں باکرہ بنا دیں گے اپنے شوہروں سے محبت کرنے والیاں اور (ان کی ) ہم عمر یہ سب کچھ داہنے ہاتھ والوں کے لیے ہو گا۔“ (٢) یہ بھی معلوم ہوا کہ جنت میں بغیر بیوی کے کوئی بھی نہیں ہوگا۔ (٣) یہ بھی معلوم ہوا کہ جنت میں جانے والی پہلی جماعت کے چہرے چودہویں کے چاند کی طرح ہوں گے۔","",{"k":"صحیح بخاری (٣٢٤٦)، صحیح مسلم (٨٣٤)۔"}],[644,"زہرم جرمی نے بیان کیا میں ابو موسی اشعری نیا الہیہ کے پاس گیا وہ مرغ کا گوشت کھا رہے تھے تو کہنے لگے: آؤ! کھالو۔ میں نے کہا: میں نے اس کو گندگی کھاتے ہوئے دیکھا ہے اس لیے میں چاہتا ہوں کہ اسے نہ کھاؤں۔ تو وہ کہنے لگے: بیٹھو! میں نے رسول اللہ ملنے ان کو اس کا گوشت کھاتے ہوئے دیکھا ہے۔“ یہ حدیث سوار سے صرف ابو ہلال ہی روایت کرتے ہیں، اسے روایت کرنے میں ابن عائشہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مرغی حلال ہے مرغی ایسا جانور نہیں ہے جس کی مطلق غذا گندگی ہو وہ اگر گندگی کھاتی ہے تو پاکیزہ اشیاء بھی بکثرت کھاتی ہے۔ تاہم اگر مرغی صرف گندگی کھاتی ہو اور اس سے بد بو آئے تو تب اس کا گوشت کھانا جائز نہیں جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے نجاست خور جانور کھانے اور اس کا دودھ پینے سے منع فرمایا ہے۔ (سنن ابی داؤد، كتاب الاطعمة، رقم: ٣٧٨٥)","",{"k":"المعجم الكبير للطبرانی (٢٠/١٧٣)۔"}],[645,"سیدہ عائشہ بنی النیہا نے بیان کیا، جب نبی صلی اللہ علیہ وسلم اپنی کسی زوجہ محترمہ سے خلوت کرتے اور پھر سستی سے اٹھ نہ سکتے تو دیوار پر ہاتھ مار کر تیم کر لیتے۔“ یہ حدیث ہشام سے صرف اسماعیل ہی روایت کرتے ہیں۔ جاتی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ ہم بستری کرنے کی وجہ سے جسم میں سستی و کاہلی پیدا ہو (٢) یہ بھی معلوم ہوا کہ اگر انسان نہ اُٹھ سکے تو تیم کر لے تو اس کے لیے یہی کافی ہے کیونکہ یہ وضو کے قائم مقام ہے جب پانی میسر نہ ہو یا پھر پانی استعمال کرنے کا خدشہ ہو۔ ہم بستری کے بعد غسل جنابت کیے بغیر آدمی سوسکتا ہے تا ہم بہتر یہ ہے کہ کم از کم سونے سے قبل وضو کر لے۔ ( صحیح مسلم، رقم: ٦ ٣٠) ٦٤٦","",{"k":"صحيح الجامع، رقم : : (٤٧٩٤)، مجمع الزوائد (١/٢٧٤)۔"}],[646,"سیدہ عائشہ منی اشیا نے بیان کیا، نبی صلی اللہ علیہ وسلم نے سیدہ خدیجہ رضی اللہ عنہا کی وفات سے تین سال بعد مجھ سے شادی کی۔ یہ حدیث ہشام سے صرف اسماعیل ہی روایت کرتے ہیں۔","",{"k":"♦، صحیح بخاری کتاب المناقب (٣٨١٧)۔","f":"مذکورہ روایت سے معلوم ہوا کہ سیدہ خدیجہ میلی لی جو ان کی وفات سے تین سال بعد، بخاری کی دوسری روایت میں ہے وفات کے تقریباً دو سال بعد نکاح کیا۔ (صحیح بخاری، رقم: ٣٨٩٦) ٦٤٧"}],[647,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جبریل علی سلام مجھے ि ہمیشہ ہم سائے کے متعلق وصیت کرتے رہے یہاں تک کہ مجھے خیال ہونے لگا کہ عنقریب وہ اس کو وارث بنا دیں گے۔ یہ حدیث ہشام سے ابن ابی حازم روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٦٠١٥)، صحيح مسلم (٦٦٨)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ پڑوسی کے ساتھ حسن سلوک کی بہت زیادہ اہمیت ہے۔ جیسا کہ جبریل علینا مسلسل تاکیدی احکام لاتے رہے تو نبی ملنے سی این فرماتے ہیں کہ مجھے خیال ہوا کہ شاید اس کو وارث بھی بنا دیا جائے گا یعنی حکم آجائے گا کہ کسی کے مرجانے کے بعد جس طرح والدین اپنی اولاد اور دوسرے اقارب اس کے ترکہ کے وارث ہوتے ہیں اسی طرح پڑوسی کا بھی اس میں حصہ ہو گا۔ اور اسی طرح نبی ل علم نے فرمایا: اللہ کی قسم وہ مومن نہیں، اللہ کی قسم، وہ مومن نہیں، اللہ کی قسم! وہ مومن نہیں!‘ عرض کیا گیا اللہ کے رسول کون؟ آپ ملے عوام نے ارشاد فرمایا: ”وہ شخص جس کی شرارتوں سے اس کا پڑوسی محفوظ نہ ہو۔“ (صحیح بخاری، کتاب الادب، رقم: ٦٠١٦)"}],[648,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، نبی صلی اللہ علیہ وسلم ایک زمین سے گزرے جسے عذرہ کہا جاتا تھا، تو آپ نے اس کا نام خضرہ رکھ دیا۔ یہ حدیث ہشام سے صرف عبدہ ہی روایت کرتے ہیں۔","",{"k":"السلسة الصحيحة (١/٢٠٧)، رقم : ٢٠٨ شعب الایمان (٥٢٢٨)، مجمع الزوائد (٥١/٨)۔","f":"بعض روایات میں ”عذرة“ کی جگہ ”عَقِرَة “اور ”غذرۃ“ کے الفاظ ہیں۔ جس کا مطلب، بنجر اور بانجھ زمین ہے۔ نبی صلی اللہ علیہ وسلم نے اس زمین کا یہ نام مکروہ سمجھتے ہوئے اس کا نام ”خضرة سرسبز و شاداب رکھ دیا۔"}],[649,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے بھائی کی مدد کر خواہ وہ ظالم ہو یا مظلوم اگر ظالم ہو تو اس کو ظلم سے ہٹاؤ اگر مظلوم ہو تو اس کا حق اسے دلاؤ۔“ یہ حدیث ہشام سے صرف اسماعیل اور عکرمہ بن ابراہیم الازدی ہی روایت کرتے ہیں۔","",{"k":"ভ ٢٤٤٣ صحیح بخاری، والغصب، رقم۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسلمان بھائی کی مدد کرنا ہر حال میں ضروری ہے خواہ وہ ظالم ہے یا مظلوم! ( تفصیل کے لیے دیکھئے: فوائد حدیث نمبر ٦٢٩) ٦٥٠"}],[650,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، میں اپنی خالہ میمونہ بنی الجھا کے ہاں مہمان بنا اور وہ اس رات حیض والی تھیں نماز نہیں پڑھتی تھیں اُنھوں نے مجھ پر ایک کمبل ڈال دیا اس کے کنارے پر میرے لیے ایک سرہانہ رکھ دیا اور رسول اللہ صلی اللہ علیہ وسلم کے لیے ایک بچھونا بچھا دیا جب رسول اللہ صلے عدیم مسجد سے تشریف لائے تو اپنے کپڑے ڈال دیے۔ اور ایک اور کپڑا پہن لیا پھر اس کے کنارے پر لیٹ گئے۔“ یہ حدیث عبداللہ بن حارث سے صرف جبلہ بن عطیہ ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن ثابت اکیلے ہیں۔ ٦٥١","",{"k":"ضعيف . مسند احمد (١/٢٨٤، ٢٥٧٢)، قال الشيخ شعيب الارناؤط اسناده۔"}],[651,"عمرو بن الحمق بنا الیہ نے بیان کیا، رسول اللہ تم نے فرمایا: ” کوئی آدمی ایمان کی حقیقت کو اُس وقت تک نہیں پاسکتا یہاں تک کہ وہ اللہ کے لیے ہی ناراض ہو اور اسی کے لیے راضی ہو جب اس نے اس طرح کر لیا تو اس نے ایمان کی حقیقت پالی۔ اور میرے دوست اور محبوب وہ لوگ ہیں جو مجھے یاد کرنے سے وہ یاد کیے جائیں اور ان کے یاد کرنے سے میں یاد کیا جاؤں۔ یہ حدیث عمرو بن حمق سے صرف اسی سند سے ہی مروی ہے، ان سے روایت کرنے میں رشدین اکیلے ہیں۔","",{"k":"کر مجمع الزوائد (١/٥٨)، مسند احمد (٤٣٠/٣)، قال الشيخ شعيب الارناؤط اسناده ضعيفٌ۔","f":". تاہم صحیح روایات میں الحب في الله والبغض فی اللہ کی بہت زیادہ اہمیت بیان کی گئی ہے۔ جیسا کہ نبی معظم نے یم نے فرمایا: دو تین خصلتیں ایسی ہیں جس میں وہ ہوں گی وہ ان کی بدولت ایمان کی لذت اور مٹھاس محسوس کرے گا۔\n(١) یہ کہ اللہ اور اس کا رسول اسے ان کے ماسوا ہر چیز (پوری کائنات ) سے زیادہ محبوب ہو۔\n(٢) اور یہ کہ وہ کسی آدمی سے صرف اللہ کے لیے محبت رکھے۔\n(٣) اور وہ کفر میں پلٹنا ایسے ہی نا پسند کرے جیسے وہ آگ میں ڈالا جانا نا پسند کرتا ہے۔ (صحیح بخاری، کتاب الایمان"}],[652,"سیدہ خولہ بنت حکیم بنی النہا سے روایت ہے اور آپ نے ان سے شادی کی تھی، پس آپ نے جس جس کو مؤخر کیا ان میں یہ بھی تھیں۔ انہوں نے کہا: رسول اللہ ملنے نام سے اس عورت کے متعلق پوچھا گیا جو خواب میں وہ کچھ دیکھے جو مرد دیکھتا ہے تو آپ نے فرمایا: ” وہ مرد کی طرح ہی ہے جب اس کا انزال ہو جائے تو غسل کرے اگر انزال نہ ہو تو وہ غسل نہ کرے۔“ یہ حدیث عمارہ سے صرف علی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مردوں کی طرح عورتوں کو بھی احتلام ہوتا ہے اور اس","",{"k":"صحیح بخاری (١٣٠)، سنن نسائی (١٩٨)، سنن ابو داؤد (٢٣٧)۔","f":"کے باعث ان پر بھی غسل فرض ہے۔ لیکن وجوب غسل کے لیے یہ شرط ہے کہ مرد یا عورت تری محسوس کریں۔ مزید وضاحت اس مسئلے کی سیدہ عائشہ بنایا تھا کہ اس حدیث سے ہوتی ہے جس میں ہے کہ رسول اللہ صلے می کنم سے ایسے شخص کے متعلق دریافت کیا گیا جو تری تو دیکھتا ہے لیکن اسے احتلام یاد نہیں تو آپ ٹیم نے فرمایا وہ غسل کرے گا۔ پھر ایسے شخص کے متعلق دریافت کیا گیا جسے اتنا تو معلوم ہے کہ اسے احتلام ہوا ہے لیکن وہ تری نہیں پاتا؟ تو نبی معظم صلی اللہ علیہ وسلم نے فرمایا: اس پر کوئی غسل نہیں۔“ (صحیح سنن ابی داؤد، رقم: ٢١٦، سنن ترمذی، رقم: ١١٣) امام ابن منذر جماللہ، شیخ ابن جبرین، اور شیخ ابن باز اللہ نے یہ فتویٰ دیا ہے کہ محتلم جب تری دیکھے تب اس پر غسل واجب ہوتا ہے۔ (الاجماع ابن منذرص ٣٦ فتاوی اسلامیدا ( ابن باز مترجم: ٥١/١)"}],[653,"سیدنا انس رضی اللہ عنہ نے بیان کیا، میں نے نبی صلی اللہ علیہ وسلم کو دیکھا کہ آپ دوران نماز کپڑے میں تھوک کر اپنی دو انگلیوں سے اس کو مسل دیتے۔“ مذکورہ حدیث سے معلوم ہوا کہ انسان کا تھوک پاک ہے اسی طرح بلغمی مادہ اور ناک کی آلائش بھی پاک ہے۔ لیکن کپڑے پر تھوک یا بلغم لگی نظر آتی ہو تو بری لگتی ہے۔ اس لیے نظافت کے طور پر صاف کر لینا چاہیے حالت نماز میں تھوکنے کی ضرورت محسوس ہو یا ناک صاف کرنے کی ضرورت ہو تو اس کا مسنون طریقہ یہ ہے کہ انسان اپنے کپڑے (رومال وغیرہ) میں تھوک کر اس کپڑے کو مسل دے۔ تھوک اور بلغم وغیرہ کو منہ کے اندر ہی اندر رکھ کر نماز ختم ہونے کا انتظار نہ کرتا رہے کیوں کہ اس طرح نماز کے خشوع وخضوع میں خلل واقع ہوتا ہے۔","",{"k":"سنن ابو داؤد (٣٨٩)، مجمع الزوائد (٢/١٩)۔"}],[654,"سیدنا انس رضی اللہ عنہ نے بیان کیا، \"رسول اللہ صلے عام ہمارے گھر تشریف لائے تو ایک مشک لٹکی ہوئی تھی تو آپ نے اس سے کھڑے ہو کر پانی پی لیا، میری ماں اٹھیں اور مشک کا منہ کاٹ دیا اور کہا: آپ صلی اللہ علیہ وسلم کے بعد کوئی بھی اس میں سے پانی نہ پئے۔ یہ دونوں حدیثیں شریک سے صرف علی بن حکیم اور منجاب سے روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کھڑے ہو کر پانی پینا جائز ہے۔","",{"k":"سنن ابن ماجه (٣٤٢٣)، مسند طیالسی (١٦٥)، قال الالبانى، صحيح۔"}],[655,"سیدنا عقبہ بن عامر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ''جس نے برے کام پر پردہ ڈالا تو گویا کہ اس نے زندہ درگور کی ہوئی لڑکی کو زندگی عطا کی۔“ یہ حدیث سعید سے صرف عمرو ہی روایت کرتے ہیں۔ فائد مذکورہ روایت شواہد کی بنا پر حسن درجے کی ہے۔ تاہم مذکورہ حدیث سے معلوم ہوا کہ مسلمانوں کے گناہوں پر پردہ ڈالنا چاہیے جب کوئی مسلمان کسی مسلمان کی لغزش یا غلطی پر مطلع ہو پھر اس پر پردہ ڈال دے تو اسے بہت زیادہ اجر ملے گا۔ لیکن جو شخص کھلم کھلا اعلانیہ اللہ کی نافرمانی کرتا ہے اور روکنے سے نہیں رکتا اس کا معاملہ ان لوگوں کے پاس پہنچایا جائے گا جو اسے روک سکیں","",{"k":"ضعيف الجامع الصغير (٥٥٩٠)، سنن ابو داؤد۔"}],[656,"سیدنا عبد الرحمن بن ابی عمیرہ بیانیہ سے روایت ہے، انہوں نے رسول اللہ صطلح علیم سے سنا۔ آپ نے سیدنا معاویہ رضی للہ علیہ کا ذکر کیا، تو فرمایا: ”اے اللہ! اس کو ہدایت دینے والا ہدایت یافتہ بنا اور اس کے ساتھ لوگوں کو ہدایت عطا فرما۔ یہ حدیث بشر سے صرف نصر ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی (٣٨٤٢)، قال الشيخ الالبانى، صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سیدنا معاویہ رضی اللہ عنہ کے لیے نبی مکرم ملنے ندیم نے ہدایت کی دعا فرمائی۔ سیدنا معاویہ رضی اللہ عنہ یہ وہ خوش نصیب صحابی رسول ہیں جنہیں کاتب وحی ہونے کا شرف حاصل تھا، علمی اعتبار سے سیدنا امیر معاویہ نبی الیہ کا مقام و مرتبہ بہت زیادہ تھا، ابتدا ہی سے لکھنے پڑھنے میں مہارت رکھتے تھے اس بنا پر ان کا صاحب علم و افتاء صحابہ نئی ایم میں شمار ہوتا تھا۔ (اعلام الموقعین: ١٣/١)"}],[657,"سیدنا سلمہ بن الاکوع رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ علیم کی اپنے اس ہاتھ سے بیعت کی، پس ہم نے اس ہاتھ کو چوما تو آپ نے اس پر کوئی اعتراض نہیں فرمایا۔ یہ حدیث سلمہ سے اسی سند سے روایت ہے، اسے روایت کرنے میں عطاف اکیلے ہیں۔","",{"k":"بخاری ادب المفرد (٩٧٣)، م الزوائد (٤٢/٨)، مجمع۔","f":"مذکورہ حدیث سے معلوم ہوا کسی عالم زاہد، بزرگ کا ہاتھ چومنا جائز ہے بشرطیکہ جس کا ہاتھ چوما جائے اس کے نفس میں یہ جذبہ نہ ہو کہ میرے ہاتھ چومے جائیں۔ جو اپنے ہاتھوں کو بوسہ دیا جانا پسند کرتے ہیں اور اس انتظار میں رہتے ہیں کہ کوئی آئے اور میرا پاؤں چومے (جب کہ فاسق فاجر بے نماز بھی ہیں) ان کے عمل کے بارے میں اس حدیث سے استدلال کرنا درست نہیں ہے۔"}],[658,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ انصار کا ایک آدمی نابینا ہو گیا تو اس نے رسول اللہ صلی اللہ علیہ وسلم کی طرف یہ پیغام بھیجا کہ آپ میرے گھر میں میرے لیے مسجد کی جگہ لکیر لگا دیں تا کہ میں وہاں نماز ادا کیا کروں۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے۔ ان کے پان اس کی قوم کے لوگ بھی جمع ہو گئے تو ان میں سے ایک شخص کہیں غائب ہو گیا۔ تو آپ صلی اللہ علیہ وسلم نے پوچھا: ”فلاں شخص کہاں گیا؟“ تو بعض لوگوں نے اس کا ذکر کیا تو آپ نے فرمایا: ” کیا وہ بدر میں ہمارے ساتھ شریک نہیں ہوا۔ لوگوں نے کہا: جی ہاں! لیکن وہ ایسا اور ایسا شخص ہے ( یعنی اچھا نہیں ہے ) تو رسول الله ملل علیم نے فرمایا: ”شاید کہ اللہ تعالیٰ نے اہل بدر پر جھانک کر یوں فرمایا: جو چاہو سو کرو میں نے تمہیں معاف کر دیا ہے۔“ مفصل حدیث بخاری شریف میں موجود ہے۔ (دیکھئے صحیح بخاری، کتاب الصلاة، رقم: ٤٢٥) اس صحابی رسول ملنے کی یمن کا نام عتبان بن مالک انصاری تھا۔ حافظ ابن حجر جماللہ نے بخاری شریف کی مفصل حدیث سے درج ذیل مسائل اخذ کیے ہیں: (١) اندھے کی امامت کا جائز ہونا، (٢) اپنی بیماری کی شکایت کرنا۔ (٣) عتبان جیسے معذوروں کے لیے اندھیرے اور بارش میں جماعت کا معاف ہونا (٤) بوقت ضرورت نماز گھر میں پڑھنے کے لیے ایک جگہ مقرر کر لینا (٥) نبی مکرم سے ہم نے جس جگہ نماز پڑھی اس جگہ کا متبرک ہونا (٦) صالح نیک انسان کو گھر میں برکت کے لیے بلایا جائے تو جائز ہے (٧) بڑے لوگوں کا چھوٹے کی دعوت قبول کرنا۔ حافظ ابن حجر جماللہ نے تقریباً اٹھارہ مسئلے اخذ کیے ہیں۔ یہ بھی مذکورہ حدیث سے معلوم ہوا کہ شہبے کی بنا پر کسی مومن کے بارے بدگمانی کرنا جائز نہیں","",{"k":"الزوائد: ٦ / ١٠٦ . صحیح بخاری (١١٧٣)، مجمع۔"}],[659,"سیدنا ابو الدرداء رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو شخص تین آدمیوں کا بھی حاکم بنا تو وہ اللہ تعالیٰ کو اس حال میں ملے گا کہ اس کا دایاں ہاتھ جکڑا ہوا ہو گا پھر اس کا انصاف کرنا اس کو کھول دے گا یا اس کا ظلم جکڑ دے گا۔“ یہ حدیث حضرت ابو الدرداء سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں سعید کیلے ہیں۔","",{"k":"مجمع الزوائد (٥/٢٠٦)، ضعيف الترغيب والترهيب (١٣٣٢)۔","f":"مذکورہ روایت کمزور ہے تاہم جب آدمی کسی کا امیر بنایا گیا وہ اللہ کے ہاں جواب دہ ہوگا۔"}],[660,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک آدمی لایا گیا جس نے زنا کیا تھا تو آپ نے اس سے پوچھا: تو اس نے اقرار کر لیا تو آپ نے حکم دیا تو اس کے کپڑے اتارے گئے تو وہ بہت کمز ور خلقت آدمی تھا چلنے کے قابل بھی نہیں تھا آپ نے فرمایا: ”ضرب اس کا کیا باقی نہیں چھوڑے گی؟، پس آپ نے کھجور کے درخت کی ایک ٹہنی منگوائی جس کی سوشا نھیں تھیں آپ نے وہ اس کو ایک ہی دفعہ ماردی۔“ یہ حدیث زید سے صرف عبید اللہ ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ انتہائی نحیف اور مریض آدمی کے ساتھ حد جاری کرنے میں مناسب حیلہ اختیار کیا جا سکتا ہے۔","",{"k":"سنن ابو داؤد (٤٤٧٢)، قال الشيخ الالبانی، صحیح، مجمع الزوائد (٢٥٢/٦)۔"}],[661,"سیدنا انس بن مالک نبی اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا کیا کرتے تھے: ”اے اسلام اور مسلمانوں کے ولی! مجھے اس پر ثابت رکھ یہاں تک کہ میں تجھ سے آملوں۔“ یہ حدیث حضرت انس سے اسی سند سے مروی ہے اسے روایت کرنے میں ابوالواصل اکیلے ہیں۔","",{"k":"المطالب العاليه لابن حجر (٣٠٢٣)، الاحاديث المختارة للمقدسي (١/١٥٠)، السلسلة الصحيحة (١٨٣٣)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ انسان کو دین اسلام پر ثابت قدمی کی دعا مانگتے رہنا چاہیے، سیدہ ام سلمہ نیلی و بہا فرماتی ہیں کہ نبی مکرم نے تم یہ دعا بکثرت کیا کرتے تھے۔ ((يا مقلب القلوب ثبت قلبي على دينك)) کیونکہ ہر آدمی کا دل اللہ تعالیٰ کی دو انگلیوں کے درمیان ہے جسے چاہے راہ راست پر قائم رکھے جسے چاہے بھٹکا دے۔ (صحیح ترمذی، رقم: ٢٧٩٢) ایمان پر استقامت کے لیے درج ذیل قرآنی دعا پڑھتے رہنا چاہیے: رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَّدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ ﴾ (آل عمران: ٨) وہ دعا کرتے ہیں: ) اے ہمارے رب! ہمیں ہدایت دینے کے بعد ہمارے دلوں کو ٹیڑھا نہ کر اور عطا کر ہمیں اپنے پاس سے رحمت، بے شک تو ہی بڑا عطا کرنے والا ہے۔“"}],[662,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: ”اے اللہ! میں تیری پناہ چاہتا ہوں اس دل سے جو ڈرتا نہیں، اس نفس سے جو سیر نہ ہوتا ہو، اس علم سے جو نفع نہ دے اور اس دعا سے جو سنی نہ جائے۔ اے اللہ! میں ان چار چیزوں کے شر سے تیری پناہ چاہتا ہوں۔ اے اللہ! میرے گناہ معاف کر دے اور میری غلطیاں بھی اور میرے جان بوجھ کر کیے ہوئے گناہ بھی معاف کر دے۔“ یہ حدیث ابوالواصل سے صرف عتاب ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد، سنن ترمذى (٣٤٨٢)، قال الشيخ الالباني، صحیح۔","f":"مذکورہ دعا میں ایسے علوم جو دین و دنیا کے فوائد سے خالی بلکہ وقت اور صلاحیت ضائع کرنے والے ہوں، ان سے اللہ کی پناہ طلب کی گئی ہے۔ یہ بھی معلوم ہوا کہ نبی مکرم سے ہم اپنے گناہوں کی معافی مانگتے حالانکہ نبی مکرم صل علی کی معصوم عن الخطا ہیں پھر بھی بکثرت اللہ ذوالجلال سے استغفار کرتے تھے۔ ٦٣"}],[663,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جس نے کسی معاہد ( ذمی ) عورت کو ناحق قتل کیا وہ جنت کی خوشبو بھی نہیں پاسکے گا حالانکہ جنت کی خوشبوسو سال کی مسافت سے بھی پائی جاتی ہے۔“ یہ حدیث عوف سے صرف عیسی ہی روایت کرتے ہیں۔","",{"k":"الخ، رقم : ٤٧٤٨ . السلسلة الصحيحه (٢٣٥٦)، سنن نسائی۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جس کسی نے ذمی کو ناحق قتل کیا وہ جنت کی خوشبو سے محروم ہو جائے گا۔ ٦٤"}],[664,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو لوگ اپنے دین سے الگ ہو گئے اور وہ کئی جماعتیں بن گئے آپ کسی چیز میں بھی ان سے کوئی تعلق نہیں رکھتے۔“ آپ نے فرمایا: ” یہ لوگ اس امت کے بدعات اور خواہشات پرست ہیں۔ “ یہ حدیث سفیان سے صرف موسیٰ ہی روایت کرتے ہیں، اسے روایت کرنے میں معلل اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٩/١٣٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ دین سے الگ ہو کر مسلمانوں کی جماعت سے نکل جانا بڑا جرم ہے۔ کیونکہ لوگوں کے ساتھ رہنا بڑی سعادت کی بات ہے، جیسا کہ حدیث میں ہے۔ ((المؤمن الذى يخالط الناس ويصبر على اذا هم افضل من المؤمن الذي لا يخالط الناس ولا يصبر على اذاهم . ( ) (صحيح الجامع الصغير، رقم: ٦٦٥١) وہ مومن جو لوگوں سے میل جول رکھتا اور ان سے پہنچنے والی تکلیفوں پر صبر کرتا ہے، اس مومن سے افضل ہے جو لوگوں سے میل ملاپ نہیں رکھتا ہے اور ان کی تکلیفوں پر صبر نہیں کرتا ہے۔"}],[665,"سیدہ عائشہ علی النیہا نے بیان کیا، میں رسول اللہ صلی اللہ علیہ وسلم کے گھر میں گڑیوں سے کھیلا کرتی تھی۔“ یہ حدیث سفیان سے صرف محمد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ بچیوں کے لیے گڑیوں سے کھیلنا جائز ہے لیکن گڑیوں کو ان مورتیوں میں سے مستثنیٰ رکھا گیا ہے، جن کا بنانا حرام ہے جو بچیاں اپنے ہاتھ سے گڑیاں گڈے وغیرہ بناتی ہیں یہ بھی جائز ہیں۔ ٦٦٦","",{"k":"صحیح بخاری، صحيح مسلم۔"}],[666,"سیدہ عائشہ علی الجھا نے بیان رسول اللہ صلی اللہ علیہ وسلم سے کاہنوں کے متعلق پوچھا گیا تو آپ نے فرمایا: وہ کچھ بھی نہیں لوگوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم وہ کچھ باتیں ایسی کرتے ہیں کہ کبھی کبھی سچی ہو جاتی ہیں۔ آپ نے فرمایا: ”یہ کلمہ حق ہوتا ہے جس کو جن اٹھا کر اپنے دوست کے کان میں مرغی کی طرح ڈال دیتا ہے، پھر اس کے ساتھ وہ سوجھوٹ ملا لیتے ہیں۔“ زمانہ جاہلیت میں شیاطین آسمانوں پر جاتے تھے۔ تکوینی امور کے سلسلہ میں جو وہاں باتیں ہوتی تھیں ان کو سن لیتے تھے اور ان باتوں کو کاہنوں کو بتا دیتے تھے۔ وہ کا ہن یہ باتیں لوگوں میں پھیلا دیتے تھے۔ کیونکہ اوپر سے سنی ہوئی بات ہوتی تھی اس لیے صحیح نکلتی تھی اور وہ ان میں اپنی طرف سے بھی ایک بات میں سو باتیں اور ملا دیتے تھے۔ ان گھڑی ہوئی پیشین گوئیوں میں سے بھی کوئی بات ٹھیک نکل آتی تھی اس وجہ سے لوگ ان کے معتقد ہو جاتے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم کی بعثت ہوئی تو اوپر جانے والے شیاطین کو روکنے کے لیے یہ انتظام کیا گیا۔ جب شیاطین نیچے سے اوپر تک ایک کے اوپر دوسرا ہو کر اوپر پہنچتے ہیں اور وہاں سننے کے لیے کان لگاتے ہیں تو ان کو آگ کے شعلے سے مارا جاتا ہے۔ بعض مرتبہ ایسا ہوتا ہے کہ سب سے اوپر والے نے کوئی بات سن لی اور اس کو شعلہ نہیں لگا تھا کہ اس نے اپنے نیچے والے کو کہہ دی پھر وہاں سے یکے بعد دیگرے ہوتے ہوئے سب سے آخری نیچے والے شیطان تک پہنچ گئی وہ اس کا ہن کے کان میں ڈال دی اس نے اس میں سوجھوٹ اور ملا دیئے۔","",{"k":"صحیح بخاری (٦٢١٣)، صحیح مسلم (٢٢٢٨)۔"}],[667,"سیدنا ابو ہریرہ رضى ال علینہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: اللہ تعالیٰ زمین کو مٹھی میں لے لے گا اور آسمانوں کو دائیں ہاتھ میں لپیٹ کر فر مائے گا: \"أَنَا الْمَلِكُ فَأَيْنَ مُلوكُ الْأَرْضِ ” میں بادشاہ ہوں زمین کے بادشاہ کہاں ہیں۔“","",{"f":"مذکورہ حدیث میں اللہ تعالیٰ کے ہاتھوں کا اثبات ہے لیکن ان کی حقیقت کو اللہ تعالیٰ جانتا ہے۔ (٢) حقیقی بادشاہ تو اب بھی اللہ عزوجل ہی ہے مگر دنیا میں عارضی بادشاہ موجود ہیں اور ان میں جبار اور متکبر بھی ہیں۔ لیکن محشر میں کسی کا کوئی وجود نہیں ہوگا اور بادشاہت صرف ایک اکیلے اللہ کی ہوگی۔"}],[668,"سیدنا حسان بن ثابت انصاری نبی اللہ نے فرمایا: ابو ہریرہ یا اللہ! میں تجھے اللہ کی قسم دیتا ہوں کہ بتاؤ کیا تم نے پیغمبر صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے؟ ” (اے حسان! ) رسول اللہ علیم کی طرف سے ( کفار کو ) جواب دو۔ اے اللہ! روح القدس (جبریل علینا) کے ذریعے اس کی مدد فرما۔“ تو سیدنا ابو ہریرہ یا الیہ نے فرمایا: ”ہاں“۔ مذکورہ حدیث سے معلوم ہوا کہ اسلام کی حمایت اور کفر کی مذمت میں نظم ونثر میں بولنا اس بارے کتابیں مضامین لکھنا باعث ثواب ہے۔ تاہم جو نام نہاد مسلمان قرآن وحدیث کی توہین و تخفیف کریں۔ جیسا کہ آج کل منکرین حدیث کا گروہ کرتا رہتا ہے ان کو جواب دینا اور ان کی مذمت کرنا بھی ضروری ہے۔ ٦٦٩","",{"k":"صحیح بخاری (٦١٥٢)، صحیح مسلم (٢٤٨٦)۔"}],[669,"سیدنا عبد اللہ بن کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ جب شعر کے متعلق آیات نازل ہوئیں تو کعب بن مالک رضی اللہ عنہ یہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو عرض کیا: اللہ کے رسول! آپ صلی اللہ علیہ وسلم کو معلوم ہی ہے جو کچھ اللہ تعالیٰ نے شعروں کے متعلق نازل فرمایا ہے تو آپ صلی اللہ علیہ وسلم کا اس کے متعلق کیا خیال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مومن اپنی تلوار کے ساتھ بھی جنگ کرتا ہے اور اپنی زبان کے ساتھ بھی۔“ یہ احادیث اسحاق سے صرف عتاب ہی روایت کرتے ہیں۔","",{"k":"مسند احمد (٤٥٦/٣، ١٥٨٢٣)، صحیح ابن حبان (٥٧٨٦)، قال الشيخ شعيب الأرناؤط، صحيح۔","f":"ایک دوسری حدیث میں ہے سیدنا انس خیلی اہلیہ سے روایت ہے نبی مکرم ملنے یم نے فرمایا: ((جاهدوا المشركين باموالكم وانفسكم والسنتكم)) (صحیح سنن ابی داؤد، رقم: ٢١٨٦) مشرکوں سے اپنے مالوں، جانوں اور اپنی زبانوں کے ساتھ جہاد کرو۔“ معلوم ہوا مسلمانوں کے تمام طبقات کو اپنی اپنی ممکنہ صلاحیتوں کے ساتھ کفر کے مقابلہ میں تیار رہنا واجب ہے جوان جوانی سے، اغنیاء اپنے مالوں سے، علماء دعوت و ترغیب سے اور تردید کفر و شرک سے بزرگ،عورتیں اور بچے اللہ کے حضور دعاؤں سے اسلام، اور مجاہدین اسلام کے لیے مدد مانگیں اشعار کی صورت میں کفر و شرک و مشرکین کی مذمت اور ہجو بھی زبان سے جہاد میں شامل ہے۔"}],[670,"سیدہ ام عطیہ انصاریہ فی الحجہ کا بیان ہے، ہمیں رسول اللہ سے تم نے حکم فرمایا: کہ ہم کنواری اور پردہ دار خواتین کو (عید کے روز ) باہر نکالیں اور حیض والی عورتوں کو بھی نکالیں تو وہ خیر اور بھلائی اور مسلمانوں کی دعا میں شامل ہوں تو ایک عورت نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! جب ہم میں سے کسی کے پاس کپڑا نہ ہو تو وہ کیا کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کی دوسری بہن اسے اپنا زائد کپڑا دے تا کہ وہ اس میں پردہ دار ہو۔ یعنی عید کے روز۔ یہ حدیث حبیب سے اور یونس سے صرف حماد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نماز عید واجب ہے کیونکہ جب حائضہ اور بغیر چادر والی خواتین کو عید گاہ میں حاضر ہونے کا حکم ہے تو مردوں کو بالا ولی یہ حکم ہے۔ یہ بھی معلوم ہوا کہ خواتین بوڑھی ہوں یا جوان، کنواری ہوں یا شوہر دیدہ، حائضہ ہوں یا طاہرہ انہیں عید گاہ کی طرف جانا چاہیے اور کم از کم مسلمانوں کی دعائے خیر میں ضرور شرکت کرنا چاہیے۔ امام ابن قدامہ جماللہ نے یہ فتویٰ دیا ہے کہ عید کے دن عورتوں کے عید گاہ کی طرف جانے میں کوئی حرج نہیں۔ (المغنی لابن قدامه: ٢٦٣/٣) شیخ ابن جبرین، ابن باز اور سعودی مستقل فتوی کمیٹی کا بھی یہی فتویٰ ہے کہ عورتیں عید گاہ کی طرف جا سکتی ہیں، لیکن خواتین باپردہ ہو کر نکلیں گی، زیب و زینت ظاہر کرتے ہوئے نہ نکلیں۔ (فتاوی اللجنة الدائمة: ٢٨٧/٨)","",{"k":"صحیح مسلم، رقم : ٨٩٠ . صحیح بخاری (٩٧٤)۔"}],[671,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، سیدنا ابو قتادہ رضی اللہ عنہ کے لمبے بال تھے تو انہوں نے ان کے متعلق نبی صلی اللہ علیہ وسلم سے سوال کیا تو آپ نے فرمایا: ان بالوں کا اکرام کرو اور ان کو تیل لگاؤ۔“ یہ حدیث بیٹی سے صرف اسماعیل ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (١٦٤/٥)، اسناده ضعیف، کنز العمال (١٧٢٦٨)۔"}],[672,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ناک میں بالوں کا اگنا کوڑھ سے امن اور نجات کا باعث ہے۔ یہ حدیث ہشام سے صرف ابوالربیع ہی روایت کرتے ہیں۔ ٦٧٣","",{"k":"الضعيفة: ٤٦٨٧ . مجمع الزوائد (٥/١٠١)، ضعيف الجامع الصغير (٥٩٥٤)، السلسلة۔"}],[673,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک غزوہ میں ایک قتل کی ہوئی عورت کے پاس سے گزرے تو آپ نے فرمایا: ” یہ عورت تو جنگ کرنے کے قابل نہیں تھی پھر آپ نے عورتوں اور بچوں کو قتل کرنے سے منع فرما دیا۔ یہ حدیث محمد بن زید سے صرف شریک ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جنگ میں قصداً عورتوں یا بچوں کا مارنا اسلام میں ٦٧٤: ناپسندیدہ کام ہے۔ تاہم اگر عورتیں قتال میں عملاً حصہ لیں اور لڑائی کریں تو قتل کرنا جائز ہوگا۔","",{"k":"صحیح بخاری، رقم : صحیح مسلم، رقم : ١٧٤٤ . ভ۔"}],[674,"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں فرمایا: ” علی علی الی! تیرے لیے جنت میں ایک خزانہ ہے اور تم اس کے دو سینگ ہو۔ تو تم ایک نظر کے پیچھے دوسری نظر نہ لگاؤ کیونکہ پہلی نظر کی تمہیں اجازت ہے مگر دوسری نظر کی اجازت نہیں ہے۔“ یہ حدیث حضرت علی سے اسی سند سے مروی ہے، اسے روایت کرنے میں حمادا کیلے ہیں۔","",{"k":"مجمع الزوائد (٤/٢٧٧)، صحیح ابن حبان، رقم: (٥٥٧٠)، مسند احمد ١/ ١٥٩، قال الشيخ شعيب الارناؤط : حسن لغيره۔","f":"معلوم ہوا غیر محرم عورت پر پڑنے والی پہلی نظر معاف ہے لیکن دوسری نظر یا بار بار دیکھنا اور دیکھتے ہی رہنا باعث گناہ ہے"}],[675,"سیدنا انس رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم کے لیے ورس اور زعفران کے ساتھ رنگا ہوا ایک کمبل تھا، آپ اس کے ساتھ اپنی عورتوں کے پاس جاتے جس کی باری ہوتی وہ اس پر پانی چھڑکاؤ کر یہ حدیث ثابت سے صرف عمارہ ہی روایت کرتے ہیں، اسے روایت کرنے میں مؤمل اکیلے ہیں۔","",{"k":"صحيح الجامع الصغير (٤٨٣٥)، السلسلة الصحيحة (٥/١٠٠، ٢١٠١)۔","f":"معلوم ہوا رنگ دار لباس کا استعمال مباح ہے بشرطیکہ شرعی امور کوملحوظ رکھ کر رنگ کیا گیا ہو۔"}],[676,"سیدنا ابو ہریرہ بنی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مہینے کی سترہویں، انیسویں اور اکیسویں تاریخ کو پچھنا لگوایا کرو۔ یہ حدیث ابن لھیعہ سے صرف محمد بن محصن ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قمری مہینے کی سترہ، انیس اور اکیس تاریخ کو سینگی لگوانا مستحب ہے ان تاریخوں کا تعلق امرغیب سے ہے۔ ہم اس کی کوئی توجیہ نہیں کر سکتے۔ ان پر ایمان رکھنا واجب ہے ان تواریخ کا اہتمام کرنا چاہے اور قدیم اطباء کا بھی اجماع ہے کہ دوسرا نصف پہلے کی نسبت بہتر ہے۔","",{"k":"سنن ابو داؤد، متى تستخبر (٣٨٦١)، مستدرك حاكم (٤٢٣٣)، قال الالباني، حسن۔"}],[677,"سیدنا انس بن مالک رضی اللہ عنہ علیہ وسلم نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سفید مرغ فندق (گھر میں) رکھا کرو کیونکہ جس گھر میں سفید مرغ ہو اس کے آس پاس کوئی شیطان، جادوگر اور کیڑے مکوڑے نہیں آتے","",{"k":"مجمع الزوائد (٥/١١٧)، ضعيف الجامع الصغير (٩١)، قال الشيخ الالبانی، موضوع۔"}],[678,"سیدنا معاذ بن جبل رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ اس علم کو فرماتے ہوئے سنا: ” بہترین مسواک زیتون کا ہے جو مبارک درخت کا ہوتا ہے منہ کو صاف کرتا ہے اور دانتوں کی زردی ختم کر دیتا ہے یہ میری اور مجھ سے پہلے انبیا علیلسلام کی مسواک ہے۔“ یہ دونوں حدیثیں ابراہیم سے صرف محمد ہی روایت کرتے ہیں۔","",{"k":"مجمعا الالبانی، موضوع. ع الزوائد: ٢/، السلسلة الضعيفة (٥٣٦٠)، قال الشيخ۔"}],[679,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے بھائی کی مدد کر چاہے ظالم ہو یا مظلوم ہو اگر مظلوم ہے تو اس پر ظلم کرنے والے کے خلاف اس کی مدد کر اور اگر ظالم ہے تو اس کو ظلم سے ہٹا دے۔“ یہ حدیث حدیج سے صرف جعفر ہی روایت کرتے ہیں۔ ٦٨٠","",{"k":"صحیح بخاری (٦٩٥٢)، سنن ترمذی (٢٢٥٥)۔"}],[680,"سیدنا جابر رضی اللہ عنہ نے بیان کیا: ”میں نے سرخ حلے (جوڑے) میں رسول اللہ الے علم سے زیادہ خوبصورت کوئی نہیں دیکھا۔“ یہ حدیث سفیان سے صرف ایوب ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ سرخ رنگ کا لباس جائز ہے لیکن یہ خالص سرخ رنگ کا لباس نہیں بلکہ اس میں سرخ رنگ کی دھاریاں تھیں۔ جسے برد کہا جاتا ہے۔ علامہ ابن القیم جاللہ نے زاد المعاد (فصل في ما لبسه: ١٣٢/١) میں اس کی یہی توجیہ پیش کی ہے۔","",{"k":"صحیح بخاری (٥٨٤٨)، سنن ابو داؤد، رقم : ٤٠٧٢ . فائدة۔"}],[681,"سيدنا ابو موسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ولی کے بغیر کوئی نکاح نہیں ہوتا۔ اسے شریک سے صرف علی ہی روایت کرتے ہیں۔ ٦٨٢","",{"k":"سنن ابو داؤد (٢٠٨٥)، سنن ترمذی (١١٠١)، قال الشيخ الالباني، صحیح۔"}],[682,"سیدنا عبد الرحمن بن ابری رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم وتر میں سبح اسْمِ رَبَّكَ الأعْلى، قُلْ يَا أَيُّهَا الْكَافِرُوْنَ﴾ اور قُلْ هُوَ اللَّهُ أَحَدٌ﴾ پڑھا کرتے تھے۔“ یہ حدیث عمرو سے سوائے قران کے کوئی روایت نہیں کرتا۔ .:٦٨٣","",{"k":"کی سنن ترمذی (٤٦٢)، سنن نسائی کتاب قیام اللیل باب نوع آخر منه (١٧٣١)۔","f":"نا معلوم ہوا کہ نماز وتر میں تینوں سورتوں کی تلاوت کرنا مسنون ہے۔"}],[683,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا: ” رسول اللہ صلی اللہ علیہ وسلم نے ہمیں تشہد سکھائی: التحیات للہ آخر تک یعنی تمام زبانی، بدنی اور مالی عبادتیں اللہ ہی کے لیے ہیں۔ اے نبی صلی اللہ علیہ وسلم! آپ پر سلام ہو، اللہ کی رحمت اور اس کی برکتیں ہوں۔ سلام ہم پر اور اللہ تعالیٰ کے نیک بندوں پر ہو میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد ملنے کی تم اس کے بندے اور اس کے رسول ہیں۔“ یہ حدیث عمر و سے صرف محمد ہی روایت کرتے ہیں۔","",{"k":"ابو داؤد، رقم : ٩٧٠ . صحیح بخاری (٨٣١)، سنن۔"}],[684,"سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اپنی اولاد میں سے کسی کو اپنے آگے بھیج دیا اور وہ ثواب کا طلب گار صبر کرنے والا ہوا تو وہ اس کے لیے جہنم سے حجاب اور پردہ بن جائے گی۔“ یہ حدیث موسیٰ سے صرف ابو یحییٰ ہی روایت کرتے ہیں۔ تاہم صحیح روایات میں ہے جس کے دو یا تین بچے فوت ہو گئے تو وہ بچے اپنے ماں باپ کو جنت میں لے جائیں گے اور جہنم سے آڑ بن جائیں گے۔ جیسا کہ سیدنا ابو ہریرہ یا یہ فرماتے ہیں کہ ایک عورت نبی معظم صلی اللہ علیہ وسلم کے پاس ایک بچے کو لے کر آئی اور عرض کیا کہ اس بچے کے لیے دعا فرمائیں۔ میں تین بچوں کو دفن کر چکی ہوں۔ آپ مطلعے علیم نے فرمایا: تو نے جہنم کے آگے مضبوط دیوار بنالی ہے۔ (ادب المفرد للبخارى،رقم: ١٤٤)","",{"k":"مجمع الزوائد (٩/٣)، فيه ابويحيى التيمي وهو ضعيف۔"}],[685,"سیدنا عابس غفاری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا کہ آپ اپنی امت پر چھ باتوں سے خوف زدہ تھے اور (١) بچوں کی حکومت (٢) کوتوالوں کی کثرت (٣) فیصلے میں رشوت (٤) قطع رحمی (٥) خونریزی کو ہلکا گرداننا (٦) ایسی پود جو قرآن کو بانسری بنالیں گے وہ ایسے آدمی کو آگے کریں گے جو سمجھ دار اور فقیہ نہیں ہوگا اور نہ ہی کوئی زیادہ پڑھا ہوا اور زیادہ فضیلت والا ہوگا اور وہ انہیں گانا سنائے گا۔ یہ حدیث موسیٰ سے صرف عیسی ہی روایت کرتے ہیں۔ ٨٦","",{"k":"صحيح الجامع الصغير (٢١٦)، منسد احمد (٦/٢٢)، مجمع الزوائد۔"}],[686,"سیدنا زید بن خطاب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گھروں میں رہنے والے سانپوں کو قتل کرنے سے منع فرمایا ایسے سانپوں کو عوام کہتے ہیں۔“ یہ حدیث جعفر سے صرف فیاض ہی روایت کرتے ہیں۔ بالخصوص مدینہ منورہ کے متعلق وارد ہے کہ وہاں گھروں میں جن رہتے تھے جو سانپوں کی شکل میں موقع بموقع نمودار ہوتے رہتے تھے۔ لیکن گھر والوں کو کوئی اذیت نہ دیتے تھے اس لیے باقی مقامات پر بھی اگر کہیں ایسی صورت ہو کہ سانپ موقع بموقع نظر آ کر غائب ہو جا تا ہو تو وہ جن ہوسکتا ہے اس لیے اس کو مارنے میں جلدی نہیں کرنا چاہیے بلکہ تین بارا سے اپنی زبان میں تنبیہ کرنا چاہیے کہ وہ یہاں سے چلا جائے، اگر اس کے بعد دکھائی دے تو مار دیا جائے۔","",{"k":"صحیح بخاری (٣٢٩٨)، سنن ابو داؤد (٥٢٥٢)، المعجم الكبير للطبراني ٤ / ٤٠٦ (٤٣٧٢)۔"}],[687,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میرے صحابہ کو گالیاں نہ دو اللہ کی قسم! اگر تم میں سے کوئی احد پہاڑ کے برابر سونا خرچ کرے تو وہ ان کے ایک مد یا نصف مد کے برابر بھی نہیں ہوسکتا۔ یہ حدیث از اعمش از ابی صالح از حضرت ابو ہریرہ صرف زید ہی روایت کرتے ہیں، شعبہ اور اُن کے اصحاب از اعمش از ابی صالح از ابوسعید روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام رضوان اللہ علیہم اجمعین کو سب وشتم کرنا حرام ہے کیونکہ اصحاب رسول امت محمدیہ کا بہترین اور افضل ترین طبقہ ہیں انہوں نے براہ راست رسول اللہ صلی اللہ علیہ وسلم سے دین و ایمان حاصل کیا۔ ان کی قربانی اور جاں شاری سے اسلامی حکومت مستحکم ہوئی اور پھر انہوں نے دین کی عظیم امانت اگلی نسلوں کو منتقل کی۔ اس لیے ان کی عند اللہ بڑی اہمیت ہے کہ اس امت کے بہترین لوگ صحابه من السلام ہیں جیسا کہ سیدنا عبد اللہ بن مسعود رضى الله فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بہتر لوگ میرے زمانہ کے (صحابہ بی ایم ) ہیں پھر وہ لوگ ہیں جو ان کے بعد ہوں گے، پھر وہ لوگ جو ان کے بعد ہوں گے۔ (صحیح بخاری، کتاب الشهادات، رقم: ٢٦٥٢)","",{"k":"صحیح بخاری، رقم :، ٣٦٧٣ صحیح مسلم (٢٥٤٠)۔"}],[688,"سیدنا جابر بن عبد اللہ ہی اللہ نے بیان کیا، رسول اللہ علیم نے فرمایا: \"جو شخص اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتا ہو وہ نہ بند کے بغیر حمام میں داخل نہ ہو جو شخص اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتا ہے وہ اپنی بیوی کو حمام میں نہ داخل کرے۔ جو شخص اللہ تعالیٰ اور آخرت کے دن پر ایمان رکھتا ہے وہ ایسے دستر خوان پر نہ بیٹھے جس پر شراب کا دور چلتا ہو۔ یہ حدیث ابراہیم سے صرف عثمان ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی (٢٨٠١)، قال الشيخ الالباني، حسن۔"}],[689,"سیدنا ابو ہریرہ فی اللہ سے روایت ہے کہ رسول اللہ ملنے صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص علم سیکھ کر آگے بیان نہ کرے اس کی مثال اس شخص کی طرح ہے جو خزانہ جمع کرتا ہے اور اس میں سے خرچ نہیں کرتا۔“ یہ حدیث حضرت ابو ہریرہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابن لھیہ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ علم کو سیکھ کر آگے لوگوں کو سکھانا چاہیے۔ جو لوگ علم کو چھپاتے ہیں ان کے متعلق بڑی سخت وعید ہے۔ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”جس شخص سے علم کے متعلق سوال کیا گیا اور اس نے اسے چھپایا تو قیامت کے دن اس کے منہ میں آگ کی لگام پہنائی جائے گی۔ (سنن ابن ماجه، مقدمه، رقم: ٢٦٦، شیخ البانی رحمہ اللہ نے اسے صحیح کہا ہے )۔ ٦٩٠","",{"k":"المعجم الكبير للطبرانی (١٩/١٣١)، السلسلة الصحيحة، رقم : (٣٤٧٩)، صحيح الجامع الصغير (٥٨٣٥)۔"}],[690,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ ملے عام ہمارے پاس تشریف لائے جبکہ ہم ایک ڈھال پر کھانا کھا رہے تھے تو آپ ہمارے ساتھ بیٹھے اور کھانا کھانے لگے اور آپ نے پانی کو نہیں چھوا۔“ یہ حدیث عمر د سے صرف موسیٰ روایت کرتے ہیں۔","",{"k":"♦، مجمع الزوائد (٥/٢٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ کھانا کھانے سے پہلے اگر پانی کو نہ چھوا جائے یعنی ہاتھ نہ دھوئے جائیں تو کوئی حرج نہیں، مجمع الزوائد میں ہے سیدنا جابر رضی اللہ عنہ فرماتے ہیں: وہ کھجوریں تھی۔ (مجمع الزوائد: ٢٦/٥) ٦٩١"}],[691,"سیدنا انس رضی اللہ عنہ نے بیان کیا، نبی صلے علی تیم انصار کے کچھ لوگوں کے پاس سے گزرے جو ہنس رہے تھے تو آپ نے فرمایا: لذتوں کو توڑ دینے والی (موت) کو کثرت سے یاد کیا کرو۔“ یہ حدیث ثابت سے صرف حماد ہی روایت کرتے ہیں، اسے روایت کرنے میں مؤمل اکیلے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ انسان کو موت کو کثرت سے یاد رکھنا چاہیے کیونکہ موت کا تصور اور اس کا ذکر انسان کو دنیاوی لذتوں میں انہماک اور معصیتوں کے ارتکاب سے باز رکھتا ہے۔اس لیے کثرت سے موت کو یاد کرنا چاہیے اور موت کے بعد پیش آنے والے معاملات سے انسان کو غافل نہیں رہنا چاہیے۔ ٦٩٢","",{"k":"سنن ترمذی (٢٣٠٧)، قال ثَابِتِ الشيخ الالبانی حسن صحیح۔"}],[692,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، ”میں نے رسول اللہ صلی اللہ علیہ وسلم کو کعبے کے سامنے اپنے سرین پر بیٹھے ہوئے دونوں رانوں کو شکم مبارک سے ملائے ہوئے، اپنے ہاتھوں سے پنڈلیاں پکڑ کر بیٹھے ہوئے دیکھا۔ یہ حدیث یکی سے صرف ابو المثنی کعھی سلیمان بن یزید ہی روایت کرتے ہیں، اسے روایت کرنے میں ابوغز یہ اکیلے ہیں۔","",{"k":"صحیح بخاری (٦٢٧٢)، مجمع الزوائد (٥/١٣١)۔","f":"احتباء کا مطلب ہے دونوں رانوں کو کھڑا کر کے سرین پر بیٹھے اور ہاتھوں کو پنڈلیوں حلقہ کرے اور رانوں کو پیٹ سے ملائے۔"}],[693,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ نے ہیم نے فرمایا: ”پانچ وسق سے کم غلہ پر زکوۃ نہیں، پانچ اونٹوں سے کم اور پانچ اوقیہ چاندی سے کم پر زکوۃ نہیں ہے۔“ یہ حدیث لیث سے صرف عبد الوارث ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری، صحیح مسلم (٩٧٩)۔","f":"اوسق جمع ہے وسق کی، ایک وسق ساٹھ صاع کا ہوتا ہے اور ایک صاع میں چار مد ہوتے ہیں اور ایک مد ایک اور تہائی رطل کے برابر ہوتا ہے۔ جدید وزن کے مطابق ایک صاع تقریباً اڑھائی کلو گرام کے برابر ہوتا ہے اور پانچ وسق تقریباً بیس من کے برابر۔ ذو د، اونٹ کے معنی میں ہے یہ اسم جمع ہے اس میں مذکر اور مونث دونوں شامل ہیں۔ اواق جمع ہے اوقیہ کی، ایک اوقیہ میں چالیس درہم ہوتے ہیں اور پانچ اوقیہ میں دوسو درہم ہوئے۔ مذکورہ حدیث میں غلہ جات، اونٹوں، اور چاندی کے نصاب کا بیان ہے۔ جو جدید اوزان کے مطابق ساڑھے باون تولہ وزن بنتا ہے۔ اس سے معلوم ہوتا ہے کہ پانچ وسق سے کم غلے میں زکاۃ واجب نہیں، جمہور علماء اسی کے قائل ہیں، جبکہ امام ابو حنیفہ اللہ نے عمومی دلائل کو پیش نظر رکھتے ہوئے یہ رائے اختیار کی ہے کہ غلہ کم ہو یا زیادہ اس میں زکاۃ واجب ہے۔ (المغنی: ٢١/٤، الحاوی: ٢١٠/٣) لیکن یہ رائے مذکورہ بالا صریح حدیث کے خلاف ہونے کی وجہ سے درست نہیں اور جمہور کا مؤقف ہی راجح ہے۔ یہ بھی معلوم ہوا کہ پانچ اونٹوں سے کم پر زکاۃ نہیں۔"}],[694,"سیدنا عبد اللہ فی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا: کہ کوئی اپنے غلام یا بیٹے کا یہ نام رکھے: حارث، مرہ، ولید، حکم، ابو الحکم، افلح، نیج، یا بسیار “ اور آپ نے فرمایا: ”اللہ تعالیٰ کو سب سے پیارا نام وہ ہے جس کے ساتھ اس کی عبادت کی جائے اور سب سے سچا نام ہمام ہے۔“ یہ حدیث سفیان سے صرف محمد ہی روایت ہیں۔ مذکورہ روایت کمزور ہے تاہم، عبداللہ، عبد الرحمان، حمام، حارث نام رکھنے جائز ہیں۔ ٩٥","",{"k":"المعجم الكبير للطبراني (٨/٤٠٠، ٩٨٤٠)، مجمع الزوائد (٨/٥٢)۔"}],[695,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، جب نبی صلی اللہ علیہ وسلم نے مکہ فتح کیا تو اس کی طرف رخ کیا اور فرمایا: تو حرام ہے تیری حرمت کتنی عظیم ہے اور خوشبو کتنی اچھی ہے۔ مگر اللہ کے نزدیک مومن تجھ سے زیادہ محترم ہے۔ یہ حدیث ابن جریج سے صرف محمد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جس طرح بیت اللہ شریف کا احترام کرنا، عزت تعظیم کرنا ہر مسلمان پر فرض ہے اسی طرح مومن آدمی کا احترام کرنا بھی ضروری ہے۔","",{"k":"سنن ترمذی (٢٠٣٢)، مجمع الزوائد (١/٨١)، صحيح الترغيب والترهيب (٣٣٩)۔"}],[696,"سيدنا حذیفہ نے بیان کیا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب چھینکنے والا چھینک مارے تو اس کو جواب دو اگر چہ وہ سات سمندر پار ہی کیوں نہ ہو اور جس نے چھینکنے والے کو جواب دیا اللہ تعالیٰ اس سے نمونیہ کی بیماری نیز داڑھ اور کانوں کا درد ختم کر دیتا ہے۔ یہ حدیث ابراہیم بن ابی عبلہ سے صرف محمد ہی روایت کرتے ہیں۔ مذکورہ روایت کمزور ہے تاہم صحیح حدیث سے یہ ثابت ہے کہ ایک مسلمان کا دوسرے مسلمان پر حق ہے کہ چھینکنے والا چھینک مارے تو اس کی چھینک کا جواب دیا جائے۔ جیسا کہ نبی مکرم اے علی تم نے فرمایا: ”مسلمان کے مسلمان پر پانچ حق ہیں، سلام کا جواب دینا، بیمار کی بیمار پرسی کرنا، جنازوں میں پیچھے چلنا، دعوت کا قبول کرنا اور چھینکنے والے کی چھینک کا جواب دینا۔“ (صحیح بخاری، کتاب الجنائز) جب چھینکنے والا الحمد للہ کہے گا پھر سننے والا کہے گا: یرحمک اللہ، اگر چھینکنے والا الحمد للہ نہیں کہتا تو جواب نہیں دینا چاہیے۔ (صحیح بخاری، باب لا يشمت العاطس اذا لم بحمد الله)","",{"k":"مجمع الزوائد (٥/٨)، فيه محمد بن محصن العكاشى وهو متروك۔"}],[697,"سیدنا مستورد بن شداد ضیا الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے کسی مسلمان آدمی کی غیبت (وغیرہ) کے انعام میں ایک لقمہ کھایا تو اللہ تعالیٰ اس کو اس جیسا کھانا جہنم میں کھلائے گا۔ اور جس شخص کو کسی مسلمان کی غیبت وغیرہ کے انعام میں کپڑا پہنایا گیا تو اللہ تعالیٰ اس کو اس کی مثل جہنم سے کپڑا پہنائے گا اور جس شخص نے کسی مسلمان کو ریا اور شہرت کے مقام پر کھڑا کیا تو اللہ تعالیٰ قیامت کے روز اس کو ذلیل کرنے کے لیے ریا اور شہرت کے مقام پر کھڑا کریں گے۔“ یہ حدیث ابن ثوبان سے صرف بقیہ ہی روایت کرتے ہیں۔ مذکورہ حدیث میں اہل ایمان کی عزت اور آبرو کی قدر و قیمت بتائی گئی ہے۔ بہت سے لوگ مسلمانوں کی عزت سے کھیلتے ہیں کچھ لوگ یونہی کسی مسلمان کو بے آبرو کر دیتے ہیں اور بعض لوگ کسی مسلمان کی بے آبروئی کر کے کچھ نفع بھی اٹھا لیتے ہیں۔ اس کے متعلق فرمایا جس شخص نے کسی مسلمان کی بے عزتی کر کے لقمہ کھایا یا کپڑا پہنا تو قیامت کے دن دوزخ کی آگ سے اسی قدر کھائے گا اور اسی قدر پہنے گا۔ اسی طرح بعض لوگ اپنی شہرت اور جاہ کے لیے کسی دوسرے مسلمان کو ذلیل کر دیتے ہیں۔ اسی کے بارے میں فرمایا کہ اللہ تعالیٰ قیامت کے دن ایسے شخص کو ایسے مقام پر کھڑا کرے گا، جہاں یہ عذاب میں مبتلا ہوگا اور دیکھنے والے بھرے مجمع میں دیکھ لیں گے کہ اس شخص کو کسی مسلمان کو ذلیل کر کے اپنی شہرت حاصل کرنے کی وجہ سے یہ سزا مل رہی ہے۔","",{"k":"المعجم الكبير للطبراني ٢٤٢/١٥، سنن ابو داؤد، قال الشيخ الالبانى، صحیح۔"}],[698,"سیدنا ابو موسی اشعری رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے ارادہ کیا کہ وہ آپ کی بیعت کرے آپ نے اسے دیکھا کہ اس پر زرد نشان تھا تو آپ نے اس سے بیعت لینے سے انکار کر دیا۔ اور فرمایا: ”مردوں کی خوشبو وہ ہے جو خوشبو ظاہر ہو مگر رنگ پوشیدہ ہو جبکہ عورتوں کی خوشبو وہ ہے جس کا رنگ ظاہر ہو مگر خوشبو پوشیدہ ہو۔ “ یہ حدیث سفیان سے صرف رمادی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مہک والی خوشبوئیں اور عطر مردوں کے لیے ہیں لیکن مردوں کے لیے یہ جائز نہیں ہے کہ پاؤڈر اور کریمیں استعمال کریں جو ان کے رنگ و روپ کو نکھارنے والی ہوں یہ صرف عورتوں کے لیے جائز ہیں۔ یہ بھی اس وقت جب عورت گھر میں موجود ہے جب گھر سے باہر جائے تو اسے خوب صاف کر لے۔ معلوم ہوا کہ اسلام اپنے معاشرے میں ایسے کسی عمل کی اجازت نہیں دیتا جو بظاہر معمولی ہی سہی مگر دھیرے دھیرے بہت بڑے فتنے کا باعث ہو سکتا ہو یا بالخصوص عصمت و عفت کے بگاڑ اور معاشرے میں فساد کا باعث بنتا ہو۔","",{"k":"سنن ترمذی (٢٧٨٧)، قال الشيخ الالبانى صحيح۔"}],[699,"سیدنا ابو موسی رضی اللہ عنہ نے بیان کیا، میں اور میرے چچا کا بیٹا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اس کے پاس ایک مسواک تھی جس سے وہ مسواک کر رہا تھا۔ میں نے کہا: اللہ کے رسول لے نے ہمیں عامل مقرر فرما دیں کیونکہ ہمارے پاس غنا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص اس کام کی حرص رکھتا ہو ہم اس کو اس کام پر نہیں لگاتے۔“ یہ حدیث عبد الملک بن عمیر سے صرف محمد بن اسحاق ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جو شخص امارت و قضا اور دیگر مناصب حکومت کا سوال یا آرزو کرے اور اس کے لیے اپنے آپ کو پیش کرے تو ایسے شخص کو عہدہ و منصب دینا منع ہے۔ کیونکہ ایسے لوگ بالعموم اپنے ذاتی مفادات کے لیے ان عہدوں کو حاصل کرتے ہیں، جس سے عام لوگوں کے مفادات کو نقصان پہنچتا ہے، جبکہ حکومت کا مقصد تو عام لوگوں کو","",{"k":"صحیح بخاری (٧١٤٩)، المعجم الكبير للطبراني (٢٠/١٧٤)۔","f":"پہنچانا ہوتا ہے نہ کہ چند مراعات یافتہ مخصوص لوگوں کو یا حکومتی منصب پر فائز لوگوں کو۔ بخاری شریف میں ہے کہ سیدنا ابو موسی اشعری خلیل اللہ فرماتے ہیں: میں اور میرے دو چچا زاد بھائی نبی معظم ملنے کی یمن کی خدمت میں حاضر ہوئے تو ان میں سے ایک نے کہا۔ (صحیح بخاری، کتاب الاحكام، رقم: (٧١٤٩) اس سے معلوم ہوا کہ سیدنا ابو موسی اشعری رضی اللہ عنہ نے نہیں کہا تھا۔ ٧٠٠"}],[700,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بلال رات کو اذان دیتے ہیں تو تم (روزے کے لیے) کھاتے پیتے رہا کرو، یہاں تک کہ ابن ام مکتوم رضی اللہ عنہ دیں۔ یہ حدیث از روح بن قاسم صرف یزید بن زریع ہی روایت کرتے ہیں اور یزید سے صرف امیہ بن بسطام ہی روایت کرتے ہیں، اسے روایت کرنے میں ابارا کیلے ہیں۔","",{"k":"صحیح بخارى (٦١٧)، صحيح مسلم، رقم : ١٠٩٢ . الله۔","f":"مذکورہ حدیث سے معلوم ہوا کہ ایک مسجد کے لیے دو مؤذن مقرر کیے جا سکتے ہیں۔ یہ بھی معلوم ہوا کہ طلوع فجر سے پہلے بھی اذان دی جاسکتی ہے، لیکن یہ اذان کسی نماز کے لیے نہیں بلکہ محض لوگوں کو بیدار کرنے اور نماز کی تیاری کرنے کے لیے دی جائے گی۔ سیدنا عبد اللہ بن ام مکتوم فضل اللہ نابینا صحابی تھے۔ معلوم ہوا کہ نابینا آدمی بھی مؤذن بنایا جا سکتا ہے بشرطیکہ اسے کوئی وقت کی اطلاع دینے والا موجود ہو۔ ٢٠١"}],[701,"سیدنا جابر نبی اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے یہ آیت پڑھی: ﴿ وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلَّی \" کہ تم مقام ابراہیم کو جائے نماز بنالو۔ یہ حدیث روح سے صرف یز ید اور یزید سے صرف امیہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابارا کیلے ہیں۔ واتخذوا، خاکے نیچے زیر کے ساتھ، بصیغہ امر نبی معظم صلی اللہ علیہ وسلم نے پڑھا۔ دوسری قراءت: خا پر زبر یعنی صیغہ ماضی کے ساتھ ہے اور معنی ہیں اور لوگوں نے مقام ابراہیم کو جائے نماز بنا لیا۔ مقام ابراہیم بیت اللہ میں وہ پتھر ہے جس پر کھڑے ہو کر سیدنا ابراہیم خلیل علینا بیت اللہ کی تعمیر کرتے رہے اور اس میں آپ کے قدم نقش ہیں۔","",{"k":"٧٠١ صحیح سنن ابو داؤد (٣٩٦٩)، قال الالباني۔"}],[702,"سیدہ عائشہ وانا الیہا نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”پانچ جانور فاسق ( ضرر رساں) ہیں جنہیں حرم میں بھی مار دیا جائے (١) چیل (٢) کوا (٣) بچھو (٤) چوہیا (٥) اور کاٹنے والا کتا","",{"k":"صحیح بخاری، صحیح مسلم (١٢٠٠)۔"}],[703,"سیدہ عائشہ بنایا تنہا سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے عرض کیا: میری ماں اچانک فوت ہوگئی اور مجھے یقین ہے کہ اگر فوت ہوتے وقت کچھ کلام کرتی تو ضرور صدقہ کرتی تو کیا اگر میں اس کی طرف سے صدقہ کر دوں تو اس کو اس کا اجر ملے گا؟ آپ نے فرمایا: ”ہاں! ضرور۔“ یہ دونوں حدیثیں روح سے صرف یزید اور یزید سے صرف امیہ ہی روایت کرتے ہیں، ان کو روایت کرنے میں ابارا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ میت کی وصیت کے بغیر بھی اس کی طرف سے صدقہ کرنا جائز ہے۔ یہ بھی معلوم ہوا کہ والدین کی طرف سے صدقہ کر کے ثواب پہنچاتے رہنا چاہیے، جیسا کہ مذکورہ حدیث میں ہے۔ اسی طرح سیدنا سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ لیے علیم سے پوچھا کہ ان کی ماں وفات پاگئی ہے، کیا ان کی طرف سے خیرات کریں تو انہیں اس کا","",{"k":"سنن ابو داؤد، رقم : ٢٨٨٢ . صحیح بخاری، رقم : (١٣٨٨)۔","f":"پہنچے گا؟ آپ صلی اللہ علیہ وسلم نے جواب دیا کہ ہاں۔ “ اس پر سیدنا سعد رضی اللہ عنہ نے فرمایا کہ میرا ایک باغ ہے اور میں آپ کو گواہ بناتا ہوں کہ میں نے وہ ان کی طرف سے صدقہ کر دیا۔ (صحیح بخاری، کتاب الوصايا، رقم: ٢٧٧٠) اسی طرح سیدنا ابوطلحہ رضی اللہ عنہ نے کنواں اور باغ اللہ کے راستے میں وقف کر دیا تھا۔ (بخاری، رقم: ٢٧٦٩) ان روایات سے معلوم ہوا کہ ایصال ثواب کے لیے کنواں یا کوئی باغ وقف کر دینا بہترین صدقہ جاریہ ہے کہ مخلوق اس سے فائدہ حاصل کرتی رہے گی، کیونکہ پانی یا پھل ساری مخلوق کے کام آتے ہیں، اور اس سے طرح طرح کی دنیاوی حاجتیں اور دینی ضرورتیں پوری ہوتی ہیں۔ اسی طرح کوئی شخص مسجد یا مدرسہ یا مسافر خانہ بنوا جائے یا پانی کی ٹینکی بنوا دے یاتل لگوا دے یا پانی کا بل ادا کرنے کا انتظام کر دے تو یہ بھی پانی کے صدقہ میں شمار ہوگا اور بہت بڑے ثواب کا باعث ہوگا۔ ٧٠٤"}],[704,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”لوگ کانوں کی طرح ہیں ان میں سے جو جاہلیت میں بہتر تھے وہ اسلام میں بھی بہتر ہیں۔“ مذکورہ حدیث سے معلوم ہوا کہ جو لوگ زمانہ جاہلیت میں اخلاق اور عادات جود وسخا کے اعتبار سے اچھے تھے اسلام میں بھی وہی اچھے ہوں گے بشرطیکہ ان میں فقہ فی الدین یعنی دینی سمجھ آ جائے۔ دینی فقاہت سے مراد کتاب و سنت کی فقاہت ہے رائے وقیاس کی فقاہت نہیں )۔ جو اچھے اعمال وہ زمانہ جاہلیت میں کرتے تھے۔ اسلام قبول کر کے بھی انہیں اختیار کریں گے۔ لیکن علم اور دینی سمجھ ہو گی۔ تب ان اعمال میں جان پڑے گی اخلاص بھی آئے گا، اور ان کاموں کے کرنے کے مواقع بھی سمجھ میں آئیں گے اور اللہ کی رضا کے لیے ان کاموں کو انجام دیں گے۔ انسانوں میں اللہ تعالیٰ نے جو صفات رکھی ہیں۔ وہ صفات خیر اسلام میں باقی رہتی ہیں۔ اسلام انسانی صفات کو ختم نہیں کرتا بلکہ ان کا رخ موڑ دیتا ہے اور ان کا مصرف خیر بنا دیتا ہے۔ ٧٠٥","",{"k":"صحيح مسلم (٢٣٧٨)، ادب المفرد للبخاری (١٢٩)۔"}],[705,"اسی سند سے ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اہل کتاب کو سلام کرنے میں پہل نہ کرو اور جب ان کو راستے میں ملو تو انہیں بہت تنگ راستے کی طرف مجبور کر دو۔“ فائد مذکورہ حدیث میں غیر مسلموں سے سلام کا طریقہ بتایا گیا ہے پہلے سلام نہیں کرنا چاہیے کیونکہ سلام پہلے کہنے میں ان کی عزت و تکریم ہے حالانکہ عزت کے حق دار صرف اہل ایمان ہیں۔ جیسا کہ ارشاد باری تعالی ہے: وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ وَلَكِنَّ الْمُنَافِقِينَ لَا يَعْلَمُونَ﴾ (المنافقون: ٨) عزت صرف اللہ کے لیے اور اس کے رسول کے لیے اور ایمان والوں کے لیے ہے مگر منافق لوگ جانتے نہیں۔“ (٢) آپس میں سلام کرنے سے محبت پیدا ہوتی ہے جبکہ کفار کے متعلق حکم ہے انہیں اپنا دوست مت بناؤ۔ لا تَتَّخِذُوا عَدُوّى وَعَدُوِّكُمْ أَوْلِيَاءَ﴾ (الممتحنه: ١)","",{"k":"سنن ابو داؤد، على اهل الذمة (٥٢٠٥)، سنن ترمذی (١٦٠٢)، الادب المفرد (١١٠٣)، قال الشيخ للالبانی: صحیح۔"}],[706,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ من علم نے فرمایا: \"اگر کوئی شخص کسی آگ کے انگارے پر بیٹھ جائے جو اس کے کپڑے کو جلا کر اس کے جسم تک پہنچ جائے تو یہ کسی قبر پر بیٹھنے سے بہتر ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ قبر پر بیٹھنا حرام ہے، جیسا کہ سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قبر پر بیٹھنے سے منع فرمایا ہے۔ (صحیح مسلم، کتاب الجنائز، رقم: ٩٧٠) امت کے جمہور کا اس بات پر اتفاق ہے کہ قبر پر بیٹھنا حرام ہے۔ (نیل الاوطار: ٣٤/٣)","",{"k":"صحیح مسلم۔"}],[707,"اسی سند سے ہے سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کسی میت پر نماز جنازہ پڑھی تو اس کے لیے ایک قیراط ثواب ہے، اور جس نے نماز جنازہ بھی پڑھی اور دفن کرنے تک اس کے پیچھے چلتا رہا تو اس کے لیے دو قیراط ثواب ہے۔ ابو ہریرہ رضی اللہ عنہ سے کہا گیا کہ دو قیراط کتنے ہیں؟ تو انہوں نے کہا: دونوں میں سے چھوٹا قیراط اُحد پہاڑ کے برابر ہے۔“ مذکورہ حدیث میں جنازہ پڑھنے اور میت کے ساتھ جانے کی فضیلت کا بیان ہے کہ میت کے ساتھ چلنے، جنازہ پڑھنے اور دفن میں شریک ہونے سے آدمی کو دواحد پہاڑ کے برابر ثواب ملتا ہے","",{"k":"صحیح مسلم (٩٤٥)، سنن ابو داؤد (٣١٦٨)، سنن ترمذی (١٠٤٠)۔"}],[708,"سیدنا ابو ہریرہ فی الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” آدمی جب اپنی پاک کمائی سے کسی پھل کا صدقہ دے اور وہ اس کے صحیح حق دار کے ہاتھ میں پہنچے تو اللہ تعالیٰ اس کو اپنے دائیں ہاتھ میں لے کر اس کو اس خوبی سے اچھی طرح پالتا ہے جس طرح تم میں سے کوئی شخص اپنے بچھڑے کو پالتا ہے یہاں تک کہ وہ پہاڑ کے برابر یا اس سے زیادہ ہو جاتا ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ جو حلال کمائی سے اللہ کی راستے میں خرچ کرتا ہے اس کو اللہ تعالیٰ بڑھا چڑھا کر پہاڑ کے برابر یا زیادہ کر دیتا ہے جیسا کہ ارشاد باری تعالیٰ ہے: مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُصْعِفَهُ لَهُ أَضْعَافًا كَثِيرَةٌ﴾ (البقرة: ٢٤٥) جو کوئی اللہ تعالیٰ کو اچھا قرض دیتا ہے تو اللہ تعالیٰ اسے بہت بڑھا چڑھا کر عطا فرماتا ہے۔“ مذکورہ حدیث سے ایک تو صدقہ کی فضلیت، اور دوسرا اللہ ذوالجلال کے ہاتھ کا بھی اثبات ہوتا ہے۔ یہ بھی معلوم ہوا کہ حرام آمدنی سے کئے گئے صدقہ کی اللہ کے ہاں کوئی اہمیت نہیں","",{"k":"ورس صحیح بخاری (٧٤٣٠)، صحیح مسلم (١٠١٤)، سنن ترمذی (٦٦١)۔"}],[709,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” (وضو میں خشک چھوڑی گئی ایڑیوں) کے لیے ”ویل“ (جہنم) ہے۔“ ایک دوسری حدیث میں ہے کہ نبی معظم ملٹے علیم نے ایک آدمی کو دیکھا، اس کے پاؤں میں ناخن کے برابر جگہ ایسی تھی جسے ( دوران وضو) پانی نہیں پہنچا تھا۔ تو نبی معظم نے یم نے فرمایا: ((ارجع فاحسن وصوئك)) واپس جاؤ اور اچھے طریقے سے وضو کرو۔ (سنن ابی داؤد، کتاب الطهارة، رقم: ١٧٣، سنن ابن ماجه رقم: ٦٦٥، قال الشيخ الالباني: صحيح) اس سے معلوم ہوا ہے کہ تمام اعضائے وضو کو مکمل طور پر دھونا واجب ہے اور اگر کسی ایک عضو کا کچھ حصہ بھی خشک رہ گیا تو وضو مکمل نہیں ہو گا۔ جمہور اہل علم اسی کے قائل ہیں۔ علاوہ ازیں یہ بھی ثابت ہوا کہ وضو میں پے در پے اعضا دھونا واجب ہے۔ اگر ایسا نہ ہوتا تو (جیسا کہ دوسری حدیث میں ہے دوبارہ وضو کا حکم دیا) نبی مکرم ملٹے علیم اسےصرف پاؤں دھونے کا ہی حکم فرما دیتے۔","",{"k":"صحیح بخاری (١٦٥)، صحیح مسلم (٢٤٠)۔"}],[710,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ”اللہ دنیا میں کسی مسلمان بندے کے عیبوں پر پردہ ڈالے تو اللہ تعالیٰ قیامت کے دن اس کے عیوب پر پردہ ڈالے گا۔“","",{"k":"سنن ترمذی، رقم : ١٩٣٠ قال الشيخ الالبانی، صحیح۔"}],[711,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اپنے ہاتھ کندھوں کے برابر اٹھاتے۔“ یہ حدیث اسماعیل بن امیہ سے صرف مسلم بن خالد ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٧٣٥)۔"}],[712,"سيده السوداء بنی النیہا نے بیان ہے، میں رسول اللہ صلی اللہ علیہ وسلم کی بیعت کرنے کے لیے حاضر ہوئی تو آپ نے فرمایا: ”جاؤ ہاتھوں کو رنگ کرو اور پھر بیعت کے لیے آؤ تا کہ میں تمہاری بیعت کروں۔“ یہ حدیث حضرت سوداء سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں نائلہ اکیلی ہیں۔","",{"k":"مجمع الزوائد (٥/١٧٢)، سنن ابو داؤد (٤١٦٥)، سنده ضعيف۔","f":"مذکورہ روایت کمزور ہے تاہم عورتوں کے لیے مہندی لگانا جائز ہے بشرطیکہ غیر مردوں کے لیے نہ ہو۔"}],[713,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا کہ وہ اپنی اکٹھی دوانگلیوں سے دعا (خطبہ کے دوران اشارہ ) کر رہا تھا تو آپ نے اس کو منع کیا اور فرمایا: ” ایک انگلی سے دعا کرو دائیں (انگلی) سے۔“ یہ حدیث ہشام سے صرف حفص ہی روایت کرتے ہیں۔ مسنون عمل ہے۔ معلوم ہوا حالت تشہد میں دائیں ہاتھ کی صرف شہادت والی انگلی سے ہی اشارہ کرنا","",{"k":"المعجم الكبير للطبرانی (١٩/١٣٢)، مسند ابی یعلی (٦٠٣٣)، صحيح ابن حبان (٨٨٤)۔"}],[714,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ انہوں نے کہا: کیا میں تمہیں نہ دکھاؤں کہ نبی صلی اللہ علیہ وسلم کا وضوء کس طرح تھا؟ پس انہوں نے اپنے ہاتھ سے پانی لیا پھر کلی کی اور ناک میں پانی ڈالا، اور پھر ہاتھ سے پانی لے کر دوسرے ہاتھ کو بھی اس کے ساتھ ملایا، پھر اپنے چہرے کو دھویا پھر اپنے ہاتھ سے پانی لیا تو اس سے اپنا ہاتھ اور باز و دھوئے، پھر دوسرے کے ساتھ بھی اسی طرح کیا۔ پھر اپنے سر کا مسح کیا پھر اپنے ہاتھ سے پانی لے کر اس کو اپنے قدموں پر چھڑ کا، پھر اپنے دونوں پاؤں کا مسح کیا جبکہ آپ (پاؤں) پر جوتے پہنے ہوئے تھے۔“ مذکورہ حدیث میں وضو کا طریقہ مذکور ہے، حدیث میں مذکور پاؤں پر مسح کے الفاظ شاذ ہیں جیسا کہ شیخ البانی اللہ نے کہا ہے۔ البتہ صحیح اور راجح بات پاؤں کو دھونا ہی ہے جیسا کہ متعدد صحیح مرفوع اور موقوف احادیث سے ثابت ہے۔","",{"k":"سنن ابو داؤد (١٣٧)، قال حسن لكن مسح القدمين شاذ۔"}],[715,"معاذ بن ابی حواء کی دادی حواء کہتی ہیں کہ رسول اللہ میم نے فرمایا: ”اے مسلمان خواتین! تم میں سے کوئی بھی خاتون اپنی ہم سایہ عورت کے لیے کوئی چیز بھی حقیر نہ سمجھے خواہ وہ جلا ہوا کھر ہی کیوں نہ ہو۔“","",{"k":"صحیح بخاری (٦٠١٧)، صحیح مسلم (١٠٣٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ آپس میں ہدیہ لینے دینے کا رواج رہنا چاہیے جو کچھ تھوڑا بہت بن پڑے دے دیا کریں دینے والی یہ نہ سوچے کہ یہ ذراسی چیز کیا دوں اور نہ ہی لینے والی یہ خیال کرے کہ اس نے ذراسی چیز بھیج دی۔ مذکورہ حدیث میں خاص پڑوسیوں کا ذکر ہے جس سے معلوم ہوتا ہے کہ پڑوسیوں کو چاہیے کہ وہ کچھ نہ کچھ ایک دوسرے کو ہدیہ دیتے رہیں۔ تاکہ ان کی باہمی محبت ومودت برقرار رہے۔ ١٦"}],[716,"سيدنا عبد الرحمن بن بجید نے اپنی دادی کے حوالے سے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”سائل خالی ہاتھ نہ موڑ وخواہ وہ جلا ہوا کھر ہی ہو۔“","",{"k":"السنن الكبرى للبيهقي (٤/١٧٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جو اللہ کے نام پر سوال کرتا ہے اس کو خالی واپس نہ موڑا جائے کچھ نہ کچھ دینا چاہیے۔ جیسا کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ علیم نے فرمایا: ”جو شخص تم سے اللہ کے ( نام کے ) ساتھ سوال کرے اسے دو۔ حلية الاوليا: ٥٦/٩ - بيهقى: ١٩٩/٤ - اسنادہ صحیح) اگر بالکل کچھ بھی نہ ہو تو اچھی بات کہہ دینا بھی صدقہ ہے جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((الكلمة الطيبة صدقة)) ”پاکیزہ کلمہ بھی صدقہ ہے۔“ (صحیح مسلم، کتاب الزكاة، باب بيان اسم الصدقة الخ) لیکن کچھ دے کر تکلیف پہنچانا یہ بہت بڑا جرم ہے۔ جیسا کہ ارشاد باری تعالیٰ ہے: قَوْلُ مَّعْرُوفٌ وَ مَغْفِرَةً خَيْرٌ مِّنْ صَدَقَةٍ يَتْبَعُهَا أَذًى﴾ (البقرة: ٢٦٣) نرم بات کہنا اور معاف کر دینا اس صدقہ سے بہتر ہے جس کے بعد ایذا رسانی ہو۔“"}],[717,"سیدنا رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ سیدنا علی رضی اللہ عنہ نے سیدنا عمار رضی اللہ عنہ سے کہا کہ وہ نبی صلی اللہ علیہ وسلم سے مندی کے متعلق سوال کریں؟ آپ نے فرمایا: ” وہ اپنی شرم گاہ دھو لے اور وضو کرے۔“ مدی: اس سفید لیس دار پانی کو کہتے ہیں جو مباشرت کے خیال یا ملاعبت کے وقت نکلتا ہے اور بسا اوقات اس کے نکلنے کا انسان کو پتا بھی نہیں چلتا۔ مرد اور عورت دونوں سے مذی خارج ہوتی ہے البتہ عورت سے زیادہ خارج ہوتی ہے۔ علماء کا اتفاق ہے کہ ندی بھی ناپاک ہے جسم کو لگ جائے تو دھونا فرض ہے،ہاں البتہ اگر کپڑے کو لگ جائے تو پانی کے چھینٹے مارنا ہی کافی ہے کیونکہ اس سے بچنا مشکل ہے۔ مذکورہ روایت سے معلوم ہوا کہ کہ مذی پر غسل نہیں بلکہ وضو ہے۔ دوسرا کپڑے کو لگ جائے تو نبی معظم ملنے یام نے فرمایا: ”اتنا ہی کافی ہے کہ پانی کا ایک چلو لے کر اپنے کپڑے پر اس جگہ بہا دو جہاں تم مذی کو لگا ہوا دیکھتے ہو۔ (صحیح سنن ابی داؤد، رقم: ١٩٠، مسند احمد: ٤٨٥/٣)","",{"k":"صحیح مسلم۔"}],[718,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، ہم نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا ہم جنت میں بھی عورتوں کے پاس جائیں گے؟ آپ نے فرمایا: اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے! ضرور جاؤ گے یقیناً ایک آدمی ایک صبح کو سو عورتوں کے پاس جا سکے گا۔ یہ حدیث ہشام سے زائدہ ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (١٠/٤١٧)، مسند ابی یعلی (٢٤٣٦)۔"}],[719,"سيدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ج گواہی مقرر کی جائے تو تم میں سے کسی کے لیے مضر نہیں کہ اس نے تھوڑا مال خرچ کر کے شادی کی ہے یا زیادہ مال خرچ کر کے شادی کی ہے۔ یہ حدیث برد سے صرف اسماعیل بن عیاش ہی روایت کرتے ہیں۔","",{"k":"سنن دار قطنی ٣ ٣٤٣ (٣١٣٩)۔"}],[720,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں حوض پر تمہارا پیش رو ہوں گا اس حوض کے دونوں کناروں کی اتنی دوری ہوگی جتنی صنعا سے ایلہ تک ہے، اور اس کے آب خورے ستاروں کی تعداد میں ہوں گے۔ یہ حدیث زیادہ بن خیثمہ سے صرف شجاع بن الولید ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نبی معظم صلی اللہ علیہ وسلم کو اللہ ذوالجلال حوض عطا فرمائے گا۔ حدیث میں آتا ہے کہ اس کا پانی دودھ سے زیادہ سفید اور شہد سے میٹھا ہے۔ (صحیح مسلم، کتاب الفضائل، رقم: ٢٣٠٠) مذکورہ بالا حدیث میں حوض کوثر کا نقشہ بیان ہوا ہے کہ اس کے دونوں کناروں کے درمیان اتنا فاصلہ ہے جتنا ایلہ اور صنعا کے درمیان سفر ہے۔ ایک روایت میں ہے کہ میرے حوض کی لمبائی اور چوڑائی ایک مہینہ کی مسافت ہے۔ (صحیح بخاری، رقم: ٦٥٧٩) ایک حدیث میں ہے کہ جتنا جرباء اور اذ رحاء کے درمیان فاصلہ ہے۔ (صحیح بخاری، کتاب الرقاق، رقم: ٦٥٧٧) ایک حدیث میں ہے کہ جتنا ایلہ اور یمن کے شہر صنعا کے درمیان فاصلہ ہے۔ (صحیح بخاری، کتاب الرقاق، رقم: ٦٥٨٠) یہ سب آپ صلی اللہ علیہ وسلم نے تقریباً لوگوں کو سمجھانے کے لیے فرمایا جو جو مقام وہ پہچانتے تھے وہ بیان فرمائے۔ ممکن ہے کسی روایت میں طول کا بیان ہو اور کسی میں عرض کا۔ (واللہ اعلم ) ·:٧٢١ مذکورہ روایت سے یہ بھی معلوم ہوا کہ حوض کے برتن آسمانی ستاروں جتنے ہوں گئے","",{"k":"صحیح مسلم، مسند ابی یعلی، رقم : ٧٤٤٣ . وصفاته۔"}],[721,"سیدنا علی رضی اللہ عنہ علیہ وسلم نے فرمایا: ”ہر دعا اللہ تعالیٰ سے پردے میں ہے یہاں تک کہ رسول اللہ تعلیم اور آپ کی آل پر درود پڑھا جائے۔ یہ حدیث ابو اسحاق سے صرف عبدالکریم الخراز ہی روایت کرتے ہیں۔ فائد مذکورہ حدیث سے درود پاک کی اہمیت وفضیلت معلوم ہوتی ہے کہ جس دعا سے قبل درود نہ پڑھا جائے وہ دعا قبول نہیں کی جاتی۔ اہل حدیث کا یہ عقیدہ ہے کہ جس نماز اور دعا میں درود نہیں اللہ وہ دعا اور نماز قبول نہیں فرماتے۔","",{"k":"السلسلة الصحيحة ٣٤/٥ (٢٠٣٥)، صحيح الجامع الصغير (٤٥٢٣)۔"}],[722,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس چیز کو آگ نے بدل دیا ہو۔ ( جو چیز آگ پر تیار ہو اسے کھا کر وضو کرو۔ یہ حدیث ایوب سے صرف عبد العزیز بن حسن بن ابی جعفر ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد (١٩٥)، قال الشيخ الالباني، صحيح۔"}],[723,"سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ارادہ فرمایا کہ آپ ایک مرد کی ایک عورت سے شادی کر دیں تو آپ نے فرمایا: ”اے فلاں عورت! کیا تو پسند کرتی ہے کہ میں تمہاری فلاں شخص کے ساتھ شادی کر دوں؟“ اور فرمایا: ”اے فلاں شخص کیا تو پسند کرتا ہے کہ میں فلاں عورت کے ساتھ تیری شادی کر دوں؟“","",{"k":"سنن ابو داؤد، مسند احمد (٦/٢١٠)، قال الشيخ شعيب الارناؤط : صحیح۔","f":"ابو داؤد میں مفصل حدیث ہے کہ ان دونوں کی شادی ہوگئی لیکن حق مہر مقرر نہیں تھا اور نہ کچھ اس نے عورت کو دیا اور یہ صحابی ان لوگوں میں سے ہے جو حدیبیہ میں شریک ہو چکے تھے اور شرکائے حدیبیہ کو خیبر میں حصہ ملا تھا۔ جب اس کی وفات کا وقت آیا تو اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فلاں عورت سے میری شادی کر دی تھی مگر میں نے اس کے لیے مہر مقرر نہیں کیا تھا۔ اور نہ اسے کچھ دیا تھا۔ اور میں تمہیں (یعنی سیدنا عقبہ بن عامر فضل اللہ کو کہا جو اس حدیث کے راوی ہیں گواہ بناتا ہوں کہ میں اسے مہر میں اپنا خیبر کا حصہ دیتا ہوں۔ چنانچہ اس عورت نے وہ حصہ لیا اور پھر اسے ایک لاکھ میں فروخت کر دیا۔ (سنن ابی داؤد، رقم: ٢١١٧) مذکورہ روایت سے معلوم ہوا کہ حق مہر مقرر نہیں تھا تاہم اگر حق مہر مقرر نہ ہو تو پھر اس عورت کو اتنا مہر دینا چاہیے جو عورت کے خاندان میں عام رائج ہے۔ اسی طرح ایک اور روایت میں ہے سیدنا عبد اللہ بن مسعود ضیا اللہ سے سوال پوچھا گیا کہ اگر حق مہر نہ ہو اور آدمی ہم بستری سے قبل ہی فوت ہو جائے؟ سیدنا عبد اللہ فی اللہ نے جواب میں فرمایا: اس عورت کو اس خاندان کی عورتوں کے مثل مہر ملے گا اس میں کمی ہوگی نہ زیادتی۔ اس عورت پر عدت گزارنا بھی لازم ہے اور اس کے لیے میراث بھی ہے۔ یہ سن کر (اس مجلس میں موجود ) سیدنا معقل بن سنان ولی الیہ کھڑے ہوئے، اور کہا ہماری ایک عورت بروع بنت واشق بینی و جیا کے بارے میں نبی صلی اللہ علیہ وسلم نے وہی فیصلہ فرمایا تھا جو آپ نبی الیہ نے کیا ہے۔ تو سیدنا عبد اللہ بن مسعود رضی اللہ عنہ خوش ہوئے۔ (صحیح سنن ابی داؤد، رقم: ١٨٥٨) معلوم ہوا کہ جس عورت کا مہر مقرر نہ کیا گیا ہو اسے (خاوند کی وفات پر ) مہر مثل دیا جائے گا خواہ اس سے مباشرت و ہم بستری کی گئی ہو یا نہ کی گئی ہو۔ امام احمد، ابو حنیفہ ہم اسی کے قائل ہیں۔ امام ابن سیرین، ابن ابی لیلی، اسحاق عبداللہ بھی یہی موقف رکھتے ہیں۔ امام مالک رحمہ اللہ فرماتے ہیں ایسی عورت جس سے ہم بستری نہیں کی گئی صرف میراث کی مستحق ہے مہر کی نہیں کیونکہ مہر ولی ومباشرت کا عوض ہے ایک روایت کے مطابق امام شافعی جاللہ کا بھی یہی موقف ہے۔ (نيل الاوطار: ٢٥٦/٤) پہلا موقف راجح ہے کیونکہ وہ گذشتہ احادیث کے موافق ہے۔"}],[724,"سیدنا عقبہ بن عامر في الله بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” بہترین نکاح وہ ہے جو نہایت آسان ہو۔“ یہ دونوں حدیثیں یزید بن ابی حبیب سے صرف محمد بن اسحاق ہی روایت کرتے ہیں، ان سے روایت کرنے میں محمد بن سلمہ اکیلے ہیں، عقبہ بن عامر سے یہ حدیث اسی سند سے مروی ہے۔ مذکورہ حدیث سے معلوم ہوا کہ جس نکاح میں محنت کم ہو، مشقت نہیں آسانی ہو تو وہ بہترین ہے اس میں برکت بھی ہے۔ لیکن جس نکاح میں مشکل میں پڑ کر فضول خرچی شریعت سے ہٹ کر کیا جائے اس نکاح میں برکت نہیں ہوتی بلکہ اس کے نتائج غلط ہی نکلتے ہیں۔","",{"k":"سنن ابو داؤد (١١٧)، السلسلة الصحيحة (٣٤١/٤)، رقم : ١٨٤٢ . فائدة۔"}],[725,"سیدنا ابو ہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: جو شخص ہر نماز کے بعد ((الله اکبر)) تینتیس بار (سبحان الله) تینتیس بار، ((الحمد لله)) تینتیس بار اور سو کی تعداد پوری کرنے کے لیے ایک دفعہ ( لا اله الا الله وحده لا شريك له، له الملك وله ((لا الحمد وهو على كل شئى قدیر )) پڑھے تو اس کے سارے گناہ معاف ہو جاتے ہیں خواہ وہ سمندر کی جھاگ کے برابر ہی کیوں نہ ہوں۔“ (١) مذکورہ حدیث سے معلوم ہوا کہ نماز کے بعد اللہ کا ذکر کرنا مسنون ہے۔ یہ بھی معلوم ہوا کہ اذکار سے اللہ ذوالجلال گناہوں کو معاف کر دیتا ہے۔ (٢) ایک روایت میں ہے کہ سو کا عدد پورا کرنے کے لیے چونتیس (٣٤) مرتبہ اللہ اکبر کہے۔ (صحیح مسلم، رقم: ٥٩٦) (٣) اس سے مراد صغیرہ گناہوں کی معافی ہے کیونکہ کبیرہ گناہ کی بخشش تو بہ کے بغیر ممکن نہیں۔","",{"k":"سنن ابو داؤد (١٥٠٤)، قال الشيخ الالباني، صحیح۔"}],[726,"سیدنا جابر نبی اللہ سے روایت ہے کہ میرے باپ کے ذمہ کئی وسق کھجور میں قرض تھیں۔ ہم نے ایک آدمی سے کہا: تم ہماری کھجوروں کا تمام پھل لے لو مگر اس نے انکار کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، ان کے ساتھ سیدنا عمر ضیا اللہ بھی تھے۔ آپ نے ہمارے لیے برکت کی دعا کی تو ہم نے کھجوروں کا پھل کاٹا اور ہر آدمی کو جو کچھ ان کا قرض تھا انہیں ادا کر دیا اور ہماری کھجوروں کا اندازہ اسی طرح موجود رہا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور ان کو بتایا تو آپ نے فرمایا: \"عمر کو بھی بتاؤ میں نے انہیں بھی بتایا تو وہ کہنے لگا: یا رسول اللہ ملتے ییم! مجھے معلوم تھا کہ جب آپ نے اس میں برکت کی دعا کی تو ضرور اس میں برکت ڈالی جائے گی۔“ (١) یہ نبی معظم ملنے سے ان کا معجزہ تھا۔ (٢) عرب لوگ کھجور کا پھل جو درخت پر ہوتا اس کا اس طرح اندازہ لگا لیتے جب تو ڑ کرنا پتے تو تقریباً اتنا ہی نکلتا سیر دو کا فرق ہی آتا۔ (٣) یہ آدمی یہودی تھا اس کا نام ابو شہم تھا اس کا قرض تمہیں (٣٠) وسق تھا۔ (صحیح بخاری، رقم: ٢٣٩٦) یہودی نے اندازہ لگایا تو کھجوریں تمہیں وسق سے کم تھیں پہلے زیادہ ہوتیں تو یہودی خوشی سے قبول کر لیتا لیکن کم ہونے کی وجہ سے اس نے انکار کر دیا۔ نبی مکرم ملنے علم کے چکر لگانے اور دعا کی برکت سے بخاری شریف میں ہے کہ سترہ (١٧) وسق اس سے بچ گئے تھے۔ (صحیح بخاری، رقم: ٢٣٩٦) وسق کی تفصیل کچھ یوں ہے ایک وسق ساٹھ صاع کا اور ایک صاع تقریباً اڑھائی کلو کا ہوتا ہے، اس حساب سے تقریباً س من اور ٣٠ کلو ہوا اور ٣٠ وسق کا وزن تقریباً ١٢ امن اور ٢٠ کلو ہوا۔ (واللہ اعلم) ٧٢٧","",{"k":"قوى . مسند احمد (٣/٤١٧، ١٥٤٨٧)، قال الشيخ شعیب الارناؤط اسناده۔"}],[727,"سیدہ ام ہانی نہی الجھا نے بتایا کہ نبی سے علی فتح مکہ کے دن اُن کے پاس تشریف لائے تو آپ نے چاشت کی نماز چار رکعت ادا کی۔“ تا ہم مذکورہ حدیث سے صلاۃ الضحی کی چار رکعتیں ثابت ہوتی ہیں۔ اس کی کم از کم رکعتیں دو (٢) ہیں۔ (دیکھئے بخاری، رقم: ١٩٨١) زیادہ سے زیادہ آٹھ رکعتیں ہیں۔ (صحیح بخاری، رقم: ٣٥٧)","",{"k":"مجمع الزوائد (٢/٢٣٨)، المعجم الكبير للطبراني (٢٤/٣٤٢)۔"}],[728,"سیدہ ام ہانی بنی این جا نے بیان کیا، ” آپ ملے عام نے ایک کندھے کا گوشت کھایا اور وضو نہیں کیا۔“ مذکورہ حدیث سے معلوم ہوا کہ آگ پر پکی ہوئی چیز کھا کر وضو نہیں ٹوٹتا جن احادیث میں ہے کہ وضو کرنا چاہیے وہ تمام احادیث منسوخ ہو چکی ہیں۔ جیسا کہ سیدنا جابر فی الیہ بیان کرتے ہیں کہ آگ سے پکی ہوئی چیز کھانے سے وضو ترک کر دینا ہی رسول اللہ صلی اللہ علیہ وسلم کے دونوں معاملات میں سے آخری تھا۔ (صحیح سنن ابی داؤد، رقم: ١٧٧، شرح مسلم للنووي: ٢٧٩/٢) ٥/٥","",{"k":"صحیح بخاری (٢٠٧)، صحیح مسلم۔"}],[729,"سيدنا ابو رافع رضی اللہ عنہ سے روایت ہے کہ ”نبی صلی اللہ علیہ وسلم نے بکری کے گوشت سے کچھ کھایا پھر وضو نہیں کیا۔“ ٣٠","",{"k":"صحیح بخاری (٢٠٨)۔"}],[730,"سیدنا جابر بن عبد اللہ ضیا المیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کچھ لوگ جہنم سے نکالے جائیں گے۔“","",{"k":"صحیح مسلم، مسند حمیدی (١٢٤٥)۔","f":"(١) مذکورہ حدیث سے معلوم ہوا کہ کچھ لوگ ابتدا میں جنت سے محروم ہو جائیں گے، اور کچھ مدت کے لیے جہنم میں جائیں گے پھر نکال کر جنت میں داخل کیے جائیں گے۔\n(٢) مذکورہ حدیث سے خارجیوں کا بھی رد ہوتا ہے جو کہتے ہیں کہ جو جہنم میں چلا گیا وہ وہاں سے نہیں نکل سکتا۔\n(٣) یہ وہ اہل ایمان ہوں گے جن کی برائیاں نیکیوں سے بڑھ جائیں گی وہ اپنی خطاؤں کی سزا پا کر بالآخر ہمیشہ ہمیشہ کے لیے جنت کے حقدار ٹھہریں گے۔"}],[731,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سفر میں روزہ رکھنا نیکی نہیں ہے۔“ یہ حدیث ابن جریج سے صرف سعید بن یزید ہی روایت کرتے ہیں، اسے روایت کرنے میں سفیان بن زیادا کیلئے ہیں۔","",{"k":"صحيح بخاری (١٩٥٤)، سنن ابو داؤد (/٢٤٠٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سفر میں روزہ رکھنا درست نہیں ہے۔ تاہم دوسری روایات سے ثابت ہے کہ نبی مکرم نے علیم اور صحابہ کرام رضوان اللہ علیہم اجمعین سفر میں روزہ رکھتے بھی تھے اور ترک بھی کرتے تھے۔ جیسا کہ سیدنا ابو درداء رضی اللہ عنہ سے مروی ہے کہ وہ ماہ رمضان کے ایک سخت گرم دن میں نبی صلی اللہ علیہ وسلم کے ساتھ سفر میں تھے، اور اس سفر میں نبی صلی اللہ علیہ وسلم اور سیدنا عبد اللہ بن رواحہ رضی اللہ عنہ سے تھے۔ (صحیح بخاری، رقم: ١٩٥٤، سنن ابی داؤد، رقم: امام شوکانی اللہ نے بھی فرمایا ہے کہ جس پر روزہ رکھنا مشکل ہو یا جسے (سفر میں ) روزہ نقصان دیتا ہو یا رخصت قبول کرنے سے اعراض کرتا ہو یا جسے دوران سفر روزہ رکھنے سے فخر و ریا کاری میں مبتلا ہونے کا اندیشہ ہو تو ایسے شخص پر روزہ چھوڑ دینا افضل ہے اور جو ان اشیاء سے مستغنی ہو اس کے حق میں روزہ رکھنا افضل ہے۔ (نیل الاوطار؛٢٠١/٣) ١٣٢"}],[732,"سیدنا ابو ہریرہ ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہر چیز کی نسبت ہے اور اللہ تعالیٰ کی نسبت قُلْ هُوَ اللهُ اَحَدٌ ہے۔ یہ حدیث حضرت ابو ہریرہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عبدالرحمن بن نافع اکیلے ہیں۔ ٧٣","",{"k":"ضعيف الجامع الصغير (١٩٣٧)، السلسلة الضعيفة (٣١٩٢)۔"}],[733,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری قبر اور میرے منبر کے درمیان جنت کے باغوں میں سے ایک باغ ہے اور میرا منبر میرے حوض پر ہوگا۔“ یہ حدیث ابن خیم سے صرف بیٹی بن سلیم ہی روایت کرتے ہیں، اسے روایت کرنے میں ابوحصین اکیلے ہیں۔ ٧٣٤","",{"k":"صحیح بخاری۔"}],[734,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن کو گالی دینا گناہ ہے اور اس سے لڑائی کرنا کفر ہے۔ یہ حدیث صالح سے صرف میمون ہی روایت کرتے ہیں، اسے روایت کرنے میں کثیر بن یحیی اکیلے ہیں۔","",{"k":"٨٠٨٠/ صحیح بخاری (٤٨١)، صحيح مسلم (٦٤)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسلمان کو گالی دینے والا فاسق ہے چونکہ اسلام میں گالی دینا ممنوع ہے اس لیے مسلمان کو گالی دینے والے کو فاسق یعنی نا فرمان کہا گیا ہے۔ فستق کا معنی لغت میں نکلنا ہے اور شرع میں اللہ اور اس کے رسول ملے علم کے حکم سے نکلنا مراد ہے اور ہر عمل انتہائی ناپسندیدہ ہے، ارشاد باری تعالیٰ ہے: ﴿وَكَرَّةَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ) (الحجرات: ٤ ) اور اس نے کفر، فسوق اور عصیان کو تمہارے لیے ناپسند بنا دیا۔“ اگر کوئی شخص مسلمان سے قتال کو حلال سمجھے تو بالا تفاق کافر اور دائرہ اسلام سے خارج ہے اگر حلال نہ سمجھے تو پھر کافر نہیں۔ قرآن وحدیث میں کفر دو معنوں میں استعمال ہوا ہے ایک وہ کفر ہے جس سے مراد خروج عن الاسلام ہے اور جس کا مرتکب اسلام سے خارج اور ابدی جہنمی ہے یہ بڑا کفر ہے یعنی اللہ اور اس کے رسول صلے علیکم کی کوئی بات ماننے سے انکار کر دینا کفر کی دوسری قسم کو امام بخاری ہمالہ اور دوسرے ائمہ نے \"كُفْرٌ دُونَ كُفْرِ بڑے کفر سے کم تر کفر قرار دیا ہے۔ یعنی اسلام میں رہ کر کفر کے کسی کام کا ارتکاب کرنا۔ اس کفر کے ارتکاب سے آدمی ایمان سے خارج نہیں ہوتا۔"}],[735,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہ ابن آدم ہے اور اپنے ہاتھ اپنی تھوڑی کے نیچے رکھا پھر ہاتھ پھیلا کر فرمایا: ” یہ اس کی آرزو ہے۔“ یہ حدیث سفیان سے صرف مصعب بن ماھان ہی روایت کرتے ہیں اور مصعب سے صرف عمرو بن ابی سلمہ ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن عیسی اکیلے ہیں۔","",{"k":"صحیح بخاری (٦٤١٨)، سنن ترمذی (٣٣٤)، سنن ابن ماجه (٣٣٢)۔","f":"مذکورہ روایت سے معلوم ہوا کہ انسان کی آرزو دن بدن بڑھتی جاتی ہیں۔ لفظ امل سے آرزو وغنا مراد ہے۔ یعنی خواہشات نفسانی پوری ہونے کی امید رکھنا۔ مثلاً آدمی یہ خیال کرے کہ ابھی بہت عمر پڑی ہے جلدی کیا ہے۔ آخر عمر میں تو بہ کر لیں گے۔ ایسی ہی غلط آرزو کو اہل کہتے ہیں۔ بڑھاپے میں ایسی آرزو کی رسی بہت دراز ہوتی جاتی ہے مگر دفعتاً موت آکر دبوچ لیتی ہے۔"}],[736,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے ہیم نے فرمایا: ”لوگوں پر ایسا وقت آئے گا کہ وہ بھیڑیئے ہو جائیں گے اور جو شخص بھیڑ یا نہ ہوگا تو اس کو بھیڑیئے کھا جائیں گے۔“ یہ حدیث زیاد الجصاص سے صرف سہل بن سعید ہی روایت کرتے ہیں، اسے روایت کرنے میں اسحاق بن وہب اکیلے ہیں۔","",{"k":"مجمع الزوائد (٨٩/٨)۔"}],[737,"سیدنا عبداللہ ابن عباس علی الجھا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کے مال یا جان کو مصیبت پہنچی تو اس نے اس کو چھپا رکھا، اور کسی شخص کے سامنے شکوہ و شکایت نہ کی۔ تو اللہ تعالیٰ پر حق ہو جاتا ہے کہ وہ اسے معاف کر دے۔“","",{"k":"مجمع الزوائد (٢٥٦/١٠)، السلسلة الضعيفة (١٩٨)، قال الشيخ الالبانی، موضوع۔"}],[738,"سیدنا عبد اللہ ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جب اللہ تعالیٰ نے جنت عدن پیدا فرمائی تو اس میں وہ چیزیں بھی پیدا کیں جو کسی آنکھ نے دیکھی ہیں، نہ کسی کان نے سنی ہیں اور نہ ہی کسی انسان کے دل میں ان کا خیال آیا ہے پھر اسے فرمایا کچھ کلام کر تو اس نے کہا: قد افلح الْمُؤْمِنُونَ ”بے شک کامیاب ہو گئے مومن۔ یہ دونوں حدیثیں ابن جریج سے صرف بقیہ ہی روایت کرتے ہیں ان دونوں کو روایت کرنے میں ہشام بن خالدا کیلے ہیں۔ مذکورہ حدیث میں جنت عدن کا ذکر ہے یہ جنت کا ایک نام ہے۔ اور صحیح یہ ہے کہ یہ تمام جنتوں کا مجموعی نام ہے اور سب جنتیں جنات عدن ہیں اللہ تعالیٰ کا ارشاد ہے: جَنَّتِ عَدْنِ نِ الَّتِي وَعَدَ الرَّحْمَنُ عِبَادَةَ بِالْغَيْبِ﴾ (مريم: ٦١) ان جنات عدن میں جن کا رحمان نے اپنے بندوں سے غائبانہ وعدہ فرمایا ہے۔“ وہ اس کے وعدہ کی چیز کو ضرور پہنچیں گے اور ارشاد ہے: وَمَسَاكِنَ طَيِّبَةٌ فِي جَنَّتِ عَدْنٍ ﴾ (الصف: ١٢) جنتی جنات عدن ( ہمیشہ کی جنتوں ) میں پاکیزہ گھروں میں رہیں گے۔“ سیدنا عبد الملک بن حبیب قرطبی جماللہ فرماتے ہیں کہ دار السلام اور دارالجلال اللہ عزوجل کی طرف منسوب ہیں لیکن جنت عدن جنت کا درمیانی اور بلند حصہ ہے اور تمام جنتوں سے اونچی ہے۔ (صفة الجنة ابو نعیم: ٩) اللہ ذوالجلال نے نعمتیں چھپا کر رکھی ہیں۔","",{"k":"صحیح بخاری (٣٢٥٤)۔"}],[739,"سیدنا براء بن عازب رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بے شک اللہ تعالیٰ اور اس کے فرشتے پہلی صف کے لیے دعا کرتے ہیں اور آپ نماز کو تشریف لاتے تو ہمارے کندھوں اور سینوں پر ہاتھ پھیرتے اور فرماتے اختلاف نہ کرو ( صف میں آگے پیچھے نہ ہوں) ورنہ تمہارے دل مختلف ہو جائیں گے۔ یہ حدیث از منصور از حکم صرف ابراہیم بن طہمان ہی روایت کرتے ہیں اور سفیان از ثوری از منصور، طلحہ سے روایت کرتے ہیں۔","",{"k":"سنن ابن ماجه (٩٩٧)، سنن ابو داؤد (١٦٤)، قال الشيخ الالباني : صحیح۔","f":"مذکورہ حدیث سے، پہلی صف میں نماز پڑھنے والوں کی فضیلت معلوم ہوئی کہ فرشتے ان کے لیے دعا کرتے ہیں۔ ایک حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” اگر لوگوں کو اذان اور صف اول ( کی شان و عظمت اور اجر و ثواب ) کا علم ہو جائے۔ پھر وہ انہیں قرعہ اندازی کے بغیر حاصل نہ کر سکیں تو وہ ان کے حصول کی خاطر آپس میں قرعہ اندازی کریں۔“ (صحیح بخاری، کتاب الاذان، رقم: ٦١٥) یہ بھی معلوم ہوا کہ نبی صلی اللہ علیہ وسلم کا عملاً صفوں کو برابر کرنا کرانا اس کے انتہائی مؤکد عمل ہونے کی دلیل ہے۔ نیز چاہیے کہ امام ایسا ہو جو صاحب علم، باعمل باوقار اور باہمیت ہو اور خوش اخلاق بھی کہ دینی امور میں اپنے سے چھوٹوں اور بڑوں کی بالفعل اصلاح کر سکے۔ ٧٤٠"}],[740,"و سیدنا جابر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”بہترین جگہ جس کی طرف رخت سفر باندھا جائے وہ میری مسجد ہے اور البیت العتیق ( بیت اللہ شریف ہے )۔‘ یہ حدیث لیث سے صرف علاء بن موسیٰ ہی روایت کرتے ہیں۔","",{"k":"کر السلسلة الصحيحة (٢/٣٩٢)، رقم : (١٦٤٨)، مسند احمد (٣/٣٥٠)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ مسجد نبوی اور بیت العتیق۔ بیت العتیق کا معنی قدیمی گھر وَلْيَطَّوفُوا بِالْبَيْتِ الْعَتِيقِ﴾ (الحج: ٢٩) کی طرف انسان ثواب کی نیت سے سفر کر سکتا ہے۔ ٧٤١"}],[741,"سیدنا عبد اللہ بن مسعود ضیا الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قل هُوَ اللهُ اَحَدٌ تہائی قرآن کے برابر ہے۔ یہ حدیث عکرمہ بن ابراہیم سے صرف علی بن جعد ہی روایت کرتے ہیں۔ ٧٤٢","",{"k":"صحیح بخاری (٥٠١٣)۔"}],[742,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مومن کے پاس جب موت حاضر ہوتی ہے تو فرشتے اس کے پاس ہوتے ہیں ان کے پاس ریشم، کستوری اور خوشبوؤں کے بنڈل ہوتے ہیں۔ اس کی روح اس کے جسم سے اس طرح نکالی جاتی ہے جس طرح گوندھے ہوئے آٹے سے بال نکالا جاتا ہے۔ اور کہا جاتا ہے: ”اے اطمینان والی جان! خوش ہو جا، اور خوشی سے باہر نکل آ، پھر اس کو ریشم میں لپیٹا جاتا ہے پھر اسے علیین میں بھیجا جاتا ہے اور جب موت کافر کے پاس آ پہنچتی ہے تو اس کی روح سختی کے ساتھ جسم سے کھینچ کر نکالی جاتی ہے، اور کہا جاتا ہے: اے خبیث جان! نکل جا ناراض ہونے والی ناراض کی گئی کسی ذلت اور عذاب کی طرح نکل جا جب روح نکل آتی اور ان چنگاریوں میں لپیٹی جاتی ہے تو اس کو سچین کی طرف لے جایا جاتا ہے۔ یہ حدیث قاسم بن فضل سے صرف سلیمان بن نعمان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مرتے وقت مومن کو مختلف اعزازات سے نوازا جاتا ہے۔","",{"k":"سنن نسائی (١٨٣٣)، المعجم الكبير للطبراني (١٩/١٣٤)، قال الشيخ الالبانى، صحیح۔","f":"(١) مؤمن آدمی کی روح لینے کے لیے رحمت کے فرشتے جنت سے سفید ریشمی کفن اپنے ساتھ لاتے ہیں۔\n(٢) مومن آدمی کی روح قبض کرنے والے فرشتے جنت سے خوشبو اپنے ساتھ لاتے ہیں۔\n(٣) روح آسانی سے جلدی جلدی نکل جاتی ہے ایک حدیث میں ہے (( فتخرج تسیل کما تسيل القطرة من في السقاء)) (ترغیب و ترهيب: ٥٢٢١/٤، اسناده حسن) روح جسم سے اس طرح ( آسانی سے) نکل آتی ہے جیسے پانی مشک سے بہہ نکلتا ہے۔“\n(٤) روح قبض کرنے سے پہلے فرشتے مومن آدمی کی روح کو مخاطب کر کے کہتے ہیں: اے پاک روح! اللہ کی مغفرت اور خوشنودی کی طرف چل، جیسا کہ ارشاد باری تعالیٰ ہے: يَا يَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلى رَبِّكِ رَاضِيَةً مَّرْضِيَّةٌ، فَادْخُلِي فِي عِبْدِيهِ وَادْخُلِي جَنَّتِي ) (الفجر: ٢٧ تا ٣٠) ”اے اطمینان والی روح! تو اپنے رب کی طرف لوٹ چل اس طرح کہ تو اس سے راضی وہ تجھ سے خوش، پس میرے خاص بندوں میں داخل ہو جا اور میری جنت میں داخل ہو جا۔“\n(٥) نیک لوگوں کی روحیں علیین میں ہوتی ہیں جیسا کہ ارشاد باری تعالیٰ ہے: كَلا إِنَّ كِتَابَ الْأَبْرَارِ لَفِي عَلِيِّينَ﴾ (المطففين: ١٨) یقیناً نیکوکاروں کا نامہ اعمال علیین میں ہے۔“ علمین آسمانوں میں یا جنت میں یا سدرۃ المنتہی یا عرش کے پاس جگہ ہے جہاں نیک لوگوں کی روحیں اور ان کے اعمال نامے محفوظ ہوتے ہیں۔ مذکورہ حدیث میں مومن کے لیے پانچ اعزازات کا تذکرہ ہے۔ دوسری احادیث میں دیگر عزازات کا بھی تذکرہ ہے۔ (١) فرشتے آکر سلام کہتے ہیں۔ (٧) مومن کی روح قبض کرتے وقت فرشتے مومن آدمی کو اللہ تعالیٰ کی مغفرت اور رضا مندی کی بشارت دیتے ہیں۔ (٨) مومن آدمی کی روح کے لیے زمین و آسمان والوں کے درمیان موجود فرشتے رحمت کی دعا کرتے ہیں۔ (٩) فرشتے آسمان والوں کو اس روح کا تعارف کرواتے ہیں۔ (١٠) ہر فرشتہ مومن کی روح کو الوداع کرنے کے لیے دوسرے آسمان تک جاتا ہے۔ کا فر کو مرتے وقت سزائیں: (١) کافر کی روح قبض کرنے والے فرشتے اپنے ساتھ ٹاٹ کا کفن لے کر آتے ہیں جس میں آگ کی چنگاری ہوتی ہے۔ (٢) جس طرح مومن کی روح بڑی آسانی سے نکلتی ہے اس کے برعکس کافر کی روح بڑی مشکل سے نکلتی ہے فرشتے کہتے ہیں اے ناپاک روح! نکل اس جسم سے اور چل اللہ کے غصہ اور غضب کی طرف۔ (٣) کافروں کا نامہ اعمال سجین میں ہوتا ہے جیسا کہ ارشاد باری تعالیٰ ہے: كَلا اِنَّ كِتَابَ الفُجَّارِ لَفِي سِجِّينٍ ﴾ (المطففين: ٧) یقیناً بدکاروں کا نامہ اعمال سجین میں ہوتا ہے۔“ سجین بعض مفسرین کہتے ہیں سجن (قید خانہ) سے ہے مطلب یہ ہے کہ قید خانے کی طرح ایک نہایت تنگ مقام ہے اور بعض کہتے ہیں کہ یہ زمین کے سب سے نچلے حصے میں ایک جگہ ہے جہاں کافروں، ظالموں، اور مشرکوں کی روحیں اور ان کے اعمال نامے جمع اور محفوظ ہوتے ہیں۔"}],[743,"سیدنا عبداللہ ابن عباس ریلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قریش کی سوالات اہل زمین کے اختلاف سے امان ہے، قریش اللہ والے ہیں تین بار فرمایا: جب عرب کا کوئی قبلہ ان سے اختلاف کرتا ہے تو وہ ابلیس کی جماعت بن جاتا ہے۔“ یہ حدیث عطاء سے صرف خلید بن دعلج ہی روایت کرتے ہیں۔ ٧٤٤","",{"k":"السلسلة الضعيفة (٦٨٣)، ضعيف الجامع الصغير (١٢٤٩)۔"}],[744,"سیدنا ابو امامہ باہلی رضی اللہ عنہ نے نبی ملل علیم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”پانی کو کوئی چیز بھی ناپاک نہیں کر سکتی مگر وہ جو اس کی بو یا اس کا ذائقہ بدل دے۔“ یہ حدیث معاویہ بن صالح سے صرف رشدین ہی روایت کرتے ہیں، اسے روایت کرنے میں محمد بن یوسف اکیلے ہیں۔ ٧٤٥","",{"k":"السنن الكبرى للبيهقي (١/٢٥٩)، ضعيف الجامع الصغير (٥٨٩٩)۔"}],[745,"سیدنا جریر بن عبد اللہ نے بیان کیا، نبی ملے لیکن جب کوئی لشکر روانہ کرتے تو یوں کہتے: ((بِسْمِ اللَّهِ وَفِي سَبِيْلِ اللَّهِ وَعَلَى مِلَّةِ رَسُوْلِ اللهِ)) اللہ کے نام کے ساتھ اللہ کی راہ میں اللہ کے رسول کی ملت پر جاؤ، خیانت کرو نہ دھوکا کرو، مثلہ کرو، نہ بچوں کو قتل کرو۔“ یہ حدیث جریر سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابن لھیعہ اکیلے ہیں۔","",{"k":"سنن ابو داؤد (٢٦١٣)، سنن ترمذی (١٤٠٨)، قال الشيخ الالباني: صحیح۔","f":"ভ مذکورہ حدیث میں جہاد کے آداب بتلائے جارہے ہیں کہ اللہ کا نام لے کر شروع کرنا چاہیے۔ لا تغلو: خیانت نہ کرو، یہ فعل نہی کا صیغہ ہے۔ باب غَلَّ يَغُلُّ (بروزن نصر ) سے اس کا معنی ہے مال غنیمت میں خیانت کرنا، مال غنیمت میں خیانت کرنے سے منع کیا ہے جیسا کہ ارشاد باری تعالیٰ ہے: وَمَنْ يَغْلُلْ يَأْتِ بِمَا عَلَّ يَوْمَ الْقِيمَةِ (آل عمران: ١٦١) ”ہر خیانت کرنے والا خیانت کو لیے ہوئے قیامت کے دن حاضر ہوگا۔“ لا تغدروا عہد شکنی مت کرو۔ لا تمثلوا مثلہ نہ کرو، مثلہ! مقتول کی ناک، کان اور دیگر اعضاء کاٹ دینے کو کہتے ہیں، ولدان: وہ بچے جو ابھی نابالغ ہوں اور لڑائی کے قابل نہ ہوں۔ اس کو قتل کرنا درست نہیں"}],[746,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بیٹھ کر نماز پڑھنے والے کو کھڑے ہو کر نماز پڑھنے والے سے آدھا ثواب ملے گا۔ اسی طرح جریر بن حازم، محمد بن اسحاق سے اور وہ زہری سے اور وہ ابوسلمہ سے روایت کرتے ہیں اور سفیان بن عیینہ زہری سے اور زہری، عیسی بن طلحہ سے روایت کرتے ہیں۔ اور ابن جریج زہری اور وہ حضرت انس بن مالک سے روایت کرتے ہیں۔ اور صالح بن ابی اخضر، زہری سے اور وہ حضرت سائب بن یزید سے اور وہ عبدالمطلب بن ابی وداعہ سے روایت کرتے ہیں۔ اور عبداللہ بن زیاد الرصافی، زہری سے، وہ نعلبہ بن ابی مالک القرظی سے اور وہ حضرت عبد اللہ بن عمرو سے روایت کرتے ہیں۔ اور محمد بن زبیر الحراسانی، سالم سے اور وہ اپنے والد سے روایت کرتے ہیں اور صحیح بات اللہ ہی زیادہ جانتا ہے، جو سفیان بن عیینہ روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کھڑے ہو کر نماز پڑھنا چاہیے بیٹھ کر پڑھنے سے ثواب میں کمی آجاتی ہے، یہ اس وقت ہے جب کوئی عذر نہ ہواگر عذر ہو تو شریعت اجازت دیتی ہے جیسا کہ سیدنا عمران بن حصین یا اللہ سے روایت ہے نبی مکرم سے تم نے فرمایا: ((اصل قائما فان لم تستطع فقاعدا فان لم تستطع فعلى جنب والا فاوم ) (صحیح بخاری:، رقم: ١١١٧، سنن ابی داؤد، رقم: ٩٥٢) کھڑے ہو کر نماز پڑھو اگر اس کی طاقت نہ ہو تو بیٹھ کر پڑھ لو اگر اس کی بھی طاقت نہ ہو تو پہلو کے بل لیٹ کر پڑھ لو اور ان میں سے کچھ بھی نہ کرسکو تو پھر اشارے ہی سے پڑھ لو۔“ ٧٤٧","",{"k":"سنن ابن ماجه، رقم : سنن ابو داؤد (٩٥٠)، قال الالبانی : صحیح۔"}],[747,"سیدنا بریدہ رضی اللہ عنہ نے بیان کیا، ایک دن نبی الے علم نے کھجوروں کی خواہش ظاہر فرمائی تو آپ ملٹیم کو ایک صاع معجوہ کھجور میں لا کر دی گئیں جب وہ لائے تو آپ صلی اللہ علیہ وسلم نے ان پر انکار کیا اور فرمایا: ”یہ تم کہاں سے لائے ہو؟“ انہوں نے کہا: ہم نے دو صاع بھیجے اور ہم ایک صاع لے آئے۔ آپ میم نے فرمایا: 'واپس کرو! واپس کرو! ہمیں ان کی کوئی ضرورت نہیں۔“ یہ حضرت بریدہ سے صرف اسی سند سے مروی ہے اور اسے روایت کرنے میں بیٹی بن معین اکیلے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا ایک ہی جنس کی اشیاء کو باہم کمی بیشی کے ساتھ فروخت کرنا جائز نہیں خواہ وہ معیار میں مختلف ہی کیوں نہ ہوں۔ البتہ اگر ان کے معیار میں کمی بیشی ہو تو پھر مناسب یہ ہے کہ گھٹیا اشیا کو رائج الوقت کرنسی کے بدلے فروخت کر دیا جائے، اور پھر عمدہ اشیا کرنسی کے بدلے خرید لی جائیں۔ ٧٤٨","",{"k":"مجمع الزوائد (٤/١١٣)، شرح معانی الاثار (٥٣٢٤)، سنده حسن۔"}],[748,"سيدنا ابو ہریرہ ضیا یہ بیان کرتے ہیں: قیامت کی نشانیوں میں سے یہ بھی ہے کہ بخل اور فحش گوئی تمہارے سامنے آجائیں گی، خائن کو امانت دار سمجھا جائے گا، امانت دار کو خائن کہا جائے گا اور ایسے کپڑے سامنے آجائیں گے جنہیں عورتیں پہنے کے باوجود ٹنگی ہوں گی اور برے لوگ نیک گھرانوں والوں کے اوپر چڑھ جائیں گے۔“ کیا اسی طرح اے عبد اللہ بن مسعود! تو نے میرے دوست یعنی نبی صلی اللہ علیہ وسلم سے یہ حدیث سنی ہے انہوں نے کہا: ہاں قسم ہے کعبے کے رب کی! ہم نے پوچھا: ”تحوت‘ سے کیا مراد ہے؟ انہوں نے کہا: برے لوگ جو کمینے اور ذلیل ہوں گے ان کو نیک لوگوں سے بلند مقام دیا جائے گا۔’وعول سے مراد نیک گھرانوں والے لوگ مراد ہیں۔ یہ حدیث ابن جریج سے صرف حجاج ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (٧/٣٢٧)، انطر (١٣٥٦)۔","f":"مذکورہ حدیث میں علامات قیامت کا تذکرہ ہے۔ قیامت کی علامات دو قسم کی ہیں علامات صغریٰ اور علامات کبری، علامات صغری یعنی چھوٹی علامات کی ابتدا نبی آخر الزمان طلئے علیم سے ہو چکی ہے اور تا حال واقع ہو رہی ہیں جن کی تعداد علماء کرام نے مختلف لکھی ہے، تقریباً ٥٧ کے قریب ہیں کچھ علامات کا تذکرہ مذکورہ بالا حدیث میں موجود ہے۔"}],[749,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما بیان کرتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ” میں تمہارا پیش خیمہ ہوں گا، اگر تم مجھے کہیں نہ پاؤ تو مجھے حوض پر ملو گے اور حوض ایلہ سے مکہ تک ہے وہاں خواتین و حضرات برتن اور مشکیزے لے کر آئیں گے۔“ یہ حدیث ابن جریج سے صرف حجاج ہی روایت کرتے ہیں۔","",{"k":"مسند احمد (٣٤٥، ٣، ١٤٧٦١)، حدیث صحیح۔"}],[750,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ ملنے سلیم نے فرمایا: ”جب تم میں سے کوئی کسی عورت سے شادی کرنا چاہے تو اس میں کوئی حرج نہیں کہ وہ مرد اس عورت کو دیکھ لے۔“ یہ حدیث ثابت سے صرف معمر ہی روایت کرتے ہیں، اسے روایت کرنے میں عبد الرزاق اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ جس عورت سے نکاح کا ارادہ ہو اسے ایک مرتبہ دیکھ لینا چاہیے۔ امام نووی، شافعی، مالک، ابو حنیفہ، احمد بینم، تمام اہل کوفہ، اور جمہور کا یہی موقف ہے کہ ایسا کرنا تحب ہے۔ (شرح مسلم للنووى: ٢٢٧/٥) شیخ ابن باز اللہ نے یہ فتویٰ دیا ہے کہ منگیتر کو ایک نظر دیکھ لینا جائز ہے مگر یہ خلوت کے بغیر ہو۔ (فتاوی اسلامیه: ١٢٨/٣) واضح رہے کہ اگر کسی معتبر ذریعے سے عورت کے رنگ و روپ اور عادات و فضائل کے متعلق صحیح معلومات حاصل ہونے کی بنا پر کوئی خود نہ دیکھنا چاہے تو اس میں کوئی حرج نہیں۔ اس بات کا بھی خیال رکھنا کہ عورت کو دیکھنے کے لیے اس سے اجازت لینا ضروری نہیں بلکہ اسے چھپ کر دیکھا جا سکتا ہے۔ جیسا کہ سیدنا جابر بلا لینے سے مروی ہے کہ جب انہوں نے منگیتر کو دیکھنے کے متعلق فرمان نبوی سنا تو وہ بیان کرتے ہیں کہ پھر میں نے ایک لڑکی کو پیغام نکاح بھیجا۔ میں اسے چھپ کر دیکھا کرتا تھا حتی کہ میں نے اس کے ان اعضا کو دیکھ ہی لیا جو اس سے نکاح کے لیے باعث رغبت تھے تو میں نے اس سے نکاح کر لیا۔ (صحیح سنن ابی داؤد، رقم: ١٨٣٢) باقی رہا کہ عورت کے کن کن اعضا کو دیکھا جا سکتا ہے۔ جمہور کا یہ مؤقف ہے کہ صرف چہرہ اور ہتھیلیاں دیکھی جا سکتی ہیں اس کے علاوہ کچھ نہیں، چہرہ دیکھنے سے خوبصورتی اور بدصورتی کا اندازہ لگایا جا سکتا ہے اور ہتھیلیوں سے جسم کے ملائم ہونے کا اندازہ لگایا جا سکتا ہے۔ (نیل الاوطار: ١٨٥/٤، فقه السنة: ١١٤/٢)","",{"k":"سنن ابن ماجه (١٨٦٤)، صحیح۔"}],[751,"سعید بن جبیر اللہ بیان کرتے ہیں، کسی آدمی نے سیدنا عبد اللہ بن عمر رضی لینے سے عرفہ کے روزے کے متعلق سوال کیا تو انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اس روزے کو دو سال کے روزوں کے برابر سمجھتے تھے۔ یہ حدیث سعید بن جبیر سے صرف ابوحریز ہی روایت کرتے ہیں۔","",{"k":"صحيح الترغيب والترهييب (١٠/٣٤٥، ١٠١٤)، تهذيب الاثار (٢/٣٧، ٨٤٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ یوم عرفہ کا روزہ رکھنا مستحب ہے یہ روزہ دو سال، ایک گذشتہ اور ایک آئندہ سال کے گناہوں کا کفارہ بن جاتا ہے۔ یوم عرفہ سے مراد ٩ ذوالحجہ کا دن ہے جس روز حجاج کرام میدان عرفات میں ہوتے ہیں لیکن یہ روزہ حجاج کے لیے نہیں بلکہ دوسرے لوگوں کے لیے جو اس سال حج کی سعادت سے محروم ہیں وہ یوم عرفہ کا روزہ رکھ لیں۔"}],[752,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا، سیدنا اسامہ بن زید رضی اللہ عنہما سے مزدلفہ تک رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سواری پر سوار تھے۔ پھر مزدلفہ سے منی تک فضل ان کی جگہ بیٹھ گئے تو ان دونوں نے بیان کیا کہ آپ تلبیہ پکارتے رہے حتی کہ جمرہ کی رمی کر لی۔ “ یہ حدیث زہری سے صرف یونس بن یزید ہی روایت کرتے ہیں، اسے روایت کرنے میں جریر بن حازم اکیلے ہیں اور جریر سے صرف اُن کے بیٹے وہیب ہی روایت کرتے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ جمرہ عقبہ کی رمی تک تلبیہ کہتے رہنا چاہیے۔ تلبیہ چھوڑنے کے وقت کے بارے میں فقہا کا اختلاف ہے امام احمد جماللہ نے کہا ہے کہ جمرہ عقبہ کو کنکریاں مارنے سے فراغت کے ساتھ ہی تلبیہ ختم ہو جائے گا جبکہ جمہور علماء کا کہنا ہے کہ پہلی کنکری مارنے پر ہی تلبیہ ختم ہو جائے گا۔ (سبل السلام: ٩٩٢/٢) امام نووی اللہ نے جمہور کے مؤقف کو ترجیح دی ہے تاہم امام شوکانی اور عبد الرحمان مبارکپوری رحمہما اللہ نے امام احمد کے موقف کو قابل اتباع قرار دیا ہے۔ اور اس حدیث کو بطور دلیل پیش نظر رکھا ہے: ((ثم قطع التلبية مع اخر حصاة)) (ابن خزیمه:، رقم: ٢٨٨٧) پھر آپ صلی اللہ علیہ وسلم نے آخری کنکری ( پھینکنے ) کے ساتھ ہی تلبیہ ختم کر دیا۔ ٧٥٣","",{"k":"صحیح بخاری، سنن ابو داؤد، رقم: سنن نسائی (٣٠٢٠، ١٩٢٠)۔"}],[753,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ سے کم دو رکعت اور وتر کے درمیان سلام کے ساتھ فرق کیا کرتے تھے اور یہ سلام ہم کو سناتے بھی تھے۔“ یہ حدیث ابراہیم الصائغ سے صرف ابوحمزہ السکری ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ تین وتر پڑھنا ہوں تو افضل طریقہ یہ ہے کہ دو رکعت پر سلام پھیر دیا جائے اور پھر ایک رکعت بطور وتر پڑھی جائے جیسا کہ ایک روایت میں ہے کہ نبی مکرم ملنے کی اہم رات کو دو دو رکعت ادا فر ماتے اور ایک رکعت وتر پڑھتے۔ (صحیح بخاری، رقم: ٩٩٥، صحیح مسلم، رقم: ٧٤٩)","",{"k":"مسند احمد (٢/٧٦)، صحیح ابن حبان (٢٤٣٤)، ارواء الغليل: ٢/۔"}],[754,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے لیے اس کے صبح کے اوقات میں برکت ڈالی گئی ہے۔ یہ حدیث ثور سے صرف عبد اللہ بن جعفر ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کوئی کام بھی کرنا ہو۔ سفر یا تجارت وغیرہ تو اس کا آغاز::٧٥٥ دن کے پہلے پہر سے کرنا زیادہ مفید اور بابرکت ہے۔ اس وقت انسان تازہ دم ہوتا ہے اور اس کی قوت وافر ہوتی ہے جو ترقی اور برکت کا باعث بنتی ہے۔","",{"k":"سنن ابو داؤد (٦٠٦)، صحيح الجامع الصغير (٢٨٤١)۔"}],[755,"سیدنا ہارون بن دینار کے والد نے بیان کیا، میں نے صحابہ کرام بھی ہم میں سے ایک صحابی رضی اللہ عنہم سے سنا ہے جن کا نام میمون بن سنباذ تھا وہ کہہ رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” میری امت کے حالات اور نظم ونسق برے لوگوں کے ہاتھ آ جائے گا۔“ یہ حدیث میمون بن سنباذ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ہارون بن دینارا کیلے ہیں۔","",{"k":"هارون بن دينار وهو ضعيف. مجمع الزوائد (٣٠٢/٥)، ضعيف الجامع الصغير (٤٤١٣)، فيه۔"}],[756,"سیدنا صہیب نبی اللہ سے روایت ہے کہ رسول اللہ سے ہم نے اس آیت: لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ یعنی نیک لوگوں کے لیے نیکی ہے اور زیادہ انعام بھی ہے۔“ کے متعلق فرمایا: ” جب جنتی جنت میں اور دوزخی دوزخ میں چلے جائیں گے تو ایک آواز دینے والا آواز دے گا اے جنت والو! اللہ تعالیٰ کے پاس تمہارا ایک وعدہ ہے جسے وہ تم سے پورا کرنا چاہتا ہے وہ کہیں گے وہ کون سا وعدہ ہے؟ کیا اس نے ہمارے چہرے سفید نہیں کیے؟ کیا اس نے ہمارے ترازو بھاری نہیں کیے؟ کیا اس نے ہمیں آگ سے دور نہیں کر دیا؟ اور جنت میں داخل نہیں کر دیا؟ تو اس وقت پردہ کھول دیا جائے گا تو وہ اللہ عز وجل کو دیکھ لیں گے اور اس دیکھنے سے زیادہ پیاری چیز انہیں اور کوئی محسوس نہ ہو گی اور یہ چیز زیادہ ہے جس کا ذکر قرآن میں ہے۔“ یہ حدیث ثابت سے صرف حماد بن سلمہ ہی روایت کرتے ہیں۔ قرآنی مذکورہ آیت لِلَّذِيْنَ اَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ (يونس: ٢٦) \"جن لوگوں نے نیکی کی ہے ان کے واسطے خوبی ہے اور مزید بھی۔ مذکورہ حدیث اور دیگر احادیث میں اس کی تفسیر دیدار باری تعالیٰ سے کی گئی ہے جس سے اہل جنت کو جنت اور جنت کی نعمتیں دینے کے بعد مشرف کیا جائے گا۔ (صحیح مسلم، کتاب الایمان، باب اثبات رؤية المومن. الخ) مذکورہ روایت سے اللہ تعالیٰ کے دیدار کا اثبات ہوتا ہے علاوہ ازیں ارشاد باری تعالی ہے: وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلى رَبَّهَا نَاظِرَةٌ﴾ (القيامه: ٢٢تا٢٣) اس روز کچھ چہرے تر و تازہ ہوں گے اپنے رب کی طرف دیکھ رہے ہوں گے۔“","",{"k":"سنن ترمذی (٣١٠٥)، سنن ابن ماجه (١٨٧)، صحيح الجامع الصغير (٥٢١)۔"}],[757,"سیدنا ابو محذورہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے اذان کو ہمارے اور ہمارے آزاد کردہ غلاموں کے لیے مقرر کر دیا، اور آپ نے آب زمزم پلانا بنی ہاشم کے لیے اور بیت اللہ کی در بانی بنو عبد الدار کے لیے مقرر فرمائی۔ یہ حدیث عبد الملک بن ابی محذورہ سے صرف ہذیل بن بلال ہی روایت کرتے ہیں۔","",{"k":"مسند احمد (٤٠١/٦، ٢٧٢٩٤)، قال الشيخ شعيب الارناؤط، اسناده ضعيف۔"}],[758,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ مطلئے علیم نے فرمایا: رات کی نماز دو دو رکعت ہے اور جب تمہیں صبح ہو جانے کا اندیشہ ہو تو ایک وتر ادا کر لو۔“ یہ حدیث مثنیٰ العطار سے صرف ابو عبیدہ الحداد ہی روایت کرتے ہیں۔",""],[759,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں نبی صلی اللہ علیہ وسلم اپنے حج کے دوران ایک عورت کے پاس سے گزرے تو اس نے اپنے ہاتھوں سے ایک بچہ باہر نکالا اور عرض کیا، اللہ کے رسول صلی اللہ علیہ وسلم! کیا اس کا حج ہو گا؟ آپ نے فرمایا: ”ہاں، اور تمہارے لیے اجر ہو گا۔“ یہ حدیث یوسف سے صرف عبید بن جناد ہی روایت کرتے ہیں۔","",{"k":"٧٥٩ ترمذی، رقم : ٩٢٤ . صحیح مسلم (١٣٣٦)، سنن۔"}],[760,"سیدنا عبداللہ ابن عباس ریلی جا نے بیان کیا، عباس بن عبد المطلب بنی اللہ جب کسی کو مضاربت کے طور پر مال دیتے تو اس سے یہ شرط کر لیتے کہ (١) تو نے سمندری راستے کو اختیار نہیں کرنا (٢) اور کسی وادی میں نہیں جانا۔ (٣) اور کوئی تر جگر والی زندہ چیز یعنی جانور نہیں خریدنا۔ اگر اس نے اس طرح کا کوئی کام کیا تو وہ مال کے ضائع ہو جانے پر مضاربت پر مال لینے والا ) ذمہ دار ہوگا تو انہوں نے یہ شرط نبی ملنے یام پر پیش کی تو آپ نے اس کی اجازت دے دی۔ یہ حدیث حضرت ابن عباس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں محمد بن عقبہ اکیلے ہیں۔","",{"k":"مجمع الزوائد (٤/١٦١)، ضعفاء ابن عدی (٣/١٨٩)۔"}],[761,"سیدنا بکر بن وائل ضیا اللہ نے بیان کیا، میرے گھر والے مجھے نبی صلی اللہ علیہ وسلم کے پاس لے گئے اور میں اس وقت نوجوان لڑکا تھا تو آپ نے اپنا ہاتھ میرے سر پر پھیرا۔ راوی کہتا ہے کہ پھر میں نے دیکھا کہ ابوعطیہ کا سر اور داڑھی سیاہ کالی تھی حالانکہ وہ سو سال کے ہو چکے تھے۔“ یہ حدیث حضرت ابوعطیہ سے اسی سند سے ہی مروی ہے، اسے روایت کرنے میں محمد بن عقبہ اکیلے ہیں۔","",{"k":"♦، مجمع الزوائد (٩/٣٩٨)، سنده ضعيف۔"}],[762,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، اس اثنا میں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تھے، ابو جہل بن ہشام، شیبہ، عقبہ بن ربیعہ، عقبہ بن ابی معیط، اور امیہ بن خلف بھی وہاں موجود تھے تو ابو جہل نے کہا: فلاں محلے والوں نے اونٹ ذبح کیا کون ہے جو اس کی اوجھری گوبر وغیرہ گندگی سمیت لاکر محمد ( متین ) پر پھینک دے۔ تو ان میں میں انتہائی بد بخت اور بے وقوف عقبہ بن ابی معیط اٹھا اور اس نے اس کو لا کر آپ کے کندھوں پر رکھ دیا۔ جبکہ نبی صلی اللہ علیہ وسلم سجدہ کی حالت میں تھے تو آپ نے اس کی کوئی پروا نہ کی۔ سیدنا عبداللہ ابن مسعود نبی اللہ نے بیان کیا، میں وہاں کھڑا تھا، اور کچھ کہنے سے ڈر رہا تھا کیونکہ میرا وہاں کوئی خاندان قبیلہ نہیں تھا جو مجھے ان سے بچاتا۔ اچا نک سیدہ فاطمہ بنایا نہ جانے یہ بات سنی تو وہ آئیں اور قریش کو برا بھلا کہنے لگیں تو انہوں نے اس کو کوئی جواب نہ دیا۔ نبی ملل سایت سجدہ پورا کر کے اسی طرح سجدے سے اٹھے جس طرح پہلے اٹھا کرتے تھے۔ جب نماز پوری کی تو یہ دعا کی: اے اللہ! تو خواہی قریش سے نمٹ لے۔ اے اللہ! تو قریش کو خودنمٹ لے اے اللہ تو عقبہ، عتبہ، امیہ بن خلف، ابو جہل بن ہشام اور شیبہ سے خود ہی نمٹ لے۔ اور نبی لئے لیکن جب م سے نکلے تو آپ کو ابوالبشتری ملا اور اس کے پاس اس خنصر انگلیوں کے درمیان ایک چھڑی تھی اس نے جب آپ کو دیکھا تو آپ کے چہرے کو اجنبی خیال کیا تو اس نے آپ کو پکڑ لیا اور کہنے لگا: آؤ کیا وجہ ہے؟ تمہیں تو کوئی مصیبت پہنچی ہے۔ آپ نے فرمایا: چھوڑ و مگر وہ کہنے لگا: اللہ جانتا ہے میں نہیں چھوڑوں گا۔ آپ سے ضرور پوچھوں گا: جب آپ کو معلوم ہوا کہ یہ پوچھے بغیر نہیں چھوڑے گا تو آپ نے اس کو بتایا اور فرمایا کہ ابو جہل نے حکم دیا تو مجھ پر گوبر ڈالا گیا۔ ابو البختری نے کہا: آؤ مسجد کی طرف چلتے ہیں۔ آپ نے انکار کیا تو اس نے آپ کو پکڑ لیا، اور مسجد میں لے گیا اور ابوجہل کی طرف متوجہ ہو کر کہا: اے ابو الحکم! کیا تو نے حکم دیا تو محمد نے ان پر گوہر پھینکا گیا؟ اس نے کہا: ہاں، تو اس نے اپنا کوڑا اٹھایا اور ابو جہل کے سر پر دے مارا، لوگ سارے پیچھے ہٹ گئے ابو جہل نے کہا: تمہارے لیے ہلاکت ہو۔ یہ اس کی کامیابی ہے، یہ چاہتا ہے کہ ہمارے درمیان دشمنی ڈال کر خود بچ جائے اور اس کے ساتھی بھی بچے رہیں۔ مذکورہ روایت سے معلوم ہوا کہ کفار اگر اپنی حرکات سے باز نہ آئیں تو ان کے لیے اللہ سے بد دعا کرنا جائز ہے۔ بلکہ ایسے بدبختوں کا نام لے کر بددعا کی جا سکتی ہے کیوں کہ دعا مومن کا بہترین ہتھیار ہے۔ کیونکہ ابتدائے اسلام میں جو کچھ کفار قریش نے آپ صلی اللہ علیہ وسلم سے برتاؤ کیا اسی میں سے ایک یہ واقعہ بھی ہے۔ آپ صلی اللہ علیہ وسلم کی دعا اللہ ذوالجلال نے قبول کی اور وہ سب کے سب بد بخت بدر کی لڑائی میں ذلت کے ساتھ مارے گئے اور ہمیشہ کے لیے اللہ تعالیٰ کی لعنت میں گرفتار ہو گئے۔“ یہ حدیث الاصلح سے صرف محمد بن اسحاق ہی روایت کرتے ہیں،اسے روایت کرنے میں مثنی بن زرعہ کیلیے ہیں۔ ٧٦٣","",{"k":"صحیح بخاری (٥٢٠)، صحيح مسلم (٧٩٤)۔"}],[763,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ لیے تعلیم نے فرمایا: ”سفر عذاب کا ایک ٹکڑا ہے وہ تم میں سے ایک (مسافر) کو اس کی نیند، اس کی لذت اس کے کھانے پینے سے روک دیتا ہے پس جب تم میں سے کوئی اپنے سفر کی ضرورت پوری کر لے تو وہ جلد ہی گھر واپس آ جائے۔‘“ یہ حدیث از مالک از سہیل صرف محمد بن جعفر الور کافی اور محمد بن خالد بن عثمہ ہی روایت کرتے ہیں۔ مالک کے اصحاب مالک سے، وہ سمی سے اور وہ ابی صالح سے روایت کرتے ہیں۔ عتیق بن یعقوب الزبیری، مالک سے اور وہ ابوالنضر سے اور وہ ابو صالح سے روایت کرتے ہیں۔ ردّاد بن جراح، مالک سے، وہ ربیعہ بن ابی عبد الرحمن سے، وہ قاسم سے اور وہ حضرت عائشہ رمنی اشیا سے روایت کرتے ہیں۔ فائد مذکورہ حدیث سے معلوم ہوا کہ مقصد سفر پورا ہو جانے کے بعد مسافر کے لیے فوراً گھر واپس آ جانا مستحب ہے۔ سفر کو عذاب اس لیے قرار دیا گیا ہے کہ اس میں سفر کی مشقتیں برداشت کرنا پڑتی ہیں۔ یہ اس زمانہ کی بات جب گھر سے باہر نکل کر قدم قدم پر بے حد تکالیف اور خطرات کا مقابلہ کرنا پڑتا تھا۔ آج کل سفر میں بہت سی آسانیاں مہیا ہو گئی ہیں مگر رسول اللہ علیم کا فرمان مبارک برحق ہے۔ ہوائی جہاز، بس، کار جس میں بھی سفر ہو بہت سی تکالیف کا سامنا کرنا پڑتا ہے بہت سے ناموافق حالات سامنے آتے ہیں جن کو دیکھ کر بے ساختہ منہ سے نکل پڑتا ہے سفر بالواقع عذاب کا ایک ٹکڑا ہے۔ ٧٦٤","",{"k":"صحیح بخاری، رقم : صحیح مسلم (١٩٢٧، ١٨٠١)۔"}],[764,"سیدنا كعب بن عجرہ ضیا المیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم مسجد میں ہمارے پاس تشریف لائے تو فرمایا: ”یہاں سے کیا تم سن رہے ہو؟ میرے بعد کچھ حاکم ہوں گے جو اللہ تعالیٰ کی فرماں برداری کے کام نہیں کریں گے تو جو شخص ان کے کام میں شریک ہوا اور ان کے ظلم میں ان کی مد کی تو وہ مجھ سے ہے نہ میں اس سے تعلق رکھتا ہوں اور نہ ہی وہ میرے حوض پر آئے گا، اور جو شخص ان کے کام میں ان کے ساتھ شریک ہوا، نہ ان کے ظلم پر ان سے تعاون کیا تو وہ مجھ سے ہے، اور میں اس سے ہوں اور وہ میرے پاس حوض پر بھی آئے گا۔“ یہ حدیث ابو موسیٰ الہلالی سے صرف ابو ہلال الراسی ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذى (٦١٤)، مسند احمد (٤/٢٤٣)، السنن الكبرى للبيهقي (١٦٥/٨)، قال الالباني، صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ برے ظالم بادشاہوں کا ساتھ دینے والے حوض کوثر سے محروم ہو جائیں گے لیکن جو ان کا ساتھ نہیں دیں گے وہ خوش قسمت حوض کوثر کا پانی پئیں گے۔ اسی طرح بدعتی لوگ دین میں نیا کام نکالنے والے بھی محروم رہیں گے۔ (دیکھئے:، بخاری، کتاب الرقاق، باب في الحوض - صحیح مسلم، کتاب فضائل النبی و شمائل، باب حوض نبينا يوم القيامة) ٧٦٥"}],[765,"سیدنا جابر بن عبد اللہ ضیا اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کی بعثت سے پہلی خبر جو ہمیں مدینے میں پہنچی، وہ اس طرح کہ اہل مدینہ کی ایک عورت تھی، جس کے تابع ایک جن تھا وہ ایک پرندے کی شکل میں آیا وہ ایک درخت کے تنے پر آ بیٹھا تو اس عورت نے اسے کہا: کیا تم ہمارے پاس نہیں آؤ گے تاکہ ہم سے کچھ باتیں کرو اور ہم تم سے باتیں کریں اور تم ہم کو ڈراؤ اور ہم تمہیں ڈرائیں؟ وہ جن کہنے لگا: نہیں میں نہیں آسکتا کیونکہ اللہ نے مکہ میں ایک نبی بھیجا ہے اس نے زنا حرام قرار دیا اور اس نے ہمارا سکون ختم کر دیا۔“ یہ حدیث ابن عقیل سے صرف ابوالح حسین بن عمر ہی روایت کرتے ہیں۔","",{"k":"و، عمر مجمع الزوائد (٢٤٣/٨)، مسند احمد (٣٣٥٦، ١٤٨٧٨)، قال الشيخ شعيب الارناؤط اسناده ضعيف۔"}],[766,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” قیامت کے دن مقتول اپنے قاتل کو پکڑ کر اللہ کے سامنے پیش کرے گا اس کی رگوں سے خون بہہ رہا ہوگا، تو وہ کہے گا: رب جی! اس سے پوچھو اس نے مجھے کیوں قتل کیا تھا؟ تو اللہ تعالیٰ اس سے پوچھے گا تو نے اس کو کیوں قتل کیا تھا؟ وہ کہے گا: میں نے اس کو اس لیے قتل کیا تا کہ فلاں آدمی کو عزت ملے تو کہا جائے گا: عزت تو ساری اللہ تعالیٰ کے لیے ہے۔ اسے عاصم سے صرف عکرمہ بن عبد اللہ البنانی ہی روایت کرتے ہیں جو بصرہ کے رہنے والے ہیں، اسے روایت کرنے میں فیض بن وثیق انتقفی اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ قیامت کے دن مقتول قاتل کو لے کر اللہ کے دربار میں حاضر ہو گا اور اس سے پوچھا جائے گا کہ تو نے اس کو کیوں قتل کیا۔ ایک دوسری حدیث میں ہے نبی مکرم ملنے کلیم نے فرمایا: ”سب سے پہلے خون کا حساب ہوگا۔“ یہ حقوق العباد میں سے ہے کیونکہ حقوق اللہ میں سب سے پہلے نماز سے متعلق سوال ہوگا۔","",{"k":"سنن ترمذی (٣٠٢٩)، سنن نسائی (٤٠٠٥)، مجمع الزوائد (٢٩٤٧)، قال الالبانی: صحیح۔"}],[767,"سیدنا عبداللہ ابن عباس رضی نینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب کلام کرتے تو ایسا دکھائی دیتا جیسے آپ کے سامنے کے دانتوں سے نور نکل رہا ہے۔ یہ حدیث حضرت ابن عباس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں۔:٧٦٨ و-ه-","",{"k":"ضعيف . ол ضعيف الجامع الصغير (٤٤٦٣)، سنن دارمی (٥٨)، سنده۔"}],[768,"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے مرتے وقت اپنے چھ غلام آزاد کر دیئے اور ان کے علاوہ اس کا اور کوئی مال نہیں تھا تو نبی صلی اللہ علیہ وسلمن نے ان کے درمیان قرعہ اندازی کی تو آپ نے دو کو آزاد کر دیا اور چار کو غلام بنا دیا۔ یہ حدیث یحی بن عتیق سے صرف حماد بن زیاد ہی روایت کرتے ہیں، اسے روایت کرنے میں فیض بن وثیق اکیلے ہیں۔ نان اسی طرح کا ایک واقعہ سیدنا سعد بن ابی وقاص رضی اللہ عنہ سے متعلق بھی ہے بیان کرتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں صاحب مال ہوں اور میری وارث صرف میری ایک بیٹی ہے تو کیا میں اپنے مال کا دو تہائی حصہ صدقہ کر دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! میں نے عرض کیا: کیا میں اپنا نصف مال صدقہ کر دوں؟ آپ میم نے فرمایا: نہیں! میں نے عرض کیا: کیا میں تہائی مال صدقہ کر دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں! مگر تہائی بھی بہت ہے یقینا تیرا اپنے ورثاء کو منی چھوڑ جانا اس سے بہت بہتر ہے کہ تو ان کو فقیر محتاج چھوڑے اور وہ لوگوں کے سامنے ہاتھ پھیلاتے پھریں۔“ (صحیح بخارى، كتاب الجنائز، رقم: ١٢٩٥، ٢٧٤٢، صحیح مسلم، رقم: ١٦٢٨) ان احادیث سے معلوم ہوا کہ اگر کوئی اپنے مال کی وصیت کرنا چاہے تو ایک تہائی تک وصیت کر سکتا ہے اس سے زیادہ وصیت کرنا جائز نہیں، تاہم اگر وہ زیادہ کی وصیت کر دے تو اس کی وصیت کا اعتبار نہیں ہو گا۔ ختم کر کے ایک تہائی تقسیم کیا جائے گا جس طرح مذکورہ حدیث میں صحابی نے چھ غلام آزاد کرنے کی وصیت کی تو نبی معظم ما علیم نے دو آزاد کر دیے۔ ٧٦٩","",{"k":"٨٠٦٠٠ صحیح مسلم، سنن ابو داؤد۔"}],[769,"سیدنا عمران بن حصین اور سمرہ بن جندب نیلی یہ نہا سے روایت ہے کہ ایک آدمی نے مرتے وقت چھ غلام آزاد کر دیئے اور اس کا ان کے علاوہ کوئی مال نہیں تھا تو نبی صلی اللہ علیہ وسلم نے ان کے درمیان قرعہ اندازی کی، پس آپ نے دو کو آزاد کر دیا اور چار کو غلام بنا لیا۔ یہ حدیث عنبہ بن ابی رائطه الاعود الغنوی سے صرف عبدالوہاب الثقفی ہی روایت کرتے ہیں، اسے روایت کرنے میں فیض بن وثیق اکیلے ہیں، یہ حدیث کسی ایک نے بھی از حسن از سمرہ سوائے عنبسہ کے روایت نہیں کی۔",""],[770,"سیدنا عبد اللہ ابن عباس نیلی اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ یہود پر لعنت کرے ان پر چربی حرام کی گئی تو انہوں نے اسے بیچ کر اس کی قیمت کھائی۔“ یہ حدیث حبیب بن ابی عمرہ سے صرف جریر ہی روایت کرتے ہیں، اسے روایت کرنے میں فیض بن وثیق اکیلے ہیں۔","",{"k":"کر صحیح بخاری (٢٢٢٣)، صحیح مسلم (١٥٨٢)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ حیلہ کر کے کسی حرام چیز کو حلال کر لینا جائز نہیں بلکہ شرعی حکم میں ردو بدل کرنا بہت بڑا جرم ہے کسی حلال کو حرام کر لینا اور حرام کو کسی حیلہ سے حلال کرانا یہ لعنت کا موجب ہے اسی طرح حلال یا حرام کے لیے مختلف حیلوں سے کام لینا یہودیوں کی صفت ہے۔ کیا جس چیز کی خرید و فروخت حرام ہے اس کی قیمت کھانا بھی حرام ہے؟ بعض اہل علم کا یہ کہنا ہے کہ یہ ضروری نہیں کہ جس چیز کی خرید و فروخت حرام ہے اس سے فائدہ اٹھانا بھی حرام ہے جیسا کہ امام ابن قیم اللہ فرماتے ہیں: فائدہ اٹھانے میں خرید وفروخت سے زیادہ وسعت ہے لہذا ایسا نہیں ہے کہ ہر وہ چیز جس کی خرید وفروخت حرام ہے اس سے فائدہ اٹھانا بھی حرام ہو کیونکہ ان دونوں کے درمیان کوئی لزوم نہیں۔ (زاد المعاد: ٢٤٢/٤)"}],[771,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ترویہ کے دن ( ٨ ذوالحجہ کو منی میں ظہر اور عصر کی نماز پڑھی۔ یہ حدیث اعمش سے صرف عبثر ہی روایت کرتے ہیں۔ رسول اللہ علیم کے زمانے میں چونکہ منی، مزدلفہ اور عرفات وغیرہ میں پانی نہیں ملتا تھا اس لیے لوگ منی روانہ ہونے سے قبل ٨ ذوالحجہ کو اپنے اونٹوں کو خوب پانی پلایا کرتے تھے تا کہ حج کے چار پانچ دن اونٹ پانی پئے بغیر گزارا کر سکیں۔ اس لیے ٨ ذوالحجہ کو یوم الترویہ کہا جاتا ہے۔ ٨ ذوالجہ کو نماز ظہر سے قبل منی پہنچنا مسنون ہے۔ مذکورہ روایت سے معلوم ہوا کہ نبی صلی اللہ علیہ وسلم نے منی میں ٨ ذی الحجہ کو نماز عصر ادا کی۔ مسلم شریف میں ہے کہ ٨ ذو الحجہ کو ظہر، عصر، مغرب، عشا اور ٩ ذی الحجہ کی فجر کی نمازیں ادا کیں۔ لہذامنی میں پانچ نمازیں پڑھنا مسنون ہے۔ (صحیح مسلم، کتاب الحج، باب حجة النبي ه - لله","",{"k":"صحیح بخاری، صحیح مسلم (٣٠٩)۔"}],[772,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلے علی تیم نے فرمایا: ” دو شکاری بھوکے بھیڑیے جو ان بکریوں کے ریوڑ میں رات گزاریں جن کے مالک ان سے بے خبر ہوں وہ چیر پھاڑ کر انہیں کھا جائیں تو یہ اتنی زیادہ خرابی نہیں کرتے جتنی خرابی مال اور عزت و شرف کی محبت مسلمان آدمی کے دین میں کرتی ہے۔ یہ حدیث سفیان سے صرف عبد الملک الذماری ہی روایت کرتے ہیں۔","",{"f":"مذکورہ حدیث سے معلوم ہوا کہ دنیا کی آرزویں، مال، عزت دین کو برباد کر دیتی ہیں کیونکہ ناجائز امید میں آخرت کو بھلا دیتی ہیں اس لیے اسلام ہمیں دنیا میں پردیس اور مسافر کی طرح رہنے کی تلقین کرتا ہے۔ جیسا کہ سیدنا عبد اللہ بن عمر ض ل ل ا ل نے روایت کرتے ہیں کہ رسول اللہ علیم نے مجھے میرے دونوں کندھوں سے پکڑا اور ارشاد فرمایا: ((کن) في الدنيا كانك غريب او عابر سبیل)) ”دنیا میں ایسے رہو جیسے پر دیسی ہو یا مسافر “ اور سیدنا عبد اللہ ابن عمر رضی اللہ عنہما فرمایا کرتے تھے: جب تم ( زندہ ) شام کر لو تو صبح کا انتظار نہ کرو۔ (صحیح بخاری، کتاب الرقاق، رقم: ٦٤١٧)"}],[773,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں کسی کو دوست بنا تا تو سیدنا ابوبکر بنا لینے کو دوست بنا تا لیکن تمہارا ساتھی صرف اللہ تعالیٰ کا دوست ہے۔“ یہ حدیث مغیرہ سے صرف جریر ہی روایت کرتے ہیں۔ ·:٧٧٤","",{"k":"المعجم الكبير للطبراني (٤٣٥/٨، ٩٩٦٠)۔","f":"مذکورہ حدیث سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت پر دلالت کرتی ہے۔"}],[774,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، اللہ کے نبی صلی اللہ علیہ وسلم آٹھ ہزار نبیوں کے بعد بھیجے گئے جن میں چار ہزار بنی اسرائیل میں تھے۔ یہ حدیث از صفوان بن سلیم از یزید الرقاشی صرف ابراهیم بن مہاجر بن مسمار ہی روایت کرتے ہیں، اسے روایت کرنے میں ابراہیم بن منذرا کیلے ہیں اور زیاد بن سعد بن صفوان بن سلیم، انس رضی اللہ عنہ سے روایت کرتے ہیں۔","",{"k":"مسند ابی یعلی (٤١٣٢)، مجمع الزوائد (٨/ ٢١٠، فيه مهاجر بن مسمار وهو ضعيفُ۔"}],[775,"سيدنا ابو الفضیل رضی اللہ عنہ نے بیان کیا، نبی ملت م تشریف لائے تو سیدنا علی رضی اللہ عنہ سے علم مٹی پر سوئے ہوئے تھے۔ آپ نے فرمایا: ”تیرے ناموں میں سے زیادہ سچا نام ابو تراب ہے چلو آئندہ تم ابو تراب ہو۔“ یہ حدیث ابوطفیل سے اسی سند سے مروی ہے، اسے روایت کرنے میں عبدالرحمن بن صالح اکیلے ہیں۔ تراب مٹی کو کہتے ہیں، چونکہ زمین پر لیٹنے سے ان کی کمر مٹی سے بھر گئی تھی اس لیے","",{"k":"صحیح بخاری (٦٢٠٤)۔","f":"الله، ما علیم نے ان کو ابو تراب کے لفظ سے یاد فرمایا۔ اور ان کی یہ بھی ایک کنیت بن گئی۔ اس سے قبل سیدنا علی رضی اللہ عنہ کی کنیت ابو الحسن مشہور تھی مذکورہ حدیث سے معلوم ہوا کہ بیٹی، بیٹے کے علاوہ اور کسی چیز سے بھی کنیت مقرر کی جاسکتی ہے جیسا کہ سیدنا ابو ہریرہ میلہ لینے کی کنیت بلی سے منسوب تھی اسی طرح سیدہ عائشہ بنا لیا کی اولاد نہیں تھی لیکن کنیت ام عبد اللہ تھی"}],[776,"سیدنا علی یا اللہ سے مروی ہے قرآن مجید کی آیت: ﴿الَّذِيْنَ بَدَّلُوا نِعْمَةَ اللَّهِ كُفْرًا وَاَحَلُّوا قَوْمَهُمْ دَارَ الْبَوَارِ یعنی جن لوگوں نے اللہ کی نعمت کو کفر سے بدل دیا اور اپنی قوم کو ہلاکت کے گھر میں اتار دیا۔ سیدنا علی ضیا یہ کہتے ہیں: یہ دو فخر کرنے والوں کے متعلق نازل ہوئی جو قریش سے ہیں ISIS (١) بنی مخزوم (٢) بنو امیہ تو بنومخزوم کی جڑ بدر کے دن کٹ گئی اور بنو امیہ کو کچھ وقت تک کے لیے مہلت دی گئی۔“ یہ حدیث مطرف سے صالح بن عمر ہی روایت کرتے ہیں، اسے روایت کرنے میں سعید بن سلیمان اکیلے ہیں۔ مذکورہ روایت کمزور ہے تاہم یہ بات درست ہے کہ اس سے مراد کفار مکہ ہیں۔","",{"k":"مجمع الزوائد (٤٤/٧)، سنده ضعيف۔","f":"(صحیح بخارى كتاب تفسير القرآن، رقم: ٤٧٠٠) اور بدر میں اللہ نے ان کو ذلیل کیا بلکہ اس کا مفہوم عام ہے کہ محمد رسول اللہ صلی اللہ علیہ وسلم اللہ کی بڑی نعمت ہیں جنہوں نے اس نعمت کی قدر کی اسے قبول کیا، اس نے شکر ادا کیا، وہ جنتی ہو گیا اور جس نے اس نعمت کو رد کر دیا، اور کفر اختیار کیے رکھا وہ دنیا و آخرت میں ذلیل ہو جائے گا۔"}],[777,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ علیم نے منی میں دو رکعت نماز پڑھی اور سیدنا ابوبکر ریالی اور سیدنا عمر ضیا المیہ نے بھی اور سیدنا عثمان رضی اللہ عنہ نے بھی اپنی خلافت کے نصف تک۔“ یہ حدیث ہشام بن عروہ سے صرف ابو خالد الاحمر اور عبدہ بن سلیمان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نبی مکرم ملے ایس ایم شیخین لیا اور سیدنا عثمان شا اللہ ابتدائی چھ سال تک منی میں دو رکعتیں پڑھتے تھے لیکن سیدنا عثان ضیا نے چھ سال کے بعد دو کی بجائے چار کعتیں منی میں پڑھتے تھے لیکن دوسرے صحابہ کرام رضوان اللہ علیہم اجمعین نے ان کا یہ فعل سنت کے خلاف سمجھا تھا۔ سیدنا عثمان رضی اللہ عنہ کے پوری پڑھنے کی بہت سی وجوہ بیان کی گئی ہیں جن میں ایک یہ بھی ہے کہ آپ سفر میں قصر کرنا اور پوری نماز پڑھنا ہر دو امر جائز جانتے تھے۔ اس لیے آپ نے جواز پر عمل کیا لیکن جو صحابہ کرام رضوان اللہ علیہم اجمعین اختلاف کرتے تھے وہ بھی سیدنا عثمان ضیا اہلیہ کے پیچھے نماز پڑھتے تھے۔","",{"k":"صحیح بخاری (١٦٥٥)، صحيح مسلم (٢٩٤)۔"}],[778,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جس نے یقین سے ”لا الہ الا اللہ\" کہہ دیا وہ جنت میں داخل ہوگا۔ یہ حدیث عمرو بن دینار سے صرف قزعہ بن سوید ہی روایت کرتے ہیں، اسے روایت کرنے میں قواریری اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ یقین کے ساتھ کلمہ توحید کا اقرار کرنے والا جنت میں جائے گا جیسا کہ سیدنا معاذ رضی اللہ عنہ سے مروی ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ”جس شخص نے دل کو خالص کرتے ہوئے ”لا الہ الا الله (کلمہ توحید کی گواہی دی وہ جنت میں داخل ہو گا۔ (سنن ابن ماجه رقم: ١/ ٢٨٠، السلسلة الصحيحة: ٢٣٥٥)","",{"k":"مجمع الزوائد (١/١٧)، صحیح۔"}],[779,"سیدنا عبد اللہ ابن عباس نیا اینجا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ترویہ سے ایک دن قبل فرمایا: ” ان شاء اللہ تعالیٰ کل ہماری منزل خیف ایمن ہوگی جہاں کفار نے کفر کی حمایت میں قسمیں کھائی تھیں۔ یہ حدیث سفیان بن حصین سے صرف عباد بن عوام ہی روایت کرتے ہیں۔ انبی ملنے سے ان کی مراد محصب تھی کیوں کہ یہیں قریش اور کنانہ نے بنو ہاشم اور بنوعبدالمطلب","",{"k":"صحیح بخاری (١٥٨٩، ١٥٩٠)، صحيح مسلم (١٣١٤)۔","f":"کے خلاف حلف اُٹھایا تھا کہ جب تک وہ نبی صلی اللہ علیہ وسلم کو ان کے حوالے نہیں کرتے ان کے ہاں شادی نہیں کریں گے اور نہ ان سے خرید و فروخت کریں گے۔ جس کے بعد نبی ملنے کی اہم اپنے خاندان سمیت شعب ابی طالب میں محصور ہو گئے تھے۔ نبی ملت ایام مکہ داخل ہوتے وقت اس مقام پر اترے مقصود اللہ تعالیٰ کا شکر بجالا نا تھا کہ ایک دن وہ تھا اور ایک آج کا دن ہے کہ اب مکہ پر اسلام کی حکومت ہے۔ و-ه-"}],[780,"سیدنا ابو امامہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اللہ کی عبادت میں ہی پروان چڑھا یہاں تک کہ موت نے اس کو آلیا تو اللہ تعالیٰ اس کو ٩٩ صدیقین کے برابر اجر دے گا۔ یہ حدیث مکحول سے صرف مرزوق ابو عبد اللہ ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (١٠/٢٧٠)، المعجم الكبير للطبرانی (٨/١٢٩، ٧٥٨٩)، كنز العمال (٤٣١٠٤)، فيه يوسف بن عطية وهو ضعيف۔"}],[781,"سیدنا سلیک غطفانی نبی اللہ نے بیان کیا، ایک دفعہ اس اثنا میں کہ رسول اللہ ملنے کی کیم خطبہ ارشاد فرما رہے تھے کہ میں مسجد میں داخل ہوا اور بیٹھ گیا۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا تو نے دو رکعت نماز ادا کی ہے؟“ میں نے کہا: نہیں! تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” یہ دو رکعت نماز پڑھو۔“ یہ حدیث ذکریا بن حکیم سے صرف داؤد بن منصور القاضی ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ دوران خطبہ بھی تحیۃ المسجد پڑھنا چاہیے۔ قبل از خطبہ جمعہ نوافل کی کوئی تعداد مقرر نہیں کم از کم دو رکعت تحیتہ المسجد لازماً پڑھنا چاہیے خواہ امام خطبہ بھی دے رہا ہو۔ ٧٨٢","",{"k":"صحیح مسلم (٨٧٥)، سنن ابو داؤد (١١١٧)، مجمع الزوائد (٢/١٨٤)۔"}],[782,"سیدہ عائشہ رضی عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں فرمایا: ”یہ جبریل تمہیں سلام کہہ رہے ہیں تو میں نے کہا: ان پر بھی سلام اور اللہ کی رحمت اور اس کی برکات ہوں، وہ اور اضافہ کرنے لگیں تو آپ نے فرمایا: ”سلام تو یہاں تک پورا ہو جاتا ہے پھر فرمایا: اللہ کی رحمت اور اس کی برکات تم اہل بیت پر ہوں۔ یہ حدیث علاء بن مسیب سے صرف عباد بن عوام ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (٣٣/٨)۔","f":"مذکورہ حدیث سے سیدہ عائشہ نبی اشیا کی فضیلت ثابت ہوتی ہے۔ معلوم ہوا جبریل علی نام سیدہ عائشہ منی الجھا کو سلام کرنے کے لیے آئے تھے۔ سیدہ عائشہ فی الجہا نبی مکرم سے علم کی پیاری بیوی ہیں بڑی ہی عالمہ، فاضلہ اور فصیح اللسان تھیں۔ خلافت معاویہ ضیا اللہ تک زندہ رہی تھیں۔ ٥٨ ہجری میں وفات پائی۔ رمضان المبارک کی ٢٧ تاریخ کو سیدنا ابو ہریرہ بیانیہ نے ان کی نماز جنازہ پڑھائی۔ مذکورہ حدیث سے یہ بھی معلوم ہوا کہ سیدہ عائشہ بنایا وہ اہل بیت میں شامل تھیں۔"}],[783,"سيدنا ابو ہریرہ میل الیہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ریڑھ کی ہڈی کے آخری سرے کے سوا ابن آدم کا سارا جسم بوسیدہ ہو جائے گا۔ قیامت کے روز اسی سے تمام مخلوق کو دوبارہ بنایا جائے گا۔“ یہ حدیث منصور بن ابی اسود سے صرف سعید بن سلیمان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ لوگوں کے اجسام میں سے ریڑھ کی ہڈی کے علاوہ باقی سارا جسم مٹی کھا جاتی ہے۔ صحیح احادیث کے مطابق انبیا و رسل علی اسلام کے جسم مٹی کے کھائے جانے سے محفوظ رہتے ہیں۔ صحیح سنن ابی داؤد، رقم: اسی طرح اولیا، صلحا، اور شہدا میں سے جن جن کے اجسام کو جب تک اللہ تعالیٰ قبروں میں محفوظ رکھنا چاہیں وہ بھی مٹی کے اثر سے محفوظ رہتے ہیں۔ (بخاری، کتاب الجنائز، باب ما جاء فی قبر النبی صلی اللہ علیہ وسلم","",{"k":"صحيح بخارى (٨١٤)، صحيح مسلم (٩٥٥)۔"}],[784,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ نے عام منبر پر کھڑے ہوئے جبکہ آپ صلی اللہ علیہ وسلم کے ہاتھ میں ایک کتاب تھی تو آپ صلی اللہ علیہ وسلم نے فرمایا: میں یہ کتاب اس شخص کو دوں گا جو اللہ تعالیٰ اور اس کے رسول ملے تعلیم سے محبت کرتا ہے اور اللہ اور اس کا رسول ملنے کی تم اس سے محبت کرتے ہیں: ”اے عثمان بن ابی العاص ضیا اللہ! کھڑے ہو جاؤ سیدنا عثمان بن ابی العاص رضی اللہ عنہ ہو گئے تو آپ صلی اللہ علیہ وسلم نے وہ کتاب ان کے حوالے کر دی۔“ یہ حدیث مقبری سے صرف ابو امیہ بن یعلیٰ ہی روایت کرتے ہیں، اسے روایت کرنے میں فیض بن وثیق اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٩/١٣٦)، مجمع الزوائد: ٩/ ٣٧١ فيه ابو امية بن يعلى وهو ضعيف۔"}],[785,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن جدعان کو فرمایا: ” جب تم جوتا خرید و تو عمدہ جوتا خرید و اسی طرح جب تم کپڑا خرید و تو عمدہ کپڑا خریدو۔“ یہ حدیث سعید المبقری صرف ابوامیہ ہی روایت کرتے ہیں، اسے روایت کرنے میں فیض بن وثیق اکیلے ہیں۔ ٧٨٦","",{"k":"السلسلة الضعيفة (٥/٣٣٦، ٢٣٣٧)، مجمع الزوائد (٤/١٠٩)۔"}],[786,"سیدنا انس رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ ملنے ایام کو موزوں پر مسح کرتے ہوئے دیکھا ہے۔“","",{"k":"السنن الكبرى للبيهقي (١/٢٨٩)۔"}],[787,"سیدنا انس رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم جب آئینے میں اپنا چہرہ مبارک و ه-- - ه - لله دیکھتے تو فرماتے: ((الْحَمْدُ لِلَّهِ الَّذِى سَوَّى خَلْقِي فَعَدَلَهُ وَصَوَّرَ صُوْرَةٌ وَجْهِلْ فَحَسَّنَهَا وَجَعَلَنِي مِنَ الْمُسْلِمِینَ)) تمام تعریفیں اس اللہ کے لیے ہیں جس نے میری تخلیق درست کی اور اس کو برابر کیا اور میرے چہرے کی تصویر بنائی تو اس کو خوبصورت بنایا اور مجھے مسلمانوں میں سے بنایا۔ یہ حدیث زہری سے صرف حارث بن مسلم اور حارث سے صرف حاتم بن عیسی ہی روایت کرتے ہیں، اسے روایت کرنے میں سلم بن قادم اکیلے ہیں","",{"k":"♦، ضعيف الجامع الصغير (٤٤٥٩)، مجمع الزوائد (١٠/١٣٩)۔"}],[788,"سیدہ عائشہ بنی النہا سے روایت ہے کہ غیلان کی بیٹی نبی صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: میں طاہر اور پاک رہنے پر طاقت نہیں رکھتی تو کیا میں نماز چھوڑ دوں؟ آپ نے فرمایا: ” یہ حیض نہیں یہ تو ایک رگ ہے جب حیض کے دن گزر جائیں تو خون کو اپنے آپ سے ہٹا اور غسل کر اور نماز پڑھ۔“ یہ حدیث از زہری از قاسم صرف محمد بن اسحاق اور ابن اسحاق سے صرف عمرو بن ہاشم ہی روایت کرتے ہیں، اسے روایت کرنے میں عبدالرحمن بن صالح اکیلے ہیں۔ حیض کے خون سے مراد وہ خون ہے جو عورتوں کو بلوغت کے بعد ہر ماہ کم و بیش چھ یا سات دن حسب عادت آتا ہے اس خون کے آنے کی کم از کم اور زیادہ سے زیادہ کوئی عمر مقرر نہیں۔ (فتاوى المراة المسلمة: ٢٦٦/١) اس کے رنگ کے متعلق فقہا کا اتفاق ہے کہ یہ خون سیاہ سرخ زرد رنگ کا ہوتا ہے۔ (فتح القدیر: ١٢/١) استحاضہ کا خون حیض سے الگ ہوتا ہے اور یہ کسی رگ کے پھٹنے کی وجہ سے آتا ہے۔ مذکورہ بالا حدیث سے معلوم ہوتا ہے کہ جب عورت کو حیض کا خون آئے تو اسے نماز سے رک جانا چاہیے لیکن اگر اسے استحاضہ کا خون آتا ہو تو اس پر نماز پڑھنا لازم ہے، لہذا وہ غسل کرے اور وضو کر کے نماز پڑھ لے۔ تاہم غسل فرض ہے واجب نہیں صرف وضو بھی کفایت کر جائے گا جیسا کہ نبی صلی اللہ علیہ وسلم نے سیدہ فاطمہ بنت جحش سے کہا تھا۔ (دیکھئے سنن ابو داؤد، رقم: ٣٠٤)","",{"k":"صحیح بخاری (٣٠٦)، صحيح مسلم (٣٣٣)۔"}],[789,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اپنے مال کی حفاظت کرتا ہوا مارا جائے تو وہ شہید ہے۔“ یہ حدیث قتادہ سے صرف حجاج ہی روایت کرتے ہیں، اسے روایت کرنے میں ابو مالک الجبھی اکیلے ہیں۔ ٧٩٠","",{"k":"صحیح بخاری، والغصب (٢٤٨٠)۔"}],[790,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مشرق اور مغرب کے درمیان جو ہے وہ قبلہ ہے۔ یہ حدیث عثمان بن محمد سے صرف عبد اللہ بن جعفر ہی روایت کرتے ہیں۔ مذکورہ روایت سے معلوم ہوا کہ (مدینہ والوں کے لیے ) مشرق و مغرب کے مابین قبلہ ہے۔ مذکورہ حدیث سے معلوم ہوتا ہے کہ جو لوگ کعبہ سے دور دراز علاقوں میں ہوں ان پر عین قبلہ رخ ہونا واجب نہیں بلکہ ان کے لیے یہی کافی ہے کہ وہ اس سمت رخ کر لیں۔ امام احمد، مالک عبداللہ اور ایک روایت کے مطابق امام شافعی ہواللہ کا بھی یہی موقف ہے لیکن امام شافعی رحمہ اللہ سے ایک دوسری روایت یہ ہے کہ جو شخص دور ہواس پر بھی عین قبلہ رخ ہونا واجب ہے۔ (کتاب الام: ١/ - شرح فتح القدیر: ٢٣٤/١) لیکن پہلا قول ہی راجح ہے اور امام شوکانی، ابن قدامہ رحمہما اللہ کا بھی یہی موقف ہے۔ (نیل الاوطار: ٦٨٢/١ - المغنی ابن قدامه: ١٠٢/٢) ٧٩١","",{"k":"سنن ترمذی (٣٤٢)، سنن ابن ماجه (١٠١١)، قال الشيخ الالباني : صحيح۔"}],[791,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ذمی اور مسلمان کی دیت برابر ہے۔“ یہ حدیث نافع سے صرف ابوکرز ہی روایت کرتے ہیں،اسے روایت کرنے میں علی بن جعدا کیلئے ہیں۔ الله","",{"k":"ضعيف الجامع الصغير (٢٩٩٣)، كنز العمال (٤٠٠٦٢)، مجمع الزوائد (٦/٢٩٩)۔"}],[792,"سیدنا ابن عباس رضی اللہ عنہما نے اللہ تعالیٰ کے اس فرمان: ﴿وَمِمَّنْ حَوْلَكُم مِنَ الْأَعْرَابِ مُنَافِقُونَ وَمِنْ أَهْلِ الْمَدِينَةِ مَرَدُوا عَلَى النِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُمْ مَرَّتَيْنِ ثُمَّ يَرُدُّونَ إِلى عَذَابِ أَلِيمَ یعنی تمہارے ارد گرد دیہاتوں میں کچھ منافق ہیں اور شہر والوں میں سے کچھ لوگوں نے نفاق پر سرکشی کی آپ ان کو نہیں جانتے ہم انہیں جانتے ہیں ضرور انہیں دو دفعہ عذاب کریں گے پھر وہ دردناک عذاب کی طرف موڑے جائیں گے۔“ کی تفسیر کے متعلق بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جمعہ کے روز خطبہ ارشاد فرمانے کے لیے کھڑے تھے تو فرمایا: ”اے فلاں کھڑا ہو جا اور مسجد سے چلا جا کیونکہ تو منافق ہے۔ اے فلاں تو بھی نکل جا کیونکہ تو بھی منافق ہے۔ ان کے نام لے لے کر نکالا اور رسوا کیا، اس جمعہ پر سیدنا عمر ابھی نہیں آئے تھے شاید کسی کام کی وجہ سے نہیں آئے تو جب وہ مسجد سے نکل رہے تھے تو سیدنا عمر رضی اللہ عنہ ملے مگر اس شرم کی وجہ سے کہ وہ ابھی تک مسجد میں نہیں آئے ان سے چھپ گئی۔ کیونکہ انہوں نے خیال کیا کہ یہ سب نماز سے فارغ ہو چکے ہیں اور وہ بھی سیدنا عمر رضی اللہ عنہ سے چھپنے لگے کیونکہ وہ سمجھ رہے تھے کہ سیدنا عم رضی اللہ عنہ کو بھی ہمارے منافق ہونے کا پتہ چل گیا ہے۔ جب وہ مسجد کے اندر پہنچے تو دیکھا کہ لوگ ابھی نماز سے فارغ نہیں ہوئے تھے۔ انہیں ایک شخص نے کہا: اے عمر رضی اللہ عنہ خوش ہو جاؤ آج اللہ تعالیٰ نے منافقوں کو رسوا کر دیا ہے۔ یہ ان کے لیے پہلا عذاب تھا اور دوسرا عذاب قبر کا عذاب ہو گا۔ یہ حدیث سدی سے صرف اسباط بن نصر ہی روایت کرتے ہیں۔ وره","",{"k":"مجمع الزوائد (٧/٣٤)، فيه حسين بن عمرو وهو ضعيف۔"}],[793,"سيدنا عبد الرحمن بن سمرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم، صلی اللہ علیہ وسلم میں سے کوئی شخص کسی بات پر قسم کھائے پھر اس سے بہتر بات اس کو معلوم ہو جائے تو وہ اس بہتر بات کو اختیار کرے اور اپنی قسم کا کفارہ دے دے۔ یہ حدیث سلیمان التیمی سے صرف معتمر ہی روایت کرتے ہیں۔","",{"k":"صحیح مسلم (١٦٥٢)۔"}],[794,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، میں نے عرض کیا: اللہ کے رسول صلے علی تیم! نئے ڈھانکے ہوئے مٹکے سے وضو کرنا بہتر ہے یا پاک جگہوں سے؟ آپ ملٹے علیم نے فرمایا: ”پاک جگہوں سے۔ بے شک اللہ کا دین حنیف آسان اور سیدھا ہے۔ راوی کہتے ہیں ”نبی صلی اللہ علیہ وسلم پاک جگہوں کی طرف پہنچتے اور پانی لایا جاتا تو آپ صلی اللہ علیہ وسلم اسے پی لیتے اور آپ مسلمانوں کے ہاتھوں کی برکت کی امید کرتے تھے۔“ یہ حدیث عبد العزیز بن ابی ردّاد سے صرف حسن بن ابراہیم ہی روایت کرتے ہیں۔","",{"k":"المعجم الكبير للطبراني (١١١٦٨)، مجمع الزوائد (١/٢١٤)، صحيح الجامع الصغير (٤٨٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ پاک جگہوں پر جو پانی ہوتا ہے جس کا رنگ، بو اور ذائقہ نہ بدلا ہو اس کو پینا اور وضو کرنا جائز ہے۔ وہ پانی چشموں کا ہو یا اسی طرح بارش، برف اور اولوں کا پانی جیسا کہ ارشاد باری تعالی ہے وَانزَلْنَا مِنَ السَّمَاءِ مَاءً طَهُورًا﴾ (الفرقان: ٤٨) اور ہم آسمان سے پاک پانی نازل کیا۔“"}],[795,"سیدنا انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”یہ امت جب تک سچ بولے گی، انصاف پر مبنی فیصلے کرے گی اور جب اس سے رحم کی اپیل کی جائے تو وہ رحم کرے گی تو یہ ہمیشہ خیر پر رہے گی۔ یہ حدیث حضرت انس کے علاوہ کسی سے روایت نہیں ہے اور ثابت سے صرف اسحاق بن یحیی بن طلحہ ہی روایت کرتے ہیں، اسے روایت کرنے میں عبدالرحمن بن ابی الرحال اکیلے ہیں۔ ٧٩٦","",{"k":"مجمع الزوائد (٥/١٩٦)، مسند ابی یعلی (٤٠٤٠)، سنده ضعيف۔"}],[796,"سیدنا جابر بن عبد اللہ فی الین نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جبریل نے ھے حکم دیا کہ میں ایک گواہ کے ساتھ قسم پر فیصلہ کر دوں۔ ان الفاظ سے یہ حدیث کسی سے روایت نہیں ہے جنہوں نے جعفر بن محمد سے یہ روایت کی ہے کہ مجھے حضرت جبریل عالینا نے حکم دیا، سوائے ابراہیم بن ابی حیہ کے۔ مذکورہ حدیث سے معلوم ہوا کہ ایک گواہی اور قسم معتبر ہو گی۔ لیکن اصل یہ ہے کہ مدعی دومرد گواہ پیش کرے یا ایک مرد اور دو عورتیں بطور گواہ لائے کیونکہ قرآن میں ہے: وَاسْتَشْهِدُوْا شَهِيدَيْنِ مِنْ رِجَالِكُمْ فَإِنْ لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَ امْرَأَتُنِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَاءِ﴾ (البقرة: ٢٨٢) اپنے مردوں میں سے دو گواہ بنا لو پس اگر دو مرد نہ ہوں تو ایک مرد اور دوعورتیں جنہیں تم گواہوں میں سے پسند کرو۔“ لیکن اگر دو گواہ یا ایک مرد اور دو عورتیں نہ ہوں تو پھر ایک گواہ ہو تو جمہور کے نزدیک مالی معاملات میں ایک گواہ اور مدعی کی ایک قسم کے ساتھ فیصلہ کیا جا سکتا ہے جیسا کہ مذکورہ بالا حدیث سے واضح ہے۔ حافظ ابن حجر جداللہ فرماتے ہیں کہ اس معنی کی روایات بیان کرنے والے صحابہ کی تعداد٢٠ کے قریب ہے۔ (تلخيص الجير: ٢٠٦/٤) جمہور، امام مالک، شافعی، احمد نیم اسی کے قائل ہیں۔ البتہ احناف نے مذکورہ بالا قرآنی آیت کو پیش نظر رکھتے ہوئے کہا ہے کہ گواہ اور قسم کے ساتھ فیصلہ جائز نہیں کیونکہ اللہ ذوالجلال نے اس کا ذکر نہیں فرمایا۔ نیل الاوطار: ٣٧٩/٥ - كتاب الام: ٢٥٦/٦) حالانکہ جب ایک مسئلہ متعدد صحیح احادیث سے ثابت ہو رہا ہو تو اسے قبول کرنا واجب ہے لہذا جمہور کا موقف ہی راجح ہے۔ ( فتح الباری: ٦١٥/٥):٧٩٧ اور امام شوکانی جماللہ نے اسی کو ترجیح دی ہے۔ (نیل الاوطار: ٢٧٩/٥)","",{"k":"ممن صحيح مسلم (١٧١٢)، سنن ابو داؤد (٣٦٠٨)، سنن سنن ترمذی (١٣٤٣)۔"}],[797,"اور نبی سے کریم نے فرمایا: بدھ کا دن نحوست جاری رہنے کا دن ہے۔“ یہ حدیث جعفر بن محمد سے صرف ابراہیم بن ابی حیہ ہی روایت کرتے ہیں۔","",{"k":"السلسلة الضعيفة (٤/٨٠، ١٥٨١)، قال الشيخ الالباني : موضوع۔"}],[798,"سیدنا عبداللہ ابن عباس زینی پہنچا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم رمضان میں وتر کے علاوہ بیس رکعت پڑھتے تھے۔“ یہ حدیث حکم سے صرف ابو شیبہ ہی روایت کرتے ہیں، حضرت ابن عباس سے یہ حدیث اسی سند سے مروی ہے۔","",{"k":"المعجم الكبير للطبراني (١٠/٨٦، ١١٩٣٤)، مجمع الزوائد (٣/١٧٢)، فيه ابوشيبة ابراهيم بن عثمان وهو ضعيف، الضعفاء لابن عدى (١/٢٤٠)۔"}],[799,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، ابوطلحہ نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ بھوک کی وجہ سے اپنے پیٹ پر پتھر باندھے ہوئے ہیں تو انہوں نے جا کر اپنی بیوی سے کہا: ام سلیم! میں نے دیکھا ہے کہ نبی علی کریم اپنے پیٹ پر پتھر باندھے ہوئے ہیں اس لیے ان کے لیے کچھ کھانے کا انتظام کر دو۔ ام سلیم نے روٹی لی جتنا کہ جانور کا پاؤں لمبا چوڑا ہوتا ہے اتنی سی روٹی تھی۔ پھر ابوطلحہ نیا نین نے آپ کو بلایا اور نبی صلی اللہ علیہ وسلم نے روٹی لے لی، پھر ام سلیم بنی ہو یا ایک کپی لائی جس سے ایک گٹھلی کے برابر گھی نچوڑا اور اس کو آپ نے روٹی کا سالن بنایا، پھر اس میں برکت کی دعا کی پھر فرمایا: \"مسجد والوں کو بلاؤ تو ابوطلحہ رضی اللہ عنہ نے انہیں بلایا تو اس روٹی کو ستر آدمیوں نے کھایا پھر رسول اللہ میم نے اور گھر والوں نے وہ روٹی کھائی پھر آپ نے اس سے اپنی بیویوں کو بھی بھیجا تو بھی پہلے سے زیادہ بچ گیا۔ یہ حدیث یزید بن ابی منصور سے صرف سہل بن اسلم ہی روایت کرتے ہیں۔","",{"k":"سنن ترمذی (٣٦٣٠)، قال الشيخ الالباني صحيح۔","f":"(١) مذکورہ حدیث سے نبی مکرم سے ہم کامعجزہ ثابت ہوتا ہے۔\n(٢) یہ بھی ثابت ہوا کہ گھی بطور سالن استعمال کیا جا سکتا ہے۔\n(٣) نبی مکرم مام کا زہد و تقویٰ کا بھی اثبات ہوا کہ آپ نے پیٹ پر پتھر باندھے ہوئے تھے۔\n(٤) معلوم ہوا کہ بڑے لوگوں کو خود کھانے سے پہلے اپنے دیگر متعلقین کی بھی فکر کرنا ضروری ہے۔ بلکہ ان سب کو پہلے کھلانا اور بعد میں خود کھانا تا کہ کوئی بھی بھوکا نہ رہ جائے۔ اللہ تعالیٰ آج کل کے نام نہاد پیروں مرشدوں کو نیز علماء کو سب کو ان اخلاق حسنہ کو اپنانے کی توفیق عطا فرمائے۔ (آمین) ٨٠٠"}],[800,"سیدنا عبداللہ ابن عمر بنی اہلیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع کرتے تو بسم اللہ الرحمن الرحیم سے اس کی ابتداء کرتے تھے۔ یہ حدیث عبید اللہ سے صرف عبدالرحمن کے بھائی کے بیٹے ہی روایت کرتے ہیں، اسے روایت کرنے میں عتیق بن یعقوب اکیلے ہیں۔ ٨٠١","",{"k":"و، ه، المعجم الكبير للطبراني (١١/١٦٩)، مجمع الزوائد (٢/١٠٩)۔"}],[801,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے اپنے حافظے اور قوت یاداشت کی کمزوری کی شکایت کی تو آپ نے فرمایا: ” اپنی یاداشت پر اپنے دائیں ہاتھ سے مدد لو۔ “ یہ حدیث ابوصالح سے صرف خصیب بن جحد رہی روایت کرتے ہیں۔ ٠٢","",{"k":"لم سنن ترمذی (٢٦٦٦)، قال الشيخ و، و، و، الالباني، ضعیف، ضعيف الجامع الصغير (٨١٣)۔"}],[802,"سیدنا عبداللہ ابن عباس ولی پہنچا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک قبر پر (میت کے ) دفن ہونے سے دورات بعد نماز جنازہ پڑھی۔ جنہوں نے شیبانی سے روایت کیا، ان میں سے کسی نے بھی دو راتوں کا ذکر نہیں ہے، سوائے اسماعیل بن زکریا کے، اسے روایت کرنے میں محمد بن صباح اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ دفن ہونے کے بعد اگر کچھ دن گزر جائیں تو بھی اس کی","",{"k":"کر صحیح مسلم (٩٥٤)۔","f":"قبر پر نماز جنازہ پڑھانا جائز ہے۔"}],[803,"سيدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک یہ مال ( دنیا ) سرسبز اور میٹھا ہے۔ پس جس نے اس کے حق کے ساتھ اسے لیا تو یہ بہترین مدد گار ثابت ہوگا۔“ اس حدیث کو مالک بن انس سے صرف معن بن عیسی نے روایت کیا ہے۔ ٨٠٤","",{"k":"٦٤٢٧ ٢٤٢٢) صحيح البخاري، رقم: صحیح مسلم (١٢٢/١٠٥٢)۔"}],[804,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ سیدہ ام سلیم بنی النما کو طواف افاضہ کے بعد حیض آ گیا تو نبی صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ کوچ کریں۔“ یہ حدیث قتادہ سے صرف سعید ہی روایت کرتے ہیں، اسے روایت کرنے میں عباد بن عوام اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ حائضہ عورت طواف افاضہ کر چکی ہو تو طواف وداع کیسے بغیر واپس جاسکتی ہے۔ جیسا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو حکم دیا کہ سب سے آخر میں تمہارا عمل بیت اللہ کا طواف ہو مگر ایام ماہواری والی عورت کے لیے تخفیف کی گئی ہے۔ (صحیح بخاری، کتاب الحج، رقم: ١٧٥٥) اسی طرح سیدہ عائشہ بنا لیا حائضہ ہو گئیں تو نبی سے ہم نے انہیں فرمایا: ”تم (طواف وداع کے بغیر ہی) نکلو۔ (صحیح بخاری، کتاب الحيض، رقم: - صحیح مسلم، رقم: ١٣٢٩)","",{"k":"مسند أبي يعلى (٣٠٨٣)، شرح معانی الآثار للطحاوي (٢/٢٣٣، ٤٠٥٤)، مجمع الزوائد (٢٨١٣)، ارواء الغليل (٤/٢٦٢)۔"}],[805,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی میم نے فرمایا: ” اگر لوگ جان لیں کہ بدھ کی رات نماز عشاء کی کیا فضیلت ہے تو وہ اس میں ضرور حاضر ہوں خواہ گھٹنوں کے بل چل کر آنا پڑے۔“ اسے ہشام بن عروہ سے صرف زکریا بن منظور ہی روایت کرتے ہیں، اسے روایت کرنے میں عقیق یعقوب اکیلے ہیں۔ ٨٠٦","",{"k":"مجمع الزوائد (٢/٣٩)، كنز العمال (١٩٤٩٢)، فيه ابن منظور وهو ضعيف۔"}],[806,"سیدنا قیس بن ابی حازم نے بیان کیا، میں سیدنا ابو بکر رضی اللہ عنہ کے پاس گیا تو آپ کے پاس ایک آدمی آیا، وہ کہنے لگا: اے اللہ کے رسول ملتے ییم! کے خلیفہ یہ شخص میرا سارا مال لے کر اسے تباہ کرنا چاہتا ہے۔ سیدنا ابو بکر رضی اللہ عنہ نے اسے فرمایا: تم کیا کہنا چاہتے ہو؟ وہ کہنے لگا: جی ہاں! یہی بات ہے تو سیدنا ابو بکر ی لیون نے کہا: تیرے لیے اس کے مال سے صرف اتنا مال لینا درست ہے جو تجھے کافی ہو۔ اس نے کہا: اے رسول اللہ عل علم کے خلیفہ! کیا نبی تعلیم نے یہ نہیں فرمایا کہ تو اور تیرا مال تیرے باپ کا ہے۔ سیدنا ابو بکر ضی اللہ نے جواب دیا تم اس چیز پر راضی ہو جاؤ جو اللہ تعالیٰ تمہارے لیے پسند کرتا ہے۔“ یہ حدیث اسماعیل بن ابی خالد سے صرف منذر بن زیاد ہی روایت کرتے ہیں۔ اند حدیث سے معلوم ہوا کہ والدین کو بغیر کسی اجازت کے اپنی اولاد کی کمائی سے اپنی ضروریات پوری کرنے کا حق حاصل ہے مگر اس معاملے میں کسی جانب سے بھی افراط و تفریط نہیں ہونا چاہیے۔ مذکورہ حدیث سے یہ مفہوم کشید کرنا جائز نہیں کہ بیٹے کا مال کلی طور پر باپ ہی کا ہے بلکہ اسی حد تک جائز ہے کہ اپنی لازمی ضروریات لے لے۔ اللہ کی شریعت میں ان دونوں کی ملکیت اور تصرف علیحدہ علیحدہ ہے اسی بنا پر ان میں وراثت چلتی ہے اگر ملکیت اور تصرف میں فرق نہ ہو تو وراثت کے کوئی معنی نہ ہوں گے۔ لہذا اولاد کی کمائی کو بے دردی سے خرچ کر کے اسے اجاڑ نا جائز نہیں ہے۔","",{"k":"السنن الكبرى للبيهقى ٤٨١٧ (١٥٥٣٢)، ارواء الغليل (٣٣٢٨)، کنز العمال (٤٥٩٢٧)، مجمع الزوائد (٤/١٥٦)۔"}],[807,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس ذات کی قسم جس کے ہاتھ میں میری جان ہے تم سب جنت میں جاؤ گے مگر جس نے انکار کیا اور اللہ تعالیٰ سے اونٹ کی طرح بدکنے اور بھاگنے لگا۔ صحابہ نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم جنت میں جانے سے کون انکار کرتا ہے؟ آپ نے فرمایا: ”جس نے میری اطاعت کی وہ جنت میں داخل ہو گا اور جس نے میری نافرمانی کی وہ جہنم میں داخل ہوگا۔“ یہ حدیث شعبہ سے صرف ابوسعید ہی روایت کرتے ہیں، اسے روایت کرنے میں ابو عبیدہ بن فضیل اکیلے ہیں۔","",{"k":"سنن ابن ماجة (١٠٦٧)، مجمع الزوائد (٢/١٥٤)، قال الشيخ الالبانی: حسن صحیح۔"}],[808,"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! تم سب جنت میں جاؤ گے مگر جس نے انکار کیا اور اللہ تعالیٰ سے اونٹ کی طرح بدکنے اور بھاگنے لگا۔ صحابہ دینی ایم نے کہا: یا رسول اللہ ملنے کی تم جنت میں جانے سے انکار کون کرتا ہے؟ آپ نے فرمایا: ”جس نے میری اطاعت کی وہ جنت میں داخل ہوگا اور جس نے میری نافرمانی کی وہ جہنم میں داخل ہوگا۔ “ یہ حدیث علاء بن مسیب سے صرف خلف بن خلیفہ ہی روایت کرتے ہیں۔","",{"k":"مستدرك حاكم (٤/٢٧٦، ٧٦٢٧)، مسند احمد (٥/٢٥٨، ٢٢٢٨٠)، اسناده حسن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کی اطاعت کرنے والا جنت میں جائے گا جب کہ نافرمانی کرنے والا جہنم میں۔ جیسا کہ ارشاد باری تعالیٰ ہے: ि مَنْ يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنْتٍ تَجْرِى مِنْ تَحْتِهَا الْأَنْهَرُ خَلِدِينَ فِيْهَا وَ ذَلِكَ الْفَوْزُ الْعَظِيمُ ٥﴾ (النساء: ١٣) ”جو شخص اللہ اور اس کے رسول ملے یکم کی اطاعت کرے گا اللہ تعالیٰ اس کو جنت میں داخل کرے گا ایسی جنت جس کے نیچے نہریں چلتی ہیں وہ اس میں ہمیشہ رہیں گے، یہ بہت بڑی کامیابی ہے۔“ ارشاد باری تعالیٰ: يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى النَّارِ يَقُولُونَ يُلَيْتَنَا أَطَعْنَا اللَّهَ وَأَطَعْنَا الرَّسُوْلاه وَقَالُوا رَبَّنَا إِنَّا أَطَعْنَا سَادَتَنَا وَكُبَرَاءَنَا فَأَضَلُوْنَا السَّبِيلَاهِ رَبَّنَا آتِهِمْ ضِعْفَيْنِ مِنَ الْعَذَابِ وَالْعَنْهُمْ لَعْنًا كَبِيرًا﴾ (الاحزاب: ٦٦ تا ٦٨) جس دن ان کے چہرے آگ میں الٹ پلٹ کئے جائیں گے بڑے افسوس سے کہیں گے کاش ہم اللہ اور رسول ملے یکم کی اطاعت کرتے، کہیں گے اے رب! ہم نے اپنے سرداروں اور بڑوں کی مانی، انہوں نے ہمیں سیدھے راستہ سے گمراہ کر دیا، اے ہمارے رب ان کو دگنا عذاب کر اور ان پر بڑی لعنت فرما۔“ ٠٩"}],[809,"سیدنا براء بن عازب نے بیان کیا، رسول اللہ علیم نے فرمایا: ”جمعہ کے روز غسل کرنا مسلمانوں پر حق ہے، اور یہ کہ آدمی اپنے اہل خانہ کی خوشبو میں سے خوشبو لگائے۔ میں نے عرض کیا: یا رسول اللہ نے تم جو شخص خوشبو نہ پائے؟ تو آپ نے فرمایا: ” پانی بھی خوشبو ہے۔“ یہ حدیث حضرت براء سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں یزید بن ابی زیادا کیلے ہیں۔ مذکورہ روایت کے آخری الفاظ خوشبو نہ ملے تو پانی استعمال کریں، صحیح سند سے ثابت نہیں ہے۔ مذکورہ روایت سے معلوم ہوا کہ غسل کرنا، اور جمعہ کے لیے خوشبو کا استعمال مستحب ہے اگر خوشبو نہ ہو تو بیوی کی ہی خوشبو استعمال کر لیں۔ جیسا کہ ایک اور حدیث میں ہے کہ سیدنا سلمان ضیا لینے سے مروی ہے رسول اللہ ایم نے فرمایا: \"جو شخص جمعہ کے دن غسل کرے، نہایت مبالغہ آرائی کے ساتھ پاکیزگی اختیار کرے، تیل لگائے یا گھر کی خوشبو لگائے پھر جمعہ کی نماز کے لیے نکلے اور دو انسانوں کے درمیان تفریق نہ کرے ( یعنی ان کے درمیان نہ بیٹھے ) پھر جس قدر ( نوافل ) اس کے مقدر میں ہیں ادا کرے پھر امام کے خطبہ دینے کے وقت خاموش رہے تو اس کے وہ گناہ جو اس جمعہ اور دوسرے جمعہ کے درمیان ہیں معاف کر دیے جاتے ہیں۔ الله (صحیح بخاری، رقم","",{"k":"مسند احمد (٤/٢٨٣)، سنن ابو داؤد (٣٤٤)۔"}],[810,"سيدنا محمد بن حنفیہ کہتے ہیں میں نے اپنے باپ ( علی رضی اللہ عنہ سے پوچھا: نبی صلی اللہ علیہ وسلم کے بعد سب سے بہتر شخص کون ہے؟ تو انہوں نے کہا: ابوبکر، میں نے کہا: پھر کون؟ تو اس نے کہا: ان کے بعد عمر ہیں۔“ یہ حدیث از اعمش از حسن بن عمرو اور محمد بن قیس، ابی حصین سے صرف منصور ہی روایت کرتے ہیں اور منصور سے صرف سعید بن سالم ہی روایت کرتے ہیں، اسے روایت کرنے میں احمد بن یونس اکیلے ہیں۔","",{"k":"ابو داؤد، رقم : ٤٦٢٩ . صحیح بخاری، سنن۔","f":"مذکورہ حدیث سے معلوم ہوا کہ ابو بکر و عمر نیای اینجا کی عظمت کا اقرار اہل بیت بھی کیا کرتے تھے اور ان کی افضلیت اور مسلمانوں میں ان کے مقام و مرتبہ سے بخوبی آگاہ تھے جیسا کہ سیدنا علی بنی اہلیہ نے صراحت سے ارشاد فرمایا۔"}],[811,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنا کپڑا بچھاؤ“ میں نے بچھا دیا تو آپ نے اکثر دن مجھ سے باتیں فرمائیں پھر میرے کپڑے میں تھوکا پھر میں نے اپنا کپڑا اپنے پیٹ کے ساتھ ملا لیا تو میں اس کے بعد کبھی کوئی چیز نہیں بھولا۔ عمرو بن عبد اللہ الجند عی، حضرت ابو ہریرہ صلی اللہ سے اس کے سوا کوئی روایت نہیں کرتے، اسے روایت کرنے میں عبداللہ بن عبدالعزیز ا کیلئے ہیں۔ اند. مذکورہ حدیث سے سیدنا ابو ہریرہ ضیا لینے کی فضیلت ثابت ہوتی ہے کہ نبی مکرم علی علیم نے ان کے لے برکت کی دعا فرمائی۔ نبی مکرم ملنے یام کی دعا سے سیدنا ابو ہریرہ بیانیہ کا حافظہ تیز ہو گیا اور پانچ ہزار سے زائد احادیث کے حافظ قرار پائے، حالانکہ سیدنا ابو ہریرہ بنی این خیر کے موقع پر مسلمان ہوئے تھے اڑھائی تین سال صحبت نبوی سے فیض یاب ہونے کا موقع ملا اگر چہ یہ مدت کم ہے لیکن اس مدت میں سفر وحضر، خلوت و جلوت میں ہر لمحہ نبی مکرم صلے علم کے ساتھ رہے۔اور دین کا بہت بڑا حصہ محفوظ کر لیا۔","",{"k":"فائده مسند احمد (٢/٣٣٣)، قال الشیخ شعیب الارناؤط: صحیح۔"}],[812,"سيدنا جریر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جس نے سانپ دیکھا پھر اس سے ڈرتے ہوئے اس کو نہ مارا تو وہ مجھ سے نہیں ہے۔“ یہ حدیث ابراہیم بن جریر سے صرف داؤد بن عبدالجبار ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد (٥٢٤٩)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سانپوں کو مارنا چاہیے۔ معلوم ہوا کہ صاحب ایمان کو جرات مند اور بہادر ہونا چاہیے اور اپنے دشمن سے خواہ وہ انسانی ہو یا حیوانی کسی طرف خوف زدہ نہیں ہونا چاہیے بلکہ اللہ تعالیٰ پر توکل کرنا چاہیے۔ اسی طرح ان کے بدلے سے بھی نہیں ڈرنا چاہیے۔"}],[813,"سیدنا عرفجہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فجر کی نماز پڑھائی پھر فرمایا: ” آج رات میرے صحابہ کو تولا گیا تو سیدنا ابو بکر ضیا الہ یہی سب سے بھاری ہو گئے پھر عمر یا الیہ کو تو لا گیا تو وہ بھاری ہو گئے پھر سیدنا عثمان رضی اللہ عنہ تو لا گیا تو وہ بھاری ہو گئے۔ یہ حدیث عرفجہ سے صرف اسی سند سے مروی ہے اسے روایت کرنے میں عبد الا علی بن ابی المساورا کیلئے ہیں۔ الله","",{"k":"مسند احمد (٤/٦٣)، مجمع الزوائد (٩/٥٩)، سنده صحیح۔","f":"مذکورہ حدیث سے درجہ بدرجہ صحابہ کرام کی فضیلت کا اثبات ہے معلوم ہوا سیدنا ابو بکر ال یہ سارے صحابہ سے افضل تھے، ان کے بعد سیدنا عمر رضی اللہ عنہ پھر ان کے بعد سیدنا عثمان رضی اللہ عنہ اسی طرح سیدنا عبد اللہ بن عمر بنی النہا سے روایت ہے کہ ہم کہا کرتے تھے جبکہ رسول اللہ صلی اللہ علیہ وسلم حیات تھے، نبی صلی اللہ علیہ وسلم کی امت میں آپ کے بعد سب سے افضل ابوبکر ہیں پھر عمر اور پھر عثمان می بسم اللہ ان سب سے راضی ہو۔ (سنن ابی داؤد، رقم: ٤٦٢٨ اسنادہ صحیح) ٨١٤"}],[814,"سیدنا انس نبی الیہ نے بیان کیا، میں سواری پر ابوطلحہ کے پیچھے بیٹھا تھا اور ان کا گھٹنا نبی صلی اللہ علیہ وسلم کے گھٹنے کے ساتھ لگ رہا تھا اور وہ دونوں بلند آواز سے حج اور عمرے دونوں کا تلبیہ پکار رہے تھے۔“ یہ حدیث ایوب، حمید بن ھلال سے صرف عبید اللہ بن عمر وہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ایک سواری پر دو آدمی بیٹھ سکتے ہیں بشرطیکہ سواری دوکا بوجھ اٹھا سکتی ہو۔ یہ بھی معلوم ہوا کہ مردوں کو اونچی آواز سے تلبیہ کہنا چاہیے جیسا کہ دوسری حدیث میں ہے رسول اللہ صلے میریم نے فرمایا: میرے پاس جبریل تشریف لائے: ((فامرنى ان امرا صحابي ان يرفعوا اصواتهم بالاهلال)) اور مجھے حکم دیا کہ میں اپنے ساتھیوں کو بلند آواز سے تلبیہ کہنے کا حکم دوں۔“ (صحيح سنن ابن ماجه رقم: سلسلة الصحيحه، رقم: ١٥٠٠) بلکہ بلند آواز سے تلبیہ کہنا اجر میں اضافے کا باعث ہے جیسا کہ سیدنا ابو بکر رضی اللہ عنہ سے مروی ہے رسول اللہ مل نیم سے دریافت کیا گیا کون سا حج افضل ہے؟ آپ ملے لی تم نے فرمایا: ((العج والثج)) جس میں بلند آواز سے تلبیہ پکارا جائے اور قربانی دی جائے۔“ ٨١٥","",{"k":"مسلم، رقم : ١٤٢٨ . صحيح بخارى، صحيح۔"}],[815,"سيدنا ابوسعید خدری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے ایک خوفناک آواز سنی جس سے وہ ڈر گئے جبریل عالی نام آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا جبریل یہ کیا آواز تھی؟ انہوں نے کہا: یہ ایک چٹان ہے جو جہنم کے کنارے سے ستر سال بعد گہرائی میں گری تو اللہ تعالیٰ نے یہ پسند فرمایا کہ اس کی آواز آپ کو سنا دی جائے اس کے بعد رسول اللہ صلی اللہ علیہ وسلم فوت ہونے تک کبھی بھی منہ بھر کر ہنستے ہوئے دکھائی نہیں دیئے۔“ والله مسلم شریف کی حدیث میں ہے سیدنا ابو ہریرہ ضیا یہ فرماتے ہیں ایک دفعہ ہم رسول اللہ الے علیم کے ساتھ تھے اچانک دھماکے کی آواز سنی رسول اللہ علیم نے دریافت فرمایا ”جانتے ہو یہ آواز کیسی ہے؟“ راوی کہتے ہیں ہم نے عرض کیا اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا ”یہ ایک پتھر تھا جو آج سے ستر سال پہلے جہنم میں پھینکا گیا تھا اور آگ میں گرتا چلا جا رہا تھا حتی کہ اب جہنم کی تہ تک پہنچا ہے۔“ (صحیح مسلم، کتاب الجنه وصفه، باب جهنم اعاذنا الله منها) معلوم ہوا جہنم اتنی گہری ہے کہ ستر سال تک پتھر گرتا رہے تب اس کی تہہ تک پہنچتا ہے حالانکہ بہت زیادہ اونچی جگہ سے کسی وزنی چیز کو نیچے پھینکا جائے تو چند منٹوں کے اندر وہ نیچے آ جاتی ہے۔ ٨١٦","",{"k":"سنن ترمذى كتاب صفة جهنم (٢٥٧٥)، مجمع الزوائد (١٠/٣٨٩)، ضعيف الترغيب والترهيب (٢١٤٦)۔"}],[816,"سیدنا ابو ہریرہ فی الین نے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب فجر طلوع ہو جائے تو فجر کی دو رکعت کے علاوہ کوئی نماز نہیں ہوتی۔“ یہ دونوں حدیثیں یحیی بن سعید سے صرف اسماعیل بن قیس ہی روایت کرتے ہیں، ان سے روایت کرنے میں احمد بن عبدالصمدا کیلئے ہیں۔ معلوم ہوا طلوع فجر کے بعد نماز فجر کے علاوہ کوئی نماز نہیں پڑھنا چاہے۔","",{"k":"سنن ترمذی (٤١٩)، قال الشيخ الالباني: صحيح۔"}],[817,"سیدنا عبداللہ ابن عباس زنی اشیا نے بیان کیا، جب رسول اللہ صلی اللہ علیہ وسلم نے بنو نضیر کو مدینہ سے نکال دینے کا حکم دیا تو ان کے کچھ لوگ آپ صلی اللہ علیہ وسلم کے پاس آئے تو انہوں نے عرض کیا، ہمارے کچھ قرضے ہیں ابھی ان کا وقت نہیں ہوا تو آپ ملنے سلیم نے فرمایا: ” ان سے کچھ کم کر کے وقت سے پہلے لے لو۔“ یہ حدیث عکرمہ سے صرف علی بن محمد بن طلحہ بن یزید بن رکا نہ ہی روایت کرتے ہیں، اسے روایت کرنے والے مسلم بن خالد ا کیلے ہیں","",{"k":"للعقيلي: ٢٥١/٣ . ع الزوائد (١٣٠/٤)، السنن الكبرى للبيهقي (٦/٢٨)، الضعفاء مجمع۔"}],[818,"سیدنا عبد اللہ ابن عم رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: ” مسافر پر عبداللہ جمعہ لازم نہیں ہے۔“ یہ حدیث نافع سے صرف اُن کے بیٹے عبداللہ ہی روایت کرتے ہیں، اسے روایت کرنے میں ابوبکر حنفی اکیلے ہیں۔","",{"k":"صحيح الجامع الصغير (٥٤٠٥)، ارواء الغليل (٦١/٣)۔","f":"مذکورہ روایت سے معلوم ہوا کہ مسافر پر جمعہ فرض نہیں اگر وہ پڑھ لے تو کوئی حرج نہیں۔ مذکورہ روایت کی سند میں کچھ علماء اختلاف کرتے ہے وہ فرماتے ہیں مسافر پر بھی جمعہ فرض ہے مسافر پر جیسا کہ ابن حزم جماللہ کا موقف ہے۔ (المحلى بالاثار: ٢٥٢/٢) جبکہ جمہور علماء کا کہنا ہے مسافر پر جمعہ واجب نہیں۔ ان کی دلیل یہ ہے کہ رسول اللہ علی علیم نے دوران حج جمعہ نہیں بلکہ ظہر پڑھی تھی۔ (نیل الاوطار: ٥٠٥/٢ سبل السلام: ٥٩/٢) اور یہی موقف راجح معلوم ہوتا ہے کہ سعودی فتوی کمیٹی نے بھی یہی فتویٰ دیا ہے۔ (فتاوی اسلامیہ: ١/ ٣٩٧)"}],[819,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صل علی تم نے فرمایا: ”جس نے مغرب کے بعد چھ رکعتیں پڑھیں، ان کے درمیان کوئی کلام نہ کیا تو وہ اس کے لیے بارہ سال کی عبادت کے برابر بنادی جائیں گی۔“ یہ حدیث یحییٰ بن ابی کثیر سے صرف عمر بن عبداللہ ہی روایت کرتے ہیں، اسے روایت کرنے میں زید بن حباب اکیلے ہیں۔","",{"k":"سنن ترمذی (٤٣٥)، سنن ابن ماجه (١١٦٧)، قال الشيخ الالباني: ضعيف۔"}],[820,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما اور سیدنا عبد اللہ ابن عباس رضی اللہ عنہما تعالیٰ کے فرمان: وصالح المؤمنین کے متعلق فرماتے ہیں کہ یہ ابو بکر اور عمر بن انشا کے متعلق نازل ہوئی۔“ یہ حدیث میمون بن مہران سے صرف فرات بن سائب ہی روایت کرتے ہیں۔:٨٢١ ٢١","",{"k":"مجمع الزوائد (٧١٢٧)، سنده ضعيف۔"}],[821,"سیدنا سلمان فارسی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سلمان کیا تم جانتے ہو کہ جمعہ کیا ہے؟“ تین دفعہ فرمایا: میں نے کہا: اللہ تعالیٰ اور اس کے رسول زیادہ جانتے ہیں۔ آپ نے فرمایا: ” تمہارے والد آدم علینام جمع کیے گئے مگر میں تم کو جمعے کے متعلق بتاتا ہوں جو شخص جمعے کی نماز کو آئے، پھر اسی طرح وضو کرے، جس طرح حکم دیا گیا، پھر پیدل چل کر مسجد کو جائے پھر خاموش رہے یہاں تک کہ نماز سے فارغ ہو جائے تو یہ جمعہ اس سے پہلے جمعہ تک کے لیے کفارہ بن جائے گا۔‘“ یہ حدیث منصور سے صرف عمرو بن ابی قیس اور جریر بن عبد الحمید ہی روایت کرتے ہیں۔ مذکورہ حدیث میں جمعہ کی فضیلت کا اثبات ہے۔ یعنی ایک جمعہ سے لے کر دوسرے جمعہ تک کے (صغیرہ ) گناہوں کا کفارہ بن جاتا ہے۔ وضو کرے جس طرح حکم دیا گیا یعنی سنت کے مطابق وضو کرے۔ ایک حدیث میں ہے سیدنا ابو ہریرہ بیانیہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو غسل کرے پھر جمعہ کے لیے (مسجد میں ) آئے پھر جتنی اس کے مقدر میں ہو نماز پڑھے پھر امام کے خطبہ سے فارغ ہونے تک خاموش رہے پھر اس کے ساتھ نماز ادا کرے تو اس کے دونوں جمعوں کے درمیانی گناہ بخش دیے جاتے ہیں اور مزید تین (٣) دن کے بھی۔ (صحیح مسلم، کتاب الجمعة، رقم: ٨٥٧، سنن ابی داؤد، رقم: ٣٤٣) معلوم ہوا مکمل اہتمام اور مسنون طریقے سے جمعہ ادا کرنے والوں کی بہت زیادہ فضیلت ہے",""],[822,"سیدنا عبد اللہ بن علی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلمن کی وفات سے ایک ماہ پہلے آپ کا یہ مکتوب ہمارے پاس آیا: کسی مردار کے چمڑے یا پٹھوں سے","",{"k":"سنن ابو داؤد، رقم: (٤١٢٨)، سنن ترمذی (١٧٢٩)، قال الشيخ الالباني: صحيح۔","f":"نہ اٹھاؤ۔“ یہ حدیث اشعث سے صرف عبد اللہ بن اور لیس ہی روایت کرتے ہیں، اسے روایت کرنے میں عمر و بن محمد الناقد ا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مردار کا چمڑا اور اس کے پٹھے بھی نجس ہیں۔ یہ اس صورت فائدة میں ہے جب کہ چھڑے کو رنگ نہ دیا گیا ہو کیوں کہ چمڑا رنگنے سے پاک ہو جاتا ہے۔ جیسا کہ نبی مکرم صلے علیم نے فرمایا: ”جس چمڑے کو رنگ دیا جائے وہ پاک ہو جاتا ہے۔“ (صحيح سنن ابن ماجه، کتاب اللباس، رقم: - سنن ترمذی، رقم: ١٧٢٨) مالکیہ، حنابلہ، شافعیہ اور حنفیہ کا یہی موقف ہے۔ (بداية المجتهد: ٧٦/١ المغنى: ٦٦/١) امام شوکانی براللہ اور شیخ البانی رحمہ اللہ بھی اسی کے قائل ہیں۔ (تمام المنة: ص ٤٩)"}],[823,"سیدنا ابو ہریرہ ضیا علینہ نے بیان کیا، رسول اللہ تعلیم نے فرمایا: ”ہر چیز کی کوئی غیر مفید چیز ہوتی ہے، اور مسجد کی غیر مفید چیز لغو اور بیہودہ قسمیں کھانا ہے جیسے نہیں اللہ کی قسم! ہاں، اللہ کی قسم! “ یہ حدیث زہری سے صرف عقیل اور عقیل سے صرف رشدین ہی روایت کرتے ہیں۔ ٨٢٤","",{"k":"المعجم الكبير للطبرانی (١٩/١٣٩)، ضعيف الجامع الصغير (١٩٣٦)، مجمع الزوائد (٢/٢٤، ٠)، مسند ابی یعلی (٤٠١٠٩٠)۔"}],[824,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک بچہ لایا گیا اس نے آپ پر پیشاب کر دیا تو آپ نے اس پر پانی چھڑک دیا اور ایک لڑکی لائی گئی اس نے آپ پر پیشاب کر دیا تو آپ نے اس کو دھو دیا۔ یہ حدیث عمرو بن شعیب از والد خود از جد خود صرف حضرت اسامہ بن زید ہی روایت کرتے ہیں، اسے روایت کرنے میں عبداللہ بن موسیٰ اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ شیر خوارگی کی عمر میں لڑکے اور لڑکی کے پیشاب کا حکم مختلف ہے لیکن اس واضح اور صحیح حدیث کے باوجود بعض مکاتب فکر نے اس کے برعکس رائے اختیار کی ہے۔ مثلاً حنفیہ اور مالکیہ کہتے ہیں دودھ پیتے لڑکے اور لڑکی دونوں کے پیشاب کو دھونا لازم ہے۔ (بداية المجتهد: ٧٧/١) اسی طرح امام اوزاعی رحمہ اللہ اور ایک قول کے مطابق امام مالک، شافعی رحمہما اللہ کے نزدیک بھی دونوں کے پیشاب پر صرف چھٹیں مارنا ہی کافی ہے۔ (شرح زرقانی علی مؤطا: ١/١) یہ دونوں آراء گذشتہ صحیح حدیث کے خلاف ہونے کی بنا پر نا قابل عمل ہیں اور وہی بات درست ہے جو مذکورہ حدیث میں ہے۔","",{"k":"المعجم الكبير للطبراني (١٨/٣٤٢، ٢٠٩١٦)، مجمع الزوائد: ١/۔"}],[825,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ” قریب ہے کہ کچھ لوگ قرآن مجید پڑھیں گے وہ اس کو اس طرح پئیں گے جس طرح پانی پیتے ہیں مگر وہ ان کے حلق سے نیچے نہیں اترے گا۔ پھر آپ نے اپنا ہاتھ اپنے حلق پر رکھا اور فرمایا: ”یہاں سے نیچے نہیں جائے گا۔‘ یہ حدیث عطاء بن سائب سے صرف عمرو بن ابی قیس ہی روایت کرتے ہیں۔","",{"f":"مذکورہ حدیث سے معلوم ہوا کہ قرآنی آیات کی منافقانہ تلاوت کرنے والوں پر قرآن اثر نہیں کرتا۔ ہمارے زمانے میں یہی حال ہے قرآن پڑھنے کو تو سینکڑوں آدمی ہیں لیکن اس کے معنی اور مطلب میں غور کرنے والے بہت تھوڑے ہیں۔ اور بعض شیاطین کا تو یہ حال ہے کہ وہ قرآن وحدیث کا ترجمہ پڑھنے پڑھانے ہی سے منع کرتے ہیں۔ ٢٦"}],[826,"سیدہ عائشہ بین النہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے حج کے متعلق انہیں فرمایا: ” تیرا اجر تیرے خرچ کرنے کے مطابق ہو گا۔“ یہ حدیث سفیان سے صرف مہران ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا حج وعمرہ میں جتنی تکلیف ہو گی اتنا ہی ثواب زیادہ ہوگا۔ لیکن یہ کوئی اصول نہیں ہے کہ جس عبادت میں زیادہ مشقت ہو گی ثواب بھی اسی کا دوسری عبادات سے زیادہ ہوگا لیکن بعض عبادتوں میں دوسری عبادتوں سے تکلیف اور مشقت کم ہوتی ہے بلکہ ثواب زیادہ ملتا ہے، جیسے لیلتہ القدر میں عبادت کرنا، رمضان کی راتوں میں عبادت کرنے سے ثواب زیادہ ہے۔ فرض نماز یا فرض زکاۃ کا ثواب نفلی نمازوں اور نفلی صدقات سے زیادہ ہے۔","",{"k":"صحیح بخاری (١٧٨٧)، مسند ابو عوانه ٤٩٥/٦ (٢٥٦٩)۔"}],[827,"حارث الاعور الہمدانی نے بیان کیا، میں علی بن ابی طالب رضی اللہ عنہ کے پاس تھا کہ سیدنا طلحہ بن عبید اللہ رضی اللہ عنہ کا بیٹا آیا تو سیدنا علی ضیا اہلیہ نے اسے کہا: بھتیجے! خوش آمدید! میرے پاس آؤ! تو اسے اپنے قریب بٹھایا پھر فرمایا: اللہ کی قسم! مجھے امید ہے کہ میں اور تمہارا والد طلحہ ان لوگوں سے ہوں گے جن کے متعلق اللہ نے فرمایا: ﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِل اور ہم نے ان کے دلوں میں جو کینہ تھا وہ نکال دیا۔ یہ حدیث نعیم بن ابی ھند سے صرف جابر بن یزید بن رفاعہ روایت کرتے ہیں۔ / / ٨:٢٨","",{"k":"السنن الكبرى للبيهقي (١٧٣/٨)، الضعفاء العقيلي (١/٢١٠)، کنز ٤٤٦٩ : العمال (٩)۔"}],[828,"سیدہ عائشہ منی الجھا نے فرمایا: ”ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے تین برتن ڈھانپ کر رکھتے تھے (١) ایک آپ کے وضوء کے لیے (٢) ایک آپ کی مسواک کے لیے (٣) اور ایک آپ کے پینے کے لیے۔ یہ حدیث ابن ابی ملیکہ سے صرف حریش ہی روایت کرتے ہیں، ان سے روایت کرنے میں حرمی اکیلے ہیں۔ ٨٢٩","",{"k":"سنن ابن ماجه، رقم : ٣٦١ قال الشيخ الالباني ضعيف۔"}],[829,"عبد الله بن عبداللہ بن عتبہ نے بیان کیا، نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ میمونہ بنا اینجا نے کسی سے تین سو درہم قرض لیا تو انہیں ان کے گھر والوں نے کہا: تم ادھار تو لے رہی ہولیکن اس کی ادائیگی کے لیے تمہارے پاس کچھ نہیں۔ تو انہوں نے کہا: میں نے رسول اللہ میم کو فرماتے ہوئے سنا: ”جو شخص قرض لے اور دل میں یہ سوچے کہ میں اسے ادا کروں گا تو اللہ اس کی ادائیگی میں اُس کی مدد فرماتا ہے۔“ یہ حدیث اعمش سے صرف محمد بن ابی عبیدہ اور جریر بن عبدالحمید ہی روایت کرتے ہیں۔","",{"k":"سنن نسائی (٤٦٨٧)، قال الشيخ الالباني: صحيح، المعجم الكبير للطبراني (١٧/٢٤٧)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جو قرض کی ادائیگی کی کوشش کرتا ہے تو اللہ تعالیٰ بھی اس آدمی کے لیے آسانیاں پیدا فرما دیتا ہے۔ ٨٣٠"}],[830,"کعب احبار کہتے ہیں میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے کہا: میں ایسے لوگوں کو جانتا ہوں کہ اگر ان پر یہ آیت نازل ہوتی تو وہ اس کا دن دیکھ کر اس (دن) کو عید بنا لیتے۔سیدنا عمر رضی اللہ عنہ نے کہا: وہ کون سی آیت ہے؟ انہوں نے کہا: وہ یہ آیت ہے: ﴿ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ الآية سيدنا عم رضی اللہ عنہ نے کہا: مجھے معلوم ہے کہ یہ آیت کس دن نازل ہوئی۔ وہ جمعہ کا دن تھا اور عرفہ کا دن تھا اور وہ دونوں دن ہمارے لیے عید کی حیثیت رکھتے ہیں۔ یہ حدیث اسحاق بن قبیصہ سے، عباد بن نسی سے روایت کرتے ہیں، اسے روایت کرنے میں زید بن حباب اکیلے ہیں۔","",{"k":"صحیح بخاری، سنن ترمذی (٣٠٣٤)، سنن نسائی (٣٠٠٢)۔","f":"مذکورہ آیت حجتہ الوداع کے موقع پر نازل ہوئی تھی جو پیغمبر نے یمن کا آخری حج تھا جس کے تین ماہ بعد نبی مکرم صلے علم دنیا سے تشریف لے گئے۔ سیدنا عمر رضی اللہ عنہ فرماتے ہیں کہ یہ آیت عرفہ کی شام کو جمعہ کے روز نازل ہوئی تھی اس کے بعد حلال حرام کا کوئی حکم نازل نہیں ہوا۔ نبی مکرم میم کی وفات سے نو رات پہلے آخری آیت ( وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ نازل ہوئی۔ مذکورہ آیت جب نازل ہوئی اس وقت پانچ عید میں جمع تھیں، جمعہ کا دن، عرفہ کا دن، یہود کی عید، نصاریٰ کی عید اور مجوس کی عید۔ مذکورہ آیت سے ان لوگوں کو بھی سبق لینا چاہیے جو رائے اور قیاس پر چلتے ہوئے نص کو چھوڑ دیتے ہیں۔"}],[831,"سيدنا و بر بن عیسی خزاعی رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ” جب تو مسجد صنعا بنائے تو اسے پہاڑ جس کو ضیق کہتے ہیں اس کی دائیں جانب بنانا۔“ یہ حدیث وبر بن عیسی سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عبد الملک الذماری اکیلے ہیں۔ ٨٣٢","",{"k":"مجمع الزوائد (٢/١٢)، اسناده حسن۔"}],[832,"سیدنا عمار بن یاسر رضی اللہ عنہ نے بیان کیا، جس نے سیدنا ابوبکر اور سیدنا عمر ناہنجا پر کسی “ بھی صحابی کو فضیلت دی تو اس نے تمام انصار اور مہاجرین اور بارہ ہزار اصحاب محمد علی تعلیم پر عیب لگایا۔ یہ حدیث ابوسنان سے صرف حازم بن جبلہ ہی روایت کرتے ہیں، حضرت عمار سے یہ اسی سند سے روایت ہے۔","",{"k":"رجاله ثقات . مجمع الزوائد (٥٣/٩)، قال الهيثمي فيه حازم بن جبلة لم اعرفه وبقية ثقات۔","f":"مذکورہ حدیث سے معلوم ہوا کہ سیدنا ابو بکر اور عمر نیلی با تمام صحابہ کرام یعنی یا تم میں سے فضل ہیں۔ ٨٣٣"}],[833,"سیدہ ام سلمہ بنی النیہا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: قیامت کے روز لوگ ننگے جسم ننگے پاؤں اکٹھے کیے جائیں گے۔ تو ام سلمہ فی النجھا نے بیان کیا، میں نے کہا اللہ کے رسول علم! وہ ایک دوسرے کو دیکھیں گے؟ آپ ملنے سلیم نے فرمایا: ”لوگ مشغول کر دیے جائیں گے (کہ انہیں دیکھنے کی ہوش نہ ہو گی )۔ میں نے عرض کیا: کون سی چیز انہیں مشغول کر دے گی؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”اعمال نامے پھیلایا جانا، ان میں ذرہ بھر اور رائی کے دانے کے برابر اعمال بھی درج ہوں گے۔“ حدیث حضرت اُم سلمہ بنی النیہا سے صرف اسی سند سے روایت ہے، ان سے روایت کرنے میں سعید بن سلیمان اکیلے ہیں مذکورہ روایت کمزور ہے تاہم یہ بات صحیح حدیث سے ثابت ہے کہ قیامت کے دن -٥- لوگ اپنی قبروں سے ننگے بدن، ننگے پاؤں اور بے ختنہ اٹھیں گے جیسا کہ سیدہ عائشہ بنی النیہا نے بیان کیا، میں نے رسول اللہ مالے علم کو فرماتے ہوئے سنا ”لوگ قیامت کے دن ننگے پاؤں، ننگے بدن اور ختنہ کے بغیر اکٹھے کیے جائیں گے۔“ میں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا مرد اور عورتیں ایک دوسرے کی طرف نہیں دیکھیں گے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! وہ دن اس قدر سخت ہوگا کہ کسی کو ایک دوسرے کی طرف دیکھنے کا ہوش نہیں ہوگا۔ (صحیح مسلم، کتاب الجنة،وصفة باب فناء الدنيا و بيان الحشر يوم القيامة)","",{"k":"ضعيف الترغيب والترهيب (٢/٢١٩، ٢٠٨٦)۔"}],[834,"سیدنا علقمہ بن سفیان ثقفی بنی اللہ نے بیان کیا، میں اس وفد میں شامل تھا جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تھا، بلال ہمارے پاس رمضان میں ہماری افطاری کا سامان لاتے تو روشنی ہوتی ہم کہتے: بلال! کیا نبی صلی اللہ علیہ وسلم نے افطار کر لیا ہے؟ وہ کہتے ہاں آپ نے افطار کر لیا۔ قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! جب میں آپ کے پاس سے آیا تو آپ افطار کر چکے تھے تو وہ اپنا ہاتھ برتن میں رکھتے، پھر خود کھاتے، پھر ہم کھاتے اور سحری کا کھانا سحری کے وقت لاتے اور وہ قبے کا پردہ ہٹا دیتے تاکہ ہم اپنا کھانا دیکھ لیں۔ یہ حدیث علقمہ ثقفی سے صرف اسی سند سے روایت ہے، اسے روایت کرنے میں ابراہیم بن اسماعیل اکیلے ہیں۔","",{"k":"مجمع الزوائد (١٥٢٣)، ضعيفٌ۔"}],[835,"قدامه بن ابراہیم نے بیان کیا، میں حجاج بن یوسف کے پاس گیا جبکہ وہ ابن زبیر بنا لینے کے معاملے میں عباس بن سہل بن سعد الساعدی کو مار رہا تھا، اس کا باپ سہل ازار و رداء ( ازار اور چادر میں ) آ گیا اور بڑی زور دار آواز سے حجاج سے کہا: کیا تجھے ہمارے بارے میں نبی صلی اللہ علیہ وسلم کی نصیحت یاد نہیں۔ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تمہارے بارے میں کیا فرمایا ہے؟ سہل نے کہا: آپ نے فرمایا: انصار کے نیک آدمی سے اچھا سلوک کیا جائے گا جبکہ ان کے گناہ گار سے درگزر کیا جائے گا۔ تو حجاج نے ان کے بیٹے کو چھوڑ دیا۔ یہ حدیث قدامہ بن ابراہیم سے صرف عبد اللہ بن مصعب ہی روایت کرتے ہیں، اسے روایت کرنے میں ان کے بیٹے مصعب اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (٦/٦)، صحیح ابن حبان (٧٢٨٧)، مسند ابی يعلى: ' (٧٥٣٢)، مجمع الزوائد (١٠/٣٦)، قال الشيخ شعيب الارناؤط اسناده حسن۔","f":"مذکورہ حدیث سے انصار صحابہ کرام بی سیم اور انصار تابعین کی فضیلت کا اثبات ہے۔ انصار صحابہ کرام معنی اسلیم سے محبت کرنا ایمان کی نشانی ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((آية المنافق بغض الانصار، واية المؤمن حب الانصار)) (صحیح مسلم، کتاب الايمان، رقم: ٢٣٥) منافق انسان کی علامت ہے کہ وہ انصار (صحابہ) سے بغض رکھتا ہے اور مومن شخص کی علامت ہے کہ وہ انصار (صحابہ) سے محبت کرتا ہے۔“ معلوم ہوا انصار سے محبت مومن ہی کر سکتا ہے اور اگر انصار میں کوئی غلطی دیکھی جائے تو درگزر کرنا چاہیے۔ خیر القرون میں ظالم و جابر حکمران بھی فرامین رسول سے کام کا پاس کرتے تھے اور انہوں نے عمل بالحدیث کی مثالیں پیش کیں۔ اور آج علماء و جہلاء ایک اس ڈگر پر چل رہ ہیں۔ اللہ تعالیٰ ہمارے حال پر رحم فرمائے"}],[836,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مجالس میں بہتر وہ ہے جو زیادہ کشادہ ہو۔“ یہ حدیث عبداللہ بن ابی طلحہ سے صرف مصعب بن ثابت ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا مجلس میں اگر افراد زیادہ ہوں تو حسن ادب اور وقار کا تقاضا","",{"k":"سنن ابو داؤد (٤٨٢٠)، مسند احمد (٣/٦٩)، قال الشيخ الالباني: صحیح۔","f":"ہے کہ حلقہ وسیع کر لیا جائے۔ ایک حدیث میں ہے نبی مکرم سے ہم نے فرمایا: ”تم میں سے کوئی شخص کسی کو ہرگز اس کی جگہ سے اٹھا کر خود نہ بیٹھ جائے لیکن جگہ نکال لیا کرو اور کھل جایا کرو۔ ( ادب المفرد، رقم: ١١٤٠) اسی طرح ارشاد باری تعالیٰ ہے: يَأَيُّهَا الَّذِينَ آمَنُوا إِذَا قِيْلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ فَافْسَحُوا يَفْسَحُ اللَّهُ لَكُمْ (المجادله: ١١) ”اے ایمان والو! جب تم سے کہا جائے کہ مجلس میں جگہ کھول دو تو تم جگہ کھول دیا کرو۔ اللہ تمھارے لیے فراخی پیدا فرما دے گا۔“"}],[837,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” کیا میں تمہیں ایسا شخص نہ بتاؤں جس پر کل (قیامت) کو آگ حرام ہو گی؟ ہر آسانی کرنے والے نرم اخلاق والے اور لوگوں کے قریب رہنے والے پر۔“ یہ حدیث ہشام بن عروہ سے صرف عبداللہ بن مصعب ہی روایت کرتے ہیں، اسے روایت کرنے میں ان کے بیٹے اکیلے ہیں۔ مذکورہ حدیث میں نرمی اور لوگوں سے قربت رکھنے والے کی فضیلت کا تذکرہ ہے۔ و-ه- حسن اخلاق کا ایمان سے نہایت گہرا تعلق ہے جو انسان کو جہنم کی آگ سے بچانے والا ہے۔","",{"k":"صحيح الجامع الصغير (٢٦٠٩)، سنن ترمذی، رقم: ٢٤٨٨ . : . : ابنه۔"}],[838,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں کوئی نماز کے لیے وضو کرے تو وہ اپنے ایک ہاتھ کی انگلیاں دوسرے ہاتھ کی انگلیوں میں داخل نہ کرے۔“ یہ حدیث محمد بن عجلان از والد از حضرت ابو ہریرہ روایت کرتے ہیں اور اسے روایت کرنے میں الدراوردی اکیلے ہیں۔ دیگر محدثین نے از ابن عجلان از سعید مقبری از حضرت کعب بن عجره از نبی کریم ملے عام روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ مسجد وغیرہ میں ایک ہاتھ کی انگلیاں دوسرے ہاتھ کی","",{"k":"سنن ابو داؤد (٥٦٢)، السلسلة الصحيحة (٣/٣٦٨، ١٢٩٤)۔","f":"انگلیوں میں داخل کر کے قینچی کرنا اور چٹیا نہ یا اس طرح کے دوسرے لا یعنی عمل درست نہیں"}],[839,"سیدنا زبیر بن العوام سے روایت ہے کہ رسول اللہ ملنے صلی اللہ علیہ وسلم نے فرمایا: ” جو شخص یہ پسند کرتا ہو کہ اس کا اعمال نامہ اس کو خوش کر دے تو وہ اس میں استغفار زیادہ شامل کرے۔“ یہ حدیث حضرت زبیر سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عتیق بن یعقوب اکیلے ہیں۔ ایک حدیث میں ہے نبی صلی اللہ علیہ وسلم نے فرمایا: طوبى لمن وجد في صحيفته استغفارا كثيرا . “(صحيح الجامع، رقم: ٣٩٣٠) ”خوشخبری ہے اس شخص کے لیے جو اپنے نامہ اعمال میں بہت زیادہ استغفار پائے۔“ مذکورہ دونوں احادیث سے معلوم ہوا ہمیں زیادہ سے زیادہ اپنے نامہ اعمال میں استغفار لکھوانا چاہیے۔ طوبی کا معنی ہے بھلائی، پاکیزگی، اچھی زندگی، اس کے علاوہ جنت میں ایک درخت کا نام بھی طوبی ہے۔ سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ملنے کی ایم نے فرمایا: ((طوبى شجرة في الجنة مسيرة مائة عام ثياب اهل الجنة تخرج من اكمامها)) (صحيح الجامع الصغير، رقم: معلوم ہوا کہ دنیا اور آخرت میں بہترین اور خوشگوار زندگی اور جنت کے درخت طوبی کا حق دار وہ شخص ہے جو زیادہ سے زیادہ استغفار کرتا ہے۔ ٨٤٠","",{"k":"صحيح الجامع الصغير (٥٩٥٥)، شعب الایمان (٢/٢١٠، ٦٦٨)، السلسلة الصحيحة (٢٢٩٩)۔"}],[840,"سیدنا ابو ہریرہ خیالیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم تین سانسوں میں پانی پیا کرتے تھے جب برتن کو اپنے منہ کے قریب کرتے تو بسم اللہ پڑھتے اور جب اس کو دور کرتے تو الحمد للہ کہتے، آپ یہ کام تین بار کرتے۔ یہ حدیث ابن عجلان سے صرف الدر اور دی روایت کرتے ہیں، اسے روایت کرنے میں عتیق بن یعقوب اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ کھانے یا پینے کے آغاز پر بسم اللہ اور آخر میں الحمد للہ کہنا چاہیے اور یہ بھی معلوم ہوا کہ پینے والی چیز تین سانس میں پی جائے یعنی پی کر برتن سے منہ ہٹا کر سانس لیا جائے۔ اس کا","",{"k":"السلسلة الصحيحة (١٢٧٧)، المعجم الكبير للطبراني (١٩/١٤٠)۔","f":"یہ ہے کہ معدہ پر یکبارگی بوجھ نہیں پڑتا نیز آدمی حیوانی مشابہت سے بچ جاتا ہے۔"}],[841,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما جب نماز شروع کرتے اور سورۃ الفاتحہ پڑھتے تو بسم الرحمن الرحیم سے آغاز فرماتے تھے اور اس کے بعد کوئی دوسری سورۃ شروع کرتے تو ”بسم اللهِ الرَّحْمنِ الرَّحِيم\" سے شروع کرتے وہ ذکر کرتے کہ انہوں نے یہ بات نبی ملتے نام سے سنی ہے۔“ مذکورہ حدیث سے معلوم ہوا کہ فاتحہ اور دیگر سورتوں کے آغاز میں بسم اللہ پڑھنا چاہیے۔ سورۃ الفاتحہ اور دوسری سورت سے قبل اس پر تو اتفاق ہے۔ اختلاف اس میں ہے کہ کیا بسم اللہ سری طور پر پڑھنا چاہیے یا اونچی آواز سے؟ جمہور اہل علم، امام ابو حنیفہ جمالا وغیرہ کا موقف ہے. بسم اللہ اونچی آواز سے مسنون نہیں جبکہ امام شافعی رحمہ اللہ کا کہنا ہے کہ بسم اللہ اونچی آواز سے پڑھنا چاہیے۔ علامہ ناصر الدین البانی اللہ کا یہ موقف ہے کہ اونچی آواز سے بسم اللہ پڑھنے کی کوئی صریح صحیح حدیث موجود نہیں۔ (تمام المنة: ص ١٦٩) شیخ الاسلام ابن تیمیہ اللہ کا کہنا ہے کہ عام اوقات میں آہستہ پڑھنا ہی سنت ہے جبکہ بعض اوقات اونچی آواز سے پڑھنا بھی جائز ومباح ہے۔(مجموع الفتاویٰ: ٤١٠/٢٢) امام ابن قیم اللہ فرماتے ہیں رسول اللہ سے یہ اونچی آواز سے بسم اللہ پڑھتے تھے لیکن اونچی آواز سے بہ نسبت ملکی آواز سے زیادہ پڑھتے تھے۔ (زاد المعاد: ١٩٩/١) امام شوکانی جماللہ فرماتے ہیں دونوں طرح جائز ہے۔(نیل الاوطار: ٢٣/٢) درست بات یہی ہے کہ آہستہ پڑھنا افضل ہے کبھی کبھار اونچی آواز سے بھی پڑھ لینا جائز ہے۔ (واللہ اعلم)","",{"k":"تقدم تخريجه، انظر (٨٠٠)۔"}],[842,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے دن جمعے کو نماز کی طرف جانے سے پہلے اپنے ناخن اور اپنی مونچھیں کاٹتے تھے۔“","",{"k":"ورس ١٧٠ /٢ ضعيف الجامع الصغير (٤٥٩٦)، كنز العمال (١٨٢٢)، مجمع الزوائد۔","f":"تاہم جمعہ کے دن صفائی ستھرائی کا خاص خیال رکھنا چاہیے۔"}],[843,"سیدنا ابو ہریرہ میل الیہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو لوگ اندھیروں میں مسجدوں کی طرف جاتے ہیں ان کے لیے اللہ تعالیٰ قیامت کے دن بلند نو ر روشن کرے گا۔“ مذکورہ حدیث میں اندھیرے میں نماز کے لیے جانے والوں کے لیے خوشخبری ہے کہ","",{"k":"سنن ابو داؤد (٥٦١)، سنن ترمذی (٢٢٣)، المعجم الكبير للطبراني (١٩/١٤١)۔","f":"ان کے لیے نور ہو گا۔ اندھیروں سے مراد عشا اور فجر کی نمازیں ہیں۔ آج کل شہروں میں تو بجلی کے بلبوں اور قمقموں کی وجہ سے زیادہ اندھیرا محسوس نہیں ہوتا۔ تا ہم پھر بھی قدرتی اندھیروں کو بالکل ختم کرنے پر کوئی قادر نہیں ہے یہ فضیلت ہے عشا و فجر کی نماز کی کہ قیامت کے دن کامل نور ملے گا جیسا کہ ارشاد باری تعالیٰ ہے: نُورُهُمْ يَسْعَى بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ يَقُولُونَ رَبَّنَا أَتْهِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا (التحريم: ٨) ان کا نور ان کے آگے اور ان کے دائیں دوڑتا ہو گا۔ کہیں گے اے ہمارے رب! ہمارے لیے ہمارا نور پورا کر دے اور ہمیں بخش دے۔“"}],[844,"سیدنا ابو ہریرہ فی اللہ سے روایت ہے کہ جب بارش برستی اور پرنالے بہنے لگتے تو رسول اللہ علیم فرماتے: ” اس سال تم پر کوئی قحط نہیں ہو گا۔ یہ تمام احادیث اغر سے صرف ابراہیم بن قدامہ ہی روایت کرتے ہیں، اسے روایت کرنے میں عقیق اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١٩/١٤١)، مجمع الزوائد (٢/٢١٦)، اسناده ضعيف۔"}],[845,"سیدنا ابن عباس رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ سر منڈانے والوں پر رحم فرمائے۔“ ہم نے کہا: اور کترانے والوں پر بھی۔ آپ نے پھر فرمایا: ”اللہ تعالیٰ سر منڈانے والوں پر رحم فرمائے۔ صحابہ نے پھر کہا: یا رسول اللہ صلی اللہ علیہ وسلم اور کترانے والوں پر بھی تو آپ نے تیسری یا چوتھی دفعہ فرمایا: اور کترانے والوں پر بھی۔“ یہ حدیث عبداللہ بن مومل سے صرف سعید بن سلیمان ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ حج یا عمرہ سے حلال ہوتے وقت بال منڈانا بال کترانے سے افضل ہے۔ کیونکہ نبی معظم صلی اللہ علیہ وسلم نے کترانے والوں کے لیے ابتدا میں دعا نہیں فرمائی بلکہ ان کے لیے صحابہ کے اصرار پر صرف تیسری مرتبہ دعا فرمائی، جبکہ منڈانے والوں کے لیے پہلی مرتبہ سے آخر تک تین مرتبہ دعا فرمائی۔ علامہ عبد الرحمن مبارکپوری جماللہ (تحفۃ الاحوذی) اور شیخ ابن باز ہمالہ (فتاوی اسلامیه: ٢٦٢/٢) کا بھی یہی موقف ہے کہ حج اور عمرہ میں بال منڈوانا افضل ہے۔ ٨٤٦","",{"k":"صحیح بخاری (١٧٢٧)، صحیح مسلم (١٣٠٢)۔"}],[846,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابو ہریرہ رضی اللہ عنہ ولیمہ کرو خواہ ایک بکری کا ہو۔ یہ حدیث عبدالرحمن بن ابی ذباب سے صرف عبداللہ بن مؤمل ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ ولیمہ کرنا سنت ہے۔ اگر کوئی استطاعت نہ رکھتا ہو کہ گوشت کے ساتھ ولیمہ کر سکے تو اسے بے جا تکلفات میں نہیں پڑنا چاہیے بلکہ حسب توفیق کسی عام کھانے یا مٹھائی یا شربت وغیرہ کے ساتھ ہی ولیمہ کی دعوت کا اہتمام کرنا چاہیے، اس کی دلیل سیدنا انس ضیا اللہ سے مروی وہ روایت ہے جس میں مذکور ہے کہ نبی مکرم مسلم نے سیدہ حفصہ نبی اشیا سے شادی کے وقت کھجور اور ستو کے ساتھ ولیمہ کیا۔ (صحیح ترمذی، رقم: ٨٧٥، سنن ابو داؤد، رقم: ٣٧٤٤) اسی طرح ایک روایت میں ہے نبی معظم صلی اللہ علیہ وسلم نے اپنی ایک بیوی کا ولیمہ دو مد ( تقریباً سوا کلو ) جو کے ساتھ کیا۔ (صحیح بخاری، کتاب النکاح، رقم: ١٦٨) قاضی عیاض ہو اللہ نے اس پر اجماع نقل کیا ہے کہ ولیمہ میں کمی بیشی کی کوئی قید نہیں بلکہ حسب ضرورت اور حسب توفیق ولیمے کا کھانا پکایا جا سکتا ہے وہ تھوڑا ہو یا زیادہ۔ (نیل الاوطار: ٩٢٦٠/٤) ٨٤٧","",{"k":"عبد الله بن المؤمل کر صحیح مسلم، سنن دارمی (٢٠٦٤)۔"}],[847,"مجاہد جماللہ نے بیان کیا، سیدنا ابو ذر خلیل اللہ ہمارے پاس آئے تو انہوں نے کعبے کے دروازے کا کنڈا پکڑا، پھر بلند آواز سے پکار کر کہا: لوگو! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سناوہ عصر کے بعد سورج غروب ہونے تک کوئی نماز پڑھنا ( درست ) نہیں۔ اسی طرح فجر کے بعد بھی کوئی نماز ( پڑھنا درست نہیں حتی کہ سورج طلوع ہو جائے، سوائے مکہ کے، سوائے مکہ کے۔“ یہ حدیث قیس بن سعید سے صرف حمید مولی عفراء ہی روایت کرتے ہیں، یہ حمید بن قیس اعرج ہیں، اسے روایت کرنے میں عبداللہ بن مؤمل المخزومی اکیلے ہیں","",{"k":"مسند احمد (٥/١٦٥)، السنن الكبرى للبيهقي (٢/٤٦١)، صحیح ابن خزیمه (٢٧٤٨)، اسناده ضعيف۔","f":"مذکورہ روایت کمزور ہے۔ تاہم صحیح حدیث سے ثابت ہے کہ عصر اور فجر کے بعد کوئی نماز نہیں جیسا کہ نبی مکرم ملے تم نے فرمایا: (( لا صلاة بعد الصبح حتى تطلع الشمس ولا صلاة بعد العصر حتى تغيب الشمس)) (صحیح بخاری، کتاب مواقيت الصلاة، رقم: ٥٨٦) صبح کی نماز کے بعد طلوع آفتاب تک کوئی نماز نہیں اور نماز عصر کے بعد غروب آفتاب تک کوئی نماز نہیں۔“"}],[848,"سيدنا عبد اللہ بن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ منعیم نے فرمایا: ” علم کو قید کرو“ میں نے عرض کیا: علم کا قید کرنا کیا ہے؟ آپ ملنے ہیم نے فرمایا: ”لکھنا۔“ یہ حدیث عطاء سے صرف عبداللہ بن مؤمل روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ علم کو لکھ لینا چاہیے کیونکہ لکھنے سے علم محفوظ رہتا ہے۔ جیسا کہ سیدنا ابو ہریرہ ضیا یہ فرماتے ہیں کہ نبی مکرم نے علم کے صحابہ بنی اسلیم میں سے سیدنا عبد اللہ بن عمرو رضی اللہ عنہما کے علاوہ مجھ سے زیادہ کوئی بھی حدیث بیان کرنے والا نہیں تھا (اس کی وجہ یہ ہے کہ ) وہ (حدیث ) لکھ لیا کرتے تھے جبکہ میں لکھا نہیں کرتا تھا۔ (صحیح بخاری، کتاب العلم، رقم: ١١٣) ٨٤٩","",{"k":"السلسلة الصحيحة ٥ / ٢٥ . ٢٥ (٢٦.٢٠٢٦)، مجمع الزوائد (١/١٥٢)۔"}],[849,"ا سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آب زمزم اسی مقصد کے لیے ہے جس مقصد کے لیے پیا جائے۔“ یہ حدیث ابوز بیر سے صرف عبداللہ بن مؤمل ہی روایت کرتے ہیں۔ مذکورہ حدیث میں آب زمزم کی فضیلت کا تذکرہ ہے کہ جس غرض سے پیا جائے وہ غرض پوری ہو جاتی ہے۔ جیسا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: زمزم کا پانی جس مقصد کے لیے پیا جائے وہی مقصد پورا ہوتا ہے اگر تو اس کو بیماری سے شفا کے لیے پیئے گا تو اللہ تجھے شفا دے گا، اگر تو اس لیے پیئے گا کہ وہ تیری پیاس بجھائے تو اللہ تیری پیاس بجھائے گا، اور یہ جبریل کا کنواں ہے جو اللہ تعالیٰ نے اسمعیل کو پلایا تھا۔ (سنن دار قطنی: ٢٨٩/٢)","",{"k":"کی سنن ابن ماجه (٣٠٦٢)، السلسلة الصحيحة (٢/٤٥٧)۔"}],[850,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: خوش خلقی گناہوں کو پگھلا دیتی ہے جس طرح پانی برف کو پگھلا دیتا ہے اور بدخلقی،عمل کو خراب کر دیتی ہے جس طرح سر کہ شہد خراب کر دیتا ہے۔“","",{"k":"السلسلة الضعيفة (٢/١٨)، رقم : بن ميمون وهو ضعيف. مجمع الزوائد (١/٢٤)، فيه عيسى۔"}],[851,"سیدنا عبداللہ ابن عباس ریلی اینجا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” دو شکاری بھیڑیے جو بکریوں میں رات گزاریں اتنی زیادہ خرابی نہیں کرتے جتنی مال و جاہ سے انسان کی محبت (اس کے دین کو ) خرابی کرتی ہے۔“ یہ دونوں حدیثیں حضرت ابن عباس سے اسی سند سے روایت ہے اور ان دونوں سے روایت کرنے میں عیسی بن میمون اکیلے ہیں۔ ٨٥٢","",{"k":"سنن ترمذی (٢٣٧٦)، المعجم الكبير للطبراني (١٩/١٣٥)۔"}],[852,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارے آگے حوض اس طرح ہے جس طرح جرباء اور اذرح کے درمیان فاصلہ ہے۔“ یہ حدیث ابن مجبر سے صرف سعید ہی روایت کرتے ہیں۔ فائد أَمْروووره جرباء اور اذرح شام کے ملک میں دو گاؤں ہیں جن میں تین دن کی مسافت ہے۔","",{"k":"صحیح بخاری (٦٥٧٧)، صحیح مسلم (٢٢٩٩)۔"}],[853,"سیدنا تحمیل غفاری رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرمائے ہوئے سنا: سواریوں کو صرف تین مسجدوں کی طرف چلایا جائے (١) مسجد حرام (٢) میری یہ مسجد (مسجد نبوی) اور (٣) مسجد بیت المقدس “ یہ حدیث از زید از مقبری از حضرت ابو ہریره فضل الله نه صرف ابن مجبر ہی روایت کرتے ہیں۔ روح بن قاسم وغیرہ نے از زید از سعید المقبری از ابی بصرہ جمیل بن بصرہ روایت کی ہے۔ ٨٥٤","",{"k":"ارواء الغليل (٣/٢٢٨)، المعجم الكبير للطبرانی (٢/٤٠٠)، صحیح۔"}],[854,"سیدنا عرباض بن ساریہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب آدمی اپنی بیوی کو پانی پلاتا ہے تو اسے اجر دیا جاتا ہے۔ راوی کہتا ہے: پھر میں نے اٹھ کر اپنی بیوی کو پانی پلایا، اور میں نے رسول اللہ علیم سے جو سنا تھا وہ اسے بتایا۔ یہ حدیث سفیان سے صرف عباد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ اپنی بیوی کے ساتھ اچھا سلوک کرنا چاہیے اس کے کھانے پینے کا بندوبست کیا جائے۔ اور اگر کوئی آدمی بھی کام کرے تو نیت یہ ہونا چاہیے کہ یہ اللہ کا حکم ہے تو یہ فطری داعیہ بھی عبادت بن جائے گا جس پر انسان اجر کا مستحق ہوگا۔ ٥٥","",{"k":"مسند احمد (٤/١٢٨)، مجمع الزوائد (٣/١١٩)، صحيح الترغيب والترهيب (٢/٢٠٣، ١٩٦٣)۔"}],[855,"سیدنا عاصم بن عدی سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے، پس سیدنا جب یہ آیت ثُمَّ لَمْ يَأْتُو بِأَرْبَعَةِ شُهَدَاءَ نازل ہوئی تو میں نے کہا: یا رسول اللہ ملے عینم! چار گواہ لانے تک وہ خسارے والا تو اپنی ضرورت پوری کر لے گا۔ راوی نے کہا: ابھی وہ اٹھے بھی نہیں تھے کہ ان کا چا زاد آ گیا، اس کے ساتھ اس کی بیوی بھی تھی جو ایک بچہ اٹھائے ہوئے تھی وہ کہہ رہی تھی: یہ تیرا ہے اور وہ کہہ رہا تھا یہ میرا نہیں تو اللہ تعالیٰ نے لعان کی آیت نازل فرمائی۔ وہ کہتا ہے کہ میں پہلا شخص تھا جس نے یہ کلام کیا اور پہلا pers Rangers شخص تھا جو اس مسئلے میں آزمایا گیا۔ یہ حدیث عاصم بن عدی سے صرف شعمی ہی روایت کرتے ہیں، اسے روایت کرنے میں حصین اکیلے ہیں۔","",{"k":"كر المعجم الكبير للطبرانی (١٢/١١٩)، اسناده صحیح۔","f":"مذکورہ حدیث میں لعان کا تذکرہ ہے۔ لعان کا معنی ایک دوسرے پر لعنت کرنا ہے۔ (المنجد: ص ٦٩٥) لعان کی صورت یہ ہے کہ شوہر اپنی بیوی پر زنا کی تہمت لگاتا ہے، اور اس کے پاس گواہ موجود نہیں جبکہ اس کی بیوی اس سے انکار کرتی ہے، تو پھر یہ شخص عدالت یا حاکم وقت کے سامنے چار مرتبہ اللہ کی قسم اٹھا کر گواہی دیتا ہے کہ وہ سچا ہے اور پانچویں مرتبہ کہتا ہے کہ اگر وہ جھوٹا ہے تو اس پر اللہ کی لعنت ہو۔ پھر اس کے جواب میں بیوی چار مرتبہ قسم اٹھا کر شہادت دیتی ہے کہ اس کا شوہر جھوٹا ہے، اور پانچویں مرتبہ کہتی ہے کہ اگر وہ سچا ہے تو مجھ پر اللہ کا غضب ہو۔ تب وہ حد زنا سے بچ جاتی ہے اس کے بعد دونوں کے درمیان ہمیشہ کے لیے جدائی ڈال دی جاتی ہے۔ اس عمل کو لعان اس لیے کہتے ہیں کہ اس میں دونوں جھوٹا ہونے کی صورت میں خود کو لعنت کا مستحق قرار دیتے ہیں۔ لعان میں بچہ ماں کے حوالے کر دیا جائے گا۔ (دیکھئے بخاری، رقم: ٥٣١٥) اور قسموں کی مرد سے ابتداء کی جائے گی۔ (مسند احمد: ١٩/٢) لعان کا حکم صرف شادی شدہ عورتوں کے لیے ہے غیر شادی شدہ کا اس میں کوئی دخل نہیں۔ (تفسير اللباب في علوم الكتاب: ٣٠٤/١٤) کیا لعان کے بعد از خود علیحدگی ہو جائے گی یا صرف حاکم کے جدائی ڈالنے پر ہی علیحدگی ہوگی؟ احناف کے ہاں اس وقت تک جدائی نہیں ہو گی جب تک کہ حاکم انہیں جدا نہ کر دے جیسا کہ نبی مکرم طلئے علیم جدائی نہیں ہوگی جب نے جدائی کرائی۔ امام مالک اللہ فرماتے ہیں: جب دونوں لعان سے فارغ ہوں گے تو از خود علیحدگی ہو جائے گی۔ خواہ حاکم تفریق نہ بھی کرائے کیونکہ وہ عورت اب شوہر پر ہمیشہ کے لیے حرام ہو چکی ہے لہذا اگر وہ اکٹھے رہنا بھی چاہیں تو نہیں رہ سکتے۔ یہی موقف زیادہ راجح معلوم ہوتا ہے۔ اور لعان کی وجہ سے عورت ہمیشہ ہمیشہ کے لیے حرام ہو جاتی ہے۔"}],[856,"سیدہ عائشہ نبی الیہ سے روایت ہے کہ رسول اللہ لئے علیم ایک سفر میں تھے مجھے رات کے وقت ڈر محسوس ہونے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کیا بات ہے؟ میں نے کہا: میں اس جگہ تاریک رات میں آپ کے متعلق ڈر رہی ہوں۔ آپ نے فرمایا: ہر گز نہیں! اللہ تعالیٰ ضرور کسی شخص کو پہنچا دے گا جس سے اللہ تعالیٰ اور اس کا رسول صلے علی تیم محبت کرتا ہے اور وہ اللہ اور اس کے رسول ملے تعلیم سے محبت کرتا ہے، وہ باقی ماندہ رات ہماری نگرانی کرے گا۔ سیدہ عائشہ بنی النھا کہتی ہیں: ہم اسی حال میں تھے کہ میں نے ایک سایہ دیکھا جو ہماری طرف آ رہا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کون ہے؟“ وہ کہنے لگا: میں سعد بن مالک ہوں۔ میں باقی رات آپ کا پہرہ دینے آیا ہوں۔ تو رسول اللہ صلی اللہ علیہ وسلم سر نیچے رکھ کر سو گئے۔“ یہ حدیث ابی جعفر سے صرف عوام ہی روایت کرتے ہیں۔ سنن ترمذی، کتاب المناقب، باب مناقب سعد بن مالك، رقم",""],[857,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے نبی تم سے روایت ہے کہ آپ نے فرمایا: ” بیٹھے ہوئے کی نماز کھڑے ہو کر پڑھنے والے سے نصف اجر رکھتی ہے۔“ یہ حدیث عمرو سے صرف سفیان ہی روایت کرتے ہیں۔","",{"k":"سنن ابن ماجه (١٢٣٠)۔"}],[858,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”زنا کا بچہ جنت میں داخل ہو گا نہ اس کی سات نسلوں تک کوئی جنت میں داخل ہو گا۔“ یہ حدیث ابراہیم سے صرف عمرو ہی روایت کرتے ہیں۔:٨:٥٩","",{"k":"السلسلة الضعيفة (٣/٢٨٦، ١٢٨٧)، مجمع الزوائد (٦/٢٥٧)۔"}],[859,"سیدنا جابر بن سمرہ رضی اللہ عنہ نے بیان کیا، میں اور میرا باپ نبی سے کم کی خدمت میں حاضر ہوئے۔ آپ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی جب سلام پھیرا تو لوگوں نے دائیں بائیں اپنے ہاتھوں۔ اشارہ کیا۔ آپ نے انہیں دیکھ لیا اور فرمایا: ”تم لوگ دائیں بائیں اس طرح پلٹتے ہو جس طرح اکڑنے والے سرکش گھوڑوں کی دمیں ہوتی ہیں۔ جب تم میں سے کوئی شخص سلام پھیرے تو دائیں اور بائیں والوں کو سلام کہہ دے“ پھر جب بھی وہ آپ کے ساتھ نماز پڑھتے تو اس طرح نہ کرتے۔ جابر رضی اللہ عنہ کہتے ہیں: ہم آپ کے ساتھ بیٹھ گئے تو آپ نے فرمایا: \"بارہ امیروں یا خلیفوں میں اسلام غالب رہے گا وہ سب کے سب قریش سے ہوں گے۔“ یہ حدیث فرات سے صرف عمرو ہی روایت کرتے ہیں۔ (١) مذکورہ حدیث سے معلوم ہوا کہ نماز میں ہاتھوں سے اشارے کرنا جائز نہیں۔ اصل میں صحابہ کرام رضوان اللہ علیہم اجمعین جب سلام پھیرتے تو ہاتھوں سے اشارے کرتے ہوئے سلام کہتے تو شریعت نے اس کام سے روک دیا کہ ہاتھ سے اشارہ نہ کریں۔ بعض لوگ مذکورہ حدیث کا مطلب یہ لیتے ہیں کہ رفع الیدین نہیں کرنا چاہیے۔ اگر بالفرض مان ہی لیا جائے تو تکبیر تحریمہ کے ساتھ بھی تو رفع یدین منع ہو گا۔ لیکن یہ رفع الیدین تو احناف بھی کرتے ہیں، بہر حال تمام محدثین کا اس پر اجماع ہے کہ اس حدیث کا تعلق تشہد کے ساتھ ہے۔ رفع الیدین عند الرکوع والرفع منہ کے ساتھ نہیں ہے۔ خیر القرون میں کسی نے بھی اس حدیث کے ساتھ رفع الیدین ( کے مسئلہ ) کی ممانعت پر استدلال نہیں کیا۔ (٢) مذکورہ حدیث میں بارہ خلفاء سے مراد وہ خلفاء ہیں جو قیامت سے پہلے مختلف ادوار میں ہوں گے۔ چاروں خلفاء راشدین، امام حسن رضی اللہ عنہ عمر بن عبد العزیز جماللہ اور امام مہدی بھی ان بارہ خلفاء میں شامل ہیں۔ اہل تشیع (اثنا عشریہ ) کا کہنا ہے کہ بارہ خلفاء اہل بیت سے ہوں گے اور وہ یکے بعد دیگرے آئیں گے ان کی ترتیب ان کے نزدیک اس طرح ہے: سیدنا علی، حسن، حسین، زین العابدین بنی اسلام، محمد باقر، جعفر صادق، موسی کاظم علی رضا، محمد تقی علی نقی حسن عسکری اور محمد مہدی رحمہم اللہ۔ (مرقات ٢٦١/١١)","",{"k":"صحیح مسلم، رقم: (٧/١٨٢١)۔"}],[860,"سیده ام فروہ بنی الشیبا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: اللہ کے نزدیک سب سے زیادہ محبوب عمل وقت پر نماز ہے یا فرمایا: ” اول وقت پر نماز ہے۔“ یہ حدیث عبید اللہ سے صرف قزعہ ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٥٢٧)، سنن ابو داؤد (٢٦)۔","f":"مذکورہ روایت سے معلوم ہوا کہ اعمال میں سب سے زیادہ پیارا عمل وہ نماز ہے اور جو اول وقت پر ادا کی جائے۔ ایک حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((أَفْضَلُ الْأَعْمَالِ الصَّلَاةِ فِي أَوَّلِ وَقْتِهَا)) (سنن ترمذی، رقم: ١٧٣، حاكم: ١٨٨/١، اسناده صحیح.) سب سے افضل عمل اول وقت میں نماز کی ادائیگی ہے۔“ ٦١"}],[861,"سیدنا انس رضی اللہ عنہ نے بیان کیا میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: کتنے ہی بکھرے بالوں والے، غبار آلود پاؤں والے اور دو پراگندہ خاک بوسیدہ کپڑوں والے ہیں جولوگوں کے دروازوں سے دور کر دیے جاتے ہیں اگر وہ اللہ تعالیٰ پر قسم کھا لیں تو اللہ تعالیٰ ان کی قسم کو پورا کر دے۔“ یہ حدیث حفص سے صرف اسامہ ہی روایت کرتے ہیں۔","",{"k":"کی سنن ترمذی، صحيح الجامع الصغير (٤٥٧٣)، قال الشيخ الالباني، صحیح۔","f":"ترمذی شریف میں ہے انہی میں سے سیدنا براء بن مالک رضی اللہ عنہ بھی ہیں۔ (سنن ترمذی، رقم: ٣٨٥٤) مذکورہ حدیث سے معلوم ہوا کہ اللہ ذوالجلال شکل وصورت کو نہیں دیکھتا بلکہ اللہ ذوالجلال کے نزدیک قدرو منزلت تقویٰ اختیار کرنے والوں کی ہے۔ اللہ تعالیٰ اپنے بندوں کی قسموں کی لاج رکھتا ہے۔"}],[862,"سیدہ عائشہ رضی اللہ عنہا سے رایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” مسجد میں اس ستون کے سامنے ایک جگہ ہے اگر لوگوں کو معلوم ہو جائے تو وہ ضرور اس جگہ نماز پڑھیں خواہ ان کے لیے قرعہ اندازی کرنا پڑے، وہاں صحابہ بنی اسلام اور کچھ مہاجرین کے بیٹے تھے انہوں نے کہا: ام المؤمنین وہ جگہ کون سی ہے؟ انہوں نے انہیں وہ جگہ نہ بتائی وہ چلے گئے، مگر عبداللہ بن زبیر بیا انہیں اسی جگہ ٹھہرے رہے انہوں ( دیگر حضرات) نے کہا: وہ اس جگہ کے متعلق انہیں ضرور بتائیں گی اس لیے مسجد میں انتظار کرو یہاں تک کہ دیکھو وہ کہاں نماز پڑھنتے ہیں پس وہ کچھ دیر بعد وہ باہر آئے تو انہوں نے ستون کے پاس نماز پڑھی جس ستون کی طرف ان کے بیٹے عامر بن عبد اللہ نے پڑھی اس کو اسطوانه القرعہ کہا جاتا ہے۔ عتیق نے کہا: یہی وہ جگہ ہے جو آپ کی قبر اور منبر کے درمیان واسطہ ہے۔ اس کی دائیں جانب منبر تک دوستون ہیں اور اس کے اور منبر کے درمیان دو ستون ہیں، یہ ستون اس کے درمیان واسطہ ہے اس کو اسطوانۃ القرعہ کہا جاتا ہے۔“ یہ حدیث ہشام سے صرف:٨٦٣ اُن کے بیٹے منذ رہی روایت کرتے ہیں، اسے روایت کرنے میں عتیق بن یعقوب اکیلے ہیں۔ ٣٦٣","",{"k":"السلسلة الضعيفه (٥/٣٨٩)، رقم : ٢٣٩٠ . مجمع الزوائد: ٤/۔"}],[863,"سیدنا جابر ضیا اللہ نے بیان کیا، رسول الله علیم نے فرمایا: ”ایمان اہل حجاز میں ہے اور دل کی تختی ربیعہ اور مضر ( قبیلوں ) میں ہے۔ یہ حدیث ابوبکرہ سے صرف احمد ہی روایت کرتے ہیں۔","",{"k":"کر صحیح بخاری (٤٩٩٧)، صحيح مسلم (١٠٥٥)۔"}],[864,"سیدنا سلمہ بن اکوع رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب نماز کا وقت ہو جائے اور رات کا کھانا بھی آ جائے تو پہلے کھانا کھا لو۔“ یہ حدیث سلمہ سے اسی سند سے مروی ہے، اسے روایت کرنے میں ایوب اکیلے ہیں۔","",{"k":"صحیح بخاری (٦٧١)۔","f":"اند. مذکورہ حدیث میں یہ حکم اس لیے دیا گیا ہے تا کہ انسان پوری توجہ اور کامل خشوع و خضوع سے نماز ادا کر سکے کیونکہ عین ممکن ہے اگر انسان اس صورت میں کھانا چھوڑ کر نماز شروع کر دے تو وہ نماز میں یکسوئی اختیار نہ کر سکے جو حقیقی مطلوب شریعت ہے۔ جمہور علماء کا کہنا ہے کہ اس حدیث میں جو کھانے کو نماز سے پہلے تناول کرنے کا حکم ہے وہ استحباب کے لیے ہے جبکہ اہل ظاہر نے اسے وجوب پر محمول کیا ہے۔ شیخ عبد اللہ بسام جراللہ نے جمہور کے موقف کو ہی ترجیح دی ہے۔ (توضیح الکلام: ٨٦/٢) ٨٦٥"}],[865,"سیدنا عبد اللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” اعمال سات ہوتے ہیں۔ دو نجات دلاتے ہیں اور دو عمل ہیں جو دو گنا عمل کے برابر ہوتے ہیں۔ ایک عمل ہے جو دس گنا کے برابر اور ایک عمل ہے جو سات سو گنا کے برابر ہے ایک عمل وہ ہے جس کا بدلہ اللہ کے سوا کوئی نہیں جانتا۔ دو نجات دینے والے عمل یہ ہیں: جو شخص اللہ عزوجل کو اس حال میں ملے کہ صرف اسی کی بندگی کرے اس کے ساتھ کسی کو شریک نہ کرے تو اس کے لیے جنت واجب ہو جاتی ہے۔ اور جو شخص اللہ تعالیٰ کو اس حال میں ملا کہ وہ اس کے ساتھ کسی کو شریک کرتا تھا تو اس کے لیے جہنم واجب ہو جائے گی۔ جو شخص برا کام کرے تو اس کو اس کا برا بدلہ دیا جائے گا اور جس نے نیکی کا ارادہ کیا مگر نیکی نہ کی تو اس کو ایک نیکی کا بدلہ ملے گا۔ اور جس نے ایک نیکی کی اس کو اس کے دو گنا بدلہ ملے گا۔ اور جس نے اپنا مال فی سبیل اللہ خرچ کیا تو ان درہموں کا خرچ کرنا اس کے لیے سات سو تک درہموں تک اور دینار کو سات سو دیناروں تک بڑھا دیا جائے گا۔ اور روزے کا ثواب صرف اللہ تعالیٰ ہی جانتا ہے۔“ یہ حدیث عبداللہ بن دینار سے صرف عمر بن محمد ہی روایت کرتے ہیں، اسے روایت کرنے میں ابو عقیل اکیلے ہیں۔","",{"k":"المعجم الكبير للطبرانی (١١١٧٠)، ضعيف الترغيب والترهيب (١/١٤٤، ٥٧٢)، مجمع الزوائد (٣/١٨٢)۔"}],[866,"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”ہر امت کا ایک امین ہے اور اس امت کا امین ابو عبیدہ بن الجراح ہے۔“ یہ حدیث از حضرت عبداللہ از حضرت عمر سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں محمد بن اسحاق اکیلے ہیں۔","",{"k":"صحیح بخاری (٤٣٨٩)، صحیح مسلم (٢٤١٩)۔","f":"معلوم ہوا کہ سیدنا ابو عبیدہ بنی اللہ اس امت کے امین ہیں۔ ان کا نام، ابو عبیدہ عامر بن عبد اللہ بن جراح رضی اللہ عنہ ہری قریشی ہے۔ عشرہ مبشرہ میں سے ہیں۔ سیدنا عثمان بن مظعون رضی اللہ عنہ کے ساتھ اسلام لائے، یہ لمبے قد خوبصورت چہرے اور ہلکی داڑھی والے تھے۔ طاعون عمواس میں ١٨ ہجری کو مقام اردن انتقال ہوا اور بیسان میں دفن ہوئے۔ اٹھاون سال عمر پائی۔ سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سیدنا ابو بکر بہت اچھے آدمی ہیں۔ سیدنا عمر بہت اچھے آدمی ہیں۔ سیدنا ابو عبیدہ بہت اچھے آدمی ہیں (یعنی اللهم )۔:٨٦٧ سنن ترمذی، کتاب المناقب، رقم: ٣٧٩٥، قال الشيخ الالباني: صحيح"}],[867,"سیدنا عبادہ بن صامت رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: ”جو شخص اللہ تعالیٰ کے لیے سجدہ کرتا ہے تو اللہ تعالیٰ اس کی وجہ سے اس کا ایک درجہ بلند دیتا ہے اور اس سے اس کا ایک گناہ گرا دیتا ہے۔“ یہ حدیث عبادہ سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں خالد اکیلے ہیں۔ مذکورہ حدیث میں سجدے کرنے والوں کی فضیلت کا تذکرہ ہے کہ جو کثرت سے سجدے کرتے ہیں اللہ تعالیٰ کے نزدیک ان لوگوں کا بہت زیادہ مقام و مرتبہ ہے۔ معدان بن طلحہ یعمری کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثو بان نبی اللہ سے پوچھا مجھے کوئی ایسا عمل بتاؤ جس سے اللہ تعالیٰ مجھے نفع دے اور مجھے جنت میں داخل فرما دے ثوبان رضی اللہ عنہ دیر خاموش رہے اور پھر میری طرف دیکھ کر فرمایا: بکثرت سجدے کرو کیوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا: ”جو ایک سجدہ کرتا ہے اللہ تعالیٰ اس کا ایک درجہ بلند فرما دیتا ہے اور ایک گناہ مٹا دیتا ہے۔ (سنن ترمذی، رقم: ٣٨٨) ٦٨","",{"k":"سنن ترمذی (٣٨٨)، صحيح مسلم (٤٨٨)۔"}],[868,"سیدنا زید بن ارقم نی اللہ نے بیان کیا، رسول اللہ صل علی ایم نے مجھے بھیجا تو فرمایا: ”تم ابو بکر کے پاس پہنچ جاؤ۔ ان کو اپنے گھر پاؤ گے وہ کپڑا لپیٹ کر بیٹھے ہوں گے انہیں کہنا اللہ کے رسول صلی اللہ علیہ وسلم تم کو سلام کہتے ہیں اور فرماتے ہیں کہ جنت کی بشارت ہو پھر آگے جانا جب ثنیہ کے پاس جاؤ گے تو وہاں عمر کو پاؤ گے جو گدھے پر سوار ہوں گے ان کا سر چمک رہا ہوگا انہیں کہنا کہ نبی ملے عیدین تمہیں سلام کہتے ہیں، اور کہتے ہیں کہ تمہیں جنت کی بشارت دی جاتی ہے۔ پھر آگے چلنا ایک بازار میں جاؤ گے تو عثمان کو ملو گے وہ اس میں خرید و فروخت کر رہے ہوں گے۔ انہیں کہنا کہ رسول اللہ ملے لیکن تمہیں سلام کہتے ہیں۔ اور سخت آزمائش کے بعد جنت کی بشارت دیتے ہیں۔ جب میں گیا تو سیدنا ابو بکر بنی اہلیہ کو گھر میں بیٹھا ہوا پایا وہ کپڑا لپیٹے ہوئے بیٹھے تھے جس طرح کی آپ نے فرمایا تھا میں نے انہیں کہا: رسول اللہ صلی اللہ علیہ وسلم آپ کو سلام کہتے ہیں، اور فرماتے ہیں کہ جنت حاصل کرنے پر خوش ہو جاؤ تو انہوں نے کہا: رسول اللہ صل علی کہاں ہیں؟ میں نے کہا: فلاں اور فلاں جگہ پر ہیں تو وہ اٹھ کر آپ کے پاس آئے۔ پھر میں ثنیہ پر گیا، وہاں سیدنا عمر بنی یعنی یہ گدھے پر سوار تھے، آپ کا سر چمک رہا تھا، جس طرح آپ علینا نے فرمایا تھا میں نے کہا: رسول اللہ اے علی تم آپ کو سلام کہتے ہیں، اور کہتے ہیں کہ جنت لینے پر خوش ہو جاؤ۔ انہوں نے کہا: آپ صلی اللہ علیہ وسلم کہاں ہیں؟ میں نے کہا: فلاں اور فلاں مقام پر ہیں تو وہ آپ کی طرف چلے گئے۔ پھر میں آگے چلا تو بازار پہنچ گیا میں وہاں سیدنا عثمان رضی اللہ عنہ سے جاملا تو وہ خرید وفروخت کر رہے تھے جیسا کہ آپ نے مجھے بتایا تھا۔ میں نے انہیں بھی کہا کہ رسول اللہ نے ہم آپ کو سلام کہتے ہیں، اور فرماتے ہیں کہ تم جنت پر خوش ہو جاؤ مگر سخت آزمائش کے بعد۔ انہوں نے بھی یہی پوچھا کہ آپ کہاں ہیں؟ میں نے بتایا کہ فلاں اور فلاں جگہ ہیں تو انہوں نے میرا ہاتھ پکڑا اور ہم دونوں اکٹھے آپ صلی اللہ علیہ وسلم کے پاس آگئے تو سیدنا عثمان رضی اللہ عنہ کہنے لگے، یا رسول اللہ نے تم! زید میرے پاس گئے، اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم تجھے سلام کہتے ہیں اور فرماتے ہیں کہ ایک سخت آزمائش کے بعد جنت کی بشارت حاصل کرو تو وہ کون سی آزمائش مجھ پر آئے گی؟ اللہ کے رسول ملنے کی؟ اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث فرمایا! میں نے کبھی برداشت کرنے میں تکلیف سمجھی نہ کبھی کوئی آرزو کی، اور نہ ہی کبھی دائیں ہاتھ سے شرم گاہ کو چھوا ہے جب سے آپ سے بیعت کی ہے۔ آپ نے فرمایا: ”یہی بات ہے۔“ یہ حدیث حضرت زید بن ارقم سے اسی سند سے مروی ہے، اسے روایت کرنے میں عبد الاعلیٰ بن ابی مساورا کیلے ہیں۔ ٨٦٩","",{"k":"کر مجمع الزوائد (٥٦/٩)، اسناده ضعيف۔"}],[869,"عبد الرحمن بن اخنس سے روایت ہے کہ انہوں نے سعید بن زید رضی اللہ عنہ سے سنا اور وہ نبی نے تم پر گواہی دے رہے تھے کہ وہ دس میں سے دسویں آپ کے ساتھ تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ابو بکر جنت میں ہوں گے، عمر جنت میں ہوں گے اور عثمان بھی جنت میں ہیں، علی بھی جنت میں ہوں گے طلحہ بھی جنتی ہیں زبیر بھی جنتی ہیں۔ عبد الرحمن بن عوف بھی جنت میں ہوں گے، سعد بن ابی وقاص بھی جنت میں ہوں گے۔ (ٹی ایم ) اگر میں چاہوں تو نویں کے متعلق بتا سکتا ہوں لوگوں نے کہا ضرور بتائیں تو وہ کہنے لگے وہ میں ہی ہوں پھر ( یہ بات کہہ کر ) وہ رو پڑے۔“ یہ حدیث ولید بن قیس السکونی، ان کا نام ابوشجاع بن ولید ہے، سے صرف محمد بن طلحہ ہی روایت کرتے ہیں۔ شعبہ اور حسن بن عبید اللہ انخعی محمد بن جمادہ اور عمرو بن قیس ملائی سے حربن صباح سے روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد، رقم : ٩ (٤٦٤٩)، قال الشيخ الالباني، صحیح۔"}],[870,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بیٹھ کر نماز پڑھنے والے کو کھڑے ہو کر نماز پڑھنے والے سے نصف ثواب ہوگا۔“","",{"k":"صحيح بخارى، وہ۔"}],[871,"سیدنا عبد اللہ بن السائب رضی اللہ عنہ نے بیان کیا، میں جاہلیت میں نبی صلی اللہ علیہ وسلم کا شریک تھا، پھر جب میں مدینے آیا تو آپ نے مجھے فرمایا: ” کیا تو مجھے پہچانتا ہے؟“ میں نے کہا: جی ہاں آپ جاہلیت میں میرے شریک تھے، آپ جھگڑا کرتے تھے نہ دھو کہ کرتے تھے۔“ یہ حدیث منصور بن ابی اسود سے صرف سعید ہی روایت کرتے ہیں۔ مذکورہ حدیث میں نبی مکرم مٹے نیم کی نبوت سے پہلے کی زندگی کا نمونہ پیش کیا گیا ہے۔ اس طرح ارشادی باری تعالیٰ بھی ہے: فَقَدْ لَبِثْتُ فِيْكُمْ عُمُرًا مِنْ قَبْلِهِ أَفَلَا تَعْقِلُونَ) (يونس: ١٦) بلاشبہ میں اس سے قبل تو ایک بڑے حصہ تک تم میں رہ چکا ہوں پھر کیا تم عقل نہیں رکھتے۔“ یعنی چالیس (٤٠) سال میں نے تمہارے ہاں گزارے ہیں اور تم میری امانت وصداقت کے بھی قائل رہے ہو۔ مذکورہ حدیث سے معلوم ہوا کہ شراکت دار یا دیگر سے جھگڑا فساد نہیں کرنا چاہیے۔","",{"k":"مجمع الزوائد (٤٠٩/٩)۔"}],[872,"سیدنا عبد اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم سجدے میں سو جاتے تھے آپ صلی اللہ علیہ وسلم کے سونے کا پتہ آپ صلی اللہ علیہ وسلم کے اونچی آواز سانس لینے سے چلتا تھا پھر آپ ملٹے علیم نماز میں ہی کھڑے ہو جاتے۔“ یہ حدیث اعمش سے صرف منصور ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا سجدے کی حالت میں سو جانے سے وضو نہیں ٹوٹتا۔ سیدنا انس رضی اللہ عنہ سے روایت ہے کہ عہد رسالت میں صحا بہ کرام بی سیم نماز عشا کا انتظار کرتے حتی کہ (غلبہ نیند کے باعث ) ان کے سر جھکنے لگتے پھر وہ نماز پڑھتے اور (نیا) وضو نہیں کرتے تھے۔ (صحیح مسلم، رقم: ٣٧٦، سنن ابو داؤد، رقم: ٢٠٠، سنن ترمذی، رقم: (٧٨) معلوم ہوا جو نیند گہری ہو شعور کو زائل کر دے اس سے وضو ٹوٹتا ہے محض اونگھنے یا سر جھک جانے سے وضو نہیں ٹو تھا۔ نیند کے ناقض وضو ہونے کے متعلق اہل علم کے مختلف اقوال ہیں۔ جن میں ہمارے علم کے مطابق راجح قول یہی ہے کہ مطلقاً نیند ناقض وضو ہے خواہ نیند بیٹھ کر آئے یا لیٹ کر یا کھڑے ہو کر بشرطیکہ وہ گہری ہو اس سے شعور زائل ہو جائے۔ (امام ابن حزم، المحلی بالاثار: ٢١٢/١) (شیخ البانی تمام المنة: ص ١٠١) ( شیخ عبد العزیز بن باز رحمہم اللہ، فتاوی ابن باز مترجم:٤٩/١) نے اسی کے مطابق فتوی دیا ہے جن روایات سے معلوم ہوتا ہے کہ صرف لیٹ کر سونے والے کی نیند ہی ناقض ہے وہ ضعیف ہیں۔ ( تمام المنۃ ص ١٠١) ٨٧٣","",{"k":"سنن ابو داؤد (٢٠٢)، سنن ترمذی (٧٧)، قال الالبانی، السلسلة الصحيحة (٦/٤٢٤، ٢٩٢٥)۔"}],[873,"سیدنا عبد اللہ ابن عباس رضی جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو عورت ولی کے بغیر نکاح کرے تو اس کا نکاح باطل ہے۔ اور اس کا نکاح باطل ہے اگر اس نے اس عورت سے جماع کیا تو اس عورت کو مہر ملے گا اس عوض میں کہ جو اس مرد نے اس عورت کی شرم گاہ کو حلال کیا اور جس کا کوئی ولی نہ ہو تو حکمران اس کا ولی ہے۔“ یہ حدیث حضرت ابن عباس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں سعید کیلے ہیں۔ معلوم ہواولی کی اجازت کے بغیر نکاح باطل ہے تفصیل پیچھے گزرچکی ہے۔ ٨٧٤","",{"k":"سنن ترمذی (١١٠٢)، قال الشيخ الالبانی، صحیح صحیح الجامع الصغير (٢٧٠٩)۔"}],[874,"سیدنا عبد الرحمن بن عوف رضی اللہ عنہ نے بیان کیا، جب نبی صلی اللہ علیہ وسلم کی وفات کا وقت آیا تو صحابہ بی ایم نے عرض کیا، اللہ کے رسول صلی اللہ علیہ وسلم! ہمیں وصیت فرمائیں۔ آپ ملنے کی ایم نے فرمایا: میں تمہیں پہلے پہلے ہجرت کرنے والوں اور ان کے بعد ان کے بیٹوں کے متعلق وصیت کرتا ہوں اگر تم نے اس طرح نہ کیا تو تمہاری نفلی عبادت قبول ہو گی نہ فرض عبادت۔“ یہ حدیث عبدالرحمن سے صرف اسی سند سے منقول ہے۔ مذکورہ روایت میں مہاجرین اور ان کی اولاد کی فضلیت کا تذکرہ ہے۔ مہاجر وہ مسلمان","",{"k":"مجمع الزوائد (١٠/١٧)، صحیح۔","f":"جو کفار مکہ کے ستانے پر اپنا وطن چھوڑ کر مدینہ جا بسے یہی مسلمان مہاجرین کہلائے۔ لفظ ہجرت اسلام کے لیے ترک وطن کرنے پر بولا جاتا ہے۔ اللہ ذوالجلال نے مہاجرین کا تذکرہ ان کی فضیلت قرآن پاک کے متعدد مقامات پر فرمائی ہے۔ جیسا کہ فرمایا: لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِنَ اللَّهِ وَرِضْوَانًا وَيَنْصُرُونَ اللهَ وَرَسُولَهُ أَوْلَئِكَ هُمُ الصَّادِقُوْنَ﴾ (الحشر: ٨) معلوم ہوا کہ جو مہاجرین کا احترام نہیں کرتا، ابو بکر، عمر، عثمان، علی دیگر صحابہ مین بنیان مین سے بغض رکھے اللہ ذوالجلال اس کی نماز بھی قبول نہیں کرتے۔"}],[875,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ فرماتا ہے جب میرا بندہ بیمار ہو جائے پس اگر وہ تین دن سے پہلے اپنے مرض کو ظاہر کر دے تو گویا اس نے میرا:٨٧٦ شکوہ کیا۔ یہ حدیث مقبری سے صرف عبدالرحمن ہی روایت کرتے ہیں، اسے روایت کرنے میں عقیق اکیلے ہیں۔","",{"k":"مجمع الزوائد (٢/٢٩٥)، اسناده ضعيف فيه عبدالرحمن بن عبدالله بن العمري وهو متروك۔"}],[876,"سیدنا ابن عمر نبی اللہ سے روایت ہے کہ رسول اللہ علی ایم نے فرمایا: \"جو شخص مدینہ سے تین دن غائب رہا، تو جب وہ وہاں آئے گا تو اس کا دل سختی والا ہو گیا ہو گا","",{"k":"مجمع الزوائد (٢/٣١٠)، اسناده ضعيفٌ فيه علقمة و عبدالله بن عمر بن حفص وهما ضعيفان۔"}],[877,"اس سند سے سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب سرمہ لگاتے تو تین سلائیاں دائیں آنکھ میں ڈال دیتے اور دوسری میں دو ڈالتے اس کو طاق کرتے تھے","",{"k":"السلسلة الصحيحة (٢/١٣٢، ٦٣٣)، مجمع الزوائد (٥/٩٦)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ آنکھوں کی حفاظت کرنا چاہیے۔ اس سلسلہ میں یہ امر مسنون ہے کہ ان میں سرمہ ڈالا جائے جیسا کہ نبی معظم نے تم خود بھی سرمہ ڈالتے اور پھر احمد سرمہ کی نبی مکرم نے دین نے تعریف بھی فرمائی کہ بہترین سرمہ احمد ہے جو بینائی کو تیز کرتا اور پلکوں کے بال اگا تا ہے۔ (سنن ابی داؤد، کتاب الطهارة، رقم: ٢٨٧٨) حافظ ابن قیم اللہ نے لکھا ہے کہ الحمد وہ سیاہ پتھر ہے جو اصفہان سے آتا ہے اور مغرب سے بھی یہ درآمد کیا جاتا ہے۔ اس کا مزاج سرد خشک ہے بینائی کو طاقت دیتا ہے بالخصوص جبکہ اس کے ساتھ کچھ کستوری بھی ملا لی جائے۔ (زاد المعاد) ٢٧٨"}],[878,"اسی سند سے سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص حق پر ہونے کے باوجود جھگڑا کرنا ترک کر دے تو میں اس کے لیے جنت کے ایک کونے میں ایک گھر کا ذمہ دار ہوں ہوں۔ اسی طرح جو شخص مزاح کے دوران بھی جھوٹ بولنا ترک کر دے تو میں اس کے لیے جنت کے درمیان ایک گھر کا ذمہ دار ہوں۔ اسی طرح جو شخص اپنے اخلاق سنوار لے تو میں اس کے لیے جنت کی اعلیٰ منازل میں ایک گھر کا ذمہ دار ہوں۔ یہ حدیث حضرت عبداللہ بن عمر سے صرف عقبہ ہی روایت کرتے ہیں، اُن سے روایت کرنے میں عتیق اکیلے ہیں۔ ماندن (١) مذکورہ حدیث سے معلوم ہوا کہ حق پر ہوتے ہوئے جھگڑا چھوڑ دینا انتہائی عزیمت کا عمل ہے اور اس کا اجر جنت میں شاندارمحل کی صورت میں حاصل ہوگا۔ (٢) مومن کے لیے جھوٹ بولنا کسی طرح روا نہیں سوائے اس کے کہ زوجین میں یا دو مسلمان بھائیوں میں صلح صفائی کی غرض سے کوئی مناسب بات بنا لی جائے۔ (٣) اسی طرح ظاہر اور باطن کو اچھا کر لینا بھی انتہائی مستحسن عمل ہے۔","",{"k":"الكبرى للبيهقي: ١٠/ ٢٤٩ . سنن ابو داؤد (٤٨٠٠)، السنن۔"}],[879,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے تنگ دست کو مہلت دی یا (قرض) معاف کر دیا تو اللہ تعالیٰ قیامت کے دن اپنے عرش کے ساتھ تلے اسے سایہ عطا فرمائے گا۔“ یہ حدیث داؤد ہی روایت کرتے ہیں، اسے روایت کرنے میں اسحاق بن سلیمان اکیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ تنگدست کو آسانی تک مہلت دینے والا یا قرض معاف کر دینے والا خوش نصیب عرش الہی کے سایہ کے نیچے ہو گا، بلکہ سب سے پہلے عرش کے نیچے جائے گا۔ جیسا کہ نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((ان اول الناس يستظل في ظل الله يوم القيامة الخ )) \"سب سے پہلے جو شخص روز قیامت عرش الہی تلے سایہ حاصل کرے ہوگا وہ آدمی ہے جو ننگ دست کو کوئی چیز ہاتھ لگنے تک مہلت دے دے یا وہ اتنا قرض اس پر صدقہ کر دے جتنے کا وہ آرزومند ہے۔ اور کہہ دے جو مال میں نے تجھ سے لینا ہے وہ اللہ کی رضا کی خاطر تجھ پر صدقہ کرتا ہوں۔ اور یہ کہہ کر قرض نامہ پھاڑ دے۔“ (معجم الطبراني الكبير: ١٦٧/١٩، مجمع الزوائد: ١٣٤/٤، قال الهيثمي: اسناده حسن.) اسی طرح ارشاد باری تعالیٰ ہے: (البقرة: ٢٨٠) اور اگر کوئی تنگی والا ہو تو اسے آسانی تک مہلت دینی چاہیے اور صدقہ کرو تو تمہارے لیے بہت ہی بہتر ہے اگر تم جانتے ہو۔“ ٨٠","",{"k":"صحيح مسلم (٣٠٠٦)، سنن ترمذی (١٣٠٦)، سنن ابن ماجه (٢٤١٩)۔"}],[880,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ نے بیان کیا، میں اس وقت نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا جب آپ نے مٹکے کا نبیذ حرام فرمایا تھا۔ اور میں اس وقت بھی آپ کے پاس موجود تھا جس وقت آپ نے اس کے پینے کا حکم دیا اور فرمایا: ”ہر نشہ آور چیز سے اجتناب کرو۔“ یہ حدیث حضرت عبداللہ بن مغفل سے اسی سند سے مروی ہے، اسے روایت کرنے میں ابوجعفرا کیلے ہیں۔","",{"k":"السلسلة الصحيحة (٦/٢٩٧، ٢٧٩٧)، صحيح الجامع الصغير (١٥٨٨)، المعجم الكبير للطبرانی (١٠/٢٠٩)۔","f":"مذکورہ روایت سے معلوم ہوا کہ مٹکے کا نبیذ ابتدائے اسلام میں منع تھا بعد میں اس کی اجازت مل گئی تھی۔ تا ہم نشہ آور مشروب خواہ سفید مٹکے میں ہو یا سبز میں اس کا پینا حرام ہے اور اگر نبیذ نشہ آور نہ ہو تو خواہ وہ کسی بھی برتن میں ہو، اس کا پینا جائز ہے۔ (تنقیح الرواۃ: ٢٢٢/٣)"}],[881,"سيدنا جبیر بنی امیہ سے روایت ہے کہ انہوں نے دس ہزار درہم کا فدیہ دیا۔ پھر فرمایا: اس مسجد کے رب کی قسم! اگر میں قسم کھاتا ہوں تو سچی قسم کھاتا ہوں یہ ایک بات تھی جس کو میں نے اپنی قسم کا کفارہ بنایا۔“ مذکورہ روایت کمزور ہے۔","",{"k":"مجمع الزوائد (٤/١٨١)، ضعيف الترغيب والترهيب (١١٥٦)۔"}],[882,"سیدنا زید بن ثابت کی اہلیہ نیا اینجا نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جب آپ پچھنے لگواتے تو اس سے نکلے ہوئے خون کو دفن کرنے کا حکم فرماتے۔“ یہ حدیث حضرت اُم سعد سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں عنبسہ اکیلے ہیں۔","",{"k":"مجمع الزوائد (٥/٩٤)، اسناده ضعيف فيه هياح بن بسطام وهو ضعيف۔"}],[883,"سیدنا عبداللہ ابن عباس ریلی اینجا نے بیان کیا، جب یہ آیت نازل ہوئی: ﴿إِذَا جَاءَ نَصْرُ اللهِ وَالْفَتْحُ ”جب آ پہنچی اللہ کی مدد اور فتح “ تو آپ نے فاطمہ بنی ہوا کو بلایا اور فرمایا: ” مجھے موت کی اطلاع دی گئی ہے تو وہ رونے لگیں۔ آپ نے فرمایا: ” رو نہیں تو میرے گھر والوں میں سے سب سے پہلے مجھے آ کر ملو گی تو وہ ہنس پڑیں اس کو آپ کی کسی زوجہ محترمہ نے دیکھ لیا تو انہوں نے انہیں کہا: ہم نے آپ روتے دیکھا پھر ہنسنے لگیں تو انہوں نے فرمایا: آپ نے مجھے فرمایا: ” مجھے موت کی اطلاع دی گئی تو میں رو پڑی پھر مجھے فرمایا: ” ”رونہیں میرے اہل میں سے سب سے پہلے تو آ کر مجھے ملے گی تو میں ہنس پڑی۔“ یہ حدیث عکرمہ صرف ہلال سے ہی روایت کرتے ہیں۔","",{"k":"سنن دارمی، المقدمة (٧٩)، المعجم الكبير للطبراني (١٠/٢٤، ١١٧٣٩)، قال حسین سلیم اسد اسناده صحيح۔","f":"ماندن مذکورہ روایت سے معلوم ہوا کہ سورہ نصر میں نبی مکرم ملنے نیم کوموت کی اطلاع دی گئی تھی اور یہ سورت نزول کے اعتبار سے آخری سورت ہے۔ (دیکھئے:صحیح مسلم، کتاب التفسیر) جب یہ نازل ہوئی تو بعض صحابہ کرام بھی اسلیم سمجھ گئے تھے کہ اب نبی مکرم مے نام کا آخری وقت آ گیا ہے۔ (٢) مذکورہ روایت سے سیدہ فاطمہ بنی اٹھیا کی بھی فضیلت ثابت ہوتی ہے کہ نبی مکرم ملے تم نے انھیں راز کی بات بتلائی پھر ایسا ہی ہوا کہ نبی مکرم ملنے علم کی وفات کے چھ ماہ بعد سیدہ فاطمہ بنی النیہا کی وفات ہوئی۔:٨٤"}],[884,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” قاتل کے لیے وراثت سے کچھ بھی نہیں۔ یہ حدیث ابن جریج سے صرف اسماعیل ہی روایت کرتے ہیں۔ اندن مذکورہ حدیث سے معلوم ہوا کہ قاتل مقتول کی وراثت کا وارث نہیں بن سکتا۔ اور اس پر","",{"k":"الصغير، رقم : ٥٤٢٢ سنن ابو داؤد (٤٥٦٤)، مسند احمد (٤٩/١)، صحيح الجامع۔","f":"اہل علم کا اتفاق ہے۔ (الفقه الاسلامی: ٧٧١/١٠ - الفرائض، رقم: ٢٤) امام شافعی اور ابو حنیفہ رحمہما اللہ نے فرمایا کہ قتل عمد ہو یا قتل خطا، قاتل مقتول کا وارث نہیں ہوگا۔ امام مالک اللہ نے کہا ہے اگر قتل خطا ہو تو وہ مال کا وارث ہوگا۔ دیت کا نہیں۔ (کتاب الام: ٧٦/٤)"}],[885,"\"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزررے جو ایک بکری کا دودھ دھو رہا تھا تو آپ نے اس کو فرمایا: ”اے فلاں شخص! جب تو دودھ دھوئے تو اس کے بچے کے لیے کچھ چھوڑنا یہ جانوروں کے ساتھ اچھا سلوک کرنے کے ضمن سے ہے۔“ یہ حدیث حضرت عبد اللہ بن عمرو سے صرف اسی سند سے روایت ہے۔","",{"k":"مجمع الزوائد (٨/١٩٦)، اسناده صحیح۔","f":"مذکورہ حدیث سے معلوم ہوا کہ\n(١) جانور کے بچے کے لیے بھی دودھ چھوڑ نا چاہیے۔\n(٢) نبی مکرم سے علم کس قدر رحمت تھے کہ جانوروں کے ساتھ بھی اچھے سلوک کا حکم دیا کرتے تھے۔\n(٣) کیونکہ بچہ اگر دودھ پیسے گا تو جلد بڑا ہو گا اور صحت مند ہوگا۔ ٨٦"}],[886,"سیدنا عبد اللہ بن سلام رضی اللہ عنہ نے بیان کیا، جب رسول اللہ صلی اللہ علیہ وسلم کے گھر میں کوئی معاشی تنگی آتی تو آپ انہیں نماز کا حکم فرماتے پھر انہوں نے یہ آیت پڑھی: وَأمُرُ أَهْلَكَ بِالصَّلوةِ وَاصْطَبِرَ عَلَيْهَا \"اپنے گھر والوں کو نماز کا حکم فرماؤ اور اس پر صبر کرو۔“ یہ","",{"k":"تفرد ٢٨/٠/ مجمع الزوائد (٧/٦٧)، اسناده حسن۔","f":"حدیث حضرت عبداللہ بن سلام سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں معمرا کیلے ہیں۔ مذکورہ حدیث سے معلوم ہوا کہ نماز تنگی معیشت کا بہترین علاج ہے جس کی وجہ سے اللہ ذوالجلال پریشانیوں کو ختم کرتے ہیں اور رزق عطا کرتے ہیں۔ اور جو نماز ادا نہیں کرتے اللہ تعالیٰ ان لوگوں کے مال سے برکت اٹھا لیتے ہیں ان کی روزی کو تنگ کر دیتے ہیں جیسا کہ ارشاد باری تعالیٰ ہے: وَ مَنْ أَعْرَضَ عَنْ ذِكْرِى فَإِنَّ لَهُ مَعِيشَةً ضَنْكًا وَ نَحْشُرُهُ يَوْمَ الْقِيمَةِ أَعْمَى (طه: ١٢٤) جو میری یاد سے روگردانی کرے گا اس کی زندگی تنگی میں رہے گی اور ہم اسے بروز قیامت اندھا کر ٨/ کے اٹھائیں گے۔“"}],[887,"سیدنا عبد اللہ بن ام مکتوم رضی اللہ عنہ نے بیان کیا، نبی صلی اللہ علیہ وسلم ایک دن صبح کو نکلے تو فرمایا: ” آگ بھڑکائی گئی اور اندھیری رات کی طرح فتنے آ گئے اگر تم جانتے جو میں جانتا ہوں تو تم ہنستے تھوڑا اور روتے زیادہ۔ یہ حدیث حضرت ابن ام مکتوم سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں اسحاق بن سلیمان اکیلے ہیں۔ .. ایک حدیث میں ہے رسول اللہ علے سلیم نے فرمایا ” میں وہ چیزیں دیکھتا ہوں جو تم نہیں دیکھتے، اور وہ کچھ سنتا ہوں جو تم نہیں سنتے بے شک آسمان چر چرا رہا ہے اور اسے چر چرانا ہی چاہیے کیونکہ اس میں کہیں ایک بالشت برابر جگہ ایسی نہیں جہاں کسی فرشتے کا سرسجدہ میں نہ ہو۔ واللہ! اگر تم وہ باتیں جان لو جو میں جانتا ہوں تو تم کم ہنسو اور زیادہ روؤ۔ بستروں پر عورتوں سے لطف اندوز ہونا چھوڑ دو، اور اللہ کی پناہ طلب کرنے کے لیے جنگلوں اور صحراؤں کی طرف نکل جاؤ۔“ (سنن ابن ماجه، کتاب الزهد، باب الحزن والبكاء) مسند احمد میں ہے صحابہ کرام بینی اسلیم نے دریافت کیا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ صلی اللہ علیہ وسلم نے کیا دیکھا ہے؟ فرمایا: ”میں نے جنت اور جہنم دیکھی ہے۔“ معلوم ہوا کہ جہنم کی آگ کی شدت بہت زیادہ ہے اللہ ہم کو محفوظ فرمائے۔ (آمین","",{"k":"صحیح بخاری (٦٤٨٥)۔"}],[888,"سیدنا جبلہ بن حارثہ رضی اللہ عنہ نے بیان کیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو میں نے عرض کیا، مجھے کوئی ایسی چیز سکھائیں، جو مجھے","",{"k":"سنن ابو داؤد (٥٠٥٥)، صحيح الجامع الصغير (٢٩٢)، قال الشيخ الالباني: صحیح۔","f":"دے؟ تو آپ میم نے فرمایا: ” جب رات کو بستر کی طرف جاؤ تو قُلْ يَا أَيُّهَا الْكَافِرُونَ پڑھا کرو کیونکہ اس میں شرک سے بیزاری ہے۔“ یہ حدیث ابواسحاق سے فروه از جبلہ روایت کرتے ہیں اور ابو اسحاق سے صرف شریک ہی روایت کرتے ہیں۔ مذکورہ حدیث سے سورۃ الکافرون کی فضیلت ثابت ہوتی ہے۔ سورۃ الکافرون مومن کو شرک سے بری کرنے والی سورت ہے۔ حدیث میں ہے سورۃ الکافرون چوتھائی قرآن کے برابر ہے۔ (سنن ترمذی، کتاب فضائل القرآن۔ اسنادہ صحیح) ظاہر ہے جو شرک سے بری ہو گیا تو اس کے لیے جنت کا وعدہ ہے جیسا کہ نبی مکرم ملے تم نے فرمایا: مَن مَاتَ وَهُوَ يَعْلَمْ أَن لَّا إِلَهُ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ)) (صحیح مسلم، کتاب الايمان، رقم: (٢٦) جو شخص اس حال میں فوت ہوا کہ وہ جانتا ہو کہ اللہ کے سوا کوئی معبود نہیں تو وہ جنت میں داخل ہوگا۔"}],[889,"سیدنا ابو شریح کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے اپنے بھائی کی بین لغزش معاف کر دی اللہ تعالیٰ اس کی لغزش قیامت کے روز معاف کر دے گا۔“ یہ حدیث عبدالملک سے صرف شریک ہی روایت کرتے ہیں۔ مذکورہ حدیث سے سودا واپس کر لینے والوں کی فضیلت کا تذکرہ ہے۔ جب بیع شرعی اصولوں کے تحت ہوئی،سودا قطعیت سے طے ہو گیا اور ایک دھو کہ ختم ہو گیا تو اس کے بیچنے والا شرعاً واپسی کا پابند نہیں لیکن اخلاق اور خیر خواہی کا تقاضا ہے کہ دوسرا فریق راضی نہیں تو سودا واپس کر لیا جائے، کیونکہ تجارت کی بنیاد ہی باہمی رضا مندی پر ہے۔ علاوہ ازیں جس دکان دار کا سودا سچا اور کھرا ہو اور اس نے بیچا بھی مناسب نفع کے ساتھ ہوا سے سودا واپس کر لینے میں کوئی تامل نہیں ہوگا۔ صرف وہی دکاندار سودا واپس لینے سے انکار کرتا ہے جس کا سودا کھوٹا ہو یا اس نے بہت زیادہ منافع لے کر بیچا ہو اس طرح گویا سودا واپس کر لینے کی فضیلت کا بیان کرنے میں بالواسطہ اس امر کی ترغیب ہے کہ دکان دار سودا بھی صحیح رکھیں اور بیچیں بھی مناسب نفع کے ساتھ تاکہ کوئی واپس کرنا چاہے تو اسے واپس لینے میں تامل نہ ہو۔ ٨٩٠","",{"k":"سنن ابو داؤد، سنن ابن ماجة (٢١٩٩)، السلسلة الصحيحة (٦/١١٣، ٢٦١٤)۔"}],[890,"سیدنا سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ نے بیان کیا، لوگ مجھے اپنے دوستوں کو برا بھلا کہنے کا حکم دیتے ہیں: جبکہ اللہ تعالیٰ نے ان پر رحم فرمایا اور انہیں معاف کر دیا پھر انہوں نے ذکر کیا کہ میں حراء پہاڑ پر تھا وہ ملنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے حکم دیا حراء ٹھہر جاؤ تجھ پر نبی، صدیق اور شہید ہیں تو آپ میم نے ابو بکر، عمر، عثمان اور علی طلحہ، زبیر، عبد الرحمن، سعد بن ابی وقاص اور سعد بن زید نی نیم کو جنتیوں میں سے شمار کیا۔“ یہ حدیث طلحہ سے صرف اُن کے بیٹے محمد ہی روایت کرتے ہیں، طلحہ نے سند میں ھلال بن لیساف، سعید بن زید،عبداللہ بن ظالم کا ذکر نہیں کیا ہے۔","",{"k":"صحیح مسلم، سنن ترمذی (٣٦٩٦)۔","f":"ناد مذکورہ حدیث سے معلوم ہوا کہ صحابہ کرام مبنی ایسی نامعین کے ساتھ بغض رکھنے والے خیر القرون میں بھی موجود تھے۔ تاہم صحابہ کرام رضوان اللہ علیہم اجمعین آپس میں ایک دوسرے سے محبت پیار کرنے والے تھے اور ایک دوسرے کے لیے دعائیں فرمایا کرتے تھے۔"}],[891,"سیدہ عائشہ علی النیہا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کے سامنے سے کبھی دسترخوان نہیں اُٹھایا گیا کہ اس پر کچھ بچا ہوا کھانا موجود ہو۔“ یہ حدیث ابوحمزہ سے صرف محمد ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوا دستر خوان پر کھانا اتنا ہو جو کھایا جا سکے اگر زیادہ ہو تو پلیٹ میں اتنا ڈالنا چاہیے جو آدمی آسانی سے کھا سکے اور برتن کو صاف کرنا چاہیے۔ جیسا کہ نبی مکرم نے علیم نے فرمایا: ”جب تم میں سے کسی کا لقمہ گر جائے تو اسے اٹھالے، اور اس میں جو گندگی (مٹی) لگ گئی ہوا سے صاف کر لے اور کھا لے، اور اسے شیطان کے لیے نہ چھوڑے۔ اور اپنے ہاتھ کو تولیے سے نہ پونچھے یہاں تک کہ (پہلے) اپنی انگلیاں چاٹ لے۔ اس لیے کہ وہ نہیں جانتا کہ اس کے کون سے کھانے میں برکت ہے۔“:٨٩٢ (صحیح مسلم، کتاب الاشربة، رقم: ٢٠٣٣)","",{"k":"صحيح الترغيب والترهيب (٣/١٤٩)، مجمع الزوائد (١٠/٣١٣)۔"}],[892,"سیدنا جابر رضی اللہ عنہ نے بیان کیا ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کیا تو ہم بچوں کی طرف سے تلبیہ کہتے تھے اور ان کی طرف سے رمی بھی کرتے تھے۔“ یہ حدیث منصور سے صرف سعید ہی روایت کرتے ہیں۔ ٨٩٣","",{"k":"سنن ترمذی (٩٢٧)، سنن ابن ماجه (٣٠٣٨)، قال الشيخ الالبانى، ضعیف۔"}],[893,"سیدنا براء بن عازب رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا، آپ نے فرمایا: قرض دار آدمی اپنے قرض کے سبب قید ہوتا ہے وہ اکیلا ہونے کی اللہ کی طرف شکایت کرتا ہے۔“ یہ حدیث حضرت براء سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں مبارک اکیلے ہیں۔","",{"k":"السلسلة الضعيفة (٣/٣٧٥، ١٣٧٦)۔"}],[894,"سیدنا عبداللہ ابن عمر نبی الیہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے زمانے میں ایک لشکر نے غنیمت میں کھانا اور شہد حاصل کیا تو ان سے خمس نہیں لیا گیا۔ یہ حدیث حضرت عبید اللہ سے صرف حضرت انس ہی روایت کرتے ہیں۔ فائد (١) مذکورہ حدیث سے معلوم ہوا دشمن کے علاقے سے ملنے والی کھانے پینے کی اشیا استعمال کرنا جائز۔ (٢) مخصوص اشیا کے علاوہ مال غنیمت سے خمس نکالا جائے گا۔ جس طرح کہ دیگر کتاب وسنت کے دلائل سے ثابت ہے۔","",{"k":"سنن ابو داؤد (٢٧٠١)، قال الشيخ الالبانى، صحيح۔"}],[895,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”زمین کی پوشیدہ جگہوں میں رزق تلاش کرو۔ یہ حدیث ہشام بن عروہ سے صرف ہشام بن عبداللہ ہی روایت کرتے ہیں۔","",{"k":"مجمع الزوائد (٤/٦٣)، السلسلة الضعيفة ٥ / ٤٨٨، مسند ابی یعلی (٤٣٨٤)۔"}],[896,"و سیدہ عائشہ رضی اللہ عنہا نے بیان کیا، ”رسول اللہ صلی اللہ علیہ وسلم کے بعد انصار کے تین آدمی ہیں جن پر کوئی آدمی بھی زیادہ فضیلت والا نہیں سمجھا جاتا (١) سعد بن معاذ (٢) اسید بن حضیر اور ایک عباد بشر بی سیم ہیں۔ “ اس حدیث کو بیٹی سے صرف محمد ہی روایت کرتے ہیں۔ ٨٩٧","",{"k":"اسد، اسناده صحیح . مجمع الزوائد (٩/١٥٦)، مسند ابی یعلی (٤٣٨٩)، قال حسین سلیم۔"}],[897,"سیدہ عائشہ بین النہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ پسند فرماتا ہے کہ جب تم میں سے کوئی شخص کوئی بھی عمل کرے تو وہ اس کو مضبوط کرے۔“ یہ حدیث ہشام سے صرف مصعب ہی روایت کرتے ہیں،اسے روایت کرنے میں بشرا کیلے ہیں۔ اند. مذکورہ حدیث سے معلوم ہوا اعمال پر ہمیشگی ہونا چاہیے جیسا کہ نبی مکرم ملے تم نے فرمایا: اللہ تعالیٰ کو دین کا ) وہی عمل زیادہ پسند ہے جس کی ہمیشہ پابندی کی جائے۔“ (صحیح بخاری، کتاب الایمان: ٤٣ ) ساتھ ساتھ ثابت قدمی کی دعا بھی کرنا چاہیے۔","",{"k":"السلسلة الصحيحة (٣/١٨٧، ١١١٣)، مجمع الزوائد (٤/٩٨)، صحيح الجامع الصغير (١٨٨٠)۔"}],[898,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی کسی قوم کی امامت کرتا تھا اور وہ ہر رکعت میں قل هو الله احد اور ایک اور سورت پڑھا کرتا تھا تو اس کے ساتھیوں نے اس سے پوچھا کہ تم ہر رکعت میں ﴿قل ھو اللہ احد اور ایک اور سورت پڑھتے ہو کیونکہ تم سمجھتے ہو سورہ اخلاص کافی نہیں تب کوئی سورت ملاتے ہو یا تو اسی پر اقتصار کر لو اور دوسری سورت نہ پڑھو یا پھر اس کے علاوہ صرف دوسری سورت ہی پڑھ لیا کرو۔ اس نے کہا: میں اس طرح نہیں کروں گا اگر تم راضی ہو تو ٹھیک ورنہ اپنا کام سنبھال لو، اور وہ ان میں سے زیادہ افضل تھا اور وہ نہیں چاہتے تھے کہ اس کے علاوہ کوئی نماز پڑھائے۔ انہوں نے یہ بات رسول اللہ علیم سے کہی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ” کیا چیز مانع ہے کہ تم اس طرح کرو جس طرح تمہاری قوم کے لوگ تمہیں کہتے ہیں اور یہ سورۃ تم کیوں لازم کر رہے ہو؟ اس نے کہا: یا رسول اللہ لے میریم! میں اس سے محبت کرتا ہوں تو آپ النے کی ایم نے فرمایا: ”تیرا اس سے محبت کرنا تجھے جنت میں داخل کر دے گا۔“ یہ حدیث عبید اللہ سے صرف عبدالعزیز ہی روایت کرتے ہیں۔ (١) مذکورہ روایت سے معلوم ہوا کہ ایک رکعت میں سورۃ فاتحہ کے علاوہ دوسورتیں ایک ساتھ پڑھنا جائز یہ بھی معلوم ہوا کہ نماز میں سورتوں کو ترتیب سے تلاوت کرنا واجب نہیں۔ (٢) یہ بھی معلوم ہوا کہ سورہ اخلاص سے محبت اور اس کی کثرت تلاوت جنت میں جانے کا باعث ہے۔ سورۃ اخلاص میں توحید کا جامع اور مکمل بیان ہے۔ ٨٩٩","",{"k":"و، و، صحیح بخاری (٧٧٤)، مسند ابی یعلی (٧/٣٦٠، ٣٢٤٦)۔"}],[899,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن ایک آنت سے کھاتا ہے جبکہ کا فرسات آنتوں سے کھاتا ہے۔ یہ حدیث حفص سے صرف خلف ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (٥٣٩٧)۔"}],[900,"سیدنا یحیی بن یزید ھنائی نے بیان کیا، میں جیل میں فرزدق کے ساتھ تھا تو فرزدق نے کہا اللہ اس کو مالک بن منذر بن جارود کے ہاتھوں سے نہ بچائے۔ اگر میں یہاں سے چلا نہ گیا تو میں مکہ میں چل رہا ہوتا۔ پھر میں سیدنا ابو ہریرہ بنی الیہ اور سیدنا ابو سعید خدری ضیا المیہ سے ملا تو میں نے ان سے پوچھا: میں نے کہا: میں اہل مشرق سے ہوں ہم پر ایک قوم آتی ہے تو جو بھی لا الہ الا اللہ کہتا ہے اس کو وہ قتل کر دیتے ہیں اور ان کے علاوہ تمام لوگ محفوظ رہتے ہیں۔ تو انہوں نے مجھے کہا اگر ایسے نہ ہو تو اللہ تعالیٰ مجھے مالک بن منذر سے نہ بچائے۔ ہم نے اپنے دوست نبی ملے کی کمی سے سنا ہے وہ فرماتے تھے ”جس نے ان کو قتل کیا اس کو ایک شہید یا دو شہیدوں کا ثواب ہو گا اور جس کو وہ قتل کر دیں اس کو ایک شہید کا اجر ملے گا۔‘ یہ حدیث فرزوق شاعر سے صرف یحیی بن یزید ہی روایت کرتے ہیں، اسے روایت کرنے میں خلف بن خلیفہ اکیلے ہیں۔","",{"k":"مجمع الزوائد (٢٣٤/٦)، سنده ضعيف۔"}],[901,"سيدنا على رضی اللہ عنہ نے فرمایا: تمہارے رب کی مخلوقات میں سے مضبوط ترین دس چیزیں ہیں (١) پہاڑ اور لوہا جو پہاڑوں ں کو توڑ دیتا ہے (٣) آگ جو لوہے کو بھی کھا جاتی ہے (٤) پانی جو آگ کو بھی بجھا دیتا ہے (٥) بادل جو آسمان اور زمین کے درمیان مسخر ہیں وہ پانی کو اٹھائے ہوئے ہیں (٦) ہوانے بادلوں کو بھی اٹھایا ہوا ہے (٧) اور انسان جو ہوا سے اپنے ہاتھ کے ساتھ بچتا ہے اور اپنے کام کے لیے اس میں بھی چل کر چلا جاتا ہے۔ (٨) اور نشہ انسان پر بھی غالب آجاتا ہے (٩) اور نیند جو نشے پر بھی غالب آجاتی ہے (١٠) اور غم جو نیند کو بھی روک دیتا ہے۔ تو اللہ کی تمام مخلوقات سے سخت مخلوق غم ہے۔“","",{"k":"ضعيف . مجمع الزوائد (١٣٢٨)، سنده ضعيفٌ فيه حارث بن عبد الله الاعور وهو عبدالله۔"}],[902,"سیدنا عبداللہ ابن عباس زنی اینجا نے بیان کیا، ”نبی صلی اللہ علیہ وسلم جب سفر میں ہوتے اور سید اے علی جلدی جانا ہوتا تو آپ سایہ ڈھلنے سے پہلے سوار ہو جاتے اور ظہر کو مؤخر کر دیتے جب عصر کا اول وقت داخل ہو جاتا تو اتر کر دونوں کو اکٹھا پڑھ لیتے۔ پھر مغرب کو مؤخر کر دیتے جب شفق غائب ہونے کے قریب ہوتا تو اتر کر مغرب اور عشاء دونوں کو اکٹھا پڑھ لیتے۔ یہ حدیث محمد بن قیس سے صرف ابو معشر ہی روایت کرتے ہیں۔ ایک حدیث میں سیدنا معاذ رضی اللہ عنہ سے روایت ہے ہم نبی مکرم ملے علم کے ساتھ غزوہ","",{"k":"صحیح بخاری، صحيح مسلم (٧٠٤)۔","f":"تبوک کے لیے روانہ ہوئے تو آپ صلی اللہ علیہ وسلم ظہر وعصر اکٹھی پڑھتے اور اسی طرح مغرب وعشاء بھی اکٹھی پڑھتے تھے۔ (صحیح مسلم، کتاب صلاة المسافرين، رقم: ٧٠٦) معلوم ہوا جمع تقدیم و تاخیر جائز ہے امام احمد، مالک، شافعی رحمہم اللہ دوران سفر اس جمع کے جواز کے قائل ہیں جبکہ احناف صرف جمع صوری کے ہی قائل ہیں۔ جمع صوری یہ ہے کہ ایک نماز کو اس کے آخری وقت میں اور دوسری کو اس کے اول وقت میں پڑھنا۔ یوں دونوں نمازیں جمع ہو جائیں گی اور ادا بھی اپنے اپنے وقت میں ہی ہوں گی۔ (بداية المجتهد: ١٢٥/١) پہلا موقف راجح ہے۔ شیخ عبد العزیز بن باز اللہ نے بھی اسی کی تائید میں فتویٰ دیا ہے۔ (فتاوی اسلامیه: ٣٨٠/١) نیز نبی مکرم علیم سے بغیر کسی سفر بیماری، بارش اور خوف کے بھی نمازیں جمع کرنا ثابت ہے۔ (صحیح مسلم، رقم: ٧٠٥- سنن ابی داؤد، رقم: ١٢١٤)"}],[903,"سيدنا کعب بن مالک انصاری رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص کسی مریض کی بیمار پرسی کرتا ہے وہ (اللہ کی) رحمت میں داخل ہو جاتا ہے اور جب اس کے پاس بیٹھ جاتا ہے تو وہ اللہ کی رحمت میں ڈوب جاتا ہے۔ یہ حدیث حضرت کعب سے صرف اسی سند سے مروی ہے۔ قانون مذکورہ حدیث سے تیمار داری کی فضیلت ثابت ہوتی ہے جو تیمار داری کے لیے گھر سے نکلتا ہے اللہ کی رحمت اس پر برس رہی ہوتی ہے ایک حدیث میں ہے: ((من عاد مريضا لم يزل يخوض في الرحمة حتى يرجع فاذا جلس اغتمس فيها)) (مجمع الزوائد: ٢٩٧/٢ - اسناده صحیح) معلوم ہوا گھر واپس آنے تک مریض کی عیادت کرنے والا اللہ کی رحمت میں رہتا ہے۔ اغتمس کا مطلب ہے رحمت میں غوطہ زن ہوتا ہے","",{"k":"مجمع الزوائد (٢/٢٩٧)، صحيح الترغيب والترهيب (٣/١٩٨، ٣٤٧٩)، الادب المفرد (٥٢٢)۔"}],[904,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، ”رسول اللہ علیم کی خدمت میں تازہ کھجوروں کا ہدیہ پیش کیا گیا تو آپ ان کو دائیں ہاتھ سے کھانے لگے اور بائیں ہاتھ میں گٹھلی پکڑ کر پھینکنے لگے۔“ مذکورہ حدیث سے معلوم ہوا دائیں ہاتھ سے کھانا مسنون ہے جیسا کہ سیدنا عمرو بن ابی","",{"k":"لم اجده۔","f":"سلمہ لا الہ کو نبی مکرم طلم نے فرمایا: ((كل بيمينك)) دائیں ہاتھ سے کھاؤ۔“ یہ حدیث حفص بن عمر بن عبداللہ بن ابی طلحہ سے صرف ابو معشر ہی روایت کرتے ہیں۔ (صحیح بخاری، رقم: ٥٣٧٦، صحیح مسلم، رقم: ٢٠٢٢)"}],[905,"سیدنا ابو ہریرہ ضیا المیہ نے بیان کیا، رسول اللہ سلم نے فرمایا: ”عمرہ دوسرے عمرے کے درمیانی عرصے کے گناہوں کا کفارہ ہے اور حج مقبول کی جزا جنت ہی ہے۔“ یہ حدیث عبد العزیز سے صرف سعید ہی روایت کرتے ہیں۔","",{"k":"صحیح بخاری (١٧٧٣)۔"}],[906,"سیدہ عائشہ مولانا نے فرمایا: ”میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے ایک نماز جنازہ پڑھائی جبکہ ہم سورج کو صرف دیواروں پر دیکھ رہے تھے۔“ یہ حدیث قاسم سے صرف حکم ہی روایت کرتے ہیں۔ مذکورہ روایت ضعیف ہے۔","",{"k":"السنن الكبرى للبيهقي (٢/٤٦٠)، مجمع الزوائد (٣/٣٦)، فيه الحكم بن سعيد الاموى وهو ضعيف لسان الميزان (٣/٣٣٢)۔"}],[907,"سیدنا ابو رافع رضی اللہ عنہ نے بیان کیا، ”میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ ے علیم نے وضو کیا تو تین بار اپنا چہرہ دھویا، تین بار ہاتھ دھوئے، سر اور کانوں کا مسح کیا اور تین دفعہ اپنے پاؤں دھوئے۔ میں نے دوسری مرتبہ آپ کو دیکھا تو آپ نے ایک ایک دفعہ وضو کیا۔“ یہ حدیث ابو رافع سے اسی سند سے روایت ہے، اسے روایت کرنے میں الدراوردی اکیلے ہیں۔","",{"k":"m = مجمع الزوائد (١/٢٣١)۔","f":"ایک ایک مرتبہ اعضائے وضو کو دھونا فرض ہے جبکہ تین تین مرتبہ بالا جماع سنت ہے۔ (شرح مسلم للنووی: ١٠٨/٢٢ نیل الاوطار: ٢٦٧/١) کم از کم ایک مرتبہ زیادہ سے زیادہ تین مرتبہ اس سے تجاوز کرنا درست نہیں ہے جیسا کہ سیدنا عمرو بن شعیب بن ابیہ بن جدہ سے روایت ہے ایک دیہاتی رسول اللہ صلی اللہ علیہ وسلم کے پاس آکر سوال کرنے لگا تو آپ صلی اللہ علیہ وسلم نے اسے تین تین مرتبہ ( وضو کر کے دکھایا اور فرمایا: ((هذا الوضوء فمن زاد على هذا فقد اساء وتعدى وظلم)) یہ وضو ہے اور جس نے اس پر اضافہ کیا تو بے شک اس نے برا کیا، حد سے تجاوز کیا اور ظلم کیا۔“ (صحیح سنن ابی داؤد، رقم: ٢٣ - احمد: ١٨٠/٢)"}],[908,"سیدنا ابو ہریرہ ضیا ایم بی اے علی تم سے روایت کیا، آپ نے فرمایا: ”دونوں بیع کرنے والوں کو ایک دوسرے سے جدا ہونے سے پہلے پہلے بیچ قائم رکھنے یا فسخ کرنے کا اختیار حاصل ہے۔“ یہ حدیث ابی کثیر یزید بن عبدالرحمن سے صرف ایوب ہی روایت کرتے ہیں۔ مذکورہ حدیث سے معلوم ہوتا ہے جب تک بائع اور مشتری ایک ہی مجلس میں ہوں انہیں بیع فسخ کرنے کا اختیار ہے۔ اور جب وہ جدا ہو جائیں تو پھر یہ اختیار ختم ہو جاتا ہے اور بیع پختہ ہو جاتی ہے۔ اختلاف اس میں ہے کہ جدائی جسمانی ہونی چاہیے یا گفتگو کی تو امام شافعی، احمد، اسحاق، ابو ثور، ابن حزم، دبینم بالا بد ان کے قائل ہیں (یعنی بائع اور مشتری بیج کا معاملہ طے کرنے کے بعد جب تک ایک مجلس میں رہیں انہیں فتح کا اختیار ہے ) جبکہ احناف اور مالکیہ تفریق بالا قوال کے قائل ہیں۔ یعنی بائع اور مشتری کے درمیان بات مکمل ہوتے ہی اختیار ختم ہو جائے گا، اگر چہ وہ ابھی ایک ہی مجلس میں ہوں۔ (فتح الباری: ٥٧/٥، تحفة الاحوذى: ٥١٣/٤، بداية المجتهد: ١٤٠/٢) راجح موقف امام شافعی رحمہ اللہ وغیرہ کا ہے کیونکہ حدیث کے واضح الفاظ اسی کی تائید کرتے ہیں۔ (فتح البارى: ٥٧/٥، تحفة الاحوذى: ٥١٤/٤)","",{"k":"صحیح بخاری (٢٠٧٩)، صحيح مسلم (١٥٣١)۔"}],[909,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس میں تین چیزیں ہوں اس کا اللہ تعالیٰ آسان حساب لے گا اور جنت میں داخل کرے گا میں نے کہا: اللہ کے رسول! وہ کون سی چیزیں ہیں آپ مالٹے علیم نے فرمایا: ” تم ان کے ساتھ صلہ رحمی کرو جو قطع رحمی کرے اور جو تمہیں محروم رکھے تم اسے عطا کرو اور جو تم پر ظلم کرے تم اس کو معاف کر دو۔“ یہ حدیث بیٹی سے صرف سلیمان ہی روایت کرتے ہیں۔","",{"k":"السلسلة الضعيفة (٤/٣٤، ١٥٣٥)، مجمع الزوائد (٨/١٥٤)۔"}],[910,"سیدنا قیس بن سائب نبی اللہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز اس وقت پڑھتے جب روشنی آسمان پر پھیل جاتی اور ظہر جب سورج ڈھل جاتا اور عصر جب کہ سورج سفید صاف ہوتا اور مغرب کی جب روزہ دار روزہ کھولتے اور عشاء کو مؤخر کیا کرتے تھے۔ یہ حدیث قیس سے صرف اسی سند سے مروی ہے، اسے روایت کرنے میں ایوب اکیلے ہیں۔ (١) معلوم ہوا نبی نے یہ تمام نمازیں اول وقت ادا فرماتے تاہم عشا کو تاخیر سے پڑھنا بہتر سمجھتے تھے۔ (٢) شفق غائب ہونے سے، شفق اس سرخی کو کہتے ہیں جو غروب آفتاب کے بعد افق پر ظاہر ہوتی ہے۔ ٩١١","",{"k":"كر المعجم الكبير للطبراني (١٩/١٤٤)۔"}],[911,"سیدنا ابوحمید ساعدی رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جب تم میں سے کوئی کسی عورت کو پیغام نکاح بھیجے تو اس پر کوئی گناہ نہیں کہ وہ اسے دیکھ لے جب وہ صرف منگنی کے لیے دیکھنا چاہے جبکہ وہ اسے جانتا نہ ہو۔“ یہ حدیث عبداللہ بن عیسی سے صرف زبیر ہی روایت کرتے ہیں اور ابوحمید الساعدی سے صرف اسی سند سے مروی ہے۔","",{"k":"نصب الراية (١٢/١٤)، مسند احمد (٤٢٤/٥)۔","f":"مذکورہ حدیث سے معلوم ہوا کہ جس عورت سے نکاح کا ارادہ ہو تو اسے ایک دفعہ دیکھ لینا چاہیے۔"}],[912,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ تعالی کے اس فرمان: ترمی كالقصر وہ جہنم محل جیسی بڑی بڑی چنگاریاں پھینکتی ہے۔ فرماتے ہیں: خبر دار! وہ درخت اور پہاڑ کی طرح نہیں مگر شہروں اور قلعوں کی طرح ہیں۔","",{"k":"مجمع الزوائد (٧/١٣٣)۔","f":"ارشاد باری تعالی ہے: مذکورہ روایت کمزور ہے۔ تاہم اس میں کوئی شک نہیں جہنم چنگاریاں پھینکے گی۔ جیسا کہ إِنَّهَا تَرْمِي بِشَرَرِ كَالْقَصْرِ﴾ (المرسلات: ٣٢) یقیناً دوزخ چنگاریاں پھینکتی ہے جو مثل محل کے ہیں۔“ یعنی جہنم اتنی زیادہ بڑھک رہی ہوگی جس کی وجہ سے اس کی چنگاریاں باہر نکل رہی ہوں گے جن کا ایک بڑے قلعہ کے برابر شعلہ ہوگا۔ اللہ ذوالجلال ہم کو جہنم کے عذاب سے بچائے۔ (آمین)"}],[913,"سیدنا عبد اللہ بن الحنظلہ بن الغسیل رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم نے فرمایا: آدمی اپنی سواری اور اپنے بچھونے کے اگلے حصے اور اپنے گھر میں امامت کرانے کا زیادہ حق دار ہے۔“ یہ حدیث مسیب اور معبد سے صرف اسحاق ہی روایت کرتے ہیں اور عبداللہ بن حنظلہ سے صرف اسی سند سے مروی ہے۔ مذکورہ حدیث میں نبی مکرم ملے ہم نے لوگوں کو زندگی کے آداب سکھلائے ہیں۔ (١) سواری کا مالک زیادہ حق دار ہے کہ وہ آگے بیٹھے۔ لیکن اگر وہ اجازت دے تو دوسرا بیٹھ سکتا ہے۔ (٢) بستر کے درمیان میں بیٹھنے کا بھی زیادہ حق دار بستر والے کا ہے۔","",{"k":"السلسلة الصحيحة، رقم : (١٥٩٥)، سنن ابو داؤد (٢٥٧٢)، مجمع الزوائد (٨/١٠٨)۔","f":"(٣) یہ بھی معلوم ہوا کہ گھر کا مالک امامت کرانے کا زیادہ مستحق ہے۔ شیخ الاسلام ابن تیمیہ اللہ فرماتے ہیں: اکثر اہل علم کے نزدیک مالک مکان کی اجازت سے اگر مہمان امامت کراتا ہے تو اس میں کوئی حرج نہیں۔ (تحفة الاحوذی: ٣٥٣/٢، نیل الاوطار: ٤١٥/٢) ابن عربی واللہ کہتے ہیں: اگر مہمان اہل علم و فضل میں سے ہو تو مالک مکان کے لیے زیادہ بہتر ہے کہ وہ اسے آگے کرے، اور اگر دونوں علم وفضل میں برابر ہوں تو بھی حسن ادب کا یہی تقاضا ہے کہ اسے ہی امامت کی درخواست کرے۔ (عارضة الأحوذي: ١٥٧/٢) ٢١٤"}],[914,"سيده ام حبیبہ بنی اشیا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے ایک دن میں بارہ رکعت نفل نماز پڑھی تو اس کے لیے جنت میں ایک گھر بنا دیا جاتا ہے۔“ یہ حدیث معبد سے صرف اسحاق ہی نے روایت کی ہے۔","",{"k":"سنن ابو داؤد (١٢٥٠)، سنن نسائی (١٧٩٨)، قال الشيخ الالبانى، صحيح۔"}],[915,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ علیم نے فرمایا: قیامت کے دن پہلی جماعت جو جنت میں داخل ہوگی وہ ان لوگوں کی ہوگی جن کے چہرے چودھویں رات کے چاند کی طرح ہوں گے، اور جو لوگ ان کے بعد ہوں گے وہ آسمان میں بہترین روشن ستارے کی طرح ہوں گے اور ہر آدمی کی دو بیویاں ہوں گی ہر بیوی کے جسم پر ایک ایک جوڑا ہو گا، اس کی پنڈلی کا گودا گوشت کے اوپر سے دکھائی دے گا جس طرح سرخ شراب شیشے کی بوتل میں (باہر سے) دکھائی دیتی ہے۔“ یہ حدیث ابو اسحاق سے صرف فضیل ہی نے روایت کی ہے۔","",{"k":"كم صحیح بخاری (٢٥٤)۔"}],[916,"سیدنا علی بنی اہلیہ نے بیان کیا، رسول اللہ ملنے کی نیم عصر سے پہلے چار رکعت پڑھا کرتے تھے۔“ قائد ابو داؤد میں سیدنا عبد اللہ بن عمر ضیا اللہ سے روایت ہے نبی معظم صلی اللہ علیہ وسلم نے فرمایا: ((رحم الله امرء اصلی قبل العصر (اربعا)) اللہ تعالیٰ اس شخص پر رحم فرمائے جو عصر کی نماز سے پہلے چار رکعت ادا کرتا ہے۔“ (سنن ابو داؤد، رقم: - ابن خزیمه، رقم: اسناده حسن) یہ چار رکعتیں دو دو کر کے بھی پڑھی جاسکتی ہیں، سیدنا علی یا اللہ فرماتے ہیں نبی مکرم ملے ای این عصر سے قبل چار رکعتیں پڑھتے اور ہر دورکعتوں کے درمیان سلام پھیر کر فاصلہ کرتے تھے۔“ (صحیح ترمذی، رقم: ٤٨٩، سنن ابن ماجه رقم: ١١٦١) چاروں رکعات کو ایک سلام کے ساتھ پڑھنا بھی ثابت ہے۔ (دیکھئے صحیح سنن ابی داؤد، رقم: ١١٣١) عصر کی یہ چارسنتیں غیر موکدہ ہیں تاہم اس کے پڑھنے والے کے حق میں نبی معظم صلی اللہ علیہ وسلمن کی دعائے رحمت سے اس کی اہمیت واضح ہوتی ہے اسی طرح نبی مکرم کے نام سے عصر سے قبل دو رکعتیں پڑھنا بھی ثابت ہے۔ معلوم ہوا کہ کبھی چار اور کبھی دور کعتیں پڑھا کرتے تھے۔","",{"k":"سنن ترمذی (٤٢٩)، سنن ابو داؤد (١٢٧١)، قال الشيخ الالبانى، حسن۔"}],[917,"سیدنا عبداللہ ابن عباس ریلی اش جا نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تین چیزیں ہیں، جس میں ان میں سے کوئی بھی نہ ہو تو اللہ تعالیٰ اس کے باقی سارے گناہ معاف کر دیتا ہے(١) جس نے مرنے تک اللہ کے ساتھ کسی کو شریک نہ کیا (٢) جادو گر بنا نہ جادو گروں کی پیروی کی (٣) اپنے مسلمان بھائی کے متعلق کینہ نہ رکھا۔“ یہ حدیث ابی فزارہ سے صرف لیٹ ہی روایت کرتے ہیں اور حضرت ابن عباس سے یہ حدیث اسی سند سے مروی ہے۔","",{"k":"الادب المفرد للبخارى (٤١٣)، ضعيف الجامع الصغير (٢٥٥١)۔"}],[918,"سیدنا جابر رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کے نزدیک سب سے افضل شہید سیدنا حمزہ بن عبد المطلب نبی اللہ ہیں۔ یہ حدیث ابراہیم سے صرف حکیم ہی روایت کرتے ہیں، اسے روایت کرنے میں عمارا کیلے ہیں۔ اندن معلوم ہوا سیدنا حمزہ بھی اللہ تمام شہداء سے افضل واعلیٰ ہیں اور رسول اللہ علیم نے سید الشہداء کا لقب صرف حمزہ بن عبدالمطلب فی اللہ ہی کو دیا ہے۔ جیسا کہ رسول الله ملل علیم نے فرمایا: ”سید الشهداء حمزة بن عبدالمطلب ورجلٌ قام الى امام جائر فامره ونهاه فقتلة","",{"k":"مجمع الزوائد (٩/٢٦٨)، مستدرك حاكم (٤٨٣٦)۔","f":"(مستدرك على الصحيحين، رقم: ٤٨٣٦)"}],[919,"سیدنا جابر بن عبد اللہ علی الجھا نے بیان کیا، نبی اے علی تم سے پوچھا گیا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا جنتی سوئیں گے؟ آپ نے فرمایا: ” نیند موت کے مانند ہے اور جنتی نہیں سوئیں گے۔“ مذکورہ حدیث سے معلوم ہوا کہ جنت میں نیند نہیں ہوگی کیونکہ نیند موت کی طرح ہوتی ہے تو اللہ تعالیٰ جنتیوں اور جہنمیوں کے سامنے موت کو ذبح کر دے گا۔","",{"k":"♦، كر السلسلة الصحيحة (٣/١٦١، ١٠٨٧)، مجمع الزوائد: ١٠ / ٤١٥ . ٣/ (١٠٨٧)۔"}],[920,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک قبر کے پاس سے گزرے تو فرمایا: ”اس قبر والا کون ہے؟ صحابہ نے عرض کیا: فلاں شخص۔ تو آپ نے فرمایا: ”اس کے نزدیک صبح کی دو سنتیں تمہاری دنیا و مافیھا سے بہتر ہیں۔“ یہ حدیث ابو مالک سے صرف حفص بن غیاث ہی روایت کرتے ہیں، اسے روایت کرنے میں حفص بن عبد اللہ اکیلے ہیں۔ اہمیت تھی۔ مذکورہ روایت سے معلوم ہوا فجر کی دوسنتوں کی نبی مکرم ملنے نیم کے نزدیک بہت زیادہ ایک حدیث میں ہے ((ركعتا الفجر خير من الدنيا وما فيها)) ایک روایت میں ہے ((لهما احب الى من الدنيا جميعا)) یہ دور کعتیں مجھے تمام دنیا سے زیادہ محبوب ہیں۔“ (صحیح مسلم، کتاب صلاة المسافرين، رقم: ٧٢٥) سیدہ عائشہ بنی النہا سے روایت ہے نبی مکرم اسے علم فجر کی دورکعتوں (سنتوں) کا جتنا خیال رکھتے تھے اتنا کسی اور نفلی نماز کا خیال نہیں رکھتے تھے۔ (صحیح بخاری، رقم: ١١٦٩، صحیح مسلم، رقم: ٧٢٤) ٩٢١","",{"k":"السلسلة الصحيحة (٣/٤٦٢)، رقم ١٣٨٨ : ٦ مجمع الزوائد (٢/٢٤٩)۔"}],[921,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب عرفات سے واپس آئے تو یوں کہہ رہے تھے: ”اے اللہ تیری طرف سواریاں دوڑ دوڑ کر بے قرار کمزور ہوگئی ہیں۔ نصاریٰ کے دین کے خلاف ان کا دین ہے۔ یہ حدیث عاصم سے صرف ابوالربیع ہی روایت کرتے ہیں۔","",{"k":"السنن الكبرى للبيهقي (٥/١٢٦)، مجمع الزوائد (٢٥٦/٣)، فيه ابو الربيع السمان متروك و عاصم بن عبيد الله العدوى وهو ضعيف۔"}],[922,"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا، رسول اللہ علیم ایک مد (پانی) سے وضو اور ایک صاع سے غسل کیا کرتے تھے۔ یہ حدیث از قتادہ از انس صرف ابو اسماعیل ہی روایت کرتے ہیں۔","",{"k":"صحيح مسلم (٣٢٥)۔","f":"مند ایک پیمانہ ہے جو کم و بیش دو رطل کے برابر ہے اور جدید وزن کے مطابق تقریباً چھ سو گرام بنتا ہے۔ صاع اور مد چیزوں کے بھرنے کے پیمانے ہیں ایک صاع میں چار مد ہوتے ہیں آپ صلی اللہ علیہ وسلم کو ٥/٥ - اتنے کم پانی سے وضو اور غسل کرنے کا مقصد امت کو پانی کے ضیاع سے اجتناب کی ترغیب دلانا تھا۔"}],[923,"سیدنا عمرو بن شعیب عن ابیہ عن جدہ کی سند سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کرام بی ایلیم سے فرمایا: میں تم سے بیعت لیتا ہوں کہ تم اللہ کے ساتھ کسی کو شریک نہیں کرو گے، اللہ کی حرام کی ہوئی جان کو ناحق قتل نہیں کرو گے، زنا کرو گے نہ چوری اور شراب نہیں پیو گے، جس نے ان کاموں سے کوئی کام کیا تو وہ اس پر اگر حد لگا دی گئی تو اس کے گناہوں کا کفارہ بن جائے گی اور جس پر اللہ تعالیٰ نے پردہ ڈال دیا تو اس کا حساب اللہ تعالیٰ کے پاس ہو گا اور جس نے ان میں سے کچھ بھی نہ کیا، تو میں اس کے لیے جنت کا ضامن ہوں۔“ یہ حدیث ایوب سے صرف طفاوی ہی روایت کرتے ہیں، اسے روایت کرنے میں عمر وا کیلے ہیں۔ جس طرح نبی مکرم نے عام لوگوں سے بیعت لیا کرتے تھے اسی طرح نبی مکرم طلئے علیم عورتوں سے بھی بیعت لیا کرتے تھے۔ جیسا کہ ارشاد باری تعالیٰ ہے: يَأَيُّهَا النَّبِيُّ إِذَا جَائَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكُنَ بِاللَّهِ شَيْئًا وَلَا يَسْرِقُنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَادَهُنَّ وَلَا يَأْتِينَ بِبُهْتَانٍ يَفْتَرِيْنَهُ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِيْنَكَ فِي مَعْرُوفٍ فَبَايِعُهُنَّ (الممتحنه: ١٢) اے پیغمبر ( ع )! جب مسلمان عورتیں آپ ( ملے عام ) سے ان باتوں پر بیعت کرنے آئیں کہ وہ اللہ کے ساتھ کسی کو شریک نہ کریں گی، چوری کریں گی نہ زنا کاری کریں گی، اپنی اولاد کو نہیں ماریں گی اور کوئی ایسا بہتان نہ باندھیں گی جو خود اپنے ہاتھوں پیروں کے سامنے گھڑ لیں اور کسی نیک کام میں تیری نافرمانی نہیں کریں گی تو آپ ملنے ) ان سے بیعت کر لیا کریں۔“ مذکورہ آیت اور حدیث میں بیعت کے سلسلہ میں نماز روزہ حج زکاۃ وغیرہ کا ذکر نہیں اس لیے کہ یہ ارکان دین اور شعائر اسلام ہیں۔","",{"k":"صحیح بخاری (٦٨٠١)، مسلم (١٧٠٩)۔"}],[924,"ابو اسحق نے بیان کیا، میں نے سیدنا عبد اللہ بن عمر سے کہا مختار کہتا ہے کہ اس کی طرف وحی آتی ہے انہوں نے کہا: وہ سچ کہتا ہے: ﴿وَانَ الشَّيَاطِينَ لَيُوْحُونَ إِلَى أَولِياءِ هِمْ یعنی شیطان اپنے دوستوں کو طرف وحی کرتے ہیں۔ یہ حدیث ابو اسحاق سے صرف ابوبکر ہی روایت کرتے ہیں۔ مذکورہ آیت کا شان نزول تو ایک خاص واقعہ کی طرف ہے کہ بخاری شریف میں ہے کہ سیدنا عبداللہ ابن عباس ریلی اینجا نے کہا کہ اگر کوئی بسم اللہ پڑھنا بھول گیا تو کوئی حرج نہیں۔ اور اللہ تعالیٰ کا فرمان اور نہ کھاؤ اس جانور کو جس پر اللہ کا نام نہ لیا گیا ہو اور بلاشبہ یہ نافرمانی ہے اور (کوئی نیک کام) بھول جانے والے کو فاسق نہیں کہا جا سکتا، اور قرآن میں اللہ تعالیٰ کا فرمان ہے اور بے شک شیاطین اپنے دوستوں کو پٹی پڑھاتے ہیں کہ وہ تم سے کٹ حجتی کریں اور اگر تم ان کا کہا مانو گے تو تم بھی مشرک ہو جاؤ گے۔ (صحیح بخارى كتاب الذبائح باب التسمية على الذبيحة) تاہم یہ عام ہے جیسا کہ مذکورہ بالا روایت سے ثابت ہے کہ مختار کی طرف شیطان وحی کرتے تھے، جس کی وجہ سے شیطان کے چیلے کبھی مختلف قسم کے انکشاف کرتے ہیں تو ان میں کبھی کبھار ان کی بات درست بھی نکل آتی ہے، اور کبھی شیطان مختلف قسم کی باتیں ذہن میں ڈالتے ہیں جیسا کہ آج بھی شرک و بدعات میں مبتلا لوگ مختلف قسم کی دلیلیں دیتے ہیں شیطان ان کی مدد کرتا ہے تو اس کی وجہ سے یہ لوگ حیلے بہانے کرتے ہیں۔","",{"k":"سنن ابو داؤد (٢٨١٨)۔"}],[925,"سیدنا عمار رضی اللہ عنہ نے نبی نے کام سے روایت کیا کہ آپ اپنے دائیں اور بائیں سلام پھیرتے اور کہتے: ((السلام علیکم ورحمة الله ) یہ حدیث ابواسحاق سے صرف ابوبکر ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد (٩٩٦)، سنن ترمذی (٢٩٥)، قال الشيخ الالبانى، صحيح۔","f":"مذکورہ روایت سے معلوم ہوا کہ نبی مکرم نے علم دونوں طرف سلام پھیرتے تھے۔ ایک طرف سلام پھیرنا بھی نبی مکرم ملے تعلیم سے ثابت ہے۔ (صحیح مسلم، کتاب صلاة المسافرين، رقم: ٧٤٦، سنن ابی داؤد، رقم: ١٣٤٢) جمہور صحابہ کرام بی سیم و تابعین عظام، امام شافعی، احمد، میم ایک طرف سلام کو واجب جبکہ دوسری طرف سلام کو سنت کہتے ہیں۔ امام مالک اللہ نے ایک طرف سلام کو بھی سنت ہی کہا ہے۔ اور احناف کا کہنا ہے کہ نماز سے خارج ہونے کے لیے سلام واجب نہیں بلکہ اگر نماز کے منافی کسی فعل (مثلاً حدث وغیرہ) کے ساتھ بھی نماز ختم کر دی جائے تو یہ جائز ہے۔ (المجموع: ٤٦٢/٣ كتاب الام: ٢٣٤/١) احناف کا یہ موقف صحیح احادیث کے خلاف ہونے کی بنا پر مردود ہے۔ شیخ الاسلام ابن تیمیہ رحمہ اللہ۔ (مجموع الفتاوى: ٦١٣/٢٢) - امام نووی راللہ ( شرح صحیح مسلم، رقم: ٣/ ٩٠)۔ امام ابن حزم رحمہ الله (المحلى بالاثار: ٣٠٤/٢)، عبد الرحمن مبارکپوری رحمہ اللہ: ( تحفۃ الاحوذی: ٤٤/١) اور علامہ البانی اللہ (صفة صلاة النبي: ٨٨) نے سلام کو واجب قرار دیا ہے اور کہا ہے کہ اگر اس سے پہلے وضو ٹوٹ جائے تو نماز باطل ہو جاتی ہے خواہ فرض ہو یا نفل۔"}],[926,"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایک دوسرے سے بغض رکھو نہ باہم حسد کرو اور ایک دوسرے کی طرف پیٹھ مت کرو اور تم میں سے کوئی اپنے بھائی کے بھاؤ پر بھاؤ نہ کرے اور کوئی مہاجر کسی دیہاتی کے لیے بیع نہ کرے، لوگوں کو چھوڑ دو اللہ تعالیٰ بعض کو بعض سے رزق پہنچا دے اور کوئی عورت اپنی مسلمان بہن کی طلاق کی شرط مقرر نہ کرے۔“ یہ حدیث عاصم سے صرف ابوبکر ہی روایت کرتے ہیں۔","",{"k":"سنن ابو داؤد (٤٩١)، قال الشيخ الالباني، صحیح۔","f":"لا تباغضوا: یہ باب تفاعل ہے، جو مسلمان تم سے بغض رکھے تم مقابلے میں بھی اس سے بغض رکھو اور اگر کوئی تم سے بغض نہیں رکھتا تو اس سے بغض رکھنا اور زیادہ برا ہے۔ اس حکم کی رو سے وہ کام بھی ممنوع ٹھہرے جن سے آپس میں دلی عداوت پیدا ہوتی ہے۔ لا تحاسدوا بھی باب تفاعل ہے جو دو شخصوں کے درمیان ہوتا ہے ایک دوسرے پر حسد مت کرو۔ کوئی حسد کرے تو اس کے جواب میں بھی اس پر حسد نہ کرو۔ مگر مسلمان پر حسد کے جواب میں بھی حسد جائز نہیں تو جو تم پر حسد نہیں کرتا اس پر حسد تو بطریق اولی حرام ہے۔ ولا تدابروا: یعنی ایک دوسرے کی طرف پیٹھ مت کرو مراد یہ ہے کہ ایک دوسرے سے قطع تعلقی نہ کرو ایک دوسرے سے بول چال بند نہ کرو کیونکہ جب دو آدمی ایک دوسرے کو چھوڑ دیتے ہیں تو وہ ایک دوسرے سے منہ پھیر لیتے ہیں یہ حالت تین دن سے زیادہ رکھنا حرام ہے۔ مذکورہ حدیث سے معلوم ہوا کہ جب دو مسلمانوں کی آپس میں بیج ہو جائے تو کسی مسلمان کے لیے جائز نہیں کہ وہ بیچنے والے سے کہے کہ تم یہ چیز میرے ہاتھ میں فروخت کرو میں تمہیں زیادہ قیمت دیتا ہوں نہ خرید نے والے سے یہ کہنا جائز ہے کہ تم یہ چیز مجھ سے خریدو میں تمہیں سنتی دیتا ہوں پہلی بیع فسخ کر دو اس سے آپس میں شدید عداوت پیدا ہوتی ہے۔ یہ بھی معلوم ہوا کہ کوئی مہاجر کسی دیہاتی کا سامان نہ بیچے۔ امام نووی رحمہ اللہ فرماتے ہیں: ہمارے اصحاب کے نزدیک اس سے مراد یہ ہے کہ ایک اجنبی آدمی دیہاتی سے یا دوسرے شہر سے ایسا ساز و سامان جن کی سبھی کو ضرورت ہے اس روز کے نرخ کے مطابق فروخت کرنے کے لیے آتا ہے مگر اسے یہ کہہ کر واپس بھیج دیا جاتا ہے کہ اس سامان کو میرے پاس چھوڑ دو تا کہ میں اسے بتدریج اعلیٰ نرخ پر بیچ دوں۔ (شرح مسلم للنووی: ٤٢٥/٥) کوئی عورت کسی دوسری عورت کی طلاق کا مطالبہ نہ کرے ومفہوم ہو سکتے ہیں:\n(١) ایک یہ کہ عورت کسی مرد سے شادی کرنا چاہتی ہو تو اس سے اس کی پہلی بیوی کی طلاق کا مطالبہ کرے۔\n(٢) دوسرا، یہ کہ عورت اپنی سوکن کی طلاق کا مطالبہ کرے۔ اس کا مقصد یہ ہو کہ سوکن کو شوہر کی طرف سے جو سہولیات اور اخراجات وغیرہ میسر ہوں وہ بھی اسے ہی مل جائیں۔ ایسا کرنا جرم ہے۔ ضروری نوٹس ١"}]]);